import React, { Component } from "react";
import { connect } from "react-redux";
import { projectActions } from "_actions";
import LuxCreatePanelShell from "views/common/create/LuxCreatePanelShell";
import CreateProjectSidebarSection from "./CreateProjectSidebarSection";

class CreateProjectSidebar extends Component {
  render() {
    const { editMode, duplicateMode, show } = this.props;
    const ready =
      show &&
      ((editMode && this.props.selectedProjectInfo) ||
        (duplicateMode && this.props.selectedProjectInfo) ||
        (!editMode && !duplicateMode));

    const title = editMode
      ? "Update project"
      : duplicateMode
      ? "Duplicate project"
      : "Create project";

    return (
      <LuxCreatePanelShell
        show={show}
        onClose={this.props.closeActionHandler}
        panelId="createprojectsidebar"
        className="lux-create-panel--project lux-overlay-shell--create create_project_right_sidebar"
        kicker="Projects workspace"
        title={title}
        subtitle={
          editMode || duplicateMode
            ? "Guided steps or full form — fields are grouped by relevance."
            : "Five focused steps: identity, client, services, fieldwork, and team."
        }
      >
        {ready && (
          <CreateProjectSidebarSection
            handleSubmit={this.props.handleSubmit}
            editMode={editMode}
            duplicateMode={duplicateMode}
            selectedProjectInfo={this.props.selectedProjectInfo}
            permission={this.props.permission}
          />
        )}
      </LuxCreatePanelShell>
    );
  }
}

const mapStateToProps = (state) => ({
  currentUser: state.authentication.user,
  fieldConfig: state.projects.fieldConfig,
  createConfig: state.projects.createConfig,
  allProjectTeamAccounts: state.accounts.allProjectTeamAccounts,
  employeeAppConfig: state.employees.createConfig,
  allUserTeams: state.appconfig.allTeams,
  allEmployees: state.employees.allEmployees,
  allRoles: state.appconfig.allRoles,
  creating: state.projects.creating,
  updating: state.projects.updating,
  purchaseOrders: state.purchaseOrders.activeItems,
});

const mapDispatchToProps = (dispatch) => ({
  initializeCreateProject: projectActions.initializeCreateProject,
});

export default connect(mapStateToProps, mapDispatchToProps)(CreateProjectSidebar);
