import React, { Component } from "react";
import classNames from "classnames/bind";
import ItemCommentsSection from "./fragments/ItemCommentsSection";
import ProjectDetailsTabShell from "./ProjectDetailsTabShell";
import AuditTrailSection from "views/common/fragments/AuditTrailSection";
import LuxSegmentNav from "views/common/fragments/LuxSegmentNav";
import { AUDIT_SCOPES } from "_constants/audit.constants";

const PANEL_VIEWS = {
  COLLAB: "collab",
  AUDIT: "audit",
};

class ProjectDetailsActivity extends Component {
  constructor(props) {
    super(props);
    this.state = { activePanel: PANEL_VIEWS.COLLAB };
  }

  setPanel = (activePanel) => {
    this.setState({ activePanel });
  };

  renderPanelTabs = () => {
    const { activePanel } = this.state;
    return (
      <LuxSegmentNav
        items={[
          { id: PANEL_VIEWS.COLLAB, label: "Comments", icon: "fe fe-message-square" },
          { id: PANEL_VIEWS.AUDIT, label: "Audit trail", icon: "fe fe-shield" },
        ]}
        activeId={activePanel}
        onChange={this.setPanel}
        ariaLabel="Project activity views"
        tabList
        testId="project-activity-nav"
      />
    );
  };

  render() {
    const { projectInfo, readOnly, isLoading } = this.props;
    const { activePanel } = this.state;
    if (!projectInfo) return null;

    return (
      <ProjectDetailsTabShell
        icon="fe fe-activity"
        tone="activity"
        eyebrow="Collaboration"
        title="Activity & audit"
        subtitle="Team conversation, operational updates, and a compliance-grade audit trail for this project."
        stats={[
          {
            key: "record",
            label: "Record",
            value: projectInfo.itemIdUserTeamPrefix || "—",
            hint: "Project ref",
            tone: "violet",
          },
          {
            key: "status",
            label: "Status",
            value: projectInfo.status || "—",
            hint: "Current stage",
            tone: "sky",
          },
          {
            key: "view",
            label: "Viewing",
            value: activePanel === PANEL_VIEWS.AUDIT ? "Audit" : "Comments",
            hint: "Active panel",
            tone: "mint",
          },
        ]}
      >
        <div
          className={classNames("lux-pd-tab__panel", "lux-pd-activity", {
            "is-loading": isLoading,
          })}
        >
          <div className="lux-pd-activity__intro" aria-hidden="false">
            <article className="lux-pd-activity__intro-card is-comments">
              <span className="lux-pd-activity__intro-icon">
                <i className="fe fe-message-square" />
              </span>
              <div>
                <strong>Comments</strong>
                <span>Decisions, mentions, and day-to-day context stay with the project.</span>
              </div>
            </article>
            <article className="lux-pd-activity__intro-card is-audit">
              <span className="lux-pd-activity__intro-icon">
                <i className="fe fe-shield" />
              </span>
              <div>
                <strong>Audit trail</strong>
                <span>Status, assignment, and approval history for compliance reviews.</span>
              </div>
            </article>
          </div>

          {this.renderPanelTabs()}

          <div className="lux-pd-activity__surface">
            {activePanel === PANEL_VIEWS.COLLAB && (
              <ItemCommentsSection
                itemId={projectInfo.id}
                subType="PROJECT"
                isReadOnly={readOnly}
              />
            )}

            {activePanel === PANEL_VIEWS.AUDIT && (
              <AuditTrailSection
                scope={AUDIT_SCOPES.ENTITY}
                entityType="PROJECT"
                entityId={projectInfo.id}
                eyebrow="Compliance"
                title="Project audit trail"
                subtitle="Status changes, assignments, checklist updates, and approvals recorded for this project."
                showEntityFilters={false}
                emptyState={{
                  eyebrow: "Project audit",
                  title: "No audit events for this project",
                  description:
                    "Edits, status transitions, and team actions will be listed here once audit logging is active on the server.",
                  hints: [
                    "Events are grouped by day with actor and change details",
                    "Delegate approvals show acting-for metadata",
                    "Export will be available for compliance reviews",
                  ],
                }}
              />
            )}
          </div>
        </div>
      </ProjectDetailsTabShell>
    );
  }
}

export default ProjectDetailsActivity;
