import React, { Component } from "react";
import { NavLink } from "react-router-dom";
import dateUtils from "_helpers/date.utils";
import classNames from "classnames/bind";
import SelectInput from "views/common/fragments/formfields/SelectInput";
import LuxListRowMenuPortal from "views/common/fragments/LuxListRowMenuPortal";
import {
  PROJECT_STATUS_OPTIONS,
  formatProjectClientLine,
  getProjectStatusMeta,
  getProjectStatusSelectValue,
  getProjectTypeMeta,
  getProjectHoursPct,
  getProjectTaskPct,
} from "./projectList.utils";

class ProjectInfoLine extends Component {
  constructor(props) {
    super(props);
    this.state = { menuOpen: false, confirmRemove: false };
    this.rowRef = React.createRef();
    this.menuTriggerRef = React.createRef();
  }

  componentDidMount() {
    document.addEventListener("mousedown", this.handleOutsideClick);
  }

  componentWillUnmount() {
    document.removeEventListener("mousedown", this.handleOutsideClick);
  }

  handleOutsideClick = (event) => {
    if (!this.state.menuOpen) return;
    if (event.target.closest(".lux-list-row-menu-portal")) return;
    if (this.rowRef.current && !this.rowRef.current.contains(event.target)) {
      this.setState({ menuOpen: false, confirmRemove: false });
    }
  };

  toggleMenu = (event) => {
    event.preventDefault();
    event.stopPropagation();
    this.setState((prev) => ({ menuOpen: !prev.menuOpen, confirmRemove: false }));
  };

  closeMenu = () => this.setState({ menuOpen: false, confirmRemove: false });

  runMenuAction = (handler) => (event) => {
    event.preventDefault();
    event.stopPropagation();
    this.closeMenu();
    if (handler) handler();
  };

  stopRowClick = (event) => {
    event.preventDefault();
    event.stopPropagation();
  };

  handleRemove = () => {
    if (this.state.confirmRemove) {
      this.props.handleRemoveProject(this.props.item.id);
      this.setState({ confirmRemove: false, menuOpen: false });
      return;
    }
    this.setState({ confirmRemove: true });
  };

  renderMenuItem = (item) => (
    <button
      key={item.key}
      type="button"
      className={classNames("lux-emp-card__menu-item", item.tone && `is-${item.tone}`)}
      role="menuitem"
      onClick={this.runMenuAction(item.onClick)}
    >
      <span className={classNames("lux-emp-card__menu-icon", item.tone && `is-${item.tone}`)}>
        <i className={item.icon} aria-hidden="true" />
      </span>
      <span className="lux-emp-card__menu-copy"><strong>{item.label}</strong></span>
    </button>
  );

  getMenuSections = () => {
    const { item, permission } = this.props;
    const primary = [];
    if (permission.viewEnabled) {
      primary.push({ key: "view", icon: "fe fe-eye", label: "View project", onClick: () => this.props.onViewProject(item.id) });
    }
    if (!item.archived && permission.editEnabled && item.status !== "COMPLETED" && item.status !== "CLOSED") {
      primary.push({ key: "edit", icon: "fe fe-edit-2", label: "Edit project", onClick: () => this.props.handleEditProject(item.id, item.userTeamId) });
    }
    if (permission.duplicateEnabled) {
      primary.push({ key: "duplicate", icon: "fe fe-copy", label: "Duplicate", onClick: () => this.props.handleDuplicateProject(item.id, item.userTeamId) });
    }

    const secondary = [];
    secondary.push({
      key: "favorite",
      icon: item.favorite ? "fe fe-star" : "fe fe-star",
      label: item.favorite ? "Remove favorite" : "Add to favorites",
      onClick: () => this.props.handleFavoriteProject(item.id, !item.favorite),
    });
    if (permission.archiveEnabled) {
      secondary.push({
        key: "archive",
        icon: item.archived ? "fe fe-inbox" : "fe fe-archive",
        label: item.archived ? "Unarchive" : "Archive",
        onClick: () => this.props.handleArchiveProject(item.id, !item.archived),
      });
    }
    if (permission.deleteEnabled) {
      secondary.push({
        key: "delete",
        icon: item.deleted ? "fe fe-rotate-ccw" : "fe fe-trash-2",
        label: item.deleted ? "Undo delete" : "Delete",
        tone: "danger",
        onClick: () => this.props.handleDeleteProject(item.id, !item.deleted),
      });
    }
    if (permission.removeEnabled) {
      secondary.push({
        key: "remove",
        icon: this.state.confirmRemove ? "fe fe-check" : "fe fe-x",
        label: this.state.confirmRemove ? "Confirm remove" : "Remove permanently",
        tone: "danger",
        onClick: this.handleRemove,
      });
    }
    return { primary, secondary };
  };

  canEdit = () => {
    const { item, permission } = this.props;
    return !item.archived && permission.editEnabled && item.status !== "COMPLETED" && item.status !== "CLOSED";
  };

  render() {
    const { item, permission } = this.props;
    const { menuOpen } = this.state;
    const statusMeta = getProjectStatusMeta(item.status);
    const typeMeta = getProjectTypeMeta(item.projectType);
    const clientLine = formatProjectClientLine(item);
    const taskPct = getProjectTaskPct(item);
    const hoursPct = getProjectHoursPct(item);
    const { primary, secondary } = this.getMenuSections();
    const projectLabel = item.name || item.itemIdUserTeamPrefix;

    return (
      <article
        ref={this.rowRef}
        className={classNames("lux-bid-list__item lux-project-row", {
          "is-archived": item.archived,
          "is-deleted": item.deleted,
          "is-favorite": item.favorite,
          "is-menu-open": menuOpen,
          [`is-status-${statusMeta.tone}`]: true,
        })}
        role="listitem"
      >
        <span className="lux-bid-list__accent" aria-hidden="true" />

        <div className="lux-bid-list__col lux-bid-list__col--fav">
          <button
            type="button"
            className={classNames("lux-project-list__fav", { "is-active": item.favorite })}
            onClick={() => this.props.handleFavoriteProject(item.id, !item.favorite)}
            aria-label={item.favorite ? "Remove from favorites" : "Add to favorites"}
          >
            <i className={classNames("fe", item.favorite ? "fe-star" : "fe-star")} aria-hidden="true" />
          </button>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--id">
          <span className="lux-bid-list__ref">{item.itemIdUserTeamPrefix}</span>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--created">
          <time className="lux-bid-list__date" dateTime={item.createdDate}>
            {dateUtils.convertDateFormat(item.createdDate)}
          </time>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--study lux-project-row__project">
          <NavLink
            to={`/project/details/${item.itemIdUserTeamPrefix}`}
            className="lux-project-row__name"
            title={projectLabel}
          >
            <span className="lux-project-row__name-text">{projectLabel}</span>
            <i className="fe fe-arrow-up-right" aria-hidden="true" />
          </NavLink>
          <div className="lux-project-row__meta">
            {clientLine && (
              <span className="lux-project-row__client" title={clientLine}>
                <i className="fe fe-users" aria-hidden="true" />
                {clientLine}
              </span>
            )}
            <div className="lux-project-row__tags">
              {item.deleted && (
                <span className="lux-bid-list__deleted-badge">
                  <i className="fe fe-trash-2" aria-hidden="true" />
                  Deleted
                </span>
              )}
              {item.shared && (
                <span className="lux-project-list__shared-badge" title="Shared project">
                  <i className="fe fe-share-2" aria-hidden="true" />
                  Shared
                </span>
              )}
              {typeMeta && (
                <span className={classNames("lux-bid-list__type-pill", `is-${typeMeta.tone}`)}>{typeMeta.label}</span>
              )}
            </div>
          </div>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--account">
          <span className="lux-project-row__account" title={item.accountName || undefined}>
            {item.accountName || "—"}
          </span>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--metrics">
          <div className="lux-project-row__metrics">
            <div className="lux-project-row__metric">
              <span className="lux-project-row__metric-label">Tasks</span>
              <span className="lux-project-row__metric-value">
                {item.completedTaskCount}/{item.taskTotalCount}
                <em>{taskPct}%</em>
              </span>
            </div>
            <div className="lux-project-row__metric">
              <span className="lux-project-row__metric-label">Hours</span>
              <span className="lux-project-row__metric-value">
                {item.actualHours}/{item.estHours}
                <em>{hoursPct}%</em>
              </span>
            </div>
          </div>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--dates lux-project-row__dates-col">
          <div className="lux-project-row__dates">
            <span className="lux-project-row__date is-start">
              <em>Start</em>
              {dateUtils.convertDateFormat(item.estStartTime) || "—"}
            </span>
            <span className="lux-project-row__date is-end">
              <em>End</em>
              {dateUtils.convertDateFormat(item.estCompletionTime) || "—"}
            </span>
          </div>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--status is-center">
          <div className={classNames("lux-bid-list__status-select lux-project-row__status", `is-${statusMeta.tone}`)}>
            <SelectInput
              options={PROJECT_STATUS_OPTIONS}
              value={getProjectStatusSelectValue(item.status)}
              allowLevelDown={permission.allowStatusLevelDown}
              changeableStatus={permission.changeableStatus}
              isReadOnly={!permission.allowStatusChange}
              itemId={item.id}
              onChange={this.props.handleUpdateStatus}
              className="lux-bid-list__status-input"
            />
          </div>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--actions">
          <div className="lux-project-row__actions">
            {permission.viewEnabled && (
              <button
                type="button"
                className="lux-project-row__action"
                title="View project"
                aria-label={`View ${projectLabel}`}
                onClick={(event) => {
                  this.stopRowClick(event);
                  this.props.onViewProject(item.id);
                }}
              >
                <i className="fe fe-eye" aria-hidden="true" />
              </button>
            )}
            {this.canEdit() && (
              <button
                type="button"
                className="lux-project-row__action"
                title="Edit project"
                aria-label={`Edit ${projectLabel}`}
                onClick={(event) => {
                  this.stopRowClick(event);
                  this.props.handleEditProject(item.id, item.userTeamId);
                }}
              >
                <i className="fe fe-edit-2" aria-hidden="true" />
              </button>
            )}
            <button
              ref={this.menuTriggerRef}
              type="button"
              className="lux-project-row__action lux-project-row__action--menu"
              onClick={this.toggleMenu}
              aria-expanded={menuOpen}
              aria-haspopup="menu"
              aria-label={`More actions for ${projectLabel}`}
            >
              <i className="fe fe-more-horizontal" aria-hidden="true" />
            </button>
            <LuxListRowMenuPortal open={menuOpen} anchorRef={this.menuTriggerRef} className="lux-bid-list__menu-panel">
              <header className="lux-emp-card__menu-head">
                <span className="lux-emp-card__menu-head-icon" aria-hidden="true"><i className="fe fe-layers" /></span>
                <div>
                  <span className="lux-emp-card__menu-eyebrow">Project</span>
                  <strong title={projectLabel}>{projectLabel}</strong>
                </div>
                <button type="button" className="lux-emp-card__menu-close" onClick={this.runMenuAction(null)} aria-label="Close menu">
                  <i className="fe fe-x" aria-hidden="true" />
                </button>
              </header>
              <div className="lux-emp-card__menu-body">
                {primary.map((entry) => this.renderMenuItem(entry))}
                {secondary.length > 0 && primary.length > 0 && <div className="lux-emp-card__menu-divider" aria-hidden="true" />}
                {secondary.map((entry) => this.renderMenuItem(entry))}
              </div>
            </LuxListRowMenuPortal>
          </div>
        </div>
      </article>
    );
  }
}

export default ProjectInfoLine;
