import React, { Component } from "react";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { ADMIN_PAGE_META } from "config/admin-page-meta.config";
import { isFeatureFlagsAdminEnabled } from "config/feature-flag.config";
import {
  buildFeatureAdoptionSeries,
  buildFeatureFlagInsights,
  buildFeatureFlagMetrics,
  buildFeatureRiskSeries,
  filterFeatureFlags,
} from "config/feature-flag.utils";
import { featureFlagService } from "_services/featureFlag.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import FeatureFlagRegister from "views/admin/components/FeatureFlagRegister";
import FeatureFlagDetailPanel from "views/admin/components/FeatureFlagDetailPanel";
import PolicyAnalyticsBarChart from "views/people/components/policy/PolicyAnalyticsBarChart";
import {
  AdminActionButton,
  AdminPanelHead,
  AdminPanelLink,
  AdminQuickNav,
  AdminLuxPage,
} from "views/admin/components/AdminLuxShared";

const MODULE_FILTERS = ["ALL", "Admin", "People", "Workspace", "Payroll", "HRMS", "Approvals"];

const QUICK_LINKS = [
  {
    path: "/admin/appconfig",
    label: "Application config",
    desc: "Org overrides & pilot groups",
    icon: "fe fe-sliders",
    tone: "violet",
  },
  {
    path: "/admin/roles",
    label: "Roles & permissions",
    desc: "Menu access for flag admin",
    icon: "fe fe-shield",
    tone: "indigo",
  },
  {
    path: "/admin/security",
    label: "Masking policy",
    desc: "Sensitive field posture",
    icon: "fe fe-eye-off",
    tone: "rose",
  },
];

class FeatureFlagsPage extends Component {
  state = {
    flags: [],
    loading: true,
    loadError: null,
    dataSource: null,
    statusFilter: "ALL",
    moduleFilter: "ALL",
    query: "",
    selectedId: null,
    saving: false,
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Feature flags");
    this.loadFlags();
  }

  loadFlags = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await featureFlagService.listFlags();
      const flags = result.payload || [];
      this.setState({
        flags,
        loading: false,
        dataSource: result.source || null,
        selectedId: this.state.selectedId || (flags[0] && flags[0].id) || null,
      });
    } catch (e) {
      this.setState({
        loading: false,
        loadError: "Unable to load feature flag registry.",
        flags: [],
      });
    }
  };

  getFilteredFlags = () => {
    const { flags, statusFilter, moduleFilter, query } = this.state;
    return filterFeatureFlags(flags, {
      status: statusFilter,
      module: moduleFilter,
      query,
    });
  };

  getSelectedFlag = () => {
    const { flags, selectedId } = this.state;
    return flags.find((row) => row.id === selectedId) || null;
  };

  getDependents = (flag) => {
    if (!flag || !flag.dependents || flag.dependents.length === 0) {
      return [];
    }
    const { flags } = this.state;
    return flag.dependents.map((key) => flags.find((row) => row.key === key) || { key, name: key, enabled: false });
  };

  handleToggle = async (enabled) => {
    const { selectedId } = this.state;
    if (!selectedId) return;
    this.setState({ saving: true });
    try {
      const result = await featureFlagService.updateFlag(selectedId, enabled);
      const updated = result.payload;
      this.setState((prev) => ({
        flags: prev.flags.map((row) => (row.id === selectedId ? updated : row)),
        saving: false,
      }));
    } catch (e) {
      this.setState({ saving: false });
    }
  };

  handleSetStatus = async (status) => {
    const { selectedId } = this.state;
    if (!selectedId) return;
    this.setState({ saving: true });
    try {
      const result = await featureFlagService.setFlagStatus(selectedId, status);
      const updated = result.payload;
      this.setState((prev) => ({
        flags: prev.flags.map((row) => (row.id === selectedId ? updated : row)),
        saving: false,
      }));
    } catch (e) {
      this.setState({ saving: false });
    }
  };

  renderInsights = () => {
    const { flags, loading } = this.state;
    if (loading) return null;
    const insights = buildFeatureFlagInsights(flags);
    return (
      <div className="lux-fflag-insights" role="list">
        {insights.map((insight) => (
          <article
            key={insight.id}
            className={classNames("lux-fflag-insight-card", `is-${insight.tone}`)}
            role="listitem"
          >
            <span className="lux-fflag-insight-card__icon" aria-hidden="true">
              <i className={insight.icon} />
            </span>
            <div className="lux-fflag-insight-card__copy">
              <strong>{insight.title}</strong>
              <p>{insight.copy}</p>
            </div>
          </article>
        ))}
      </div>
    );
  };

  renderAnalytics = () => {
    const { flags, loading } = this.state;
    if (loading) return null;
    const adoptionSeries = buildFeatureAdoptionSeries(flags).map((row) => ({
      label: row.label,
      value: row.value,
      tone: row.enabled ? "green" : "slate",
      meta: row.enabled ? "on" : "off",
    }));
    const riskSeries = buildFeatureRiskSeries(flags).map((row) => ({
      label: row.label,
      value: row.value,
      tone: row.tone,
      meta: row.meta,
    }));
    return (
      <section className="lux-fflag-analytics lux-hrms-dash__panel">
        <AdminPanelHead
          title="Rollout analytics"
          subtitle="Pilot uptake and risk mix across the org flag registry."
        />
        <div className="lux-fflag-analytics__grid">
          <PolicyAnalyticsBarChart
            title="Adoption by flag"
            subtitle="Percent of active users exposed"
            series={adoptionSeries}
            suffix="%"
          />
          <PolicyAnalyticsBarChart
            title="Risk posture"
            subtitle="Flags by blast-radius band"
            series={riskSeries}
          />
        </div>
      </section>
    );
  };

  render() {
    if (!isFeatureFlagsAdminEnabled()) {
      return (
        <PersonaAccessDenied
          moduleName="Feature flags"
          reason="Feature flag administration is not enabled for your organization."
        />
      );
    }

    const { loading, loadError, dataSource, statusFilter, moduleFilter, query } = this.state;
    const filteredFlags = this.getFilteredFlags();
    const metrics = buildFeatureFlagMetrics(this.state.flags);
    const selectedFlag = this.getSelectedFlag();

    const kpiCards = [
      {
        id: "flags",
        label: "Flags",
        value: metrics.totalFlags,
        hint: `${metrics.enabledFlags} enabled`,
        tone: "primary",
        icon: "fe fe-toggle-right",
      },
      {
        id: "pilot",
        label: "Staged",
        value: metrics.pilotFlags,
        hint: "Not fully enabled",
        tone: "blue",
        icon: "fe fe-zap",
      },
      {
        id: "adoption",
        label: "Adoption",
        value: `${metrics.adoptionAvg}%`,
        hint: "Avg uptake",
        tone: "green",
        icon: "fe fe-trending-up",
      },
      {
        id: "risk",
        label: "High risk on",
        value: metrics.highRiskEnabled,
        hint: "Needs review",
        tone: "amber",
        icon: "fe fe-alert-triangle",
      },
    ];

    return (
      <AdminLuxPage
        pageMeta={ADMIN_PAGE_META.featureFlags}
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        testId="page-admin-feature-flags"
        className="lux-register-page lux-fflag-page"
        heroActions={
          <AdminActionButton icon="fe fe-refresh-cw" onClick={this.loadFlags} disabled={loading}>
            Refresh
          </AdminActionButton>
        }
      >
        {loadError && (
          <div className="lux-employee-360__error lux-fflag__error" role="alert">
            <span>{loadError}</span>
            <AdminActionButton variant="ghost" onClick={this.loadFlags}>
              Retry
            </AdminActionButton>
          </div>
        )}

        {this.renderInsights()}

        <AdminQuickNav
          className="lux-fflag-quick-nav"
          eyebrow="Related governance"
          title="Continue in Admin"
          links={QUICK_LINKS}
        />

        {this.renderAnalytics()}

        <section className="lux-hrms-dash__panel lux-fflag-panel">
          <AdminPanelHead
            title="Org flag registry"
            subtitle="Select a flag to stage, enable, or disable. Changes are audited when audit writes are enabled."
            actions={<AdminPanelLink to="/admin/appconfig">Application config</AdminPanelLink>}
          />

          <div className="lux-fflag-panel__toolbar">
            <div className="lux-appr-toolbar__row">
              <div className="lux-appr-toolbar__search">
                <i className="fe fe-search" aria-hidden="true" />
                <input
                  type="search"
                  className="lux-appr-toolbar__search-input"
                  placeholder="Search flag name or key"
                  value={query}
                  onChange={(e) => this.setState({ query: e.target.value })}
                />
              </div>
              <span className="lux-appr-toolbar__count">
                <strong>{filteredFlags.length}</strong> flag{filteredFlags.length === 1 ? "" : "s"}
              </span>
            </div>
            <div className="lux-fflag-panel__filters">
              <div className="lux-appr-toolbar__group">
                <span className="lux-appr-toolbar__label">Status</span>
                <div className="lux-hrms-dash__filter-group">
                  {["ALL", "ENABLED", "PILOT", "DISABLED"].map((value) => (
                    <button
                      key={value}
                      type="button"
                      className={classNames("lux-hrms-dash__filter-chip", {
                        "is-active": statusFilter === value,
                      })}
                      onClick={() => this.setState({ statusFilter: value })}
                    >
                      {value === "ALL" ? "All" : value.charAt(0) + value.slice(1).toLowerCase()}
                    </button>
                  ))}
                </div>
              </div>
              <div className="lux-appr-toolbar__group">
                <span className="lux-appr-toolbar__label">Module</span>
                <div className="lux-hrms-dash__filter-group">
                  {MODULE_FILTERS.map((value) => (
                    <button
                      key={value}
                      type="button"
                      className={classNames("lux-hrms-dash__filter-chip", {
                        "is-active": moduleFilter === value,
                      })}
                      onClick={() => this.setState({ moduleFilter: value })}
                    >
                      {value === "ALL" ? "All" : value}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>

          <div className="lux-fflag-panel__body">
            <div className="lux-fflag-panel__grid">
              <div className="lux-fflag-panel__register">
                {loading ? (
                  <LuxRegisterEmptyState title="Loading flags" description="Fetching org feature registry." />
                ) : filteredFlags.length === 0 ? (
                  <LuxRegisterEmptyState title="No flags match" description="Adjust filters or search." />
                ) : (
                  <FeatureFlagRegister
                    flags={filteredFlags}
                    selectedId={this.state.selectedId}
                    onSelect={(flag) => this.setState({ selectedId: flag.id })}
                  />
                )}
              </div>
              <FeatureFlagDetailPanel
                flag={selectedFlag}
                saving={this.state.saving}
                dependents={this.getDependents(selectedFlag)}
                onToggle={this.handleToggle}
                onSetStatus={this.handleSetStatus}
              />
            </div>
          </div>
        </section>
      </AdminLuxPage>
    );
  }
}

export default FeatureFlagsPage;
