/**
 * F02-T1: Normalize Employee 360 aggregate API payload into client shape.
 */

function pickSummaryFields(raw) {
  if (!raw || typeof raw !== "object") {
    return null;
  }
  const source = raw.summary && typeof raw.summary === "object" ? raw.summary : raw;
  return {
    teamName: source.teamName,
    roleName: source.roleName,
    manager: source.manager,
    location: source.location,
    employmentType: source.employmentType,
    attendanceToday: source.attendanceToday,
    leaveBalanceDays: source.leaveBalanceDays,
    timesheetStatus: source.timesheetStatus,
    pendingApprovals: source.pendingApprovals,
    profileCompletionPct: source.profileCompletionPct,
    payrollGroup: source.payrollGroup,
    payroll: source.payroll && typeof source.payroll === "object" ? source.payroll : null,
    attentionItems: Array.isArray(source.attentionItems) ? source.attentionItems : [],
    allocatedProjects: Array.isArray(source.allocatedProjects) ? source.allocatedProjects : [],
    projectAllocations: Array.isArray(source.projectAllocations) ? source.projectAllocations : [],
    documents: Array.isArray(source.documents) ? source.documents : [],
    assets: Array.isArray(source.assets) ? source.assets : [],
    recentNotes: Array.isArray(source.recentNotes) ? source.recentNotes : [],
    activityCount: source.activityCount != null ? source.activityCount : null,
    performance:
      source.performance && typeof source.performance === "object" ? source.performance : null,
  };
}

export function normalizeEmployee360Payload(apiPayload) {
  if (!apiPayload) {
    return null;
  }

  const employee = apiPayload.employee || apiPayload.profile || null;
  const summary = pickSummaryFields(apiPayload);
  const visibleTabIds = Array.isArray(apiPayload.visibleTabIds)
    ? apiPayload.visibleTabIds
    : Array.isArray(apiPayload.visibleTabs)
      ? apiPayload.visibleTabs.map((tab) => (typeof tab === "string" ? tab : tab.id))
      : null;

  return {
    employee,
    summary,
    visibleTabIds,
    maskingPolicy: apiPayload.maskingPolicy || null,
    accessAllowed: apiPayload.accessAllowed !== false,
    scopeType: apiPayload.scopeType || null,
    source: "api",
  };
}

export function mergeSummaryWithEmployee(employee, summary) {
  if (!employee) {
    return summary;
  }
  const base = summary || {};
  return {
    ...base,
    teamName:
      base.teamName ||
      (employee.defaultUserTeamDetails && employee.defaultUserTeamDetails.name),
    roleName:
      base.roleName ||
      (employee.userAccessDetails && employee.userAccessDetails.name),
    profileCompletionPct:
      base.profileCompletionPct != null
        ? base.profileCompletionPct
        : employee.profileCompletionPct,
  };
}
