import {
  EXPENSE_CATEGORIES,
  EXPENSE_CLAIM_STATUSES,
  REIMBURSEMENT_STATUSES,
  normalizeExpenseClaim,
  normalizeExpensePolicyRule,
  normalizeReimbursement,
} from "config/expenses.config";

export function filterExpenseClaims(rows = [], filters = {}) {
  let next = [...rows];
  if (filters.status) {
    next = next.filter((row) => row.status === filters.status);
  }
  if (filters.category) {
    next = next.filter((row) => row.category === filters.category);
  }
  if (filters.employeeId) {
    next = next.filter((row) => row.employeeId === filters.employeeId);
  }
  if (filters.projectId) {
    next = next.filter((row) => row.projectId === filters.projectId);
  }
  if (filters.pendingApproval) {
    next = next.filter((row) =>
      [EXPENSE_CLAIM_STATUSES.SUBMITTED, EXPENSE_CLAIM_STATUSES.MANAGER_APPROVED].includes(row.status)
    );
  }
  if (filters.query) {
    const q = String(filters.query).toLowerCase();
    next = next.filter(
      (row) =>
        (row.title || "").toLowerCase().includes(q) ||
        (row.employeeName || "").toLowerCase().includes(q) ||
        (row.projectName || "").toLowerCase().includes(q)
    );
  }
  if (filters.policyIssuesOnly) {
    next = next.filter((row) => row.policyViolations && row.policyViolations.length > 0);
  }
  return next.map((row) => normalizeExpenseClaim(row)).filter(Boolean);
}

export function filterReimbursements(rows = [], filters = {}) {
  let next = [...rows];
  if (filters.status) {
    next = next.filter((row) => row.status === filters.status);
  }
  if (filters.employeeId) {
    next = next.filter((row) => row.employeeId === filters.employeeId);
  }
  if (filters.query) {
    const q = String(filters.query).toLowerCase();
    next = next.filter(
      (row) =>
        (row.employeeName || "").toLowerCase().includes(q) ||
        (row.projectName || "").toLowerCase().includes(q)
    );
  }
  return next.map((row) => normalizeReimbursement(row)).filter(Boolean);
}

export function validateExpenseAgainstPolicy(claim, policyRules = []) {
  const normalized = normalizeExpenseClaim(claim);
  if (!normalized) {
    return { valid: false, violations: ["Invalid claim payload"] };
  }
  const violations = [];
  const rule =
    policyRules.find((item) => item.category === normalized.category) ||
    policyRules.find((item) => item.category === EXPENSE_CATEGORIES.OTHER);

  if (rule) {
    const policy = normalizeExpensePolicyRule(rule);
    if (policy.maxAmountUsd != null && normalized.totalUsd > policy.maxAmountUsd) {
      violations.push(`Amount exceeds ${policy.category} limit of $${policy.maxAmountUsd}`);
    }
    if (policy.requiresReceipt && normalized.receipts.length === 0) {
      violations.push("Receipt required for this category");
    }
    if (policy.requiresProject && !normalized.projectId) {
      violations.push("Project code required for billable expenses");
    }
    const missingReceiptLines = normalized.lines.filter((line) => !line.receiptAttached);
    if (policy.requiresReceipt && missingReceiptLines.length > 0) {
      violations.push("All line items must have receipts attached");
    }
  }

  return {
    valid: violations.length === 0,
    violations,
    requiresFinanceApproval:
      rule && rule.financeThresholdUsd != null && normalized.totalUsd >= rule.financeThresholdUsd,
  };
}

export function buildEmployeeExpensesOverview(claims = [], options = {}) {
  const rows = filterExpenseClaims(claims, options.filters || {});
  const draftCount = rows.filter((row) => row.status === EXPENSE_CLAIM_STATUSES.DRAFT).length;
  const pendingCount = rows.filter((row) =>
    [EXPENSE_CLAIM_STATUSES.SUBMITTED, EXPENSE_CLAIM_STATUSES.MANAGER_APPROVED].includes(row.status)
  ).length;
  const reimbursedUsd = rows
    .filter((row) => row.status === EXPENSE_CLAIM_STATUSES.REIMBURSED)
    .reduce((sum, row) => sum + (row.totalUsd || 0), 0);

  return {
    claims: rows,
    kpiCards: [
      { id: "open", label: "Open claims", value: String(rows.length), hint: "All statuses", icon: "fe fe-layers", tone: "indigo" },
      { id: "draft", label: "Drafts", value: String(draftCount), hint: "Ready to submit", icon: "fe fe-edit", tone: "slate" },
      { id: "pending", label: "Pending approval", value: String(pendingCount), hint: "Manager or finance", icon: "fe fe-clock", tone: "amber" },
      { id: "reimbursed", label: "Reimbursed YTD", value: `$${reimbursedUsd.toLocaleString()}`, hint: "Paid to you", icon: "fe fe-dollar-sign", tone: "green" },
    ],
    insights: buildExpenseInsights(rows, "employee"),
    categoryBreakdown: buildCategoryBreakdown(rows),
  };
}

export function buildFinanceExpensesOverview(claims = [], leakageFlags = [], options = {}) {
  const rows = filterExpenseClaims(claims, options.filters || {});
  const pendingFinance = rows.filter((row) =>
    [EXPENSE_CLAIM_STATUSES.SUBMITTED, EXPENSE_CLAIM_STATUSES.MANAGER_APPROVED].includes(row.status)
  );
  const policyViolations = rows.filter((row) => row.policyViolations.length > 0).length;
  const billableUnbilled = rows.filter(
    (row) => row.billable && row.status === EXPENSE_CLAIM_STATUSES.FINANCE_APPROVED
  ).length;
  const openLeakage = (leakageFlags || []).filter((row) => row.status === "OPEN");

  return {
    claims: rows,
    pendingApprovals: pendingFinance,
    leakageFlags: openLeakage,
    kpiCards: [
      { id: "queue", label: "Approval queue", value: String(pendingFinance.length), hint: "Needs finance action", icon: "fe fe-inbox", tone: "amber" },
      { id: "violations", label: "Policy violations", value: String(policyViolations), hint: "Requires review", icon: "fe fe-alert-triangle", tone: "rose" },
      { id: "billable", label: "Billable unbilled", value: String(billableUnbilled), hint: "Ready for project billing", icon: "fe fe-briefcase", tone: "blue" },
      { id: "leakage", label: "Leakage flags", value: String(openLeakage.length), hint: "Agent-detected risk", icon: "fe fe-shield", tone: "violet" },
    ],
    insights: buildExpenseInsights(rows, "finance"),
    categoryBreakdown: buildCategoryBreakdown(rows),
    agingSeries: buildReimbursementAgingSeries(rows),
  };
}

export function buildReimbursementsOverview(reimbursements = [], options = {}) {
  const rows = filterReimbursements(reimbursements, options.filters || {});
  const pending = rows.filter((row) => row.status === REIMBURSEMENT_STATUSES.PENDING);
  const scheduled = rows.filter((row) => row.status === REIMBURSEMENT_STATUSES.SCHEDULED);
  const paidUsd = rows
    .filter((row) => row.status === REIMBURSEMENT_STATUSES.PAID)
    .reduce((sum, row) => sum + (row.amountUsd || 0), 0);

  return {
    reimbursements: rows,
    kpiCards: [
      { id: "pending", label: "Pending payout", value: String(pending.length), hint: "Awaiting payroll run", icon: "fe fe-clock", tone: "amber" },
      { id: "scheduled", label: "Scheduled", value: String(scheduled.length), hint: "In next payroll cycle", icon: "fe fe-calendar", tone: "blue" },
      { id: "paid", label: "Paid YTD", value: `$${paidUsd.toLocaleString()}`, hint: "Completed reimbursements", icon: "fe fe-check-circle", tone: "green" },
      { id: "aging", label: "Avg aging", value: `${averageAgingDays(pending)}d`, hint: "Pending queue", icon: "fe fe-trending-up", tone: "slate" },
    ],
    insights: [
      {
        id: "payroll-link",
        tone: "blue",
        icon: "fe fe-layers",
        title: "Payroll linkage",
        copy: "Approved claims sync to the next open payroll run when reimbursement is scheduled.",
        path: "/payroll/runs",
      },
    ],
  };
}

function averageAgingDays(rows) {
  if (!rows.length) {
    return 0;
  }
  const total = rows.reduce((sum, row) => sum + (row.agingDays || 0), 0);
  return Math.round(total / rows.length);
}

function buildCategoryBreakdown(rows) {
  const totals = {};
  rows.forEach((row) => {
    const key = row.category || EXPENSE_CATEGORIES.OTHER;
    totals[key] = (totals[key] || 0) + (row.totalUsd || 0);
  });
  return Object.keys(totals).map((category) => ({
    category,
    amountUsd: totals[category],
  }));
}

function buildReimbursementAgingSeries(rows) {
  const buckets = [
    { label: "0–7d", count: 0 },
    { label: "8–14d", count: 0 },
    { label: "15–30d", count: 0 },
    { label: "30d+", count: 0 },
  ];
  rows
    .filter((row) =>
      [EXPENSE_CLAIM_STATUSES.SUBMITTED, EXPENSE_CLAIM_STATUSES.MANAGER_APPROVED].includes(row.status)
    )
    .forEach((row) => {
      const submitted = row.submittedAt ? new Date(row.submittedAt) : new Date();
      const days = Math.max(0, Math.round((Date.now() - submitted.getTime()) / 86400000));
      if (days <= 7) {
        buckets[0].count += 1;
      } else if (days <= 14) {
        buckets[1].count += 1;
      } else if (days <= 30) {
        buckets[2].count += 1;
      } else {
        buckets[3].count += 1;
      }
    });
  return buckets;
}

function buildExpenseInsights(rows, mode) {
  const insights = [];
  const violations = rows.filter((row) => row.policyViolations.length > 0);
  if (violations.length) {
    insights.push({
      id: "policy",
      tone: "rose",
      icon: "fe fe-alert-triangle",
      title: `${violations.length} claim${violations.length === 1 ? "" : "s"} with policy exceptions`,
      copy: "Review receipts, category limits, and project linkage before approval.",
      path: mode === "finance" ? "/finance/expenses" : "/payroll/expenses",
    });
  }
  const billable = rows.filter((row) => row.billable && row.status === EXPENSE_CLAIM_STATUSES.FINANCE_APPROVED);
  if (billable.length && mode === "finance") {
    insights.push({
      id: "billable",
      tone: "blue",
      icon: "fe fe-briefcase",
      title: `${billable.length} billable expense${billable.length === 1 ? "" : "s"} ready for project billing`,
      copy: "Link approved claims to project cost and invoice workflows.",
      path: "/finance/project-financials",
    });
  }
  if (!insights.length) {
    insights.push({
      id: "healthy",
      tone: "green",
      icon: "fe fe-check-circle",
      title: "Expense queue is healthy",
      copy: "No policy violations or aging blockers in the current filter.",
      path: mode === "finance" ? "/finance/expenses" : "/payroll/expenses",
    });
  }
  return insights;
}

export function exportExpensesCsv(claims = []) {
  const header = "claim_id,employee,title,status,category,total_usd,billable,project,submitted_at";
  const lines = filterExpenseClaims(claims).map((row) =>
    [
      row.id,
      row.employeeName,
      `"${(row.title || "").replace(/"/g, '""')}"`,
      row.status,
      row.category,
      row.totalUsd != null ? row.totalUsd : "",
      row.billable ? "yes" : "no",
      row.projectCode || "",
      row.submittedAt || "",
    ].join(",")
  );
  return [header, ...lines].join("\n");
}

export function validateExpenseClaimPayload(payload = {}) {
  if (!payload.title || !String(payload.title).trim()) {
    return { valid: false, message: "Title is required" };
  }
  const lines = payload.lines || [];
  if (!lines.length) {
    return { valid: false, message: "At least one line item is required" };
  }
  const invalidLine = lines.find((line) => !line.description || line.amountUsd == null || line.amountUsd <= 0);
  if (invalidLine) {
    return { valid: false, message: "Each line needs a description and positive amount" };
  }
  return { valid: true };
}
