import React from "react";
import classNames from "classnames";

export default function Employee360Tabs({ tabs, activeTab, onSelect }) {
  if (!tabs || tabs.length === 0) {
    return null;
  }

  return (
    <nav className="pd-nav profile-nav lux-employee-360__tabs" role="tablist" aria-label="Employee 360 sections">
      {tabs.map((tab) => {
        const panelId = `employee-360-tabpanel-${tab.id}`;
        return (
          <button
            key={tab.id}
            type="button"
            role="tab"
            id={`employee-360-tab-${tab.id}`}
            aria-controls={panelId}
            aria-selected={activeTab === tab.id}
            className={classNames("pd-nav__item", { "is-active": activeTab === tab.id })}
            onClick={() => onSelect(tab.id)}
          >
            <i className={tab.icon} aria-hidden="true" />
            <span>{tab.label}</span>
            {tab.planned === true && (
              <span className="lux-employee-360__tab-soon" aria-label="Planned feature">
                <i className="fe fe-clock" aria-hidden="true" />
              </span>
            )}
          </button>
        );
      })}
    </nav>
  );
}
