import React from "react";
import Skeleton, { SkeletonTheme } from "react-loading-skeleton";
import { LUX_SKELETON_THEME } from "./luxSkeleton.constants";

/** Summary strip skeleton (projects, reports, feedback, bids, etc.). */
export default function LuxSummaryPageSkeleton({ className, kpiCount = 6 }) {
  return (
    <SkeletonTheme baseColor={LUX_SKELETON_THEME.baseColor} highlightColor={LUX_SKELETON_THEME.highlightColor}>
      <div className={["lux-bid-summary is-loading", className].filter(Boolean).join(" ")} aria-busy="true">
        <Skeleton height={88} borderRadius={16} />
        <div className="lux-bid-summary__kpi-strip lux-bid-summary__kpi-strip--skeleton">
          {Array.from({ length: kpiCount }, (_, i) => (
            <Skeleton key={i} height={72} borderRadius={14} />
          ))}
        </div>
      </div>
    </SkeletonTheme>
  );
}
