import React, { Component } from "react";
import { connect } from "react-redux";
import { accessUtils } from "_helpers";
import LuxCreatePanelShell from "views/common/create/LuxCreatePanelShell";
import ProjectDetailsGeneral from "../ProjectDetailsGeneral";

class ViewProjectDetailsSidebar extends Component {
  constructor() {
    super();
    this.state = {
      permission: accessUtils.getProjectAccessControl(),
    };
  }

  noop = () => {};

  render() {
    const { show, onCloseViewProject, projectInfo } = this.props;
    const teamEstimate =
      projectInfo &&
      projectInfo.projectEstimate &&
      projectInfo.projectEstimate.teamEstimate;

    return (
      <LuxCreatePanelShell
        show={show}
        onClose={onCloseViewProject}
        panelId="view-project-details-sidebar"
        className="view_project_right_sidebar lux-view-project-panel"
        kicker="Project"
        title="Project details"
        subtitle={projectInfo && projectInfo.name ? projectInfo.name : "View schedule, estimates, and checklist"}
      >
        {show && projectInfo && (
          <div className="lux-create-panel__scroll lux-view-project-panel__scroll">
            <ProjectDetailsGeneral
              item={projectInfo}
              readOnly
              embedded
              showHero
              permission={this.state.permission}
              projectEstimateRequest={teamEstimate}
              onEstimateChange={this.noop}
              handleUpdateEstimate={this.noop}
            />
          </div>
        )}
      </LuxCreatePanelShell>
    );
  }
}

const mapStateToProps = (state) => ({
  projectInfo: state.projects.selectedProjectInfo,
  isLoading: state.projects.loading,
});

export default connect(mapStateToProps)(ViewProjectDetailsSidebar);
