import React, { Component } from "react";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import {
  EDITABLE_PERSONAS,
  buildPersonaDraftFromRole,
  clonePagePersonaDraft,
  getPersonaAccessMeta,
  groupPersonaPageRows,
  buildPersonaPageRows,
  summarizePersonaPages,
  togglePersonaOnPageInDraft,
  resetPageToProductDefault,
} from "config/persona-access-matrix.utils";
import { listCatalogPagesForPersonaAdmin } from "config/persona-page-map.config";
import { isOrgPathDisabled, isOrgPersonaDisabled } from "config/org-access-policy.config";
import { AdminActionButton } from "views/admin/components/AdminLuxShared";

/**
 * Persona-first access editor (Roles & permissions).
 * Persona enablement is role-scoped; page toggles write the org pagePersonaMap.
 */
export default class PersonaAccessEditor extends Component {
  state = {
    personaDraft: buildPersonaDraftFromRole(null),
    pageMapDraft: {},
    pages: listCatalogPagesForPersonaAdmin(),
    expandedPersona: null,
    pageQuery: "",
    dirtyPersonas: false,
    dirtyPages: false,
    syncedRoleId: null,
    syncedMapKey: null,
  };

  static getDerivedStateFromProps(props, state) {
    const roleId = props.role && props.role.id;
    const mapKey = props.pageMapRevision != null ? String(props.pageMapRevision) : "0";
    if (roleId !== state.syncedRoleId || mapKey !== state.syncedMapKey) {
      return {
        syncedRoleId: roleId,
        syncedMapKey: mapKey,
        personaDraft: buildPersonaDraftFromRole(props.role),
        pageMapDraft: clonePagePersonaDraft(props.pageMap || {}),
        pages: props.pages || listCatalogPagesForPersonaAdmin(),
        expandedPersona: null,
        pageQuery: "",
        dirtyPersonas: false,
        dirtyPages: false,
      };
    }
    return null;
  }

  togglePersonaEnabled = (code) => {
    if (this.props.readOnly || isOrgPersonaDisabled(code)) return;
    this.setState((prev) => {
      const set = new Set(prev.personaDraft.allowedPersonas || []);
      if (set.has(code)) {
        set.delete(code);
      } else {
        set.add(code);
      }
      const allowedPersonas = EDITABLE_PERSONAS.filter((p) => set.has(p));
      let defaultPersona = prev.personaDraft.defaultPersona;
      if (!allowedPersonas.includes(defaultPersona)) {
        defaultPersona = allowedPersonas[0] || "EMPLOYEE";
      }
      return {
        personaDraft: {
          ...prev.personaDraft,
          allowedPersonas,
          defaultPersona,
        },
        dirtyPersonas: true,
        expandedPersona:
          prev.expandedPersona === code && !allowedPersonas.includes(code)
            ? null
            : prev.expandedPersona,
      };
    });
  };

  setDefaultPersona = (event) => {
    const value = event.target.value;
    this.setState((prev) => ({
      personaDraft: { ...prev.personaDraft, defaultPersona: value },
      dirtyPersonas: true,
    }));
  };

  setSwitchEnabled = (event) => {
    const enabled = event.target.checked;
    this.setState((prev) => ({
      personaDraft: { ...prev.personaDraft, personaSwitchEnabled: enabled },
      dirtyPersonas: true,
    }));
  };

  toggleExpanded = (code) => {
    this.setState((prev) => ({
      expandedPersona: prev.expandedPersona === code ? null : code,
      pageQuery: prev.expandedPersona === code ? prev.pageQuery : "",
    }));
  };

  togglePageForPersona = (pageRow, personaCode) => {
    if (this.props.readOnly) return;
    this.setState((prev) => ({
      pageMapDraft: togglePersonaOnPageInDraft(prev.pageMapDraft, pageRow, personaCode),
      dirtyPages: true,
    }));
  };

  resetPageDefault = (path) => {
    if (this.props.readOnly) return;
    this.setState((prev) => ({
      pageMapDraft: resetPageToProductDefault(prev.pageMapDraft, path),
      dirtyPages: true,
    }));
  };

  handleSave = async () => {
    const { onSave } = this.props;
    if (!onSave) return;
    const { personaDraft, pageMapDraft, dirtyPersonas, dirtyPages } = this.state;
    try {
      await onSave({
        personaModules: {
          allowedPersonas: personaDraft.allowedPersonas,
          defaultPersona: personaDraft.defaultPersona,
          personaSwitchEnabled: personaDraft.personaSwitchEnabled,
        },
        pagePersonaMap: pageMapDraft,
        dirtyPersonas,
        dirtyPages,
      });
      this.setState({ dirtyPersonas: false, dirtyPages: false });
    } catch (e) {
      /* parent surfaces errors; keep dirty flags */
    }
  };

  renderPageGroups = (personaCode) => {
    const { role, readOnly } = this.props;
    const { pages, pageMapDraft, pageQuery } = this.state;
    const roleModules = (role && role.modules) || {};
    let rows = buildPersonaPageRows(personaCode, pages, pageMapDraft, roleModules);
    const q = String(pageQuery || "")
      .trim()
      .toLowerCase();
    if (q) {
      rows = rows.filter(
        (row) =>
          row.path.toLowerCase().includes(q) ||
          String(row.name || "")
            .toLowerCase()
            .includes(q) ||
          String(row.groupName || "")
            .toLowerCase()
            .includes(q)
      );
    }
    const groups = groupPersonaPageRows(rows);
    if (!groups.length) {
      return (
        <p className="lux-persona-access__empty-pages">No pages match this filter.</p>
      );
    }
    return groups.map((group) => (
      <div key={group.groupId} className="lux-persona-access__page-group">
        <div className="lux-persona-access__page-group-head">
          <strong>{group.groupName}</strong>
          <span>
            {group.enabledCount}/{group.pages.length} for persona
          </span>
        </div>
        <ul className="lux-persona-access__page-list" role="list">
          {group.pages.map((page) => {
            const orgPathOff = isOrgPathDisabled(page.path);
            return (
            <li
              key={page.path}
              className={classNames("lux-persona-access__page-row", {
                "is-on": page.personaAllowed && !orgPathOff,
                "is-module-off": !page.moduleEnabled || orgPathOff,
              })}
              role="listitem"
            >
              <div className="lux-persona-access__page-copy">
                <strong>{page.name}</strong>
                <span>
                  {page.path}
                  {orgPathOff
                    ? " · disabled at organization root"
                    : !page.moduleEnabled
                      ? " · blocked by role module flag"
                      : ""}
                  {!orgPathOff &&
                    (page.usingOverride
                      ? " · org override"
                      : page.effectiveOpen
                        ? " · open default"
                        : " · catalog default")}
                </span>
              </div>
              <div className="lux-persona-access__page-actions">
                {page.usingOverride && !readOnly && !orgPathOff && (
                  <button
                    type="button"
                    className="lux-persona-access__reset"
                    onClick={() => this.resetPageDefault(page.path)}
                  >
                    Reset
                  </button>
                )}
                <label className="custom-switch custom-switch-sm m-0 lux-rbac-matrix-card__switch">
                  <input
                    type="checkbox"
                    className="custom-switch-input"
                    checked={page.personaAllowed && !orgPathOff}
                    disabled={readOnly || orgPathOff}
                    onChange={() => this.togglePageForPersona(page, personaCode)}
                  />
                  <span className="custom-switch-indicator" />
                </label>
              </div>
            </li>
            );
          })}
        </ul>
      </div>
    ));
  };

  render() {
    const { readOnly, saving, compact } = this.props;
    const { personaDraft, pages, pageMapDraft, expandedPersona, pageQuery, dirtyPersonas, dirtyPages } =
      this.state;
    const roleModules = (this.props.role && this.props.role.modules) || {};
    const dirty = dirtyPersonas || dirtyPages;
    const allowedCount = (personaDraft.allowedPersonas || []).length;

    return (
      <section
        className={classNames("lux-persona-access", "lux-rbac-matrix-card", "is-indigo", {
          "lux-persona-access--compact": compact,
        })}
        data-testid="persona-access-editor"
      >
        <header className="lux-rbac-matrix-card__head">
          <div className="lux-rbac-matrix-card__title">
            <span className="lux-rbac-matrix-card__icon" aria-hidden="true">
              <i className="fe fe-users" />
            </span>
            <div>
              <strong>Persona access</strong>
              <span>
                {personaDraft.configured
                  ? `${allowedCount} persona${allowedCount === 1 ? "" : "s"} locked for this role`
                  : "Automatic from module flags — save to lock"}
              </span>
            </div>
          </div>
          <span
            className={classNames("lux-doc-badge", {
              "is-success": personaDraft.configured,
              "is-amber": !personaDraft.configured,
            })}
          >
            {personaDraft.configured ? "Explicit" : "Automatic"}
          </span>
        </header>

        <p className="lux-persona-access__notice">
          <i className="fe fe-info" aria-hidden="true" />
          <span>
            Enable personas for this role, then expand one to manage pages.{" "}
            <strong>Page toggles are organization-wide</strong> for that persona.{" "}
            <Link to="/admin/persona-navigation" className="lux-inline-link">
              Open org editor
            </Link>
          </span>
        </p>

        <ul className="lux-persona-access__list" role="list">
          {EDITABLE_PERSONAS.map((code) => {
            const meta = getPersonaAccessMeta(code);
            const orgDisabled = isOrgPersonaDisabled(code);
            const enabled = !orgDisabled && personaDraft.allowedPersonas.includes(code);
            const expanded = expandedPersona === code;
            const summary = summarizePersonaPages(code, pages, pageMapDraft, roleModules);
            return (
              <li
                key={code}
                className={classNames("lux-persona-access__item", {
                  "is-enabled": enabled,
                  "is-expanded": expanded,
                  "is-org-disabled": orgDisabled,
                })}
                role="listitem"
              >
                <div className="lux-persona-access__item-row">
                  <button
                    type="button"
                    className="lux-persona-access__expand"
                    onClick={() => this.toggleExpanded(code)}
                    aria-expanded={expanded}
                    disabled={!enabled}
                    title={
                      orgDisabled
                        ? "Disabled organization-wide"
                        : enabled
                          ? "Show pages for this persona"
                          : "Enable persona to manage pages"
                    }
                  >
                    <i className={expanded ? "fe fe-chevron-down" : "fe fe-chevron-right"} aria-hidden="true" />
                    <span className={classNames("lux-persona-access__avatar", meta.tone && `is-${meta.tone}`)}>
                      <i className={meta.icon} aria-hidden="true" />
                    </span>
                    <span className="lux-persona-access__item-copy">
                      <strong>{meta.label}</strong>
                      <span>
                        {orgDisabled
                          ? "Disabled at organization root"
                          : enabled
                            ? `${summary.enabled} pages allowed · ${summary.visible} visible with this role’s modules`
                            : "Disabled for this role"}
                      </span>
                    </span>
                  </button>
                  <label className="custom-switch custom-switch-sm m-0 lux-rbac-matrix-card__switch">
                    <input
                      type="checkbox"
                      className="custom-switch-input"
                      checked={enabled}
                      disabled={readOnly || saving || orgDisabled}
                      onChange={() => this.togglePersonaEnabled(code)}
                    />
                    <span className="custom-switch-indicator" />
                  </label>
                </div>
                {expanded && enabled && (
                  <div className="lux-persona-access__pages">
                    <div className="lux-persona-access__pages-toolbar">
                      <input
                        type="search"
                        className="form-control form-control-sm"
                        placeholder="Filter pages…"
                        value={pageQuery}
                        onChange={(e) => this.setState({ pageQuery: e.target.value })}
                      />
                      <span className="lux-persona-access__pages-hint">
                        {summary.blockedByModule > 0
                          ? `${summary.blockedByModule} allowed here but off via module flags`
                          : "Org page map + role modules"}
                      </span>
                    </div>
                    {this.renderPageGroups(code)}
                  </div>
                )}
              </li>
            );
          })}
        </ul>

        <div className="lux-persona-access__footer">
          <label className="lux-persona-access__field">
            <span>Default persona</span>
            <select
              className="form-control form-control-sm"
              value={personaDraft.defaultPersona || ""}
              disabled={readOnly || saving || allowedCount === 0}
              onChange={this.setDefaultPersona}
            >
              {personaDraft.allowedPersonas.map((code) => {
                const meta = getPersonaAccessMeta(code);
                return (
                  <option key={code} value={code}>
                    {meta.label}
                  </option>
                );
              })}
            </select>
          </label>
          <label className="custom-switch custom-switch-sm m-0 lux-persona-access__switch-label">
            <input
              type="checkbox"
              className="custom-switch-input"
              checked={personaDraft.personaSwitchEnabled !== false}
              disabled={readOnly || saving}
              onChange={this.setSwitchEnabled}
            />
            <span className="custom-switch-indicator" />
            <span>Allow persona switching in header</span>
          </label>
          {!readOnly && (
            <AdminActionButton
              variant="primary"
              className="lux-onb-action--sm"
              disabled={saving || allowedCount === 0 || !dirty}
              onClick={this.handleSave}
            >
              {saving ? "Saving…" : dirty ? "Save persona access" : "No changes"}
            </AdminActionButton>
          )}
        </div>
      </section>
    );
  }
}
