import React, { Component } from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { ADMIN_PAGE_META } from "config/admin-page-meta.config";
import { isAuditAdminEnabled } from "config/audit-admin.config";
import { isAuditUiEnabled } from "_helpers/audit.config";
import { auditService } from "_services/audit.service";
import { AUDIT_ACTION_TYPES, AUDIT_ENTITY_FILTER_OPTIONS, AUDIT_ENTITY_TYPES } from "_constants/audit.constants";
import { recordAuditEvent, flushBufferedAuditEvents } from "config/audit-write.service";
import { mergeBufferedAuditEvents } from "config/audit-write.utils";
import { listBufferedAuditEvents } from "config/audit-write.storage";
import {
  AUDIT_ACTION_FILTER_OPTIONS,
  AUDIT_AREA_QUICK_FILTERS,
  buildAuditActionSeries,
  buildAuditAdminInsights,
  buildAuditAdminMetrics,
  buildMockAdminAuditEvents,
  downloadAuditExportCsv,
  filterAdminAuditEvents,
  hasActiveAuditFilters,
  normalizeAdminAuditEvents,
} from "config/audit-admin.utils";
import { isMockDataEnabled } from "mock/mock.config";
import AuditTimeline from "views/common/fragments/AuditTimeline";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import AuditEventRegister from "views/admin/components/AuditEventRegister";
import PolicyAnalyticsBarChart from "views/people/components/policy/PolicyAnalyticsBarChart";
import {
  AdminActionButton,
  AdminInsightStrip,
  AdminPanelHead,
  AdminPanelLink,
  AdminLuxPage,
} from "views/admin/components/AdminLuxShared";

const DEFAULT_FILTERS = {
  entityType: "ALL",
  actionType: "ALL",
  query: "",
};

class AdminAuditPage extends Component {
  state = {
    events: [],
    loading: true,
    loadError: null,
    exporting: false,
    dataSource: null,
    filters: { ...DEFAULT_FILTERS },
    viewMode: "register",
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Audit & compliance");
    this.loadEvents();
    recordAuditEvent({
      actionType: AUDIT_ACTION_TYPES.AUDIT_VIEWED,
      entityType: AUDIT_ENTITY_TYPES.ADMIN_CONFIG,
      entityRef: "Audit & compliance",
      correlationId: `audit-view-${new Date().toISOString().slice(0, 10)}`,
      metadata: {
        route: "/admin/audit",
        viewMode: this.state.viewMode,
      },
    });
  }

  loadEvents = async () => {
    if (!isAuditUiEnabled()) {
      this.setState({ loading: false, events: [], loadError: null });
      return;
    }

    this.setState({ loading: true, loadError: null });
    try {
      await flushBufferedAuditEvents();
      const response = await auditService.getEvents({ page: 1, pageSize: 50 });
      const payload = (response && response.payload) || response;
      const rows =
        (payload && (payload.items || payload.events)) ||
        (Array.isArray(payload) ? payload : []);
      const buffered = listBufferedAuditEvents();
      const events = normalizeAdminAuditEvents(mergeBufferedAuditEvents(rows, buffered));
      if (events.length) {
        this.setState({
          events,
          loading: false,
          dataSource: "api",
          loadError: null,
        });
        return;
      }
      if (isMockDataEnabled()) {
        this.setState({
          events: buildMockAdminAuditEvents(),
          loading: false,
          dataSource: "mock",
          loadError: null,
        });
        return;
      }
      this.setState({
        events: [],
        loading: false,
        dataSource: null,
        loadError: null,
      });
    } catch (e) {
      const buffered = listBufferedAuditEvents();
      if (isMockDataEnabled()) {
        this.setState({
          events: mergeBufferedAuditEvents(buildMockAdminAuditEvents(), buffered),
          loading: false,
          dataSource: "mock",
          loadError: null,
        });
        return;
      }
      this.setState({
        loading: false,
        loadError: "Unable to load audit events.",
        events: normalizeAdminAuditEvents(buffered),
        dataSource: null,
      });
    }
  };

  handleFilterChange = (key, value) => {
    this.setState((prev) => ({
      filters: { ...prev.filters, [key]: value },
    }));
  };

  clearFilters = () => {
    this.setState({ filters: { ...DEFAULT_FILTERS } });
  };

  handleExport = async () => {
    const { filters } = this.state;
    const filteredEvents = filterAdminAuditEvents(this.state.events, filters);
    this.setState({ exporting: true });
    try {
      const blob = await auditService.exportEvents({
        entityType: filters.entityType !== "ALL" ? filters.entityType : undefined,
        query: filters.query || undefined,
      });
      if (blob) {
        const url = window.URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.href = url;
        link.download = `tracopus-audit-export-${new Date().toISOString().slice(0, 10)}.csv`;
        link.click();
        window.URL.revokeObjectURL(url);
        return;
      }
      downloadAuditExportCsv(filteredEvents);
    } catch (e) {
      downloadAuditExportCsv(filteredEvents);
    } finally {
      recordAuditEvent({
        actionType: AUDIT_ACTION_TYPES.EXPORTED,
        entityType: AUDIT_ENTITY_TYPES.ADMIN_CONFIG,
        entityRef: "Audit export",
        metadata: {
          entityType: filters.entityType,
          actionType: filters.actionType,
          resultCount: filteredEvents.length,
          hasKeywordFilter: Boolean(String(filters.query || "").trim()),
        },
      });
      this.setState({ exporting: false });
    }
  };

  render() {
    if (!isAuditAdminEnabled()) {
      return (
        <PersonaAccessDenied
          moduleName="Audit & compliance"
          reason="Admin audit search is not enabled for your organization."
        />
      );
    }

    if (!isAuditUiEnabled()) {
      return (
        <PersonaAccessDenied
          moduleName="Audit & compliance"
          reason="Audit UI is disabled for your organization."
        />
      );
    }

    const { events, loading, loadError, filters, exporting, dataSource, viewMode } = this.state;
    const filteredEvents = filterAdminAuditEvents(events, filters);
    const metrics = buildAuditAdminMetrics(events);
    const insights = loading ? [] : buildAuditAdminInsights(events, filters);
    const actionSeries = loading ? [] : buildAuditActionSeries(events);
    const filtersActive = hasActiveAuditFilters(filters);
    const quickAreaOptions = AUDIT_ENTITY_FILTER_OPTIONS.filter((option) =>
      AUDIT_AREA_QUICK_FILTERS.includes(option.value)
    );
    const selectedAreaLabel =
      (AUDIT_ENTITY_FILTER_OPTIONS.find((option) => option.value === filters.entityType) || {}).label ||
      "All areas";
    const selectedActionLabel =
      (AUDIT_ACTION_FILTER_OPTIONS.find((option) => option.value === filters.actionType) || {}).label ||
      "All actions";
    const kpiCards = [
      { id: "total", label: "Total events", value: metrics.total, hint: "Organization-wide", tone: "slate", icon: "fe fe-shield" },
      { id: "recent", label: "Last 24h", value: metrics.recent24h, hint: "Recent activity", tone: "blue", icon: "fe fe-activity" },
      { id: "actors", label: "Unique actors", value: metrics.uniqueActors, hint: "Distinct users", tone: "primary", icon: "fe fe-user" },
      { id: "approvals", label: "Approvals", value: metrics.approvals, hint: metrics.delegateActions ? `${metrics.delegateActions} delegate` : "Recorded decisions", tone: "green", icon: "fe fe-check-circle" },
    ];

    return (
      <AdminLuxPage
        pageMeta={ADMIN_PAGE_META.audit}
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        testId="page-admin-audit"
        className="lux-register-page lux-audit-admin-page"
        heroActions={
          <>
            <AdminActionButton icon="fe fe-refresh-cw" onClick={this.loadEvents} disabled={loading}>
              Refresh
            </AdminActionButton>
            <AdminActionButton
              icon="fe fe-download"
              variant="ghost"
              onClick={this.handleExport}
              disabled={exporting || filteredEvents.length === 0}
            >
              {exporting ? "Exporting…" : "Export CSV"}
            </AdminActionButton>
          </>
        }
      >
        {loadError && (
          <div className="lux-employee-360__error lux-audit-admin__error" role="alert">
            <span>{loadError}</span>
            <AdminActionButton variant="ghost" onClick={this.loadEvents}>
              Retry
            </AdminActionButton>
          </div>
        )}

        <AdminInsightStrip insights={insights} />

        {!loading && actionSeries.length > 0 && (
          <section className="lux-audit-admin-analytics lux-hrms-dash__panel">
            <AdminPanelHead title="Audit volume" subtitle="Action mix across loaded events — spot compliance hotspots." />
            <PolicyAnalyticsBarChart title="Events by action" subtitle="Top action types" series={actionSeries} />
          </section>
        )}

        <section className="lux-hrms-dash__panel lux-audit-admin-panel">
          <AdminPanelHead
            title="Audit event register"
            subtitle="Search first, then narrow by area or action — switch to timeline for day-grouped review"
            actions={<AdminPanelLink to="/admin/approval-policies">Approval policies</AdminPanelLink>}
          />

          <div className="lux-audit-admin-panel__toolbar">
            <div className="lux-audit-admin-toolbar__primary">
              <div className="lux-appr-toolbar__search lux-audit-admin-toolbar__search">
                <i className="fe fe-search" aria-hidden="true" />
                <input
                  type="search"
                  className="lux-appr-toolbar__search-input"
                  placeholder="Search actor, action, entity, or headline…"
                  value={filters.query}
                  onChange={(e) => this.handleFilterChange("query", e.target.value)}
                  data-testid="audit-search"
                />
              </div>

              <div className="lux-audit-admin-toolbar__view" role="group" aria-label="Register view">
                {[
                  { value: "register", label: "Register", icon: "fe fe-list" },
                  { value: "timeline", label: "Timeline", icon: "fe fe-clock" },
                ].map((option) => (
                  <button
                    key={option.value}
                    type="button"
                    className={classNames("lux-audit-admin-toolbar__view-btn", {
                      "is-active": viewMode === option.value,
                    })}
                    onClick={() => this.setState({ viewMode: option.value })}
                    aria-pressed={viewMode === option.value}
                  >
                    <i className={option.icon} aria-hidden="true" />
                    {option.label}
                  </button>
                ))}
              </div>

              <span className="lux-appr-toolbar__count">
                <strong>{filteredEvents.length}</strong> event{filteredEvents.length === 1 ? "" : "s"}
              </span>
            </div>

            <div className="lux-audit-admin-toolbar__controls">
              <label className="lux-audit-admin-toolbar__field">
                <span className="lux-audit-admin-toolbar__field-label">
                  <i className="fe fe-grid" aria-hidden="true" /> Area
                </span>
                <select
                  className="lux-audit-admin-toolbar__select"
                  value={filters.entityType}
                  onChange={(e) => this.handleFilterChange("entityType", e.target.value)}
                  data-testid="audit-filter-area"
                >
                  {AUDIT_ENTITY_FILTER_OPTIONS.map((option) => (
                    <option key={option.value} value={option.value}>
                      {option.label}
                    </option>
                  ))}
                </select>
              </label>

              <label className="lux-audit-admin-toolbar__field">
                <span className="lux-audit-admin-toolbar__field-label">
                  <i className="fe fe-zap" aria-hidden="true" /> Action
                </span>
                <select
                  className="lux-audit-admin-toolbar__select"
                  value={filters.actionType}
                  onChange={(e) => this.handleFilterChange("actionType", e.target.value)}
                  data-testid="audit-filter-action"
                >
                  {AUDIT_ACTION_FILTER_OPTIONS.map((option) => (
                    <option key={option.value} value={option.value}>
                      {option.label}
                    </option>
                  ))}
                </select>
              </label>

              <button
                type="button"
                className="lux-audit-admin-panel__export-btn"
                onClick={this.handleExport}
                disabled={exporting || filteredEvents.length === 0}
              >
                <i className="fe fe-download" aria-hidden="true" />
                {exporting ? "Exporting…" : "Export CSV"}
              </button>
            </div>

            <div className="lux-audit-admin-toolbar__quick">
              <span className="lux-audit-admin-toolbar__quick-label">Quick areas</span>
              <div className="lux-hrms-dash__filter-group">
                {quickAreaOptions.map((option) => (
                  <button
                    key={option.value}
                    type="button"
                    className={classNames("lux-hrms-dash__filter-chip", {
                      "is-active": filters.entityType === option.value,
                    })}
                    onClick={() => this.handleFilterChange("entityType", option.value)}
                  >
                    {option.label}
                  </button>
                ))}
              </div>
            </div>

            {filtersActive ? (
              <div className="lux-audit-admin-toolbar__active" aria-live="polite">
                <span className="lux-audit-admin-toolbar__active-label">Active filters</span>
                <div className="lux-audit-admin-toolbar__pills">
                  {filters.entityType !== "ALL" ? (
                    <button
                      type="button"
                      className="lux-audit-admin-toolbar__pill"
                      onClick={() => this.handleFilterChange("entityType", "ALL")}
                      title="Clear area filter"
                    >
                      Area: {selectedAreaLabel}
                      <i className="fe fe-x" aria-hidden="true" />
                    </button>
                  ) : null}
                  {filters.actionType !== "ALL" ? (
                    <button
                      type="button"
                      className="lux-audit-admin-toolbar__pill"
                      onClick={() => this.handleFilterChange("actionType", "ALL")}
                      title="Clear action filter"
                    >
                      Action: {selectedActionLabel}
                      <i className="fe fe-x" aria-hidden="true" />
                    </button>
                  ) : null}
                  {String(filters.query || "").trim() ? (
                    <button
                      type="button"
                      className="lux-audit-admin-toolbar__pill"
                      onClick={() => this.handleFilterChange("query", "")}
                      title="Clear search"
                    >
                      Search: “{String(filters.query).trim()}”
                      <i className="fe fe-x" aria-hidden="true" />
                    </button>
                  ) : null}
                </div>
                <button
                  type="button"
                  className="lux-audit-admin-toolbar__clear"
                  onClick={this.clearFilters}
                  data-testid="audit-clear-filters"
                >
                  Clear all
                </button>
              </div>
            ) : null}
          </div>

          <div className="lux-hrms-dash__panel-body">
            {loading ? (
              <LuxRegisterEmptyState
                className="lux-register-empty--compact"
                title="Loading audit events"
                description="Fetching organization audit timeline."
              />
            ) : filteredEvents.length === 0 ? (
              <LuxRegisterEmptyState
                className="lux-register-empty--compact"
                icon="fe fe-shield"
                title="No audit events match"
                description="Clear filters or broaden your search to see more events."
              />
            ) : viewMode === "timeline" ? (
              <AuditTimeline events={filteredEvents} loading={false} />
            ) : (
              <AuditEventRegister events={filteredEvents} />
            )}
          </div>
        </section>
      </AdminLuxPage>
    );
  }
}

export default AdminAuditPage;
