import React from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";

export default function AnalyticsDrilldownStrip({ metrics = [] }) {
  const drilldowns = metrics.filter((row) => row.drilldownPath).slice(0, 8);

  if (!drilldowns.length) {
    return null;
  }

  return (
    <div className="lux-analytics-drilldown">
      <div className="lux-analytics-drilldown__head">
        <span className="lux-analytics-drilldown__label">Metric drill-down</span>
        <span className="lux-analytics-drilldown__count">{drilldowns.length} linked routes</span>
      </div>
      <div className="lux-analytics-drilldown__grid">
        {drilldowns.map((row) => (
          <Link key={row.id} to={row.drilldownPath} className={classNames("lux-analytics-drilldown__card")}>
            <span className="lux-analytics-drilldown__card-icon" aria-hidden="true">
              <i className="fe fe-external-link" />
            </span>
            <strong>{row.label}</strong>
            <small>{row.sourceModule || row.domain || "Module"}</small>
          </Link>
        ))}
      </div>
    </div>
  );
}
