import React, { Component } from "react";
import classNames from "classnames/bind";

class PurchaseOrderDetailsHeader extends Component {
  renderTab = (id, label, icon) => {
    const active = this.props.selectedMenu === id;
    return (
      <button
        type="button"
        className={classNames("lux-po-detail-tabs__tab", { "is-active": active })}
        onClick={() => this.props.onSelectMenu(id)}
        aria-current={active ? "page" : undefined}
      >
        <i className={`fe ${icon}`} aria-hidden="true" />
        {label}
      </button>
    );
  };

  render() {
    return (
      <nav className="lux-po-detail-tabs" aria-label="Purchase contract sections">
        {this.renderTab("details", "Details", "fe-file-text")}
        {this.renderTab("projects", "Projects", "fe-folder")}
      </nav>
    );
  }
}

export default PurchaseOrderDetailsHeader;
