import React, { Component } from "react";
import CustomInput from "views/common/fragments/formfields/CustomInput";

class ProfileExitDateAdmin extends Component {
  constructor(props) {
    super(props);
    this.state = {
      exitDate: props.employee && props.employee.exitDate,
      enabled: false,
      formErrors: {},
    };
  }

  componentDidUpdate(prevProps) {
    if (prevProps.employee !== this.props.employee && this.props.employee) {
      this.setState({ exitDate: this.props.employee.exitDate, enabled: false });
    }
  }

  onChange = (fieldName, value) => {
    if (fieldName === "exitDate") {
      this.setState({ exitDate: value, enabled: true });
    }
  };

  onFormError = () => {};

  handleUpdate = () => {
    if (this.props.onUpdate && this.props.employee) {
      this.props.onUpdate(this.props.employee.id, this.state.exitDate);
      this.setState({ enabled: false });
    }
  };

  render() {
    const { employee, fieldConfig } = this.props;
    if (!employee) return null;

    const mappingObject = { ...employee, exitDate: this.state.exitDate };

    return (
      <section className="profile-exit-admin">
        <header className="profile-exit-admin__head">
          <i className="fe fe-log-out" aria-hidden="true" />
          <div>
            <strong>Exit date administration</strong>
            <span>Update separation date for this employee record</span>
          </div>
        </header>
        <div className="profile-exit-admin__body">
          <CustomInput
            className="colorRed"
            type="dateselect"
            label="Exit date"
            name="exitDate"
            fieldConfig={fieldConfig}
            mappingObject={mappingObject}
            onChange={this.onChange}
            time={false}
            onFormError={this.onFormError}
            minDate={new Date(2022, 0, 1)}
            maxDate={new Date(2050, 0, 1)}
            currentDate={new Date()}
          />
          <button
            type="button"
            className="profile-exit-admin__btn"
            disabled={!this.state.enabled}
            onClick={this.handleUpdate}
          >
            Update exit date
          </button>
        </div>
      </section>
    );
  }
}

export default ProfileExitDateAdmin;
