import React from "react";
import classNames from "classnames/bind";
import {
  MASKING_LEVELS,
  MASKING_LEVEL_LABELS,
  MASKING_PERSONAS,
} from "config/masking-policy.config";
import { getMaskingDomainMeta } from "config/masking-policy.utils";
import { getPersonaMeta } from "config/role-permission.utils";

const LEVEL_OPTIONS = [
  MASKING_LEVELS.VISIBLE,
  MASKING_LEVELS.MASKED,
  MASKING_LEVELS.HIDDEN,
];

export default function MaskingPolicyDetailPanel({ rule, savingKey, onSetLevel }) {
  if (!rule) {
    return (
      <div className="lux-mask-detail lux-mask-detail--empty">
        <span className="lux-mask-detail__empty-icon" aria-hidden="true">
          <i className="fe fe-eye-off" />
        </span>
        <strong>Select a field rule</strong>
        <p>Configure persona visibility for sensitive Employee 360, payroll, and export surfaces.</p>
      </div>
    );
  }

  const meta = getMaskingDomainMeta(rule.domain);

  return (
    <aside className="lux-mask-detail">
      <header className="lux-mask-detail__head">
        <div className="lux-mask-detail__identity">
          <span className={classNames("lux-mask-detail__avatar", meta.tone && `is-${meta.tone}`)} aria-hidden="true">
            <i className={meta.icon} />
          </span>
          <div>
            <h3>{rule.name}</h3>
            <p>
              {rule.fieldKey} · {rule.domain} · {rule.owner}
            </p>
          </div>
        </div>
        <span className={classNames("lux-mask-detail__risk", `is-${rule.risk}`)}>{rule.risk} risk</span>
      </header>

      <p className="lux-mask-detail__copy">{rule.description}</p>

      <dl className="lux-mask-detail__meta">
        <div>
          <dt>Export policy</dt>
          <dd>{rule.exportRestricted ? MASKING_LEVEL_LABELS[rule.exportLevel] || "Restricted" : "Not restricted"}</dd>
        </div>
        <div>
          <dt>MaskedField key</dt>
          <dd>{rule.fieldKey}</dd>
        </div>
      </dl>

      <div className="lux-mask-detail__matrix-head">
        <h4>Persona visibility</h4>
        <span>{MASKING_PERSONAS.length} personas</span>
      </div>

      <ul className="lux-mask-detail__personas" role="list">
        {MASKING_PERSONAS.map((persona) => {
          const personaMeta = getPersonaMeta(persona);
          const currentLevel = (rule.levels && rule.levels[persona]) || MASKING_LEVELS.VISIBLE;
          const rowKey = `${rule.id}:${persona}`;
          return (
            <li key={persona} className="lux-mask-detail__persona" role="listitem">
              <div className="lux-mask-detail__persona-copy">
                <span className={classNames("lux-mask-detail__persona-icon", personaMeta.tone && `is-${personaMeta.tone}`)}>
                  <i className={personaMeta.icon} aria-hidden="true" />
                </span>
                <span>
                  <strong>{personaMeta.label}</strong>
                  <em>{persona}</em>
                </span>
              </div>
              <div className="lux-mask-detail__level-group" role="group" aria-label={`${personaMeta.label} visibility`}>
                {LEVEL_OPTIONS.map((level) => (
                  <button
                    key={level}
                    type="button"
                    className={classNames("lux-mask-detail__level-btn", `is-${level.toLowerCase()}`, {
                      "is-active": currentLevel === level,
                    })}
                    disabled={savingKey === rowKey}
                    onClick={() => onSetLevel && onSetLevel(persona, level)}
                  >
                    {MASKING_LEVEL_LABELS[level]}
                  </button>
                ))}
              </div>
            </li>
          );
        })}
      </ul>
    </aside>
  );
}
