import { axiosUtils } from "../_helpers";
import { commonUtils } from "../_helpers/common.utils";
import urlConfig from "url.config";
import { normalizeApprovalPolicy } from "config/approval-policy.config";

import { apiErrorResult } from "config/mock-fallback.utils";

export const approvalPolicyService = {
  listPolicies,
  savePolicy,
  updatePolicy,
};

async function listPoliciesFromApi() {
  const response = await axiosUtils.getWithParam(`${urlConfig.APPROVALS_API_PATH}/policies`, {
    userTeamId: commonUtils.getCurrentUserTeamId(),
  });
  const rows = (response && response.payload) || response || [];
  const list = Array.isArray(rows) ? rows : [];
  return {
    payload: list.map((row) => normalizeApprovalPolicy(row)).filter(Boolean),
    source: "api",
  };
}

async function listPolicies() {
  try {
    return await listPoliciesFromApi();
  } catch (e) {
    return apiErrorResult([]);
  }
}

async function savePolicy(payload) {
  const userTeamId = commonUtils.getCurrentUserTeamId();
  const actorId = commonUtils.getCurrentUserId();
  const response = await axiosUtils.post(
    `${urlConfig.APPROVALS_API_PATH}/policies?userTeamId=${userTeamId}&actorId=${actorId}&adminPersona=true`,
    payload || {}
  );
  const row = (response && response.payload) || response;
  return {
    payload: normalizeApprovalPolicy(row),
    source: "api",
  };
}

async function updatePolicy(policyId, payload) {
  const userTeamId = commonUtils.getCurrentUserTeamId();
  const actorId = commonUtils.getCurrentUserId();
  const response = await axiosUtils.patch(
    `${urlConfig.APPROVALS_API_PATH}/policies/${encodeURIComponent(policyId)}?userTeamId=${userTeamId}&actorId=${actorId}&adminPersona=true`,
    payload || {}
  );
  const row = (response && response.payload) || response;
  return {
    payload: normalizeApprovalPolicy(row),
    source: "api",
  };
}
