import React from 'react';
import { connect } from 'react-redux';
import { withRouter } from 'react-router-dom';
import { leavePhase2Service as api } from '_services/leavePhase2.service';
import { getApiErrorMessage } from '_helpers/apiError.utils';
import { AdminActionButton } from 'views/admin/components/AdminLuxShared';
import {
  LeavePhase2AdminBase,
  LeavePhase2Panel,
  LeavePhase2Register,
  LEAVE_PHASE2_EMPTY_DESCRIPTION,
  mapLeavePhase2State,
  renderLeavePhase2Nav,
  cell,
} from './leavePhase2.shared';
import '../leaveLuxForms.css';

const NAV = [
  { path: '/admin/leave/anomaly-rules', label: 'Rules', icon: 'fe fe-shield', exact: true },
  { path: '/admin/leave/anomaly-review', label: 'Flags & review', icon: 'fe fe-flag' },
  { path: '/admin/leave/fairness-analytics', label: 'Fairness', icon: 'fe fe-bar-chart-2' },
];

const EMPTY_RULE = { name: '', ruleType: 'REPEAT_PATTERN', severity: 'MEDIUM' };

function sectionFromPath(pathname) {
  if (pathname.includes('anomaly-review')) return 'flags';
  if (pathname.includes('fairness-analytics')) return 'fairness';
  return 'rules';
}

class LeaveAnomalyPage extends LeavePhase2AdminBase {
  state = {
    ...this.state,
    rules: [],
    flags: [],
    snapshots: [],
    saving: false,
    ruleForm: { ...EMPTY_RULE },
  };

  fetchSectionData = async (teamId) => {
    const section = sectionFromPath(this.props.location.pathname);
    if (section === 'rules') {
      const rules = (await api.listAnomalyRules(teamId)) || [];
      this.setState({ rules: Array.isArray(rules) ? rules : [] });
      return;
    }
    if (section === 'flags') {
      const flags = (await api.listAnomalyFlags(teamId)) || [];
      this.setState({ flags: Array.isArray(flags) ? flags : [] });
      return;
    }
    const snapshots = (await api.listFairnessSnapshots(teamId)) || [];
    this.setState({ snapshots: Array.isArray(snapshots) ? snapshots : [] });
  };

  saveRule = (event) => {
    event.preventDefault();
    const { ruleForm } = this.state;
    const name = (ruleForm.name || '').trim();
    if (!name) return;
    const teamId = this.teamId();
    if (!teamId) {
      this.setState({ error: 'Select a team first.' });
      return;
    }
    this.setState({ saving: true, error: null, notice: null });
    api
      .saveAnomalyRule({
        userTeamId: teamId,
        actorId: this.actorId(),
        name,
        ruleType: ruleForm.ruleType || 'REPEAT_PATTERN',
        severity: ruleForm.severity || 'MEDIUM',
        active: true,
      })
      .then(() => {
        this.setState({
          saving: false,
          notice: 'Anomaly rule saved (advisory only — never auto-rejects leave).',
          ruleForm: { ...EMPTY_RULE },
        });
        return this.loadAll();
      })
      .catch((e) => {
        this.setState({
          saving: false,
          error: getApiErrorMessage(e, 'Could not save rule.'),
        });
      });
  };

  render() {
    const { loading, rules, flags, snapshots, ruleForm, saving } = this.state;
    const section = sectionFromPath(this.props.location.pathname);
    const kpiCards = [
      { id: 'rules', label: 'Rules', value: rules.length, tone: 'primary', icon: 'fe fe-shield' },
      { id: 'flags', label: 'Flags', value: flags.length, tone: 'amber', icon: 'fe fe-flag' },
      { id: 'fair', label: 'Snapshots', value: snapshots.length, tone: 'blue', icon: 'fe fe-bar-chart-2' },
    ];

    return this.renderChrome({
      testId: 'page-leave-anomaly',
      kpiCards,
      pageMeta: {
        tone: 'emerald',
        icon: 'fe fe-shield',
        eyebrow: 'Admin · Leave',
        titleLead: 'Anomaly',
        titleAccent: 'intelligence',
        lede: 'Advisory anomaly rules and fairness snapshots — never auto-reject leave. Add rules below.',
      },
      heroNav: renderLeavePhase2Nav(NAV, this.props.location.pathname),
      children: (
        <>
          {section === 'rules' && (
            <>
              <LeavePhase2Panel title="Add anomaly rule" subtitle="Flags for HR review only.">
                <form className="lux-glp-form" onSubmit={this.saveRule} data-testid="glp23-add-rule-form">
                  <label>
                    Name
                    <input
                      required
                      value={ruleForm.name}
                      onChange={(e) => this.setState({ ruleForm: { ...ruleForm, name: e.target.value } })}
                      placeholder="Repeat Monday pattern"
                    />
                  </label>
                  <label>
                    Rule type
                    <input
                      value={ruleForm.ruleType}
                      onChange={(e) =>
                        this.setState({ ruleForm: { ...ruleForm, ruleType: e.target.value } })
                      }
                      placeholder="REPEAT_PATTERN"
                    />
                  </label>
                  <label>
                    Severity
                    <select
                      value={ruleForm.severity}
                      onChange={(e) =>
                        this.setState({ ruleForm: { ...ruleForm, severity: e.target.value } })
                      }
                    >
                      <option value="LOW">Low</option>
                      <option value="MEDIUM">Medium</option>
                      <option value="HIGH">High</option>
                    </select>
                  </label>
                  <div className="lux-glp-form__actions">
                    <AdminActionButton type="submit" icon="fe fe-plus" disabled={saving || loading}>
                      Save rule
                    </AdminActionButton>
                  </div>
                </form>
              </LeavePhase2Panel>
              <LeavePhase2Panel
                title="Anomaly rules"
                subtitle="Repeat/peak-period flags with protected-attribute guardrails."
              >
                <LeavePhase2Register
                  loading={loading}
                  rows={rules}
                  testId="glp23-rules-register"
                  emptyTitle="No anomaly rules"
                  emptyDescription={LEAVE_PHASE2_EMPTY_DESCRIPTION}
                  columns={[
                    { key: 'id', label: 'ID' },
                    { key: 'name', label: 'Name' },
                    { key: 'ruleType', label: 'Type' },
                    { key: 'severity', label: 'Severity' },
                    { key: 'active', label: 'Active' },
                  ]}
                />
              </LeavePhase2Panel>
            </>
          )}
          {section === 'flags' && (
            <LeavePhase2Panel title="Flags & HR review" subtitle="Explainable flags awaiting human review — no automatic rejection.">
              <LeavePhase2Register
                loading={loading}
                rows={flags}
                testId="glp23-flags-register"
                emptyTitle="No anomaly flags"
                emptyDescription={LEAVE_PHASE2_EMPTY_DESCRIPTION}
                columns={[
                  { key: 'id', label: 'Flag' },
                  { key: 'employeeId', label: 'Employee' },
                  { key: 'ruleId', label: 'Rule' },
                  { key: 'status', label: 'Status' },
                  { key: 'explanation', label: 'Explanation', render: (r) => cell(r.explanation || r.maskedExplanation) },
                ]}
              />
            </LeavePhase2Panel>
          )}
          {section === 'fairness' && (
            <LeavePhase2Panel title="Fairness analytics" subtitle="Team-level fairness snapshots without protected attributes.">
              <LeavePhase2Register
                loading={loading}
                rows={snapshots}
                testId="glp23-fairness-register"
                emptyTitle="No fairness snapshots"
                emptyDescription={LEAVE_PHASE2_EMPTY_DESCRIPTION}
                columns={[
                  { key: 'id', label: 'Snapshot' },
                  { key: 'periodLabel', label: 'Period', render: (r) => cell(r.periodLabel || r.period) },
                  { key: 'fairnessScore', label: 'Score' },
                  { key: 'generatedAt', label: 'Generated' },
                ]}
              />
            </LeavePhase2Panel>
          )}
        </>
      ),
    });
  }
}

export default connect(mapLeavePhase2State)(withRouter(LeaveAnomalyPage));
