import React, { useEffect } from "react";
import { useReportPageDataSource } from "views/common/PageChromeContext";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import { AdminInsightStrip } from "views/admin/components/AdminLuxShared";
import AdminHubTabs, { WORKFLOW_HUB_TABS } from "views/admin/components/AdminHubTabs";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import { GovernanceKpiStrip } from "views/project/components/ProjectGovernanceLuxShared";

export default function WorkflowLuxPage({
  pageMeta,
  dataSource,
  demoLabel = "Demo workflow data",
  heroActions,
  kpiCards,
  loading,
  pageHeaderNameChangeHandler,
  shellTitle,
  children,
}) {
  useReportPageDataSource(dataSource);
  const meta = pageMeta || {
    tone: "violet",
    icon: "fe fe-git-branch",
    eyebrow: "Admin",
    titleLead: "Workflow",
    titleAccent: "automation",
    lede: "Configure enterprise workflow rules.",
  };

  useEffect(() => {
    if (pageHeaderNameChangeHandler && shellTitle) {
      pageHeaderNameChangeHandler(shellTitle);
    }
  }, [pageHeaderNameChangeHandler, shellTitle]);

  return (
    <div className={classNames("lux-register-page", "lux-wf-module", "lux-wf-lux", meta.tone && `is-${meta.tone}`)}>
      <div className="lux-wf-lux__ambient" aria-hidden="true">
        <span className="lux-wf-lux__orb lux-wf-lux__orb--a" />
        <span className="lux-wf-lux__orb lux-wf-lux__orb--b" />
        <span className="lux-wf-lux__orb lux-wf-lux__orb--c" />
      </div>
      <LuxModuleIntro
        meta={meta}
        actions={heroActions || undefined}
        nav={<AdminHubTabs tabs={WORKFLOW_HUB_TABS} ariaLabel="Workflow automation sections" />}
      />
      <div className="lux-register-page__body">
        {kpiCards && kpiCards.length ? (
          <GovernanceKpiStrip cards={kpiCards} loading={loading} className="lux-wf-lux__kpi-strip" />
        ) : null}

        <div className="lux-wf-lux__content">{children}</div>
      </div>
    </div>
  );
}

export function WorkflowActionButton({ to, onClick, icon, variant = "ghost", children, disabled, className }) {
  const classes = classNames("lux-onb-action", "lux-wf-action", `lux-onb-action--${variant}`, className);
  const content = icon ? (
    <>
      <i className={icon} aria-hidden="true" />
      <span>{children}</span>
    </>
  ) : (
    children
  );
  if (to && !onClick) {
    return (
      <Link to={to} className={classes}>
        {content}
      </Link>
    );
  }
  return (
    <button type="button" className={classes} onClick={onClick} disabled={disabled}>
      {content}
    </button>
  );
}

export function WorkflowLuxPanel({ title, meta, icon, accent, featured, actions, children, className }) {
  return (
    <section
      className={classNames(
        "lux-hrms-dash__panel",
        "lux-wf-lux__panel",
        accent && `is-${accent}`,
        featured && "lux-wf-lux__panel--featured",
        className
      )}
    >
      <header className="lux-hrms-dash__panel-head lux-wf-lux__panel-head">
        <div className="lux-wf-lux__panel-head-main">
          {icon ? <i className={icon} aria-hidden="true" /> : null}
          <div>
            <h2 className="lux-hrms-dash__panel-title">{title}</h2>
            {meta ? <p className="lux-hrms-dash__panel-sub">{meta}</p> : null}
          </div>
        </div>
        {actions ? <div className="lux-hrms-dash__panel-actions lux-wf-lux__panel-actions">{actions}</div> : null}
      </header>
      <div className="lux-hrms-dash__panel-body lux-wf-lux__panel-body">{children}</div>
    </section>
  );
}

export function WorkflowInsightPanel({ insights, loading }) {
  return <AdminInsightStrip insights={insights} loading={loading} className="lux-wf-lux__insights" />;
}

export function WorkflowStatusBadge({ status }) {
  const label = status === "in_review" ? "In review" : status;
  return <span className={classNames("lux-wf-badge", `lux-wf-badge--${status || "draft"}`)}>{label}</span>;
}

export function WorkflowRunStatusBadge({ status }) {
  return <span className={classNames("lux-wf-badge", "lux-wf-badge--run", `lux-wf-badge--${status || "running"}`)}>{status}</span>;
}
