import React, { Component } from "react";
import { connect } from "react-redux";
import { accessUtils } from "_helpers";
import BidRequestsDetailsGeneral from "../BidRequestsDetailsGeneral";
import LuxCreatePanelShell from "views/common/create/LuxCreatePanelShell";
import LuxDetailPageSkeleton from "views/common/fragments/LuxDetailPageSkeleton";

class ViewBidRequestsDetailsSidebar extends Component {
  constructor() {
    super();
    this.state = {
      permission: accessUtils.getBidRequestsAccessControl(),
    };
  }

  render() {
    const item = this.props.bidRequestsInfo;

    return (
      <LuxCreatePanelShell
        show={this.props.show}
        onClose={this.props.onCloseViewBidRequests}
        panelId="viewBidRequestSidebar"
        className="lux-create-panel--bid view_bid_request_right_sidebar"
        kicker="Sales workspace"
        title={item ? item.studyName : "Bid request"}
        subtitle={item ? "Read-only bid details" : undefined}
      >
        {this.props.show && !item && (
          <LuxDetailPageSkeleton ariaLabel="Loading bid request" className="lux-bid-detail__view-skeleton" />
        )}
        {this.props.show && item && (
          <div className="lux-create-panel__scroll lux-bid-detail__view-body">
            <BidRequestsDetailsGeneral
              item={item}
              readOnly={true}
              permission={this.state.permission}
              compactView
            />
          </div>
        )}
      </LuxCreatePanelShell>
    );
  }
}

const mapStateToProps = (state) => ({
  bidRequestsInfo: state.bidRequests.selectedBidRequestsInfo,
});

export default connect(mapStateToProps)(ViewBidRequestsDetailsSidebar);
