export function minsToHoursLabel(mins) {
  const m = Number(mins) || 0;
  if (m <= 0) return "0h";
  const h = Math.floor(m / 60);
  const r = m % 60;
  return r > 0 ? `${h}h ${r}m` : `${h}h`;
}

export function computeWeeklyUtilization(utilization, standardWeekMins = 40 * 60) {
  if (!utilization) return { totalMins: 0, leaveMins: 0, utilizationPct: 0 };
  const totalMins =
    (utilization.billableMins || 0) +
    (utilization.nonBillableMins || 0) +
    (utilization.leaveMins || 0) +
    (utilization.holidayMins || 0);
  const leaveMins = (utilization.leaveMins || 0) + (utilization.holidayMins || 0);
  const workMins = Math.max(0, totalMins - leaveMins);
  const utilizationPct = Math.min(100, Math.round((workMins / standardWeekMins) * 100));
  return { totalMins, leaveMins, utilizationPct };
}

export function summarizeTaskStatuses(items) {
  const list = Array.isArray(items) ? items : [];
  const counts = {
    total: list.length,
    inProgress: 0,
    assigned: 0,
    newTasks: 0,
    paused: 0,
  };
  list.forEach((item) => {
    const status = (item.status || "").toUpperCase();
    if (status === "INPROGRESS") counts.inProgress += 1;
    else if (status === "ASSIGNED") counts.assigned += 1;
    else if (status === "NEW") counts.newTasks += 1;
    else if (status === "PAUSED") counts.paused += 1;
  });
  return counts;
}

export function getTaskStatusMeta(status) {
  const s = (status || "").toUpperCase();
  if (s === "INPROGRESS") return { label: "In progress", className: "is-progress" };
  if (s === "ASSIGNED") return { label: "Assigned", className: "is-assigned" };
  if (s === "PAUSED") return { label: "Paused", className: "is-paused" };
  if (s === "NEW") return { label: "New", className: "is-new" };
  if (s === "COMPLETED" || s === "CLOSED") return { label: "Done", className: "is-done" };
  return { label: s || "Open", className: "is-new" };
}
