import React from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import {
  formatPayrollCurrency,
  formatPayrollDate,
  getPayrollRunStatusTone,
} from "config/payroll.utils";
import { PayrollStatusBadge } from "views/payroll/components/PayrollLuxShared";

function getInitials(name = "") {
  return name
    .split(" ")
    .filter(Boolean)
    .map((part) => part[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();
}

export function PayrollRegisterWrap({ children, className }) {
  return <div className={classNames("lux-payroll-register-wrap", className)}>{children}</div>;
}

export function PayrollRegisterOpen({ to, label }) {
  return (
    <Link to={to} className="lux-payroll-register__open" aria-label={label}>
      <i className="fe fe-chevron-right" aria-hidden="true" />
    </Link>
  );
}

export function PayrollRegisterPrimaryCell({
  icon,
  iconTone = "primary",
  initials,
  title,
  meta,
  to,
  linkLabel,
}) {
  const titleNode = (
    <strong className="lux-payroll-register__primary-title">{title}</strong>
  );

  const content = (
    <>
      <span className={classNames("lux-payroll-register__avatar", iconTone && `is-${iconTone}`)} aria-hidden="true">
        {icon ? <i className={icon} /> : initials}
      </span>
      <span className="lux-payroll-register__primary-copy">
        {titleNode}
        {meta && <span className="lux-payroll-register__primary-meta">{meta}</span>}
        {to && linkLabel && (
          <Link to={to} className="lux-payroll-register__inline-link">{linkLabel}</Link>
        )}
      </span>
    </>
  );

  if (to && !linkLabel) {
    return (
      <Link to={to} className="lux-payroll-register__primary">
        {content}
      </Link>
    );
  }

  return <div className="lux-payroll-register__primary">{content}</div>;
}

export function PayrollReadinessCell({ score }) {
  if (score == null) {
    return <span className="lux-payroll-readiness-pill is-slate">—</span>;
  }
  const tone = score >= 95 ? "is-high" : score >= 80 ? "is-mid" : "is-low";
  return <span className={classNames("lux-payroll-readiness-pill", tone)}>{score}%</span>;
}

export function PayrollMoneyCell({ value, muted }) {
  return (
    <span className={classNames("lux-payroll-register__money", { "is-muted": muted })}>
      {formatPayrollCurrency(value)}
    </span>
  );
}

export function PayrollRunsRegister({ rows }) {
  return (
    <PayrollRegisterWrap>
      <table className="lux-payroll-register">
        <thead>
          <tr>
            <th>Run</th>
            <th>Group</th>
            <th>Period</th>
            <th>Pay date</th>
            <th>Employees</th>
            <th>Gross</th>
            <th>Readiness</th>
            <th>Exceptions</th>
            <th>Status</th>
            <th aria-hidden="true" />
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => (
            <tr
              key={row.id}
              className={classNames("lux-payroll-register__row", {
                "is-attention": (row.exceptionCount || 0) > 0 || row.readinessScore < 80,
              })}
            >
              <td>
                <PayrollRegisterPrimaryCell
                  icon="fe fe-layers"
                  iconTone={getPayrollRunStatusTone(row.status) === "success" ? "green" : "primary"}
                  title={row.name}
                  meta={`Updated ${formatPayrollDate(row.updatedAt)}`}
                  to={`/payroll/runs/${row.id}${row.userTeamId != null ? `?userTeamId=${encodeURIComponent(row.userTeamId)}` : ""}`}
                />
              </td>
              <td>
                <span className="lux-payroll-register__chip">
                  <i className="fe fe-users" aria-hidden="true" />
                  {row.groupName}
                </span>
              </td>
              <td><span className="lux-payroll-register__date">{formatPayrollDate(row.periodStart)} – {formatPayrollDate(row.periodEnd)}</span></td>
              <td><span className="lux-payroll-register__date">{formatPayrollDate(row.payDate)}</span></td>
              <td><span className="lux-payroll-register__count">{row.employeeCount}</span></td>
              <td><PayrollMoneyCell value={row.grossTotal} /></td>
              <td><PayrollReadinessCell score={row.readinessScore} /></td>
              <td>
                <span className={classNames("lux-payroll-register__exception", {
                  "is-clear": !row.exceptionCount,
                  "is-warning": row.exceptionCount > 0,
                })}
                >
                  {row.exceptionCount || 0}
                </span>
              </td>
              <td><PayrollStatusBadge status={row.status} /></td>
              <td><PayrollRegisterOpen to={`/payroll/runs/${row.id}${row.userTeamId != null ? `?userTeamId=${encodeURIComponent(row.userTeamId)}` : ""}`} label={`Open ${row.name}`} /></td>
            </tr>
          ))}
        </tbody>
      </table>
    </PayrollRegisterWrap>
  );
}

