export function PayrollLinesRegister({ lines }) {
  return (
    <PayrollRegisterWrap>
      <table className="lux-payroll-register">
        <thead>
          <tr>
            <th>Employee</th>
            <th>Department</th>
            <th>Gross</th>
            <th>Deductions</th>
            <th>Net</th>
            <th>Status</th>
            <th aria-hidden="true" />
          </tr>
        </thead>
        <tbody>
          {lines.map((row) => (
            <tr
              key={row.id}
              className={classNames("lux-payroll-register__row", { "is-attention": row.status === "Exception" })}
            >
              <td>
                <PayrollRegisterPrimaryCell
                  initials={getInitials(row.employeeName)}
                  iconTone={row.status === "Exception" ? "amber" : "green"}
                  title={row.employeeName}
                  meta={row.employeeId ? "Employee profile" : null}
                  to={row.employeeId ? `/people/employees/${row.employeeId}/360` : null}
                  linkLabel={row.employeeId ? "View 360" : null}
                />
              </td>
              <td><span className="lux-payroll-register__chip is-slate">{row.department || "Unassigned"}</span></td>
              <td><PayrollMoneyCell value={row.gross} /></td>
              <td><PayrollMoneyCell value={row.deductions} muted /></td>
              <td><PayrollMoneyCell value={row.net} /></td>
              <td>
                <span className={classNames("lux-doc-badge", {
                  "is-warning": row.status === "Exception",
                  "is-success": row.status !== "Exception",
                })}
                >
                  {row.status}
                </span>
              </td>
              <td>
                {row.employeeId ? (
                  <PayrollRegisterOpen to={`/people/employees/${row.employeeId}/360`} label={`View ${row.employeeName}`} />
                ) : (
                  <span className="lux-payroll-register__open is-disabled" aria-hidden="true" />
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </PayrollRegisterWrap>
  );
}

