export function PayrollExceptionsRegister({ exceptions }) {
  const rows = (exceptions || []).filter((row) => !row.resolved);
  return (
    <PayrollRegisterWrap>
      <table className="lux-payroll-register">
        <thead>
          <tr>
            <th>Employee</th>
            <th>Issue</th>
            <th>Category</th>
            <th>Severity</th>
            <th>Run</th>
            <th aria-hidden="true" />
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => (
            <tr
              key={row.id}
              className={classNames("lux-payroll-register__row", {
                "is-attention": row.severity === "Blocker",
              })}
            >
              <td>
                <PayrollRegisterPrimaryCell
                  initials={getInitials(row.employeeName || "GE")}
                  iconTone={row.severity === "Blocker" ? "amber" : "primary"}
                  title={row.employeeName || "General"}
                  meta={row.category || "Payroll exception"}
                />
              </td>
              <td>
                <strong className="lux-payroll-register__issue-code">{row.code}</strong>
                {row.message && <span className="lux-payroll-register__primary-meta">{row.message}</span>}
              </td>
              <td><span className="lux-payroll-register__chip is-slate">{row.category || "—"}</span></td>
              <td>
                <span className={classNames("lux-doc-badge", {
                  "is-danger": row.severity === "Blocker",
                  "is-warning": row.severity === "Warning",
                })}
                >
                  {row.severity}
                </span>
              </td>
              <td>
                {row.runId ? (
                  <Link to={`/payroll/runs/${row.runId}`} className="lux-payroll-register__inline-link">View run</Link>
                ) : (
                  "—"
                )}
              </td>
              <td>
                {row.runId ? (
                  <PayrollRegisterOpen to={`/payroll/runs/${row.runId}`} label={`Open run for ${row.code}`} />
                ) : null}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </PayrollRegisterWrap>
  );
}

export function PayrollGroupsRegister({ groups, onEdit }) {
  return (
    <PayrollRegisterWrap>
      <table className="lux-payroll-register">
        <thead>
          <tr>
            <th>Group</th>
            <th>Frequency</th>
            <th>Current period</th>
            <th>Next pay date</th>
            <th>Lock day</th>
            <th>Currency</th>
            <th>Employees</th>
            <th>Status</th>
            <th aria-label="Actions" />
          </tr>
        </thead>
        <tbody>
          {groups.map((row) => {
            const isActive = String(row.status || "Active").toLowerCase() === "active";
            return (
              <tr key={row.id || row.code} className="lux-payroll-register__row">
                <td>
                  <PayrollRegisterPrimaryCell
                    icon="fe fe-users"
                    iconTone="green"
                    title={row.name}
                    meta={row.code}
                  />
                </td>
                <td>
                  <span className="lux-payroll-register__chip">{row.payFrequency || "—"}</span>
                </td>
                <td>
                  <span className="lux-payroll-register__date">{row.currentPeriod || "—"}</span>
                </td>
                <td>
                  <span className="lux-payroll-register__date is-emphasis">
                    {formatPayrollDate(row.nextPayDate)}
                  </span>
                </td>
                <td>
                  <span className="lux-payroll-register__count">
                    {row.lockDay != null ? `Day ${row.lockDay}` : "—"}
                  </span>
                </td>
                <td>
                  <span className="lux-payroll-register__chip is-slate">{row.currency || "—"}</span>
                </td>
                <td>
                  <span className="lux-payroll-register__count">{row.employeeCount != null ? row.employeeCount : 0}</span>
                </td>
                <td>
                  <span className={classNames("lux-doc-badge", isActive ? "is-green" : "is-slate")}>
                    {row.status || "Active"}
                  </span>
                </td>
                <td>
                  {typeof onEdit === "function" ? (
                    <button
                      type="button"
                      className="lux-payroll-register__inline-link"
                      onClick={() => onEdit(row)}
                    >
                      Edit
                    </button>
                  ) : null}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </PayrollRegisterWrap>
  );
}
