const PROFILE_PHOTO_STORAGE_PREFIX = "famstack-profile-photo-";

export function getStoredProfilePhoto(employeeId) {
  if (!employeeId) return null;
  try {
    return localStorage.getItem(`${PROFILE_PHOTO_STORAGE_PREFIX}${employeeId}`);
  } catch (e) {
    return null;
  }
}

export function getDefaultEmployeeAvatarUrl(employee) {
  const isFemale = employee && (employee.gender === "female" || employee.gender === "Female");
  return `/assets/images/${isFemale ? "female.png" : "male.jpg"}`;
}

export function resolveEmployeeAvatarUrl(employee) {
  if (!employee) return getDefaultEmployeeAvatarUrl(null);
  const stored = getStoredProfilePhoto(employee.id);
  return stored || getDefaultEmployeeAvatarUrl(employee);
}
