import React, { Component } from "react";
import classNames from "classnames/bind";
import { benefitsService } from "_services/benefits/benefits.service";
import BenefitsLuxPage, {
  BenefitsActionButton,
  BenefitsLuxPanel,
  BenefitsQuickNav,
  BenefitsInsightPanel,
  BenefitsField,
  BenefitsFormGrid,
  BenefitsRegisterWrap,
  BenefitsRegisterPrimary,
  BenefitsToolbar,
  BenefitsStatusBadge,
  BenefitsSectionTabs,
} from "views/benefits/components/BenefitsLuxShared";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

const PLAN_TYPES = [
  { value: "MEDICAL", label: "Medical" },
  { value: "DENTAL", label: "Dental" },
  { value: "VISION", label: "Vision" },
  { value: "OTHER", label: "Other" },
];

class BenefitsPlansPage extends Component {
  state = {
    loading: true,
    loadError: null,
    rows: [],
    saving: false,
    query: "",
    typeFilter: "ALL",
    form: { name: "", code: "", carrierName: "", planType: "MEDICAL" },
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Benefits plans");
    }
    this.load();
  }

  load = async () => {
    this.setState({ loading: true, loadError: null });
    const result = await benefitsService.listPlans();
    if (result.source === "api" && Array.isArray(result.payload)) {
      this.setState({ loading: false, rows: result.payload });
    } else {
      this.setState({
        loading: false,
        rows: [],
        loadError: result.error || new Error("Unable to load plans"),
      });
    }
  };

  handleCreate = async (e) => {
    e.preventDefault();
    const { form } = this.state;
    if (!form.name) return;
    this.setState({ saving: true, loadError: null });
    const result = await benefitsService.createPlan(form);
    this.setState({ saving: false });
    if (result.source === "api") {
      this.setState({ form: { name: "", code: "", carrierName: "", planType: "MEDICAL" } });
      this.load();
    } else {
      this.setState({ loadError: result.error || new Error("Create failed") });
    }
  };

  getFiltered = () => {
    const { rows, query, typeFilter } = this.state;
    const q = (query || "").trim().toLowerCase();
    return rows.filter((row) => {
      if (typeFilter !== "ALL" && String(row.planType || "").toUpperCase() !== typeFilter) {
        return false;
      }
      if (!q) return true;
      const hay = [row.name, row.code, row.carrierName, row.planRef, row.planType]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();
      return hay.includes(q);
    });
  };

  render() {
    const { loading, loadError, rows, saving, form, query, typeFilter } = this.state;
    const filtered = this.getFiltered();
    const activeCount = rows.filter((r) => r.active !== false).length;
    const kpiCards = [
      {
        id: "plans",
        label: "Plans",
        value: rows.length,
        hint: "Catalog entries",
        tone: "green",
        icon: "fe fe-heart",
      },
      {
        id: "active",
        label: "Active",
        value: activeCount,
        hint: "Open for enrollment",
        tone: "blue",
        icon: "fe fe-check-circle",
      },
      {
        id: "types",
        label: "Plan types",
        value: new Set(rows.map((r) => r.planType).filter(Boolean)).size,
        hint: "Medical, dental…",
        tone: "violet",
        icon: "fe fe-layers",
      },
      {
        id: "carriers",
        label: "Carriers",
        value: new Set(rows.map((r) => r.carrierName).filter(Boolean)).size,
        hint: "Unique providers",
        tone: "amber",
        icon: "fe fe-briefcase",
      },
    ];

    return (
      <BenefitsLuxPage
        testId="benefits-plans-page"
        dataSource={rows.length ? "api" : loadError ? "api-error" : loading ? null : "api"}
        loading={loading}
        kpiCards={kpiCards}
        pageMeta={{
          tone: "green",
          icon: "fe fe-heart",
          eyebrow: "People · Benefits",
          titleLead: "Benefits",
          titleAccent: "plans",
          lede: "Define medical, dental, vision, and other carrier plans for enrollment.",
        }}
        heroActions={
          <>
            <BenefitsActionButton icon="fe fe-refresh-cw" variant="ghost" onClick={this.load} disabled={loading}>
              Refresh
            </BenefitsActionButton>
            <BenefitsActionButton to="/benefits/enrollment" icon="fe fe-user-check" variant="ghost">
              Enrollment
            </BenefitsActionButton>
          </>
        }
      >
        <BenefitsSectionTabs active="/benefits/plans" />
        <BenefitsQuickNav />
        <BenefitsInsightPanel
          insights={[
            {
              id: "enroll",
              tone: "indigo",
              icon: "fe fe-user-plus",
              title: "Next: enroll employees",
              copy: "Create plans here, then enroll coverage on the enrollment workspace.",
              path: "/benefits/enrollment",
            },
            {
              id: "carrier",
              tone: "amber",
              icon: "fe fe-file-text",
              title: "Carrier exchange",
              copy: "Export file-based carrier files after enrollments are approved.",
              path: "/benefits/carrier-files",
            },
            {
              id: "report",
              tone: "blue",
              icon: "fe fe-bar-chart-2",
              title: "Track coverage health",
              copy: "Use benefits reports for plan and enrollment aggregates.",
              path: "/benefits/reports",
            },
          ]}
        />

        {loadError ? (
          <LuxInlineAlert tone="warning" title="Unable to load plans">
            {String(loadError.message || loadError)}
          </LuxInlineAlert>
        ) : null}

        <BenefitsLuxPanel
          title="Create plan"
          meta="Carrier catalog entry used by enrollment"
          icon="fe fe-plus"
          accent="green"
        >
          <form className="lux-benefits-form" onSubmit={this.handleCreate}>
            <BenefitsFormGrid columns={4}>
              <BenefitsField label="Plan name" hint="Visible on enrollment">
                <input
                  className="form-control"
                  placeholder="e.g. PPO Medical 2026"
                  value={form.name}
                  onChange={(e) => this.setState({ form: { ...form, name: e.target.value } })}
                  required
                />
              </BenefitsField>
              <BenefitsField label="Code">
                <input
                  className="form-control"
                  placeholder="MED-PPO"
                  value={form.code}
                  onChange={(e) => this.setState({ form: { ...form, code: e.target.value } })}
                />
              </BenefitsField>
              <BenefitsField label="Carrier">
                <input
                  className="form-control"
                  placeholder="Carrier name"
                  value={form.carrierName}
                  onChange={(e) => this.setState({ form: { ...form, carrierName: e.target.value } })}
                />
              </BenefitsField>
              <BenefitsField label="Plan type">
                <select
                  className="form-control"
                  value={form.planType}
                  onChange={(e) => this.setState({ form: { ...form, planType: e.target.value } })}
                >
                  {PLAN_TYPES.map((t) => (
                    <option key={t.value} value={t.value}>
                      {t.label}
                    </option>
                  ))}
                </select>
              </BenefitsField>
            </BenefitsFormGrid>
            <div className="lux-benefits-form__actions">
              <BenefitsActionButton type="submit" icon="fe fe-check" disabled={saving || !form.name}>
                {saving ? "Creating…" : "Create plan"}
              </BenefitsActionButton>
            </div>
          </form>
        </BenefitsLuxPanel>

        <BenefitsLuxPanel
          title="Plan register"
          meta={`${filtered.length} of ${rows.length} plan${rows.length === 1 ? "" : "s"}`}
          icon="fe fe-list"
          accent="indigo"
        >
          <BenefitsToolbar
            query={query}
            onQueryChange={(value) => this.setState({ query: value })}
            placeholder="Search name, code, carrier…"
            countLabel={
              <>
                <strong>{filtered.length}</strong> shown
              </>
            }
          >
            <div className="lux-hrms-dash__filter-group">
              {["ALL", ...PLAN_TYPES.map((t) => t.value)].map((value) => (
                <button
                  key={value}
                  type="button"
                  className={classNames("lux-hrms-dash__filter-chip", {
                    "is-active": typeFilter === value,
                  })}
                  onClick={() => this.setState({ typeFilter: value })}
                >
                  {value === "ALL" ? "All types" : value.charAt(0) + value.slice(1).toLowerCase()}
                </button>
              ))}
            </div>
          </BenefitsToolbar>

          {loading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="Loading plans"
              description="Fetching benefits plan catalog."
            />
          ) : filtered.length === 0 ? (
            <LuxRegisterEmptyState
              title={rows.length === 0 ? "No plans yet" : "No matching plans"}
              description={
                rows.length === 0
                  ? "Create a benefits plan to begin enrollment."
                  : "Try a different search or type filter."
              }
              showCreate={false}
            />
          ) : (
            <BenefitsRegisterWrap>
              <table className="lux-benefits-register">
                <thead>
                  <tr>
                    <th>Plan</th>
                    <th>Code</th>
                    <th>Carrier</th>
                    <th>Type</th>
                    <th>Status</th>
                    <th>Ref</th>
                  </tr>
                </thead>
                <tbody>
                  {filtered.map((r) => (
                    <tr key={r.planRef || r.id}>
                      <td>
                        <BenefitsRegisterPrimary
                          title={r.name}
                          meta={r.planRef || `ID ${r.id}`}
                          icon="fe fe-heart"
                          tone="green"
                        />
                      </td>
                      <td>
                        <code className="lux-benefits-code">{r.code || "—"}</code>
                      </td>
                      <td>{r.carrierName || "—"}</td>
                      <td>
                        <span className="lux-benefits-chip">{r.planType || "—"}</span>
                      </td>
                      <td>
                        <BenefitsStatusBadge
                          status={r.active !== false}
                          label={r.active === false ? "Inactive" : "Active"}
                        />
                      </td>
                      <td>
                        <span className="lux-benefits-muted">{r.planRef || r.id || "—"}</span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </BenefitsRegisterWrap>
          )}
        </BenefitsLuxPanel>
      </BenefitsLuxPage>
    );
  }
}

export default BenefitsPlansPage;
