import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isDeveloperPortalEnabled } from "config/developer-portal.config";
import { WEBHOOKS_PAGE_META } from "config/developer-portal-nav.config";
import { developerPortalService } from "_services/developerPortal.service";
import DeveloperLuxPage, {
  DeveloperActionButton,
  DeveloperInsightPanel,
} from "views/developer/components/DeveloperLuxShared";
import WebhookSubscriptionRegister from "views/developer/components/WebhookSubscriptionRegister";
import WebhookDeliveryPanel from "views/developer/components/WebhookDeliveryPanel";
import { WebhookCreateDrawer } from "views/developer/components/DeveloperCreateDrawers";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

class WebhooksPage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    webhooks: [],
    deliveries: [],
    kpiCards: [],
    insights: [],
    selectedSubscriptionId: null,
    createOpen: false,
  };

  componentDidMount() {
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await developerPortalService.getOverview({});
      const payload = result.payload || {};
      const webhooks = payload.webhooks || [];
      this.setState({
        loading: false,
        dataSource: result.source,
        webhooks,
        deliveries: payload.deliveries || [],
        kpiCards: payload.kpiCards || [],
        insights: payload.insights || [],
        selectedSubscriptionId: (webhooks[0] && webhooks[0].id) || null,
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load webhooks.",
      });
    }
  };

  render() {
    if (!isDeveloperPortalEnabled()) {
      return <PersonaAccessDenied featureLabel="Webhooks" />;
    }

    const { loading, loadError, dataSource, webhooks, deliveries, kpiCards, insights, selectedSubscriptionId, createOpen } = this.state;

    return (
      <DeveloperLuxPage
        pageMeta={WEBHOOKS_PAGE_META}
        pageId="webhooks"
        shellTitle="Webhooks"
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        heroActions={
          <>
            <DeveloperActionButton icon="fe fe-refresh-cw" onClick={this.loadData} disabled={loading}>
              Refresh
            </DeveloperActionButton>
            <DeveloperActionButton variant="primary" icon="fe fe-plus" onClick={() => this.setState({ createOpen: true })}>
              Create webhook
            </DeveloperActionButton>
            <DeveloperActionButton to="/admin/developer" icon="fe fe-code">
              Portal
            </DeveloperActionButton>
          </>
        }
      >
        {loadError ? <LuxInlineAlert message={loadError} /> : null}
        <DeveloperInsightPanel insights={insights} loading={loading} />
        <div className="lux-dev-page-grid">
          <WebhookSubscriptionRegister
            webhooks={webhooks}
            loading={loading}
            selectedId={selectedSubscriptionId}
            onSelect={(row) => this.setState({ selectedSubscriptionId: row.id })}
          />
          <WebhookDeliveryPanel
            deliveries={deliveries}
            loading={loading}
            selectedSubscriptionId={selectedSubscriptionId}
          />
        </div>
        <WebhookCreateDrawer
          open={createOpen}
          onClose={() => this.setState({ createOpen: false })}
          onCreate={(payload) => developerPortalService.createWebhook(payload)}
          onCreated={this.loadData}
        />
      </DeveloperLuxPage>
    );
  }
}

export default WebhooksPage;
