import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isIntegrationCenterEnabled } from "config/integration-center.config";
import { INTEGRATION_JOBS_PAGE_META } from "config/integration-center-nav.config";
import { buildJobInsights, buildJobsKpis } from "config/integration-center.utils";
import { integrationCenterService } from "_services/integrationCenter.service";
import IntegrationsLuxPage, {
  IntegrationActionButton,
  IntegrationInsightPanel,
  IntegrationLuxPanel,
} from "views/integrations/components/IntegrationsLuxShared";
import {
  IntegrationSnapshotStrip,
  SyncJobsRegister,
  buildJobsSnapshotMetrics,
} from "views/integrations/components/IntegrationRegisters";

class IntegrationJobsPage extends Component {
  state = { loading: true, loadError: null, dataSource: null, jobs: [], busyId: null, kpiCards: [], insights: [] };

  componentDidMount() {
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await integrationCenterService.listSyncJobs();
      const jobs = result.payload || [];
      this.setState({
        loading: false,
        dataSource: result.source,
        jobs,
        kpiCards: buildJobsKpis(jobs),
        insights: buildJobInsights(jobs),
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load sync jobs.",
      });
    }
  };

  handleRetry = async (jobId) => {
    this.setState({ busyId: jobId, loadError: null });
    try {
      await integrationCenterService.retrySyncJob(jobId);
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to retry job." });
    } finally {
      this.setState({ busyId: null });
    }
  };

  render() {
    if (!isIntegrationCenterEnabled()) {
      return <PersonaAccessDenied title="Import/export jobs" message="Integration center is not enabled for this organization." />;
    }

    const { loading, loadError, dataSource, jobs, busyId, kpiCards, insights } = this.state;

    return (
      <IntegrationsLuxPage
        pageMeta={INTEGRATION_JOBS_PAGE_META}
        pageId="jobs"
        shellTitle="Import/export jobs"
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        heroActions={
          <IntegrationActionButton icon="fe fe-refresh-cw" onClick={this.loadData} disabled={loading}>
            Refresh
          </IntegrationActionButton>
        }
      >
        {loadError ? <p className="lux-integ-error">{loadError}</p> : null}
        <IntegrationInsightPanel insights={insights} />
        <IntegrationSnapshotStrip
          loading={loading}
          badgeIcon="fe fe-repeat"
          badgeLabel="Job throughput"
          metrics={buildJobsSnapshotMetrics(jobs)}
        />
        <IntegrationLuxPanel
          title="Job register"
          meta="Incremental and full sync runs with retry controls"
          icon="fe fe-repeat"
          accent="amber"
          featured
        >
          <SyncJobsRegister jobs={jobs} loading={loading} onRetry={this.handleRetry} busyId={busyId} />
        </IntegrationLuxPanel>
      </IntegrationsLuxPage>
    );
  }
}

export default IntegrationJobsPage;
