import React, { Component } from 'react';
import { connect } from 'react-redux';
import { Link } from 'react-router-dom';
import classNames from 'classnames/bind';
import { employeeConstants } from '_constants';
import { accessUtils, commonUtils, store } from '_helpers';
import {
  loadLeaveConfig,
  LEAVE_CONFIG_CHANGED,
  shouldUseLeaveManagement,
  resolveLeaveUserTeamIds,
  buildLeaveUserTeamsAllSelected,
} from '_helpers/leave.config';
import { leaveService } from '_services/leave.service';
import { employeeService } from '_services/employee.service';
import PageInnerHeader from 'views/common/PageInnerHeader';
import { PageDataSourceReporter } from 'views/common/PageChromeContext';
import LuxModuleIntro from 'views/common/fragments/LuxModuleIntro';
import LuxRegisterEmptyState from 'views/common/fragments/LuxRegisterEmptyState';
import {
  AdminInsightStrip,
  AdminKpiStrip,
} from 'views/admin/components/AdminLuxShared';
import LeaveEmployeeFilter from './components/leave/LeaveEmployeeFilter';
import {
  buildBalanceCardsFromApi,
  findCurrentUserEmployee,
} from './components/leave/leave.utils';
import './leaveLuxForms.css';

function buildEmployeeLeaveInsights(cards, selectedEmployee) {
  const insights = [];
  const lowBalance = cards.filter((card) => Number(card.balance) <= 1 && Number(card.balance) >= 0);
  const pending = cards.reduce((sum, card) => sum + (Number(card.pending) || 0), 0);

  if (!selectedEmployee) {
    return [];
  }
  if (lowBalance.length > 0) {
    insights.push({
      id: 'low-balance',
      tone: 'amber',
      icon: 'fe fe-alert-triangle',
      title: `${lowBalance.length} type(s) with low balance`,
      copy: `Review entitlement for ${selectedEmployee.name} before peak season.`,
    });
  }
  if (pending > 0) {
    insights.push({
      id: 'pending',
      tone: 'blue',
      icon: 'fe fe-clock',
      title: `${pending} day(s) pending approval`,
      copy: 'Pending requests reduce available balance once approved.',
    });
  }
  if (insights.length === 0 && cards.length > 0) {
    insights.push({
      id: 'healthy',
      tone: 'green',
      icon: 'fe fe-check-circle',
      title: `${cards.length} balance record(s) loaded`,
      copy: `Entitlements for ${selectedEmployee.name} are current.`,
    });
  }
  return insights.slice(0, 3);
}

class EmployeeLeaveConfigPage extends Component {
  constructor() {
    super();
    this.state = {
      permission: accessUtils.getLeaveAccessControl(),
      moduleEnabled: shouldUseLeaveManagement(),
      selectedEmployeeId: null,
      leaveUserTeams: null,
      employees: [],
      leaveTypes: [],
      balances: [],
      loadingEmployees: false,
      loadingBalances: false,
      adjusting: false,
      adjustForm: { leaveTypeId: '', amount: '', entitlementAmount: '', comment: '', confirmingActorId: '' },
      message: null,
      messageTone: 'success',
      adjustError: null,
      employeesError: null,
    };
  }

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler(this.props.routeProp.name);
    this.handleLeaveConfigChanged = () => {
      this.setState(
        {
          permission: accessUtils.getLeaveAccessControl(),
          moduleEnabled: shouldUseLeaveManagement(),
        },
        () => this.bootstrap()
      );
    };
    window.addEventListener(LEAVE_CONFIG_CHANGED, this.handleLeaveConfigChanged);
    loadLeaveConfig().then(() => {
      this.setState(
        {
          permission: accessUtils.getLeaveAccessControl(),
          moduleEnabled: shouldUseLeaveManagement(),
        },
        () => this.bootstrap()
      );
    });
  }

  componentWillUnmount() {
    window.removeEventListener(LEAVE_CONFIG_CHANGED, this.handleLeaveConfigChanged);
  }

  bootstrap = () => {
    const existing = commonUtils.getUserTeams(this.props.userTeams) || [];
    const anyChecked = existing.some((team) => team && team.isChecked);
    const userTeams = anyChecked
      ? existing
      : buildLeaveUserTeamsAllSelected(existing.length ? existing : null);
    store.dispatch({
      type: employeeConstants.INITIALIZE_EMPLOYEE_ATTENDANCE_USER_TEAMS,
      userTeams,
    });
    this.setState({ leaveUserTeams: userTeams }, () => {
      this.reloadEmployees(userTeams);
      this.loadLeaveTypes();
    });
  };

  getLeaveUserTeams = () => {
    if (this.state.leaveUserTeams && this.state.leaveUserTeams.length) {
      return this.state.leaveUserTeams;
    }
    return commonUtils.getUserTeams(this.props.userTeams) || [];
  };

  leaveTeamMenuPermission = () => {
    const leave = this.state.permission || accessUtils.getLeaveAccessControl() || {};
    const teams = this.getLeaveUserTeams();
    return {
      ...leave,
      switchUserTeamsEnabled: leave.switchUserTeamsEnabled === true || teams.length > 1,
    };
  };

  /** HR / managers who can switch people elsewhere can configure others here. */
  canSelectOtherEmployees = () => {
    const p = this.state.permission || {};
    return (
      p.switchEmployeesEnabled === true
      || p.policyAdminEnabled === true
      || p.approveTeamEnabled === true
      || p.approveAllEnabled === true
    );
  };

  reloadEmployees = async (userTeams) => {
    const teams = userTeams || this.getLeaveUserTeams();
    let selectedUserTeams = (teams || [])
      .filter((team) => team && team.isChecked)
      .map((team) => team.id)
      .filter((id) => id != null);
    if (!selectedUserTeams.length) {
      selectedUserTeams = resolveLeaveUserTeamIds(teams);
    }
    if (!selectedUserTeams.length) {
      this.setState({
        loadingEmployees: false,
        employees: [],
        employeesError: 'No teams available. Check your team membership.',
      });
      return;
    }

    this.setState({ loadingEmployees: true, employeesError: null });
    try {
      const res = await employeeService.getTeamsEmployees(selectedUserTeams);
      let list = (res && res.payload) || [];
      if (!Array.isArray(list)) list = [];

      const currentUserId = commonUtils.getCurrentUserId();
      let current = findCurrentUserEmployee(list, currentUserId);

      // Ensure signed-in employee is available even if team filter omitted them.
      if (!current && currentUserId != null) {
        try {
          const selfRes = await employeeService.getEmployeeById(currentUserId);
          const self = selfRes && (selfRes.payload || selfRes);
          if (self && self.id != null) {
            list = [self, ...list.filter((e) => String(e.id) !== String(self.id))];
            current = self;
          }
        } catch (ignore) {
          // keep team list only
        }
      }

      const selectedStillValid =
        this.state.selectedEmployeeId != null
        && list.some((e) => String(e.id) === String(this.state.selectedEmployeeId));

      const nextSelectedId = selectedStillValid
        ? this.state.selectedEmployeeId
        : current
          ? current.id
          : null;

      this.setState(
        {
          loadingEmployees: false,
          employees: list,
          selectedEmployeeId: nextSelectedId,
          employeesError: list.length
            ? null
            : 'No employees returned for the selected teams.',
        },
        () => {
          if (nextSelectedId) {
            this.loadBalances(nextSelectedId);
          } else {
            this.setState({ balances: [] });
          }
        }
      );
    } catch (e) {
      this.setState({
        loadingEmployees: false,
        employees: [],
        employeesError: (e && e.message) || 'Unable to load employees for selected teams.',
      });
    }
  };

  loadLeaveTypes = () => {
    const teamIds = resolveLeaveUserTeamIds(this.getLeaveUserTeams());
    if (!teamIds.length || !this.state.moduleEnabled) return;
    leaveService.listLeaveTypes(teamIds).then(
      (res) => {
        const types = (res && res.payload) || [];
        this.setState({ leaveTypes: types });
      },
      () => this.setState({ leaveTypes: [] })
    );
  };

  renderEmployeePicker = (extraClass) => (
    <LeaveEmployeeFilter
      className={extraClass}
      panelAlign="left"
      employees={this.state.employees || []}
      selectedEmployeeId={this.state.selectedEmployeeId}
      currentEmployee={this.resolveSelectedEmployee()}
      onChange={this.handleEmployeeChange}
      isLoading={this.state.loadingEmployees}
      placeholder="Select employee"
    />
  );

  resolveSelectedEmployee = () => {
    const { selectedEmployeeId, employees } = this.state;
    if (!selectedEmployeeId) return null;
    return (employees || []).find(
      (emp) => String(emp.id) === String(selectedEmployeeId)
    );
  };

  loadBalances = (employeeId) => {
    if (!employeeId) {
      this.setState({
        balances: [],
        selectedEmployeeId: null,
        adjustError: null,
        message: null,
      });
      return;
    }

    this.setState({
      loadingBalances: true,
      selectedEmployeeId: employeeId,
      message: null,
      adjustError: null,
    });

    leaveService.getBalances(employeeId).then(
      (res) => {
        this.setState({
          balances: (res && res.payload) || [],
          loadingBalances: false,
        });
      },
      () => this.setState({ loadingBalances: false, balances: [] })
    );
  };

  handleEmployeeChange = (employeeId) => {
    this.loadBalances(employeeId);
  };

  updateAdjustForm = (patch) => {
    this.setState((prev) => ({
      adjustForm: { ...prev.adjustForm, ...patch },
      adjustError: null,
    }));
  };

  handleAdjust = () => {
    const { adjustForm, selectedEmployeeId } = this.state;
    const actorId = commonUtils.getCurrentUserId();
    const DUAL_CONTROL_THRESHOLD = 5;

    if (!selectedEmployeeId) {
      this.setState({ adjustError: 'Select an employee first.' });
      return;
    }
    if (!adjustForm.leaveTypeId) {
      this.setState({ adjustError: 'Choose a leave type.' });
      return;
    }
    if (!adjustForm.amount && !adjustForm.entitlementAmount) {
      this.setState({
        adjustError: 'Enter a balance adjustment (+/−) or opening entitlement.',
      });
      return;
    }

    const amountAbs = Math.abs(parseFloat(adjustForm.amount) || 0);
    const entitlementAbs = Math.abs(parseFloat(adjustForm.entitlementAmount) || 0);
    const impact = amountAbs + entitlementAbs;
    let confirmingActorId = null;
    if (impact >= DUAL_CONTROL_THRESHOLD) {
      confirmingActorId = parseInt(adjustForm.confirmingActorId, 10);
      if (!confirmingActorId || confirmingActorId === actorId) {
        this.setState({
          adjustError: `Adjustments of ${DUAL_CONTROL_THRESHOLD}+ days need a second confirmer (employee id ≠ yours).`,
        });
        return;
      }
    }

    this.setState({ adjusting: true, message: null, adjustError: null });
    const payload = {
      employeeId: selectedEmployeeId,
      leaveTypeId: parseInt(adjustForm.leaveTypeId, 10),
      comment: (adjustForm.comment && adjustForm.comment.trim()) || 'HR balance adjustment',
      actorId,
    };
    if (adjustForm.amount !== '' && adjustForm.amount != null) {
      payload.amount = parseFloat(adjustForm.amount);
    }
    if (adjustForm.entitlementAmount !== '' && adjustForm.entitlementAmount != null) {
      payload.entitlementAmount = parseFloat(adjustForm.entitlementAmount);
    }
    if (confirmingActorId) {
      payload.confirmingActorId = confirmingActorId;
    }

    leaveService.adjustBalance(payload).then(
      () => {
        this.setState({
          adjusting: false,
          adjustForm: {
            leaveTypeId: '',
            amount: '',
            entitlementAmount: '',
            comment: '',
            confirmingActorId: '',
          },
          message: 'Balance updated successfully.',
          messageTone: 'success',
        });
        this.loadBalances(selectedEmployeeId);
      },
      (err) => {
        const apiMsg =
          (err && err.response && err.response.data && (err.response.data.message || err.response.data.error)) ||
          (err && err.message) ||
          null;
        this.setState({
          adjusting: false,
          message: apiMsg || 'Balance adjustment failed. Check values and try again.',
          messageTone: 'error',
        });
      }
    );
  };

  renderField = (label, icon, children) => (
    <label className="lux-leave-drawer__field">
      <span className="lux-leave-drawer__label">
        {icon && <i className={`fe ${icon}`} aria-hidden="true" />}
        {label}
      </span>
      {children}
    </label>
  );

  render() {
    const {
      permission,
      moduleEnabled,
      selectedEmployeeId,
      leaveTypes,
      loadingEmployees,
      loadingBalances,
      adjusting,
      adjustForm,
      message,
      messageTone,
      adjustError,
      employees,
      employeesError,
    } = this.state;

    const cards = buildBalanceCardsFromApi(this.state.balances, leaveTypes);
    const selectedEmployee = this.resolveSelectedEmployee();
    const isLoading = loadingEmployees || loadingBalances;
    const showEmployeeFilter = this.canSelectOtherEmployees();
    const totalEntitlement = cards.reduce((sum, card) => sum + (Number(card.entitlement) || 0), 0);
    const totalUsed = cards.reduce((sum, card) => sum + (Number(card.usedDays) || 0), 0);
    const totalBalance = cards.reduce((sum, card) => sum + (Number(card.balance) || 0), 0);
    const totalPending = cards.reduce((sum, card) => sum + (Number(card.pending) || 0), 0);
    const insights = loadingBalances ? [] : buildEmployeeLeaveInsights(cards, selectedEmployee);
    const kpiCards = [
      { id: 'types', label: 'Leave types', value: cards.length, hint: 'Configured balances', tone: 'amber', icon: 'fe fe-layers' },
      { id: 'entitlement', label: 'Entitlement', value: loadingBalances ? '—' : totalEntitlement.toFixed(1), hint: 'Total allocated days', tone: 'violet', icon: 'fe fe-book-open' },
      { id: 'used', label: 'Used', value: loadingBalances ? '—' : totalUsed.toFixed(1), hint: 'Approved usage', tone: 'primary', icon: 'fe fe-check-circle' },
      { id: 'balance', label: 'Remaining', value: loadingBalances ? '—' : totalBalance.toFixed(1), hint: totalPending > 0 ? `${totalPending} pending approval` : 'Available balance', tone: 'green', icon: 'fe fe-sun' },
    ];

    if (!permission.policyAdminEnabled) {
      return (
        <div className="lux-leave-page lux-leave-config-page">
          <LuxRegisterEmptyState
            className="lux-register-empty--compact lux-leave-empty"
            icon="fe fe-lock"
            title="Employee leave config not available"
            description="HR policy admin access is required."
          />
        </div>
      );
    }

    return (
      <div className="lux-leave-page lux-leave-config-page" data-testid="page-employee-leave-config">
        <PageDataSourceReporter dataSource="api" />
        <LuxModuleIntro
          meta={{
            tone: 'teal',
            icon: 'fe fe-sliders',
            eyebrow: 'Admin · Leave',
            titleLead: 'Employee leave',
            titleAccent: 'configuration',
            lede: 'Entitlements, balances, and adjustments per employee.',
          }}
          howToHref="/documentation/hrms/leave-configuration.html"
          howToTestId="leave-config-documentation-link"
          actions={
            <Link to="/admin/leave-policies" className="lux-page-header__action-btn">
              <i className="fe fe-layers" aria-hidden="true" />
              Leave policies
            </Link>
          }
        />
        <PageInnerHeader
          userTeams={this.getLeaveUserTeams()}
          handleUserTeamsSelection={(userTeams) => {
            store.dispatch({
              type: employeeConstants.INITIALIZE_EMPLOYEE_ATTENDANCE_USER_TEAMS,
              userTeams,
            });
            this.setState(
              { leaveUserTeams: userTeams, selectedEmployeeId: null, balances: [] },
              () => {
                this.reloadEmployees(userTeams);
                this.loadLeaveTypes();
              }
            );
          }}
          showUserTeamMenu={true}
          showFilter={false}
          isLoading={isLoading}
          permission={this.leaveTeamMenuPermission()}
          employeeFilterSlot={showEmployeeFilter ? this.renderEmployeePicker() : null}
        />

        {!moduleEnabled ? (
          <LuxRegisterEmptyState
            className="lux-register-empty--compact lux-leave-empty"
            icon="fe fe-sliders"
            title="Native leave module is off"
            description="Enable leaveManagementEnabled under leaveAdditional in Application Configuration."
          />
        ) : employees.length === 0 && !loadingEmployees ? (
          <LuxRegisterEmptyState
            className="lux-register-empty--compact lux-leave-empty"
            icon="fe fe-users"
            title="No employees loaded"
            description={
              employeesError
              || 'Select a team above or check your team filter to load employees.'
            }
          />
        ) : (
          <>
            {message && (
              <div
                className={classNames('lux-leave-config__banner', {
                  'is-success': messageTone === 'success',
                  'is-error': messageTone === 'error',
                })}
                role="status"
              >
                <i
                  className={classNames('fe', messageTone === 'success' ? 'fe-check-circle' : 'fe-alert-circle')}
                  aria-hidden="true"
                />
                <span>{message}</span>
                <button type="button" onClick={() => this.setState({ message: null })} aria-label="Dismiss">
                  <i className="fe fe-x" aria-hidden="true" />
                </button>
              </div>
            )}

            {showEmployeeFilter ? (
              <section
                className="lux-leave-subpanel lux-leave-config__employee-pick"
                aria-label="Employee selection"
                data-testid="leave-config-employee-pick"
              >
                <header className="lux-leave-subpanel__head">
                  <div>
                    <span className="lux-leave-subpanel__eyebrow">Employee</span>
                    <h3 className="lux-leave-subpanel__title">
                      {selectedEmployee ? selectedEmployee.name : 'Choose who to configure'}
                    </h3>
                    <p className="lux-leave-subpanel__sub">
                      Defaults to you. Pick another team member to adjust their balances.
                    </p>
                  </div>
                  {this.renderEmployeePicker('lux-leave-employee-filter--prominent')}
                </header>
              </section>
            ) : selectedEmployee ? (
              <section className="lux-leave-subpanel lux-leave-config__employee-pick" aria-label="Current employee">
                <header className="lux-leave-subpanel__head">
                  <div>
                    <span className="lux-leave-subpanel__eyebrow">Employee</span>
                    <h3 className="lux-leave-subpanel__title">{selectedEmployee.name}</h3>
                    <p className="lux-leave-subpanel__sub">Configuring leave balances for your employee record.</p>
                  </div>
                </header>
              </section>
            ) : null}

            {!selectedEmployeeId ? (
              <LuxRegisterEmptyState
                className="lux-register-empty--compact lux-leave-empty"
                icon="fe fe-user"
                title={loadingEmployees ? 'Loading employees…' : 'Select an employee'}
                description={
                  showEmployeeFilter
                    ? 'Use the employee menu above to load leave balances and apply HR adjustments.'
                    : 'Your user is not linked to an employee record in the selected teams.'
                }
              />
            ) : (
              <>
                <AdminKpiStrip cards={kpiCards} loading={loadingBalances} className="lux-leave-config-kpi-strip" />
                <AdminInsightStrip insights={insights} />

                <section className="lux-leave-subpanel lux-leave-config__balances" aria-label="Employee leave balances">
                  <header className="lux-leave-subpanel__head">
                    <div>
                      <span className="lux-leave-subpanel__eyebrow">Balances</span>
                      <h3 className="lux-leave-subpanel__title">{selectedEmployee.name}</h3>
                      <p className="lux-leave-subpanel__sub">
                        Current entitlement, usage, and remaining balance by leave type
                      </p>
                    </div>
                  </header>

                  {loadingBalances ? (
                    <div className="lux-leave-register__skeleton" aria-busy="true" />
                  ) : cards.length === 0 ? (
                    <LuxRegisterEmptyState
                      className="lux-register-empty--compact lux-leave-empty"
                      icon="fe fe-layers"
                      title="No balance records"
                      description="Use the adjustment form below to set opening entitlement or credit balance."
                    />
                  ) : (
                    <div className="lux-leave-register-wrap">
                      <table className="lux-leave-register">
                        <thead>
                          <tr>
                            <th>Type</th>
                            <th>Entitlement</th>
                            <th>Used</th>
                            <th>Pending</th>
                            <th>Balance</th>
                            <th>Available</th>
                          </tr>
                        </thead>
                        <tbody>
                          {cards.map((card) => (
                            <tr key={card.leaveTypeId || card.code} className="lux-leave-register__row">
                              <td>
                                <span className="lux-leave-register__type">
                                  <strong>{card.label}</strong>
                                  <em>{card.code}</em>
                                </span>
                              </td>
                              <td>{card.entitlement}</td>
                              <td>{card.usedDays}</td>
                              <td>{card.pending || 0}</td>
                              <td>
                                <strong className="lux-leave-calc__balance-val">{card.balance}</strong>
                              </td>
                              <td>{card.available}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  )}
                </section>

                <section className="lux-leave-subpanel lux-leave-config__adjust" aria-label="Adjust leave balance">
                  <header className="lux-leave-subpanel__head">
                    <div>
                      <span className="lux-leave-subpanel__eyebrow">HR adjustment</span>
                      <h3 className="lux-leave-subpanel__title">Adjust balance</h3>
                      <p className="lux-leave-subpanel__sub">
                        Balance adjust changes available days. Opening entitlement also credits balance (annual allocation).
                        Adjustments of 5+ days require a second confirmer employee id.
                      </p>
                    </div>
                  </header>

                  {adjustError && (
                    <div className="lux-leave-config__banner is-error" role="alert">
                      <i className="fe fe-alert-circle" aria-hidden="true" />
                      <span>{adjustError}</span>
                    </div>
                  )}

                  <div className="lux-leave-config__form">
                    <div className="lux-leave-config__form-grid">
                      {this.renderField(
                        'Leave type',
                        'fe-layers',
                        <select
                          className="lux-leave-drawer__input"
                          value={adjustForm.leaveTypeId}
                          onChange={(e) => this.updateAdjustForm({ leaveTypeId: e.target.value })}
                        >
                          <option value="">Select leave type…</option>
                          {leaveTypes.map((type) => (
                            <option key={type.id} value={type.id}>
                              {type.code} — {type.name}
                            </option>
                          ))}
                        </select>
                      )}

                      {this.renderField(
                        'Balance (+/−)',
                        'fe-plus-circle',
                        <input
                          type="number"
                          step="0.5"
                          className="lux-leave-drawer__input"
                          value={adjustForm.amount}
                          onChange={(e) => this.updateAdjustForm({ amount: e.target.value })}
                          placeholder="e.g. 2 or -1"
                        />
                      )}

                      {this.renderField(
                        'Opening entitlement',
                        'fe-book-open',
                        <input
                          type="number"
                          step="0.5"
                          className="lux-leave-drawer__input"
                          value={adjustForm.entitlementAmount}
                          onChange={(e) => this.updateAdjustForm({ entitlementAmount: e.target.value })}
                          placeholder="e.g. 12"
                        />
                      )}

                      {this.renderField(
                        'Comment',
                        'fe-message-square',
                        <input
                          type="text"
                          className="lux-leave-drawer__input"
                          value={adjustForm.comment}
                          onChange={(e) => this.updateAdjustForm({ comment: e.target.value })}
                          placeholder="Reason for adjustment"
                        />
                      )}

                      {(Math.abs(parseFloat(adjustForm.amount) || 0) +
                        Math.abs(parseFloat(adjustForm.entitlementAmount) || 0) >=
                        5) &&
                        this.renderField(
                          'Confirmer employee id',
                          'fe-user-check',
                          <input
                            type="number"
                            className="lux-leave-drawer__input"
                            value={adjustForm.confirmingActorId || ''}
                            onChange={(e) => this.updateAdjustForm({ confirmingActorId: e.target.value })}
                            placeholder="Second HR/manager employee id"
                            data-testid="leave-adjust-confirmer"
                          />
                        )}
                    </div>

                    <div className="lux-leave-config__form-actions">
                      <button
                        type="button"
                        className="lux-leave-drawer__btn is-ghost"
                        onClick={() =>
                          this.setState({
                            adjustForm: {
                              leaveTypeId: '',
                              amount: '',
                              entitlementAmount: '',
                              comment: '',
                              confirmingActorId: '',
                            },
                            adjustError: null,
                          })
                        }
                        disabled={adjusting}
                      >
                        Clear
                      </button>
                      <button
                        type="button"
                        className="lux-leave-drawer__btn is-primary"
                        disabled={adjusting || loadingBalances}
                        onClick={this.handleAdjust}
                      >
                        {adjusting ? 'Applying…' : 'Apply adjustment'}
                      </button>
                    </div>
                  </div>
                </section>
              </>
            )}
          </>
        )}
      </div>
    );
  }
}

function mapStateToProps(state) {
  return {
    userTeams: state.employees.userTeamsA || state.employees.userTeams,
  };
}

export default connect(mapStateToProps)(EmployeeLeaveConfigPage);
