import {
  UNIVERSAL_APPROVAL_PRIORITIES,
  UNIVERSAL_APPROVAL_STATUSES,
  getApprovalDomainMeta,
} from "./universal-approval.config";
import { classifyApprovalAging } from "./approval-analytics.utils";
import { getExceptionTypeLabel } from "./attendance-regularization.config";

const DOMAIN_TYPE_MAP = {
  leave: "LEAVE",
  timesheet: "TIMESHEET",
  expense: "EXPENSE",
  staffing: "STAFFING",
  document: "DOCUMENT",
  lifecycle: "LIFECYCLE",
  onboarding: "ONBOARDING",
  offboarding: "OFFBOARDING",
  attendance: "ATTENDANCE",
  "attendance regularization": "ATTENDANCE_REGULARIZATION",
  regularization: "ATTENDANCE_REGULARIZATION",
};

export function normalizeApprovalPriority(value) {
  const normalized = String(value || "NORMAL").toUpperCase();
  if (normalized === "HIGH" || normalized === "URGENT" || normalized === "P1") {
    return UNIVERSAL_APPROVAL_PRIORITIES.HIGH;
  }
  if (normalized === "LOW" || normalized === "P3") {
    return UNIVERSAL_APPROVAL_PRIORITIES.LOW;
  }
  return UNIVERSAL_APPROVAL_PRIORITIES.NORMAL;
}

export function normalizeApprovalStatus(value) {
  const normalized = String(value || "PENDING").toUpperCase();
  if (normalized === "APPROVED" || normalized === "ACCEPTED") {
    return UNIVERSAL_APPROVAL_STATUSES.APPROVED;
  }
  if (normalized === "REJECTED" || normalized === "DECLINED") {
    return UNIVERSAL_APPROVAL_STATUSES.REJECTED;
  }
  return UNIVERSAL_APPROVAL_STATUSES.PENDING;
}

export function resolveApprovalDomainId(raw) {
  if (raw.domain) {
    return String(raw.domain).toUpperCase();
  }
  const fromType = DOMAIN_TYPE_MAP[String(raw.type || "").toLowerCase()];
  return fromType || "UNKNOWN";
}

export function buildUniversalApprovalId(domain, sourceId, sourceType = "mock") {
  return `${sourceType}:${domain}:${sourceId}`;
}

export function hasLiveSourceContract(item) {
  return Boolean(
    item &&
      item.liveSource === true &&
      item.canonicalSource &&
      item.sourceEntity &&
      Array.isArray(item.sourceLinks) &&
      item.sourceLinks.length > 0
  );
}

export function normalizeUniversalApprovalItem(raw, sourceType = "mock") {
  const domain = resolveApprovalDomainId(raw);
  const domainMeta = getApprovalDomainMeta(domain);
  const sourceId = raw.sourceId != null ? raw.sourceId : raw.id;
  const status = normalizeApprovalStatus(raw.status);
  const priority = normalizeApprovalPriority(raw.priority);
  const requesterId = raw.requesterId != null ? raw.requesterId : raw.employeeId != null ? raw.employeeId : null;
  const requester =
    firstNonEmpty(
      raw.requesterName,
      raw.requester,
      raw.employeeName,
      raw.candidateName,
      requesterId != null ? `Employee ${requesterId}` : null
    ) || "Unknown";
  const subject = raw.subject || raw.title || raw.summary || domainMeta.label;
  const dueLabel = raw.dueLabel || raw.due || raw.dueDate || raw.weekEnding || null;
  const submittedAt = raw.submittedAt || raw.submittedOn || raw.createdAt || null;
  const detailPath = resolveApprovalDetailPath(
    domain,
    raw.detailPath || domainMeta.detailPath || null
  );

  return {
    id: raw.universalId || buildUniversalApprovalId(domain, sourceId, sourceType),
    sourceId,
    sourceType,
    domain,
    domainLabel: domainMeta.label,
    domainIcon: domainMeta.icon,
    module: raw.module || domainMeta.module,
    moduleTone: domainMeta.tone,
    type: raw.type || domainMeta.label,
    requester,
    requesterId,
    subject,
    status,
    priority,
    dueLabel,
    submittedAt,
    detailPath,
    actingAsDelegate: raw.actingAsDelegate === true,
    authorityManagerId: raw.authorityManagerId || null,
    liveSource: raw.liveSource === true,
    canonicalSource: raw.canonicalSource || null,
    sourceEntity: raw.sourceEntity || null,
    sourceLinks: Array.isArray(raw.sourceLinks) ? raw.sourceLinks : [],
    metadata: raw.metadata || {},
    raw,
  };
}

/** Map API detail paths that do not exist as FE routes onto real module pages. */
export function resolveApprovalDetailPath(domain, detailPath) {
  const path = detailPath ? String(detailPath).trim() : "";
  if (!path) {
    const meta = getApprovalDomainMeta(domain);
    return meta.detailPath || null;
  }
  if (
    domain === "ATTENDANCE_REGULARIZATION" ||
    path === "/people/attendance/regularization" ||
    path.startsWith("/people/attendance/regularization/")
  ) {
    return "/people/attendance";
  }
  return path;
}

function firstNonEmpty(...values) {
  for (let i = 0; i < values.length; i += 1) {
    const value = values[i];
    if (value == null) continue;
    const text = String(value).trim();
    if (!text || /^unknown$/i.test(text)) continue;
    return text;
  }
  return null;
}

export function findEmployeeForApproval(employees, employeeId) {
  if (employeeId == null || employeeId === "") {
    return null;
  }
  return (employees || []).find((emp) => String(emp.id) === String(employeeId)) || null;
}

export function formatApprovalRequesterDisplay({ name, empCode, employeeId }) {
  const bits = [
    firstNonEmpty(name),
    empCode ? `Code ${empCode}` : null,
    employeeId != null && employeeId !== "" ? `ID ${employeeId}` : null,
  ].filter(Boolean);
  return bits.length ? bits.join(" · ") : "Unknown";
}

/**
 * Resolve missing/blank requester labels from the employee roster.
 * Updates requester + metadata (employeeName, empCode, employeeId).
 */
export function enrichApprovalInboxItems(items, employees) {
  if (!items || !items.length) {
    return items || [];
  }
  const roster = employees || [];
  return items.map((item) => {
    if (!item) return item;
    const employeeId =
      item.requesterId != null
        ? item.requesterId
        : item.metadata && item.metadata.employeeId != null
          ? item.metadata.employeeId
          : null;
    const match = findEmployeeForApproval(roster, employeeId);
    const meta = Object.assign({}, item.metadata || {});
    const name = firstNonEmpty(
      match && match.name,
      meta.employeeName,
      item.requester && !/^employee\s+/i.test(String(item.requester)) && !/^unknown$/i.test(String(item.requester))
        ? item.requester
        : null
    );
    const empCode = firstNonEmpty(
      match && (match.empCode || match.employeeCode || match.code),
      meta.empCode,
      meta.employeeCode
    );
    if (name) meta.employeeName = name;
    if (empCode) meta.empCode = empCode;
    if (employeeId != null) meta.employeeId = String(employeeId);

    const needsEnrichment =
      !item.requester ||
      /^unknown$/i.test(String(item.requester).trim()) ||
      /^employee\s+/i.test(String(item.requester).trim()) ||
      (match && name && String(item.requester) !== name);

    if (!needsEnrichment && !match) {
      return item.metadata === meta ? item : Object.assign({}, item, { metadata: meta });
    }

    return Object.assign({}, item, {
      requester: formatApprovalRequesterDisplay({
        name: name || (employeeId != null ? `Employee ${employeeId}` : null),
        empCode,
        employeeId,
      }),
      requesterId: employeeId != null ? employeeId : item.requesterId,
      metadata: meta,
    });
  });
}

export function normalizeAttendanceApprovalItem(attendance) {
  if (!attendance) {
    return null;
  }
  return normalizeUniversalApprovalItem(
    {
      domain: "ATTENDANCE",
      sourceId: attendance.id,
      type: "Attendance",
      requester: attendance.employeeName,
      requesterId: attendance.employeeId,
      subject: "Attendance approval",
      status: attendance.status || "PENDING",
      priority: attendance.priority || "NORMAL",
      dueLabel: attendance.markDate || attendance.attendanceDate,
      submittedAt: attendance.submittedAt || attendance.markDate,
      actingAsDelegate: attendance.actingAsDelegate,
      authorityManagerId: attendance.authorityManagerId,
      detailPath: "/people/attendance",
      metadata: {
        attendanceDate: attendance.markDate || attendance.attendanceDate,
        adapterKind: "ATTENDANCE_MODEL",
      },
    },
    "live"
  );
}

export function normalizeLeaveApprovalItem(leave) {
  if (!leave) {
    return null;
  }
  const typeLabel = leave.leaveTypeName || leave.leaveType || "Leave";
  const days = leave.numberOfDays != null ? `${leave.numberOfDays} day(s)` : "";
  return normalizeUniversalApprovalItem(
    {
      domain: "LEAVE",
      sourceId: leave.id,
      type: "Leave",
      requester: leave.employeeName,
      requesterId: leave.employeeId,
      subject: [typeLabel, days].filter(Boolean).join(" · "),
      status: leave.status || "PENDING",
      priority: leave.priority || "NORMAL",
      dueLabel: leave.endDate || leave.startDate,
      submittedAt: leave.submittedOn || leave.createdAt,
      actingAsDelegate: leave.actingAsDelegate,
      authorityManagerId: leave.authorityManagerId,
      detailPath: "/people/leaves",
      metadata: { leaveType: typeLabel },
    },
    "live"
  );
}

export function normalizeTimesheetApprovalItem(week) {
  if (!week) {
    return null;
  }
  return normalizeUniversalApprovalItem(
    {
      domain: "TIMESHEET",
      sourceId: week.id,
      type: "Timesheet",
      requester: week.employeeName,
      requesterId: week.employeeId,
      subject: week.weekLabel || `Week ending ${week.weekEndDate || week.endDate || ""}`,
      status: week.status || "PENDING",
      priority: week.priority || (week.hasConflicts ? "HIGH" : "NORMAL"),
      dueLabel: week.weekEndDate || week.endDate,
      submittedAt: week.submittedOn || week.submittedAt,
      actingAsDelegate: week.actingAsDelegate,
      authorityManagerId: week.authorityManagerId,
      detailPath: "/people/timesheet",
      metadata: {
        totalHours: week.totalHours,
        conflictCount: week.conflictCount,
      },
    },
    "live"
  );
}

export function normalizeRegularizationApprovalItem(row) {
  if (!row) {
    return null;
  }
    const markDate = row.attendanceDate || row.date || row.markDate || null;
  const exceptionLabel =
    row.exceptionLabel ||
    row.exceptionTypeLabel ||
    getExceptionTypeLabel(row.exceptionType) ||
    "Punch correction";
  const inTime = row.requestedInTime || row.inTime || null;
  const outTime = row.requestedOutTime || row.outTime || null;
  const punchWindow =
    inTime || outTime ? `${inTime || "—"} → ${outTime || "—"}` : null;
  const empCode = row.empCode || row.employeeCode || null;
  const employeeName =
    (row.employeeName && String(row.employeeName).trim()) ||
    (row.requesterName && String(row.requesterName).trim()) ||
    null;
  const requesterBits = [
    employeeName,
    empCode ? `Code ${empCode}` : null,
    row.employeeId != null ? `ID ${row.employeeId}` : null,
  ].filter(Boolean);
  const subject =
    row.reasonLabel ||
    [exceptionLabel, markDate].filter(Boolean).join(" · ") ||
    "Punch regularization";

  return normalizeUniversalApprovalItem(
    {
      domain: "ATTENDANCE_REGULARIZATION",
      sourceId: row.id,
      type: "Regularization",
      requester: requesterBits.length
        ? requesterBits.join(" · ")
        : row.employeeId != null
          ? `Employee ${row.employeeId}`
          : "Unknown",
      requesterId: row.employeeId,
      employeeName,
      empCode,
      subject,
      status: row.status || "PENDING",
      priority: row.priority || (row.payrollLocked || row.timesheetConflict ? "HIGH" : "NORMAL"),
      dueLabel: markDate,
      submittedAt: row.submittedAt || row.createdAt,
      detailPath: "/people/attendance",
      metadata: {
        attendanceDate: markDate,
        exceptionType: exceptionLabel,
        punchWindow,
        reason: row.reason || null,
        empCode,
        employeeName,
        employeeId: row.employeeId != null ? String(row.employeeId) : null,
        payrollLocked: row.payrollLocked === true ? "Yes" : null,
        timesheetConflict: row.timesheetConflict === true ? "Yes" : null,
        userTeamId: row.userTeamId || row.user_team_id || null,
      },
    },
    "live"
  );
}

export function normalizeLifecycleApprovalItem(caseData, task, domain) {
  if (!caseData || !task) {
    return null;
  }
  const normalizedDomain = String(domain || "LIFECYCLE").toUpperCase();
  const requester =
    caseData.candidateName || caseData.employeeName || caseData.owner || "Unknown";
  const subjectParts = [task.title];
  if (caseData.role) {
    subjectParts.push(caseData.role);
  }
  const detailPath =
    normalizedDomain === "OFFBOARDING" ? "/people/offboarding" : "/people/onboarding";
  const priority =
    task.status === "blocked" || task.status === "in_progress" ? "HIGH" : "NORMAL";

  return normalizeUniversalApprovalItem(
    {
      domain: normalizedDomain,
      sourceId: `${caseData.id}:${task.id}`,
      type: normalizedDomain === "OFFBOARDING" ? "Offboarding" : "Onboarding",
      requester,
      requesterId: caseData.managerId || caseData.employeeId || null,
      subject: subjectParts.filter(Boolean).join(" · "),
      status: "PENDING",
      priority,
      dueLabel: task.dueDate || caseData.startDate || caseData.lastDay,
      submittedAt: task.createdAt || caseData.startDate || caseData.lastDay,
      detailPath,
      metadata: {
        caseId: caseData.id,
        taskId: task.id,
        lifecycle: normalizedDomain === "OFFBOARDING" ? "offboarding" : "onboarding",
        taskTitle: task.title,
        taskCategory: task.category,
        department: caseData.department,
      },
    },
    "live"
  );
}

export function buildApprovalInboxMetrics(items) {
  const list = items || [];
  const pending = list.filter((item) => item.status === UNIVERSAL_APPROVAL_STATUSES.PENDING);
  const highPriority = pending.filter((item) => item.priority === UNIVERSAL_APPROVAL_PRIORITIES.HIGH);
  const domains = new Set(pending.map((item) => item.domain));
  const delegateCount = pending.filter((item) => item.actingAsDelegate).length;

  return {
    total: list.length,
    pending: pending.length,
    highPriority: highPriority.length,
    domainCount: domains.size,
    delegateCount,
  };
}

export function filterApprovalInboxItems(items, filters = {}) {
  const {
    status = "PENDING",
    domain = "ALL",
    priority = "ALL",
    query = "",
  } = filters;
  const normalizedQuery = String(query || "").trim().toLowerCase();

  return (items || []).filter((item) => {
    if (status !== "ALL" && item.status !== status) {
      return false;
    }
    if (domain !== "ALL" && item.domain !== domain) {
      return false;
    }
    if (priority !== "ALL" && item.priority !== priority) {
      return false;
    }
    if (!normalizedQuery) {
      return true;
    }
    const haystack = [item.requester, item.subject, item.domainLabel, item.module, item.type]
      .join(" ")
      .toLowerCase();
    return haystack.includes(normalizedQuery);
  });
}

export function sortApprovalInboxItems(items, now = new Date()) {
  const priorityRank = {
    [UNIVERSAL_APPROVAL_PRIORITIES.HIGH]: 0,
    [UNIVERSAL_APPROVAL_PRIORITIES.NORMAL]: 1,
    [UNIVERSAL_APPROVAL_PRIORITIES.LOW]: 2,
  };
  const agingRank = { overdue: 0, dueSoon: 1, onTrack: 2 };

  return [...(items || [])].sort((left, right) => {
    const leftAging = classifyApprovalAging(left, now);
    const rightAging = classifyApprovalAging(right, now);
    const agingDelta =
      (agingRank[leftAging] != null ? agingRank[leftAging] : 3) -
      (agingRank[rightAging] != null ? agingRank[rightAging] : 3);
    if (agingDelta !== 0) {
      return agingDelta;
    }

    const priorityDelta =
      (priorityRank[left.priority] != null ? priorityRank[left.priority] : 9) -
      (priorityRank[right.priority] != null ? priorityRank[right.priority] : 9);
    if (priorityDelta !== 0) {
      return priorityDelta;
    }
    return String(left.requester || "").localeCompare(String(right.requester || ""));
  });
}

export function getApprovalPriorityTone(priority) {
  if (priority === UNIVERSAL_APPROVAL_PRIORITIES.HIGH) {
    return "danger";
  }
  if (priority === UNIVERSAL_APPROVAL_PRIORITIES.LOW) {
    return "slate";
  }
  return "warning";
}
