import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isResourcePlanningEnabled, STAFFING_REQUEST_STATUSES } from "config/resource-planning.config";
import { buildSimulationInsights } from "config/resource-planning.utils";
import { resourcePlanningService } from "_services/resourcePlanning.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import {
  AdminInsightStrip,
} from "views/admin/components/AdminLuxShared";
import {
  ResourcesActionButton,
  ResourcesHeroActions,
  ResourcesKpiStrip,
  ResourcesSectionHead,
} from "views/resources/components/ResourcesLuxShared";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import { PageDataSourceReporter } from "views/common/PageChromeContext";
import SimulationCompareStrip from "views/resources/components/SimulationCompareStrip";
import SimulationScenarioPanel from "views/resources/components/SimulationScenarioPanel";
import { DENSE_PAGE_META } from "config/dense-page-meta.config";

class CapacitySimulationPage extends Component {
  state = {
    templates: [],
    staffingRequests: [],
    benchRecords: [],
    allocations: [],
    adjustments: [],
    scenarioName: "",
    result: null,
    loading: true,
    running: false,
    loadError: null,
    dataSource: null,
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Capacity simulation");
    this.loadContext();
  }

  loadContext = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const [templatesRes, staffingRes, benchRes, allocRes, capacityRes] = await Promise.all([
        resourcePlanningService.listSimulationTemplates(),
        resourcePlanningService.listStaffingRequests(),
        resourcePlanningService.listBenchRecords(),
        resourcePlanningService.listAllocations(),
        resourcePlanningService.getCapacitySummary(),
      ]);
      this.setState({
        templates: templatesRes.payload || [],
        staffingRequests: staffingRes.payload || [],
        benchRecords: benchRes.payload || [],
        allocations: allocRes.payload || [],
        capacitySummary: capacityRes.payload,
        loading: false,
        dataSource: templatesRes.source || staffingRes.source || null,
      });
    } catch (e) {
      this.setState({
        loading: false,
        loadError: "Unable to load simulation context.",
      });
    }
  };

  handleAdjustmentsChange = (adjustments, scenarioName = "") => {
    this.setState({
      adjustments,
      scenarioName: scenarioName || this.state.scenarioName,
      result: null,
    });
  };

  handleRemoveAdjustment = (index) => {
    this.setState((prev) => ({
      adjustments: prev.adjustments.filter((_, i) => i !== index),
      result: null,
    }));
  };

  runScenario = async (adjustments, scenarioName) => {
    const list = adjustments || this.state.adjustments;
    if (!list.length) {
      return;
    }
    this.setState({ running: true, loadError: null });
    try {
      const result = await resourcePlanningService.runCapacitySimulation({
        name: scenarioName || "Custom scenario",
        adjustments: list,
      });
      if (result && result.payload) {
        this.setState({
          running: false,
          result: result.payload,
          scenarioName: scenarioName || this.state.scenarioName,
          dataSource: result.source || this.state.dataSource,
        });
        return;
      }
      this.setState({
        running: false,
        loadError: "Simulation did not return results. Try again.",
      });
    } catch (e) {
      this.setState({ running: false, loadError: "Simulation failed. Try again." });
    }
  };

  getContext = () => ({
    staffingRequests: this.state.staffingRequests,
    benchRecords: this.state.benchRecords,
    allocations: this.state.allocations,
  });

  render() {
    if (!isResourcePlanningEnabled()) {
      return (
        <PersonaAccessDenied
          moduleName="Resources"
          reason="Resource planning is not enabled for your organization."
        />
      );
    }

    const {
      loading,
      loadError,
      dataSource,
      templates,
      adjustments,
      scenarioName,
      result,
      running,
      staffingRequests,
      benchRecords,
      allocations,
    } = this.state;

    const baseline = result && result.baseline;
    const projected = result && result.projected;
    const comparison = result && result.comparison;
    const insights =
      result && baseline && projected
        ? buildSimulationInsights(baseline, projected, adjustments)
        : [];

    const openDemand = (staffingRequests || [])
      .filter(
        (row) =>
          row.status === STAFFING_REQUEST_STATUSES.PENDING ||
          row.status === STAFFING_REQUEST_STATUSES.APPROVED
      )
      .reduce((sum, row) => sum + (row.headcount || 0), 0);

    const kpiCards = [
      {
        id: "baseline-util",
        label: "Baseline utilization",
        value: baseline ? `${baseline.avgUtilizationPct}%` : "—",
        hint: "Current team snapshot",
        tone: "primary",
        icon: "fe fe-activity",
      },
      {
        id: "projected-util",
        label: "Scenario utilization",
        value: projected ? `${projected.avgUtilizationPct}%` : "—",
        hint: result ? scenarioName || "Custom scenario" : "Run a scenario",
        tone:
          projected && baseline && projected.avgUtilizationPct > baseline.avgUtilizationPct
            ? "amber"
            : "green",
        icon: "fe fe-trending-up",
      },
      {
        id: "demand",
        label: "Open demand",
        value: baseline ? baseline.openDemandHeadcount : openDemand || "—",
        hint: "Roles across open requests",
        tone: "rose",
        icon: "fe fe-users",
      },
      {
        id: "gap",
        label: "Supply gap",
        value: projected ? projected.supplyGap : baseline ? baseline.supplyGap : "—",
        hint: "Demand minus bench supply",
        tone: projected && baseline && projected.supplyGap < baseline.supplyGap ? "green" : "amber",
        icon: "fe fe-alert-triangle",
      },
    ];

    const canRun = !running && adjustments.length > 0;

    return (
      <div
        className="lux-simulation-page lux-register-page lux-simulation-lux"
        data-testid="page-resources-planner"
      >
        <PageDataSourceReporter dataSource={dataSource} />
        <div className="lux-simulation-lux__ambient" aria-hidden="true">
          <span className="lux-simulation-lux__orb lux-simulation-lux__orb--a" />
          <span className="lux-simulation-lux__orb lux-simulation-lux__orb--b" />
        </div>

        <LuxModuleIntro
          meta={DENSE_PAGE_META.capacitySimulation}
          className="lux-simulation-hero"
          actions={
            <ResourcesHeroActions dataSource={dataSource}>
              <ResourcesActionButton
                icon="fe fe-refresh-cw"
                variant="ghost"
                onClick={this.loadContext}
                disabled={loading || running}
              >
                Refresh
              </ResourcesActionButton>
              <ResourcesActionButton to="/project/capacity" icon="fe fe-pie-chart" variant="ghost">
                Team capacity
              </ResourcesActionButton>
              <ResourcesActionButton
                icon="fe fe-play"
                variant="primary"
                disabled={!canRun}
                onClick={() => this.runScenario()}
              >
                {running ? "Running…" : "Run scenario"}
              </ResourcesActionButton>
            </ResourcesHeroActions>
          }
        />

        <div className="lux-simulation-page__body">
          <ResourcesKpiStrip cards={kpiCards} loading={loading} className="lux-simulation-kpi-strip" />

          {loadError && (
            <div className="lux-employee-360__error lux-simulation__error" role="alert">
              <span>{loadError}</span>
              <ResourcesActionButton variant="ghost" onClick={this.loadContext}>
                Retry
              </ResourcesActionButton>
            </div>
          )}

          <AdminInsightStrip insights={insights} className="lux-simulation-insights" />

          <div className="lux-simulation-layout">
            <section className="lux-hrms-dash__panel lux-simulation-panel-wrap">
              <ResourcesSectionHead
                tone="sky"
                icon="fe fe-sliders"
                eyebrow="What-if builder"
                title="Scenario builder"
                subtitle="Templates, adjustments, and the run queue"
                badge={`${adjustments.length} steps`}
              />
              {loading ? (
                <LuxRegisterEmptyState
                  className="lux-register-empty--compact"
                  title="Loading simulation context"
                  description="Pulling capacity, demand, and bench supply."
                />
              ) : (
                <SimulationScenarioPanel
                  templates={templates}
                  adjustments={adjustments}
                  scenarioName={scenarioName}
                  staffingRequests={staffingRequests}
                  benchRecords={benchRecords}
                  allocations={allocations}
                  context={this.getContext()}
                  onAdjustmentsChange={this.handleAdjustmentsChange}
                  onRemoveAdjustment={this.handleRemoveAdjustment}
                  onRun={this.runScenario}
                  running={running}
                />
              )}
            </section>

            <section className="lux-hrms-dash__panel lux-simulation-results-wrap">
              <ResourcesSectionHead
                tone="indigo"
                icon="fe fe-trending-up"
                eyebrow="Impact view"
                title="Impact comparison"
                subtitle="Baseline vs projected capacity metrics"
                badge={result ? "Results ready" : "Awaiting run"}
              />
              <div className="lux-simulation-results__body">
                {!result && !running ? (
                  <LuxRegisterEmptyState
                    className="lux-register-empty--compact"
                    title="No scenario results yet"
                    description="Load a template or add adjustments, then run the scenario."
                    showCreate={canRun}
                    createLabel="Run scenario"
                    createIcon="fe fe-play"
                    onCreate={() => this.runScenario()}
                  />
                ) : (
                  <SimulationCompareStrip comparison={comparison} loading={running} />
                )}
              </div>
            </section>
          </div>
        </div>
      </div>
    );
  }
}

export default CapacitySimulationPage;
