class TimesheetPageInputItem extends Component {
  constructor() {
    super();
    this.pendingScrollTarget = null;
    this.state = {
      hasFormError: false,
      editable: true,
      updateButtonEnabled: false,
      selectedProjects: [],
      detailView: null,
    }
  }

  componentDidMount() {
    //console.log(" this.props.timeSheetRequest")
    //console.log(this.props.timeSheetRequest)
    this.setState({
      //timeSheetRequest: this.props.timeSheetRequest ? this.props.timeSheetRequest :
      // {}
    })
  }

  componentDidUpdate(prevProps) {
    if (this.pendingScrollTarget && this.props.timeSheetRequest !== prevProps.timeSheetRequest) {
      const scrollId = this.pendingScrollTarget;
      this.pendingScrollTarget = null;
      window.requestAnimationFrame(() => {
        const groupEl = document.getElementById(scrollId);
        if (groupEl) {
          groupEl.scrollIntoView({ behavior: "smooth", block: "center" });
          groupEl.classList.add("is-scroll-highlight");
          window.setTimeout(() => groupEl.classList.remove("is-scroll-highlight"), 2400);
        }
        const newEntry = groupEl && groupEl.querySelector(".lux-ts-board__entry.is-new-row");
        if (newEntry) {
          newEntry.classList.add("is-focus-pulse");
          window.setTimeout(() => newEntry.classList.remove("is-focus-pulse"), 2400);
        }
      });
    }
  }

  onAddProjectTaskTimeEntry = (selectedProjectOption, tasksTobeAdded) => { // type :BILLABLE/NONBILLABLE
    this.setState((prevState) =>
    ({
      selectedProjects: {
        ...prevState.selectedProjects,
        [selectedProjectOption.id]: {
          ...selectedProjectOption
        }
      }
    }));

    let tasks = (this.props.timeSheetRequest.project && this.props.timeSheetRequest.project[selectedProjectOption.id] && this.props.timeSheetRequest.project[selectedProjectOption.id].tasks) || []
    // if(tasksTobeAdded && Object.keys(tasksTobeAdded).length > 0) {
    tasks.push(tasksTobeAdded);
    //}
    /*this.setState((prevState) =>
    ({
      timeSheetRequest: {
        ...this.props.timeSheetRequest,
        "project": {
          ...this.props.timeSheetRequest.project,
          [selectedProjectOption.id]: {
            ...this.props.timeSheetRequest.project[selectedProjectOption.id],
            "isNew": (this.props.timeSheetRequest.project[selectedProjectOption.id] && this.props.timeSheetRequest.project[selectedProjectOption.id].isNew) || true,
            "projectName": selectedProjectOption.name,
            "projectCode": selectedProjectOption.code,
            "tasks": tasks
          }
        }
      }
    }), () => {
      //console.log(this.props.timeSheetRequest);
      this.props.onChange(this.props.name, this.props.timeSheetRequest);
    });*/
    this.props.onChange({
      ...this.props.timeSheetRequest,
      "project": {
        ...this.props.timeSheetRequest.project,
        [selectedProjectOption.id]: {
          ...this.props.timeSheetRequest.project[selectedProjectOption.id],
          "isNew": (this.props.timeSheetRequest.project[selectedProjectOption.id] && this.props.timeSheetRequest.project[selectedProjectOption.id].isNew) || true,
          "projectName": selectedProjectOption.name,
          "projectCode": selectedProjectOption.code,
          "tasks": tasks
        }
      }
    });
  }
  onAddNonBillabelCategoryTimeEntry = (categoryName, tasksTobeAdded) => { // type :BILLABLE/NONBILLABLE

    let tasks = (this.props.timeSheetRequest.nonProject && this.props.timeSheetRequest.nonProject[categoryName] && this.props.timeSheetRequest.nonProject[categoryName].tasks) || []
    // if(tasksTobeAdded && Object.keys(tasksTobeAdded).length > 0) {
    tasks.push(tasksTobeAdded);
    //}
    /*this.setState((prevState) =>
    ({
      timeSheetRequest: {
        ...this.props.timeSheetRequest,
        "nonProject": {
          ...this.props.timeSheetRequest.nonProject,
          [categoryName]: {
            ...this.props.timeSheetRequest.nonProject[categoryName],
            "isNew": (this.props.timeSheetRequest.nonProject[categoryName] && this.props.timeSheetRequest.nonProject[categoryName].isNew) || true,
            "tasks": tasks
          }
        }
      }
    }), () => {
      //console.log(this.props.timeSheetRequest);
      this.props.onChange(this.props.name, this.props.timeSheetRequest);
    });*/
    this.props.onChange({
      ...this.props.timeSheetRequest,
      "nonProject": {
        ...this.props.timeSheetRequest.nonProject,
        [categoryName]: {
          ...this.props.timeSheetRequest.nonProject[categoryName],
          "isNew": (this.props.timeSheetRequest.nonProject[categoryName] && this.props.timeSheetRequest.nonProject[categoryName].isNew) || true,
          "tasks": tasks
        }
      }
    });
  }

  onChange = (type, taskGroupItems) => {
    this.setState((prevState) =>
    ({
      /* timeSheetRequest: {
         ...this.props.timeSheetRequest,
         [type]: taskGroupItems
       },*/
      updateButtonEnabled: true,
      hasFormError: false
    }), () => {
      //  //console.log(this.props.timeSheetRequest);
      // this.props.onChange(this.props.name, this.props.timeSheetRequest);
    });
    this.props.onChange({
      ...this.props.timeSheetRequest,
      [type]: taskGroupItems
    });
  }

  onResetFormError = () => {
    this.setState({
      hasFormError: false
    })
  }

  handleUpdateTimeSheet = (afterSaveCallback) => {
    let newTasksValid = true;
    let newTaskCount = 0;
    const timeSheetRequest = this.props.timeSheetRequest;
    TIMESHEET_TYPE_KEYS.forEach((timeSheet) => {
      const section = timeSheetRequest && timeSheetRequest[timeSheet];
      if (!section || typeof section !== "object") return;
      Object.keys(section).forEach((timeSheetItem) => {
        const tasks = section[timeSheetItem] && section[timeSheetItem].tasks;
        if (!tasks) return;
        tasks.forEach((task) => {
          if (task.isNew === true) {
            newTaskCount++;
            if (task.isValid !== true) {
              newTasksValid = false;
            }
          }
        });
      });
    });
    // Existing hour edits have no isNew rows — still allow save.
    // Only block when newly added rows fail validation.
    if (newTaskCount === 0 || newTasksValid) {
      this.props.handleUpdateTimeSheet((payload) => {
        this.toggleEditOption(false);
        if (typeof afterSaveCallback === "function") {
          afterSaveCallback(payload);
        }
      });
    } else {
      this.setState({
        hasFormError: true
      });
    }
  }

  handleSubmitClick = () => {
    if (!this.props.handleSubmitTimesheet) {
      return;
    }
    if (this.state.updateButtonEnabled) {
      // Persist edits first so reopen/resubmit uses the latest hours.
      this.handleUpdateTimeSheet((payload) => {
        this.props.handleSubmitTimesheet(payload);
      });
      return;
    }
    this.props.handleSubmitTimesheet();
  };

  onFormError = (fieldName, hasError) => {
    this.setState(prevState => ({
      formErrors: {
        ...prevState.formErrors,
        [fieldName]: hasError
      }
    }))
  }

  toggleEditOption = (isEdit) => {
    this.setState({
      updateButtonEnabled: isEdit
    })
  }

  resetTimeSheet = () => {
    this.toggleEditOption(false)
    this.props.resetTimeSheet();
  }

  handleAddProjectForTimeEntry = (typeSelectionOption, categorySelectionOption, projectSelectionOption) => {
    if (typeSelectionOption && typeSelectionOption.value === "project") {
      this.pendingScrollTarget = buildGroupScrollId("project", projectSelectionOption.id);
      this.onAddProjectTaskTimeEntry(projectSelectionOption,
        {
          "isNew": true,
          "isValid": false,
          "employeeId": this.props.selectedEmployee.id,
          "userTeamId": this.props.selectedEmployee.userTeamId,
        });
    } else {
      this.pendingScrollTarget = buildGroupScrollId("nonProject", categorySelectionOption.value);
      this.onAddNonBillabelCategoryTimeEntry(categorySelectionOption.value,
        {
          "isNew": true,
          "isValid": false,
          "taskActCategory": categorySelectionOption.value,
          "workItemName": categorySelectionOption.value,
          "employeeId": this.props.selectedEmployee.id,
          "userTeamId": this.props.selectedEmployee.userTeamId,
        })
    }
  }

  openEntryDetail = (payload) => {
    this.setState({ detailView: { kind: "entry", ...payload } });
  };

  openDayDetail = (dateString) => {
    if (!dateString) return;
    this.setState({ detailView: { kind: "day", dateString } });
  };

  closeDetail = () => {
    this.setState({ detailView: null });
  };

  render() {
    const weekDates =
      (this.props.applicableDates && this.props.applicableDates.currentWeekDates) || [];
    const totalByDateMap = buildDailyTotalsMap(this.props.timeSheetRequest, weekDates);
    const weekTotalMins = Object.keys(totalByDateMap).reduce(
      (sum, dateString) => sum + totalByDateMap[dateString].totalMins,
      0
    );
    const hasGroups =
      this.props.timeSheetRequest &&
      TIMESHEET_TYPE_KEYS.some((timesheetType) => {
        const section = this.props.timeSheetRequest[timesheetType];
        return section && typeof section === "object" && Object.keys(section).length > 0;
      });
    const approvalWorkflowActive = isTimesheetApprovalWorkflowActive(
      this.props.timeSheetRequest,
      this.props.permission
    );
    const saveCopy = getSaveDraftCopy(this.props.permission, this.props.timeSheetRequest);
    const weekRejectionComment = getWeekRejectionComment(this.props.timeSheetRequest);
    const lineRejections = collectLineRejections(this.props.timeSheetRequest);
    const showSubmit =
      canSubmitTimesheet(this.props.timeSheetRequest, this.props.permission) &&
      !!this.props.handleSubmitTimesheet;
    const submitLabel = isResubmitAction(this.props.timeSheetRequest)
      ? "Resubmit for approval"
      : "Submit for approval";
    const hasUnsavedChanges = this.state.updateButtonEnabled === true;
    const weekApproved = isTimesheetApproved(this.props.timeSheetRequest);
    const weekReopened =
      isTimesheetReopened(this.props.timeSheetRequest) &&
      wasTimesheetPreviouslyApproved(this.props.timeSheetRequest);

    return (
      <div
        className={classNames("lux-ts-board timesheetpage", {
          "has-pending-save": this.state.updateButtonEnabled,
          "is-approval-workflow": approvalWorkflowActive,
        })}
      >
        {this.state.editable && (
          <TimesheetAddEntryModal
            key={this.props.addEntrySession}
            show={this.props.showSelectionWindow}
            cancelShowSelectionWindow={this.props.cancelShowSelectionWindow}
            handleAddProjectForTimeEntry={this.handleAddProjectForTimeEntry}
            selectedEmployee={this.props.selectedEmployee}
            startOfTheWeek={this.props.startOfTheWeek}
            permission={this.props.permission}
          />
        )}

        {approvalWorkflowActive && (
          <div className="lux-ts-board__workflow" role="region" aria-label="Timesheet approval">
            {isTimesheetRejected(this.props.timeSheetRequest) && weekRejectionComment && (
              <div className="lux-ts-board__rejection-notice is-week" role="alert">
                <i className="fe fe-x-circle" aria-hidden="true" />
                <div>
                  <strong>Manager rejection</strong>
                  <p>{weekRejectionComment}</p>
                </div>
              </div>
            )}
            {lineRejections.map((row) => (
              <div key={row.key} className="lux-ts-board__rejection-notice is-line" role="alert">
                <i className="fe fe-message-square" aria-hidden="true" />
                <div>
                  <strong>{row.label}</strong>
                  <p>{row.comment}</p>
                </div>
              </div>
            ))}
            {isTimesheetPendingApproval(this.props.timeSheetRequest) && (
              <div className="lux-ts-board__workflow-status is-pending">
                <i className="fe fe-clock" aria-hidden="true" />
                <span>
                  {this.props.canReviewPendingWeek
                    ? "This week is awaiting your approval — use Pending approvals above to Approve or Reject."
                    : "Awaiting manager approval — edits are locked until rejected or reopened."}
                </span>
              </div>
            )}
            {weekApproved && (
              <div className="lux-ts-board__workflow-status is-approved">
                <i className="fe fe-check-circle" aria-hidden="true" />
                <span>
                  This week is approved — Submit is hidden. Hours post to work items only when approved.
                  Dotted “Not posted” cells were saved after approval and need the approver to reopen + resubmit to post.
                </span>
              </div>
            )}
            {weekReopened && (
              <div className="lux-ts-board__workflow-status is-reopened">
                <i className="fe fe-rotate-ccw" aria-hidden="true" />
                <span>
                  Previously approved timesheet reopened — edit hours, save draft, then resubmit for approval.
                </span>
              </div>
            )}
            {isTimesheetPendingApproval(this.props.timeSheetRequest) &&
              this.props.timeSheetRequest &&
              this.props.timeSheetRequest.weekId &&
              this.props.selectedEmployee &&
              this.props.selectedEmployee.id && (
                <div className="lux-ts-board__workflow-remind">
                  <ApprovalRemindApproverButton
                    visible={true}
                    requestType="TIMESHEET"
                    referenceId={this.props.timeSheetRequest.weekId}
                    employeeId={this.props.selectedEmployee.id}
                    permission={this.props.permission}
                  />
                </div>
              )}
            {showSubmit && (
              <div className="lux-ts-board__workflow-actions">
                <div className="lux-ts-board__workflow-status is-draft">
                  <i className={`fe ${hasUnsavedChanges ? "fe-save" : "fe-edit-3"}`} aria-hidden="true" />
                  <span>
                    {hasUnsavedChanges
                      ? "You have unsaved edits — Resubmit will save your draft and send it for approval."
                      : "Draft saved — submit when this week is ready for approval."}
                  </span>
                </div>
                <button
                  type="button"
                  className="lux-ts-board__workflow-btn"
                  onClick={this.handleSubmitClick}
                  disabled={this.props.submitInProgress === true}
                >
                  <i className="fe fe-send" aria-hidden="true" />
                  {this.props.submitInProgress ? "Submitting…" : submitLabel}
                </button>
              </div>
            )}
            {!showSubmit &&
              approvalWorkflowActive &&
              this.props.timeSheetRequest &&
              this.props.timeSheetRequest.weekId &&
              ["DRAFT", "REOPENED", "REJECTED"].includes(
                getTimesheetWeekStatus(this.props.timeSheetRequest)
              ) &&
              hasUnsavedChanges && (
                <div className="lux-ts-board__workflow-status is-draft">
                  <i className="fe fe-save" aria-hidden="true" />
                  <span>Save your draft first — Submit appears after unsaved changes are saved.</span>
                </div>
              )}
          </div>
        )}

        {this.props.intelligenceEnabled && (
          <TimesheetRecommendationPanel
            recommendation={this.props.recommendation}
            loading={this.props.recommendationLoading}
            compact
          />
        )}

        {weekDates.length > 0 && (
          <TimesheetWeekRail
            weekDates={weekDates}
            maxHoursAllowed={this.props.permission.maxHoursAllowedToEnter}
            sticky
            onDayClick={this.openDayDetail}
          />
        )}

        <div className="lux-ts-board__body">
          {!hasGroups && (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              variant="timesheet"
              eyebrow="Weekly timesheet"
              title="No entries this week"
              description="You have not logged time for this week yet. Add project or non-project hours across the days in the rail above."
              hints={[
                "Tap a day in the week rail to review or add hours",
                "Project and leave entries appear in separate groups",
              ]}
              createLabel="Add entry"
              onCreate={this.props.onOpenAddEntry}
              showCreate={this.state.editable && Boolean(this.props.onOpenAddEntry)}
              createDisabled={this.props.addEntryOpen === true}
            />
          )}

          {hasGroups &&
            this.props.timeSheetRequest &&
            TIMESHEET_TYPE_KEYS.map((timesheetType) => {
              const taskGroupItems = this.props.timeSheetRequest[timesheetType];
              if (!taskGroupItems || typeof taskGroupItems !== "object") {
                return null;
              }
              return (
              <TimesheetPageTaskGroupInputItem
                key={timesheetType}
                permission={this.props.permission}
                selectedEmployee={this.props.selectedEmployee}
                editable={this.state.editable}
                onChange={this.onChange}
                taskGroupItems={taskGroupItems}
                timesheetType={timesheetType}
                projectsForTimesheet={this.props.projectsForTimesheet}
                selectedProjects={this.state.selectedProjects}
                applicableDates={this.props.applicableDates}
                nonProjectAppConfig={this.props.nonProjectAppConfig}
                nonProjectFieldConfig={this.props.nonProjectFieldConfig}
                projectFieldConfig={this.props.projectFieldConfig}
                allUserTeams={this.props.allUserTeams}
                allProjectTeamAccounts={
                  this.props.allProjectTeamAccounts || this.props.allProjectAccounts
                }
                onOpenEntryDetail={this.openEntryDetail}
                onDayClick={this.openDayDetail}
              />
              );
            })}
        </div>

        {hasGroups && weekDates.length > 0 && (
          <TimesheetBoardFooter
            weekDates={weekDates}
            totalByDateMap={totalByDateMap}
            weekTotalMins={weekTotalMins}
            maxHoursAllowed={this.props.permission.maxHoursAllowedToEnter}
            onDayClick={this.openDayDetail}
          />
        )}

        <TimesheetEntryDetailModal
          show={this.state.detailView && this.state.detailView.kind === "entry"}
          payload={this.state.detailView}
          timeSheetRequest={this.props.timeSheetRequest}
          weekDates={weekDates}
          onClose={this.closeDetail}
        />
        <TimesheetDayDetailModal
          show={this.state.detailView && this.state.detailView.kind === "day"}
          dateString={this.state.detailView && this.state.detailView.dateString}
          timeSheetRequest={this.props.timeSheetRequest}
          weekDates={weekDates}
          onClose={this.closeDetail}
        />

        {this.state.editable && this.state.updateButtonEnabled && !weekApproved && (
          <div className="lux-ts-board__save-bar" role="region" aria-label="Save timesheet changes">
            {this.state.hasFormError && (
              <div className="lux-ts-board__save-error">
                <i className="fa fa-exclamation-triangle" aria-hidden="true" />
                <span>Please complete all mandatory fields before saving.</span>
                <button
                  type="button"
                  className="lux-ts-board__save-error-dismiss"
                  onClick={this.onResetFormError}
                  aria-label="Dismiss"
                />
              </div>
            )}
            <div className="lux-ts-board__save-bar-inner">
              <div className="lux-ts-board__save-copy">
                <strong>{saveCopy.title}</strong>
                <span>{saveCopy.body}</span>
              </div>
              <div className="lux-ts-board__save-actions">
                <button
                  type="button"
                  className="lux-ts-board__save-btn lux-ts-board__save-btn--ghost"
                  onClick={this.resetTimeSheet}
                >
                  Discard
                </button>
                <button
                  type="button"
                  className="lux-ts-board__save-btn lux-ts-board__save-btn--primary"
                  onClick={this.handleUpdateTimeSheet}
                >
                  <i className="fe fe-check" aria-hidden="true" />
                  {saveCopy.buttonLabel}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    );
  }
}

class TimesheetPageTaskGroupInputItem extends Component {

  constructor() {
    super();
    this.state = {
    }
  }

  removeProjectFromTimesheet = (itemTobeRemoved) => {
    //console.log("removeProjectFromTimesheet " + itemTobeRemoved)
    let taskGroupItemsUpdated = { ...this.props.taskGroupItems };
    delete taskGroupItemsUpdated[itemTobeRemoved];
    this.props.onChange(this.props.timesheetType, taskGroupItemsUpdated);
  }

  addTaskToTimeSheetTimesheet = (groupId) => {
    let taskList = this.props.taskGroupItems[groupId].tasks;
    let newTask = null;
    if (this.props.timesheetType === "project") {
      newTask = {
        "isNew": true,
        "isValid": false,
        "employeeId": this.props.selectedEmployee.id,
        "userTeamId": this.props.selectedEmployee.userTeamId,
      }
    } else {
      newTask = {
        "isNew": true,
        "isValid": false,
        "taskActCategory": groupId,
        "workItemName": groupId,
        "employeeId": this.props.selectedEmployee.id,
        "userTeamId": this.props.selectedEmployee.userTeamId,
      }
    }
    taskList.push(newTask);
    this.onChange(groupId, taskList);

  }

  onChange = (groupId, timeSheetTaskList, isValidObject) => {

    const taskGroupItemsUpdated = {
      ...this.props.taskGroupItems,
      [groupId]: {
        ...this.props.taskGroupItems[groupId],
        "tasks": timeSheetTaskList
      }
    }
    this.props.onChange(this.props.timesheetType, taskGroupItemsUpdated, isValidObject);

  }

  render() {
    const taskGroupItems = this.props.taskGroupItems;
    if (!taskGroupItems || typeof taskGroupItems !== "object") {
      return null;
    }
    return (
      Object.keys(taskGroupItems).map(taskGroupId => {
        let timeEntryTaskSection = taskGroupItems[taskGroupId];
        if (!timeEntryTaskSection || typeof timeEntryTaskSection !== "object") {
          return null;
        }
        const isLeaveGroup = (taskGroupId || "").toLowerCase() === "leave";
        const isHolidayGroup = (taskGroupId || "").toLowerCase() === "holiday";
        return (
          <section
            id={buildGroupScrollId(this.props.timesheetType, taskGroupId)}
            className={classNames("lux-ts-board__group", {
              "is-project": this.props.timesheetType === "project",
              "is-non-project": this.props.timesheetType === "nonProject",
              "lux-ts-board__group--leave": isLeaveGroup,
              "lux-ts-board__group--holiday": isHolidayGroup,
            })}
            key={taskGroupId}
          >
            <header className="lux-ts-board__group-head">
              <div className="lux-ts-board__group-id">
                {this.props.timesheetType === "project" && (
                  <>
                    <span className="lux-ts-board__group-badge is-billable">Billable</span>
                    <strong className="lux-ts-board__group-code">
                      {timeEntryTaskSection.projectCode || "PROJECT"}
                    </strong>
                    <span className="lux-ts-board__group-name">{timeEntryTaskSection.projectName}</span>
                  </>
                )}
                {this.props.timesheetType === "nonProject" && (
                  <>
                    {isLeaveGroup && (
                      <span className="lux-ts-board__group-badge is-leave">
                        <i className="fe fe-sun" aria-hidden="true" /> Leave
                      </span>
                    )}
                    {isHolidayGroup && (
                      <span className="lux-ts-board__group-badge is-holiday">
                        <i className="fe fe-flag" aria-hidden="true" /> Holiday
                      </span>
                    )}
                    {!isLeaveGroup && !isHolidayGroup && (
                      <span className="lux-ts-board__group-badge is-non-billable">Non-billable</span>
                    )}
                    <strong className="lux-ts-board__group-name">{taskGroupId}</strong>
                  </>
                )}
              </div>
              <div className="lux-ts-board__group-actions">
                {timeEntryTaskSection.isNew && (
                  <>
                    <button
                      type="button"
                      className="lux-ts-board__icon-btn"
                      title="Add task row"
                      onClick={() => this.addTaskToTimeSheetTimesheet(taskGroupId)}
                    >
                      <i className="fe fe-plus" aria-hidden="true" />
                    </button>
                    <button
                      type="button"
                      className="lux-ts-board__icon-btn is-danger"
                      title="Remove group"
                      onClick={() => this.removeProjectFromTimesheet(taskGroupId)}
                    >
                      <i className="fe fe-x" aria-hidden="true" />
                    </button>
                  </>
                )}
              </div>
            </header>
            <div className="lux-ts-board__group-body">
              <TimeSheetTaskListInput
                permission={this.props.permission}
                timesheetType={this.props.timesheetType}
                selectedEmployee={this.props.selectedEmployee}
                timeSheetTaskList={timeEntryTaskSection.tasks}
                selectedProject={this.props.selectedProjects && this.props.selectedProjects[taskGroupId]}
                taskGroupId={taskGroupId}
                applicableDates={this.props.applicableDates}
                nonProjectAppConfig={this.props.nonProjectAppConfig}
                nonProjectFieldConfig={this.props.nonProjectFieldConfig}
                projectFieldConfig={this.props.projectFieldConfig}
                allUserTeams={this.props.allUserTeams}
                allProjectTeamAccounts={this.props.allProjectTeamAccounts}
                onChange={this.onChange}
                onOpenEntryDetail={this.props.onOpenEntryDetail}
                onDayClick={this.props.onDayClick}
              />
            </div>
          </section>
        );
      })
    );
  }
}

class TimeSheetTaskListInput extends Component {
  constructor() {
    super();
    this.state = {
      timeSheetTaskList: []
    }
  }
  componentDidMount() {
    this.setState({
      // timeSheetTaskList: this.props.timeSheetTaskList
    })
  }
  removeTaskFromTimesheet = (taskIndexTobeRemoved) => {
    //console.log("removeTaskFromTimesheet " + taskIndexTobeRemoved)
    let timeSheetTaskListUpdated = this.props.timeSheetTaskList;
    timeSheetTaskListUpdated.splice(taskIndexTobeRemoved, 1);

    //console.log(timeSheetTaskListUpdated);
    //console.log("this.props.taskGroupId " + this.props.taskGroupId)
    this.props.onChange(this.props.taskGroupId, timeSheetTaskListUpdated, { [taskIndexTobeRemoved]: true });

  }

  onChange = (updatedTimeSheetTaskItem, index) => {

    let timeSheetTaskListUpdated = this.props.timeSheetTaskList;
    timeSheetTaskListUpdated[index] = updatedTimeSheetTaskItem;
    this.props.onChange(this.props.taskGroupId, timeSheetTaskListUpdated);

  }

  render() {

    return (
      this.props.timeSheetTaskList && this.props.timeSheetTaskList.map((timeSheetTaskItem, index) =>
        <TimeSheetTaskItem key={index}
          timesheetType={this.props.timesheetType}
          selectedEmployee={this.props.selectedEmployee}
          permission={this.props.permission}
          timeSheetTaskItem={timeSheetTaskItem}
          selectedProject={this.props.selectedProject}
          nonProjectAppConfig={this.props.nonProjectAppConfig}
          nonProjectFieldConfig={this.props.nonProjectFieldConfig}
          projectFieldConfig={this.props.projectFieldConfig}
          allUserTeams={this.props.allUserTeams}
          applicableDates={this.props.applicableDates}
          taskIndex={index}
          taskGroupId={this.props.taskGroupId}
          removeTaskFromTimesheet={this.removeTaskFromTimesheet}
          allProjectTeamAccounts={this.props.allProjectTeamAccounts}
          onChange={this.onChange}
          onOpenEntryDetail={this.props.onOpenEntryDetail}
          onDayClick={this.props.onDayClick}
        />
      )
    )
  }
}

class TimeSheetTaskItem extends Component {
  constructor() {
    super();
    this.state = {
      timeSheetTaskItem: {},
      selectedDeliverableOption: null,
      formErrors: {},
      disableDeliveryOptionSelection: false
    }
  }

  onTimeEntryValueChange = (valueInHours, dateString) => {
    if (!validationUtils.validateDecimalNumberic(valueInHours) || (valueInHours && this.props.permission.maxHoursAllowedToEnter < parseFloat(valueInHours) || (parseFloat(valueInHours) - parseInt(valueInHours) > .59))) {
      return;
    }
    let valueInMins = 0;
    if (valueInHours !== "") {
      valueInMins = (parseInt(valueInHours) * 60) + (Math.round((parseFloat(valueInHours) - parseInt(valueInHours)) * 100));
    }
    let timeEntry = {}
    if (this.props.timeSheetTaskItem && this.props.timeSheetTaskItem.timeEntry) {
      timeEntry = this.props.timeSheetTaskItem.timeEntry;
      if (!this.props.timeSheetTaskItem.timeEntry[dateString]) {
        timeEntry = {
          ...timeEntry,
          [dateString]: {
            "isNew": true
          }
        }
      } else {
        timeEntry = {
          ...timeEntry,
          [dateString]: {
            ...timeEntry[dateString],
            "isUpdated": true
          }
        }
      }
    } else {
      timeEntry = {
        [dateString]: {
          "isNew": true
        }
      }
    }

    const timeSheetTaskItemUpdated = {
      ...this.props.timeSheetTaskItem,
      "timeEntry": {
        ...timeEntry,
        [dateString]: {
          ...timeEntry[dateString],
          "timesheetTimeMins": valueInMins,
          "timesheetTimeHours": valueInHours
        }
      }
    }

    this.setState({
      disableDeliveryOptionSelection: true
    })

    this.onChange(timeSheetTaskItemUpdated, this.props.taskIndex);

  }

  onAdditionalFieldValueChange = (name, value, dateString) => {

    const timeSheetTaskItemUpdated = {
      ...this.props.timeSheetTaskItem,
      "timeEntry": {
        ...this.props.timeSheetTaskItem.timeEntry,
        [dateString]: {
          ...this.props.timeSheetTaskItem.timeEntry[dateString],
          [name]: value
        }
      }
    }
    this.onChange(timeSheetTaskItemUpdated, this.props.taskIndex);
  }

  onFormError = (fieldName, hasError) => {
    this.setState(prevState => ({
      formErrors: {
        ...prevState.formErrors,
        [fieldName]: hasError
      }
    }))
  }

  getNonBillableFieldConfig = () => {
    return this.state.timeSheetTaskItem && workItemUtils.filterNonMandatoryFields(this.props.nonProjectFieldConfig, this.props.timeSheetTaskItem.taskActCategory, this.props.nonProjectAppConfig);
  }
  onChange = (timeSheetTaskItem, index) => {

    const fieldConfig = this.props.timesheetType === "project" ? this.props.projectFieldConfig : this.getNonBillableFieldConfig();
    let isValid = validationUtils.isValidRequest(fieldConfig, timeSheetTaskItem, this.state.formErrors);

    timeSheetTaskItem = {
      ...timeSheetTaskItem,
      "isValid": isValid
    }
    this.props.onChange(timeSheetTaskItem, index);
  }

  onFieldValueChange = (name, value) => {

    let workItemName = this.props.timeSheetTaskItem.workItemName;
    let taskActCategory = this.props.timeSheetTaskItem.taskActCategory;
    if (name === 'taskActCategory') {
      workItemName = value;
    }
    if (name === 'taskId') {
      taskActCategory = null;
    }
    let timeSheetTaskItemUpdated = {
      ...this.props.timeSheetTaskItem,
      "workItemName": workItemName,
      "taskActCategory": taskActCategory,
      [name]: value,
    }

    this.onChange(timeSheetTaskItemUpdated, this.props.taskIndex);
  }
  addAdditionalTaskDetails = (dateString, additionalTaskDetails) => {

    const timeSheetTaskItemUpdated = {
      ...this.props.timeSheetTaskItem,
      "timeEntry": {
        ...this.props.timeSheetTaskItem.timeEntry,
        [dateString]: {
          ...this.props.timeSheetTaskItem.timeEntry[dateString],
          ...additionalTaskDetails
        }
      }
    }
    this.onChange(timeSheetTaskItemUpdated, this.props.taskIndex);

  }

  convertMinsToHours = (timeInMins) => {
    if (timeInMins && timeInMins !== '') {
      return (Math.floor(timeInMins / 60) + ((timeInMins % 60) / 100)).toFixed(2);
    }
    return '';
  }
  isCreateDateEnabled = (dateString) => {
    let workItemStartDate = "";
    let workItemEndDate = "";
    if (this.props.timesheetType === "nonProject") {
      if (this.props.taskGroupId.toLowerCase() === 'leave' || this.props.taskGroupId.toLowerCase() === 'holiday') {
        if (this.props.permission.allowLeaveAndHolidayForPast) {
          workItemStartDate = this.props.applicableDates.workItemMinDates.actualStartDate;
        } else {
          workItemStartDate = this.props.applicableDates.workItemMinDates.nonProjectStart;
        }
        if (this.props.permission.allowLeaveAndHolidayForFuture) {
          workItemEndDate = this.props.applicableDates.workItemMaxDates.actualEndDate;
        } else {
          workItemEndDate = this.props.applicableDates.workItemMaxDates.nonProjectEnd;
        }
      } else {
        workItemStartDate = this.props.applicableDates.workItemMinDates.nonProjectStart;
        workItemEndDate = this.props.applicableDates.workItemMaxDates.nonProjectEnd;
      }
    } else if (this.props.timesheetType === "project") {
      workItemStartDate = this.props.applicableDates.workItemMinDates.projectStart;
      workItemEndDate = this.props.applicableDates.workItemMaxDates.projectEnd;

      if (this.state.selectedDeliverableOption && this.state.selectedDeliverableOption.estStartTime) {
        const deliverableEstStartTime = dateUtils.convertDateStringToMoment(this.state.selectedDeliverableOption.estStartTime).clone().startOf('day');
        if (workItemStartDate.diff(deliverableEstStartTime) < 0) {
          workItemStartDate = deliverableEstStartTime
        }
      }
      if (this.state.selectedDeliverableOption && this.state.selectedDeliverableOption.estCompletionTime) {
        const deliverableEstCompletionTime = dateUtils.convertDateStringToMoment(this.state.selectedDeliverableOption.estCompletionTime).clone().endOf('day');
        if (workItemEndDate.diff(deliverableEstCompletionTime) > 0) {
          workItemEndDate = deliverableEstCompletionTime
        }
      }
    }

    let momentDate = dateUtils.convertDateStringToMoment(dateString).clone().startOf("day");

    return momentDate.diff(workItemStartDate) >= 0 && momentDate.diff(workItemEndDate) <= 0;

  }

  onDeliveryFieldValueChange = (fieldName, selectedDeliverableOption) => {
    if (this.state.disableDeliveryOptionSelection === false) {
      this.setState(prev => ({
        selectedDeliverableOption: selectedDeliverableOption
      }), () => {
        this.props.onChange(this.props.timeSheetTaskItem, this.props.taskIndex);
      }
      );
      this.onFieldValueChange(fieldName, selectedDeliverableOption.id)
    } else {
      store.dispatch(notificationActions.warning("Once a timesheet entry is added, deliverables cannot be altered."));
    }
  }

  getRestrictedSkillOptions = () => {
    let employeeSkills = commonUtils.getEmployeeSkills(this.props.selectedEmployee);
    const restrictedByEmployeeSkills = this.state.selectedDeliverableOption && this.state.selectedDeliverableOption.restrictedByEmployeeSkills;

    if (this.props.permission.restrictedBySkillsEnabled === true && restrictedByEmployeeSkills && employeeSkills) {
      employeeSkills = employeeSkills.filter(skill => restrictedByEmployeeSkills.includes(skill));
    }
    return commonUtils.convertConfigListToSelectObject(employeeSkills);
  }

  render() {
    let timeEntry = (this.props.timeSheetTaskItem && this.props.timeSheetTaskItem.timeEntry) || {};
    const weekDates =
      (this.props.applicableDates && this.props.applicableDates.currentWeekDates) || [];
    const rowTotalMins = computeEntryWeekTotalMins(this.props.timeSheetTaskItem, weekDates);
    const groupKeyLower = (this.props.taskGroupId || "").toLowerCase();
    const isLeaveRow =
      getLeaveHolidayKind(this.props.taskGroupId, this.props.timeSheetTaskItem.taskActCategory) === "leave";
    const isHolidayRow =
      getLeaveHolidayKind(this.props.taskGroupId, this.props.timeSheetTaskItem.taskActCategory) === "holiday";
    const isEditingRow =
      (this.props.timesheetType === "project" && !this.props.timeSheetTaskItem.taskName) ||
      (this.props.timesheetType === "nonProject" &&
        this.props.timeSheetTaskItem.isNew === true &&
        groupKeyLower !== "holiday" &&
        groupKeyLower !== "leave");
    const needsHours = isEditingRow && rowTotalMins === 0;

    const openEntryDetail = () => {
      if (!this.props.onOpenEntryDetail || isEditingRow) return;
      this.props.onOpenEntryDetail({
        timesheetType: this.props.timesheetType,
        taskGroupId: this.props.taskGroupId,
        taskIndex: this.props.taskIndex,
      });
    };

    const handleDayInspect = (dateString, event) => {
      if (!this.props.onDayClick) return;
      // Day/entry detail popups open from task name (or footer), not from hour/comment cells while editing.
      if (event.target.closest("input, button, textarea, select, .lux-ts-comments-pop, .lux-ts-board__hour-input")) {
        return;
      }
      this.props.onDayClick(dateString);
    };

    return (
      <article
        className={classNames("lux-ts-board__entry", "lux-ts-board__grid-row", {
          "lux-ts-board__entry--leave": isLeaveRow,
          "lux-ts-board__entry--holiday": isHolidayRow,
          "is-new-row": this.props.timeSheetTaskItem.isNew === true,
          "is-editing": isEditingRow,
          "needs-hours": needsHours,
          "has-hours": rowTotalMins > 0,
        })}
      >
        <div className="lux-ts-board__entry-meta lux-ts-board__col-meta">
          {isEditingRow && (
            <div className="lux-ts-board__section-label">
              <span className="lux-ts-board__section-step">1</span>
              Work details
            </div>
          )}
          {this.props.timesheetType === "project" && this.props.timeSheetTaskItem.taskName && (
            <button
              type="button"
              className="lux-ts-board__line lux-ts-board__line-btn"
              title={`${this.props.timeSheetTaskItem.taskName} · ${this.props.timeSheetTaskItem.taskActCategory} · ${this.props.timeSheetTaskItem.workItemName}`}
              onClick={openEntryDetail}
            >
              <strong>{this.props.timeSheetTaskItem.taskName}</strong>
              <span className="lux-ts-board__line-sep">·</span>
              <span>{this.props.timeSheetTaskItem.taskActCategory}</span>
              <span className="lux-ts-board__line-sep">·</span>
              <span className="lux-ts-board__line-muted">{this.props.timeSheetTaskItem.workItemName}</span>
              <i className="fe fe-maximize-2 lux-ts-board__line-icon" aria-hidden="true" />
            </button>
          )}
          {this.props.timesheetType === "project" && !this.props.timeSheetTaskItem.taskName && (
            <ProjectTaskSelector
              selectedProject={this.props.selectedProject}
              selectedDeliverableOption={this.state.selectedDeliverableOption}
              onDeliveryFieldValueChange={this.onDeliveryFieldValueChange}
              permission={this.props.permission}
              selectedEmployee={this.props.selectedEmployee}
              projectAppConfig={this.state.projectAppConfig}
              projectFieldConfig={this.props.projectFieldConfig}
              timeSheetTaskItem={this.props.timeSheetTaskItem}
              onFieldValueChange={this.onFieldValueChange}
              onFormError={this.onFormError}
            />
          )}
          {this.props.timesheetType === "nonProject" &&
            ((this.props.timeSheetTaskItem.isNew === undefined ||
              !this.props.timeSheetTaskItem.isNew) ||
              groupKeyLower === "holiday" ||
              groupKeyLower === "leave") && (
              <button
                type="button"
                className="lux-ts-board__line lux-ts-board__line-btn"
                title={[
                  this.props.timeSheetTaskItem.workItemName,
                  this.props.timeSheetTaskItem.division,
                  this.props.timeSheetTaskItem.account,
                  this.props.timeSheetTaskItem.requestingTeamName,
                ]
                  .filter(Boolean)
                  .join(" · ")}
                onClick={openEntryDetail}
              >
                <strong>{this.props.timeSheetTaskItem.workItemName || "—"}</strong>
                {(this.props.timeSheetTaskItem.division ||
                  this.props.timeSheetTaskItem.account ||
                  this.props.timeSheetTaskItem.requestingTeamName) && (
                  <>
                    <span className="lux-ts-board__line-sep">·</span>
                    <span className="lux-ts-board__line-muted">
                      {[
                        this.props.timeSheetTaskItem.division,
                        this.props.timeSheetTaskItem.account,
                        this.props.timeSheetTaskItem.requestingTeamName,
                      ]
                        .filter(Boolean)
                        .join(" · ")}
                    </span>
                  </>
                )}
                <i className="fe fe-maximize-2 lux-ts-board__line-icon" aria-hidden="true" />
              </button>
            )}
          {isEditingRow && this.props.timesheetType === "nonProject" && (
            <NonProjectTaskSelector
              nonProjectAppConfig={this.props.nonProjectAppConfig}
              getNonBillableFieldConfig={this.getNonBillableFieldConfig}
              allUserTeams={this.props.allUserTeams}
              timeSheetTaskItem={this.props.timeSheetTaskItem}
              allProjectTeamAccounts={this.props.allProjectTeamAccounts}
              onFieldValueChange={this.onFieldValueChange}
              onFormError={this.onFormError}
            />
          )}
        </div>

        {isEditingRow && (
          <div className="lux-ts-board__hours-row-label lux-ts-board__col-meta">
            <span className="lux-ts-board__section-step">2</span>
            Enter hours
            {needsHours && <span className="lux-ts-board__section-hint">Required</span>}
          </div>
        )}

        {weekDates.map((dateString, dayIndex) => {
            let timeInMins =
              (timeEntry && timeEntry[dateString] && timeEntry[dateString].timesheetTimeMins) || "";
            let timeInHours =
              (timeEntry && timeEntry[dateString] && timeEntry[dateString].timesheetTimeHours) ||
              null;
            const dayMeta = getDayHeaderMeta(dateString);
            const minsNum = parseInt(timeInMins || 0, 10);
            const hourLevel = getHourLevelFromMins(minsNum);
            const dateEnabled = this.isCreateDateEnabled(dateString);
            const cellEntry = (timeEntry && timeEntry[dateString]) || null;
            const hasProjectOrNonProjectContext =
              this.props.timesheetType === "nonProject" ||
              !!this.state.selectedDeliverableOption ||
              !!this.props.timeSheetTaskItem.taskName ||
              !!this.props.timeSheetTaskItem.taskId;
            const canEdit =
              hasProjectOrNonProjectContext &&
              dateEnabled &&
              isTimesheetCellEditable(cellEntry, this.props.timeSheetTaskItem.isNew === true);
            const isReadonlyLocked = isTimesheetCellReadonly(
              cellEntry,
              this.props.timeSheetTaskItem.isNew === true
            );
            const cellBadges = getTimesheetCellBadges(cellEntry);
            const showCommentsControl = minsNum > 0 && (canEdit || isReadonlyLocked);
            // While editing hours, do not open day-detail from the cell — only task name opens row detail.
            const dayInspectEnabled = !!this.props.onDayClick && !canEdit;

            const commentsPopover = showCommentsControl ? (
              <TimesheetCommentsPopover
                selectedEmployeeOption={this.props.selectedEmployee}
                selectedDeliverableOption={this.state.selectedDeliverableOption}
                permission={this.props.permission}
                timesheetType={this.props.timesheetType}
                onFieldValueChange={this.onAdditionalFieldValueChange}
                dateString={dateString}
                timeEntryValues={timeEntry[dateString] || cellEntry}
                projectFieldConfig={this.props.projectFieldConfig}
                onFormError={this.onFormError}
                getRestrictedSkillOptions={this.getRestrictedSkillOptions}
                readOnly={!canEdit}
              />
            ) : null;

            return (
              <div
                key={dateString}
                className={classNames(
                  "lux-ts-board__day-slot",
                  getTimesheetDayColumnClass(dayIndex),
                  getTimesheetCellClassNames(cellEntry, this.props.timeSheetTaskItem.isNew === true, {
                    "is-today": dayMeta.isToday,
                    "is-weekend": dayMeta.isSaturday || dayMeta.isSunday,
                    "is-disabled": !dateEnabled,
                    "has-value": minsNum > 0,
                    "is-editable-empty": canEdit && minsNum === 0,
                    "is-inspectable": dayInspectEnabled,
                    [`is-level-${hourLevel}`]: minsNum > 0,
                  })
                )}
                onClick={
                  dayInspectEnabled
                    ? (event) => handleDayInspect(dateString, event)
                    : undefined
                }
                onKeyDown={
                  dayInspectEnabled
                    ? (event) => {
                        if (
                          event.target.closest(
                            "input, button, textarea, select, .lux-ts-comments-pop, .lux-ts-board__hour-input"
                          )
                        ) {
                          return;
                        }
                        if (event.key === "Enter" || event.key === " ") {
                          event.preventDefault();
                          handleDayInspect(dateString, event);
                        }
                      }
                    : undefined
                }
                role={dayInspectEnabled ? "button" : undefined}
                tabIndex={dayInspectEnabled ? 0 : undefined}
                title={dayInspectEnabled ? `View ${dayMeta.dayShort} summary` : undefined}
              >
                <div className="lux-ts-board__day-slot-body">
                  {canEdit && (
                    <>
                      <input
                        type="text"
                        onChange={(e) => this.onTimeEntryValueChange(e.target.value, dateString)}
                        className="form-control lux-ts-board__hour-input state-valid"
                        value={timeInHours || this.convertMinsToHours(timeInMins)}
                        aria-label={`${dayMeta.dayShort} ${dateString}`}
                        placeholder="—"
                      />
                      {commentsPopover}
                    </>
                  )}
                  {isReadonlyLocked && (
                    <>
                      <span className="lux-ts-board__hour-readonly">
                        {timeInHours || this.convertMinsToHours(timeInMins)}
                      </span>
                      {commentsPopover}
                    </>
                  )}
                  {!canEdit && !isReadonlyLocked && (
                    <span className="lux-ts-board__hour-empty" aria-hidden="true">
                      —
                    </span>
                  )}
                  {cellBadges.length > 0 && (
                    <div className="lux-ts-board__cell-badges" aria-hidden="true">
                      {cellBadges.map((badge) => (
                        <span
                          key={badge.key}
                          className={classNames(
                            "lux-ts-board__cell-badge",
                            `is-tone-${badge.tone}`
                          )}
                          title={badge.title}
                        >
                          <i className={`fe ${badge.icon}`} aria-hidden="true" />
                          <span>{badge.label}</span>
                        </span>
                      ))}
                    </div>
                  )}
                </div>
              </div>
            );
          })}

        <div className="lux-ts-board__entry-tools lux-ts-board__col-tools">
          <span
            className={classNames("lux-ts-board__entry-total", {
              "has-value": rowTotalMins > 0,
            })}
          >
            {formatEntryTotalLabel(rowTotalMins)}
          </span>
          {this.props.timeSheetTaskItem.isNew && (
            <button
              type="button"
              className="lux-ts-board__icon-btn is-danger is-compact"
              title="Remove row"
              onClick={() => this.props.removeTaskFromTimesheet(this.props.taskIndex)}
            >
              <i className="fe fe-trash-2" aria-hidden="true" />
            </button>
          )}
        </div>
      </article>
    );
  }
}

class ProjectTaskSelector extends Component {
  constructor() {
    super();
    this.state = {

    }
  }
  processProjectModuleData = (moduleConfig) => {
    this.setState({
      projectAppConfig: moduleConfig
    })
  }

  componentDidMount() {
    if (this.props.selectedProject) {
      store.dispatch(projectActions.getModuleConfigData(this.props.selectedEmployee.userTeamId, this.processProjectModuleData))
    }
  }
  getRestrictedDeliverables = (selectedProjectOption) => {
    let deliverables = selectedProjectOption.taskInfoList;
    if (this.props.permission.restrictedBySkillsEnabled === true) {
      const employeeSkills = commonUtils.getEmployeeSkills(this.props.selectedEmployee);
      deliverables = selectedProjectOption.taskInfoList &&
        selectedProjectOption.taskInfoList.filter(deliverable => !deliverable.restrictedByEmployeeSkills || employeeSkills.some(skill => deliverable.restrictedByEmployeeSkills.includes(skill)));
      deliverables = deliverables && deliverables.filter(deliverable => !deliverable.restrictedByEmployeeIds || (this.state.selectedEmployeeOption && deliverable.restrictedByEmployeeIds.includes(this.props.selectedEmployee.value)));
    }
    if (commonUtils.getAppConfigValue(this.state.projectAppConfig, "enableRestrictProjectByEmployeeServiceLine") && deliverables) {
      deliverables = deliverables.filter(deliverable => this.props.selectedEmployee.serviceLines && this.props.selectedEmployee.serviceLines.includes(deliverable.serviceLine));
    }
    return commonUtils.convertObjectToSelectObject(deliverables)
  }

  getRestrictedDeliverableOptions = () => {
    return commonUtils.convertObjectToSelectObject(this.getRestrictedDeliverables(this.props.selectedProject))
  }

  render() {
    return (
      <div className="lux-ts-board__fields lux-ts-board__fields--project">
        <div className="lux-ts-board__field">
          <span className="lux-ts-board__field-label">Deliverable</span>
          {this.props.selectedProject && (
            <div className="timesheet-select lux-ts-board__select">
              <CustomInput
                readOnly={this.props.readOnly}
                type='select'
                name="taskId"
                fieldConfig={this.props.projectFieldConfig}
                mappingObject={{ ...this.props.timeSheetTaskItem, "taskId": this.props.selectedDeliverableOption }}
                onChange={this.props.onDeliveryFieldValueChange}
                placeholder="Deliverable..."
                options={(this.props.selectedProject && this.state.projectAppConfig && this.getRestrictedDeliverableOptions()) || []}
                onFormError={this.props.onFormError}
                getSelectOptionEnabled={true}
                menuPortal
                menuPortalZIndex={10140}
              />
            </div>
          )}
        </div>
        <div className="lux-ts-board__field">
          <span className="lux-ts-board__field-label">Category</span>
          {this.props.selectedProject && (
            <div className="timesheet-select lux-ts-board__select">
              {(commonUtils.getAppConfigValue(this.state.projectAppConfig, "enableCategorySelection")) &&
                <CustomInput
                  readOnly={this.props.readOnly}
                  type='select'
                  name="taskActCategory"
                  fieldConfig={this.props.projectFieldConfig}
                  mappingObject={this.props.timeSheetTaskItem}
                  onChange={this.props.onFieldValueChange}
                  placeholder="Category..."
                  isAppConfig={true}
                  configName={"taskActCategory"}
                  createConfig={this.state.projectAppConfig}
                  onFormError={this.props.onFormError}
                  menuPortal
                  menuPortalZIndex={10140}
                />
              }

              {(!commonUtils.getAppConfigValue(this.state.projectAppConfig, "enableCategorySelection")) &&
                <CustomInput
                  type='select'
                  name="taskActCategory"
                  configName="taskActCategory"
                  fieldConfig={this.props.projectFieldConfig}
                  mappingObject={this.props.timeSheetTaskItem}
                  onChange={this.props.onFieldValueChange}
                  placeholder="Category..."
                  options={this.state.projectAppConfig && this.props.selectedDeliverableOption && workItemUtils.getWorkItemCategories(this.state.projectAppConfig, commonUtils.getAppConfigValue(this.state.projectAppConfig, "enableServiceLineEstimate") ? this.props.selectedDeliverableOption.serviceLine : this.state.selectedProject.category, this.props.selectedDeliverableOption.taskCategory)}
                  onFormError={this.props.onFormError}
                  menuPortal
                  menuPortalZIndex={10140}
                />
              }
            </div>
          )}
        </div>
        <div className="lux-ts-board__field">
          <span className="lux-ts-board__field-label">Work item</span>
          <CustomInput
            type='text'
            name="workItemName"
            inputClassName={"workItemText lux-ts-board__text-input"}
            fieldConfig={this.props.projectFieldConfig}
            mappingObject={this.props.timeSheetTaskItem}
            onChange={this.props.onFieldValueChange}
            placeholder="Work Item Name.."
            onFormError={this.props.onFormError}
          />
        </div>
      </div>
    )
  }
}

