import React, { Component } from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { ADMIN_PAGE_META } from "config/admin-page-meta.config";
import {
  isApprovalPolicyAdminEnabled,
  buildApprovalPolicySummary,
  filterApprovalPolicies,
  getApprovalPolicyDomainOptions,
} from "config/approval-policy.config";
import { getApprovalDomainMeta } from "config/universal-approval.config";
import { approvalPolicyService } from "_services/approvalPolicy.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import ApprovalPolicyRegister from "views/admin/components/ApprovalPolicyRegister";
import AdminInsightsSummary from "views/admin/components/AdminInsightsSummary";
import {
  AdminActionButton,
  AdminPanelLink,
  AdminLuxPage,
} from "views/admin/components/AdminLuxShared";
import "views/hrms/leaveLuxForms.css";
import "views/admin/components/ApprovalPolicyDrawer.css";

const EMPTY_FORM = {
  name: "",
  domain: "LEAVE",
  description: "",
  slaHours: "24",
  escalationHours: "48",
  approverLevels: "Manager",
  autoEscalate: false,
  reminderEnabled: true,
  status: "Draft",
};

class ApprovalPoliciesPage extends Component {
  state = {
    policies: [],
    loading: true,
    loadError: null,
    dataSource: null,
    statusFilter: "ALL",
    domainFilter: "ALL",
    query: "",
    showForm: false,
    form: { ...EMPTY_FORM },
    formError: null,
    saving: false,
    editingId: null,
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Approval policies");
    this.loadPolicies();
  }

  loadPolicies = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await approvalPolicyService.listPolicies();
      this.setState({
        policies: result.payload || [],
        loading: false,
        dataSource: result.source || null,
      });
    } catch (e) {
      this.setState({
        loading: false,
        loadError: "Unable to load approval policies.",
        policies: [],
      });
    }
  };

  getFilteredPolicies = () => {
    const { policies, statusFilter, domainFilter, query } = this.state;
    return filterApprovalPolicies(policies, {
      status: statusFilter,
      domain: domainFilter,
      query,
    });
  };

  closeForm = () => {
    if (this.state.saving) return;
    this.setState({ showForm: false, formError: null, editingId: null, form: { ...EMPTY_FORM } });
  };

  openCreateForm = () => {
    this.setState({ showForm: true, editingId: null, form: { ...EMPTY_FORM }, formError: null });
  };

  openEditForm = (policy) => {
    this.setState({
      showForm: true,
      editingId: policy.id,
      form: {
        name: policy.name || "",
        domain: policy.domain || "LEAVE",
        description: policy.description || "",
        slaHours: policy.slaHours != null ? String(policy.slaHours) : "24",
        escalationHours: policy.escalationHours != null ? String(policy.escalationHours) : "48",
        approverLevels: Array.isArray(policy.approverLevels)
          ? policy.approverLevels.join(", ")
          : policy.approverLevels || "Manager",
        autoEscalate: !!policy.autoEscalate,
        reminderEnabled: !!policy.reminderEnabled,
        status: policy.status || "Draft",
      },
      formError: null,
    });
  };

  handleFormChange = (field, value) => {
    this.setState((prev) => ({ form: { ...prev.form, [field]: value } }));
  };

  handleSave = async (event) => {
    if (event && event.preventDefault) event.preventDefault();
    const { form, editingId } = this.state;
    if (!String(form.name || "").trim() || !String(form.domain || "").trim()) {
      this.setState({ formError: "Name and domain are required." });
      return;
    }
    const payload = {
      name: form.name.trim(),
      domain: form.domain,
      description: form.description || "",
      slaHours: form.slaHours === "" ? null : Number(form.slaHours),
      escalationHours: form.escalationHours === "" ? null : Number(form.escalationHours),
      approverLevels: String(form.approverLevels || "")
        .split(",")
        .map((s) => s.trim())
        .filter(Boolean),
      autoEscalate: !!form.autoEscalate,
      reminderEnabled: !!form.reminderEnabled,
      status: form.status || "Draft",
    };
    this.setState({ saving: true, formError: null });
    try {
      if (editingId) {
        await approvalPolicyService.updatePolicy(editingId, payload);
      } else {
        await approvalPolicyService.savePolicy(payload);
      }
      this.setState({ showForm: false, saving: false, editingId: null, form: { ...EMPTY_FORM } });
      await this.loadPolicies();
    } catch (e) {
      this.setState({
        saving: false,
        formError: (e && e.message) || "Unable to save approval policy.",
      });
    }
  };

  renderField = (label, icon, children, spanFull) => (
    <label
      className={classNames("lux-leave-drawer__field", {
        "lux-leave-drawer__field--full": spanFull,
      })}
    >
      <span className="lux-leave-drawer__label">
        {icon ? <i className={`fe ${icon}`} aria-hidden="true" /> : null} {label}
      </span>
      {children}
    </label>
  );

  renderFormDrawer() {
    const { showForm, form, formError, saving, editingId } = this.state;
    if (!showForm || typeof document === "undefined") {
      return null;
    }

    const domainOptions = getApprovalPolicyDomainOptions();
    const domainMeta = getApprovalDomainMeta(form.domain);
    const isEdit = !!editingId;
    const chainPreview = String(form.approverLevels || "")
      .split(",")
      .map((s) => s.trim())
      .filter(Boolean);

    return createPortal(
      <div
        className="lux-onb-drawer-backdrop lux-leave-drawer-backdrop"
        role="presentation"
        onClick={this.closeForm}
        data-testid="approval-policy-form-backdrop"
      >
        <aside
          className="lux-onb-drawer lux-leave-drawer lux-appr-policy-drawer lux-onb-drawer--primary"
          data-testid="approval-policy-form"
          role="dialog"
          aria-modal="true"
          aria-labelledby="approval-policy-drawer-title"
          onClick={(e) => e.stopPropagation()}
        >
          <span className="lux-onb-drawer__accent" aria-hidden="true" />

          <header className="lux-onb-drawer__head">
            <div className="lux-onb-drawer__head-main">
              <span
                className={classNames(
                  "lux-onb-drawer__category-icon",
                  domainMeta.tone && `is-${domainMeta.tone}`
                )}
                aria-hidden="true"
              >
                <i className="fe fe-shield" />
              </span>
              <div className="lux-onb-drawer__head-copy">
                <span className="lux-leave-drawer__eyebrow">Admin · Approval policies</span>
                <h2 id="approval-policy-drawer-title">
                  {isEdit ? "Edit approval policy" : "Create approval policy"}
                </h2>
                <p>
                  Define SLA windows, escalation, and the approver chain for{" "}
                  <strong>{domainMeta.label}</strong> requests.
                </p>
                <div className="lux-onb-drawer__badges">
                  <span className="lux-onb-drawer__pill lux-onb-drawer__pill--required">
                    {form.status || "Draft"}
                  </span>
                  <span className="lux-onb-drawer__pill lux-onb-drawer__pill--optional">
                    {domainMeta.module} · {domainMeta.label}
                  </span>
                </div>
              </div>
            </div>
            <button
              type="button"
              className="lux-onb-drawer__close"
              aria-label="Close"
              onClick={this.closeForm}
              disabled={saving}
              data-testid="approval-policy-form-close"
            >
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </header>

          <form className="lux-onb-drawer__body lux-leave-drawer__body" onSubmit={this.handleSave}>
            <div className="lux-leave-drawer__scroll">
              {formError ? (
                <div className="lux-leave-config__banner is-error" role="alert">
                  <i className="fe fe-alert-circle" aria-hidden="true" />
                  <span>{formError}</span>
                </div>
              ) : null}

              <div className="lux-appr-policy-drawer__banner">
                <i className="fe fe-info" aria-hidden="true" />
                <div>
                  <strong>Policy metadata only</strong>
                  <p>
                    Runtime authority still resolves through delegation / ApprovalAuthorityService.
                    This register does not rewrite that core.
                  </p>
                </div>
              </div>

              <section className="lux-onb-drawer__section">
                <header className="lux-onb-drawer__section-head">
                  <i className="fe fe-grid" aria-hidden="true" /> Domain
                </header>
                <div
                  className="lux-appr-policy-drawer__domain-grid"
                  role="radiogroup"
                  aria-label="Approval domain"
                >
                  {domainOptions.map((option) => {
                    const meta = getApprovalDomainMeta(option.id);
                    const selected = form.domain === option.id;
                    return (
                      <button
                        key={option.id}
                        type="button"
                        role="radio"
                        aria-checked={selected}
                        disabled={saving}
                        className={classNames(
                          "lux-appr-policy-drawer__domain-card",
                          meta.tone && `is-${meta.tone}`,
                          { "is-selected": selected }
                        )}
                        onClick={() => this.handleFormChange("domain", option.id)}
                        data-testid={`approval-policy-domain-${option.id}`}
                      >
                        <i className={meta.icon} aria-hidden="true" />
                        <strong>{meta.label}</strong>
                        <em>{meta.module}</em>
                      </button>
                    );
                  })}
                </div>
                <input
                  type="hidden"
                  data-testid="approval-policy-domain"
                  value={form.domain}
                  readOnly
                />
              </section>

              <section className="lux-onb-drawer__section">
                <header className="lux-onb-drawer__section-head">
                  <i className="fe fe-bookmark" aria-hidden="true" /> Identity
                </header>
                <div className="lux-leave-drawer__grid">
                  {this.renderField(
                    "Policy name",
                    "fe-tag",
                    <input
                      className="lux-leave-drawer__input"
                      data-testid="approval-policy-name"
                      value={form.name}
                      placeholder="e.g. Leave manager SLA"
                      onChange={(e) => this.handleFormChange("name", e.target.value)}
                      required
                      disabled={saving}
                    />
                  )}
                  {this.renderField(
                    "Status",
                    "fe-flag",
                    <select
                      className="lux-leave-drawer__input"
                      value={form.status}
                      onChange={(e) => this.handleFormChange("status", e.target.value)}
                      disabled={saving}
                      data-testid="approval-policy-status"
                    >
                      <option value="Draft">Draft</option>
                      <option value="Active">Active</option>
                    </select>
                  )}
                </div>
                {this.renderField(
                  "Description",
                  "fe-align-left",
                  <textarea
                    className="lux-leave-drawer__textarea"
                    rows={2}
                    value={form.description}
                    placeholder="Optional notes for admins and auditors"
                    onChange={(e) => this.handleFormChange("description", e.target.value)}
                    disabled={saving}
                  />,
                  true
                )}
              </section>

              <section className="lux-onb-drawer__section">
                <header className="lux-onb-drawer__section-head">
                  <i className="fe fe-clock" aria-hidden="true" /> SLA &amp; escalation
                </header>
                <div className="lux-leave-drawer__grid">
                  {this.renderField(
                    "SLA hours",
                    "fe-hourglass",
                    <input
                      type="number"
                      min="1"
                      className="lux-leave-drawer__input"
                      value={form.slaHours}
                      onChange={(e) => this.handleFormChange("slaHours", e.target.value)}
                      disabled={saving}
                      data-testid="approval-policy-sla"
                    />
                  )}
                  {this.renderField(
                    "Escalation hours",
                    "fe-trending-up",
                    <input
                      type="number"
                      min="1"
                      className="lux-leave-drawer__input"
                      value={form.escalationHours}
                      onChange={(e) => this.handleFormChange("escalationHours", e.target.value)}
                      disabled={saving}
                      data-testid="approval-policy-escalation"
                    />
                  )}
                </div>
                <div className="lux-appr-policy-drawer__toggle-row">
                  <label className="lux-leave-drawer__check">
                    <input
                      type="checkbox"
                      checked={form.autoEscalate}
                      onChange={(e) => this.handleFormChange("autoEscalate", e.target.checked)}
                      disabled={saving}
                    />
                    <span>Auto-escalate when SLA is breached</span>
                  </label>
                  <label className="lux-leave-drawer__check">
                    <input
                      type="checkbox"
                      checked={form.reminderEnabled}
                      onChange={(e) => this.handleFormChange("reminderEnabled", e.target.checked)}
                      disabled={saving}
                    />
                    <span>Send reminder nudges to pending approvers</span>
                  </label>
                </div>
              </section>

              <section className="lux-onb-drawer__section">
                <header className="lux-onb-drawer__section-head">
                  <i className="fe fe-git-branch" aria-hidden="true" /> Approver chain
                </header>
                {this.renderField(
                  "Levels (comma-separated)",
                  "fe-users",
                  <input
                    className="lux-leave-drawer__input"
                    value={form.approverLevels}
                    placeholder="e.g. Manager, HR, Director"
                    onChange={(e) => this.handleFormChange("approverLevels", e.target.value)}
                    disabled={saving}
                    data-testid="approval-policy-approvers"
                  />,
                  true
                )}
                {chainPreview.length > 0 ? (
                  <div className="lux-appr-policy-drawer__preview" aria-label="Approver chain preview">
                    {chainPreview.map((level, index) => (
                      <React.Fragment key={`${level}-${index}`}>
                        {index > 0 ? (
                          <span className="lux-appr-policy-register__chain-sep" aria-hidden="true">
                            →
                          </span>
                        ) : null}
                        <span className="lux-appr-policy-drawer__preview-chip">
                          <i className="fe fe-user" aria-hidden="true" />
                          {level}
                        </span>
                      </React.Fragment>
                    ))}
                  </div>
                ) : null}
              </section>
            </div>

            <footer className="lux-onb-drawer__foot">
              <div className="lux-onb-drawer__foot-actions">
                <button
                  type="button"
                  className="lux-leave-drawer__btn is-ghost"
                  onClick={this.closeForm}
                  disabled={saving}
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="lux-leave-drawer__btn is-primary"
                  disabled={saving}
                  data-testid="approval-policy-save"
                >
                  {saving ? "Saving…" : isEdit ? "Update policy" : "Create policy"}
                </button>
              </div>
            </footer>
          </form>
        </aside>
      </div>,
      document.body
    );
  }

  render() {
    if (!isApprovalPolicyAdminEnabled()) {
      return (
        <PersonaAccessDenied
          moduleName="Approval policies"
          reason="Approval policy administration is not enabled for your organization."
        />
      );
    }

    const { loading, loadError, dataSource, statusFilter, domainFilter, query } = this.state;
    const filteredPolicies = this.getFilteredPolicies();
    const domainOptions = getApprovalPolicyDomainOptions().filter((row) =>
      this.state.policies.some((policy) => policy.domain === row.id)
    );
    const summary = loading ? null : buildApprovalPolicySummary(this.state.policies);

    return (
      <AdminLuxPage
        pageMeta={ADMIN_PAGE_META.approvalPolicies}
        dataSource={dataSource}
        loading={loading}
        className="lux-register-page lux-appr-policy-page lux-admin-page"
        heroActions={
          <>
            <AdminActionButton
              icon="fe fe-plus"
              variant="primary"
              onClick={this.openCreateForm}
              testId="approval-policy-create"
            >
              Create policy
            </AdminActionButton>
            <AdminActionButton icon="fe fe-refresh-cw" onClick={this.loadPolicies} disabled={loading}>
              Refresh
            </AdminActionButton>
            <AdminActionButton to="/admin/audit" icon="fe fe-activity" variant="ghost">
              Audit trail
            </AdminActionButton>
          </>
        }
      >
        {loadError && (
          <div className="lux-employee-360__error lux-appr-policy__error" role="alert">
            <span>{loadError}</span>
            <AdminActionButton variant="ghost" onClick={this.loadPolicies}>Retry</AdminActionButton>
          </div>
        )}
        <AdminInsightsSummary
          storageKey="famstack-approval-policies-summary-expanded"
          domainClass="lux-admin-summary--approval-policies"
          loading={loading}
          eyebrow="Policy intelligence"
          eyebrowIcon="fe-git-branch"
          title="Approval policy insights"
          compactTitle={
            summary
              ? `${summary.metrics.total} policies · ${summary.metrics.active} active · ${summary.metrics.draft} draft`
              : "Approval policy insights"
          }
          collapsedLine={
            summary
              ? `${summary.metrics.domains} domains · ${summary.metrics.autoEscalate} auto-escalate · ${summary.metrics.reminders} reminders`
              : null
          }
          subtitle="Publish posture, SLA controls, and domain coverage across the approval engine."
          kpis={summary ? summary.kpis : []}
          highlights={summary ? summary.highlights : []}
          attention={summary ? summary.attention : []}
          mixInsights={summary ? summary.mixInsights : []}
          series={summary ? summary.series : []}
          testId="approval-policies-insights"
        />

        <section
          className="lux-admin-atelier lux-admin-atelier--approval-policies"
          data-testid="approval-policies-register"
        >
          <header className="lux-admin-atelier__masthead">
            <div className="lux-admin-atelier__masthead-main">
              <span className="lux-admin-atelier__mark" aria-hidden="true">
                <i className="fe fe-git-branch" />
              </span>
              <div>
                <p className="lux-admin-atelier__eyebrow">Approval engine</p>
                <h2 className="lux-admin-atelier__title">Policy register</h2>
                <p className="lux-admin-atelier__lede">
                  Craft SLA windows, escalation posture, and multi-level approver chains by domain.
                </p>
              </div>
            </div>
            <div className="lux-admin-atelier__masthead-aside">
              <AdminPanelLink to="/admin/delegation">Delegation rules</AdminPanelLink>
              <span className="lux-admin-atelier__count">
                <strong>{filteredPolicies.length}</strong>
                <em>shown</em>
              </span>
            </div>
          </header>

          <div className="lux-admin-atelier__toolbar">
            <div className="lux-admin-atelier__toolbar-primary">
              <div className="lux-admin-atelier__search">
                <i className="fe fe-search" aria-hidden="true" />
                <input
                  type="search"
                  className="lux-admin-atelier__search-input"
                  placeholder="Search policies, domains, or approvers"
                  value={query}
                  onChange={(e) => this.setState({ query: e.target.value })}
                />
              </div>
              {summary ? (
                <div className="lux-admin-atelier__focus-row" aria-label="Policy posture">
                  <div className="lux-admin-atelier__focus is-mint">
                    <i className="fe fe-check-circle" aria-hidden="true" />
                    <span>
                      <strong>{summary.metrics.active}</strong>
                      <em>Live</em>
                    </span>
                  </div>
                  <div className="lux-admin-atelier__focus is-amber">
                    <i className="fe fe-edit-3" aria-hidden="true" />
                    <span>
                      <strong>{summary.metrics.draft}</strong>
                      <em>Draft</em>
                    </span>
                  </div>
                  <div className="lux-admin-atelier__focus is-violet">
                    <i className="fe fe-zap" aria-hidden="true" />
                    <span>
                      <strong>{summary.metrics.autoEscalate}</strong>
                      <em>Auto-escalate</em>
                    </span>
                  </div>
                  <div className="lux-admin-atelier__focus is-blue">
                    <i className="fe fe-bell" aria-hidden="true" />
                    <span>
                      <strong>{summary.metrics.reminders}</strong>
                      <em>Reminders</em>
                    </span>
                  </div>
                </div>
              ) : null}
            </div>
            <div className="lux-admin-atelier__filters">
              <div className="lux-admin-atelier__filter">
                <span>Status</span>
                <div className="lux-admin-atelier__chips" role="group" aria-label="Filter by status">
                  {["ALL", "Active", "Draft"].map((value) => (
                    <button
                      key={value}
                      type="button"
                      className={classNames("lux-admin-atelier__chip", {
                        "is-active": statusFilter === value,
                      })}
                      onClick={() => this.setState({ statusFilter: value })}
                    >
                      {value === "ALL" ? "All" : value}
                    </button>
                  ))}
                </div>
              </div>
              <div className="lux-admin-atelier__filter">
                <span>Domain</span>
                <div className="lux-admin-atelier__chips" role="group" aria-label="Filter by domain">
                  <button
                    type="button"
                    className={classNames("lux-admin-atelier__chip", {
                      "is-active": domainFilter === "ALL",
                    })}
                    onClick={() => this.setState({ domainFilter: "ALL" })}
                  >
                    All
                  </button>
                  {domainOptions.map((domain) => (
                    <button
                      key={domain.id}
                      type="button"
                      className={classNames("lux-admin-atelier__chip", {
                        "is-active": domainFilter === domain.id,
                      })}
                      onClick={() => this.setState({ domainFilter: domain.id })}
                    >
                      {domain.label}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>

          <div className="lux-admin-atelier__body">
            <div className="lux-admin-atelier__pane-label">
              <span>Policies</span>
              <em>
                {loading
                  ? "Loading…"
                  : `${filteredPolicies.length} of ${this.state.policies.length} in register`}
              </em>
            </div>
            {loading ? (
              <LuxRegisterEmptyState
                className="lux-register-empty--compact"
                title="Loading policies"
                description="Fetching approval policy configuration."
              />
            ) : filteredPolicies.length === 0 ? (
              <LuxRegisterEmptyState
                className="lux-register-empty--compact"
                icon="fe fe-shield"
                title="No approval policies"
                description="No policies match your filters. Create a policy or broaden filters."
              />
            ) : (
              <ApprovalPolicyRegister policies={filteredPolicies} onEdit={this.openEditForm} />
            )}
          </div>
        </section>

        {this.renderFormDrawer()}
      </AdminLuxPage>
    );
  }
}

export default ApprovalPoliciesPage;
