import { ACCESS_REQUEST_STATUSES } from "config/asset-register.config";
import { buildAccessRequestMetrics } from "config/asset-register.utils";

const ACCESS_REQUEST_TYPE_META = {
  SOFTWARE: { label: "Software", icon: "fe fe-package", tone: "sky" },
  ACCESS: { label: "IT access", icon: "fe fe-key", tone: "violet" },
  HARDWARE: { label: "Hardware", icon: "fe fe-monitor", tone: "amber" },
  LAPTOP: { label: "Laptop", icon: "fe fe-hard-drive", tone: "primary" },
  MOBILE: { label: "Mobile", icon: "fe fe-smartphone", tone: "green" },
  SYSTEM: { label: "System", icon: "fe fe-server", tone: "slate" },
};

export function getAccessRequestTypeMeta(type) {
  const key = String(type || "").toUpperCase();
  return ACCESS_REQUEST_TYPE_META[key] || {
    label: type || "Request",
    icon: "fe fe-layers",
    tone: "slate",
  };
}

export function getAccessRequestStatusTone(status) {
  const normalized = String(status || "").toLowerCase();
  if (normalized === "pending") return "warning";
  if (normalized === "approved") return "primary";
  if (normalized === "rejected") return "danger";
  if (normalized === "fulfilled") return "success";
  return "slate";
}

export function getAccessRequestPriorityTone(priority) {
  const normalized = String(priority || "").toUpperCase();
  if (normalized === "HIGH") return "danger";
  if (normalized === "LOW") return "slate";
  return "slate";
}

export function formatAccessRequestDate(value) {
  if (!value) return "—";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
}

export function getRequesterInitials(name) {
  const parts = String(name || "?")
    .trim()
    .split(/\s+/)
    .filter(Boolean);
  if (!parts.length) return "?";
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return `${parts[0][0]}${parts[parts.length - 1][0]}`.toUpperCase();
}

export function buildAccessRequestAdminMetrics(requests) {
  const base = buildAccessRequestMetrics(requests);
  const rows = requests || [];
  return {
    ...base,
    rejected: rows.filter((row) => row.status === ACCESS_REQUEST_STATUSES.REJECTED).length,
    highPriority: rows.filter(
      (row) =>
        String(row.priority).toUpperCase() === "HIGH" &&
        row.status === ACCESS_REQUEST_STATUSES.PENDING
    ).length,
  };
}

export function buildAccessRequestInsights(requests) {
  const metrics = buildAccessRequestAdminMetrics(requests);
  const insights = [];

  if (metrics.highPriority > 0) {
    insights.push({
      id: "high-priority",
      tone: "rose",
      icon: "fe fe-alert-triangle",
      title: `${metrics.highPriority} high-priority request(s) pending`,
      copy: "Review incident, on-call, or production access requests first.",
    });
  }
  if (metrics.pending > 0) {
    insights.push({
      id: "pending",
      tone: "amber",
      icon: "fe fe-inbox",
      title: `${metrics.pending} request(s) awaiting IT/HR action`,
      copy: "Approve or reject to route fulfillment through the asset register.",
    });
  }
  if (metrics.approved > 0) {
    insights.push({
      id: "approved",
      tone: "blue",
      icon: "fe fe-check-circle",
      title: `${metrics.approved} approved — pending fulfillment`,
      copy: "Mark fulfilled once hardware is assigned or access is provisioned.",
    });
  }
  if (metrics.total === 0) {
    insights.push({
      id: "empty",
      tone: "green",
      icon: "fe fe-key",
      title: "Queue is clear",
      copy: "Employee hardware and IT access requests will appear here when submitted.",
    });
  }
  return insights.slice(0, 3);
}
