import React, { Component } from "react";
import PayrollLuxDrawerShell from "views/payroll/components/PayrollLuxDrawerShell";
import {
  PayrollDrawerBanner,
  PayrollDrawerCard,
  PayrollDrawerField,
  PayrollDrawerMeta,
  PayrollDrawerStatStrip,
} from "views/payroll/components/PayrollLuxDrawerShared";
import { PayrollActionButton } from "views/payroll/components/PayrollLuxShared";
import { shouldUsePayrollApi } from "config/payroll.config";

const FREQUENCIES = [
  { id: "Monthly", label: "Monthly", hint: "12 cycles / year" },
  { id: "Bi-weekly", label: "Bi-weekly", hint: "26 cycles / year" },
  { id: "Weekly", label: "Weekly", hint: "52 cycles / year" },
];

const STATUSES = ["Active", "Inactive", "Draft"];

const DRAWER_LINKS = [
  { to: "/admin/payroll-config", label: "Payroll readiness", hint: "Mandatory gates", icon: "fe fe-shield" },
  { to: "/payroll/salary-structures", label: "Salary structures", hint: "Component templates", icon: "fe fe-sliders" },
  { to: "/payroll/runs", label: "Payroll runs", hint: "Create a cycle", icon: "fe fe-play" },
];

/**
 * Luxury create/edit drawer for payroll groups.
 */
class PayrollGroupDrawer extends Component {
  render() {
    const {
      open,
      onClose,
      form,
      formError,
      saving,
      editingId,
      onChange,
      onSubmit,
    } = this.props;

    const apiEnabled = shouldUsePayrollApi();
    const title = editingId ? "Edit payroll group" : "Create payroll group";

    const footer = (
      <>
        <PayrollActionButton type="button" variant="ghost" onClick={onClose} disabled={saving}>
          Cancel
        </PayrollActionButton>
        <PayrollActionButton
          type="submit"
          form="payroll-group-form"
          variant="primary"
          icon="fe fe-check"
          disabled={saving || !apiEnabled}
          data-testid="payroll-group-save"
        >
          {saving ? "Saving…" : editingId ? "Update group" : "Create group"}
        </PayrollActionButton>
      </>
    );

    return (
      <PayrollLuxDrawerShell
        open={open}
        onClose={onClose}
        accent="green"
        wide
        icon="fe-users"
        eyebrow="Payroll · Cohorts"
        title={title}
        subtitle="Define pay frequency, lock day, currency, and calendar for this employee cohort."
        quickLinks={DRAWER_LINKS}
        footer={footer}
        ariaLabel={title}
      >
        <form id="payroll-group-form" onSubmit={onSubmit} data-testid="payroll-group-form">
          {formError ? (
            <div className="lux-employee-360__error" role="alert">
              {formError}
            </div>
          ) : null}

          {!apiEnabled ? (
            <PayrollDrawerBanner icon="fe-alert-triangle" tone="warning">
              Payroll API is disabled. Enable <code>REACT_APP_USE_PAYROLL_API</code> to create or edit groups.
            </PayrollDrawerBanner>
          ) : (
            <PayrollDrawerBanner icon="fe-info" tone="info">
              Groups drive pay calendars and lock windows for payroll runs. Employees inherit the cohort schedule.
            </PayrollDrawerBanner>
          )}

          <PayrollDrawerStatStrip
            stats={[
              {
                label: "Frequency",
                value: form.payFrequency || "—",
                hint: "Pay cycle",
                tone: "green",
              },
              {
                label: "Lock day",
                value: form.lockDay ? `Day ${form.lockDay}` : "—",
                hint: "Attendance lock",
                tone: "amber",
              },
              {
                label: "Currency",
                value: form.currency || "—",
                hint: "Payout",
                tone: "blue",
              },
            ]}
          />

          <PayrollDrawerCard title="Identity" subtitle="How this cohort appears across payroll">
            <div className="lux-payroll-drawer__date-grid" style={{ gridTemplateColumns: "1.4fr 1fr" }}>
              <PayrollDrawerField label="Group name" hint="Visible on runs and readiness">
                <input
                  data-testid="payroll-group-name"
                  value={form.name}
                  onChange={(e) => onChange("name", e.target.value)}
                  placeholder="e.g. India Monthly"
                  required
                  disabled={!apiEnabled || saving}
                />
              </PayrollDrawerField>
              <PayrollDrawerField label="Code" hint="Short reference">
                <input
                  data-testid="payroll-group-code"
                  value={form.code}
                  onChange={(e) => onChange("code", e.target.value)}
                  placeholder="IN-MTH"
                  disabled={!apiEnabled || saving}
                />
              </PayrollDrawerField>
            </div>
            <PayrollDrawerField label="Status">
              <select
                value={form.status}
                onChange={(e) => onChange("status", e.target.value)}
                disabled={!apiEnabled || saving}
              >
                {STATUSES.map((status) => (
                  <option key={status} value={status}>
                    {status}
                  </option>
                ))}
              </select>
            </PayrollDrawerField>
          </PayrollDrawerCard>

          <PayrollDrawerCard title="Pay frequency" subtitle="Choose how often this cohort is paid">
            <div className="lux-payroll-drawer__group-grid">
              {FREQUENCIES.map((freq) => (
                <button
                  key={freq.id}
                  type="button"
                  className={`lux-payroll-drawer__group-card${
                    form.payFrequency === freq.id ? " is-selected" : ""
                  }`}
                  onClick={() => onChange("payFrequency", freq.id)}
                  disabled={!apiEnabled || saving}
                  data-testid={`payroll-group-frequency-${freq.id}`}
                >
                  <strong className="lux-payroll-drawer__group-name">{freq.label}</strong>
                  <span className="lux-payroll-drawer__group-meta">{freq.hint}</span>
                </button>
              ))}
            </div>
          </PayrollDrawerCard>

          <PayrollDrawerCard title="Calendar & currency" subtitle="Lock windows and payout currency">
            <div className="lux-payroll-drawer__date-grid" style={{ gridTemplateColumns: "repeat(2, minmax(0, 1fr))" }}>
              <PayrollDrawerField label="Currency">
                <input
                  value={form.currency}
                  onChange={(e) => onChange("currency", e.target.value)}
                  placeholder="INR"
                  disabled={!apiEnabled || saving}
                />
              </PayrollDrawerField>
              <PayrollDrawerField label="Lock day" hint="Day of month attendance locks">
                <input
                  type="number"
                  min="1"
                  max="31"
                  value={form.lockDay}
                  onChange={(e) => onChange("lockDay", e.target.value)}
                  disabled={!apiEnabled || saving}
                />
              </PayrollDrawerField>
              <PayrollDrawerField label="Next pay date">
                <input
                  type="date"
                  value={form.nextPayDate}
                  onChange={(e) => onChange("nextPayDate", e.target.value)}
                  disabled={!apiEnabled || saving}
                />
              </PayrollDrawerField>
              <PayrollDrawerField label="Current period label" hint="e.g. Jul 2026">
                <input
                  value={form.currentPeriod}
                  onChange={(e) => onChange("currentPeriod", e.target.value)}
                  placeholder="Jul 2026"
                  disabled={!apiEnabled || saving}
                />
              </PayrollDrawerField>
            </div>
          </PayrollDrawerCard>

          <PayrollDrawerCard title="Preview" subtitle="Confirm before saving" className="is-review">
            <PayrollDrawerMeta
              items={[
                { label: "Name", value: form.name },
                { label: "Code", value: form.code },
                { label: "Frequency", value: form.payFrequency },
                { label: "Currency", value: form.currency },
                { label: "Lock day", value: form.lockDay ? `Day ${form.lockDay}` : null },
                { label: "Next pay", value: form.nextPayDate },
                { label: "Status", value: form.status },
              ]}
            />
          </PayrollDrawerCard>
        </form>
      </PayrollLuxDrawerShell>
    );
  }
}

export default PayrollGroupDrawer;
