import { shouldUseWorkspaceNotifications } from "config/tracopus-pilot.config";
import { accessUtils } from "_helpers";

export function isNotificationTemplatesAdminEnabled() {
  const adminModules = accessUtils.getAccessControll("adminModules") || {};
  if (adminModules.notificationTemplatesEnabled === false) {
    return false;
  }
  return shouldUseWorkspaceNotifications();
}

export function filterNotificationTemplates(templates, { query = "", channel = "ALL", source = "ALL" } = {}) {
  const q = String(query || "").trim().toLowerCase();
  return (templates || []).filter((row) => {
    if (channel !== "ALL" && String(row.channel || "").toUpperCase() !== channel) {
      return false;
    }
    if (source === "SYSTEM" && row.systemDefault !== true && row.source !== "classpath-thymeleaf") {
      return false;
    }
    if (source === "OVERRIDE" && (row.systemDefault === true || row.source === "classpath-thymeleaf")) {
      return false;
    }
    if (!q) {
      return true;
    }
    const haystack = [row.eventType, row.subject, row.channel, row.templateRef, row.classpathTemplateName]
      .filter(Boolean)
      .join(" ")
      .toLowerCase();
    return haystack.includes(q);
  });
}

export function buildNotificationTemplateMetrics(templates) {
  const rows = templates || [];
  const overrides = rows.filter((row) => row.source === "org-override" || row.systemDefault === false);
  const disabled = rows.filter((row) => row.enabled === false);
  const email = rows.filter((row) => String(row.channel || "EMAIL").toUpperCase() === "EMAIL");
  return {
    total: rows.length,
    overrides: overrides.length,
    disabled: disabled.length,
    email: email.length,
  };
}

export function isSystemNotificationTemplate(row) {
  if (!row) return false;
  return row.systemDefault === true || row.source === "classpath-thymeleaf";
}

export function getNotificationTemplateSourceLabel(row) {
  if (!row) return "Unknown";
  if (isSystemNotificationTemplate(row)) {
    return "System default";
  }
  return "Org override";
}

export function getNotificationTemplateSourceTip(row) {
  if (isSystemNotificationTemplate(row)) {
    return "Classpath Thymeleaf template. Clone to layer an org override at dispatch time.";
  }
  return "Organization override stored for this workspace. Edits apply on next dispatch.";
}

export function buildNotificationTemplateInsights(templates) {
  const metrics = buildNotificationTemplateMetrics(templates);
  return [
    {
      id: "system",
      icon: "fe fe-package",
      tone: "blue",
      title: "System defaults",
      copy: `${Math.max(0, metrics.total - metrics.overrides)} classpath templates ship with the product and stay read-only.`,
    },
    {
      id: "overrides",
      icon: "fe fe-edit-3",
      tone: "primary",
      title: "Org overrides",
      copy: `${metrics.overrides} custom template${metrics.overrides === 1 ? "" : "s"} layer over defaults at send time.`,
    },
    {
      id: "masking",
      icon: "fe fe-eye-off",
      tone: "amber",
      title: "Masked preview",
      copy: "Preview renders with sensitive placeholders masked. Use Send-test for a real mailbox check.",
    },
  ];
}
