export function isProjectGovernanceEnabled() {
  return shouldUseProjectGovernance();
}

export function shouldUseProjectGovernanceApi() {
  return envconfig.USE_PROJECT_GOVERNANCE_API === true;
}

export function isProjectGovernanceAiImportEnabled() {
  return shouldUseProjectGovernance() && envconfig.PROJECT_GOVERNANCE_AI_IMPORT_ENABLED === true;
}

export function normalizeMilestone(row) {
  if (!row) {
    return null;
  }
  const status = row.status || MILESTONE_STATUSES.PLANNED;
  return {
    id: row.id,
    projectId: row.projectId || null,
    projectCode: row.projectCode || "",
    projectName: row.projectName || "Unnamed project",
    name: row.name || "Milestone",
    description: row.description || "",
    plannedStart: row.plannedStart || row.start || null,
    plannedEnd: row.plannedEnd || row.end || null,
    actualStart: row.actualStart || null,
    actualEnd: row.actualEnd || null,
    status,
    ownerId: row.ownerId || null,
    ownerName: row.ownerName || row.owner || "",
    percentComplete: row.percentComplete != null ? row.percentComplete : status === MILESTONE_STATUSES.COMPLETE ? 100 : 0,
    onCriticalPath: row.onCriticalPath === true,
    gateId: row.gateId || null,
    updatedAt: row.updatedAt || null,
  };
}

