export function normalizeIssueAction(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    issueId: row.issueId || null,
    title: row.title || "Action",
    ownerName: row.ownerName || row.owner || "",
    status: row.status || ISSUE_ACTION_STATUSES.OPEN,
    dueDate: row.dueDate || null,
    slaDays: row.slaDays != null ? row.slaDays : 5,
    completedAt: row.completedAt || null,
    updatedAt: row.updatedAt || null,
  };
}

export function normalizeIssue(row, actions = null) {
  if (!row) {
    return null;
  }
  const linkedActions = Array.isArray(actions)
    ? actions.map((item) => normalizeIssueAction(item)).filter(Boolean)
    : null;
  const actionCount =
    linkedActions != null
      ? linkedActions.length
      : row.actionCount != null
        ? row.actionCount
        : 0;
  return {
    id: row.id,
    projectId: row.projectId || null,
    projectCode: row.projectCode || "",
    projectName: row.projectName || "",
    title: row.title || "Issue",
    description: row.description || "",
    priority: row.priority || ISSUE_PRIORITIES.P2,
    ownerId: row.ownerId || null,
    ownerName: row.ownerName || row.owner || "",
    status: row.status || ISSUE_STATUSES.OPEN,
    dueDate: row.dueDate || row.due || null,
    openedAt: row.openedAt || row.createdAt || null,
    closedAt: row.closedAt || null,
    updatedAt: row.updatedAt || null,
    actionCount,
    actions: linkedActions,
  };
}

