import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";
import {
  normalizeAsset,
  normalizeAccessRequest,
  shouldUseAssetRegisterApi,
  toApiAccessRequestStatus,
} from "config/asset-register.config";
import { toEmployee360AssetRow } from "config/asset-register.utils";
import { recordAuditEvent } from "config/audit-write.service";
import { AUDIT_ACTION_TYPES, AUDIT_ENTITY_TYPES } from "_constants/audit.constants";
import { apiErrorResult } from "config/mock-fallback.utils";

export const assetRegisterService = {
  listAssets,
  listAccessRequests,
  getEmployeeAssets,
  assignAsset,
  returnAsset,
  acknowledgeAsset,
  createAccessRequest,
  updateAccessRequestStatus,
};

function assetTeamQuery(extra) {
  const query = { userTeamId: commonUtils.getCurrentUserTeamId() };
  if (extra) {
    Object.keys(extra).forEach((key) => {
      if (extra[key] != null && extra[key] !== "") {
        query[key] = extra[key];
      }
    });
  }
  return query;
}

function assetTeamQueryString(extra) {
  const query = assetTeamQuery(extra);
  return Object.keys(query)
    .map((key) => `${encodeURIComponent(key)}=${encodeURIComponent(query[key])}`)
    .join("&");
}

function recordAssetAudit(actionType, headline, entityRef, metadata) {
  recordAuditEvent({
    actionType,
    entityType: AUDIT_ENTITY_TYPES.ASSET,
    entityRef: entityRef || headline,
    headline,
    metadata,
  });
}

async function listAssetsFromApi(filters = {}) {
  const response = await axiosUtils.getWithParam(
    urlConfig.ASSET_REGISTER_API_PATH,
    assetTeamQuery({ assigneeId: filters.assigneeId || undefined })
  );
  const rows = (response && response.payload) || response || [];
  const list = Array.isArray(rows) ? rows : [];
  return {
    payload: list.map((row) => normalizeAsset(row)).filter(Boolean),
    source: "api",
  };
}

async function listAssets(filters = {}) {

  if (shouldUseAssetRegisterApi()) {
    try {
      return await listAssetsFromApi(filters);
    } catch (e) {
      return apiErrorResult([]);
    }
  }

  return apiErrorResult([]);
}

async function listAccessRequestsFromApi() {
  const response = await axiosUtils.getWithParam(
    urlConfig.ACCESS_REQUESTS_API_PATH,
    assetTeamQuery()
  );
  const rows = (response && response.payload) || response || [];
  const list = Array.isArray(rows) ? rows : [];
  return {
    payload: list.map((row) => normalizeAccessRequest(row)).filter(Boolean),
    source: "api",
  };
}

async function listAccessRequests() {

  if (shouldUseAssetRegisterApi()) {
    try {
      return await listAccessRequestsFromApi();
    } catch (e) {
      return apiErrorResult([]);
    }
  }

  return apiErrorResult([]);
}

async function getEmployeeAssets(employeeId) {

  if (shouldUseAssetRegisterApi()) {
    try {
      return await (async () => {
        const result = await listAssetsFromApi({ assigneeId: employeeId });
        return {
          payload: (result.payload || []).map((row) => toEmployee360AssetRow(row)),
          source: result.source,
        };
      })();
    } catch (e) {
      return apiErrorResult([]);
    }
  }

  try {
      return await (async () => {
      const response = await axiosUtils.get(`${urlConfig.EMPLOYEE_GET_INFO}/${employeeId}/assets`);
      const rows = (response && response.payload) || response || [];
      const list = Array.isArray(rows) ? rows : [];
      return {
        payload: list.map((row) => normalizeAsset(row)).filter(Boolean),
        source: "api",
      };
    })();
    } catch (e) {
      return apiErrorResult([]);
    }
}

async function assignAsset(assetId, assignee) {
  if (shouldUseAssetRegisterApi()) {
    try {
      return await (async () => {
        const response = await axiosUtils.post(
          `${urlConfig.ASSET_REGISTER_API_PATH}/${assetId}/assign?${assetTeamQueryString({
            actorId: commonUtils.getCurrentUserId(),
          })}`,
          {
            assigneeId: assignee && assignee.id,
            assigneeName: assignee && (assignee.name || assignee.employeeName),
          }
        );
        const row = normalizeAsset((response && response.payload) || response);
        recordAssetAudit(AUDIT_ACTION_TYPES.UPDATED, "Asset assigned", assetId, {
          assigneeId: assignee && assignee.id,
        });
        return { payload: row, source: "api" };
      })();
    } catch (e) {
      return apiErrorResult(null);
    }
  }

  return apiErrorResult(null);
}

