async function createAccessRequest(payload = {}) {
  if (shouldUseAssetRegisterApi()) {
    try {
      return await (async () => {
        const response = await axiosUtils.post(
          `${urlConfig.ACCESS_REQUESTS_API_PATH}?${assetTeamQueryString({
            actorId: commonUtils.getCurrentUserId(),
          })}`,
          {
            type: payload.type || "SYSTEM",
            title: payload.title,
            requesterId: payload.requesterId || String(commonUtils.getCurrentUserId()),
            requesterName: payload.requesterName || "",
            priority: payload.priority || "NORMAL",
            assetTag: payload.assetTag,
            notes: payload.notes,
          }
        );
        const row = normalizeAccessRequest((response && response.payload) || response);
        recordAssetAudit(AUDIT_ACTION_TYPES.CREATED, "Access request created", row && row.id);
        return { payload: row, source: "api" };
      })();
    } catch (e) {
      return apiErrorResult(null);
    }
  }

  return apiErrorResult(null);
}

async function updateAccessRequestStatus(requestId, status) {
  if (shouldUseAssetRegisterApi()) {
    try {
      return await (async () => {
        const apiStatus = toApiAccessRequestStatus(status);
        const response = await axiosUtils.patch(
          `${urlConfig.ACCESS_REQUESTS_API_PATH}/${requestId}/status?${assetTeamQueryString({
            actorId: commonUtils.getCurrentUserId(),
            status: apiStatus,
          })}`
        );
        const row = normalizeAccessRequest((response && response.payload) || response);
        recordAssetAudit(AUDIT_ACTION_TYPES.UPDATED, "Access request updated", requestId, {
          status: apiStatus,
        });
        return { payload: row, source: "api" };
      })();
    } catch (e) {
      return apiErrorResult(null);
    }
  }

  return apiErrorResult(null);
}
