import React, { Component } from "react";
import { NavLink } from "react-router-dom";
import classNames from "classnames";
import { getVisibleSidebarItems } from "config/sidebar-menu.config";
import {
  buildModuleContextSections,
  findActiveSidebarNavSectionId,
} from "config/sidebar-nav-groups";
import { isIntegrationCenterEnabled } from "config/integration-center.config";
import { INTEGRATION_QUICK_LINKS } from "config/integration-center-nav.config";
import PlannedMenuIndicator from "components/navigation/PlannedMenuIndicator";

/**
 * F01-T2: Module context submenu — pinned daily links + collapsible feature groups.
 * Menu link styles stay unchanged.
 */
class ModuleContextMenu extends Component {
  state = {
    moduleId: null,
    expandedIds: {},
  };

  static getDerivedStateFromProps(props, state) {
    const moduleId = props.group && props.group.id;
    if (!moduleId || state.moduleId === moduleId) {
      return null;
    }
    return {
      moduleId,
      expandedIds: {},
    };
  }

  componentDidUpdate(prevProps) {
    const prevPath = prevProps.location && prevProps.location.pathname;
    const nextPath = this.props.location && this.props.location.pathname;
    if (prevPath === nextPath) {
      return;
    }
    const sections = this.resolveSections();
    const activeSectionId = findActiveSidebarNavSectionId(nextPath, sections);
    const activeSection = sections.find((section) => section.id === activeSectionId);
    if (!activeSectionId || (activeSection && activeSection.pinned)) {
      return;
    }
    if (this.state.expandedIds[activeSectionId] === false) {
      this.setState((prev) => ({
        expandedIds: {
          ...prev.expandedIds,
          [activeSectionId]: true,
        },
      }));
    }
  }

  resolveSections = () => {
    const { group, menuAccessControl, activePersona } = this.props;
    if (!group) {
      return [];
    }
    let items = getVisibleSidebarItems(group, menuAccessControl, activePersona);
    if (!items.length && group.id === "integrations" && isIntegrationCenterEnabled()) {
      items = INTEGRATION_QUICK_LINKS.map((link) => ({
        path: link.path || link.to,
        name: link.label,
      }));
    }
    return buildModuleContextSections(group.id, items);
  };

  activeRoutePage = (routeName) => {
    const path = this.props.location.pathname;
    return path.indexOf(routeName) > -1 ? "active" : "";
  };

  handlePlannedItemClick = (event) => {
    event.preventDefault();
    event.stopPropagation();
  };

  isSectionExpanded = (section, activeSectionId) => {
    if (section.pinned) {
      return true;
    }
    const { expandedIds } = this.state;
    if (Object.prototype.hasOwnProperty.call(expandedIds, section.id)) {
      return expandedIds[section.id] === true;
    }
    return section.id === activeSectionId;
  };

  handleGroupToggle = (section, activeSectionId) => (event) => {
    event.preventDefault();
    if (section.pinned) {
      return;
    }
    const isExpanded = this.isSectionExpanded(section, activeSectionId);
    this.setState((prev) => ({
      expandedIds: {
        ...prev.expandedIds,
        [section.id]: !isExpanded,
      },
    }));
  };

  renderItem = (item, key) => {
    if (item.planned === true) {
      return (
        <li key={key}>
          <span
            className="nav-link list-b lux-nav__child lux-nav__child--planned lux-nav__child--disabled"
            role="menuitem"
            aria-disabled="true"
            title={`${item.name} (coming soon)`}
            onClick={this.handlePlannedItemClick}
          >
            <span>{item.name}</span>
            <PlannedMenuIndicator label="Planned feature" />
          </span>
        </li>
      );
    }

    return (
      <li className={this.activeRoutePage(item.path)} key={key}>
        <NavLink
          to={item.path}
          className="nav-link list-b lux-nav__child lux-menu-context__link"
          activeClassName="active"
          title={item.name}
        >
          <span>{item.name}</span>
        </NavLink>
      </li>
    );
  };

  renderSection = (section, activeSectionId) => {
    const expanded = this.isSectionExpanded(section, activeSectionId);
    const hasLabel = Boolean(section.label);

    if (section.pinned || !hasLabel) {
      return (
        <React.Fragment key={section.id}>
          {section.pinned ? (
            <li className="lux-menu-context__pinned-label" role="presentation">
              <span>Quick access</span>
            </li>
          ) : null}
          {section.items.map((item, idx) => this.renderItem(item, `${section.id}-${idx}`))}
        </React.Fragment>
      );
    }

    const headerId = `lux-menu-context-header-${section.id}`;

    return (
      <React.Fragment key={section.id}>
        <li
          className={classNames(
            "lux-menu-context__group",
            expanded && "is-expanded",
            section.id === activeSectionId && "is-active-group"
          )}
        >
          <button
            type="button"
            id={headerId}
            className="lux-menu-context__group-toggle"
            aria-expanded={expanded}
            onClick={this.handleGroupToggle(section, activeSectionId)}
          >
            <span className="lux-menu-context__group-accent" aria-hidden="true" />
            <span className="lux-menu-context__group-label">{section.label}</span>
            <span className="lux-menu-context__group-meta">
              <span className="lux-menu-context__group-count">{section.items.length}</span>
              <i
                className={classNames(
                  "fe",
                  expanded ? "fe-chevron-up" : "fe-chevron-down",
                  "lux-menu-context__group-chevron"
                )}
                aria-hidden="true"
              />
            </span>
          </button>
        </li>
        {expanded
          ? section.items.map((item, idx) => this.renderItem(item, `${section.id}-${idx}`))
          : null}
      </React.Fragment>
    );
  };

  render() {
    const { group, location } = this.props;
    if (!group) {
      return (
        <div className="lux-menu-context lux-menu-context--empty">
          <p className="lux-menu-context__empty">No modules available for this view.</p>
        </div>
      );
    }

    const sections = this.resolveSections();
    const itemCount = sections.reduce((sum, section) => sum + section.items.length, 0);
    const activeSectionId = findActiveSidebarNavSectionId(
      location && location.pathname,
      sections
    );

    return (
      <div className="lux-menu-context">
        <div className="lux-menu-context__header">
          <h2 className="lux-menu-context__title">{group.menuName}</h2>
          <span className="lux-menu-context__count" aria-label={`${itemCount} items`}>
            {itemCount}
          </span>
        </div>
        <nav
          className="lux-menu-context__nav"
          aria-label={`${group.menuName} menu`}
        >
          <ul className={classNames("lux-menu-context__list", "metismenu")}>
            {sections.map((section) => this.renderSection(section, activeSectionId))}
          </ul>
        </nav>
      </div>
    );
  }
}

export default ModuleContextMenu;
