export function getFooterModuleHref(module, permission) {
  const mod = permission && permission[module.accessKey];
  if (!mod || mod.active !== true) return null;
  const page = mod.defaultRedirectPage || "dashboard";
  return `${module.layout}/${page}`;
}

export function getActiveFooterModule(pathname) {
  const segment = (pathname || "").split("/").filter(Boolean)[0];
  if (segment === "hrms") {
    return FOOTER_MODULES.find((module) => module.id === "people") || null;
  }
  return FOOTER_MODULES.find((module) => module.id === segment) || null;
}
