import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isIntegrationCenterEnabled } from "config/integration-center.config";
import { INTEGRATION_ADAPTERS_PAGE_META } from "config/integration-center-nav.config";
import { buildAdapterInsights, buildAdapterKpis } from "config/integration-adapter.utils";
import { integrationCenterService } from "_services/integrationCenter.service";
import IntegrationsLuxPage, {
  IntegrationActionButton,
  IntegrationInsightPanel,
  IntegrationLuxPanel,
} from "views/integrations/components/IntegrationsLuxShared";
import AdapterRegister, {
  AdapterDetailDrawer,
  AdapterTransportFilter,
} from "views/integrations/components/AdapterRegister";
import {
  IntegrationSnapshotStrip,
  buildAdapterSnapshotMetrics,
} from "views/integrations/components/IntegrationAdapterUtils";

class IntegrationAdaptersPage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    adapters: [],
    kpiCards: [],
    insights: [],
    transportFilter: "ALL",
    selectedAdapter: null,
    drawerAdapter: null,
    testResult: null,
    syncResult: null,
    testing: false,
    syncing: false,
    busyId: null,
    actionBusyId: null,
  };

  componentDidMount() {
    this.loadData();
  }

  loadData = async () => {
    const { transportFilter } = this.state;
    this.setState({ loading: true, loadError: null });
    try {
      const filters = {};
      if (transportFilter !== "ALL") {
        filters.transport = transportFilter;
      }
      const result = await integrationCenterService.listAdapters(filters);
      const adapters = result.payload || [];
      this.setState({
        loading: false,
        dataSource: result.source,
        adapters,
        kpiCards: buildAdapterKpis(adapters),
        insights: buildAdapterInsights(adapters),
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load adapter registry.",
      });
    }
  };

  handleTransportChange = (transportFilter) => {
    this.setState({ transportFilter }, this.loadData);
  };

  handleTest = async (adapter) => {
    this.setState({
      actionBusyId: adapter.id,
      testing: true,
      testResult: null,
      loadError: null,
      drawerAdapter: adapter,
    });
    try {
      const result = await integrationCenterService.testAdapterConnection(adapter.id);
      this.setState({ testResult: result.payload || null });
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Connection test failed." });
    } finally {
      this.setState({ actionBusyId: null, testing: false });
    }
  };

  handleSync = async (adapter) => {
    this.setState({
      busyId: adapter.id,
      syncing: true,
      syncResult: null,
      loadError: null,
      drawerAdapter: adapter,
    });
    try {
      const result = await integrationCenterService.triggerAdapterSync(adapter.id);
      this.setState({ syncResult: result.payload || null });
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to trigger adapter sync." });
    } finally {
      this.setState({ busyId: null, syncing: false });
    }
  };

  render() {
    if (!isIntegrationCenterEnabled()) {
      return (
        <PersonaAccessDenied
          title="Connector adapters"
          message="Integration center is not enabled for this organization."
        />
      );
    }

    const {
      loading,
      loadError,
      dataSource,
      adapters,
      kpiCards,
      insights,
      transportFilter,
      selectedAdapter,
      drawerAdapter,
      testResult,
      syncResult,
      testing,
      syncing,
      busyId,
      actionBusyId,
    } = this.state;

    let drawerRow = drawerAdapter;
    if (drawerAdapter && adapters.length) {
      const refreshed = adapters.find((row) => row.id === drawerAdapter.id);
      if (refreshed) {
        drawerRow = refreshed;
      }
    }

    return (
      <IntegrationsLuxPage
        pageMeta={INTEGRATION_ADAPTERS_PAGE_META}
        pageId="adapters"
        shellTitle="Connector adapters"
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        heroActions={
          <IntegrationActionButton icon="fe fe-refresh-cw" onClick={this.loadData} disabled={loading}>
            Refresh
          </IntegrationActionButton>
        }
      >
        {loadError ? <p className="lux-integ-error">{loadError}</p> : null}
        <IntegrationInsightPanel insights={insights} />
        <IntegrationSnapshotStrip
          loading={loading}
          badgeIcon="fe fe-package"
          badgeLabel="Adapter throughput"
          metrics={buildAdapterSnapshotMetrics(adapters)}
        />
        <IntegrationLuxPanel
          title="Adapter wrappers"
          meta="Salesforce, leave feed, webhook, CSV, and SFTP transport adapters"
          icon="fe fe-package"
          accent="violet"
          featured
          actions={<AdapterTransportFilter value={transportFilter} onChange={this.handleTransportChange} />}
        >
          <AdapterRegister
            adapters={adapters}
            loading={loading}
            selectedId={selectedAdapter && selectedAdapter.id}
            onSelect={(row) => this.setState({ drawerAdapter: row, selectedAdapter: row, testResult: null, syncResult: null })}
            onTest={this.handleTest}
            onSync={this.handleSync}
            busyId={busyId}
            actionBusyId={actionBusyId}
          />
        </IntegrationLuxPanel>

        <AdapterDetailDrawer
          adapter={drawerRow}
          testResult={testResult}
          syncResult={syncResult}
          testing={testing}
          syncing={syncing}
          onClose={() => this.setState({ drawerAdapter: null, testResult: null, syncResult: null })}
          onTest={this.handleTest}
          onSync={this.handleSync}
        />
      </IntegrationsLuxPage>
    );
  }
}

export default IntegrationAdaptersPage;
