import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import { commonUtils } from "_helpers";

class PageInnerHeaderEmployeesSelectionMenu extends PureComponent {
  constructor() {
    super();
    this.state = {
      showEmployeePanel: false,
      selectedEmployeesIds: [],
      filterText: "",
      selectAll: false,
    };
    this.employeeTriggerRef = React.createRef();
    this.employeePanelRef = React.createRef();
  }

  componentDidMount() {
    this.initializeEmployeesIds();
    document.addEventListener("mousedown", this.handleOutsideClick);
  }

  componentDidUpdate(prevProps) {
    const employeesChanged = prevProps.employees !== this.props.employees;
    const selectionChanged =
      String(prevProps.selectedEmployeeId) !== String(this.props.selectedEmployeeId);

    if (!this.state.showEmployeePanel && (employeesChanged || selectionChanged)) {
      this.initializeEmployeesIds();
    }
  }

  componentWillUnmount() {
    document.removeEventListener("mousedown", this.handleOutsideClick);
  }

  handleOutsideClick = (event) => {
    if (!this.state.showEmployeePanel) return;
    const panel = this.employeePanelRef.current;
    const trigger = this.employeeTriggerRef.current;
    if (
      panel &&
      !panel.contains(event.target) &&
      trigger &&
      !trigger.contains(event.target)
    ) {
      this.closeEmployeePanel();
    }
  };

  getActiveEmployeeId = () => {
    const { selectedEmployeeId, allowAllTeamEmployees } = this.props;
    if (allowAllTeamEmployees && (selectedEmployeeId == null || selectedEmployeeId === "")) {
      return null;
    }
    if (selectedEmployeeId != null && selectedEmployeeId !== "") {
      return String(selectedEmployeeId);
    }
    return String(commonUtils.getCurrentUserId());
  };

  initializeEmployeesIds = () => {
    const activeEmployeeId = this.getActiveEmployeeId();
    const currentEmployee = commonUtils.getCurrentUser();
    const employeeMap = new Map();

    if (currentEmployee && currentEmployee.id != null) {
      employeeMap.set(String(currentEmployee.id), { ...currentEmployee });
    }

    (this.props.employees || []).forEach((employeeItem) => {
      employeeMap.set(String(employeeItem.id), { ...employeeItem });
    });

    const selectedEmployeesIds = commonUtils.sortArrayOfObjects(
      Array.from(employeeMap.values()).map((employeeItem) => ({
        ...employeeItem,
        isChecked: activeEmployeeId != null && String(employeeItem.id) === activeEmployeeId,
      })),
      true
    );

    this.setState({ selectedEmployeesIds });
  };

  getSelectedEmployeeCount = () =>
    (this.state.selectedEmployeesIds || []).filter((item) => item.isChecked).length;

  getTotalEmployeeCount = () => (this.state.selectedEmployeesIds || []).length;

  getSelectedEmployeeName = () => {
    if (this.props.allowAllTeamEmployees && this.getActiveEmployeeId() == null) {
      return "All team";
    }
    const selectedEmployee = this.state.selectedEmployeesIds.find(
      (employeeItem) => employeeItem.isChecked
    );
    return (selectedEmployee && selectedEmployee.name) || "";
  };

  selectAllTeam = () => {
    const cleared = this.state.selectedEmployeesIds.map((employeeItem) => ({
      ...employeeItem,
      isChecked: false,
    }));
    this.setState(
      { selectedEmployeesIds: cleared, showEmployeePanel: false, filterText: "", selectAll: false },
      () => this.props.handleEmployeesSelection(cleared)
    );
  };

  toggleEmployeePanel = () => {
    if (this.props.isLoading) return;
    if (this.state.showEmployeePanel) {
      this.closeEmployeePanel();
      return;
    }
    this.initializeEmployeesIds();
    this.setState({ showEmployeePanel: true, filterText: "", selectAll: false });
  };

  closeEmployeePanel = () => {
    this.setState({ showEmployeePanel: false, filterText: "", selectAll: false });
  };

  applyEmployeeSelection = () => {
    if (this.getSelectedEmployeeCount() === 0) return;
    this.props.handleEmployeesSelection(this.state.selectedEmployeesIds);
    this.setState({ showEmployeePanel: false, filterText: "", selectAll: false });
  };

  onSelectAllEmployees = (event) => {
    this.setState({
      selectAll: event.target.checked,
      selectedEmployeesIds: this.state.selectedEmployeesIds.map((employeeItem) => ({
        ...employeeItem,
        isChecked: event.target.checked,
      })),
    });
  };

  onEmployeeCheckChange = (event) => {
    const employeeId = event.target.value;
    const isChecked = event.target.checked;
    const singleSelection = this.props.enableSingleSelection === true;
    const closeImmediately =
      singleSelection && this.props.applyEmployeeSelectionImmediately === true;

    this.setState(
      (prevState) => {
        const selectedEmployeesIds = prevState.selectedEmployeesIds.map((employeeItem) => {
          if (String(employeeItem.id) === String(employeeId)) {
            return { ...employeeItem, isChecked };
          }
          if (singleSelection && isChecked) {
            return { ...employeeItem, isChecked: false };
          }
          return employeeItem;
        });

        return {
          selectedEmployeesIds,
          selectAll:
            !singleSelection &&
            selectedEmployeesIds.length > 0 &&
            selectedEmployeesIds.every((item) => item.isChecked),
          showEmployeePanel: closeImmediately ? false : prevState.showEmployeePanel,
        };
      },
      () => {
        if (closeImmediately) {
          this.props.handleEmployeesSelection(this.state.selectedEmployeesIds);
        }
      }
    );
  };

  onFilterChange = (event) => {
    this.setState({ filterText: event.target.value });
  };

  renderTriggerLabel = () => {
    const { showEmployeeNameDropDownLabel, enableSingleSelection } = this.props;
    if (showEmployeeNameDropDownLabel && enableSingleSelection === true) {
      return (
        <span className="lux-page-header__employee-name" title={this.getSelectedEmployeeName()}>
          {this.getSelectedEmployeeName()}
        </span>
      );
    }
    return <span>Employees</span>;
  };

  render() {
    const { employees, enabled, isLoading, enableSingleSelection } = this.props;

    if (!employees || employees.length === 0 || !enabled) {
      return null;
    }

    const selectedCount = this.getSelectedEmployeeCount();
    const totalCount = this.getTotalEmployeeCount();
    const showCountBadge = !(
      this.props.showEmployeeNameDropDownLabel && enableSingleSelection === true
    );
    const showFooter =
      !(enableSingleSelection && this.props.applyEmployeeSelectionImmediately === true) &&
      totalCount > 1;
    const filteredEmployees = this.state.selectedEmployeesIds.filter(
      (employee) =>
        !this.state.filterText ||
        commonUtils.stringContainsString(employee.name, this.state.filterText)
    );
    const currentUserId = commonUtils.getCurrentUserId();

    return (
      <div className="lux-page-header__employee-wrap" ref={this.employeeTriggerRef}>
        <button
          type="button"
          className={classNames("lux-page-header__employee-btn", {
            "is-open": this.state.showEmployeePanel,
          })}
          onClick={this.toggleEmployeePanel}
          disabled={isLoading}
          aria-expanded={this.state.showEmployeePanel}
          title="Select employees"
        >
          <i className="fe fe-user" aria-hidden="true" />
          {this.renderTriggerLabel()}
          {showCountBadge && (
            <span className="lux-page-header__team-count">{selectedCount}</span>
          )}
        </button>

        {this.state.showEmployeePanel && (
          <div className="lux-page-header__employee-panel" ref={this.employeePanelRef}>
            <header className="lux-page-header__team-panel-head">
              <div className="lux-page-header__team-panel-head-main">
                <span className="lux-page-header__team-panel-icon" aria-hidden="true">
                  <i className="fe fe-users" />
                </span>
                <div>
                  <span className="lux-page-header__team-panel-eyebrow">People</span>
                  <strong>Select employees</strong>
                  <span className="lux-page-header__team-panel-meta">
                    {selectedCount} of {totalCount} selected
                  </span>
                </div>
              </div>
              <button
                type="button"
                className="lux-page-header__team-panel-close"
                onClick={this.closeEmployeePanel}
                aria-label="Close employee selector"
              >
                <i className="fe fe-x" aria-hidden="true" />
              </button>
            </header>

            <div className="lux-page-header__team-panel-body">
              <label className="lux-page-header__team-search">
                <i className="fe fe-search" aria-hidden="true" />
                <input
                  type="search"
                  value={this.state.filterText}
                  onChange={this.onFilterChange}
                  placeholder="Search employees..."
                />
              </label>

              {!enableSingleSelection && totalCount > 1 && (
                <label className="lux-page-header__team-all">
                  <input
                    type="checkbox"
                    className="lux-page-header__team-checkbox"
                    checked={this.state.selectAll}
                    onChange={this.onSelectAllEmployees}
                    disabled={isLoading}
                  />
                  <span className="lux-page-header__team-all-label">Select all employees</span>
                </label>
              )}

              <ul className="lux-page-header__team-list">
                {this.props.allowAllTeamEmployees && enableSingleSelection === true && (
                  <li>
                    <label
                      className={classNames("lux-page-header__team-item", "lux-page-header__team-item--all", {
                        "is-selected": this.getActiveEmployeeId() == null,
                      })}
                    >
                      <input
                        type="checkbox"
                        className="lux-page-header__team-checkbox"
                        checked={this.getActiveEmployeeId() == null}
                        onChange={() => this.selectAllTeam()}
                        disabled={isLoading}
                      />
                      <span className="lux-page-header__team-item-mark" aria-hidden="true">
                        <i className="fe fe-check" />
                      </span>
                      <span className="lux-page-header__team-item-name">All team</span>
                      <span className="lux-page-header__team-item-hint">Timeline &amp; Gantt</span>
                    </label>
                  </li>
                )}
                {filteredEmployees.length > 0 ? (
                  filteredEmployees.map((employee) => (
                    <li key={employee.id}>
                      <label
                        className={classNames("lux-page-header__team-item", {
                          "is-selected": employee.isChecked,
                          "is-self": String(employee.id) === String(currentUserId),
                        })}
                      >
                        <input
                          type="checkbox"
                          className="lux-page-header__team-checkbox"
                          checked={employee.isChecked}
                          onChange={this.onEmployeeCheckChange}
                          value={employee.id}
                          disabled={isLoading || totalCount === 1}
                        />
                        <span className="lux-page-header__team-item-mark" aria-hidden="true">
                          <i className="fe fe-check" />
                        </span>
                        <span className="lux-page-header__team-item-name">{employee.name}</span>
                      </label>
                    </li>
                  ))
                ) : (
                  <li className="lux-page-header__team-empty">
                    No employees match your search.
                  </li>
                )}
              </ul>
            </div>

            {showFooter && (
              <footer className="lux-page-header__team-footer">
                <button
                  type="button"
                  className="lux-page-header__team-cancel"
                  onClick={this.closeEmployeePanel}
                >
                  Cancel
                </button>
                <button
                  type="button"
                  className="lux-page-header__team-apply"
                  onClick={this.applyEmployeeSelection}
                  disabled={selectedCount === 0}
                >
                  Apply selection
                </button>
              </footer>
            )}
          </div>
        )}
      </div>
    );
  }
}

export default PageInnerHeaderEmployeesSelectionMenu;
