import React, { Component } from "react";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isProjectGovernanceEnabled, ISSUE_PRIORITIES, ISSUE_STATUSES } from "config/project-governance.config";
import {
  buildIssueAgingModel,
  buildIssueInsights,
  buildIssueMetrics,
  buildProjectOptionsFromIssues,
  filterIssues,
  ISSUE_PRIORITY_FILTER_OPTIONS,
  ISSUE_STATUS_FILTER_OPTIONS,
  validateIssuePayload,
} from "config/project-governance.utils";
import { projectGovernanceService } from "_services/projectGovernance.service";
import { GOVERNANCE_PAGE_IDS, getGovernanceQuickLinks } from "config/project-governance-nav.config";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { ResourcesActionButton } from "views/resources/components/ResourcesLuxShared";
import GovernanceLuxPage, {
  GovernanceLuxFilters,
  GovernanceLuxPanel,
} from "views/project/components/ProjectGovernanceLuxShared";
import IssueAgingPanel from "views/project/components/IssueAgingPanel";
import IssueDrawer from "views/project/components/IssueDrawer";
import IssueRegister from "views/project/components/IssueRegister";

class ProjectIssuesPage extends Component {
  state = {
    issues: [],
    actions: [],
    loading: true,
    loadError: null,
    dataSource: null,
    query: "",
    priorityFilter: "ALL",
    statusFilter: "ALL",
    projectFilter: "ALL",
    drawerOpen: false,
    selectedIssue: null,
    creating: false,
    createError: null,
    draft: {
      title: "",
      projectId: "",
      priority: ISSUE_PRIORITIES.P2,
      ownerName: "",
      description: "",
      dueDate: "",
    },
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Issues & actions");
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const [issuesRes, actionsRes] = await Promise.all([
        projectGovernanceService.listIssues(),
        projectGovernanceService.listIssueActions(),
      ]);
      this.setState({
        issues: issuesRes.payload || [],
        actions: actionsRes.payload || [],
        loading: false,
        dataSource: issuesRes.source || null,
      });
    } catch (e) {
      this.setState({ loading: false, loadError: "Unable to load issues.", issues: [], actions: [] });
    }
  };

  loadIssueActions = async (issueId) => {
    const result = await projectGovernanceService.listIssueActions({ issueId });
    return result.payload || [];
  };

  openDrawer = async (issue) => {
    const detail = await projectGovernanceService.getIssue(issue.id);
    this.setState({
      drawerOpen: true,
      selectedIssue: (detail && detail.payload) || issue,
    });
  };

  closeDrawer = () => {
    this.setState({ drawerOpen: false, selectedIssue: null });
  };

  handleSaveIssue = async (issueId, payload) => {
    await projectGovernanceService.updateIssue(issueId, payload);
    await this.loadData();
  };

  handleCloseIssue = async (issueId) => {
    await projectGovernanceService.closeIssue(issueId);
    await this.loadData();
  };

  handleCreateAction = async (payload) => {
    await projectGovernanceService.createIssueAction(payload);
    await this.loadData();
  };

  handleCompleteAction = async (actionId) => {
    await projectGovernanceService.completeIssueAction(actionId);
    await this.loadData();
  };

  handleCreateIssue = async (e) => {
    e.preventDefault();
    const { draft, issues } = this.state;
    const project = buildProjectOptionsFromIssues(issues).find((row) => row.id === draft.projectId);
    const payload = {
      ...draft,
      projectName: project && project.label,
      projectCode: project && project.code,
      status: ISSUE_STATUSES.OPEN,
    };
    const validation = validateIssuePayload(payload);
    if (!validation.valid) {
      this.setState({ createError: validation.reason });
      return;
    }

    this.setState({ creating: true, createError: null });
    try {
      await projectGovernanceService.createIssue(payload);
      await this.loadData();
      this.setState({
        creating: false,
        draft: {
          title: "",
          projectId: "",
          priority: ISSUE_PRIORITIES.P2,
          ownerName: "",
          description: "",
          dueDate: "",
        },
      });
    } catch (err) {
      this.setState({
        creating: false,
        createError: (err && err.message) || "Unable to create issue.",
      });
    }
  };

  render() {
    if (!isProjectGovernanceEnabled()) {
      return <PersonaAccessDenied featureLabel="Project issues" />;
    }

    const {
      issues,
      actions,
      loading,
      loadError,
      dataSource,
      query,
      priorityFilter,
      statusFilter,
      projectFilter,
      drawerOpen,
      selectedIssue,
      creating,
      createError,
      draft,
    } = this.state;

    const filtered = filterIssues(issues, {
      query,
      priority: priorityFilter,
      status: statusFilter,
      projectId: projectFilter === "ALL" ? undefined : projectFilter,
    });
    const metrics = buildIssueMetrics(issues, actions);
    const insights = buildIssueInsights(metrics, issues);
    const projectOptions = buildProjectOptionsFromIssues(issues);
    const agingModel = buildIssueAgingModel(issues, { projectId: projectFilter });

    return (
      <GovernanceLuxPage
        pageId={GOVERNANCE_PAGE_IDS.ISSUES}
        dataSource={dataSource}
        demoLabel="Demo issue data"
        loading={loading}
        insights={insights}
        quickLinks={getGovernanceQuickLinks(GOVERNANCE_PAGE_IDS.ISSUES)}
        kpiCards={[
          { id: "open", label: "Open issues", value: metrics.open, tone: "blue", icon: "fe fe-alert-circle" },
          { id: "p1", label: "P1 priority", value: metrics.p1, tone: "rose", icon: "fe fe-alert-octagon" },
          { id: "actions", label: "Open actions", value: metrics.openActions, tone: "amber", icon: "fe fe-check-square" },
          { id: "sla", label: "Action SLA", value: `${metrics.actionSlaRate}%`, tone: "violet", icon: "fe fe-clock" },
        ]}
        heroActions={
          <ResourcesActionButton to="/project/governance" icon="fe fe-shield" variant="ghost">
            Governance hub
          </ResourcesActionButton>
        }
      >
        <GovernanceLuxPanel
          title="Open issue aging"
          meta={`${agingModel.openCount} open · avg ${metrics.avgAgeDays}d`}
          icon="fe fe-bar-chart"
          accent="rose"
        >
          <IssueAgingPanel model={agingModel} loading={loading} />
        </GovernanceLuxPanel>

        <GovernanceLuxPanel
          title="Issues & actions"
          meta={`${filtered.length} visible · ${metrics.openActions} open actions`}
          icon="fe fe-alert-circle"
          accent="rose"
        >
          <GovernanceLuxFilters>
            <label className="lux-gov-filters__search">
              <i className="fe fe-search" aria-hidden="true" />
              <input
                type="search"
                placeholder="Search issue, project, owner, or description"
                value={query}
                onChange={(e) => this.setState({ query: e.target.value })}
              />
            </label>
            <select
              className="lux-gov-filters__select"
              value={projectFilter}
              onChange={(e) => this.setState({ projectFilter: e.target.value })}
            >
              {projectOptions.map((option) => (
                <option key={option.id} value={option.id}>
                  {option.label}
                </option>
              ))}
            </select>
            <div className="lux-gov-filters__chips" role="tablist" aria-label="Issue priority">
              {ISSUE_PRIORITY_FILTER_OPTIONS.map((option) => (
                <button
                  key={option.id}
                  type="button"
                  role="tab"
                  aria-selected={priorityFilter === option.id}
                  className={classNames("lux-gov-filters__chip", { "is-active": priorityFilter === option.id })}
                  onClick={() => this.setState({ priorityFilter: option.id })}
                >
                  {option.label}
                </button>
              ))}
            </div>
            <div className="lux-gov-filters__chips" role="tablist" aria-label="Issue status">
              {ISSUE_STATUS_FILTER_OPTIONS.map((option) => (
                <button
                  key={option.id}
                  type="button"
                  role="tab"
                  aria-selected={statusFilter === option.id}
                  className={classNames("lux-gov-filters__chip", { "is-active": statusFilter === option.id })}
                  onClick={() => this.setState({ statusFilter: option.id })}
                >
                  {option.label}
                </button>
              ))}
            </div>
          </GovernanceLuxFilters>

          <form className="lux-gov-issue-form" onSubmit={this.handleCreateIssue}>
            <p className="lux-gov-issue-form__title">Log new issue</p>
            <div className="lux-gov-issue-form__fields">
              <label>
                Title
                <input
                  value={draft.title}
                  onChange={(e) => this.setState({ draft: { ...draft, title: e.target.value } })}
                  placeholder="Describe the blocker"
                />
              </label>
              <label>
                Project
                <select
                  value={draft.projectId}
                  onChange={(e) => this.setState({ draft: { ...draft, projectId: e.target.value } })}
                >
                  <option value="">Select project</option>
                  {projectOptions
                    .filter((row) => row.id !== "ALL")
                    .map((option) => (
                      <option key={option.id} value={option.id}>
                        {option.label}
                      </option>
                    ))}
                </select>
              </label>
              <label>
                Priority
                <select
                  value={draft.priority}
                  onChange={(e) => this.setState({ draft: { ...draft, priority: e.target.value } })}
                >
                  {Object.values(ISSUE_PRIORITIES).map((value) => (
                    <option key={value} value={value}>
                      {value}
                    </option>
                  ))}
                </select>
              </label>
              <label>
                Owner
                <input
                  value={draft.ownerName}
                  onChange={(e) => this.setState({ draft: { ...draft, ownerName: e.target.value } })}
                />
              </label>
              <label>
                Due
                <input
                  type="date"
                  value={draft.dueDate}
                  onChange={(e) => this.setState({ draft: { ...draft, dueDate: e.target.value } })}
                />
              </label>
              <button type="submit" className="lux-gov-issue-form__submit" disabled={creating}>
                {creating ? "Logging…" : "Add issue"}
              </button>
            </div>
            <label className="lux-gov-issue-form__wide">
              Description
              <textarea
                rows={2}
                value={draft.description}
                onChange={(e) => this.setState({ draft: { ...draft, description: e.target.value } })}
              />
            </label>
            {createError ? <p className="lux-gov-issue-form__error">{createError}</p> : null}
          </form>

          {loadError ? (
            <LuxRegisterEmptyState title="Unable to load issues" copy={loadError} onRetry={this.loadData} />
          ) : null}

          {!loadError && !loading && filtered.length === 0 ? (
            <LuxRegisterEmptyState
              title="No issues match"
              copy="Adjust filters or log a new delivery blocker."
            />
          ) : null}

          <IssueRegister rows={filtered} loading={loading} onSelect={this.openDrawer} />
        </GovernanceLuxPanel>

        <IssueDrawer
          open={drawerOpen}
          issue={selectedIssue}
          onClose={this.closeDrawer}
          onSave={this.handleSaveIssue}
          onCloseIssue={this.handleCloseIssue}
          onCreateAction={this.handleCreateAction}
          onCompleteAction={this.handleCompleteAction}
          onLoadActions={this.loadIssueActions}
        />
      </GovernanceLuxPage>
    );
  }
}

export default ProjectIssuesPage;
