import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isPerformanceManagementEnabled } from "config/performance-management.config";
import { PERFORMANCE_DASHBOARD_PAGE_META } from "config/performance-management-nav.config";
import { performanceManagementService } from "_services/performanceManagement.service";
import PerformanceLuxPage, {
  PerformanceActionButton,
  PerformanceInsightPanel,
  PerformanceLuxPanel,
} from "views/performance/components/PerformanceLuxShared";
import PerformanceAnalyticsPanel from "views/performance/components/PerformanceAnalyticsPanel";
import PerformanceAiEvidencePanel from "views/performance/components/PerformanceAiEvidencePanel";
import ReviewCycleRegister from "views/performance/components/ReviewCycleRegister";
import GoalRegister from "views/performance/components/GoalRegister";

class PerformanceDashboardPage extends Component {
  state = { loading: true, loadError: null, dataSource: null, payload: {} };

  componentDidMount() {
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await performanceManagementService.getOverview({});
      this.setState({ loading: false, dataSource: result.source, payload: result.payload || {} });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load performance dashboard.",
      });
    }
  };

  render() {
    if (!isPerformanceManagementEnabled()) {
      return <PersonaAccessDenied featureLabel="Performance dashboard" />;
    }

    const { loading, loadError, dataSource, payload } = this.state;

    return (
      <PerformanceLuxPage
        pageMeta={PERFORMANCE_DASHBOARD_PAGE_META}
        pageId="dashboard"
        shellTitle="Performance dashboard"
        dataSource={dataSource}
        kpiCards={payload.kpiCards}
        loading={loading}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        heroActions={
          <PerformanceActionButton icon="fe fe-refresh-cw" onClick={this.loadData} disabled={loading}>
            Refresh
          </PerformanceActionButton>
        }
      >
        {loadError ? <div className="lux-perf-alert">{loadError}</div> : null}
        <PerformanceInsightPanel insights={payload.insights} />
        <PerformanceAnalyticsPanel analytics={payload.analytics} loading={loading} />
        <div className="lux-perf-page-grid">
          <PerformanceLuxPanel title="Active cycles" meta="Review windows in flight" icon="fe fe-calendar" accent="violet">
            <ReviewCycleRegister cycles={(payload.cycles || []).filter((row) => row.status === "active")} loading={loading} />
          </PerformanceLuxPanel>
          <PerformanceLuxPanel title="Goals needing attention" meta="At risk or behind" icon="fe fe-target" accent="amber">
            <GoalRegister
              goals={(payload.goals || []).filter((row) => row.status === "at_risk" || row.status === "behind")}
              loading={loading}
            />
          </PerformanceLuxPanel>
        </div>
        <PerformanceAiEvidencePanel evidence={payload.aiEvidence} loading={loading} />
      </PerformanceLuxPage>
    );
  }
}

export default PerformanceDashboardPage;
