import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isPerformanceManagementEnabled } from "config/performance-management.config";
import { GROWTH_PLANS_PAGE_META } from "config/performance-management-nav.config";
import { performanceManagementService } from "_services/performanceManagement.service";
import PerformanceLuxPage, { PerformanceActionButton, PerformanceLuxPanel } from "views/performance/components/PerformanceLuxShared";
import GrowthPlanRegister from "views/performance/components/GrowthPlanRegister";
import { GrowthPlanCreateDrawer } from "views/performance/components/PerformanceCreateDrawers";

class GrowthPlansPage extends Component {
  state = { loading: true, plans: [], kpiCards: [], dataSource: null, createOpen: false, busy: false };

  componentDidMount() {
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true });
    try {
      const [overview, plansResult] = await Promise.all([
        performanceManagementService.getOverview({}),
        performanceManagementService.listGrowthPlans({}),
      ]);
      this.setState({
        loading: false,
        dataSource: plansResult.source,
        plans: plansResult.payload || [],
        kpiCards: (overview.payload && overview.payload.kpiCards) || [],
      });
    } catch (error) {
      this.setState({ loading: false, plans: [] });
    }
  };

  handleCreate = async (payload) => {
    this.setState({ busy: true });
    try {
      await performanceManagementService.createGrowthPlan(payload);
      this.setState({ createOpen: false, busy: false });
      await this.loadData();
    } catch (error) {
      this.setState({ busy: false });
    }
  };

  render() {
    if (!isPerformanceManagementEnabled()) {
      return <PersonaAccessDenied featureLabel="Growth plans" />;
    }

    const { loading, plans, kpiCards, dataSource, createOpen, busy } = this.state;

    return (
      <PerformanceLuxPage
        pageMeta={GROWTH_PLANS_PAGE_META}
        pageId="growth-plans"
        shellTitle="Growth plans"
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        heroActions={
          <>
            <PerformanceActionButton icon="fe fe-refresh-cw" onClick={this.loadData} disabled={loading}>
              Refresh
            </PerformanceActionButton>
            <PerformanceActionButton variant="primary" icon="fe fe-plus" onClick={() => this.setState({ createOpen: true })}>
              Create plan
            </PerformanceActionButton>
          </>
        }
      >
        <PerformanceLuxPanel title="Development register" meta="Competency targets and milestones" icon="fe fe-trending-up" accent="rose" featured>
          <GrowthPlanRegister plans={plans} loading={loading} />
        </PerformanceLuxPanel>
        <GrowthPlanCreateDrawer open={createOpen} onClose={() => this.setState({ createOpen: false })} onCreate={this.handleCreate} busy={busy} />
      </PerformanceLuxPage>
    );
  }
}

export default GrowthPlansPage;
