import { shouldUseTimesheetApprovalWorkflow } from "_helpers/timesheetApproval.config";
import {
  getTimesheetStatusMeta,
  normalizeTimesheetStatus,
  readAttributeValue,
} from "./timesheetSummary.utils";

const TASK_BOARD_SOURCE = "TASK_BOARD";

function deriveLegacyTimesheetEntryStatus(entry, taskIsNew) {
  const explicit = normalizeTimesheetStatus(
    readAttributeValue(entry && entry.status) ||
      readAttributeValue(entry && entry.timesheetStatus)
  );
  if (explicit) return explicit;

  const mins = parseInt((entry && entry.timesheetTimeMins) || 0, 10);
  if (mins <= 0) return null;

  if (entry.isNew === true || entry.isUpdated === true || taskIsNew === true) {
    return "DRAFT";
  }
  if (entry.isStaged === true || entry.dataLayer === "STAGED") {
    return "DRAFT";
  }
  // Editable / unlocked hours are still draft (e.g. after Save draft). Only locked
  // cells without an explicit status are treated as approved for display.
  if (entry.isEditable !== false) {
    return "DRAFT";
  }

  return "APPROVED";
}

function isSubmittedOrApprovedStatus(entry) {
  const status = normalizeTimesheetStatus(
    readAttributeValue(entry && entry.status) ||
      readAttributeValue(entry && entry.timesheetStatus)
  );
  return status === "APPROVED" || status === "PENDING" || status === "PENDING_APPROVAL";
}

/**
 * Cell editability.
 * Flag OFF (legacy): cells are editable unless explicitly locked (`isEditable === false`).
 * Flag ON: trust API `isEditable` from merge/staging, but never allow edit once
 * submitted/approved even if staging overlay left `isEditable` true.
 */
export function isTimesheetCellEditable(entry, taskIsNew) {
  if (taskIsNew === true) {
    return true;
  }
  if (!shouldUseTimesheetApprovalWorkflow()) {
    if (!entry) {
      return true;
    }
    return entry.isEditable !== false;
  }
  if (!entry) {
    return false;
  }
  if (isSubmittedOrApprovedStatus(entry)) {
    return false;
  }
  return entry.isEditable === true;
}

export function isTimesheetCellReadonly(entry, taskIsNew) {
  if (!entry || taskIsNew === true) {
    return false;
  }
  const mins = parseInt(entry.timesheetTimeMins || 0, 10);
  if (mins <= 0) {
    return false;
  }
  if (!shouldUseTimesheetApprovalWorkflow()) {
    return entry.isEditable === false;
  }
  if (isSubmittedOrApprovedStatus(entry)) {
    return true;
  }
  return entry.isEditable !== true;
}

export function resolveTimesheetEntryStatus(entry, taskIsNew) {
  if (!shouldUseTimesheetApprovalWorkflow() || !entry) {
    // Still honor explicit staged statuses when a weekId is present (approval path).
    if (entry && entry.weekId) {
      const stagedStatus = normalizeTimesheetStatus(
        readAttributeValue(entry.status) || readAttributeValue(entry.timesheetStatus)
      );
      if (stagedStatus) return stagedStatus === "PENDING_APPROVAL" ? "PENDING" : stagedStatus;
    }
    return deriveLegacyTimesheetEntryStatus(entry, taskIsNew);
  }

  const apiStatus = normalizeTimesheetStatus(
    readAttributeValue(entry.status) || readAttributeValue(entry.timesheetStatus)
  );
  if (apiStatus) {
    return apiStatus === "PENDING_APPROVAL" ? "PENDING" : apiStatus;
  }

  if (entry.hasOpenConflict === true) {
    return "PENDING";
  }
  if (entry.isStaged === true || entry.dataLayer === "STAGED") {
    return "DRAFT";
  }
  if (entry.dataLayer === "APPROVED" || entry.isStaged === false) {
    if (entry.source === TASK_BOARD_SOURCE) {
      return "APPROVED";
    }
    return deriveLegacyTimesheetEntryStatus(entry, taskIsNew);
  }

  return deriveLegacyTimesheetEntryStatus(entry, taskIsNew);
}

export function getTimesheetCellBadges(entry) {
  if (!shouldUseTimesheetApprovalWorkflow() || !entry) {
    return [];
  }

  const badges = [];
  const mins = parseInt(entry.timesheetTimeMins || 0, 10);
  if (mins <= 0) {
    return badges;
  }

  if (entry.source === TASK_BOARD_SOURCE) {
    badges.push({
      key: "task-board",
      label: "Board",
      tone: "violet",
      icon: "fe-layers",
      title: "Logged from task board (auto-approved)",
    });
  }
  if (entry.hasOpenConflict === true) {
    badges.push({
      key: "conflict",
      label: "Conflict",
      tone: "rose",
      icon: "fe-alert-triangle",
      title: "Resolve overlap before approval",
    });
  }

  const statusKey = resolveTimesheetEntryStatus(entry, false);
  const isOrphanStaged =
    entry.isStaged === true &&
    (entry.dataLayer === "STAGED" || !entry.taskActivityId) &&
    !entry.taskActivityId &&
    mins > 0;
  if (isOrphanStaged && (statusKey === "DRAFT" || statusKey === "APPROVED")) {
    badges.push({
      key: "not-posted",
      label: "Not posted",
      tone: "amber",
      icon: "fe-alert-circle",
      title: "Staged hours only — not yet posted to work item activities. Reopen, submit, and approve to post.",
    });
  } else if (statusKey && statusKey !== "APPROVED" && statusKey !== "DRAFT") {
    const meta = getTimesheetStatusMeta(statusKey);
    badges.push({
      key: `status-${statusKey}`,
      label: meta.label,
      tone: meta.tone,
      icon: meta.icon,
      title: meta.hint,
    });
  } else if (statusKey === "DRAFT" && entry.isStaged === true) {
    badges.push({
      key: "staged",
      label: "Draft",
      tone: "slate",
      icon: "fe-edit-3",
      title: "Staged — not yet approved",
    });
  }

  return badges;
}

export function getTimesheetCellClassNames(entry, taskIsNew, baseClasses) {
  const classes = { ...(baseClasses || {}) };
  if (!shouldUseTimesheetApprovalWorkflow() || !entry) {
    return classes;
  }

  const mins = parseInt(entry.timesheetTimeMins || 0, 10);
  if (mins <= 0 && entry.isEditable !== true) {
    return classes;
  }

  if (entry.dataLayer === "APPROVED" || (entry.isStaged === false && entry.dataLayer !== "STAGED")) {
    classes["is-layer-approved"] = true;
  }
  if (entry.dataLayer === "STAGED" || entry.isStaged === true) {
    classes["is-layer-staged"] = true;
  }
  if (entry.dataLayer === "BOTH") {
    classes["is-layer-both"] = true;
  }
  if (entry.hasOpenConflict === true) {
    classes["is-conflict"] = true;
  }
  if (entry.source === TASK_BOARD_SOURCE) {
    classes["is-task-board"] = true;
  }

  const statusKey = resolveTimesheetEntryStatus(entry, taskIsNew);
  if (statusKey) {
    classes[`is-status-${statusKey.toLowerCase()}`] = true;
  }
  if (isTimesheetCellReadonly(entry, taskIsNew)) {
    classes["is-readonly-approved"] = true;
  }

  return classes;
}
