import React from "react";
import classNames from "classnames/bind";
import CustomInput from "views/common/fragments/formfields/CustomInput";
import { commonUtils } from "_helpers";
import { resolveOptionLabel } from "./feedbackTemplateEditor.utils";

const FIELD_ICONS = {
  type: "fe-layers",
  subType: "fe-filter",
  name: "fe-type",
  description: "fe-align-left",
  restrictedByUserTeamIds: "fe-shield",
};

function LuxFieldShell({ icon, title, hint, children, span = "half" }) {
  return (
    <div
      className={classNames("lux-ft-field", {
        "lux-ft-field--half": span === "half",
        "lux-ft-field--full": span === "full",
      })}
    >
      <div className="lux-ft-field__head">
        <span className="lux-ft-field__icon" aria-hidden="true">
          <i className={`fe ${icon}`} />
        </span>
        <div className="lux-ft-field__labels">
          <span className="lux-ft-field__title">{title}</span>
          {hint && <span className="lux-ft-field__hint">{hint}</span>}
        </div>
      </div>
      <div className="lux-ft-field__control">{children}</div>
    </div>
  );
}

function ReadOnlyFact({ label, value, icon }) {
  return (
    <div className="lux-ft-fact">
      <span className="lux-ft-fact__icon" aria-hidden="true">
        <i className={`fe ${icon}`} />
      </span>
      <div>
        <span className="lux-ft-fact__label">{label}</span>
        <strong className="lux-ft-fact__value">{value || "—"}</strong>
      </div>
    </div>
  );
}

export default function LuxFeedbackTemplateDetailsSection({
  feedbackTemplateRequest,
  editMode,
  fieldConfig,
  onChange,
  onFormError,
  feedbackTypeOptions,
  feedbackSubTypeOptions,
  allUserTeams,
}) {
  const req = feedbackTemplateRequest || {};
  const readOnly = !editMode;
  const teamOptions =
    allUserTeams && commonUtils.convertObjectToSelectObject(allUserTeams);

  const inputProps = {
    fieldConfig,
    mappingObject: req,
    onChange,
    onFormError,
    menuPortal: true,
    menuPortalZIndex: 10070,
  };

  if (readOnly && !req.id) {
    return (
      <section className="lux-ft-details lux-ft-details--empty">
        <div className="lux-ft-details__empty">
          <i className="fe fe-file-text" aria-hidden="true" />
          <strong>Template details</strong>
          <p>Select a template from the library or create a new one to edit details.</p>
        </div>
      </section>
    );
  }

  return (
    <section className="lux-ft-details" aria-labelledby="lux-ft-details-heading">
      <header className="lux-ft-details__head">
        <div className="lux-ft-details__head-icon" aria-hidden="true">
          <i className="fe fe-file-text" />
        </div>
        <div className="lux-ft-details__head-copy">
          <h3 id="lux-ft-details-heading">Template details</h3>
          <p>How this template is labeled, classified, and shared across teams.</p>
        </div>
      </header>

      {readOnly ? (
        <div className="lux-ft-details__readonly">
          <div className="lux-ft-details__facts">
            <ReadOnlyFact
              icon={FIELD_ICONS.type}
              label="Type"
              value={resolveOptionLabel(feedbackTypeOptions, req.type)}
            />
            <ReadOnlyFact
              icon={FIELD_ICONS.subType}
              label="Sub type"
              value={resolveOptionLabel(feedbackSubTypeOptions, req.subType)}
            />
            <ReadOnlyFact icon={FIELD_ICONS.name} label="Name" value={req.name} />
          </div>
          {req.description && (
            <div className="lux-ft-details__description-block">
              <span className="lux-ft-details__description-label">Description</span>
              <p>{req.description}</p>
            </div>
          )}
          <div className="lux-ft-details__access-readonly">
            <ReadOnlyFact
              icon={FIELD_ICONS.restrictedByUserTeamIds}
              label="Team access"
              value={
                req.restrictedByUserTeamIds && req.restrictedByUserTeamIds.length
                  ? `${req.restrictedByUserTeamIds.length} restricted team(s)`
                  : "Available to all teams"
              }
            />
          </div>
        </div>
      ) : (
        <div className="lux-ft-details__body">
          <div className="lux-ft-details__grid">
            <LuxFieldShell icon={FIELD_ICONS.type} title="Type" hint="Item category for this template">
              <CustomInput
                readOnly={readOnly}
                type="select"
                name="type"
                fieldConfig={fieldConfig}
                placeholder="Select type"
                options={feedbackTypeOptions}
                {...inputProps}
              />
            </LuxFieldShell>

            <LuxFieldShell icon={FIELD_ICONS.subType} title="Sub type" hint="Narrows when this template applies">
              <CustomInput
                readOnly={readOnly}
                type="select"
                name="subType"
                fieldConfig={fieldConfig}
                placeholder="Select sub type"
                options={feedbackSubTypeOptions}
                {...inputProps}
              />
            </LuxFieldShell>

            <LuxFieldShell
              icon={FIELD_ICONS.name}
              title="Template name"
              hint="Shown when choosing a template"
              span="full"
            >
              <CustomInput
                readOnly={readOnly}
                inputtype="text"
                name="name"
                fieldConfig={fieldConfig}
                placeholder="e.g. Quarterly client satisfaction"
                datatype="alpnumspl"
                {...inputProps}
              />
            </LuxFieldShell>

            <LuxFieldShell
              icon={FIELD_ICONS.description}
              title="Description"
              hint="Optional context for admins and managers"
              span="full"
            >
              <CustomInput
                readOnly={readOnly}
                name="description"
                type="textarea"
                height="72px"
                fieldConfig={fieldConfig}
                placeholder="Who should use this template and when?"
                datatype="alpnumspl"
                {...inputProps}
              />
            </LuxFieldShell>
          </div>

          <div className="lux-ft-details__access">
            <header className="lux-ft-details__access-head">
              <span className="lux-ft-details__access-icon" aria-hidden="true">
                <i className="fe fe-shield" />
              </span>
              <div>
                <h4>Access control</h4>
                <p>Limit which teams can select this template. Leave empty for everyone.</p>
              </div>
            </header>
            <LuxFieldShell
              icon={FIELD_ICONS.restrictedByUserTeamIds}
              title="Restricted to teams"
              span="full"
            >
              <CustomInput
                readOnly={readOnly}
                type="select"
                name="restrictedByUserTeamIds"
                fieldConfig={fieldConfig}
                placeholder="All teams (no restriction)"
                options={teamOptions}
                multi
                {...inputProps}
              />
            </LuxFieldShell>
          </div>
        </div>
      )}
    </section>
  );
}
