import React from "react";
import classNames from "classnames/bind";

const DEFAULT_FORM = {
  assigneeId: "",
  assigneeName: "",
};

export default class AssetAssignmentDrawer extends React.Component {
  state = {
    form: { ...DEFAULT_FORM },
    saving: false,
    error: null,
  };

  componentDidUpdate(prevProps) {
    if (this.props.open && !prevProps.open) {
      this.setState({ form: { ...DEFAULT_FORM }, saving: false, error: null });
    }
  }

  handleChange = (field) => (event) => {
    this.setState((prev) => ({
      form: { ...prev.form, [field]: event.target.value },
    }));
  };

  handleSubmit = async (event) => {
    event.preventDefault();
    const { asset, mode, onAssign, onReturn } = this.props;
    const { form } = this.state;
    this.setState({ saving: true, error: null });
    try {
      if (mode === "return") {
        await onReturn(asset);
      } else {
        if (!form.assigneeName.trim()) {
          this.setState({ saving: false, error: "Assignee name is required." });
          return;
        }
        await onAssign(asset, { id: form.assigneeId || `emp-${Date.now()}`, name: form.assigneeName });
      }
      this.props.onClose();
    } catch (e) {
      this.setState({ saving: false, error: "Unable to update asset assignment." });
    }
  };

  render() {
    const { open, onClose, asset, mode } = this.props;
    const { form, saving, error } = this.state;
    if (!open || !asset) {
      return null;
    }

    const isReturn = mode === "return";

    return (
      <div className="lux-asset-drawer-backdrop" role="presentation" onClick={onClose}>
        <aside
          className="lux-asset-drawer"
          role="dialog"
          aria-labelledby="asset-assign-title"
          onClick={(event) => event.stopPropagation()}
        >
          <header className="lux-asset-drawer__head">
            <div>
              <span className="lux-asset-drawer__eyebrow">Asset register</span>
              <h2 id="asset-assign-title">{isReturn ? "Return asset" : "Assign asset"}</h2>
              <p>{asset.name} · {asset.tag}</p>
            </div>
            <button type="button" className="lux-asset-drawer__close" onClick={onClose} aria-label="Close">
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </header>

          <form className="lux-asset-drawer__body" onSubmit={this.handleSubmit}>
            {error && (
              <div className="lux-employee-360__error" role="alert">
                {error}
              </div>
            )}

            {isReturn ? (
              <p className="lux-asset-drawer__hint">
                Mark <strong>{asset.name}</strong> as returned from {asset.assigneeName || "assignee"}. This clears offboarding blockers tied to this asset.
              </p>
            ) : (
              <>
                <label className="lux-asset-drawer__field">
                  <span>Assignee name</span>
                  <input type="text" value={form.assigneeName} onChange={this.handleChange("assigneeName")} required />
                </label>
                <label className="lux-asset-drawer__field">
                  <span>Employee ID (optional)</span>
                  <input type="text" value={form.assigneeId} onChange={this.handleChange("assigneeId")} />
                </label>
              </>
            )}

            <footer className="lux-asset-drawer__foot">
              <button type="button" className="lux-onb-action lux-onb-action--ghost" onClick={onClose} disabled={saving}>
                Cancel
              </button>
              <button type="submit" className={classNames("lux-leave-drawer__btn is-primary", { "is-loading": saving })} disabled={saving}>
                {saving ? "Saving…" : isReturn ? "Confirm return" : "Assign asset"}
              </button>
            </footer>
          </form>
        </aside>
      </div>
    );
  }
}
