import React, { Component } from "react";
import Select from "react-select";
import { connect } from "react-redux";
import { employeeActions } from "_actions";
import { validationUtils } from "_helpers";
import { commonUtils } from "_helpers";
import { store } from "_helpers";
import workItemUtils from "_helpers/workitem.utils";
import { getMonthRangeOptions } from "../fragments/projectEstimate.utils";

class ProjectEstimateAddLineModal extends Component {
    constructor() {
        super();
        this.state = {
            selectedMonth: null,
            selectedEstimateTypeOption: null,
            selectedEstimateNameOption: null,
            selectedEstimatedHours: {},
            selectedPrimaryPracticeEstimateNameOption: null,
        };
    }

    componentDidUpdate(prevProps) {
        if (this.props.show && !prevProps.show) {
            this.resetForm();
            if (this.props.teamId && !this.props.employeeAppConfig) {
                store.dispatch(employeeActions.getModuleConfig(this.props.teamId));
            }
        }
    }

    resetForm = () => {
        this.setState({
            selectedMonth: null,
            selectedEstimateTypeOption: this.props.estimateTypeOptions && this.props.estimateTypeOptions[0],
            selectedEstimateNameOption: null,
            selectedEstimatedHours: {},
            selectedPrimaryPracticeEstimateNameOption: null,
        });
    };

    onChangeEstimatedHours = (label, value) => {
        if (validationUtils.validateHourDecimal(value)) {
            this.setState((prev) => ({
                selectedEstimatedHours: { ...prev.selectedEstimatedHours, [label]: value },
            }));
        }
    };

    getRestrictedEmployees = () => {
        let employees = this.props.projectInfo.restrictedByEmployeeDetails || this.props.allEmployees;
        const restrictedUserTeams = this.props.projectInfo.restrictedByUserTeamIds
            || (this.props.userTeams && this.props.userTeams.map((userTeam) => userTeam.id));
        if (employees && restrictedUserTeams && restrictedUserTeams.length > 0) {
            employees = commonUtils.filterEmployeesByTeams(employees, restrictedUserTeams);
        }
        return employees;
    };

    getRestrictedBySkillsOptions = () => {
        const configObject = this.props.employeeAppConfig && this.props.employeeAppConfig.find((c) => c.name === "skills");
        let restrictedBySkills = this.props.projectInfo.restrictedByEmployeeSkills || (configObject && configObject.value);
        const employees = this.getRestrictedEmployees();
        if (employees && employees.length > 0 && restrictedBySkills) {
            restrictedBySkills = commonUtils.filterSkillsByEmployee(employees, restrictedBySkills);
        }
        return commonUtils.convertConfigListToSelectObject(restrictedBySkills);
    };

    getEmployeeDesignationsOptions = () => {
        const configObject = this.props.employeeAppConfig && this.props.employeeAppConfig.find((c) => c.name === "designation");
        return configObject && commonUtils.convertConfigListToSelectObject(configObject.value);
    };

    handleSubmit = (e) => {
        e.preventDefault();
        const estimationType = (this.state.selectedEstimateTypeOption && this.state.selectedEstimateTypeOption.value)
            || (this.props.estimateTypeOptions[0] && this.props.estimateTypeOptions[0].value);
        let estimationName = (this.state.selectedEstimateNameOption && this.state.selectedEstimateNameOption.value) || "Hours";

        if (estimationType === "PRACTICE") {
            const primary = this.state.selectedPrimaryPracticeEstimateNameOption && this.state.selectedPrimaryPracticeEstimateNameOption.value;
            estimationName = `${primary || ""}#${estimationName}`;
        }

        const hours = this.state.selectedEstimatedHours;
        const requiredKeys = ["estimate"];
        if (this.props.projectItem.automationEnabled) requiredKeys.push("estimateAutomation");
        if (this.props.projectItem.revisedEstEnabled) requiredKeys.push("estimateRevised");

        const allFilled = this.state.selectedMonth
            && requiredKeys.every((k) => hours[k] !== undefined && hours[k] !== "");

        if (allFilled) {
            this.props.onAdd(
                this.state.selectedMonth.value,
                estimationType,
                estimationName,
                hours
            );
            this.props.onClose();
        }
    };

    render() {
        if (!this.props.show) return null;

        const { projectInfo, projectItem, teamName, onClose } = this.props;
        const monthOptions = getMonthRangeOptions(projectInfo.estStartTime, projectInfo.estCompletionTime);
        const typeOption = this.state.selectedEstimateTypeOption || (this.props.estimateTypeOptions && this.props.estimateTypeOptions[0]);
        const typeValue = typeOption && typeOption.value;

        return (
            <div className="lux-estimate-line-modal" role="dialog" aria-modal="true">
                <div className="lux-estimate-line-modal__backdrop" onClick={onClose} />
                <div className="lux-estimate-line-modal__panel">
                    <header className="lux-estimate-line-modal__head">
                        <div>
                            <span className="lux-estimate-line-modal__kicker">Add estimate line</span>
                            <h3 className="lux-estimate-line-modal__title">{teamName}</h3>
                        </div>
                        <button type="button" className="pd-icon-btn link" onClick={onClose} aria-label="Close">
                            <i className="fe fe-x" />
                        </button>
                    </header>

                    <form className="lux-estimate-line-modal__form" onSubmit={this.handleSubmit}>
                        <div className="lux-estimate-form-grid">
                            <div className="lux-estimate-field">
                                <label className="lux-estimate-field__label">Month</label>
                                <Select
                                    isSearchable
                                    isClearable
                                    placeholder="Select month"
                                    classNamePrefix="custom-select"
                                    menuPlacement="auto"
                                    value={this.state.selectedMonth}
                                    onChange={(opt) => this.setState({ selectedMonth: opt })}
                                    options={monthOptions}
                                />
                            </div>

                            <div className="lux-estimate-field">
                                <label className="lux-estimate-field__label">Estimate type</label>
                                <Select
                                    isSearchable
                                    isClearable
                                    placeholder="Estimate type"
                                    classNamePrefix="custom-select"
                                    menuPlacement="auto"
                                    value={typeOption}
                                    onChange={(opt) => this.setState({
                                        selectedEstimateTypeOption: opt,
                                        selectedEstimateNameOption: null,
                                    })}
                                    options={this.props.estimateTypeOptions}
                                />
                            </div>

                            {this.props.employeeAppConfig && typeValue === "SKILL" &&
                                <div className="lux-estimate-field lux-estimate-field--wide">
                                    <label className="lux-estimate-field__label">Skill</label>
                                    <Select
                                        isSearchable
                                        isClearable
                                        placeholder="Select skill"
                                        classNamePrefix="custom-select"
                                        menuPlacement="auto"
                                        value={this.state.selectedEstimateNameOption}
                                        onChange={(opt) => this.setState({ selectedEstimateNameOption: opt })}
                                        options={this.getRestrictedBySkillsOptions()}
                                    />
                                </div>
                            }

                            {this.props.employeeAppConfig && typeValue === "PRACTICE" &&
                                <>
                                    <div className="lux-estimate-field lux-estimate-field--wide">
                                        <label className="lux-estimate-field__label">Primary practice</label>
                                        <Select
                                            isSearchable
                                            isClearable
                                            placeholder="Primary practice"
                                            classNamePrefix="custom-select"
                                            menuPlacement="auto"
                                            value={this.state.selectedPrimaryPracticeEstimateNameOption}
                                            onChange={(opt) => this.setState({
                                                selectedPrimaryPracticeEstimateNameOption: opt,
                                                selectedEstimateNameOption: null,
                                            })}
                                            options={workItemUtils.getEmployeePrimaryPractice(this.props.employeeAppConfig)}
                                        />
                                    </div>
                                    {this.state.selectedPrimaryPracticeEstimateNameOption &&
                                        <div className="lux-estimate-field lux-estimate-field--wide">
                                            <label className="lux-estimate-field__label">Secondary practice</label>
                                            <Select
                                                isSearchable
                                                isClearable
                                                placeholder="Secondary practice"
                                                classNamePrefix="custom-select"
                                                menuPlacement="auto"
                                                value={this.state.selectedEstimateNameOption}
                                                onChange={(opt) => this.setState({ selectedEstimateNameOption: opt })}
                                                options={workItemUtils.getEmployeeSecondaryPractice(
                                                    this.props.employeeAppConfig,
                                                    this.state.selectedPrimaryPracticeEstimateNameOption.value
                                                )}
                                            />
                                        </div>
                                    }
                                </>
                            }

                            {this.props.employeeAppConfig && typeValue === "DESIGNATION" &&
                                <div className="lux-estimate-field lux-estimate-field--wide">
                                    <label className="lux-estimate-field__label">Designation</label>
                                    <Select
                                        isSearchable
                                        isClearable
                                        placeholder="Select designation"
                                        classNamePrefix="custom-select"
                                        menuPlacement="auto"
                                        value={this.state.selectedEstimateNameOption}
                                        onChange={(opt) => this.setState({ selectedEstimateNameOption: opt })}
                                        options={this.getEmployeeDesignationsOptions()}
                                    />
                                </div>
                            }

                            <div className="lux-estimate-field">
                                <label className="lux-estimate-field__label">
                                    {projectItem.automationEnabled ? "Hours (with tool)" : "Estimated hours"}
                                </label>
                                <input
                                    type="text"
                                    className="form-control lux-estimate-input"
                                    value={(this.state.selectedEstimatedHours && this.state.selectedEstimatedHours.estimate) || ""}
                                    onChange={(e) => this.onChangeEstimatedHours("estimate", e.target.value)}
                                    placeholder="0.00"
                                />
                            </div>

                            {projectItem.automationEnabled &&
                                <div className="lux-estimate-field">
                                    <label className="lux-estimate-field__label">Hours (without tool)</label>
                                    <input
                                        type="text"
                                        className="form-control lux-estimate-input"
                                        value={(this.state.selectedEstimatedHours && this.state.selectedEstimatedHours.estimateAutomation) || ""}
                                        onChange={(e) => this.onChangeEstimatedHours("estimateAutomation", e.target.value)}
                                        placeholder="0.00"
                                    />
                                </div>
                            }

                            {projectItem.revisedEstEnabled &&
                                <div className="lux-estimate-field">
                                    <label className="lux-estimate-field__label">Revised hours</label>
                                    <input
                                        type="text"
                                        className="form-control lux-estimate-input"
                                        value={(this.state.selectedEstimatedHours && this.state.selectedEstimatedHours.estimateRevised) || ""}
                                        onChange={(e) => this.onChangeEstimatedHours("estimateRevised", e.target.value)}
                                        placeholder="0.00"
                                    />
                                </div>
                            }
                        </div>

                        <footer className="lux-estimate-line-modal__foot">
                            <button type="button" className="lux-estimate-btn lux-estimate-btn--ghost" onClick={onClose}>
                                Cancel
                            </button>
                            <button type="submit" className="lux-estimate-btn lux-estimate-btn--primary">
                                <i className="fe fe-plus" /> Add line
                            </button>
                        </footer>
                    </form>
                </div>
            </div>
        );
    }
}

const mapStateToProps = (state) => ({
    employeeAppConfig: state.employees.createConfig,
    estimateTypeOptions: state.projects.estimateTypeOptions,
});

export default connect(mapStateToProps)(ProjectEstimateAddLineModal);
