import React, { useEffect } from "react";
import { useReportPageDataSource } from "views/common/PageChromeContext";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import {
  ANALYTICS_DOMAIN_META,
  ANALYTICS_HUB_META,
  getAnalyticsShellPageTitle,
} from "config/analytics-platform-nav.config";
import { AdminInsightStrip } from "views/admin/components/AdminLuxShared";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import LuxKpiStrip from "views/common/fragments/LuxKpiStrip";

export default function AnalyticsLuxPage({
  domain,
  hub = false,
  pageMeta,
  dataSource,
  demoLabel = "Demo analytics data",
  heroActions,
  kpiCards,
  loading,
  testId,
  pageHeaderNameChangeHandler,
  children,
}) {
  useReportPageDataSource(dataSource);
  const meta = pageMeta || (hub ? ANALYTICS_HUB_META : (ANALYTICS_DOMAIN_META[domain] || ANALYTICS_HUB_META));
  const shellTitle = getAnalyticsShellPageTitle(meta);

  useEffect(() => {
    if (pageHeaderNameChangeHandler) {
      pageHeaderNameChangeHandler(shellTitle);
    }
  }, [pageHeaderNameChangeHandler, shellTitle]);

  return (
    <div
      className={classNames("lux-register-page", "lux-analytics-module", "lux-analytics-lux", meta.tone && `is-${meta.tone}`)}
      data-testid={testId || (hub ? "page-analytics-hub" : domain ? `page-analytics-${domain}` : undefined)}
    >
      <div className="lux-analytics-lux__ambient" aria-hidden="true">
        <span className="lux-analytics-lux__orb lux-analytics-lux__orb--a" />
        <span className="lux-analytics-lux__orb lux-analytics-lux__orb--b" />
      </div>
      <LuxModuleIntro meta={meta} actions={heroActions || undefined} />

      <div className="lux-register-page__body">
        {kpiCards && kpiCards.length ? (
          <LuxKpiStrip cards={kpiCards} loading={loading} className="lux-analytics-lux__kpi-strip" />
        ) : null}

        <div className="lux-analytics-lux__content">{children}</div>
      </div>
    </div>
  );
}

export function AnalyticsDomainGrid({ domains = [], loading }) {
  if (loading) {
    return <div className="lux-analytics-hub__skeleton" aria-busy="true" />;
  }

  if (!domains.length) {
    return (
      <div className="lux-analytics-hub__empty">
        <strong>No domain dashboards</strong>
        <p>Enable the analytics platform flag to load metric catalog and dashboard configs.</p>
      </div>
    );
  }

  return (
    <div className="lux-analytics-hub__grid">
      {domains.map((row) => {
        const meta = ANALYTICS_DOMAIN_META[row.domain] || {};
        return (
          <Link key={row.domain} to={meta.path || "#"} className={classNames("lux-analytics-hub__card", meta.tone && `is-${meta.tone}`)}>
            <span className="lux-analytics-hub__card-icon" aria-hidden="true">
              <i className={meta.icon || "fe fe-bar-chart-2"} />
            </span>
            <span className="lux-analytics-hub__card-eyebrow">{row.metricCount} metrics</span>
            <strong>
              {meta.titleLead} {meta.titleAccent}
            </strong>
            <span className="lux-analytics-hub__card-value">{row.headline}</span>
            <small>{row.headlineLabel}</small>
            <p>{row.insight}</p>
          </Link>
        );
      })}
    </div>
  );
}

export function AnalyticsInsightPanel({ insights }) {
  if (!insights || !insights.length) {
    return null;
  }
  return <AdminInsightStrip insights={insights} className="lux-analytics-lux__insights" />;
}

export function AnalyticsLuxPanel({ title, meta, icon, accent, children, actions }) {
  return (
    <section className={classNames("lux-hrms-dash__panel", "lux-analytics-lux__panel", accent && `is-${accent}`)}>
      <header className="lux-hrms-dash__panel-head lux-analytics-lux__panel-head">
        <div className="lux-analytics-lux__panel-head-main">
          {icon ? <i className={icon} aria-hidden="true" /> : null}
          <div>
            <h2 className="lux-hrms-dash__panel-title">{title}</h2>
            {meta ? <p className="lux-hrms-dash__panel-sub">{meta}</p> : null}
          </div>
        </div>
        {actions ? <div className="lux-hrms-dash__panel-actions">{actions}</div> : null}
      </header>
      <div className="lux-hrms-dash__panel-body lux-analytics-lux__panel-body">{children}</div>
    </section>
  );
}

export function AnalyticsActionButton({
  to,
  children,
  icon,
  variant = "primary",
  onClick,
  disabled,
  className,
  buttonType = "button",
}) {
  const classes = classNames("lux-onb-action", "lux-analytics-action", `lux-onb-action--${variant}`, className);
  const content = icon ? (
    <>
      <i className={icon} aria-hidden="true" />
      <span>{children}</span>
    </>
  ) : (
    children
  );
  if (to && !onClick) {
    return (
      <Link to={to} className={classes}>
        {content}
      </Link>
    );
  }
  return (
    <button type={buttonType} className={classes} onClick={onClick} disabled={disabled}>
      {content}
    </button>
  );
}
