import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isAnalyticsPlatformEnabled } from "config/analytics-platform.config";
import { REPORT_BUILDER_PAGE_META } from "config/analytics-platform-nav.config";
import { analyticsPlatformService } from "_services/analyticsPlatform.service";
import AnalyticsLuxPage, { AnalyticsActionButton, AnalyticsLuxPanel } from "views/analytics/components/AnalyticsLuxShared";
import ReportBuilderPanel from "views/analytics/components/ReportBuilderPanel";
import AnalyticsSavedFiltersPanel from "views/analytics/components/AnalyticsSavedFiltersPanel";
import { applySavedFilterToQuery } from "config/analytics-platform.utils";

class ReportBuilderPage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    savedReports: [],
    templates: [],
    availableMetrics: [],
    savedFilters: [],
    preview: null,
    activeFilter: null,
  };

  componentDidMount() {
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const [reportsResult, templatesResult, metricsResult, filtersResult] = await Promise.all([
        analyticsPlatformService.listSavedReports(),
        analyticsPlatformService.listReportTemplates(),
        analyticsPlatformService.getMetricCatalog(),
        analyticsPlatformService.listSavedFilters(),
      ]);
      this.setState({
        loading: false,
        savedReports: reportsResult.payload || [],
        templates: templatesResult.payload || [],
        availableMetrics: metricsResult.payload || [],
        savedFilters: filtersResult.payload || [],
        dataSource: reportsResult.source || metricsResult.source,
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load report builder.",
      });
    }
  };

  handleRunQuery = async (query) => {
    const result = await analyticsPlatformService.runReportQuery(query);
    this.setState({ preview: result.payload });
    return result;
  };

  handlePreviewReport = async (reportId) => {
    const result = await analyticsPlatformService.previewSavedReport(reportId);
    this.setState({ preview: result.payload });
  };

  handleSaveReport = async (payload) => {
    const result = await analyticsPlatformService.saveReport(payload);
    const reportsResult = await analyticsPlatformService.listSavedReports();
    this.setState({
      savedReports: reportsResult.payload || [],
      preview: null,
    });
    const previewResult = await analyticsPlatformService.previewSavedReport(result.payload.id);
    this.setState({ preview: previewResult.payload });
    return result;
  };

  handleExportReport = (query, reportName) => analyticsPlatformService.exportReport(query, reportName);

  handleApplyFilter = async (filter) => {
    const query = applySavedFilterToQuery(filter, {});
    const result = await analyticsPlatformService.runReportQuery(query);
    this.setState({
      activeFilter: filter,
      preview: result.payload,
    });
  };

  handleSaveFilter = async (payload) => {
    const result = await analyticsPlatformService.saveSavedFilter(payload);
    const filtersResult = await analyticsPlatformService.listSavedFilters();
    this.setState({ savedFilters: filtersResult.payload || [] });
    return result;
  };

  render() {
    if (!isAnalyticsPlatformEnabled()) {
      return <PersonaAccessDenied featureLabel="Report builder" />;
    }

    const {
      loading,
      loadError,
      dataSource,
      savedReports,
      templates,
      availableMetrics,
      savedFilters,
      preview,
      activeFilter,
    } = this.state;
    const meta = REPORT_BUILDER_PAGE_META;

    return (
      <AnalyticsLuxPage
        testId="page-analytics-report-builder"
        pageMeta={meta}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        dataSource={dataSource}
        kpiCards={[
          { id: "reports", label: "Saved reports", value: String(savedReports.length), hint: "Composer library", icon: "fe fe-save", tone: "indigo" },
          { id: "templates", label: "Templates", value: String(templates.length), hint: "Starter packs", icon: "fe fe-layers", tone: "violet" },
          { id: "metrics", label: "Metrics", value: String(availableMetrics.length), hint: "Catalog scope", icon: "fe fe-list", tone: "blue" },
          { id: "filters", label: "Saved filters", value: String(savedFilters.length), hint: "Reusable views", icon: "fe fe-filter", tone: "slate" },
        ]}
        demoLabel="Demo report builder"
        loading={loading}
        heroActions={
          <>
            <AnalyticsActionButton to="/analytics/hub" icon="fe fe-grid" variant="ghost">
              Analytics hub
            </AnalyticsActionButton>
            <AnalyticsActionButton to="/analytics/scheduled-reports" icon="fe fe-clock" variant="ghost">
              Scheduled reports
            </AnalyticsActionButton>
            <AnalyticsActionButton to="/analytics/executive" icon="fe fe-bar-chart-2" variant="primary">
              Executive analytics
            </AnalyticsActionButton>
          </>
        }
      >
        {loadError ? (
          <AnalyticsLuxPanel title="Report builder load issue" meta={loadError} accent="rose">
            <AnalyticsActionButton icon="fe fe-refresh-cw" variant="primary" onClick={this.loadData}>
              Retry
            </AnalyticsActionButton>
          </AnalyticsLuxPanel>
        ) : null}

        <AnalyticsLuxPanel
          title="Saved filters"
          meta={activeFilter ? `Active: ${activeFilter.name}` : "Reuse metric selections across reports"}
          icon="fe fe-filter"
          accent="slate"
        >
          <AnalyticsSavedFiltersPanel
            savedFilters={savedFilters}
            loading={loading}
            onApplyFilter={this.handleApplyFilter}
            onSaveFilter={this.handleSaveFilter}
          />
        </AnalyticsLuxPanel>

        <AnalyticsLuxPanel
          title={meta.panelTitle}
          meta={meta.panelMeta}
          icon="fe fe-edit-3"
          accent="indigo"
        >
          <ReportBuilderPanel
            savedReports={savedReports}
            templates={templates}
            availableMetrics={availableMetrics}
            preview={preview}
            loading={loading}
            onRunQuery={this.handleRunQuery}
            onPreviewReport={this.handlePreviewReport}
            onSaveReport={this.handleSaveReport}
            onExportReport={this.handleExportReport}
          />
        </AnalyticsLuxPanel>
      </AnalyticsLuxPage>
    );
  }
}

export default ReportBuilderPage;
