/** F30 — Marketplace, developer portal and extensibility. */

/**
 * W2-B03 / ADMIN-016 — fail-closed: only org/env capability enables UI.
 * Do not invent enablement via mock or development ENV_NAME (avoids fake working UI).
 */
export function isDeveloperPortalEnabled() {
  return shouldUseDeveloperPortal() === true;
}

export function shouldUseDeveloperPortalApi() {
  return envconfig.USE_DEVELOPER_PORTAL_API === true;
}

