import { axiosUtils, commonUtils } from '../_helpers';
import urlConfig from 'url.config';

export const shiftPolicyService = {
  list,
  create,
  update,
};

async function list(userTeamId) {
  return axiosUtils.get(`${urlConfig.SHIFT_POLICIES_API_PATH}?userTeamId=${userTeamId}`);
}

async function create(payload) {
  return axiosUtils.post(urlConfig.SHIFT_POLICIES_API_PATH, {
    ...payload,
    userTeamId: payload.userTeamId || commonUtils.getCurrentUserTeamId(),
    actorId: payload.actorId || commonUtils.getCurrentUserId(),
  });
}

async function update(policyId, payload) {
  return axiosUtils.put(`${urlConfig.SHIFT_POLICIES_API_PATH}/${policyId}`, {
    ...payload,
    userTeamId: payload.userTeamId || commonUtils.getCurrentUserTeamId(),
    actorId: payload.actorId || commonUtils.getCurrentUserId(),
  });
}
