import React, { Component } from "react";
import classNames from "classnames/bind";
import { REVENUE_RECOGNITION_ENTRIES_META } from "config/finance-intelligence-nav.config";
import { formatFinanceUsd } from "config/finance-intelligence.utils";
import { revenueRecognitionService } from "_services/revenueRecognition.service";
import { commonUtils } from "_helpers";
import FinanceLuxPage, {
  FinanceActionButton,
  FinanceInsightPanel,
  FinanceLuxPanel,
  FinanceQuickNav,
  FinanceRegisterPrimary,
  FinanceRegisterWrap,
  FinanceRevRecSectionTabs,
  FinanceStatusBadge,
  FinanceToolbar,
  REV_REC_QUICK_LINKS,
} from "views/finance/components/FinanceLuxShared";
import FinanceLoadAlert from "views/finance/components/FinanceLoadAlert";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";

class RevenueRecognitionEntriesPage extends Component {
  state = {
    loading: true,
    loadError: null,
    rows: [],
    query: "",
    statusFilter: "ALL",
    busyRef: null,
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Rev-rec entries");
    }
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    const result = await revenueRecognitionService.listEntries();
    if (result.source === "api" && Array.isArray(result.payload)) {
      this.setState({ loading: false, rows: result.payload, loadError: null });
    } else {
      this.setState({
        loading: false,
        rows: [],
        loadError: result.error || new Error("Unable to load entries"),
      });
    }
  };

  handleApprove = async (ref, userTeamId) => {
    this.setState({ busyRef: ref });
    await revenueRecognitionService.approveEntry(ref, userTeamId);
    this.setState({ busyRef: null });
    this.loadData();
  };

  handleReverse = async (ref, userTeamId) => {
    this.setState({ busyRef: ref });
    await revenueRecognitionService.reverseEntry(ref, "UI reverse", userTeamId);
    this.setState({ busyRef: null });
    this.loadData();
  };

  getFiltered = () => {
    const { rows, query, statusFilter } = this.state;
    const q = (query || "").trim().toLowerCase();
    return rows.filter((row) => {
      if (statusFilter !== "ALL" && String(row.status || "").toUpperCase() !== statusFilter) {
        return false;
      }
      if (!q) return true;
      const hay = [row.entryRef, row.periodKey, row.status, row.projectId, row.currency]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();
      return hay.includes(q);
    });
  };

  render() {
    const { loading, loadError, rows, query, statusFilter, busyRef } = this.state;
    const filtered = this.getFiltered();
    const draftCount = rows.filter((r) => String(r.status).toUpperCase() === "DRAFT").length;
    const approvedCount = rows.filter((r) => String(r.status).toUpperCase() === "APPROVED").length;
    const approvedTotal = rows
      .filter((r) => String(r.status).toUpperCase() === "APPROVED")
      .reduce((sum, r) => sum + (Number(r.amount) || 0), 0);
    const kpiCards = [
      {
        id: "entries",
        label: "Entries",
        value: rows.length,
        hint: "All statuses",
        tone: "amber",
        icon: "fe fe-check-square",
      },
      {
        id: "draft",
        label: "Draft",
        value: draftCount,
        hint: "Awaiting approval",
        tone: "slate",
        icon: "fe fe-edit",
      },
      {
        id: "approved",
        label: "Approved",
        value: approvedCount,
        hint: "Posted to period",
        tone: "green",
        icon: "fe fe-check-circle",
      },
      {
        id: "amount",
        label: "Approved $",
        value: formatFinanceUsd(approvedTotal),
        hint: "Recognized total",
        tone: "indigo",
        icon: "fe fe-dollar-sign",
      },
    ];

    return (
      <FinanceLuxPage
        testId="rev-rec-entries-page"
        pageMeta={REVENUE_RECOGNITION_ENTRIES_META}
        dataSource={rows.length ? "api" : loadError ? "api-error" : loading ? null : "api"}
        demoLabel={null}
        loading={loading}
        kpiCards={kpiCards}
        heroActions={
          <>
            <FinanceActionButton icon="fe fe-refresh-cw" variant="ghost" onClick={this.loadData} disabled={loading}>
              Refresh
            </FinanceActionButton>
            <FinanceActionButton
              to="/finance/revenue-recognition/period-close"
              icon="fe fe-lock"
              variant="primary"
            >
              Period close
            </FinanceActionButton>
          </>
        }
      >
        <FinanceRevRecSectionTabs active="/finance/revenue-recognition/entries" />
        <FinanceQuickNav
          links={REV_REC_QUICK_LINKS}
          eyebrow="Recognition workflow"
          title="Approve drafts, then lock the period"
        />
        <FinanceInsightPanel
          insights={[
            {
              id: "approve",
              tone: "green",
              icon: "fe fe-check",
              title: "Approve to post",
              copy: "Draft entries become recognized amounts in the target period when approved.",
            },
            {
              id: "reverse",
              tone: "amber",
              icon: "fe fe-rotate-ccw",
              title: "Reverse when needed",
              copy: "Approved entries can be reversed before the period is locked.",
            },
            {
              id: "lock",
              tone: "rose",
              icon: "fe fe-lock",
              title: "Close the books",
              copy: "After review, lock the accounting period so recognition stays final.",
              path: "/finance/revenue-recognition/period-close",
            },
          ]}
        />
        <FinanceLoadAlert
          error={loadError}
          fallback="Unable to load entries."
          onDismiss={() => this.setState({ loadError: null })}
        />

        <FinanceLuxPanel
          title="Entry register"
          meta={`${filtered.length} of ${rows.length} entr${rows.length === 1 ? "y" : "ies"}`}
          icon="fe fe-list"
          accent="amber"
        >
          <FinanceToolbar
            query={query}
            onQueryChange={(value) => this.setState({ query: value })}
            placeholder="Search ref, period, project…"
            countLabel={
              <>
                <strong>{filtered.length}</strong> shown
              </>
            }
          >
            <div className="lux-hrms-dash__filter-group">
              {["ALL", "DRAFT", "APPROVED", "REVERSED"].map((value) => (
                <button
                  key={value}
                  type="button"
                  className={classNames("lux-hrms-dash__filter-chip", {
                    "is-active": statusFilter === value,
                  })}
                  onClick={() => this.setState({ statusFilter: value })}
                >
                  {value === "ALL" ? "All statuses" : value.charAt(0) + value.slice(1).toLowerCase()}
                </button>
              ))}
            </div>
          </FinanceToolbar>

          {loading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="Loading entries"
              description="Fetching recognition entries."
            />
          ) : filtered.length === 0 ? (
            <LuxRegisterEmptyState
              title={rows.length === 0 ? "No entries yet" : "No matching entries"}
              description={
                rows.length === 0
                  ? `Generate a schedule to create draft entries for team ${commonUtils.getCurrentUserTeamId()}.`
                  : "Try a different search or status filter."
              }
              showCreate={false}
            />
          ) : (
            <FinanceRegisterWrap>
              <table className="lux-finance-register" data-testid="rev-rec-entries-table">
                <thead>
                  <tr>
                    <th>Entry</th>
                    <th>Period</th>
                    <th>Amount</th>
                    <th>Status</th>
                    <th>Project</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {filtered.map((row) => {
                    const busy = busyRef === row.entryRef;
                    return (
                      <tr key={row.entryRef || row.id}>
                        <td>
                          <FinanceRegisterPrimary
                            title={row.entryRef || `Entry ${row.id}`}
                            meta={row.currency || "USD"}
                            icon="fe fe-check-square"
                            tone="amber"
                          />
                        </td>
                        <td>
                          <span className="lux-finance-chip">{row.periodKey || "—"}</span>
                        </td>
                        <td>
                          <strong>
                            {row.currency || "USD"} {row.amount}
                          </strong>
                        </td>
                        <td>
                          <FinanceStatusBadge status={row.status} />
                        </td>
                        <td>{row.projectId || "—"}</td>
                        <td>
                          <div className="lux-finance-row-actions">
                            {row.status === "DRAFT" && (
                              <FinanceActionButton
                                type="button"
                                variant="primary"
                                icon="fe fe-check"
                                disabled={busy}
                                onClick={() => this.handleApprove(row.entryRef, row.userTeamId)}
                              >
                                {busy ? "…" : "Approve"}
                              </FinanceActionButton>
                            )}
                            {row.status === "APPROVED" && (
                              <FinanceActionButton
                                type="button"
                                variant="ghost"
                                icon="fe fe-rotate-ccw"
                                disabled={busy}
                                onClick={() => this.handleReverse(row.entryRef, row.userTeamId)}
                              >
                                {busy ? "…" : "Reverse"}
                              </FinanceActionButton>
                            )}
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </FinanceRegisterWrap>
          )}
        </FinanceLuxPanel>
      </FinanceLuxPage>
    );
  }
}

export default RevenueRecognitionEntriesPage;
