import { useContext } from "react";
import { PersonaContext } from "context/PersonaContextProvider";

/**
 * P00-T5 hook for persona-aware components.
 * @returns {import('react').ContextType<typeof PersonaContext>}
 */
export function usePersonaContext() {
  const value = useContext(PersonaContext);
  if (!value) {
    throw new Error("usePersonaContext must be used within PersonaContextProvider");
  }
  return value;
}

export default usePersonaContext;
