import React, { Component } from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { ADMIN_PAGE_META } from "config/admin-page-meta.config";
import { isOrgStructureAdminEnabled, ORG_UNIT_TYPES } from "config/org-structure.config";
import {
  buildOrgStructureAdminInsights,
  buildOrgStructureAdminMetrics,
  filterOrgUnits,
} from "config/org-structure.utils";
import { orgStructureService } from "_services/orgStructure.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import OrgUnitRegister from "views/admin/components/OrgUnitRegister";
import {
  AdminActionButton,
  AdminInsightStrip,
  AdminPanelHead,
  AdminPanelLink,
  AdminLuxPage,
} from "views/admin/components/AdminLuxShared";

class OrgStructureAdminPage extends Component {
  state = {
    orgUnits: [],
    employees: [],
    loading: true,
    loadError: null,
    dataSource: null,
    typeFilter: "ALL",
    query: "",
    selectedId: null,
    reassignManagerId: "",
    reassignSaving: false,
    reassignError: null,
    reassignSuccess: null,
    masterLists: { department: [], designation: [], teamName: [], costCenter: [] },
    masterListKey: "department",
    masterValue: "",
    masterSaving: false,
    masterError: null,
    masterSuccess: null,
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Org structure");
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const [unitsResult, chartResult, masterResult] = await Promise.all([
        orgStructureService.listOrgUnits(),
        orgStructureService.getOrgChart(),
        orgStructureService.listMasterValues(),
      ]);
      this.setState({
        orgUnits: unitsResult.payload || [],
        employees: (chartResult.payload && chartResult.payload.employees) || [],
        masterLists: (masterResult && masterResult.payload) || {
          department: [],
          designation: [],
          teamName: [],
          costCenter: [],
        },
        loading: false,
        dataSource: unitsResult.source || chartResult.source || null,
      });
    } catch (e) {
      this.setState({
        loading: false,
        loadError: "Unable to load org structure.",
        orgUnits: [],
        employees: [],
      });
    }
  };

  getFilteredUnits = () => {
    const { orgUnits, typeFilter, query } = this.state;
    return filterOrgUnits(orgUnits, { type: typeFilter, query });
  };

  getSelectedUnit = () => {
    const { orgUnits, selectedId } = this.state;
    return orgUnits.find((row) => row.id === selectedId) || null;
  };

  resolveUnitEmployeeId = (unit) => {
    if (!unit) {
      return null;
    }
    if (unit.sourceEntityId) {
      return String(unit.sourceEntityId);
    }
    if (unit.headEmployeeId) {
      return String(unit.headEmployeeId);
    }
    const id = unit.id != null ? String(unit.id) : "";
    if (id.startsWith("emp-root-")) {
      return id.slice("emp-root-".length);
    }
    return null;
  };

  handleReassignManager = async () => {
    const selectedUnit = this.getSelectedUnit();
    const employeeId = this.resolveUnitEmployeeId(selectedUnit);
    const { reassignManagerId, employees } = this.state;
    if (!employeeId || !reassignManagerId) {
      this.setState({ reassignError: "Select a manager to reassign reporting to." });
      return;
    }
    if (String(employeeId) === String(reassignManagerId)) {
      this.setState({ reassignError: "Employee cannot report to themselves." });
      return;
    }
    const manager = (employees || []).find((row) => String(row.id) === String(reassignManagerId));
    this.setState({ reassignSaving: true, reassignError: null, reassignSuccess: null });
    try {
      await orgStructureService.reassignManager(
        employeeId,
        reassignManagerId,
        manager ? manager.name : null
      );
      const managerLabel = manager && manager.name ? manager.name : "selected manager";
      this.setState({
        reassignSaving: false,
        reassignSuccess: `Manager reassignment saved. Reporting line now points to ${managerLabel}.`,
        reassignManagerId: "",
      });
      await this.loadData();
    } catch (e) {
      this.setState({
        reassignSaving: false,
        reassignError: "Unable to persist manager reassignment.",
      });
    }
  };

  handleCreateMasterValue = async () => {
    const { masterListKey, masterValue } = this.state;
    const trimmed = (masterValue || "").trim();
    if (!trimmed) {
      this.setState({ masterError: "Enter a non-blank value." });
      return;
    }
    this.setState({ masterSaving: true, masterError: null, masterSuccess: null });
    try {
      const result = await orgStructureService.createMasterValue(masterListKey, trimmed);
      if (!result || !result.payload) {
        this.setState({
          masterSaving: false,
          masterError: "Unable to save. Value may be blank or already exist.",
        });
        return;
      }
      this.setState({
        masterSaving: false,
        masterValue: "",
        masterSuccess: `Saved ${masterListKey}: ${trimmed} (Application Config).`,
        masterLists: {
          ...this.state.masterLists,
          [masterListKey]: result.payload.values || [
            ...(this.state.masterLists[masterListKey] || []),
            trimmed,
          ],
        },
      });
    } catch (e) {
      this.setState({
        masterSaving: false,
        masterError: (e && e.message) || "Unable to save list value.",
      });
    }
  };

  render() {
    if (!isOrgStructureAdminEnabled()) {
      return (
        <PersonaAccessDenied
          moduleName="Org structure"
          reason="Org structure administration is not enabled for your organization."
        />
      );
    }

    const { loading, loadError, dataSource, typeFilter, query } = this.state;
    const rows = this.getFilteredUnits();
    const metrics = buildOrgStructureAdminMetrics(this.state.orgUnits);
    const insights = loading ? [] : buildOrgStructureAdminInsights(this.state.orgUnits);
    const selectedUnit = this.getSelectedUnit();
    const kpiCards = [
      { id: "units", label: "Org units", value: metrics.totalUnits, hint: "Hierarchy nodes", tone: "primary", icon: "fe fe-layers" },
      { id: "departments", label: "Departments", value: metrics.departments, hint: `${metrics.divisions} division(s)`, tone: "blue", icon: "fe fe-grid" },
      { id: "headcount", label: "Headcount", value: metrics.headcount, hint: "Rolled up", tone: "green", icon: "fe fe-users" },
      { id: "vacant", label: "Vacant heads", value: metrics.vacantHeads, hint: "Needs assignment", tone: metrics.vacantHeads ? "amber" : "slate", icon: "fe fe-user-x" },
    ];

    return (
      <AdminLuxPage
        pageMeta={ADMIN_PAGE_META.orgStructure}
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        className="lux-register-page lux-org-structure-page"
        heroActions={
          <AdminActionButton icon="fe fe-refresh-cw" onClick={this.loadData} disabled={loading}>
            Refresh
          </AdminActionButton>
        }
      >
        {loadError && (
          <div className="lux-employee-360__error lux-org-structure__error" role="alert">
            <span>{loadError}</span>
            <AdminActionButton variant="ghost" onClick={this.loadData}>
              Retry
            </AdminActionButton>
          </div>
        )}

        <AdminInsightStrip insights={insights} />

        <section className="lux-hrms-dash__panel lux-org-structure-panel" data-testid="org-master-lists-panel">
          <AdminPanelHead
            title="Department & designation lists"
            subtitle="Stored in Application Config (HRMS) — used when mapping employees. No duplicate org master tables."
          />
          <div className="lux-hrms-dash__panel-body">
            <div className="lux-org-structure-detail__reassign" style={{ maxWidth: 480 }}>
              <label htmlFor="org-master-list-key">List</label>
              <select
                id="org-master-list-key"
                className="lux-appr-toolbar__search-input"
                value={this.state.masterListKey}
                onChange={(e) =>
                  this.setState({
                    masterListKey: e.target.value,
                    masterError: null,
                    masterSuccess: null,
                  })
                }
              >
                <option value="department">Department</option>
                <option value="designation">Designation</option>
                <option value="teamName">Team name</option>
                <option value="costCenter">Cost center</option>
              </select>
              <label htmlFor="org-master-value">New value</label>
              <input
                id="org-master-value"
                type="text"
                className="lux-appr-toolbar__search-input"
                placeholder="e.g. Platform Engineering"
                value={this.state.masterValue}
                onChange={(e) =>
                  this.setState({
                    masterValue: e.target.value,
                    masterError: null,
                    masterSuccess: null,
                  })
                }
              />
              <AdminActionButton
                variant="primary"
                onClick={this.handleCreateMasterValue}
                disabled={this.state.masterSaving || !(this.state.masterValue || "").trim()}
              >
                {this.state.masterSaving ? "Saving…" : "Add to Application Config"}
              </AdminActionButton>
              {this.state.masterError && (
                <p className="lux-org-structure-detail__error" role="alert">
                  {this.state.masterError}
                </p>
              )}
              {this.state.masterSuccess && (
                <p className="lux-org-structure-detail__success" role="status">
                  {this.state.masterSuccess}
                </p>
              )}
              <p className="lux-org-structure-detail__hint" style={{ marginTop: 12 }}>
                Current {(this.state.masterListKey || "department")} values:{" "}
                {(this.state.masterLists[this.state.masterListKey] || []).length
                  ? (this.state.masterLists[this.state.masterListKey] || []).join(", ")
                  : "— none yet —"}
              </p>
            </div>
          </div>
        </section>

        <section className="lux-hrms-dash__panel lux-org-structure-panel">
          <AdminPanelHead
            title="Org unit register"
            subtitle="Business units, departments, and teams with rolled-up headcount"
            actions={<AdminPanelLink to="/people/org-chart">View org chart</AdminPanelLink>}
          />

          <div className="lux-org-structure-panel__toolbar">
            <div className="lux-appr-toolbar__row">
              <div className="lux-appr-toolbar__search">
                <i className="fe fe-search" aria-hidden="true" />
                <input
                  type="search"
                  className="lux-appr-toolbar__search-input"
                  placeholder="Search units, heads, or cost centers"
                  value={query}
                  onChange={(e) => this.setState({ query: e.target.value })}
                />
              </div>
              <span className="lux-appr-toolbar__count">
                <strong>{rows.length}</strong> unit{rows.length === 1 ? "" : "s"}
              </span>
            </div>
            <div className="lux-appr-toolbar__group">
              <span className="lux-appr-toolbar__label">Type</span>
              <div className="lux-hrms-dash__filter-group">
                {["ALL", ORG_UNIT_TYPES.COMPANY, ORG_UNIT_TYPES.DIVISION, ORG_UNIT_TYPES.DEPARTMENT, ORG_UNIT_TYPES.TEAM].map(
                  (value) => (
                    <button
                      key={value}
                      type="button"
                      className={classNames("lux-hrms-dash__filter-chip", {
                        "is-active": typeFilter === value,
                      })}
                      onClick={() => this.setState({ typeFilter: value })}
                    >
                      {value === "ALL" ? "All" : value.charAt(0) + value.slice(1).toLowerCase()}
                    </button>
                  )
                )}
              </div>
            </div>
          </div>

          <div className="lux-hrms-dash__panel-body lux-org-structure-panel__body">
            {loading ? (
              <LuxRegisterEmptyState
                className="lux-register-empty--compact"
                title="Loading org structure"
                description="Fetching org units and leadership assignments."
              />
            ) : rows.length === 0 ? (
              <LuxRegisterEmptyState
                className="lux-register-empty--compact"
                icon="fe fe-layers"
                title="No org units match"
                description="Try broadening type or search filters."
              />
            ) : (
              <div className="lux-org-structure-panel__grid">
                <OrgUnitRegister
                  orgUnits={rows}
                  selectedId={this.state.selectedId}
                  onSelect={(row) => this.setState({ selectedId: row.id })}
                />
                {selectedUnit && (
                  <aside className="lux-org-structure-detail" aria-label="Selected org unit">
                    <header className="lux-org-structure-detail__head">
                      <h3>{selectedUnit.name}</h3>
                      <span className={classNames("lux-doc-badge", selectedUnit.status === "Active" ? "is-primary" : "is-slate")}>
                        {selectedUnit.status}
                      </span>
                    </header>
                    <dl className="lux-org-structure-detail__grid">
                      <div>
                        <dt>Type</dt>
                        <dd>{selectedUnit.type}</dd>
                      </div>
                      <div>
                        <dt>Head</dt>
                        <dd>{selectedUnit.headEmployeeName || "Vacant"}</dd>
                      </div>
                      <div>
                        <dt>Headcount</dt>
                        <dd>{selectedUnit.headcount != null ? selectedUnit.headcount : "—"}</dd>
                      </div>
                      <div>
                        <dt>Cost center</dt>
                        <dd>{selectedUnit.costCenter || "—"}</dd>
                      </div>
                      <div>
                        <dt>Location</dt>
                        <dd>{selectedUnit.location || "—"}</dd>
                      </div>
                      <div>
                        <dt>Last updated</dt>
                        <dd>{selectedUnit.updatedAt || "—"}</dd>
                      </div>
                    </dl>
                    <div className="lux-org-structure-detail__reassign">
                      <label htmlFor="org-reassign-manager">Reassign manager</label>
                      <p className="lux-org-structure-detail__hint">
                        Persists reporting line on EmployeeModel (fs_employee_model.manager_id).
                      </p>
                      <select
                        id="org-reassign-manager"
                        className="lux-appr-toolbar__search-input"
                        value={this.state.reassignManagerId}
                        onChange={(e) =>
                          this.setState({
                            reassignManagerId: e.target.value,
                            reassignError: null,
                            reassignSuccess: null,
                          })
                        }
                      >
                        <option value="">Select manager…</option>
                        {(this.state.employees || [])
                          .filter((row) => String(row.id) !== String(this.resolveUnitEmployeeId(selectedUnit)))
                          .map((row) => (
                            <option key={row.id} value={row.id}>
                              {row.name}
                              {row.designation ? ` — ${row.designation}` : ""}
                            </option>
                          ))}
                      </select>
                      <AdminActionButton
                        variant="primary"
                        onClick={this.handleReassignManager}
                        disabled={this.state.reassignSaving || !this.state.reassignManagerId}
                      >
                        {this.state.reassignSaving ? "Saving…" : "Save manager"}
                      </AdminActionButton>
                      {this.state.reassignError && (
                        <p className="lux-org-structure-detail__error" role="alert">
                          {this.state.reassignError}
                        </p>
                      )}
                      {this.state.reassignSuccess && (
                        <p className="lux-org-structure-detail__success" role="status">
                          {this.state.reassignSuccess}
                        </p>
                      )}
                    </div>
                  </aside>
                )}
              </div>
            )}
          </div>
        </section>
      </AdminLuxPage>
    );
  }
}

export default OrgStructureAdminPage;
