import React from "react";
import { NavLink } from "react-router-dom";
import classNames from "classnames/bind";
import dateUtils from "_helpers/date.utils";
import { getDeliverableStatusMeta } from "./deliverableList.utils";

function formatScheduleRange(start, end) {
  const startM = start && dateUtils.convertDateStringToMoment(start);
  const endM = end && dateUtils.convertDateStringToMoment(end);
  if (!startM && !endM) return "—";
  const fmt = (m) => (m ? m.format("D MMM YYYY") : "—");
  if (startM && endM) return `${fmt(startM)} → ${fmt(endM)}`;
  return fmt(startM || endM);
}

function Fact({ icon, label, value }) {
  return (
    <div className="lux-workitem-create-context__fact">
      <span className="lux-workitem-create-context__fact-icon" aria-hidden="true">
        <i className={icon} />
      </span>
      <div className="lux-workitem-create-context__fact-copy">
        <span className="lux-workitem-create-context__fact-label">{label}</span>
        <strong className="lux-workitem-create-context__fact-value" title={String(value || "—")}>
          {value || "—"}
        </strong>
      </div>
    </div>
  );
}

export default function WorkItemCreateContextInsight({ taskInfo }) {
  if (!taskInfo) return null;

  const statusMeta = getDeliverableStatusMeta(taskInfo.status);
  const project = taskInfo.projectInfo;
  const projectRef = project && (project.itemIdUserTeamPrefix || project.id);
  const projectPath = projectRef ? `/project/details/${projectRef}` : null;
  const deliverableRef = taskInfo.itemIdUserTeamPrefix || taskInfo.id;
  const deliverablePath = `/project/deliverable/${deliverableRef}`;
  const scheduleLabel = formatScheduleRange(
    taskInfo.estStartTime,
    taskInfo.estCompletionTime
  );
  const owner =
    (taskInfo.ownerDetails && taskInfo.ownerDetails.name) ||
    (taskInfo.ownerUserTeamDetails && taskInfo.ownerUserTeamDetails.name) ||
    null;

  return (
    <section className="lux-workitem-create-context" aria-label="Deliverable context">
      <div className="lux-workitem-create-context__hero">
        <div className="lux-workitem-create-context__identity">
          <span className="lux-workitem-create-context__badge">Parent deliverable</span>
          <NavLink to={deliverablePath} className="lux-workitem-create-context__name">
            {taskInfo.name || deliverableRef}
            <i className="fe fe-arrow-up-right" aria-hidden="true" />
          </NavLink>
          <p className="lux-workitem-create-context__meta-line">
            {projectPath ? (
              <NavLink to={projectPath} className="lux-workitem-create-context__project-link">
                <i className="fe fe-briefcase" aria-hidden="true" />
                {(project && project.name) || projectRef}
              </NavLink>
            ) : (
              <span>
                <i className="fe fe-briefcase" aria-hidden="true" />
                {(project && project.name) || "—"}
              </span>
            )}
            {deliverableRef && (
              <>
                <span className="lux-workitem-create-context__dot">·</span>
                <span className="lux-workitem-create-context__ref">{deliverableRef}</span>
              </>
            )}
            <span className="lux-workitem-create-context__dot">·</span>
            <span
              className={classNames(
                "lux-workitem-create-context__status",
                `is-${statusMeta.tone}`
              )}
            >
              {statusMeta.label}
            </span>
          </p>
        </div>
        <span className="lux-workitem-create-context__orb" aria-hidden="true">
          <i className="fe fe-check-square" />
        </span>
      </div>

      <div className="lux-workitem-create-context__facts" aria-label="Deliverable at a glance">
        <Fact icon="fe fe-calendar" label="Schedule" value={scheduleLabel} />
        <Fact icon="fe fe-user" label="Delivery lead" value={owner} />
        <Fact
          icon="fe fe-tag"
          label="Category"
          value={taskInfo.category || (project && project.category)}
        />
        <Fact
          icon="fe fe-flag"
          label="Priority"
          value={taskInfo.priority || null}
        />
      </div>
    </section>
  );
}
