import React from "react";
import classNames from "classnames/bind";

export default function AiHitlSnapshotStrip({ overview, llmAccess, loading }) {
  if (loading) {
    return <div className="lux-ai-intel-snapshot lux-ai-intel-snapshot--loading" aria-busy="true" />;
  }

  const o = overview || {};
  const access = llmAccess || {};
  const acceptance = o.acceptanceRate != null ? o.acceptanceRate : 0;

  return (
    <section className="lux-ai-intel-snapshot" aria-label="AI work intelligence snapshot">
      <div className="lux-ai-intel-snapshot__badge">
        <i className="fe fe-shield" aria-hidden="true" />
        <span>Human-in-the-loop required</span>
        {access.modeLabel ? (
          <span className={classNames("lux-ai-intel-snapshot__mode", access.canUseLiveLlm ? "is-live" : "is-pilot")}>
            {access.modeLabel}
          </span>
        ) : null}
      </div>
      <div className="lux-ai-intel-snapshot__metrics">
        <article className="lux-ai-intel-snapshot__metric is-violet">
          <span>Active agents</span>
          <strong>{o.activeAgentCount != null ? o.activeAgentCount : 0}</strong>
          <small>of {o.agentCount != null ? o.agentCount : 0} registered</small>
        </article>
        <article className="lux-ai-intel-snapshot__metric is-indigo">
          <span>Pending drafts</span>
          <strong>{o.pendingRecommendationCount != null ? o.pendingRecommendationCount : 0}</strong>
          <small>Awaiting decision</small>
        </article>
        <article className="lux-ai-intel-snapshot__metric is-emerald">
          <span>Acceptance rate</span>
          <strong>{acceptance}%</strong>
          <small>Accepted recommendations</small>
        </article>
        <article className="lux-ai-intel-snapshot__metric is-amber">
          <span>Last run</span>
          <strong className="is-compact">
            {o.lastRunAt ? new Date(o.lastRunAt).toLocaleString(undefined, { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }) : "—"}
          </strong>
          <small>Most recent execution</small>
        </article>
      </div>
    </section>
  );
}

export function AiAgentDomainHero({ agent, loading }) {
  if (loading) {
    return <div className="lux-ai-intel-domain-hero lux-ai-intel-domain-hero--loading" aria-busy="true" />;
  }
  if (!agent) {
    return null;
  }

  const acceptance = Math.round((agent.acceptanceRate || 0) * (agent.acceptanceRate <= 1 ? 100 : 1));

  return (
    <section className={classNames("lux-ai-intel-domain-hero", agent.tone && `is-${agent.tone}`)}>
      <div className="lux-ai-intel-domain-hero__main">
        <span className="lux-ai-intel-domain-hero__icon" aria-hidden="true">
          <i className={agent.icon || "fe fe-cpu"} />
        </span>
        <div>
          <h2 className="lux-ai-intel-domain-hero__title">{agent.name}</h2>
          <p>{agent.description}</p>
        </div>
      </div>
      <div className="lux-ai-intel-domain-hero__stats">
        <span>
          Runs <strong>{agent.runCount || 0}</strong>
        </span>
        <span>
          Acceptance <strong>{acceptance}%</strong>
        </span>
        <span>
          Confidence <strong>{Math.round((agent.confidence || 0) * 100)}%</strong>
        </span>
        <span className="lux-ai-intel-domain-hero__last">{agent.lastRun || "No recent run"}</span>
      </div>
      <div className="lux-ai-intel-domain-hero__chips">
        {(agent.evidenceTemplates || []).map((label) => (
          <span key={label} className="lux-ai-intel-chip is-violet">
            {label}
          </span>
        ))}
      </div>
    </section>
  );
}
