import React, { useState } from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import ProjectDetailsTabShell from "views/project/components/ProjectDetailsTabShell";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxSegmentNav from "views/common/fragments/LuxSegmentNav";
import {
  buildDocumentsTabStats,
  resolveEmployeeAssets,
  resolveEmployeeDocuments,
} from "config/employee360Tab.utils";
import { getEmployeeDisplayName } from "config/employee360.utils";
import { isDocumentVaultEnabled } from "config/document-vault.config";
import { isAssetRegisterEnabled } from "config/asset-register.config";

const PANELS = {
  DOCUMENTS: "documents",
  ASSETS: "assets",
};

function DocumentStatusBadge({ status }) {
  const normalized = String(status || "").toLowerCase();
  return (
    <span
      className={classNames("lux-employee-360__badge", {
        "is-success": normalized.includes("verified") || normalized.includes("active"),
        "is-warning": normalized.includes("pending") || normalized.includes("review"),
      })}
    >
      {status || "—"}
    </span>
  );
}

export default function Employee360DocumentsTab({ employee, summary }) {
  const [activePanel, setActivePanel] = useState(PANELS.DOCUMENTS);

  if (!employee) {
    return null;
  }

  const documents = resolveEmployeeDocuments(summary);
  const assets = resolveEmployeeAssets(summary);
  const stats = buildDocumentsTabStats(documents, assets);
  const displayName = getEmployeeDisplayName(employee);
  const vaultLive = isDocumentVaultEnabled();
  const assetsLive = isAssetRegisterEnabled();
  const documentsEmptyCopy = vaultLive
    ? "No documents are on file for this employee yet. Upload agreements and compliance forms in the document vault."
    : "Employment agreements and compliance forms will appear here once HR uploads them to the vault.";
  const assetsEmptyCopy = assetsLive
    ? "No equipment or access credentials are assigned to this employee yet."
    : "Laptops, phones, and access credentials will appear here once assets are assigned in the register.";

  return (
    <ProjectDetailsTabShell
      icon="fe fe-file-text"
      eyebrow="Records"
      title="Documents & assets"
      subtitle={`HR document vault and assigned equipment for ${displayName}.`}
      stats={stats}
      className="lux-employee-360__embed lux-employee-360__embed--documents"
    >
      <div className="lux-employee-360__embed-links">
        <Link to="/people/documents" className="lux-employee-360__embed-link">Open document vault</Link>
        <Link to="/people/assets" className="lux-employee-360__embed-link">Open asset register</Link>
      </div>
      <LuxSegmentNav
        items={[
          { id: PANELS.DOCUMENTS, label: "Documents", icon: "fe fe-file-text", badge: documents.length, showZeroBadge: true },
          { id: PANELS.ASSETS, label: "Assets", icon: "fe fe-monitor", badge: assets.length, showZeroBadge: true },
        ]}
        activeId={activePanel}
        onChange={setActivePanel}
        ariaLabel="Documents and assets views"
        tabList
        testId="employee-360-docs-nav"
      />

      {activePanel === PANELS.DOCUMENTS && (
        <div
          className="lux-pd-tab__panel"
          role="tabpanel"
          id="employee-360-docs-panel-documents"
          aria-labelledby="employee-360-docs-tab-documents"
        >
          {documents.length === 0 ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact lux-employee-360__embed-empty"
              icon="fe fe-file-text"
              title="No documents on file"
              description={documentsEmptyCopy}
            />
          ) : (
            <div className="lux-employee-360__register-wrap">
              <table className="lux-employee-360__register">
                <thead>
                  <tr>
                    <th>Document</th>
                    <th>Type</th>
                    <th>Status</th>
                    <th>Uploaded</th>
                  </tr>
                </thead>
                <tbody>
                  {documents.map((row) => (
                    <tr key={row.id || row.title}>
                      <td><strong>{row.title || "—"}</strong></td>
                      <td>{row.type || "—"}</td>
                      <td><DocumentStatusBadge status={row.status} /></td>
                      <td>{row.uploadedAt || "—"}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {activePanel === PANELS.ASSETS && (
        <div
          className="lux-pd-tab__panel"
          role="tabpanel"
          id="employee-360-docs-panel-assets"
          aria-labelledby="employee-360-docs-tab-assets"
        >
          {assets.length === 0 ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact lux-employee-360__embed-empty"
              icon="fe fe-monitor"
              title="No assigned assets"
              description={assetsEmptyCopy}
            />
          ) : (
            <div className="lux-employee-360__register-wrap">
              <table className="lux-employee-360__register">
                <thead>
                  <tr>
                    <th>Asset</th>
                    <th>Type</th>
                    <th>Tag</th>
                    <th>Assigned</th>
                    <th>Status</th>
                  </tr>
                </thead>
                <tbody>
                  {assets.map((row) => (
                    <tr key={row.id || row.tag}>
                      <td><strong>{row.name || "—"}</strong></td>
                      <td>{row.type || "—"}</td>
                      <td>{row.tag || "—"}</td>
                      <td>{row.assignedAt || "—"}</td>
                      <td><DocumentStatusBadge status={row.status} /></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}
    </ProjectDetailsTabShell>
  );
}
