import React from "react";
import classNames from "classnames/bind";

const TABS = [
  { id: "personal", label: "My projects", icon: "fe-user" },
  { id: "manager", label: "Manager overview", icon: "fe-users" },
];

export default function ProjectDashboardTabs({ activeTab, onChange, showManagerTab }) {
  if (!showManagerTab) {
    return null;
  }

  return (
    <nav className="lux-hrms-dash__tabs" aria-label="Dashboard views">
      {TABS.map((tab) => (
        <button
          key={tab.id}
          type="button"
          className={classNames("lux-hrms-dash__tab", { "is-active": activeTab === tab.id })}
          onClick={() => onChange && onChange(tab.id)}
          aria-selected={activeTab === tab.id}
        >
          <i className={`fe ${tab.icon}`} aria-hidden="true" />
          {tab.label}
        </button>
      ))}
    </nav>
  );
}

