function resourceTeamQuery(extra) {
  const query = { userTeamId: commonUtils.getCurrentUserTeamId() };
  if (extra) {
    Object.keys(extra).forEach((key) => {
      if (extra[key] != null && extra[key] !== "") {
        query[key] = extra[key];
      }
    });
  }
  return query;
}

function resourceTeamQueryString(extra) {
  const query = resourceTeamQuery(extra);
  return Object.keys(query)
    .map((key) => `${encodeURIComponent(key)}=${encodeURIComponent(query[key])}`)
    .join("&");
}

function recordResourceAudit(actionType, headline, entityRef, metadata) {
  recordAuditEvent({
    actionType,
    entityType: AUDIT_ENTITY_TYPES.RESOURCE,
    entityRef: entityRef || headline,
    headline,
    metadata,
  });
}

async function listAllocationsFromApi(filters = {}) {
  const response = await axiosUtils.getWithParam(
    `${urlConfig.RESOURCE_PLANNING_API_PATH}/allocations`,
    resourceTeamQuery({
      employeeId: filters.employeeId || undefined,
      projectId: filters.projectId || undefined,
    })
  );
  const rows = (response && response.payload) || response || [];
  const list = Array.isArray(rows) ? rows : [];
  return {
    payload: list.map((row) => normalizeAllocation(row)).filter(Boolean),
    source: "api",
  };
}

async function listAllocations(filters = {}) {

  if (shouldUseResourcePlanningApi()) {
    try {
      return await listAllocationsFromApi(filters);
    } catch (e) {
      // fall through
    }
  }

  try {
    return await listAllocationsFromApi(filters);
  } catch (e) {
        return apiErrorResult(null);
  }
}

