import React from "react";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import { WorkGraphLuxPanel } from "views/workgraph/components/WorkGraphLuxShared";

export default function EntityRelationshipPanel({ node, related, edges, loading, onSelectNode }) {
  if (loading) {
    return (
      <WorkGraphLuxPanel title="Related entities" meta="Relationships" icon="fe fe-share-2" accent="blue">
        <div className="lux-wg-skeleton lux-wg-skeleton--panel" />
      </WorkGraphLuxPanel>
    );
  }

  if (!node) {
    return (
      <WorkGraphLuxPanel title="Related entities" meta="Relationships" icon="fe fe-share-2" accent="blue">
        <div className="lux-wg-rel-empty">
          <p>Select a node in the constellation to explore relationships.</p>
        </div>
      </WorkGraphLuxPanel>
    );
  }

  const relatedList = related || [];
  const edgeList = edges || [];

  return (
    <WorkGraphLuxPanel
      title={node.label}
      meta={`${node.type} · ${node.module}`}
      icon="fe fe-share-2"
      accent={node.tone || "blue"}
      actions={
        node.route ? (
          <Link to={node.route} className="lux-onb-action lux-onb-action--ghost lux-wg-action">
            Open record
          </Link>
        ) : null
      }
    >
      <div className="lux-wg-rel-grid">
        <div className="lux-wg-rel-section">
          <h3>Connected entities ({relatedList.length})</h3>
          <ul className="lux-wg-rel-list">
            {relatedList.map((item) => (
              <li key={item.id}>
                <button
                  type="button"
                  className={classNames("lux-wg-rel-chip", item.tone && `is-${item.tone}`)}
                  onClick={() => onSelectNode && onSelectNode(item)}
                >
                  <span className="lux-wg-rel-chip__type">{item.type}</span>
                  {item.label}
                </button>
              </li>
            ))}
          </ul>
        </div>
        <div className="lux-wg-rel-section">
          <h3>Edges ({edgeList.length})</h3>
          <ul className="lux-wg-edge-list">
            {edgeList.map((edge) => (
              <li key={edge.id} className="lux-wg-edge-row">
                <span className="lux-wg-edge-row__type">{edge.type}</span>
                <span>{edge.label || edge.id}</span>
              </li>
            ))}
          </ul>
        </div>
      </div>
    </WorkGraphLuxPanel>
  );
}
