import React, { useEffect, useState } from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";
import { leaveService } from "_services/leave.service";
import { getLeaveTypeLabel } from "./leave.utils";
import { downloadLedgerCsv } from "./leaveLedger.utils";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";

const DRAWER_CLOSE_MS = 280;

function toNum(value) {
  const n = parseFloat(value);
  return Number.isNaN(n) ? 0 : n;
}

function LeaveBalanceLedgerDrawer({ open, employeeId, leaveTypeId, leaveTypes, employeeName, onClose }) {
  const [entries, setEntries] = useState([]);
  const [loading, setLoading] = useState(false);
  const [visible, setVisible] = useState(false);
  const [closing, setClosing] = useState(false);

  useEffect(() => {
    if (open) {
      setVisible(true);
      setClosing(false);
    }
  }, [open]);

  useEffect(() => {
    if (!open || !employeeId) {
      setEntries([]);
      return;
    }
    setLoading(true);
    leaveService.getBalanceLedger(employeeId, leaveTypeId).then(
      (response) => {
        setEntries((response && response.payload) || []);
        setLoading(false);
      },
      () => {
        setEntries([]);
        setLoading(false);
      }
    );
  }, [open, employeeId, leaveTypeId]);

  const requestClose = () => {
    if (closing) return;
    setClosing(true);
    window.setTimeout(() => {
      setVisible(false);
      setClosing(false);
      onClose();
    }, DRAWER_CLOSE_MS);
  };

  if (!visible) return null;

  const type = (leaveTypes || []).find((t) => String(t.id) === String(leaveTypeId));
  const title = type ? getLeaveTypeLabel(type.code, type.name) : "Balance ledger";

  return createPortal(
    <div
      className={classNames("lux-onb-drawer-backdrop lux-leave-drawer-backdrop", { "is-closing": closing })}
      role="presentation"
      onClick={requestClose}
    >
      <aside
        className={classNames("lux-onb-drawer lux-leave-drawer lux-onb-drawer--primary", { "is-closing": closing })}
        role="dialog"
        aria-label={`${title} ledger`}
        onClick={(event) => event.stopPropagation()}
      >
        <header className="lux-onb-drawer__head">
          <div className="lux-onb-drawer__head-main">
            <span className="lux-onb-drawer__category-icon" aria-hidden="true">
              <i className="fe fe-book-open" />
            </span>
            <div className="lux-onb-drawer__head-copy">
              <span className="lux-leave-drawer__eyebrow">Balance · Ledger</span>
              <h2>{title}</h2>
              <p>{employeeName ? `${employeeName} · change history` : "Balance change history"}</p>
            </div>
          </div>
          <button type="button" className="lux-onb-drawer__close" onClick={requestClose} aria-label="Close">
            <i className="fe fe-x" aria-hidden="true" />
          </button>
        </header>

        <div className="lux-onb-drawer__body lux-leave-ledger">
          {!loading && entries.length > 0 && (
            <div className="lux-leave-ledger__toolbar">
              <button
                type="button"
                className="lux-leave-drawer__btn is-ghost"
                onClick={() =>
                  downloadLedgerCsv(entries, {
                    employeeName: employeeName || `employee-${employeeId}`,
                    leaveTypeLabel: title,
                  })
                }
              >
                <i className="fe fe-download" aria-hidden="true" /> Export CSV
              </button>
            </div>
          )}

          {loading ? (
            <div className="lux-leave-register__skeleton" aria-busy="true" />
          ) : entries.length === 0 ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              icon="fe fe-book-open"
              title="No ledger entries"
              description="Balance adjustments will appear here when recorded."
            />
          ) : (
            <ul className="lux-leave-ledger__list">
              {entries.map((entry) => {
                const amount = toNum(entry.amount);
                return (
                  <li key={entry.id} className="lux-leave-ledger__item">
                    <div className="lux-leave-ledger__item-head">
                      <strong>{entry.changeType || entry.change_type || "Change"}</strong>
                      <span className={classNames("lux-leave-ledger__amount", amount < 0 ? "is-debit" : "is-credit")}>
                        {amount > 0 ? "+" : ""}
                        {amount}
                      </span>
                    </div>
                    <p className="lux-leave-ledger__meta">
                      {entry.balanceBefore != null || entry.balance_before != null
                        ? `${toNum(entry.balanceBefore || entry.balance_before)} → ${toNum(entry.balanceAfter || entry.balance_after)}`
                        : null}
                      {entry.comment ? ` · ${entry.comment}` : ""}
                    </p>
                  </li>
                );
              })}
            </ul>
          )}
        </div>
      </aside>
    </div>,
    document.body
  );
}

export default LeaveBalanceLedgerDrawer;
