import React from "react";
import { resolveApprovalSlaState } from "config/approval-sla.utils";
import {
  buildApprovalAiSummaryBrief,
  normalizeApprovalAiSummary,
} from "config/universal-approval-ai.utils";
import {
  isApprovalAiSummaryEnabled,
  shouldUseApprovalAiSummaryApi,
} from "config/universal-approval-ai.config";
import { shouldFallbackToMock } from "config/mock-fallback.utils";
import { universalApprovalService } from "_services/universalApproval.service";

export default class UniversalApprovalAiSummaryPanel extends React.Component {
  state = {
    brief: null,
    loading: false,
    source: "client",
    loadError: null,
  };

  componentDidMount() {
    this.loadBrief();
  }

  componentDidUpdate(prevProps) {
    const prevId = prevProps.item && prevProps.item.id;
    const nextId = this.props.item && this.props.item.id;
    if (prevId !== nextId) {
      this.loadBrief();
    }
  }

  loadBrief = async () => {
    const { item } = this.props;
    if (!item || !isApprovalAiSummaryEnabled()) {
      return;
    }

    const slaState = resolveApprovalSlaState(item);
    this.setState({ loading: true, loadError: null });
    try {
      if (shouldUseApprovalAiSummaryApi()) {
        const result = await universalApprovalService.getAiSummary(item, slaState);
        if (result.source === "api-error") {
          this.setState({
            brief: null,
            loading: false,
            source: "api-error",
            loadError: "Unable to load AI summary.",
          });
          return;
        }
        if (result.payload) {
          this.setState({
            brief: result.payload,
            loading: false,
            source: result.source || "api",
            loadError: null,
          });
          return;
        }
        if (!shouldFallbackToMock()) {
          this.setState({
            brief: null,
            loading: false,
            source: "api-error",
            loadError: "Unable to load AI summary.",
          });
          return;
        }
      }
      if (!shouldFallbackToMock() && shouldUseApprovalAiSummaryApi()) {
        this.setState({
          brief: null,
          loading: false,
          source: "api-error",
          loadError: "Unable to load AI summary.",
        });
        return;
      }
      const draft = buildApprovalAiSummaryBrief(item, { source: "client", slaState });
      this.setState({
        brief: normalizeApprovalAiSummary(draft),
        loading: false,
        source: "client",
        loadError: null,
      });
    } catch (e) {
      if (!shouldFallbackToMock()) {
        this.setState({
          brief: null,
          loading: false,
          source: "api-error",
          loadError: "Unable to load AI summary.",
        });
        return;
      }
      const draft = buildApprovalAiSummaryBrief(item, { source: "client", slaState });
      this.setState({
        brief: normalizeApprovalAiSummary(draft),
        loading: false,
        source: "client",
        loadError: null,
      });
    }
  };

  render() {
    if (!isApprovalAiSummaryEnabled()) {
      return null;
    }

    const { brief, loading, source, loadError } = this.state;
    if (loading && !brief) {
      return (
        <section className="lux-appr-drawer__card lux-appr-ai-summary" aria-busy="true">
          <header className="lux-appr-drawer__card-head">
            <h3>AI summary draft</h3>
            <p>Generating approval context…</p>
          </header>
        </section>
      );
    }
    if (!brief) {
      if (source === "api-error" || loadError) {
        return (
          <section className="lux-appr-drawer__card lux-appr-ai-summary">
            <header className="lux-appr-drawer__card-head">
              <h3>AI summary draft</h3>
              <p>{loadError || "AI summary unavailable."}</p>
            </header>
          </section>
        );
      }
      return null;
    }

    const confidencePct = Math.round((brief.confidence || 0) * 100);

    return (
      <section className="lux-appr-drawer__card lux-appr-ai-summary">
        <header className="lux-appr-drawer__card-head">
          <h3>AI summary draft</h3>
          <p>AI agent gateway preview — read-only recommendation for approvers.</p>
        </header>
        <p className="lux-appr-ai-summary__text">{brief.summary}</p>
        <p className="lux-appr-ai-summary__rec">{brief.recommendation}</p>
        {brief.nextBestAction ? (
          <p className="lux-appr-ai-summary__action">{brief.nextBestAction}</p>
        ) : null}
        <div className="lux-appr-ai-summary__meta">
          <span className="lux-appr-ai-summary__confidence">Confidence {confidencePct}%</span>
          <span className="lux-appr-ai-summary__badge">
            {source === "api"
              ? "Live"
              : source === "mock"
                ? "Demo"
                : "Unavailable"}
          </span>
        </div>
        {(brief.checklist || []).length > 0 && (
          <ul className="lux-appr-ai-summary__checklist">
            {(brief.checklist || []).map((row) => (
              <li key={row.id}>
                <strong>{row.label}</strong>
                <small>{row.detail}</small>
              </li>
            ))}
          </ul>
        )}
        {(brief.evidence || []).length > 0 && (
          <ul className="lux-appr-ai-summary__evidence">
            {(brief.evidence || []).map((row) => (
              <li key={row}>{row}</li>
            ))}
          </ul>
        )}
        <p className="lux-appr-ai-summary__disclaimer">{brief.disclaimer}</p>
      </section>
    );
  }
}
