import React, { useEffect } from "react";
import { useReportPageDataSource } from "views/common/PageChromeContext";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import { AdminInsightStrip } from "views/admin/components/AdminLuxShared";
import AdminHubTabs, { filterDeveloperHubTabs } from "views/admin/components/AdminHubTabs";
import { usePersonaContext } from "hooks/usePersonaContext";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import { GovernanceKpiStrip } from "views/project/components/ProjectGovernanceLuxShared";

export default function DeveloperLuxPage({
  pageMeta,
  dataSource,
  demoLabel = "Demo extensibility data",
  heroActions,
  kpiCards,
  loading,
  pageHeaderNameChangeHandler,
  shellTitle,
  testId,
  pageId,
  children,
  moduleClass = "lux-dev-module",
}) {
  useReportPageDataSource(dataSource);
  const { menuAccessControl } = usePersonaContext();
  const developerHubTabs = filterDeveloperHubTabs(menuAccessControl);
  const meta = pageMeta || {
    tone: "cyan",
    icon: "fe fe-code",
    eyebrow: "Admin",
    titleLead: "Developer",
    titleAccent: "portal",
    lede: "Enterprise extensibility controls.",
  };

  useEffect(() => {
    if (pageHeaderNameChangeHandler && shellTitle) {
      pageHeaderNameChangeHandler(shellTitle);
    }
  }, [pageHeaderNameChangeHandler, shellTitle]);

  return (
    <div
      className={classNames("lux-register-page", moduleClass, "lux-dev-lux", meta.tone && `is-${meta.tone}`)}
      data-testid={testId || (pageId ? `page-integrations-${pageId}` : undefined)}
    >
      <div className="lux-dev-lux__ambient" aria-hidden="true">
        <span className="lux-dev-lux__orb lux-dev-lux__orb--a" />
        <span className="lux-dev-lux__orb lux-dev-lux__orb--b" />
        <span className="lux-dev-lux__orb lux-dev-lux__orb--c" />
      </div>
      <LuxModuleIntro
        meta={meta}
        actions={heroActions || undefined}
        nav={
          developerHubTabs.length ? (
            <AdminHubTabs tabs={developerHubTabs} ariaLabel="Developer portal sections" />
          ) : null
        }
      />
      <div className="lux-register-page__body">
        {kpiCards && kpiCards.length ? (
          <GovernanceKpiStrip cards={kpiCards} loading={loading} className="lux-dev-lux__kpi-strip" />
        ) : null}

        <div className="lux-dev-lux__content">{children}</div>
      </div>
    </div>
  );
}

export function DeveloperActionButton({ to, onClick, icon, variant = "ghost", children, disabled, className }) {
  const classes = classNames("lux-onb-action", "lux-dev-action", `lux-onb-action--${variant}`, className);
  const content = icon ? (
    <>
      <i className={icon} aria-hidden="true" />
      <span>{children}</span>
    </>
  ) : (
    children
  );
  if (to && !onClick) {
    return (
      <Link to={to} className={classes}>
        {content}
      </Link>
    );
  }
  return (
    <button type="button" className={classes} onClick={onClick} disabled={disabled}>
      {content}
    </button>
  );
}

export function DeveloperLuxPanel({ title, meta, icon, accent, featured, actions, children, className }) {
  return (
    <section
      className={classNames(
        "lux-hrms-dash__panel",
        "lux-dev-lux__panel",
        accent && `is-${accent}`,
        featured && "lux-dev-lux__panel--featured",
        className
      )}
    >
      <header className="lux-hrms-dash__panel-head lux-dev-lux__panel-head">
        <div className="lux-dev-lux__panel-head-main">
          {icon ? <i className={icon} aria-hidden="true" /> : null}
          <div>
            <h2 className="lux-hrms-dash__panel-title">{title}</h2>
            {meta ? <p className="lux-hrms-dash__panel-sub">{meta}</p> : null}
          </div>
        </div>
        {actions ? <div className="lux-hrms-dash__panel-actions lux-dev-lux__panel-actions">{actions}</div> : null}
      </header>
      <div className="lux-hrms-dash__panel-body lux-dev-lux__panel-body">{children}</div>
    </section>
  );
}

export function DeveloperInsightPanel({ insights, loading }) {
  return <AdminInsightStrip insights={insights} loading={loading} className="lux-dev-lux__insights" />;
}

export function DeveloperStatusBadge({ status }) {
  return <span className={classNames("lux-dev-badge", `lux-dev-badge--${status || "active"}`)}>{status}</span>;
}
