import React, { Component } from "react";
import { REVENUE_RECOGNITION_HUB_META } from "config/finance-intelligence-nav.config";
import { formatFinanceUsd } from "config/finance-intelligence.utils";
import { revenueRecognitionService } from "_services/revenueRecognition.service";
import FinanceLuxPage, {
  FinanceActionButton,
  FinanceInsightPanel,
  FinanceLuxPanel,
  FinanceMetricTiles,
  FinanceQuickNav,
  FinanceRevRecSectionTabs,
  REV_REC_QUICK_LINKS,
} from "views/finance/components/FinanceLuxShared";
import FinanceLoadAlert from "views/finance/components/FinanceLoadAlert";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";

class RevenueRecognitionHubPage extends Component {
  state = { loading: true, loadError: null, report: null };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Revenue recognition");
    }
    this.loadReport();
  }

  loadReport = async () => {
    this.setState({ loading: true, loadError: null });
    const result = await revenueRecognitionService.recognizedVsBilled();
    if (result.source === "api" && result.payload) {
      this.setState({ loading: false, report: result.payload, loadError: null });
    } else {
      this.setState({
        loading: false,
        report: null,
        loadError: result.error || new Error("Unable to load report"),
      });
    }
  };

  buildKpis = (report, loading) => {
    const recognized = report && report.recognizedUsd != null ? report.recognizedUsd : null;
    const billed = report && report.billedUsd != null ? report.billedUsd : null;
    const unbilled = report && report.unbilledUsd != null ? report.unbilledUsd : null;
    return [
      {
        id: "recognized",
        label: "Recognized",
        value: loading || recognized == null ? "—" : formatFinanceUsd(recognized),
        hint: "Posted recognition",
        tone: "indigo",
        icon: "fe fe-trending-up",
      },
      {
        id: "billed",
        label: "Billed",
        value: loading || billed == null ? "—" : formatFinanceUsd(billed),
        hint: "Invoiced amount",
        tone: "green",
        icon: "fe fe-credit-card",
      },
      {
        id: "unbilled",
        label: "Unbilled",
        value: loading || unbilled == null ? "—" : formatFinanceUsd(unbilled),
        hint: "Recognized, not billed",
        tone: "amber",
        icon: "fe fe-clock",
      },
      {
        id: "workflow",
        label: "Workflow",
        value: "4",
        hint: "Policy → lock steps",
        tone: "violet",
        icon: "fe fe-git-branch",
      },
    ];
  };

  render() {
    const { loading, loadError, report } = this.state;
    const kpiCards = this.buildKpis(report, loading);
    const metricTiles = report
      ? [
          {
            id: "recognized",
            label: "Recognized USD",
            value: formatFinanceUsd(report.recognizedUsd),
            hint: "Approved recognition entries",
            tone: "indigo",
          },
          {
            id: "billed",
            label: "Billed USD",
            value: formatFinanceUsd(report.billedUsd),
            hint: "Linked invoice billing",
            tone: "green",
          },
          {
            id: "unbilled",
            label: "Unbilled recognized",
            value: formatFinanceUsd(report.unbilledUsd),
            hint: "Gap to close with invoices",
            tone: "amber",
          },
        ]
      : [];

    return (
      <FinanceLuxPage
        testId="revenue-recognition-hub"
        pageMeta={REVENUE_RECOGNITION_HUB_META}
        dataSource={report ? "api" : loadError ? "api-error" : loading ? null : "api"}
        demoLabel={null}
        loading={loading}
        kpiCards={kpiCards}
        heroActions={
          <>
            <FinanceActionButton
              icon="fe fe-refresh-cw"
              variant="ghost"
              onClick={this.loadReport}
              disabled={loading}
            >
              Refresh
            </FinanceActionButton>
            <FinanceActionButton
              to="/finance/revenue-recognition/policies"
              icon="fe fe-sliders"
              variant="ghost"
            >
              Policies
            </FinanceActionButton>
            <FinanceActionButton
              to="/finance/revenue-recognition/entries"
              icon="fe fe-check-square"
              variant="primary"
            >
              Review entries
            </FinanceActionButton>
          </>
        }
      >
        <FinanceRevRecSectionTabs active="/finance/revenue-recognition" />
        <FinanceQuickNav
          links={REV_REC_QUICK_LINKS.filter((l) => l.path !== "/finance/revenue-recognition")}
          eyebrow="Recognition workflow"
          title="Continue policy → schedule → entry → lock"
        />
        <FinanceInsightPanel
          insights={[
            {
              id: "policy",
              tone: "violet",
              icon: "fe fe-sliders",
              title: "Start with a policy",
              copy: "Define TIME_BASED, MILESTONE, or percent-complete methods before generating schedules.",
              path: "/finance/revenue-recognition/policies",
            },
            {
              id: "schedule",
              tone: "green",
              icon: "fe fe-calendar",
              title: "Link Project / PO / invoice",
              copy: "Schedules must reference live Project, Purchase Order, billing plan, and invoice.",
              path: "/finance/revenue-recognition/schedules",
            },
            {
              id: "close",
              tone: "rose",
              icon: "fe fe-lock",
              title: "Close the period",
              copy: "Approve entries, then lock the period so recognition amounts stay final.",
              path: "/finance/revenue-recognition/period-close",
            },
          ]}
        />
        <FinanceLoadAlert
          error={loadError}
          fallback="Unable to load recognized vs billed."
          onDismiss={() => this.setState({ loadError: null })}
        />

        <FinanceLuxPanel
          title="Recognized vs billed"
          meta="Live rollup from recognition entries and linked invoices"
          icon="fe fe-bar-chart-2"
          accent="indigo"
          actions={
            <FinanceActionButton
              to="/finance/billing-plans"
              icon="fe fe-layers"
              variant="ghost"
            >
              Billing plans
            </FinanceActionButton>
          }
        >
          {loading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="Loading report"
              description="Fetching recognized vs billed totals."
            />
          ) : report ? (
            <FinanceMetricTiles tiles={metricTiles} testId="rev-rec-report" />
          ) : (
            <LuxRegisterEmptyState
              title="No report data"
              description="Recognized vs billed totals will appear once recognition entries are posted."
              showCreate={false}
            />
          )}
        </FinanceLuxPanel>

        <FinanceLuxPanel
          title="Recognition pipeline"
          meta="Canonical source links stay on Project / PO / TaskActivity"
          icon="fe fe-git-branch"
          accent="violet"
        >
          <ol className="lux-finance-pipeline" data-testid="rev-rec-pipeline">
            <li>
              <strong>Policy</strong>
              <span>Choose recognition method and periods or milestones.</span>
            </li>
            <li>
              <strong>Schedule</strong>
              <span>Generate draft lines tied to Project, PO, billing plan, and invoice.</span>
            </li>
            <li>
              <strong>Entries</strong>
              <span>Approve drafts to post recognized amounts into the period.</span>
            </li>
            <li>
              <strong>Period close</strong>
              <span>Lock the period so posted recognition cannot be edited.</span>
            </li>
          </ol>
        </FinanceLuxPanel>
      </FinanceLuxPage>
    );
  }
}

export default RevenueRecognitionHubPage;
