function resolveUserTeamId(explicit) {
  if (explicit != null && explicit !== "") {
    return explicit;
  }
  const teamId = commonUtils.getCurrentUserTeamId();
  if (teamId != null && teamId !== "") {
    return teamId;
  }
  const user = commonUtils.getCurrentUser() || {};
  if (user.userTeamId != null) {
    return user.userTeamId;
  }
  return null;
}

function resolveActorId() {
  const actorId = commonUtils.getCurrentUserId();
  return actorId != null ? actorId : null;
}

function assertUserTeamId(userTeamId) {
  if (userTeamId == null || userTeamId === "" || String(userTeamId) === "undefined") {
    throw new Error("userTeamId is required for payroll API calls");
  }
  return userTeamId;
}

function payrollRunQueryParams(userTeamId) {
  return {
    userTeamId: assertUserTeamId(resolveUserTeamId(userTeamId)),
    actorId: resolveActorId(),
  };
}

function payrollListTeamQuery(extra) {
  const query = {};
  const explicitIds = extra && extra.userTeamIds;
  const currentIds = commonUtils.getCurrentUserTeamIds
    ? commonUtils.getCurrentUserTeamIds() || []
    : [];
  const currentId = resolveUserTeamId();
  if (Array.isArray(explicitIds) && explicitIds.length) {
    query.userTeamIds = explicitIds;
  } else if (currentIds.length > 0) {
    query.userTeamIds = currentIds;
  } else if (currentId != null && currentId !== "") {
    query.userTeamId = currentId;
  }
  if (extra) {
    Object.keys(extra).forEach((key) => {
      if (key === "userTeamId" || key === "userTeamIds") return;
      if (extra[key] != null && extra[key] !== "") {
        query[key] = extra[key];
      }
    });
  }
  return query;
}

function toQueryString(params) {
  const parts = [];
  Object.keys(params || {}).forEach((key) => {
    const value = params[key];
    if (Array.isArray(value)) {
      value.forEach((item) => {
        if (item != null && item !== "") {
          parts.push(`${encodeURIComponent(key)}=${encodeURIComponent(item)}`);
        }
      });
    } else if (value != null && value !== "") {
      parts.push(`${encodeURIComponent(key)}=${encodeURIComponent(value)}`);
    }
  });
  return parts.join("&");
}

