/** PR-01 — POST calculate generates lines + draft paychecks from live employee finance profiles. */
async function calculateRun(runId, userTeamId) {

  if (shouldUsePayrollApi()) {
    try {
      const { userTeamId: resolvedTeamId, actorId } = payrollRunQueryParams(userTeamId);
      const response = await axiosUtils.post(
        `${urlConfig.PAYROLL_API_PATH}/runs/${encodeURIComponent(runId)}/calculate?userTeamId=${resolvedTeamId}&actorId=${actorId}`
      );
      const payload = (response && response.payload) || response || {};
      const run = normalizePayrollRun(payload.run || payload);
      const lines = Array.isArray(payload.lines) ? payload.lines.map(normalizePayrollLine) : [];
      const exceptions = Array.isArray(payload.exceptions)
        ? payload.exceptions.map(normalizePayrollException)
        : [];
      recordRunStatusAudit(run, "Calculated");
      return { payload: { run, lines, exceptions }, source: "api" };
    } catch (e) {
      return { payload: null, source: "api-error", error: e };
    }
  }
  return { payload: null, source: "api-error" };
}

/** EH06 — GET payout CSV for published (or calculated draft) paychecks. */
async function downloadPayoutExport(runId) {
  if (!runId || !shouldUsePayrollApi()) {
    return { payload: null, source: "unavailable" };
  }
  try {
    const { userTeamId } = payrollRunQueryParams();
    const blob = await axiosUtils.get(
      `${urlConfig.PAYROLL_API_PATH}/runs/${encodeURIComponent(runId)}/payout-export?userTeamId=${userTeamId}`,
      { responseType: "blob" }
    );
    if (!blob) {
      return { payload: null, source: "api-error" };
    }
    const filename = `payout-export-${String(runId).replace(/[^a-zA-Z0-9._-]+/g, "-")}.csv`;
    const url = window.URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = filename;
    link.click();
    window.URL.revokeObjectURL(url);
    return { payload: { downloaded: true, filename }, source: "api" };
  } catch (e) {
    return { payload: null, source: "api-error", error: e };
  }
}

