async function getEmployeePayroll(employeeId) {
  if (shouldUsePayrollApi()) {
    try {
      const [paychecksResult, groupsResult] = await Promise.all([
        listPaychecks({ employeeId }),
        listPayrollGroups(),
      ]);
      const paychecks = paychecksResult.payload || [];
      const lines = paychecks.map((row) => ({
        id: row.id,
        employeeId: row.employeeId,
        employeeName: row.employeeName,
        department: row.department,
        gross: row.gross,
        net: row.net,
        status: row.status,
        period: row.periodLabel,
        paidOn: row.payDate,
      }));
      const groupName = (groupsResult.payload && groupsResult.payload[0] && groupsResult.payload[0].name) || null;
      return {
        payload: toEmployee360PayrollSummary(employeeId, lines, groupName),
        source: paychecksResult.source || "api",
      };
    } catch (e) {
      return { payload: null, source: "client" };
    }
  }
  return { payload: null, source: "client" };
}

