async function getPaycheck(paycheckId, viewerContext) {
  if (shouldUsePayrollApi()) {
    try {
      const { userTeamId } = payrollRunQueryParams();
      const requesterEmployeeId =
        (viewerContext && viewerContext.viewerEmployeeId) || commonUtils.getCurrentUserId();
      const payrollAdmin = canManagePaycheck(viewerContext);
      const employeeSelfService = !payrollAdmin;
      const query = [
        `userTeamId=${userTeamId}`,
        requesterEmployeeId != null ? `requesterEmployeeId=${encodeURIComponent(requesterEmployeeId)}` : null,
        `payrollAdmin=${payrollAdmin ? "true" : "false"}`,
        `employeeSelfService=${employeeSelfService ? "true" : "false"}`,
      ]
        .filter(Boolean)
        .join("&");
      const response = await axiosUtils.get(
        `${urlConfig.PAYROLL_API_PATH}/paychecks/${encodeURIComponent(paycheckId)}?${query}`
      );
      const paycheck = normalizePaycheck((response && response.payload) || response);
      if (!paycheck) {
        return { payload: null, source: "api" };
      }
      if (viewerContext && !canViewPaycheckDetail(viewerContext, paycheck)) {
        return { payload: null, source: "api", accessDenied: true };
      }
      const masked = maskPaycheckForDisplay(
        paycheck,
        viewerContext && viewerContext.maskingPolicy,
        viewerContext
      );
      return { payload: masked, source: "api" };
    } catch (e) {
      if (e && (e.status === 403 || e.responseStatus === 403 || String(e.message || "").includes("403"))) {
        return { payload: null, source: "api", accessDenied: true };
      }
      console.warn("[Payroll] Paycheck detail API unavailable.", e);
      return { payload: null, source: "client" };
    }
  }
  return { payload: null, source: "client" };
}

