function triggerBlobDownload(blob, filename) {
  const url = window.URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  link.click();
  window.URL.revokeObjectURL(url);
}

function safeDownloadFilename(prefix, id, ext) {
  const safe = String(id || "file").replace(/[^a-zA-Z0-9._-]+/g, "-");
  return `${prefix}-${safe}.${ext}`;
}

/** EH06 — Prefer server Payslip estimate PDF; jsPDF only when mock fallback is on. */
async function downloadPaycheckPdf(paycheckId) {
  if (!isPayslipPdfEnabled()) {
    throw new Error("Payslip PDF download is not enabled.");
  }
  if (shouldUsePayrollApi()) {
    try {
      const { userTeamId } = payrollRunQueryParams();
      const blob = await axiosUtils.get(
        `${urlConfig.PAYROLL_API_PATH}/paychecks/${encodeURIComponent(paycheckId)}/documents/download?userTeamId=${userTeamId}`,
        { responseType: "blob" }
      );
      if (blob) {
        const filename = safeDownloadFilename("payslip-estimate", paycheckId, "pdf");
        triggerBlobDownload(blob, filename);
        recordAuditEvent({
          actionType: AUDIT_ACTION_TYPES.EXPORTED,
          entityType: AUDIT_ENTITY_TYPES.PAYROLL,
          entityId: paycheckId,
          entityRef: String(paycheckId),
          metadata: {
            format: "pdf",
            source: "api",
            renderer: "payslip-estimate",
          },
        });
        return { payload: { downloaded: true, filename }, source: "api" };
      }
    } catch (e) {
      // fail closed — no mock PDF path
    }
  }
  throw new Error("Unable to complete action via API.");
}

/**
 * EH06 — Form 16 estimate PDF for employee + Indian FY (e.g. 2025-26).
 * Fail-closed when payroll API is off or mock fallback is disabled.
 * Always labeled ESTIMATE — not a legal Form 16.
 */
async function downloadForm16(employeeId, fy, viewerContext) {
  if (!employeeId || !fy) {
    throw new Error("employeeId and fy are required for Form 16 estimate download.");
  }
  if (!shouldUsePayrollApi()) {
    throw new Error("Unable to complete action via API.");
  }
  const { userTeamId } = payrollRunQueryParams();
  const requesterEmployeeId =
    (viewerContext && viewerContext.viewerEmployeeId) || commonUtils.getCurrentUserId();
  const payrollAdmin = canManagePaycheck(viewerContext);
  const query = [
    `employeeId=${encodeURIComponent(employeeId)}`,
    `fy=${encodeURIComponent(fy)}`,
    `userTeamId=${userTeamId}`,
    requesterEmployeeId != null ? `requesterEmployeeId=${encodeURIComponent(requesterEmployeeId)}` : null,
    `payrollAdmin=${payrollAdmin ? "true" : "false"}`,
  ]
    .filter(Boolean)
    .join("&");
  try {
    const blob = await axiosUtils.get(
      `${urlConfig.PAYROLL_API_PATH}/form16/download?${query}`,
      { responseType: "blob" }
    );
    if (!blob) {
      throw new Error("Unable to complete action via API.");
    }
    const filename = safeDownloadFilename("form16-estimate", `${employeeId}-${fy}`, "pdf");
    triggerBlobDownload(blob, filename);
    recordAuditEvent({
      actionType: AUDIT_ACTION_TYPES.EXPORTED,
      entityType: AUDIT_ENTITY_TYPES.PAYROLL,
      entityId: employeeId,
      entityRef: `Form16 estimate · ${fy}`,
      metadata: {
        format: "pdf",
        document: "form16-estimate",
        documentKind: "ESTIMATE",
        statutory: false,
        legalForm16: false,
        financialYear: fy,
      },
    });
    return {
      payload: { downloaded: true, filename, fy, documentKind: "ESTIMATE", statutory: false },
      source: "api",
    };
  } catch (e) {
    throw new Error("Unable to complete action via API.");
  }
}

async function listDeductions() {
  if (shouldUsePayrollApi()) {
    try {
      const response = await axiosUtils.getWithParam(
        `${urlConfig.PAYROLL_API_PATH}/deductions`,
        payrollListTeamQuery()
      );
      const rows = (response && response.payload) || response || [];
      return {
        payload: (Array.isArray(rows) ? rows : []).map((row) => normalizeDeductionSchedule(row)).filter(Boolean),
        source: "api",
      };
    } catch (e) {
      console.warn("[Payroll] Deductions API unavailable, falling back.", e);
    }
  }
  try {
    const result = await employeeFinanceService.listDeductionSchedules();
    return { payload: result.payload || [], source: result.source || "api-error" };
  } catch (e) {
    return { payload: [], source: "api-error" };
  }
}

async function createDeduction(request) {
  if (!shouldUsePayrollApi()) {
    return { payload: normalizeDeductionSchedule(request), source: "client" };
  }
  const { userTeamId, actorId } = payrollRunQueryParams();
  const response = await axiosUtils.post(
    `${urlConfig.PAYROLL_API_PATH}/deductions?userTeamId=${userTeamId}&actorId=${actorId}`,
    request
  );
  const row = (response && response.payload) || response;
  return { payload: normalizeDeductionSchedule(row), source: "api" };
}

async function updateDeduction(deductionId, request) {
  if (!shouldUsePayrollApi()) {
    return { payload: normalizeDeductionSchedule({ ...request, id: deductionId }), source: "client" };
  }
  const { userTeamId, actorId } = payrollRunQueryParams();
  const response = await axiosUtils.patch(
    `${urlConfig.PAYROLL_API_PATH}/deductions/${encodeURIComponent(deductionId)}?userTeamId=${userTeamId}&actorId=${actorId}`,
    request
  );
  const row = (response && response.payload) || response;
  return { payload: normalizeDeductionSchedule(row), source: "api" };
}

async function getPayrollConfig() {
  if (shouldUsePayrollApi()) {
    try {
      const { userTeamId } = payrollRunQueryParams();
      const response = await axiosUtils.getWithParam(`${urlConfig.PAYROLL_API_PATH}/config`, {
        userTeamId,
      });
      const raw = (response && response.payload) || response || {};
      const groups = (raw.groups || []).map(normalizePayrollGroup).filter(Boolean);
      return {
        payload: enrichPayrollConfigPayload({
          ...raw,
          groups,
          mandatoryChecks: Array.isArray(raw.mandatoryChecks) ? raw.mandatoryChecks : [],
        }),
        source: "api",
      };
    } catch (e) {
      console.warn("[Payroll] Config API unavailable, composing from local sources.", e);
    }
  }

  const [groupsResult, deductionsResult, structuresResult] = await Promise.all([
    listPayrollGroups(),
    listDeductions(),
    listSalaryStructures(),
  ]);
  const groups = groupsResult.payload || [];
  const structureCount = (structuresResult.payload || []).length;
  const paychecksEnabled = isPaychecksEnabled();

  return {
    payload: enrichPayrollConfigPayload({
      groups,
      deductionScheduleCount: (deductionsResult.payload || []).length,
      structureCount,
      paychecksEnabled,
      mandatoryChecks: buildClientPayrollMandatoryChecks({
        groups,
        paychecksEnabled,
        structureCount,
      }),
      source: "application-config-and-payroll-models",
    }),
    source: groupsResult.source || structuresResult.source || "client",
  };
}
