import React, { useEffect } from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";

function TimesheetLuxuryDialog({
  show,
  onClose,
  ariaLabel,
  kicker,
  kickerIcon = "fe-layers",
  title,
  subtitle,
  badge,
  children,
  footer,
  panelClassName,
  wide,
  hideHeader = false,
}) {
  useEffect(() => {
    if (!show) return undefined;

    const onKeyDown = (event) => {
      if (event.key === "Escape") onClose();
    };

    document.addEventListener("keydown", onKeyDown);
    document.body.classList.add("lux-ts-detail-open");

    return () => {
      document.removeEventListener("keydown", onKeyDown);
      document.body.classList.remove("lux-ts-detail-open");
    };
  }, [show, onClose]);

  if (!show || typeof document === "undefined") return null;

  const closeButton = (
    <button type="button" className="lux-ts-detail__close" onClick={onClose} aria-label="Close">
      <i className="fe fe-x" aria-hidden="true" />
    </button>
  );

  return createPortal(
    <div className="lux-ts-detail" role="dialog" aria-modal="true" aria-label={ariaLabel}>
      <button type="button" className="lux-ts-detail__backdrop" onClick={onClose} aria-label="Close" />
      <div
        className={classNames("lux-ts-detail__panel", panelClassName, {
          "lux-ts-detail__panel--wide": wide,
          "lux-ts-detail__panel--no-head": hideHeader,
        })}
      >
        {hideHeader ? (
          closeButton
        ) : (
          <header className="lux-ts-detail__head">
            <div>
              {kicker && (
                <span className="lux-ts-detail__kicker">
                  <i className={`fe ${kickerIcon}`} aria-hidden="true" />
                  {kicker}
                </span>
              )}
              <div className="lux-ts-detail__title-row">
                <h3 className="lux-ts-detail__title">{title}</h3>
                {badge && (
                  <span className={classNames("lux-ts-detail__badge", `is-${badge.tone}`)}>
                    {badge.label}
                  </span>
                )}
              </div>
              {subtitle && <p className="lux-ts-detail__sub">{subtitle}</p>}
            </div>
            {closeButton}
          </header>
        )}
        <div className="lux-ts-detail__body">{children}</div>
        {footer && <footer className="lux-ts-detail__foot">{footer}</footer>}
      </div>
    </div>,
    document.body
  );
}

export default TimesheetLuxuryDialog;
