import React from "react";
import { DeveloperLuxPanel } from "views/developer/components/DeveloperLuxShared";

export default function DeveloperUsageAnalyticsPanel({ analytics, loading, loadError }) {
  if (loading) {
    return (
      <DeveloperLuxPanel title="Usage analytics" meta="API and webhook health" icon="fe fe-bar-chart-2" accent="indigo">
        <div className="lux-dev-skeleton lux-dev-skeleton--panel" />
      </DeveloperLuxPanel>
    );
  }

  if (!analytics) {
    return (
      <DeveloperLuxPanel title="Usage analytics" meta="API and webhook health" icon="fe fe-bar-chart-2" accent="indigo">
        <div className="lux-dev-empty">
          {loadError ? "Usage analytics are unavailable until the overview loads." : "No usage analytics yet."}
        </div>
      </DeveloperLuxPanel>
    );
  }

  const scopes = analytics.topScopes || [];
  const totalApiRequests = Number(analytics.totalApiRequests) || 0;
  const webhookSuccessRate = Number(analytics.webhookSuccessRate) || 0;
  const webhookFailureRate = Number(analytics.webhookFailureRate) || 0;

  return (
    <div className="lux-dev-analytics-grid">
      <DeveloperLuxPanel title="Platform usage" meta="Last 30 days" icon="fe fe-activity" accent="cyan">
        <div className="lux-dev-snapshot">
          <div className="lux-dev-snapshot__metrics">
            <article className="lux-dev-snapshot__metric is-cyan">
              <span>API requests</span>
              <strong>{totalApiRequests.toLocaleString()}</strong>
            </article>
            <article className="lux-dev-snapshot__metric is-emerald">
              <span>Webhook success</span>
              <strong>{webhookSuccessRate}%</strong>
            </article>
            <article className="lux-dev-snapshot__metric is-rose">
              <span>Webhook failures</span>
              <strong>{webhookFailureRate}%</strong>
            </article>
          </div>
        </div>
      </DeveloperLuxPanel>

      <DeveloperLuxPanel title="Scope distribution" meta="Active API keys" icon="fe fe-layers" accent="indigo">
        <div className="lux-dev-density-bars">
          {scopes.map((bar) => (
            <div key={bar.label} className="lux-dev-density-row">
              <span className="lux-dev-density-row__label">{bar.label}</span>
              <div className="lux-dev-density-row__track">
                <span className="lux-dev-density-row__fill" style={{ width: `${Math.min(bar.count * 20, 100)}%` }} />
              </div>
              <span className="lux-dev-density-row__meta">{bar.count}</span>
            </div>
          ))}
        </div>
      </DeveloperLuxPanel>
    </div>
  );
}
