import React from "react";
import { WorkGraphLuxPanel } from "views/workgraph/components/WorkGraphLuxShared";

export default function IndexEventsStrip({ events, loading }) {
  const list = events || [];

  return (
    <WorkGraphLuxPanel title="Index updater" meta="Event-driven" icon="fe fe-refresh-cw" accent="slate">
      {loading ? (
        <div className="lux-wg-skeleton lux-wg-skeleton--row" />
      ) : (
        <ul className="lux-wg-events">
          {list.map((evt) => (
            <li key={evt.id} className="lux-wg-event-row">
              <span className="lux-wg-event-row__type">{evt.eventType}</span>
              <span className="lux-wg-event-row__node">{evt.nodeId}</span>
              <span className="lux-wg-event-row__status">{evt.status}</span>
              <time>{evt.at}</time>
            </li>
          ))}
        </ul>
      )}
    </WorkGraphLuxPanel>
  );
}
