import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import { commonUtils } from "_helpers";

class LeaveEmployeeFilter extends PureComponent {
  constructor() {
    super();
    this.state = { open: false, filterText: "" };
    this.triggerRef = React.createRef();
    this.panelRef = React.createRef();
  }

  componentDidMount() {
    document.addEventListener("mousedown", this.handleOutsideClick);
  }

  componentWillUnmount() {
    document.removeEventListener("mousedown", this.handleOutsideClick);
  }

  handleOutsideClick = (event) => {
    if (!this.state.open) return;
    const panel = this.panelRef.current;
    const trigger = this.triggerRef.current;
    if (panel && !panel.contains(event.target) && trigger && !trigger.contains(event.target)) {
      this.closePanel();
    }
  };

  closePanel = () => this.setState({ open: false, filterText: "" });

  togglePanel = () => {
    if (this.props.isLoading) return;
    this.setState((prev) => ({ open: !prev.open, filterText: prev.open ? "" : prev.filterText }));
  };

  selectEmployee = (employeeId) => {
    this.props.onChange(employeeId);
    this.closePanel();
  };

  getSelectedLabel = () => {
    const { employees, selectedEmployeeId, currentEmployee, placeholder } = this.props;
    if (selectedEmployeeId != null && selectedEmployeeId !== "") {
      const match = (employees || []).find((emp) => String(emp.id) === String(selectedEmployeeId));
      return (match && match.name) || "Employee";
    }
    if (currentEmployee && currentEmployee.name) {
      return currentEmployee.name;
    }
    return placeholder || "Select employee";
  };

  render() {
    const { employees, selectedEmployeeId, isLoading, className, panelAlign } = this.props;
    const { open, filterText } = this.state;
    const list = (employees || []).filter(
      (employee) => !filterText || commonUtils.stringContainsString(employee.name, filterText)
    );
    const hasEmployees = (employees || []).length > 0;

    return (
      <div
        className={classNames("lux-leave-employee-filter", className)}
        data-testid="leave-employee-filter"
      >
        <button
          ref={this.triggerRef}
          type="button"
          className={classNames("lux-leave-employee-filter__trigger", { "is-open": open })}
          onClick={this.togglePanel}
          disabled={isLoading || !hasEmployees}
          aria-expanded={open}
          aria-haspopup="listbox"
          data-testid="leave-employee-filter-trigger"
        >
          <i className="fe fe-user" aria-hidden="true" />
          <span>{isLoading && !hasEmployees ? "Loading employees…" : this.getSelectedLabel()}</span>
          <i className="fe fe-chevron-down" aria-hidden="true" />
        </button>

        {open && (
          <div
            ref={this.panelRef}
            className={classNames("lux-leave-employee-filter__panel", {
              "is-align-left": panelAlign === "left",
            })}
            role="listbox"
          >
            <label className="lux-leave-employee-filter__search">
              <i className="fe fe-search" aria-hidden="true" />
              <input
                type="search"
                placeholder="Search employees…"
                value={filterText}
                onChange={(event) => this.setState({ filterText: event.target.value })}
                aria-label="Search employees"
              />
            </label>
            <div className="lux-leave-employee-filter__list">
              {list.map((employee) => (
                <button
                  key={employee.id}
                  type="button"
                  role="option"
                  aria-selected={String(selectedEmployeeId || "") === String(employee.id)}
                  className={classNames("lux-leave-employee-filter__option", {
                    "is-selected": String(selectedEmployeeId || "") === String(employee.id),
                  })}
                  onClick={() => this.selectEmployee(employee.id)}
                >
                  <strong>{employee.name}</strong>
                  {employee.designation && <em>{employee.designation}</em>}
                </button>
              ))}
              {!list.length && (
                <p className="lux-leave-employee-filter__empty">
                  {hasEmployees ? "No matching employees." : "No employees for selected teams."}
                </p>
              )}
            </div>
          </div>
        )}
      </div>
    );
  }
}

export default LeaveEmployeeFilter;
