import React from 'react';
import { connect } from 'react-redux';
import { withRouter } from 'react-router-dom';
import { leavePhase2Service as api } from '_services/leavePhase2.service';
import { getApiErrorMessage } from '_helpers/apiError.utils';
import { AdminActionButton } from 'views/admin/components/AdminLuxShared';
import {
  LeavePhase2AdminBase,
  LeavePhase2Panel,
  LeavePhase2Register,
  LEAVE_PHASE2_EMPTY_DESCRIPTION,
  mapLeavePhase2State,
  cell,
} from './leavePhase2.shared';
import '../leaveLuxForms.css';

const EMPTY_PACK = { localeCode: 'en-US', countryCode: 'US' };

class LeaveLocalizationPage extends LeavePhase2AdminBase {
  state = {
    ...this.state,
    packs: [],
    translations: [],
    saving: false,
    packForm: { ...EMPTY_PACK },
  };

  fetchSectionData = async (teamId) => {
    const packs = (await api.listLocalePacks(teamId)) || [];
    const list = Array.isArray(packs) ? packs : [];
    let translations = [];
    if (list.length && list[0].policyId) {
      translations = (await api.listPolicyTranslations(null, list[0].policyId).catch(() => [])) || [];
    } else {
      translations = (await api.listPolicyTranslations().catch(() => [])) || [];
    }
    this.setState({
      packs: list,
      translations: Array.isArray(translations) ? translations : [],
    });
  };

  savePack = (event) => {
    event.preventDefault();
    const { packForm } = this.state;
    const localeCode = (packForm.localeCode || '').trim();
    if (!localeCode) return;
    const teamId = this.teamId();
    if (!teamId) {
      this.setState({ error: 'Select a team first.' });
      return;
    }
    this.setState({ saving: true, error: null, notice: null });
    api
      .saveLocalePack({
        userTeamId: teamId,
        actorId: this.actorId(),
        localeCode,
        countryCode: (packForm.countryCode || '').trim() || null,
        active: true,
      })
      .then(() => {
        this.setState({
          saving: false,
          notice: 'Locale pack saved.',
          packForm: { ...EMPTY_PACK },
        });
        return this.loadAll();
      })
      .catch((e) => {
        this.setState({
          saving: false,
          error: getApiErrorMessage(e, 'Could not save locale pack.'),
        });
      });
  };

  render() {
    const { loading, packs, translations, packForm, saving } = this.state;
    const kpiCards = [
      { id: 'packs', label: 'Locale packs', value: packs.length, tone: 'primary', icon: 'fe fe-globe' },
      { id: 'tr', label: 'Translations', value: translations.length, tone: 'blue', icon: 'fe fe-type' },
    ];

    return this.renderChrome({
      testId: 'page-leave-localization',
      kpiCards,
      pageMeta: {
        tone: 'emerald',
        icon: 'fe fe-globe',
        eyebrow: 'Admin · Leave',
        titleLead: 'Localization',
        titleAccent: '& calendars',
        lede: 'Locale packs for formats and labels. Missing packs fall back to English.',
      },
      children: (
        <>
          <LeavePhase2Panel title="Add locale pack" subtitle="Missing packs fall back to English labels.">
            <form className="lux-glp-form" onSubmit={this.savePack} data-testid="glp25-add-pack-form">
              <label>
                Locale code
                <input
                  required
                  value={packForm.localeCode}
                  onChange={(e) =>
                    this.setState({ packForm: { ...packForm, localeCode: e.target.value } })
                  }
                  placeholder="en-US"
                />
              </label>
              <label>
                Country code
                <input
                  value={packForm.countryCode}
                  onChange={(e) =>
                    this.setState({ packForm: { ...packForm, countryCode: e.target.value } })
                  }
                  placeholder="US"
                />
              </label>
              <div className="lux-glp-form__actions">
                <AdminActionButton type="submit" icon="fe fe-plus" disabled={saving || loading}>
                  Save pack
                </AdminActionButton>
              </div>
            </form>
          </LeavePhase2Panel>
          <LeavePhase2Panel
            title="Locale packs"
            subtitle="Country-specific formats — missing packs fall back to English labels."
          >
            {!loading && packs.length === 0 && (
              <p className="lux-leave-phase2-fallback-note" data-testid="glp25-english-fallback">
                No locale packs configured — employee leave labels currently use the English fallback.
              </p>
            )}
            <LeavePhase2Register
              loading={loading}
              rows={packs}
              testId="glp25-packs-register"
              emptyTitle="No locale packs"
              emptyDescription={LEAVE_PHASE2_EMPTY_DESCRIPTION}
              columns={[
                { key: 'id', label: 'ID' },
                { key: 'localeCode', label: 'Locale', render: (r) => cell(r.localeCode || r.locale) },
                { key: 'countryCode', label: 'Country' },
                { key: 'dateFormat', label: 'Date format' },
                { key: 'timezone', label: 'Timezone' },
              ]}
            />
          </LeavePhase2Panel>
          <LeavePhase2Panel title="Policy translations" subtitle="Localized leave type names and employee help.">
            <LeavePhase2Register
              loading={loading}
              rows={translations}
              testId="glp25-translations-register"
              emptyTitle="No translations"
              emptyDescription={LEAVE_PHASE2_EMPTY_DESCRIPTION}
              columns={[
                { key: 'id', label: 'ID' },
                { key: 'localeCode', label: 'Locale' },
                { key: 'fieldKey', label: 'Field' },
                { key: 'translatedText', label: 'Text', render: (r) => cell(r.translatedText || r.value) },
              ]}
            />
          </LeavePhase2Panel>
        </>
      ),
    });
  }
}

export default connect(mapLeavePhase2State)(withRouter(LeaveLocalizationPage));
