import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isDeveloperPortalEnabled } from "config/developer-portal.config";
import { MARKETPLACE_PAGE_META } from "config/developer-portal-nav.config";
import { developerPortalService } from "_services/developerPortal.service";
import DeveloperLuxPage, {
  DeveloperActionButton,
  DeveloperInsightPanel,
} from "views/developer/components/DeveloperLuxShared";
import MarketplaceCatalogPanel from "views/developer/components/MarketplaceCatalogPanel";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

class MarketplacePage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    listings: [],
    kpiCards: [],
    insights: [],
    categoryFilter: "ALL",
    busy: false,
  };

  componentDidMount() {
    this.loadData();
  }

  loadData = async () => {
    const { categoryFilter } = this.state;
    this.setState({ loading: true, loadError: null });
    try {
      const filters = categoryFilter !== "ALL" ? { category: categoryFilter } : {};
      const result = await developerPortalService.getOverview(filters);
      const payload = result.payload || {};
      this.setState({
        loading: false,
        dataSource: result.source,
        listings: payload.listings || [],
        kpiCards: payload.kpiCards || [],
        insights: payload.insights || [],
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load marketplace.",
      });
    }
  };

  handleInstall = async (listing) => {
    this.setState({ busy: true });
    try {
      await developerPortalService.installMarketplaceListing(listing.id);
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to install listing." });
    } finally {
      this.setState({ busy: false });
    }
  };

  render() {
    if (!isDeveloperPortalEnabled()) {
      return <PersonaAccessDenied featureLabel="Connector marketplace" />;
    }

    const { loading, loadError, dataSource, listings, kpiCards, insights, categoryFilter, busy } = this.state;

    return (
      <DeveloperLuxPage
        pageMeta={MARKETPLACE_PAGE_META}
        shellTitle="Connector marketplace"
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        moduleClass="lux-dev-module lux-mkt-module"
        heroActions={
          <>
            <DeveloperActionButton icon="fe fe-refresh-cw" onClick={this.loadData} disabled={loading}>
              Refresh
            </DeveloperActionButton>
            <DeveloperActionButton to="/integrations/hub" icon="fe fe-link">
              Integration hub
            </DeveloperActionButton>
            <DeveloperActionButton to="/admin/developer" icon="fe fe-code" variant="primary">
              Developer portal
            </DeveloperActionButton>
          </>
        }
      >
        {loadError ? <LuxInlineAlert message={loadError} /> : null}
        <DeveloperInsightPanel insights={insights} loading={loading} />
        <div className="lux-dev-filter-row">
          <label htmlFor="marketplace-category">Category</label>
          <select
            id="marketplace-category"
            className="lux-dev-filter"
            value={categoryFilter}
            onChange={(e) => this.setState({ categoryFilter: e.target.value }, this.loadData)}
          >
            <option value="ALL">All categories</option>
            <option value="Collaboration">Collaboration</option>
            <option value="DevOps">DevOps</option>
            <option value="CRM">CRM</option>
            <option value="HR">HR</option>
            <option value="Developer">Developer</option>
          </select>
        </div>
        <MarketplaceCatalogPanel
          listings={listings}
          loading={loading}
          onInstall={this.handleInstall}
          busy={busy}
        />
      </DeveloperLuxPage>
    );
  }
}

export default MarketplacePage;
