import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import LuxSummaryEyebrow from "views/common/fragments/LuxSummaryEyebrow";
import { commonUtils } from "_helpers";
import Skeleton, { SkeletonTheme } from "react-loading-skeleton";
import CountUp from "react-countup";
import DashboardApexChart from "views/hrms/components/dashboard/DashboardApexChart";
import BidPipelineFunnelDiagram from "views/sales/components/fragments/BidPipelineFunnelDiagram";
import {
  buildPoStatusDonutChart,
  buildPoOutcomeDonutChart,
  buildPoProjectTypeBarChart,
  buildPoAccountBarChart,
  buildPoSourceDonutChart,
  buildPoTimelineHealthDonutChart,
  buildPoBidLinkDonutChart,
  buildPoFunnelBarChart,
  buildPoCreatedTrendAreaChart,
  buildPoTeamBarChart,
} from "./purchaseOrderSummary.charts";
import {
  readSummaryExpanded,
  writeSummaryExpanded,
  getSummaryToggleLabel,
} from "_helpers/summaryExpandedStorage";

const SUMMARY_STORAGE_KEY = "famstack-purchase-orders-summary-expanded";

const QUICK_FILTERS = [
  { value: "ALL", label: "All" },
  { value: "ACTIVE", label: "Active" },
  { value: "NEW", label: "New" },
  { value: "CREATED", label: "Created" },
  { value: "INPROGRESS", label: "In progress" },
  { value: "COMPLETED", label: "Completed" },
  { value: "CLOSED", label: "Closed" },
  { value: "DELETED", label: "Deleted" },
  { value: "ARCHIVED", label: "Archived" },
];

class PurchaseOrderPageSummary extends PureComponent {
  constructor(props) {
    super(props);
    this.state = { expanded: readSummaryExpanded(SUMMARY_STORAGE_KEY) };
  }

  toggleExpanded = () => {
    this.setState(
      (prev) => ({ expanded: !prev.expanded }),
      () => {
        writeSummaryExpanded(SUMMARY_STORAGE_KEY, this.state.expanded);
      }
    );
  };

  getShowFilter = () => {
    const options = this.props.filterOptions;
    return (options && options.SHOW && options.SHOW.selected) || "ACTIVE";
  };

  quickFilter = (value) => {
    if (this.props.onQuickFilter) {
      this.props.onQuickFilter(value);
    }
  };

  getCharts = (stat) => ({
    statusDonut: buildPoStatusDonutChart(stat),
    outcomeDonut: buildPoOutcomeDonutChart(stat),
    projectTypeBar: buildPoProjectTypeBarChart(stat),
    accountBar: buildPoAccountBarChart(stat),
    sourceDonut: buildPoSourceDonutChart(stat),
    timelineDonut: buildPoTimelineHealthDonutChart(stat),
    bidLinkDonut: buildPoBidLinkDonutChart(stat),
    funnelBar: buildPoFunnelBarChart(stat),
    createdTrend: buildPoCreatedTrendAreaChart(stat),
    teamBar: buildPoTeamBarChart(stat),
  });

  renderFilterChips = (showFilter, compact) => (
    <div
      className={classNames("lux-bid-summary__filters", {
        "lux-bid-summary__filters--compact": compact,
      })}
      role="group"
      aria-label="Filter contracts by status"
    >
      {QUICK_FILTERS.map((option) => (
        <button
          key={option.value}
          type="button"
          className={classNames("lux-bid-summary__filter-chip", {
            "is-active":
              option.value === "INPROGRESS"
                ? commonUtils.isBidInProgressFilterSelected(showFilter)
                : showFilter === option.value,
          })}
          onClick={() => this.quickFilter(option.value)}
        >
          {option.label}
        </button>
      ))}
    </div>
  );

  buildContextLine = (stat, visibleCount, filterOptions) => {
    const parts = [];
    parts.push(
      stat.selectedTeams > 0
        ? `${stat.selectedTeams} team${stat.selectedTeams === 1 ? "" : "s"} selected`
        : "All teams"
    );
    if (visibleCount !== stat.total) {
      parts.push(`${visibleCount} of ${stat.total} shown`);
    }
    if (filterOptions && filterOptions.filterText) {
      parts.push(`matching “${filterOptions.filterText}”`);
    }
    if (stat.salesforceCount > 0) {
      parts.push(`${stat.salesforceCount} from Salesforce`);
    }
    return parts.join(" · ");
  };

  renderKpiStrip = (stat) => (
    <div className="lux-bid-summary__kpi-strip" role="list" aria-label="Contract portfolio metrics">
      {stat.kpis.map((kpi) => (
        <article
          key={kpi.key}
          className={classNames("lux-bid-summary__kpi", kpi.tone && `is-${kpi.tone}`)}
          role="listitem"
        >
          <div className="lux-bid-summary__kpi-top">
            <span className="lux-bid-summary__kpi-label">{kpi.label}</span>
            <span className="lux-bid-summary__kpi-icon" aria-hidden="true">
              <i className={kpi.icon} />
            </span>
          </div>
          <strong className="lux-bid-summary__kpi-value">
            <CountUp end={kpi.value} duration={0.85} />
          </strong>
          {kpi.hint && <span className="lux-bid-summary__kpi-hint">{kpi.hint}</span>}
        </article>
      ))}
    </div>
  );

  renderRateChips = (stat) => (
    <div className="lux-po-summary__rate-chips">
      <div
        className="lux-bid-summary__win-chip lux-po-summary__completion-chip"
        title="Share of active contracts marked completed"
      >
        <div
          className="lux-bid-summary__rate-ring"
          style={{ "--lux-win-pct": `${stat.completionRate}%` }}
          aria-hidden="true"
        >
          <span>
            <CountUp end={stat.completionRate} duration={0.8} />%
          </span>
        </div>
        <div className="lux-bid-summary__win-chip-copy">
          <strong>Completion</strong>
          <span>
            {stat.completed} done · {stat.pipeline} open
          </span>
        </div>
      </div>
      <div
        className="lux-bid-summary__win-chip lux-po-summary__pipeline-chip"
        title="Contracts in New, Created, or In progress"
      >
        <div
          className="lux-bid-summary__rate-ring is-pipeline"
          style={{ "--lux-win-pct": `${stat.pipelineRate}%` }}
          aria-hidden="true"
        >
          <span>
            <CountUp end={stat.pipelineRate} duration={0.8} />%
          </span>
        </div>
        <div className="lux-bid-summary__win-chip-copy">
          <strong>Pipeline load</strong>
          <span>{stat.pipeline} in delivery funnel</span>
        </div>
      </div>
    </div>
  );

  renderHighlights = (stat) => (
    <div className="lux-po-summary__highlights" role="list" aria-label="Portfolio highlights">
      {stat.highlights.map((item) => (
        <article
          key={item.key}
          className={classNames("lux-po-summary__highlight", item.tone && `is-${item.tone}`)}
          role="listitem"
        >
          <span className="lux-po-summary__highlight-icon" aria-hidden="true">
            <i className={item.icon} />
          </span>
          <div className="lux-po-summary__highlight-copy">
            <span className="lux-po-summary__highlight-label">{item.label}</span>
            <strong>
              <CountUp end={item.value} duration={0.75} />
            </strong>
            <span className="lux-po-summary__highlight-hint">{item.hint}</span>
          </div>
        </article>
      ))}
    </div>
  );

  renderInsightCard = (insight) => (
    <article key={insight.key} className="lux-bid-summary__insight lux-po-summary__insight">
      <header>
        <i className={insight.icon} aria-hidden="true" />
        <div>
          <strong>{insight.title}</strong>
          <span>{insight.subtitle}</span>
        </div>
      </header>
      {!insight.mix || !insight.mix.length ? (
        <div className="lux-bid-summary__bar lux-bid-summary__bar--empty">{insight.emptyLabel}</div>
      ) : (
        <>
          <div className="lux-bid-summary__bar" aria-hidden="true">
            {insight.mix.map((seg) => (
              <span
                key={seg.key}
                className={classNames("lux-bid-summary__bar-segment", `is-${seg.tone}`)}
                style={{ flexGrow: Math.max(seg.count, 0.15) }}
                title={`${seg.label}: ${seg.count}`}
              />
            ))}
          </div>
          <ul className="lux-bid-summary__legend">
            {insight.mix.map((seg) => (
              <li key={seg.key}>
                <span className={classNames("lux-bid-summary__legend-dot", `is-${seg.tone}`)} />
                <span>{seg.label}</span>
                <strong>{seg.count}</strong>
                <em>{seg.pct}%</em>
              </li>
            ))}
          </ul>
        </>
      )}
    </article>
  );

  renderStageFlow = (stat) => (
    <div className="lux-bid-summary__stage-flow" aria-label="Contract lifecycle stages">
      {[
        { key: "new", label: "New", count: stat.stageCounts.newCount, tone: "sky" },
        { key: "created", label: "Created", count: stat.stageCounts.createdCount, tone: "indigo" },
        {
          key: "progress",
          label: "In progress",
          count: stat.stageCounts.inProgressCount,
          tone: "amber",
        },
        {
          key: "completed",
          label: "Completed",
          count: stat.stageCounts.completedCount,
          tone: "green",
        },
      ].map((stage, index, arr) => (
        <React.Fragment key={stage.key}>
          <div className={classNames("lux-bid-summary__stage-node", `is-${stage.tone}`)}>
            <span className="lux-bid-summary__stage-node-label">{stage.label}</span>
            <strong>
              <CountUp end={stage.count} duration={0.7} />
            </strong>
          </div>
          {index < arr.length - 1 && (
            <span className="lux-bid-summary__stage-arrow" aria-hidden="true">
              <i className="fe fe-arrow-right" />
            </span>
          )}
        </React.Fragment>
      ))}
    </div>
  );

  renderChartPanel = (
    title,
    subtitle,
    chart,
    emptyMessage,
    { height = 168, wide = false, chartType = "donut", compactHead = false } = {}
  ) => (
    <article
      className={classNames("lux-bid-summary__chart-panel", {
        "lux-bid-summary__chart-panel--wide": wide,
        "lux-bid-summary__chart-panel--compact": compactHead,
      })}
    >
      <div className="lux-bid-summary__panel-head">
        <div>
          <h3 className="lux-bid-summary__panel-title">{title}</h3>
          {!compactHead && subtitle && (
            <p className="lux-bid-summary__panel-sub">{subtitle}</p>
          )}
        </div>
      </div>
      <div className="lux-bid-summary__chart-body">
        {!chart && <p className="lux-bid-summary__chart-empty">{emptyMessage}</p>}
        {chart && (
          <DashboardApexChart
            type={chartType}
            series={chart.series}
            options={chart.options}
            height={height}
          />
        )}
      </div>
    </article>
  );

  renderSkeleton = () => (
    <SkeletonTheme baseColor="#f1f5f9" highlightColor="#e2e8f0">
      <div className="lux-bid-summary is-loading">
        <Skeleton height={88} borderRadius={16} />
        <div className="lux-bid-summary__kpi-strip lux-bid-summary__kpi-strip--skeleton">
          {[1, 2, 3, 4].map((key) => (
            <Skeleton key={key} height={72} borderRadius={14} />
          ))}
        </div>
        <div className="lux-bid-summary__insights lux-bid-summary__charts--skeleton">
          {[1, 2, 3].map((key) => (
            <Skeleton key={key} height={120} borderRadius={12} />
          ))}
        </div>
        <div className="lux-po-summary__analytics lux-bid-summary__charts--skeleton">
          {[1, 2, 3, 4, 5, 6, 7, 8].map((key) => (
            <Skeleton key={key} height={140} borderRadius={12} />
          ))}
        </div>
      </div>
    </SkeletonTheme>
  );

  render() {
    const { stat, isLoading, visibleCount, filterOptions } = this.props;
    const { expanded } = this.state;

    if (isLoading && (!stat || stat.total === 0)) {
      return this.renderSkeleton();
    }

    const showFilter = this.getShowFilter();
    const charts = this.getCharts(stat);

    return (
      <section
        className={classNames("lux-bid-summary lux-po-summary", { "is-collapsed": !expanded })}
        aria-label="Purchase contract overview"
      >
        <div className="lux-bid-summary__header-bar">
          <div className="lux-bid-summary__header-main">
            <LuxSummaryEyebrow variant="purchase-contracts" className="lux-bid-summary__eyebrow">
              Contract portfolio intelligence
            </LuxSummaryEyebrow>
            {!expanded ? (
              <h2 className="lux-bid-summary__title lux-bid-summary__title--compact">
                <CountUp end={stat.total} duration={0.9} />{" "}
                <span>
                  contracts · {stat.stageCounts.inProgressCount} in progress ·{" "}
                  {stat.completionRate}% complete · {stat.overdueCount} overdue
                </span>
              </h2>
            ) : (
              <h2 className="lux-bid-summary__title lux-bid-summary__title--bar">
                Purchase contract overview
              </h2>
            )}
          </div>
          <button
            type="button"
            className="lux-bid-summary__toggle"
            onClick={this.toggleExpanded}
            aria-expanded={expanded}
            aria-controls="lux-po-summary-body"
          >
            <span>{getSummaryToggleLabel(expanded)}</span>
            <i
              className={classNames("fe", expanded ? "fe-chevron-up" : "fe-chevron-down")}
              aria-hidden="true"
            />
          </button>
        </div>

        {!expanded && (
          <div className="lux-bid-summary__collapsed-strip">
            <p className="lux-bid-summary__collapsed-line">
              {this.buildContextLine(stat, visibleCount, filterOptions)}
            </p>
            {this.renderFilterChips(showFilter, true)}
          </div>
        )}

        <div id="lux-po-summary-body" className="lux-bid-summary__body" aria-hidden={!expanded}>
          <div className="lux-bid-summary__toolbar">
            <p className="lux-bid-summary__subtitle">
              {this.buildContextLine(stat, visibleCount, filterOptions)}
            </p>
            {this.renderFilterChips(showFilter, false)}
          </div>

          <div className="lux-bid-summary__metrics-row lux-po-summary__metrics-row">
            {this.renderKpiStrip(stat)}
            {this.renderRateChips(stat)}
          </div>

          {this.renderHighlights(stat)}

          <div className="lux-bid-summary__insights lux-po-summary__insights">
            {stat.insights.map(this.renderInsightCard)}
          </div>

          {this.renderStageFlow(stat)}

          <div className="lux-po-summary__analytics lux-po-summary__analytics--primary">
            <article className="lux-bid-summary__chart-panel lux-bid-summary__chart-panel--funnel lux-bid-summary__chart-panel--funnel-compact">
              <div className="lux-bid-summary__panel-head">
                <h3 className="lux-bid-summary__panel-title">Delivery funnel</h3>
                <p className="lux-bid-summary__panel-sub">Stage progression for active contracts</p>
              </div>
              <BidPipelineFunnelDiagram
                funnel={stat.funnel}
                totalActive={stat.active}
                layout="horizontal"
              />
            </article>

            {this.renderChartPanel(
              "By status",
              "Active contracts only",
              charts.statusDonut,
              "No status data yet",
              { height: 168, compactHead: true }
            )}
            {this.renderChartPanel(
              "Portfolio mix",
              "Pipeline vs completed vs archived",
              charts.outcomeDonut,
              "No outcome data yet",
              { height: 168, compactHead: true }
            )}
            {this.renderChartPanel(
              "Delivery health",
              "Open contracts by due date",
              charts.timelineDonut,
              "No open delivery dates",
              { height: 168, compactHead: true }
            )}
          </div>

          <div className="lux-po-summary__analytics lux-po-summary__analytics--secondary">
            {this.renderChartPanel(
              "Creation trend",
              "New contracts over the last 6 months",
              charts.createdTrend,
              "No contracts created in this period",
              { height: 176, chartType: "area", wide: true, compactHead: true }
            )}
            {this.renderChartPanel(
              "Project types",
              "Distribution by contract type",
              charts.projectTypeBar,
              "No project type data",
              { height: 168, chartType: "bar", compactHead: true }
            )}
            {this.renderChartPanel(
              "Creation channel",
              "Salesforce vs manual entry",
              charts.sourceDonut,
              "No channel data",
              { height: 168, compactHead: true }
            )}
            {this.renderChartPanel(
              "Bid linkage",
              "Contracts tied to a bid request",
              charts.bidLinkDonut,
              "No linkage data",
              { height: 168, compactHead: true }
            )}
            {this.renderChartPanel(
              "Funnel volume",
              "Count at each delivery stage",
              charts.funnelBar,
              "No funnel data",
              { height: 168, chartType: "bar", compactHead: true }
            )}
            {this.renderChartPanel(
              "Top accounts",
              "Most active client accounts",
              charts.accountBar,
              "No account data yet",
              { height: 168, chartType: "bar", compactHead: true }
            )}
            {this.renderChartPanel(
              "By team",
              "Contracts per delivery team",
              charts.teamBar,
              "No team breakdown",
              { height: 168, chartType: "bar", compactHead: true }
            )}
          </div>
        </div>
      </section>
    );
  }
}

export default PurchaseOrderPageSummary;
