import React, { Component } from "react";
import classNames from "classnames/bind";
import {
  getModuleSections,
  getPersonaMeta,
  getRoleCoverageStats,
} from "config/role-permission.utils";
import { AdminActionButton } from "views/admin/components/AdminLuxShared";
import PersonaAccessEditor from "views/admin/components/PersonaAccessEditor";

export default class RolePermissionDetailPanel extends Component {
  state = {
    matrixExpanded: false,
    syncedRoleId: null,
  };

  static getDerivedStateFromProps(props, state) {
    const roleId = props.role && props.role.id;
    if (roleId !== state.syncedRoleId) {
      return {
        syncedRoleId: roleId,
        matrixExpanded: false,
      };
    }
    return null;
  }

  toggleMatrix = () => {
    this.setState((prev) => ({ matrixExpanded: !prev.matrixExpanded }));
  };

  render() {
    const {
      role,
      savingKey,
      onToggle,
      onSetStatus,
      readOnly,
      pageMap,
      pageMapRevision,
      catalogPages,
      onSavePersonaAccess,
    } = this.props;
    if (!role) {
      return (
        <div className="lux-rbac-detail lux-rbac-detail--empty">
          <span className="lux-rbac-detail__empty-orb" aria-hidden="true" />
          <span className="lux-rbac-detail__empty-icon" aria-hidden="true">
            <i className="fe fe-shield" />
          </span>
          <strong>Select a role</strong>
          <p>Choose a profile on the left to shape persona access and capabilities.</p>
        </div>
      );
    }

    const sections = getModuleSections(role);
    const personaMeta = getPersonaMeta(role.persona);
    const coverage = getRoleCoverageStats(role);
    const isInactive = role.status === "Inactive";
    const isReadOnly = readOnly === true || !onToggle;
    const isSavingPersonas =
      savingKey === "personaModules" || savingKey === "personaAccess";
    const { matrixExpanded } = this.state;

    return (
      <aside className="lux-rbac-detail lux-rbac-detail--atelier">
        <header
          className={classNames(
            "lux-rbac-detail__hero",
            personaMeta.tone && `is-${personaMeta.tone}`
          )}
        >
          <div className="lux-rbac-detail__hero-glow" aria-hidden="true" />
          <div className="lux-rbac-detail__identity">
            <span
              className={classNames(
                "lux-rbac-detail__avatar",
                personaMeta.tone && `is-${personaMeta.tone}`
              )}
              aria-hidden="true"
            >
              <i className={personaMeta.icon} />
            </span>
            <div className="lux-rbac-detail__identity-copy">
              <p className="lux-rbac-detail__eyebrow">Editing profile</p>
              <div className="lux-rbac-detail__title-row">
                <h3>{role.name}</h3>
                <span
                  className={classNames("lux-rbac-detail__status-pill", {
                    "is-active": !isInactive,
                    "is-inactive": isInactive,
                  })}
                >
                  {role.status}
                </span>
              </div>
              <p className="lux-rbac-detail__identity-meta">
                <code>{role.code}</code>
                <span
                  className={classNames(
                    "lux-rbac-detail__persona-chip",
                    personaMeta.tone && `is-${personaMeta.tone}`
                  )}
                >
                  <i className={personaMeta.icon} aria-hidden="true" />
                  {personaMeta.label}
                </span>
              </p>
              {role.description ? (
                <p className="lux-rbac-detail__desc">{role.description}</p>
              ) : null}
            </div>
          </div>
          {!isReadOnly ? (
            <AdminActionButton
              variant="ghost"
              className="lux-onb-action--sm lux-rbac-detail__status-btn"
              icon={isInactive ? "fe fe-check-circle" : "fe fe-pause-circle"}
              onClick={() => onSetStatus && onSetStatus(isInactive ? "Active" : "Inactive")}
            >
              Mark {isInactive ? "active" : "inactive"}
            </AdminActionButton>
          ) : null}
        </header>

        <div className="lux-rbac-detail__pulse" role="list" aria-label="Role health">
          <article className="lux-rbac-detail__pulse-card is-coverage" role="listitem">
            <div
              className="lux-rbac-detail__pulse-ring"
              style={{ "--rbac-pulse": `${Math.max(coverage.coverage, 6)}%` }}
              aria-hidden="true"
            >
              <strong>{coverage.coverage}%</strong>
            </div>
            <div className="lux-rbac-detail__pulse-copy">
              <span>Coverage</span>
              <em>
                {coverage.enabled} of {coverage.total} flags
              </em>
            </div>
          </article>
          <article className="lux-rbac-detail__pulse-card is-users" role="listitem">
            <strong>{role.userCount || 0}</strong>
            <span>Users mapped</span>
          </article>
          <article className="lux-rbac-detail__pulse-card is-modules" role="listitem">
            <strong>{sections.length}</strong>
            <span>Module groups</span>
          </article>
        </div>

        <PersonaAccessEditor
          role={role}
          pageMap={pageMap}
          pageMapRevision={pageMapRevision}
          pages={catalogPages}
          readOnly={isReadOnly}
          saving={isSavingPersonas}
          onSave={onSavePersonaAccess}
        />

        <section
          className={classNames("lux-rbac-advanced", { "is-open": matrixExpanded })}
          data-testid="role-permission-matrix-advanced"
        >
          <button
            type="button"
            className="lux-rbac-advanced__toggle"
            onClick={this.toggleMatrix}
            aria-expanded={matrixExpanded}
          >
            <span className="lux-rbac-advanced__toggle-main">
              <span className="lux-rbac-advanced__toggle-icon" aria-hidden="true">
                <i className="fe fe-sliders" />
              </span>
              <span>
                <strong>Advanced · module capabilities</strong>
                <em>
                  {coverage.enabled}/{coverage.total} flags · {sections.length} groups
                </em>
              </span>
            </span>
            <span className="lux-rbac-advanced__toggle-state">
              {matrixExpanded ? "Hide" : "Show"}
              <i
                className={`fe fe-chevron-${matrixExpanded ? "up" : "down"}`}
                aria-hidden="true"
              />
            </span>
          </button>

          {matrixExpanded ? (
            <div
              className={classNames("lux-rbac-detail__matrix lux-rbac-advanced__body", {
                "lux-rbac-detail__matrix--dense": sections.length > 2,
              })}
            >
              <p className="lux-rbac-advanced__hint">
                Turn on a module flag when a page is allowed for a persona but still blocked.
              </p>
              {sections.map((section) => (
                <section
                  key={section.moduleKey}
                  className={classNames(
                    "lux-rbac-matrix-card",
                    section.meta.tone && `is-${section.meta.tone}`
                  )}
                >
                  <header className="lux-rbac-matrix-card__head">
                    <div className="lux-rbac-matrix-card__title">
                      <span className="lux-rbac-matrix-card__icon" aria-hidden="true">
                        <i className={section.meta.icon} />
                      </span>
                      <div>
                        <strong>{section.meta.label}</strong>
                        <span>
                          {section.enabledCount}/{section.totalCount} enabled
                        </span>
                      </div>
                    </div>
                    <div className="lux-rbac-matrix-card__coverage" aria-hidden="true">
                      <span style={{ width: `${Math.max(section.coverage, 8)}%` }} />
                    </div>
                  </header>

                  <ul className="lux-rbac-matrix-card__flags" role="list">
                    {section.flags.map((flag) => {
                      const key = `${section.moduleKey}:${flag.flagKey}`;
                      const isSaving = savingKey === key;
                      return (
                        <li
                          key={key}
                          className={classNames("lux-rbac-matrix-card__flag", {
                            "is-enabled": flag.enabled,
                            "is-saving": isSaving,
                          })}
                          role="listitem"
                        >
                          <div className="lux-rbac-matrix-card__flag-copy">
                            <strong>{flag.label || flag.flagKey}</strong>
                            <span>{flag.flagKey}</span>
                          </div>
                          <label className="custom-switch custom-switch-sm m-0 lux-rbac-matrix-card__switch">
                            <input
                              type="checkbox"
                              className="custom-switch-input"
                              checked={flag.enabled}
                              disabled={isReadOnly || isSaving}
                              readOnly={isReadOnly}
                              onChange={(e) =>
                                !isReadOnly &&
                                onToggle &&
                                onToggle(section.moduleKey, flag.flagKey, e.target.checked)
                              }
                            />
                            <span className="custom-switch-indicator" />
                          </label>
                        </li>
                      );
                    })}
                  </ul>
                </section>
              ))}
            </div>
          ) : null}
        </section>
      </aside>
    );
  }
}
