import React, { Component } from "react";
import classNames from "classnames/bind";
import { formatTimesheetWeekRange } from "./timesheetApproval.utils";
import { getTimesheetStatusMeta, normalizeTimesheetStatus } from "./timesheetSummary.utils";

const COMPLIANCE_COLLAPSED_KEY = "famstack-timesheet-compliance-collapsed";

function readCollapsedPreference() {
  try {
    return localStorage.getItem(COMPLIANCE_COLLAPSED_KEY) === "1";
  } catch (error) {
    return false;
  }
}

function writeCollapsedPreference(collapsed) {
  try {
    localStorage.setItem(COMPLIANCE_COLLAPSED_KEY, collapsed ? "1" : "0");
  } catch (error) {
    /* ignore quota / private mode */
  }
}

class TimesheetCompliancePanel extends Component {
  constructor(props) {
    super(props);
    this.state = { collapsed: readCollapsedPreference() };
  }

  toggleCollapsed = () => {
    this.setState((prevState) => {
      const collapsed = !prevState.collapsed;
      writeCollapsedPreference(collapsed);
      return { collapsed };
    });
  };

  renderStatus = (status) => {
    const normalized = normalizeTimesheetStatus(status === "NOT_SUBMITTED" ? "NOT_STARTED" : status);
    const meta = getTimesheetStatusMeta(normalized || status);
    return (
      <span className={classNames("lux-ts-compliance__status", meta.tone && `is-${meta.tone}`)}>
        <i className={`fe ${meta.icon}`} aria-hidden="true" />
        {meta.label}
      </span>
    );
  };

  render() {
    const { defaulters, weekLabel, isLoading, onLockPayroll, lockInProgress, canLockPayroll } =
      this.props;
    const { collapsed } = this.state;
    const rows = defaulters || [];
    const hasIssues = rows.length > 0;
    const issueLabel = `${rows.length} compliance issue${rows.length === 1 ? "" : "s"}`;

    if (!rows.length && !isLoading && !canLockPayroll) {
      return null;
    }

    if (collapsed) {
      return (
        <section
          className={classNames("lux-ts-compliance", "lux-ts-compliance--collapsed", {
            "is-warning": hasIssues,
            "is-ok": !hasIssues && !isLoading,
          })}
          aria-label="Timesheet compliance"
        >
          <button
            type="button"
            className="lux-ts-compliance__collapsed-bar"
            onClick={this.toggleCollapsed}
            aria-expanded="false"
          >
            <span className="lux-ts-compliance__collapsed-icon" aria-hidden="true">
              <i className={hasIssues ? "fe fe-alert-triangle" : "fe fe-check-circle"} />
            </span>
            <span className="lux-ts-compliance__collapsed-copy">
              <strong>
                {isLoading
                  ? "Checking timesheet compliance…"
                  : hasIssues
                    ? issueLabel
                    : "Timesheet compliance clear"}
              </strong>
              <em>
                {hasIssues
                  ? `${weekLabel || "Selected week"} · action required before payroll lock`
                  : weekLabel || "Selected week"}
              </em>
            </span>
            {hasIssues ? <span className="lux-ts-compliance__count">{rows.length}</span> : null}
            <span className="lux-ts-compliance__collapsed-expand">
              Expand
              <i className="fe fe-chevron-down" aria-hidden="true" />
            </span>
          </button>
        </section>
      );
    }

    return (
      <section
        className={classNames("lux-ts-compliance", {
          "is-warning": hasIssues,
          "is-ok": !hasIssues && !isLoading,
        })}
        aria-label="Timesheet compliance"
        role={hasIssues ? "status" : undefined}
      >
        <header className="lux-ts-compliance__head">
          <div>
            <span className="lux-ts-compliance__eyebrow">
              {hasIssues ? "Compliance warning" : "Compliance"}
            </span>
            <h3>Timesheet defaulters</h3>
            <p>
              {isLoading
                ? "Loading compliance data…"
                : hasIssues
                  ? `${issueLabel} for ${weekLabel || "this week"} — employees still need to submit or correct timesheets.`
                  : `All employees are compliant for ${weekLabel || "this week"}.`}
            </p>
          </div>
          <div className="lux-ts-compliance__head-actions">
            {canLockPayroll && onLockPayroll && (
              <button
                type="button"
                className={classNames("lux-ts-compliance__lock-btn", { "is-loading": lockInProgress })}
                disabled={lockInProgress || isLoading}
                onClick={onLockPayroll}
              >
                Lock approved for payroll
              </button>
            )}
            <button
              type="button"
              className="lux-ts-compliance__toggle"
              onClick={this.toggleCollapsed}
              aria-expanded="true"
              aria-label="Collapse compliance panel"
            >
              <i className="fe fe-chevron-up" aria-hidden="true" />
            </button>
          </div>
        </header>

        {isLoading ? (
          <p className="lux-ts-compliance__empty">Loading compliance data…</p>
        ) : null}

        {!isLoading && !rows.length ? (
          <p className="lux-ts-compliance__empty">No defaulters for this week.</p>
        ) : null}

        {!isLoading && rows.length > 0 && (
          <ul className="lux-ts-compliance__list">
            {rows.map((row) => (
              <li
                key={`${row.employeeId}-${row.weekStartDate || weekLabel}`}
                className="lux-ts-compliance__row"
              >
                <div>
                  <strong>{row.employeeName || `Employee #${row.employeeId}`}</strong>
                  <span>{row.reason || "Action required"}</span>
                  {row.weekStartDate && <em>{formatTimesheetWeekRange(row)}</em>}
                </div>
                {this.renderStatus(row.status)}
              </li>
            ))}
          </ul>
        )}
      </section>
    );
  }
}

export default TimesheetCompliancePanel;
