import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { ADMIN_PAGE_META } from "config/admin-page-meta.config";
import { isAdminInsightsEnabled } from "config/admin-insights.config";
import {
  buildAdminInsightsChartBundle,
  buildAdminInsightsInsights,
  buildAdminInsightsMetrics,
} from "config/admin-insights.utils";
import { adminInsightsService } from "_services/adminInsights.service";
import { recordAuditEvent } from "config/audit-write.service";
import { AUDIT_ACTION_TYPES, AUDIT_ENTITY_TYPES } from "_constants/audit.constants";
import PolicyAnalyticsBarChart from "views/people/components/policy/PolicyAnalyticsBarChart";
import {
  AdminActionButton,
  AdminInsightStrip,
  AdminPanelHead,
  AdminPanelLink,
  AdminLuxPage,
} from "views/admin/components/AdminLuxShared";

class AdminInsightsPage extends Component {
  state = {
    snapshot: null,
    loading: true,
    loadError: null,
    dataSource: null,
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Admin insights");
    this.loadDashboard();
    recordAuditEvent({
      actionType: AUDIT_ACTION_TYPES.AUDIT_VIEWED,
      entityType: AUDIT_ENTITY_TYPES.ADMIN_CONFIG,
      entityRef: "Admin insights",
      correlationId: `admin-insights-view-${new Date().toISOString().slice(0, 10)}`,
      metadata: {
        route: "/admin/insights",
      },
    });
  }

  loadDashboard = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await adminInsightsService.getDashboard();
      this.setState({
        snapshot: result.payload || {},
        loading: false,
        dataSource: result.source || null,
      });
    } catch (e) {
      this.setState({
        loading: false,
        loadError: "Unable to load governance insights.",
        snapshot: null,
      });
    }
  };

  render() {
    if (!isAdminInsightsEnabled()) {
      return (
        <PersonaAccessDenied
          moduleName="Admin insights"
          reason="Governance insights dashboard is not enabled for your organization."
        />
      );
    }

    const { loading, loadError, dataSource, snapshot } = this.state;
    const metrics = buildAdminInsightsMetrics(snapshot || {});
    const insights = loading ? [] : buildAdminInsightsInsights(snapshot || {});
    const charts = loading ? {} : buildAdminInsightsChartBundle(snapshot || {});

    const kpiCards = [
      {
        id: "audit",
        label: "Audit events",
        value: metrics.auditTotal.toLocaleString(),
        hint: `${metrics.auditRecent24h} in last 24h`,
        tone: "violet",
        icon: "fe fe-shield",
      },
      {
        id: "denials",
        label: "Access denials",
        value: metrics.accessDenials,
        hint: "Rejected approvals + requests",
        tone: metrics.accessDenials ? "rose" : "slate",
        icon: "fe fe-slash",
      },
      {
        id: "compliance",
        label: "Compliance ready",
        value: `${metrics.complianceReadinessPct}%`,
        hint: `${metrics.readySections}/${metrics.totalSections} sections`,
        tone: "green",
        icon: "fe fe-check-circle",
      },
      {
        id: "adoption",
        label: "Flag adoption",
        value: `${metrics.flagAdoptionAvg}%`,
        hint: `${metrics.enabledFlags} flags enabled`,
        tone: "blue",
        icon: "fe fe-toggle-right",
      },
    ];

    const hasCharts =
      (charts.auditVolume && charts.auditVolume.length > 0) ||
      (charts.accessDenials && charts.accessDenials.length > 0) ||
      (charts.sensitiveFieldAccess && charts.sensitiveFieldAccess.length > 0) ||
      (charts.complianceReadiness && charts.complianceReadiness.length > 0) ||
      (charts.featureAdoption && charts.featureAdoption.length > 0);

    return (
      <AdminLuxPage
        pageMeta={ADMIN_PAGE_META.insights}
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        testId="page-admin-insights"
        className="lux-register-page lux-admin-insights-page"
        heroActions={
          <>
            <AdminActionButton icon="fe fe-refresh-cw" onClick={this.loadDashboard} disabled={loading}>
              Refresh
            </AdminActionButton>
            <AdminActionButton to="/admin/audit" icon="fe fe-activity" variant="ghost">
              Audit trail
            </AdminActionButton>
          </>
        }
      >
        {loadError && (
          <div className="lux-employee-360__error lux-admin-insights__error" role="alert">
            <span>{loadError}</span>
            <AdminActionButton variant="ghost" onClick={this.loadDashboard}>
              Retry
            </AdminActionButton>
          </div>
        )}

        <AdminInsightStrip insights={insights} />

        {!loading && hasCharts && (
          <section className="lux-admin-insights-analytics lux-hrms-dash__panel">
            <AdminPanelHead
              title="Governance charts"
              subtitle="Aggregated metrics from audit, masking, compliance, and feature flag domains."
              actions={
                <>
                  <AdminPanelLink to="/admin/audit">Audit trail</AdminPanelLink>
                  <AdminPanelLink to="/admin/compliance-export">Compliance export</AdminPanelLink>
                </>
              }
            />
            <div className="lux-admin-insights-analytics__grid">
              {charts.auditVolume && charts.auditVolume.some((row) => row.value > 0) && (
                <PolicyAnalyticsBarChart
                  title="Audit volume"
                  subtitle="Events by day (last 7 days)"
                  series={charts.auditVolume}
                />
              )}
              {charts.auditActions && charts.auditActions.length > 0 && (
                <PolicyAnalyticsBarChart
                  title="Audit actions"
                  subtitle="Top action types"
                  series={charts.auditActions}
                />
              )}
              {charts.accessDenials && charts.accessDenials.length > 0 && (
                <PolicyAnalyticsBarChart
                  title="Access denials"
                  subtitle="Rejected by domain"
                  series={charts.accessDenials}
                />
              )}
              {charts.sensitiveFieldAccess && charts.sensitiveFieldAccess.length > 0 && (
                <PolicyAnalyticsBarChart
                  title="Sensitive field access"
                  subtitle="Persona masking posture"
                  series={charts.sensitiveFieldAccess}
                />
              )}
              {charts.complianceReadiness && charts.complianceReadiness.length > 0 && (
                <PolicyAnalyticsBarChart
                  title="Compliance readiness"
                  subtitle="Pack section posture"
                  series={charts.complianceReadiness}
                />
              )}
              {charts.featureAdoption && charts.featureAdoption.length > 0 && (
                <PolicyAnalyticsBarChart
                  title="Feature adoption"
                  subtitle="Pilot flag uptake (%)"
                  series={charts.featureAdoption}
                />
              )}
            </div>
          </section>
        )}
      </AdminLuxPage>
    );
  }
}

export default AdminInsightsPage;
