import React, { Component } from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";
import {
  getNotificationTemplateSourceLabel,
  isSystemNotificationTemplate,
} from "config/notification-template.config";

class NotificationTemplateDrawer extends Component {
  componentDidMount() {
    document.addEventListener("keydown", this.handleKeyDown);
  }

  componentWillUnmount() {
    document.removeEventListener("keydown", this.handleKeyDown);
  }

  handleKeyDown = (event) => {
    if (event.key !== "Escape") return;
    const { busy, showPreview, onClosePreview, onClose } = this.props;
    if (busy) return;
    if (showPreview) {
      onClosePreview && onClosePreview();
      return;
    }
    onClose && onClose();
  };

  renderField = (label, icon, control, full = false) => (
    <label className={classNames("lux-leave-drawer__field", { "is-full": full })}>
      <span className="lux-leave-drawer__label">
        <i className={`fe ${icon}`} aria-hidden="true" />
        {label}
      </span>
      {control}
    </label>
  );

  renderMetaCard = (label, value, icon, tone = "slate") => (
    <article className={classNames("lux-ntpl-meta-card", `is-${tone}`)}>
      <span className="lux-ntpl-meta-card__icon" aria-hidden="true">
        <i className={`fe ${icon}`} />
      </span>
      <span className="lux-ntpl-meta-card__copy">
        <em>{label}</em>
        <strong title={value || ""}>{value || "—"}</strong>
      </span>
    </article>
  );

  render() {
    const {
      open,
      selected,
      busy,
      saving,
      previewHtml,
      previewLoading,
      showPreview,
      showDeleteConfirm,
      sendTestEmail,
      sendTestLoading,
      sendTestMessage,
      formError,
      onClose,
      onChange,
      onToggleEnabled,
      onClone,
      onSave,
      onRequestDelete,
      onCancelDelete,
      onConfirmDelete,
      onPreview,
      onClosePreview,
      onSendTestEmailChange,
      onSendTest,
    } = this.props;

    if (!open || !selected || typeof document === "undefined") {
      return null;
    }

    const system = isSystemNotificationTemplate(selected);
    const channel = String(selected.channel || "EMAIL").toUpperCase();
    const sourceLabel = getNotificationTemplateSourceLabel(selected);
    const enabled = selected.enabled !== false;
    const eventType = selected.eventType || "Notification template";
    const title = system ? "View system template" : "Edit org override";
    const subtitle = system
      ? "Read-only classpath default. Preview safely, then clone to customize for your organization."
      : "Org overrides layer over classpath defaults at dispatch time.";

    return createPortal(
      <div
        className="lux-onb-drawer-backdrop lux-leave-drawer-backdrop lux-ntpl-drawer-backdrop"
        role="presentation"
        onClick={() => {
          if (!busy) onClose && onClose();
        }}
        data-testid="ntpl-drawer-backdrop"
      >
        <aside
          className={classNames(
            "lux-onb-drawer lux-leave-drawer lux-ntpl-drawer lux-onb-drawer--primary",
            system ? "is-system-view" : "is-override-edit"
          )}
          data-testid="ntpl-drawer"
          role="dialog"
          aria-modal="true"
          aria-labelledby="ntpl-drawer-title"
          onClick={(e) => e.stopPropagation()}
        >
          <span className="lux-onb-drawer__accent" aria-hidden="true" />
          <span className="lux-ntpl-drawer__glow" aria-hidden="true" />

          <header className="lux-onb-drawer__head lux-ntpl-drawer__head">
            <div className="lux-onb-drawer__head-main">
              <span
                className={classNames(
                  "lux-onb-drawer__category-icon lux-ntpl-drawer__mark",
                  system ? "is-blue" : "is-primary"
                )}
                aria-hidden="true"
              >
                <i className={system ? "fe fe-package" : "fe fe-edit-3"} />
              </span>
              <div className="lux-onb-drawer__head-copy">
                <span className="lux-leave-drawer__eyebrow">Admin · Notification templates</span>
                <h2 id="ntpl-drawer-title">{title}</h2>
                <p className="lux-ntpl-drawer__event">{eventType}</p>
                <p>{subtitle}</p>
                <div className="lux-onb-drawer__badges">
                  <span className="lux-onb-drawer__pill lux-onb-drawer__pill--required">{channel}</span>
                  <span className="lux-onb-drawer__pill lux-onb-drawer__pill--optional">{sourceLabel}</span>
                  <span
                    className={classNames(
                      "lux-onb-drawer__pill",
                      enabled ? "lux-onb-drawer__pill--optional" : "lux-onb-drawer__pill--required"
                    )}
                  >
                    {enabled ? "Enabled" : "Disabled"}
                  </span>
                </div>
              </div>
            </div>
            <button
              type="button"
              className="lux-onb-drawer__close"
              aria-label="Close"
              onClick={onClose}
              disabled={busy}
              data-testid="ntpl-drawer-close"
            >
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </header>

          <div className="lux-onb-drawer__body lux-leave-drawer__body lux-ntpl-drawer__body">
            <div className="lux-leave-drawer__scroll">
              {formError ? (
                <div className="lux-leave-config__banner is-error" role="alert">
                  <i className="fe fe-alert-circle" aria-hidden="true" />
                  <span>{formError}</span>
                </div>
              ) : null}

              <div className="lux-ntpl-drawer__hero">
                <span className="lux-ntpl-drawer__hero-icon" aria-hidden="true">
                  <i className="fe fe-eye-off" />
                </span>
                <div>
                  <strong>Masked preview · safe sample data</strong>
                  <p>
                    Sensitive placeholders stay masked in preview. Send-test uses a live mailbox when mail is
                    enabled for this workspace.
                  </p>
                </div>
              </div>

              {system ? (
                <>
                  <section className="lux-onb-drawer__section lux-ntpl-drawer__section">
                    <header className="lux-onb-drawer__section-head">
                      <i className="fe fe-layers" aria-hidden="true" /> Template identity
                    </header>
                    <div className="lux-ntpl-meta-grid">
                      {this.renderMetaCard("Event type", selected.eventType, "fe-zap", "blue")}
                      {this.renderMetaCard("Channel", channel, "fe-at-sign", "sky")}
                      {this.renderMetaCard("Source", sourceLabel, "fe-package", "violet")}
                      {this.renderMetaCard(
                        "Dispatch",
                        enabled ? "Enabled" : "Disabled",
                        enabled ? "fe-check-circle" : "fe-slash",
                        enabled ? "mint" : "amber"
                      )}
                    </div>
                    <div className="lux-ntpl-subject-card">
                      <span className="lux-ntpl-subject-card__label">
                        <i className="fe fe-type" aria-hidden="true" /> Subject line
                      </span>
                      <strong>{selected.subject || "—"}</strong>
                    </div>
                    {selected.classpathTemplateName ? (
                      <div className="lux-ntpl-classpath-card">
                        <div className="lux-ntpl-classpath-card__head">
                          <span>
                            <i className="fe fe-folder" aria-hidden="true" /> Classpath Thymeleaf
                          </span>
                          <em>Read-only</em>
                        </div>
                        <code title={selected.classpathTemplateName}>{selected.classpathTemplateName}</code>
                      </div>
                    ) : null}
                  </section>

                  <section className="lux-onb-drawer__section lux-ntpl-drawer__section">
                    <div className="lux-ntpl-clone-card">
                      <div className="lux-ntpl-clone-card__copy">
                        <span className="lux-ntpl-clone-card__kicker">Customize for your org</span>
                        <strong>Create an org override</strong>
                        <p>
                          Keep the system default intact. Clone to edit subject and HTML for this event at
                          dispatch time.
                        </p>
                      </div>
                      <button
                        type="button"
                        className="lux-leave-drawer__btn is-primary lux-ntpl-clone-card__btn"
                        onClick={onClone}
                        disabled={busy}
                        data-testid="ntpl-clone"
                      >
                        <i className="fe fe-copy" aria-hidden="true" /> Create org override
                      </button>
                    </div>
                  </section>
                </>
              ) : (
                <>
                  <section className="lux-onb-drawer__section lux-ntpl-drawer__section">
                    <header className="lux-onb-drawer__section-head">
                      <i className="fe fe-bookmark" aria-hidden="true" /> Identity
                    </header>
                    <div className="lux-leave-drawer__grid">
                      {this.renderField(
                        "Event type",
                        "fe-zap",
                        <input
                          className="lux-leave-drawer__input"
                          value={selected.eventType || ""}
                          disabled
                          data-testid="ntpl-event-type"
                        />
                      )}
                      {this.renderField(
                        "Channel",
                        "fe-at-sign",
                        <input className="lux-leave-drawer__input" value={channel} disabled />
                      )}
                    </div>
                    {this.renderField(
                      "Subject",
                      "fe-type",
                      <input
                        className="lux-leave-drawer__input"
                        value={selected.subject || ""}
                        disabled={busy}
                        onChange={(e) => onChange && onChange("subject", e.target.value)}
                        data-testid="ntpl-subject"
                      />,
                      true
                    )}
                  </section>

                  <section className="lux-onb-drawer__section lux-ntpl-drawer__section">
                    <header className="lux-onb-drawer__section-head">
                      <i className="fe fe-toggle-right" aria-hidden="true" /> Dispatch
                    </header>
                    <label className="lux-leave-drawer__check">
                      <input
                        type="checkbox"
                        checked={enabled}
                        disabled={busy}
                        onChange={(e) => onToggleEnabled && onToggleEnabled(e.target.checked)}
                        data-testid="ntpl-enabled"
                      />
                      <span>Template enabled for dispatch</span>
                    </label>
                    {this.renderField(
                      "HTML override (Thymeleaf)",
                      "fe-code",
                      <textarea
                        className="lux-leave-drawer__textarea lux-ntpl-drawer__html"
                        rows={10}
                        value={selected.htmlTemplate || ""}
                        disabled={busy}
                        onChange={(e) => onChange && onChange("htmlTemplate", e.target.value)}
                        placeholder="<p>Hello ${employeeName}, …</p>"
                        data-testid="ntpl-html"
                      />,
                      true
                    )}
                  </section>
                </>
              )}

              <section className="lux-onb-drawer__section lux-ntpl-drawer__section">
                <header className="lux-onb-drawer__section-head">
                  <i className="fe fe-send" aria-hidden="true" /> Send-test
                </header>
                <div className="lux-ntpl-send-card">
                  <div className="lux-ntpl-drawer__send">
                    {this.renderField(
                      "Recipient email",
                      "fe-mail",
                      <input
                        type="email"
                        className="lux-leave-drawer__input"
                        placeholder="Defaults to your email when blank"
                        value={sendTestEmail || ""}
                        disabled={sendTestLoading || busy}
                        onChange={(e) => onSendTestEmailChange && onSendTestEmailChange(e.target.value)}
                        data-testid="ntpl-send-test-email"
                      />
                    )}
                    <button
                      type="button"
                      className="lux-leave-drawer__btn is-ghost"
                      onClick={onSendTest}
                      disabled={sendTestLoading || busy}
                      data-testid="ntpl-send-test"
                    >
                      <i className="fe fe-send" aria-hidden="true" />
                      {sendTestLoading ? "Sending…" : "Send test"}
                    </button>
                  </div>
                  {sendTestMessage ? (
                    <p className="lux-ntpl-drawer__status" role="status" data-testid="send-test-result">
                      {sendTestMessage}
                    </p>
                  ) : (
                    <p className="lux-ntpl-send-card__hint">
                      Fail-closed when mail is disabled. Delivery is audited as SEND_TEST.
                    </p>
                  )}
                </div>
              </section>

              {showDeleteConfirm ? (
                <div className="lux-ntpl-drawer__confirm" role="alertdialog" aria-labelledby="ntpl-delete-title">
                  <strong id="ntpl-delete-title">Delete this org override?</strong>
                  <p>System defaults cannot be removed. This only deletes the workspace override.</p>
                  <div className="lux-ntpl-drawer__confirm-actions">
                    <button
                      type="button"
                      className="lux-leave-drawer__btn is-ghost"
                      onClick={onCancelDelete}
                      disabled={saving}
                      data-testid="ntpl-delete-cancel"
                    >
                      Cancel
                    </button>
                    <button
                      type="button"
                      className="lux-leave-drawer__btn is-danger"
                      onClick={onConfirmDelete}
                      disabled={saving}
                      data-testid="ntpl-delete-confirm"
                    >
                      {saving ? "Deleting…" : "Delete override"}
                    </button>
                  </div>
                </div>
              ) : null}
            </div>

            <footer className="lux-onb-drawer__foot lux-ntpl-drawer__foot">
              <div className="lux-onb-drawer__foot-actions">
                <button
                  type="button"
                  className="lux-leave-drawer__btn is-ghost"
                  onClick={onClose}
                  disabled={busy}
                >
                  Close
                </button>
                <button
                  type="button"
                  className="lux-leave-drawer__btn is-ghost lux-ntpl-drawer__preview-btn"
                  onClick={onPreview}
                  disabled={previewLoading || busy}
                  data-testid="ntpl-preview"
                >
                  <i className="fe fe-eye" aria-hidden="true" />
                  {previewLoading ? "Previewing…" : "Preview masked"}
                </button>
                {system ? (
                  <button
                    type="button"
                    className="lux-leave-drawer__btn is-primary"
                    onClick={onClone}
                    disabled={busy}
                    data-testid="ntpl-clone-footer"
                  >
                    <i className="fe fe-copy" aria-hidden="true" /> Clone override
                  </button>
                ) : (
                  <>
                    <button
                      type="button"
                      className="lux-leave-drawer__btn is-ghost"
                      onClick={onRequestDelete}
                      disabled={saving || busy || !selected.templateRef}
                      data-testid="ntpl-delete"
                    >
                      Delete
                    </button>
                    <button
                      type="button"
                      className="lux-leave-drawer__btn is-primary"
                      onClick={onSave}
                      disabled={saving || busy}
                      data-testid="ntpl-save"
                    >
                      {saving ? "Saving…" : "Save override"}
                    </button>
                  </>
                )}
              </div>
            </footer>
          </div>

          {showPreview ? (
            <div className="lux-ntpl-preview-overlay" data-testid="ntpl-preview-overlay">
              <div className="lux-ntpl-preview-panel" role="dialog" aria-label="Masked template preview">
                <div className="lux-ntpl-preview-panel__head">
                  <div>
                    <h3>Masked preview</h3>
                    <p>Rendered with sensitive placeholders masked for safety.</p>
                  </div>
                  <button
                    type="button"
                    className="lux-onb-drawer__close"
                    aria-label="Close preview"
                    onClick={onClosePreview}
                    data-testid="ntpl-preview-close"
                  >
                    <i className="fe fe-x" aria-hidden="true" />
                  </button>
                </div>
                <div className="lux-ntpl-preview-panel__body">
                  {previewHtml ? (
                    <div
                      className="lux-ntpl-preview-panel__frame"
                      dangerouslySetInnerHTML={{ __html: previewHtml }}
                    />
                  ) : (
                    <p className="lux-ntpl-preview-empty">No preview content.</p>
                  )}
                </div>
              </div>
            </div>
          ) : null}
        </aside>
      </div>,
      document.body
    );
  }
}

export default NotificationTemplateDrawer;
