import React from "react";
import { Link, withRouter } from "react-router-dom";
import classNames from "classnames/bind";
import { sanitizeUiCopy } from "_helpers/ui-copy.utils";
import { useReportPageDataSource } from "views/common/PageChromeContext";
import LuxKpiStrip from "views/common/fragments/LuxKpiStrip";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";

export function AdminHeroActions({ dataSource, demoLabel, children }) {
  useReportPageDataSource(dataSource);
  return (
    <div className="lux-admin-hero__actions">
      <div className="lux-admin-hero__buttons">{children}</div>
    </div>
  );
}

export function AdminActionButton({
  to,
  href,
  onClick,
  children,
  label,
  icon,
  iconOnly = false,
  variant = "primary",
  type = "button",
  disabled = false,
  className,
  testId,
  title,
  target,
  rel,
}) {
  const classes = classNames("lux-onb-action lux-admin-action", `lux-onb-action--${variant}`, className, {
    "is-disabled": disabled,
    "is-icon-only": iconOnly,
  });
  const text = children != null ? children : label;
  const content =
    icon && iconOnly ? (
      <i className={icon} aria-hidden="true" />
    ) : icon ? (
      <>
        <i className={icon} aria-hidden="true" />
        <span>{text}</span>
      </>
    ) : (
      text
    );

  if (href && !disabled) {
    return (
      <a
        href={href}
        className={classes}
        data-testid={testId}
        title={title}
        target={target}
        rel={rel || (target === "_blank" ? "noopener noreferrer" : undefined)}
      >
        {content}
      </a>
    );
  }

  if (to && !disabled) {
    return (
      <Link to={to} className={classes} data-testid={testId} title={title}>
        {content}
      </Link>
    );
  }

  return (
    <button
      type={type}
      className={classes}
      onClick={onClick}
      disabled={disabled}
      data-testid={testId}
      title={title}
    >
      {content}
    </button>
  );
}

/** Rich KPI strip — same governance luxury treatment across admin/module consoles. */
export function AdminKpiStrip({ cards, loading, className }) {
  return (
    <LuxKpiStrip
      cards={cards}
      loading={loading}
      className={classNames("lux-admin-kpi-strip", className)}
    />
  );
}

/**
 * Module console shell for admin pages: register gutters + masthead + optional KPI.
 * Auto-appends icon-only How to use when a registry doc exists for the current route.
 */
function AdminLuxPageInner({
  pageMeta,
  dataSource,
  demoLabel = "Demo admin data",
  heroActions,
  heroNav,
  kpiCards,
  loading,
  testId,
  children,
  className,
  howToHref,
  hideHowTo,
}) {
  useReportPageDataSource(dataSource);
  const meta = pageMeta || {
    tone: "indigo",
    icon: "fe fe-settings",
    eyebrow: "Admin",
    titleLead: "Administration",
    titleAccent: "console",
    lede: "Platform governance and configuration.",
  };

  return (
    <div
      className={classNames(
        "lux-register-page",
        "lux-admin-page",
        "lux-admin-lux",
        meta.tone && `is-${meta.tone}`,
        className
      )}
      {...(testId ? { "data-testid": testId } : {})}
    >
      <div className="lux-admin-lux__ambient" aria-hidden="true">
        <span className="lux-admin-lux__orb lux-admin-lux__orb--a" />
        <span className="lux-admin-lux__orb lux-admin-lux__orb--b" />
      </div>
      <LuxModuleIntro
        meta={meta}
        actions={heroActions || undefined}
        nav={heroNav || undefined}
        howToHref={howToHref}
        howToTestId={`${testId || "admin"}-howto-link`}
        hideHowTo={hideHowTo}
      />

      <div className="lux-register-page__body">
        {kpiCards && kpiCards.length ? (
          <AdminKpiStrip cards={kpiCards} loading={loading} />
        ) : null}
        <div className="lux-admin-lux__content">{children}</div>
      </div>
    </div>
  );
}

export const AdminLuxPage = withRouter(AdminLuxPageInner);

export function AdminPanelHead({ title, subtitle, actions }) {
  return (
    <header className={classNames("lux-hrms-dash__panel-head", { "lux-hrms-dash__panel-head--stack": subtitle })}>
      <div>
        <h2 className="lux-hrms-dash__panel-title">{title}</h2>
        {subtitle && <p className="lux-hrms-dash__panel-sub">{sanitizeUiCopy(subtitle)}</p>}
      </div>
      {actions && <div className="lux-hrms-dash__panel-actions">{actions}</div>}
    </header>
  );
}

export function AdminPanelLink({ to, children }) {
  return (
    <Link to={to} className="lux-admin-panel-link">
      {children}
      <i className="fe fe-arrow-right" aria-hidden="true" />
    </Link>
  );
}

/** Rich 3-column insight cards — shared across admin consoles */
export function AdminInsightStrip({ insights, className }) {
  if (!insights || insights.length === 0) {
    return null;
  }

  return (
    <div className={classNames("lux-admin-insights", className)} role="list">
      {insights.map((insight) => {
        const body = (
          <>
            <span className="lux-admin-insight-card__icon" aria-hidden="true">
              <i className={insight.icon || "fe fe-info"} />
            </span>
            <div className="lux-admin-insight-card__copy">
              <strong>{sanitizeUiCopy(insight.title)}</strong>
              <p>{sanitizeUiCopy(insight.copy || insight.body || insight.detail)}</p>
            </div>
            {insight.path && <i className="fe fe-chevron-right lux-admin-insight-card__chevron" aria-hidden="true" />}
          </>
        );
        const cardClass = classNames("lux-admin-insight-card", insight.tone && `is-${insight.tone}`);

        if (insight.path) {
          return (
            <Link key={insight.id} to={insight.path} className={cardClass} role="listitem">
              {body}
            </Link>
          );
        }

        return (
          <article key={insight.id} className={cardClass} role="listitem">
            {body}
          </article>
        );
      })}
    </div>
  );
}

/** Horizontal quick-nav cards with icon, copy, and chevron */
export function AdminQuickNav({ eyebrow, title, links, actions, className, ariaLabel }) {
  if (!links || links.length === 0) {
    return null;
  }

  return (
    <section className={classNames("lux-admin-quick-nav", className)} aria-label={ariaLabel || title || "Quick navigation"}>
      <header className="lux-admin-quick-nav__head">
        <div>
          {eyebrow && <span className="lux-hrms-dash__section-eyebrow">{sanitizeUiCopy(eyebrow)}</span>}
          {title && <h2 className="lux-hrms-dash__section-title">{title}</h2>}
        </div>
        {actions}
      </header>
      <div className="lux-admin-quick-nav__grid">
        {links.map((item) => {
          const href = item.path || item.to;
          return (
          <Link
            key={href || item.label}
            to={href}
            className={classNames("lux-admin-quick-card", item.tone && `is-${item.tone}`)}
          >
            <span className="lux-admin-quick-card__icon" aria-hidden="true">
              <i className={item.icon} />
            </span>
            <span className="lux-admin-quick-card__copy">
              <strong>{sanitizeUiCopy(item.label)}</strong>
              <small>{sanitizeUiCopy(item.desc)}</small>
            </span>
            <i className="fe fe-arrow-right lux-admin-quick-card__chevron" aria-hidden="true" />
          </Link>
          );
        })}
      </div>
    </section>
  );
}
