import React from "react";
import classNames from "classnames/bind";

const TABS = [
  { id: "personal", label: "My dashboard", icon: "fe-user" },
  { id: "team", label: "Team dashboard", icon: "fe-users" },
];

function EmployeeDashboardTabs({ activeTab, onChange, showManagerTab }) {
  if (!showManagerTab) return null;

  return (
    <nav className="lux-hrms-dash__tabs" aria-label="Dashboard views">
      {TABS.map((tab) => (
        <button
          key={tab.id}
          type="button"
          className={classNames("lux-hrms-dash__tab", { "is-active": activeTab === tab.id })}
          onClick={() => onChange && onChange(tab.id)}
          aria-selected={activeTab === tab.id}
        >
          <i className={`fe ${tab.icon}`} aria-hidden="true" />
          {tab.label}
        </button>
      ))}
    </nav>
  );
}

export default EmployeeDashboardTabs;
