import React from "react";
import classNames from "classnames/bind";
import {
  getStaffingPriorityTone,
  getStaffingStatusTone,
} from "config/resource-planning.utils";

export default function StaffingRequestRegister({ rows, loading, onSelect }) {
  if (loading) {
    return null;
  }

  return (
    <div className="lux-staffing-register-wrap">
      <table className="lux-staffing-register">
        <thead>
          <tr>
            <th>Request</th>
            <th>Project</th>
            <th>Role</th>
            <th>Headcount</th>
            <th>Priority</th>
            <th>Status</th>
            <th>Due</th>
            <th>Requester</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => {
            const statusTone = getStaffingStatusTone(row.status);
            const priorityTone = getStaffingPriorityTone(row.priority);
            const isUrgent = String(row.priority).toUpperCase() === "HIGH" && row.status === "Pending";
            return (
              <tr
                key={row.id}
                className={classNames("lux-staffing-register__row", {
                  "is-urgent": isUrgent,
                  "is-open": row.status === "Pending" || row.status === "Approved",
                })}
              >
                <td>
                  <button type="button" className="lux-staffing-register__title" onClick={() => onSelect(row)}>
                    <strong>{row.title}</strong>
                    {row.notes && <span className="lux-staffing-register__meta">{row.notes}</span>}
                  </button>
                </td>
                <td>
                  <span className="lux-staffing-register__project">{row.projectName}</span>
                </td>
                <td>{row.roleNeeded}</td>
                <td>
                  <span className="lux-staffing-register__count">{row.headcount}</span>
                </td>
                <td>
                  <span className={classNames("lux-staffing-register__chip", `is-${priorityTone}`)}>
                    {row.priority || "NORMAL"}
                  </span>
                </td>
                <td>
                  <span className={classNames("lux-doc-badge", `is-${statusTone}`)}>{row.status}</span>
                </td>
                <td>
                  <span className="lux-staffing-register__date">{row.dueAt || "—"}</span>
                </td>
                <td>
                  <span className="lux-staffing-register__requester">{row.requesterName || "—"}</span>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
