import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import {
  getDayMeta,
  getAttendanceStatusMeta,
  isAttendanceMarked,
  isAttendanceLeave,
  canMarkAttendanceFor,
} from "./attendance.utils";

class AttendanceDayCell extends PureComponent {
  handleClick = (event) => {
    event.preventDefault();
    event.stopPropagation();

    const {
      item,
      employeeId,
      employeeName,
      dayMonth,
      isLoading,
      force,
      permission,
      currentUserId,
      onRequestMark,
      onRequestViewDetails,
      workdays,
      holidayDates,
    } = this.props;
    const meta = getDayMeta(dayMonth, workdays, holidayDates);
    const canMark = canMarkAttendanceFor(permission, employeeId, currentUserId);

    if (isLoading || meta.isFuture) return;

    // Leave / half-day rows are owned by leave flow — block mark unless force.
    if (isAttendanceLeave(item) && force !== true) {
      if (item && item.id != null && onRequestViewDetails) {
        onRequestViewDetails(employeeId, employeeName, dayMonth, item);
      }
      return;
    }

    if (item && item.id != null && isAttendanceMarked(item)) {
      onRequestViewDetails(employeeId, employeeName, dayMonth, item);
    } else if (canMark && onRequestMark) {
      onRequestMark(employeeId, employeeName, dayMonth);
    }
  };

  render() {
    const {
      item,
      employeeId,
      dayMonth,
      isLoading,
      force,
      permission,
      currentUserId,
      workdays,
      holidayDates,
    } = this.props;
    const meta = getDayMeta(dayMonth, workdays, holidayDates);
    const statusMeta = getAttendanceStatusMeta(item);
    const isMarked = isAttendanceMarked(item);
    const leaveLocked = isAttendanceLeave(item) && force !== true;
    const canMark = canMarkAttendanceFor(permission, employeeId, currentUserId);
    const canViewMarked = isMarked && item && item.id != null;
    const canToggle =
      !meta.isFuture &&
      !isLoading &&
      !(leaveLocked && !canViewMarked) &&
      (canViewMarked || canMark);

    return (
      <td
        className={classNames("lux-att-day", {
          "is-weekend-sat": meta.isSaturday,
          "is-weekend-sun": meta.isSunday,
          "is-holiday": meta.isHoliday,
          "is-today": meta.isToday,
          "is-future": meta.isFuture,
          "is-present": statusMeta.tone === "present",
          "is-pending": statusMeta.tone === "pending",
          "is-pending-removal": statusMeta.tone === "pending-removal",
          "is-rejected": statusMeta.tone === "rejected",
          "is-leave": statusMeta.tone === "leave",
          "is-leave-locked": leaveLocked,
          "is-absent": statusMeta.tone === "absent" && !meta.isFuture,
          "is-clickable": canToggle,
        })}
      >
        {meta.isFuture ? (
          <span className="lux-att-day__future" aria-hidden="true" />
        ) : (
          <button
            type="button"
            className={classNames("lux-att-day__btn", {
              "is-present": statusMeta.tone === "present",
              "is-pending": statusMeta.tone === "pending",
              "is-rejected": statusMeta.tone === "rejected",
              "is-leave": statusMeta.tone === "leave",
              "is-absent": statusMeta.tone === "absent",
            })}
            onClick={this.handleClick}
            disabled={!canToggle}
            title={
              leaveLocked
                ? item && item.id != null
                  ? `${statusMeta.label} — managed via leave (click for details)`
                  : `${statusMeta.label} — marking blocked (managed via leave)`
                : !canMark && !canViewMarked
                ? `${statusMeta.label} — mark attendance not permitted for your role`
                : meta.isWeekend
                ? isMarked
                  ? `${statusMeta.label} (optional day) — click to view details`
                  : "Not marked (optional day) — click to mark present"
                : isMarked
                ? `${statusMeta.label} — click to view details`
                : "Absent — click to mark with time details"
            }
            aria-label={`${statusMeta.label} on ${dayMonth.format("MMM D")}`}
          >
            <i className={statusMeta.icon} aria-hidden="true" />
          </button>
        )}
      </td>
    );
  }
}

export default AttendanceDayCell;
