export function humanizePermissionKey(key) {
  if (CRUD_PERMISSION_LABELS[key]) {
    return CRUD_PERMISSION_LABELS[key];
  }
  if (PERMISSION_KEY_LABELS[key]) {
    return PERMISSION_KEY_LABELS[key];
  }
  return String(key || "")
    .replace(/Enabled$/i, "")
    .replace(/^enable/i, "")
    .replace(/^allow/i, "")
    .replace(/([a-z])([A-Z])/g, "$1 $2")
    .replace(/[_-]+/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .replace(/^./, (c) => c.toUpperCase());
}

export function buildHowToSteps({ moduleLabel, configSetting, hasActionPermissions, pageTitle }) {
  const steps = [
    "Open Admin → Application config",
    "Select the role (or org unit) that should get access",
  ];
  if (moduleLabel) {
    steps.push(`Open the ${moduleLabel} module group`);
  } else {
    steps.push("Open the module group that owns this page");
  }
  if (hasActionPermissions && configSetting) {
    steps.push(`Find Module permissions → ${configSetting}`);
    steps.push("Break the chain (override) if the setting is inherited");
    steps.push("Enable View / Create / Edit / Delete / Archive / Remove (and any extra options) as needed");
  } else if (pageTitle) {
    steps.push(`Enable the menu / page flag for “${pageTitle}” under Module access`);
  } else {
    steps.push("Enable the menu / page flag for this area under Module access");
  }
  steps.push("Click Update to save, then refresh this page");
  return steps;
}

