export function buildOrgHowToSteps({ groupLabels, teamId, orgLabel, orgPath }) {
  const orgSelectLabel = orgPath || orgLabel || (teamId != null ? `team id ${teamId}` : null);
  const steps = [
    "Open Admin → Application config",
    orgSelectLabel
      ? `Select your organization unit (${orgSelectLabel})`
      : "Select the organization unit for this workspace",
    "Open the HRMS module (and PROJECT / SALES when relevant)",
  ];
  if (groupLabels && groupLabels.length) {
    steps.push(`Review org settings under: ${groupLabels.join(", ")}`);
  } else {
    steps.push("Review the Tracopus *Additional and related org config groups");
  }
  steps.push("Break the chain (override) if a setting is inherited from a parent org");
  steps.push("Toggle org flags or edit property values, then click Update");
  steps.push("Refresh this page so the encrypted access blob and pilot flags reload");
  return steps;
}

