import React, { Component } from "react";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isExpenseManagementEnabled, REIMBURSEMENT_STATUSES } from "config/expenses.config";
import { EXPENSE_PAGE_META } from "config/expenses-nav.config";
import { expensesService } from "_services/expenses.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import ExpensesLuxPage, {
  ExpenseActionButton,
  ExpenseInsightPanel,
  ExpenseLuxPanel,
} from "views/expenses/components/ExpensesLuxShared";

function reimbursementTone(status) {
  switch (status) {
    case REIMBURSEMENT_STATUSES.PAID:
      return "green";
    case REIMBURSEMENT_STATUSES.SCHEDULED:
      return "blue";
    case REIMBURSEMENT_STATUSES.PENDING:
      return "amber";
    default:
      return "slate";
  }
}

class ReimbursementsPage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    reimbursements: [],
    kpiCards: [],
    insights: [],
    busyId: null,
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Reimbursements");
    }
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await expensesService.getReimbursementsOverview();
      const overview = result.payload || {};
      this.setState({
        loading: false,
        reimbursements: overview.reimbursements || [],
        kpiCards: overview.kpiCards || [],
        insights: overview.insights || [],
        dataSource: result.source,
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load reimbursements.",
      });
    }
  };

  handleSchedule = async (reimbursementId) => {
    this.setState({ busyId: reimbursementId });
    try {
      const payrollRunId =
        (typeof window !== "undefined" &&
          window.prompt &&
          window.prompt("Payroll run ID for this reimbursement schedule", "")) ||
        "";
      const runId = String(payrollRunId || "").trim();
      if (!runId) {
        this.setState({
          loadError: "Payroll run ID is required to schedule a reimbursement.",
          busyId: null,
        });
        return;
      }
      await expensesService.scheduleReimbursement(reimbursementId, runId);
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to schedule reimbursement." });
    } finally {
      this.setState({ busyId: null });
    }
  };

  handleMarkPaid = async (reimbursementId) => {
    this.setState({ busyId: reimbursementId });
    try {
      await expensesService.markReimbursementPaid(reimbursementId);
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to mark reimbursement paid." });
    } finally {
      this.setState({ busyId: null });
    }
  };

  renderRegister() {
    const { reimbursements, loading, busyId } = this.state;
    if (loading) {
      return <div className="lux-expense-register__skeleton" aria-busy="true" />;
    }
    if (!reimbursements.length) {
      return (
        <LuxRegisterEmptyState
          className="lux-register-empty--compact lux-expense-empty"
          icon="fe fe-dollar-sign"
          title="No reimbursements"
          description="Approved expense claims will appear here for payroll scheduling."
        />
      );
    }

    return (
      <div className="lux-expense-register-wrap">
        <table className="lux-expense-register">
          <thead>
            <tr>
              <th>Employee</th>
              <th>Amount</th>
              <th>Status</th>
              <th>Payroll run</th>
              <th>Aging</th>
              <th aria-label="Actions" />
            </tr>
          </thead>
          <tbody>
            {reimbursements.map((row) => (
              <tr key={row.id}>
                <td>
                  <div>{row.employeeName}</div>
                  {row.projectName ? <div className="lux-expense-register__meta">{row.projectName}</div> : null}
                </td>
                <td>
                  <strong>${Number(row.amountUsd || 0).toLocaleString()}</strong>
                </td>
                <td>
                  <span className={classNames("lux-doc-badge", `is-${reimbursementTone(row.status)}`)}>{row.status}</span>
                </td>
                <td>{row.payrollRunLabel || "—"}</td>
                <td>{row.agingDays != null ? `${row.agingDays}d` : "—"}</td>
                <td>
                  <div className="lux-expense-register__actions">
                    {row.status === REIMBURSEMENT_STATUSES.PENDING ? (
                      <button
                        type="button"
                        className="lux-onb-action lux-onb-action--primary lux-onb-action--sm"
                        disabled={busyId === row.id}
                        onClick={() => this.handleSchedule(row.id)}
                      >
                        Schedule
                      </button>
                    ) : null}
                    {row.status === REIMBURSEMENT_STATUSES.SCHEDULED ? (
                      <button
                        type="button"
                        className="lux-onb-action lux-onb-action--ghost lux-onb-action--sm"
                        disabled={busyId === row.id}
                        onClick={() => this.handleMarkPaid(row.id)}
                      >
                        Mark paid
                      </button>
                    ) : null}
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    );
  }

  render() {
    if (!isExpenseManagementEnabled()) {
      return <PersonaAccessDenied featureLabel="Reimbursements" />;
    }

    const { loading, loadError, dataSource, kpiCards, insights } = this.state;
    const meta = EXPENSE_PAGE_META.reimbursements;

    return (
      <ExpensesLuxPage
        testId="page-payroll-reimbursements"
        pageMeta={meta}
        dataSource={dataSource}
        demoLabel="Demo reimbursement queue"
        loading={loading}
        kpiCards={kpiCards}
        heroActions={
          <>
            <ExpenseActionButton to="/finance/expenses" icon="fe fe-briefcase" variant="ghost">
              Expense approvals
            </ExpenseActionButton>
            <ExpenseActionButton to="/payroll/runs" icon="fe fe-layers" variant="primary">
              Payroll runs
            </ExpenseActionButton>
          </>
        }
      >
        <ExpenseInsightPanel insights={insights} />
        {loadError ? (
          <ExpenseLuxPanel title="Reimbursement load issue" meta={loadError} accent="rose">
            <ExpenseActionButton icon="fe fe-refresh-cw" variant="primary" onClick={this.loadData}>
              Retry
            </ExpenseActionButton>
          </ExpenseLuxPanel>
        ) : null}
        <ExpenseLuxPanel
          title="Reimbursement payout queue"
          meta="Link approved claims to payroll runs and track payout aging"
          icon="fe fe-dollar-sign"
          accent="blue"
        >
          {this.renderRegister()}
        </ExpenseLuxPanel>
      </ExpensesLuxPage>
    );
  }
}

export default ReimbursementsPage;
