import {
  isTimesheetApprovalConfigLoaded,
  shouldUseTimesheetApprovalWorkflow,
} from "./timesheetApproval.config";
import { normalizeTimesheetStatus, readAttributeValue } from "views/hrms/components/timesheet/timesheetSummary.utils";

const SUBMITTABLE_STATUSES = new Set(["DRAFT", "REJECTED", "REOPENED"]);
const RESUBMIT_STATUSES = new Set(["REJECTED", "REOPENED"]);

export function normalizeTimesheetWeekStatus(rawStatus) {
  const normalized = normalizeTimesheetStatus(rawStatus);
  if (normalized === "PENDING_APPROVAL") {
    return "PENDING";
  }
  return normalized;
}

export function getTimesheetWeekStatus(timeSheetData) {
  return normalizeTimesheetWeekStatus(readAttributeValue(timeSheetData && timeSheetData.status));
}

export function timesheetHasLoggedHours(timeSheetData) {
  if (!timeSheetData) return false;
  return ["project", "nonProject"].some((sectionKey) => {
    const groups = timeSheetData[sectionKey];
    if (!groups) return false;
    return Object.keys(groups).some((groupId) => {
      const tasks = groups[groupId] && groups[groupId].tasks;
      if (!tasks) return false;
      return tasks.some((task) => {
        const timeEntry = task.timeEntry || {};
        return Object.keys(timeEntry).some(
          (dateKey) => parseInt(timeEntry[dateKey].timesheetTimeMins || 0, 10) > 0
        );
      });
    });
  });
}

/**
 * Approval UI is active when org/env flag (or permission mirror) is on.
 * While config is still loading, a staged `weekId` is a soft signal.
 * After config is known off, never keep Submit/draft chrome alive from weekId alone.
 */
export function isTimesheetApprovalWorkflowActive(timeSheetData, permission) {
  if (shouldUseTimesheetApprovalWorkflow()) {
    return true;
  }
  if (permission && permission.timesheetApprovalEnabled === true) {
    return true;
  }
  if (!isTimesheetApprovalConfigLoaded()) {
    return !!(timeSheetData && timeSheetData.weekId);
  }
  return false;
}

export function canSubmitTimesheet(timeSheetData, permission) {
  if (!isTimesheetApprovalWorkflowActive(timeSheetData, permission)) {
    return false;
  }
  // Staged weeks (weekId) are already editable via save; do not hide Submit
  // solely because role enableTimeSheetEdit is missing/false while draft exists.
  if (
    permission &&
    permission.enableTimeSheetEdit === false &&
    !(timeSheetData && timeSheetData.weekId)
  ) {
    return false;
  }
  if (!timeSheetData || !timeSheetData.weekId) {
    return false;
  }
  const status = getTimesheetWeekStatus(timeSheetData);
  if (status && SUBMITTABLE_STATUSES.has(status)) {
    return timesheetHasLoggedHours(timeSheetData);
  }
  if (!status && timesheetHasLoggedHours(timeSheetData)) {
    return true;
  }
  return false;
}

export function isResubmitAction(timeSheetData) {
  const status = getTimesheetWeekStatus(timeSheetData);
  return RESUBMIT_STATUSES.has(status);
}

export function isTimesheetPendingApproval(timeSheetData) {
  return getTimesheetWeekStatus(timeSheetData) === "PENDING";
}

export function isTimesheetRejected(timeSheetData) {
  return getTimesheetWeekStatus(timeSheetData) === "REJECTED";
}

export function getSaveDraftCopy(permission, timeSheetData) {
  if (isTimesheetApprovalWorkflowActive(timeSheetData, permission)) {
    return {
      title: "Unsaved draft changes",
      body: "Save your draft to staging. Submit for approval when the week is ready.",
      buttonLabel: "Save draft",
    };
  }
  return {
    title: "Unsaved changes",
    body: "Review your entries and save to update the timesheet.",
    buttonLabel: "Save timesheet",
  };
}

export function collectLineRejections(timeSheetData) {
  const rows = [];
  if (!timeSheetData) return rows;

  ["project", "nonProject"].forEach((sectionKey) => {
    const groups = timeSheetData[sectionKey];
    if (!groups) return;
    Object.keys(groups).forEach((groupId) => {
      const section = groups[groupId];
      const tasks = section && section.tasks;
      if (!tasks) return;
      tasks.forEach((task) => {
        const lineStatus = normalizeTimesheetStatus(readAttributeValue(task.lineStatus));
        const comment = readAttributeValue(task.rejectionComment);
        if (lineStatus !== "REJECTED" || !comment) {
          return;
        }
        const label =
          sectionKey === "project"
            ? [task.taskName, task.workItemName].filter(Boolean).join(" · ")
            : task.workItemName || groupId;
        rows.push({ key: `${sectionKey}-${groupId}-${task.lineId || label}`, label, comment });
      });
    });
  });
  return rows;
}

export function getWeekRejectionComment(timeSheetData) {
  return readAttributeValue(timeSheetData && timeSheetData.rejectionComment);
}

export function isTimesheetApproved(timeSheetData) {
  return getTimesheetWeekStatus(timeSheetData) === "APPROVED";
}

export function isTimesheetReopened(timeSheetData) {
  return getTimesheetWeekStatus(timeSheetData) === "REOPENED";
}

export function wasTimesheetPreviouslyApproved(timeSheetData) {
  return !!(
    timeSheetData &&
    (readAttributeValue(timeSheetData.approvedBy) || readAttributeValue(timeSheetData.approvedDate))
  );
}

export function isTimesheetWeekLocked(timeSheetData) {
  const status = getTimesheetWeekStatus(timeSheetData);
  return status === "LOCKED" || status === "PAYROLL_PROCESSED";
}

export function isTimesheetPayrollProcessed(timeSheetData) {
  return getTimesheetWeekStatus(timeSheetData) === "PAYROLL_PROCESSED";
}

/**
 * ADD TIME ENTRY / create row — blocked once the week is pending, approved, or locked.
 */
export function canAddTimesheetEntry(timeSheetData, permission) {
  if (permission && permission.enableTimeSheetEntry === false) {
    return false;
  }
  const status = getTimesheetWeekStatus(timeSheetData);
  if (!status) {
    return true;
  }
  return status === "DRAFT" || status === "REJECTED" || status === "REOPENED";
}
