import React from "react";
import { Link } from "react-router-dom";
import PropTypes from "prop-types";
import envconfig from "env.config";
import LoginPageFooter from "./LoginPageFooter";
import AuthPageShell from "./components/AuthPageShell";
import AuthLoginCard from "./components/AuthLoginCard";

function LegalDocumentPage({ title, eyebrow, children }) {
  const appName = envconfig.APP_NAME || "Tracopus";

  return (
    <div data-testid={`page-legal-${title.toLowerCase().replace(/\s+/g, "-")}`}>
      <AuthPageShell>
        <AuthLoginCard
          eyebrow={eyebrow}
          title={title}
          subtitle={`${appName} legal information`}
          footer={
            <p className="auth-login__foot-text">
              <Link to="/user/login" className="auth-login__link">
                Back to sign in
              </Link>
            </p>
          }
        >
          <div className="auth-legal__content">{children}</div>
        </AuthLoginCard>
        <LoginPageFooter />
      </AuthPageShell>
    </div>
  );
}

LegalDocumentPage.propTypes = {
  title: PropTypes.string.isRequired,
  eyebrow: PropTypes.string,
  children: PropTypes.node.isRequired,
};

LegalDocumentPage.defaultProps = {
  eyebrow: "Legal",
};

