import React, { useEffect } from "react";
import { useReportPageDataSource } from "views/common/PageChromeContext";
import classNames from "classnames/bind";
import {
  PORTFOLIO_PAGE_META,
  PORTFOLIO_PAGE_VARIANTS,
  getPortfolioShellPageTitle,
} from "config/portfolio-control-tower-nav.config";
import { buildPortfolioInsights, buildPortfolioKpiCards } from "config/portfolio-control-tower.utils";
import { AdminInsightStrip } from "views/admin/components/AdminLuxShared";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import { GovernanceKpiStrip, GovernanceLuxPanel } from "views/project/components/ProjectGovernanceLuxShared";

export { GovernanceLuxPanel as PortfolioLuxPanel };

export default function PortfolioLuxPage({
  variant = PORTFOLIO_PAGE_VARIANTS.PORTFOLIO,
  dataSource,
  demoLabel = "Demo portfolio data",
  heroActions,
  rollup,
  executiveMetrics,
  loading,
  pageHeaderNameChangeHandler,
  children,
}) {
  useReportPageDataSource(dataSource);
  const meta = PORTFOLIO_PAGE_META[variant] || PORTFOLIO_PAGE_META.portfolio;
  const isExecutive = variant === PORTFOLIO_PAGE_VARIANTS.EXECUTIVE;
  const isScenarios = variant === PORTFOLIO_PAGE_VARIANTS.SCENARIOS;
  const shellTitle = getPortfolioShellPageTitle(variant);
  const insights = buildPortfolioInsights(rollup);
  const kpiCards = buildPortfolioKpiCards(rollup || {}, executiveMetrics || []);

  useEffect(() => {
    if (pageHeaderNameChangeHandler) {
      pageHeaderNameChangeHandler(shellTitle);
    }
  }, [pageHeaderNameChangeHandler, shellTitle]);

  return (
    <div
      className={classNames(
        "lux-register-page",
        "lux-portfolio-module",
        "lux-portfolio-lux",
        meta.tone && `is-${meta.tone}`,
        isExecutive && "lux-portfolio-lux--executive",
        isScenarios && "lux-portfolio-lux--scenarios"
      )}
      data-testid={isExecutive ? "page-analytics-control-tower" : undefined}
    >
      <div className="lux-portfolio-lux__ambient" aria-hidden="true">
        <span className="lux-portfolio-lux__orb lux-portfolio-lux__orb--a" />
        <span className="lux-portfolio-lux__orb lux-portfolio-lux__orb--b" />
        {isExecutive ? <span className="lux-portfolio-lux__orb lux-portfolio-lux__orb--c" /> : null}
      </div>
      <LuxModuleIntro meta={meta} actions={heroActions || undefined} />

      <div className="lux-register-page__body">
        {kpiCards.length ? (
          <GovernanceKpiStrip cards={kpiCards} loading={loading} className="lux-portfolio-lux__kpi-strip" />
        ) : null}

        {insights.length ? <AdminInsightStrip insights={insights} className="lux-portfolio-lux__insights" /> : null}

        <div className={classNames("lux-portfolio-lux__content", isExecutive && "lux-portfolio-lux__content--executive")}>
          {children}
        </div>
      </div>
    </div>
  );
}
