import React from "react";
import classNames from "classnames/bind";
import {
  getBenchStatusLabel,
  getBenchStatusTone,
  getEmployeeInitials,
  isRolloffWithinDays,
} from "config/resource-planning.utils";

export default function BenchRegister({ rows, loading, onSelect }) {
  if (loading) {
    return null;
  }

  return (
    <div className="lux-bench-register-wrap">
      <table className="lux-bench-register">
        <thead>
          <tr>
            <th>Consultant</th>
            <th>Role</th>
            <th>Status</th>
            <th>Availability</th>
            <th>Last project</th>
            <th>Roll-off / available</th>
            <th>Skills</th>
            <th>Days on bench</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => {
            const statusTone = getBenchStatusTone(row.status);
            const isSoon = row.status === "ROLLING_OFF" && isRolloffWithinDays(row, 14);
            const isLongBench = row.status === "ON_BENCH" && row.daysOnBench >= 14;
            return (
              <tr
                key={row.id}
                className={classNames("lux-bench-register__row", {
                  "is-soon": isSoon,
                  "is-long": isLongBench,
                  "is-partial": row.status === "PARTIAL",
                })}
              >
                <td>
                  <button type="button" className="lux-bench-register__person" onClick={() => onSelect(row)}>
                    <span className="lux-bench-register__avatar" aria-hidden="true">
                      {getEmployeeInitials(row.employeeName)}
                    </span>
                    <span className="lux-bench-register__person-copy">
                      <strong>{row.employeeName}</strong>
                      <span className="lux-bench-register__meta">{row.department || row.location || "—"}</span>
                    </span>
                  </button>
                </td>
                <td>{row.role || "—"}</td>
                <td>
                  <span className={classNames("lux-doc-badge", `is-${statusTone}`)}>
                    {getBenchStatusLabel(row.status)}
                  </span>
                </td>
                <td>
                  <span className={classNames("lux-bench-register__avail", `is-${statusTone}`)}>
                    {row.availabilityPct}%
                  </span>
                </td>
                <td>
                  <span className="lux-bench-register__project">{row.lastProjectName || "—"}</span>
                </td>
                <td>
                  <span className="lux-bench-register__date">
                    {row.lastProjectEndDate || row.availableFrom || "—"}
                  </span>
                </td>
                <td>
                  <span className="lux-bench-register__skills">{row.primarySkills || "—"}</span>
                </td>
                <td>
                  <span
                    className={classNames("lux-bench-register__days", {
                      "is-alert": isLongBench,
                    })}
                  >
                    {row.daysOnBench > 0 ? row.daysOnBench : "—"}
                  </span>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
