/**
 * Factory for Module-console luxury page shells.
 */
import React from "react";
import classNames from "classnames/bind";
import { useReportPageDataSource } from "views/common/PageChromeContext";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import LuxKpiStrip from "views/common/fragments/LuxKpiStrip";

/**
 * @param {object} options
 * @param {string} options.rootClass - e.g. "lux-recruiting-lux"
 * @param {object} options.defaultMeta - LuxModuleIntro meta defaults
 */
export function createModuleLuxPage({ rootClass, defaultMeta }) {
  return function ModuleLuxPage({
    pageMeta,
    dataSource,
    heroActions,
    kpiCards,
    loading,
    testId,
    children,
    className,
  }) {
    useReportPageDataSource(dataSource);
    const meta = { ...(defaultMeta || {}), ...(pageMeta || {}) };

    return (
      <div
        className={classNames(
          "lux-register-page",
          rootClass,
          meta.tone && `is-${meta.tone}`,
          className
        )}
        {...(testId ? { "data-testid": testId } : {})}
      >
        <div className={`${rootClass}__ambient`} aria-hidden="true">
          <span className={`${rootClass}__orb ${rootClass}__orb--a`} />
          <span className={`${rootClass}__orb ${rootClass}__orb--b`} />
        </div>
        <LuxModuleIntro meta={meta} actions={heroActions || undefined} />

        <div className="lux-register-page__body">
          {kpiCards && kpiCards.length ? (
            <LuxKpiStrip cards={kpiCards} loading={loading} className={`${rootClass}__kpi-strip`} />
          ) : null}
          <div className={`${rootClass}__content`}>{children}</div>
        </div>
      </div>
    );
  };
}

export function LuxModulePanel({ title, meta, icon, accent, children, actions, className }) {
  return (
    <section className={classNames("lux-hrms-dash__panel", accent && `is-${accent}`, className)}>
      <header className="lux-hrms-dash__panel-head">
        <div className="d-flex align-items-start">
          {icon ? <i className={`${icon} mr-2 mt-1`} aria-hidden="true" /> : null}
          <div>
            <h2 className="lux-hrms-dash__panel-title">{title}</h2>
            {meta ? <p className="lux-hrms-dash__panel-sub">{meta}</p> : null}
          </div>
        </div>
        {actions ? <div className="lux-hrms-dash__panel-actions">{actions}</div> : null}
      </header>
      <div className="lux-hrms-dash__panel-body">{children}</div>
    </section>
  );
}
