import React, { Component } from "react";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isProjectGovernanceEnabled } from "config/project-governance.config";
import {
  buildDependencyValidationReport,
  buildMilestoneInsights,
  buildMilestoneMetrics,
  buildProjectOptions,
  computeCriticalPathAnalysis,
  enrichMilestonesWithScheduleAnalysis,
  filterMilestones,
  MILESTONE_STATUS_FILTER_OPTIONS,
} from "config/project-governance.utils";
import { projectGovernanceService } from "_services/projectGovernance.service";
import { GOVERNANCE_PAGE_IDS, getGovernanceQuickLinks } from "config/project-governance-nav.config";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { ResourcesActionButton } from "views/resources/components/ResourcesLuxShared";
import GovernanceLuxPage, {
  GovernanceLuxFilters,
  GovernanceLuxPanel,
} from "views/project/components/ProjectGovernanceLuxShared";
import DependencyRegister from "views/project/components/DependencyRegister";
import DependencyValidationPanel from "views/project/components/DependencyValidationPanel";
import GovernanceAiImportPanel from "views/project/components/GovernanceAiImportPanel";
import MilestoneDrawer from "views/project/components/MilestoneDrawer";
import MilestoneRegister from "views/project/components/MilestoneRegister";

class ProjectMilestonesPage extends Component {
  state = {
    milestones: [],
    dependencies: [],
    loading: true,
    loadError: null,
    dataSource: null,
    query: "",
    statusFilter: "ALL",
    projectFilter: "ALL",
    drawerOpen: false,
    selectedMilestone: null,
    creatingDependency: false,
    dependencyError: null,
    aiImportRefreshKey: 0,
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Milestones");
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const [milestonesRes, dependenciesRes] = await Promise.all([
        projectGovernanceService.listMilestones(),
        projectGovernanceService.listDependencies(),
      ]);
      this.setState({
        milestones: milestonesRes.payload || [],
        dependencies: dependenciesRes.payload || [],
        loading: false,
        dataSource: milestonesRes.source || null,
      });
    } catch (e) {
      this.setState({
        loading: false,
        loadError: "Unable to load milestones.",
        milestones: [],
        dependencies: [],
      });
    }
  };

  openDrawer = (milestone) => {
    this.setState({ drawerOpen: true, selectedMilestone: milestone });
  };

  closeDrawer = () => {
    this.setState({ drawerOpen: false, selectedMilestone: null });
  };

  handleSaveMilestone = async (milestoneId, payload) => {
    await projectGovernanceService.updateMilestone(milestoneId, payload);
    await this.loadData();
  };

  handleCreateDependency = async (payload) => {
    this.setState({ creatingDependency: true, dependencyError: null });
    try {
      await projectGovernanceService.createDependency(payload);
      await this.loadData();
      this.setState({ creatingDependency: false, dependencyError: null });
    } catch (e) {
      this.setState({
        creatingDependency: false,
        dependencyError: (e && e.message) || "Unable to create dependency.",
      });
      throw e;
    }
  };

  render() {
    if (!isProjectGovernanceEnabled()) {
      return <PersonaAccessDenied featureLabel="Project milestones" />;
    }

    const {
      loading,
      loadError,
      dataSource,
      query,
      statusFilter,
      projectFilter,
      milestones,
      dependencies,
      drawerOpen,
      selectedMilestone,
      creatingDependency,
      dependencyError,
    } = this.state;

    const enrichedMilestones = enrichMilestonesWithScheduleAnalysis(milestones, dependencies, {
      projectId: projectFilter,
    });
    const filtered = filterMilestones(enrichedMilestones, {
      query,
      status: statusFilter,
      projectId: projectFilter === "ALL" ? undefined : projectFilter,
    });
    const metrics = buildMilestoneMetrics(milestones, dependencies, { projectId: projectFilter });
    const validationIssues = buildDependencyValidationReport(milestones, dependencies, {
      projectId: projectFilter,
    });
    const analysis = computeCriticalPathAnalysis(milestones, dependencies, { projectId: projectFilter });
    const insights = buildMilestoneInsights(metrics, milestones, { validationIssues });
    const projectOptions = buildProjectOptions(milestones);
    const scopedDependencies =
      projectFilter === "ALL"
        ? dependencies
        : dependencies.filter((dep) => !dep.projectId || dep.projectId === projectFilter);

    const kpiCards = [
      { id: "total", label: "Milestones", value: metrics.total, tone: "blue", icon: "fe fe-flag" },
      { id: "complete", label: "Complete", value: metrics.complete, tone: "green", icon: "fe fe-check-circle" },
      { id: "progress", label: "Avg progress", value: `${metrics.avgComplete}%`, tone: "violet", icon: "fe fe-percent" },
      { id: "critical", label: "Critical path", value: metrics.onCriticalPath, tone: "rose", icon: "fe fe-git-branch" },
      { id: "deps", label: "Dependencies", value: metrics.dependencyCount, tone: "amber", icon: "fe fe-link" },
    ];

    return (
      <GovernanceLuxPage
        pageId={GOVERNANCE_PAGE_IDS.MILESTONES}
        dataSource={dataSource}
        loading={loading}
        insights={insights}
        quickLinks={getGovernanceQuickLinks(GOVERNANCE_PAGE_IDS.MILESTONES)}
        kpiCards={kpiCards}
        heroActions={
          <ResourcesActionButton to="/project/timeline" icon="fe fe-bar-chart-2" variant="ghost">
            Open timeline
          </ResourcesActionButton>
        }
      >
        <GovernanceAiImportPanel
          refreshKey={this.state.aiImportRefreshKey}
          projectId={projectFilter !== "ALL" ? projectFilter : undefined}
          projectName={
            projectFilter !== "ALL"
              ? (projectOptions.find((row) => row.id === projectFilter) || {}).label
              : undefined
          }
          showGenerate={projectFilter !== "ALL"}
          onImported={() => {
            this.loadData();
            this.setState((prev) => ({ aiImportRefreshKey: prev.aiImportRefreshKey + 1 }));
          }}
        />

        <GovernanceLuxPanel
          title="Milestone register"
          meta={`${filtered.length} visible · ${metrics.completionRate}% complete`}
          icon="fe fe-flag"
          accent="indigo"
        >
          <GovernanceLuxFilters>
            <label className="lux-gov-filters__search">
              <i className="fe fe-search" aria-hidden="true" />
              <input
                type="search"
                placeholder="Search milestone, project, or owner"
                value={query}
                onChange={(e) => this.setState({ query: e.target.value })}
              />
            </label>
            <select
              className="lux-gov-filters__select"
              value={projectFilter}
              onChange={(e) => this.setState({ projectFilter: e.target.value })}
            >
              {projectOptions.map((option) => (
                <option key={option.id} value={option.id}>
                  {option.label}
                </option>
              ))}
            </select>
            <div className="lux-gov-filters__chips" role="tablist" aria-label="Milestone status">
              {MILESTONE_STATUS_FILTER_OPTIONS.map((option) => (
                <button
                  key={option.id}
                  type="button"
                  role="tab"
                  aria-selected={statusFilter === option.id}
                  className={classNames("lux-gov-filters__chip", { "is-active": statusFilter === option.id })}
                  onClick={() => this.setState({ statusFilter: option.id })}
                >
                  {option.label}
                </button>
              ))}
            </div>
          </GovernanceLuxFilters>

          {loadError ? (
            <LuxRegisterEmptyState title="Unable to load milestones" copy={loadError} onRetry={this.loadData} />
          ) : null}

          {!loadError && !loading && filtered.length === 0 ? (
            <LuxRegisterEmptyState
              title="No milestones match"
              copy="Adjust filters or add milestones once project delivery plans are imported."
            />
          ) : null}

          <MilestoneRegister rows={filtered} loading={loading} onSelect={this.openDrawer} />
        </GovernanceLuxPanel>

        <GovernanceLuxPanel
          title="Dependencies & critical path"
          meta={`${analysis.criticalMilestoneIds.length} critical milestones · ${validationIssues.length} checks`}
          icon="fe fe-shuffle"
          accent="blue"
        >
          <DependencyValidationPanel
            milestones={milestones}
            dependencies={dependencies}
            projectFilter={projectFilter}
            canEdit
            creating={creatingDependency}
            createError={dependencyError}
            onCreateDependency={this.handleCreateDependency}
          />
          <DependencyRegister
            rows={scopedDependencies}
            criticalDependencyIds={analysis.criticalDependencyIds}
            validationIssues={validationIssues}
            loading={loading}
          />
        </GovernanceLuxPanel>

        <MilestoneDrawer
          open={drawerOpen}
          milestone={selectedMilestone}
          onClose={this.closeDrawer}
          onSave={this.handleSaveMilestone}
        />
      </GovernanceLuxPage>
    );
  }
}

export default ProjectMilestonesPage;
