import React, { Component } from "react";
import Menu from "./fragments/Menu";
import BrandNameLogo from "./fragments/BrandNameLogo";
import envConfig from "env.config";
import { commonUtils } from "_helpers";
import { SIDEBAR_GROUPS, isSidebarGroupVisible } from "config/sidebar-menu.config";
import { resolveActivePersona, PERSONA_CONTEXT_CHANGED } from "config/persona-navigation.utils";
import { PersonaContext } from "context/PersonaContextProvider";
import ModuleMenuRail from "components/navigation/ModuleMenuRail";
import ModuleContextMenu from "components/navigation/ModuleContextMenu";
import {
  findSidebarGroupById,
  getVisibleSidebarGroups,
  isModuleMenuRailLayoutEnabled,
  resolveActiveModuleId,
} from "config/module-rail.utils";

class PageLeftMenu extends Component {
  state = {
    selectedModuleId: null,
  };

  componentDidMount() {
    this._settingsListener = () => {
      this.setState({ selectedModuleId: null });
    };
    this._personaListener = () => {
      this.setState({ selectedModuleId: null });
    };
    window.addEventListener("lux-ui-settings-changed", this._settingsListener);
    window.addEventListener(PERSONA_CONTEXT_CHANGED, this._personaListener);
  }

  componentWillUnmount() {
    window.removeEventListener("lux-ui-settings-changed", this._settingsListener);
    window.removeEventListener(PERSONA_CONTEXT_CHANGED, this._personaListener);
  }

  componentDidUpdate(prevProps) {
    if (prevProps.location.pathname !== this.props.location.pathname) {
      this.setState({ selectedModuleId: null });
    }
  }

  getCompanyLabel = () => {
    const user = commonUtils.getCurrentUser && commonUtils.getCurrentUser();
    const teamName = user && user.defaultUserTeamDetails && user.defaultUserTeamDetails.name;
    return teamName ? teamName : (envConfig.APP_LABEL || "Workspace");
  };

  handleModuleSelect = (moduleId) => {
    this.setState({ selectedModuleId: moduleId });
  };

  resolveActiveModule = (visibleGroups, menuAccessControl, activePersona) => {
    const { selectedModuleId } = this.state;
    if (
      selectedModuleId &&
      visibleGroups.some((group) => group.id === selectedModuleId)
    ) {
      return selectedModuleId;
    }
    return resolveActiveModuleId(
      this.props.location.pathname,
      menuAccessControl,
      activePersona
    );
  };

  renderCollapsibleSidebar(menuAccessControl, activePersona) {
    const visibleGroups = SIDEBAR_GROUPS.filter((group) =>
      isSidebarGroupVisible(group, menuAccessControl, activePersona)
    );

    return (
      <nav id="left-sidebar-nav" className="sidebar-nav lux-sidebar__nav">
        <ul className="metismenu lux-nav">
          <li className="g_heading lux-nav__heading">Modules</li>
          {visibleGroups.map((group) => (
            <Menu
              key={group.id}
              {...this.props}
              menuName={group.menuName}
              icon={group.icon}
              menuItems={group.items}
              pathPrefixes={group.pathPrefixes}
              pathExclude={group.pathExclude}
              menuAccessControl={menuAccessControl}
              activePersona={activePersona}
            />
          ))}
        </ul>
      </nav>
    );
  }

  renderModuleRailSidebar(menuAccessControl, activePersona) {
    const visibleGroups = getVisibleSidebarGroups(menuAccessControl, activePersona);
    const activeModuleId = this.resolveActiveModule(
      visibleGroups,
      menuAccessControl,
      activePersona
    );
    const activeGroup = findSidebarGroupById(activeModuleId);

    return (
      <div id="left-sidebar-nav" className="sidebar-nav lux-sidebar__nav lux-sidebar__nav--split">
        <div className="lux-sidebar__split-body">
          <ModuleMenuRail
            groups={visibleGroups}
            activeModuleId={activeModuleId}
            onSelectModule={this.handleModuleSelect}
          />
          <ModuleContextMenu
            {...this.props}
            group={activeGroup}
            menuAccessControl={menuAccessControl}
            activePersona={activePersona}
          />
        </div>
      </div>
    );
  }

  renderSidebar(menuAccessControl, activePersona) {
    const useModuleRail = isModuleMenuRailLayoutEnabled();

    return (
      <div
        id="left-sidebar"
        className={`sidebar no-print lux-sidebar${useModuleRail ? " lux-sidebar--module-rail" : ""}`}
        data-tour="lux-sidebar"
      >
        <div className="lux-sidebar__top">
          <div className="lux-sidebar__brand lux-sidebar__brand--logo">
            <BrandNameLogo />
          </div>
        </div>

        <div className="lux-company-chip">
          <span className="lux-company-chip__icon" aria-hidden="true">
            ✦
          </span>
          <span className="lux-company-chip__label">{this.getCompanyLabel()}</span>
        </div>

        {useModuleRail
          ? this.renderModuleRailSidebar(menuAccessControl, activePersona)
          : this.renderCollapsibleSidebar(menuAccessControl, activePersona)}
      </div>
    );
  }

  render() {
    const { menuAccessControl: propsMenuAccess } = this.props;

    return (
      <PersonaContext.Consumer>
        {(personaCtx) => {
          const menuAccessControl = (personaCtx && personaCtx.menuAccessControl) || propsMenuAccess;
          const activePersona =
            (personaCtx && personaCtx.activePersona) ||
            resolveActivePersona(menuAccessControl);
          return this.renderSidebar(menuAccessControl, activePersona);
        }}
      </PersonaContext.Consumer>
    );
  }
}

export default PageLeftMenu;
