import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import LuxRegisterListSkeletonRows from "views/common/fragments/LuxRegisterListSkeletonRows";
import AccountDirectoryRow from "./AccountDirectoryRow";
import UserTeamDirectoryRow from "./UserTeamDirectoryRow";

class AccountsDirectoryList extends PureComponent {
  render() {
    const {
      items,
      itemRows,
      parentItem,
      isLoading,
      viewName,
      viewByAccounts,
      hierarchyEnabled,
      permission,
      userTeamsPermission,
      confirmRemoveId,
      onSelectItem,
      onOpenDetail,
      onRemoveRequest,
      onDetach,
      isUserTeamsView,
    } = this.props;

    const rows =
      itemRows ||
      (items && parentItem ? items.map((item) => ({ item, parentItem })) : []);

    return (
      <div
        className={classNames("lux-acct-dir-list", { "is-loading": isLoading })}
        role="list"
        aria-label="Account directory"
        aria-busy={isLoading || undefined}
      >
        {!isLoading && rows.length > 0 && (
          <header className="lux-acct-dir-list__head" aria-hidden="true">
            <span className="lux-acct-dir-list__head-col lux-acct-dir-list__head-col--main">
              Record
            </span>
            <span className="lux-acct-dir-list__head-col">Counts</span>
            <span className="lux-acct-dir-list__head-col">Actions</span>
          </header>
        )}

        {isLoading && (
          <LuxRegisterListSkeletonRows variant="acctdir" rowCount={12} cellHeight={12} />
        )}

        {!isLoading &&
          rows.map(({ item, parentItem: rowParent }) => (
            <div key={item.id} className="lux-acct-dir-list__item" role="listitem">
              {isUserTeamsView ? (
                <UserTeamDirectoryRow
                  item={item}
                  parentItem={rowParent}
                  hierarchyEnabled={hierarchyEnabled !== false}
                  onSelect={() => onSelectItem(item, "ACCOUNT", 0)}
                  onOpenDetail={() => onOpenDetail(item, rowParent)}
                />
              ) : (
                <AccountDirectoryRow
                  item={item}
                  parentItem={rowParent}
                  viewName={viewName}
                  viewByAccounts={viewByAccounts}
                  hierarchyEnabled={hierarchyEnabled !== false}
                  permission={permission}
                  confirmRemoveId={confirmRemoveId}
                  onSelect={() => onSelectItem(item, viewName, 2)}
                  onOpenDetail={() => onOpenDetail(item, rowParent)}
                  onRemoveRequest={onRemoveRequest}
                  onDetach={onDetach}
                />
              )}
            </div>
          ))}
      </div>
    );
  }
}

export default AccountsDirectoryList;
