import React from "react";
import classNames from "classnames/bind";
import {
  isTimesheetApproved,
  isTimesheetPayrollProcessed,
  isTimesheetReopened,
  isTimesheetWeekLocked,
  wasTimesheetPreviouslyApproved,
} from "_helpers/timesheetWorkflow.utils";

function TimesheetLockBanner({
  timeSheetData,
  canUnlock,
  unlockInProgress,
  onUnlock,
  canReopen,
  reopenInProgress,
  onReopen,
}) {
  const locked = timeSheetData && isTimesheetWeekLocked(timeSheetData);
  const approved = timeSheetData && isTimesheetApproved(timeSheetData);
  const reopened =
    timeSheetData &&
    isTimesheetReopened(timeSheetData) &&
    wasTimesheetPreviouslyApproved(timeSheetData);

  if (!locked && !approved && !reopened) {
    return null;
  }

  const payrollProcessed = isTimesheetPayrollProcessed(timeSheetData);
  const showReopen = approved && canReopen && onReopen;
  const showUnlock = locked && canUnlock && onUnlock;
  const inProgress = approved ? reopenInProgress : unlockInProgress;
  const onAction = approved ? onReopen : onUnlock;
  const canAct = approved ? showReopen : showUnlock;

  let ariaLabel = "Timesheet lock notice";
  let title = "Timesheet locked";
  let body = "This week is locked for compliance. Edits are blocked until a manager reopens it.";
  let icon = "fe-lock";

  if (payrollProcessed) {
    ariaLabel = "Timesheet payroll notice";
    title = "Payroll processed — week locked";
    body = "This week has been included in payroll. Edits are blocked until a manager reopens it.";
    icon = "fe-dollar-sign";
  } else if (reopened) {
    ariaLabel = "Timesheet reopened notice";
    title = "Previously approved timesheet reopened";
    body =
      "This week was approved earlier and has been reopened for corrections. Update hours, save your draft, then resubmit for approval.";
    icon = "fe-rotate-ccw";
  } else if (approved) {
    ariaLabel = "Timesheet approved notice";
    title = "Timesheet approved";
    body = canAct
      ? "Editing and Submit are blocked. Reopen this week to correct hours, then save and resubmit."
      : "Editing and Submit are blocked. Only the person who approved this timesheet can reopen it.";
    icon = "fe-check-circle";
  }

  return (
    <section
      className={classNames("lux-ts-lock-banner", {
        "is-payroll": payrollProcessed,
        "is-approved": approved && !locked,
        "is-reopened": reopened && !locked && !approved,
      })}
      aria-label={ariaLabel}
      data-testid="timesheet-lock-banner"
    >
      <div className="lux-ts-lock-banner__icon" aria-hidden="true">
        <i className={`fe ${icon}`} />
      </div>
      <div className="lux-ts-lock-banner__copy">
        <strong>{title}</strong>
        <p>{body}</p>
      </div>
      {canAct && (
        <button
          type="button"
          className={classNames("lux-ts-lock-banner__btn", { "is-loading": inProgress })}
          disabled={inProgress}
          onClick={onAction}
          data-testid="timesheet-reopen-week"
        >
          Reopen week
        </button>
      )}
    </section>
  );
}

export default TimesheetLockBanner;
