import React, { Component } from "react";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { ADMIN_PAGE_META } from "config/admin-page-meta.config";
import { isRbacAdminEnabled } from "config/role-permission.config";
import {
  filterRolePermissionProfiles,
  getPersonaMeta,
  getRoleCoverageStats,
} from "config/role-permission.utils";
import { rolePermissionService } from "_services/rolePermission.service";
import {
  listCatalogPagesForPersonaAdmin,
  loadOrgAccessPolicyFromAppConfig,
  loadPersonaPageMapFromAppConfig,
  savePersonaPageMap,
} from "config/persona-page-map.config";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import RolePermissionRegister from "views/admin/components/RolePermissionRegister";
import RolePermissionDetailPanel from "views/admin/components/RolePermissionDetailPanel";
import RolePermissionOverview from "views/admin/components/RolePermissionOverview";
import {
  AdminActionButton,
  AdminPanelLink,
  AdminLuxPage,
} from "views/admin/components/AdminLuxShared";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import { getLuxInlineAlertProps } from "_helpers/apiError.utils";

const PERSONA_FILTERS = ["ALL", "ADMIN", "HR_ADMIN", "MANAGER", "EMPLOYEE", "EXECUTIVE"];

class RolePermissionPage extends Component {
  state = {
    roles: [],
    loading: true,
    loadError: null,
    dataSource: null,
    statusFilter: "ALL",
    personaFilter: "ALL",
    query: "",
    selectedId: null,
    savingKey: null,
    pageMap: {},
    pageMapRevision: 0,
    catalogPages: listCatalogPagesForPersonaAdmin(),
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Roles & permissions");
    this.loadRoles();
    this.loadPageMap();
  }

  loadPageMap = async () => {
    try {
      const policy = await loadOrgAccessPolicyFromAppConfig();
      const map = (policy && policy.pagePersonaMap) || (await loadPersonaPageMapFromAppConfig()) || {};
      this.setState((prev) => ({
        pageMap: map,
        pageMapRevision: prev.pageMapRevision + 1,
      }));
    } catch (e) {
      /* local/empty map is fine; persona editor falls back gracefully */
    }
  };

  loadRoles = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await rolePermissionService.listRoles();
      if (result.source === "api-error") {
        this.setState({
          loading: false,
          loadError: getLuxInlineAlertProps(
            result.error,
            "Unable to load role permission profiles from the live API."
          ),
          roles: [],
          dataSource: result.source,
        });
        return;
      }
      const roles = result.payload || [];
      this.setState({
        roles,
        loading: false,
        dataSource: result.source || null,
        selectedId: this.state.selectedId || (roles[0] && roles[0].id) || null,
        loadError: null,
      });
    } catch (e) {
      this.setState({
        loading: false,
        loadError: getLuxInlineAlertProps(e, "Unable to load role permission profiles."),
        roles: [],
        dataSource: "api-error",
      });
    }
  };

  handleToggle = async (moduleKey, flagKey, enabled) => {
    const { selectedId } = this.state;
    if (!selectedId) return;
    const savingKey = `${moduleKey}:${flagKey}`;
    this.setState({ savingKey, loadError: null });
    try {
      const result = await rolePermissionService.updatePermission(selectedId, moduleKey, flagKey, enabled);
      const updated = result.payload;
      if (!updated) {
        throw new Error("Update returned empty role");
      }
      this.setState((prev) => ({
        roles: prev.roles.map((row) => (row.id === selectedId ? updated : row)),
        savingKey: null,
      }));
    } catch (e) {
      this.setState({
        savingKey: null,
        loadError: getLuxInlineAlertProps(
          e,
          "Unable to save permission change. Check Application Config access."
        ),
      });
    }
  };

  handleSetStatus = async (status) => {
    const { selectedId } = this.state;
    if (!selectedId) return;
    this.setState({ loadError: null });
    try {
      const result = await rolePermissionService.setRoleStatus(selectedId, status);
      const updated = result.payload;
      if (!updated) {
        throw new Error("Status update returned empty role");
      }
      this.setState((prev) => ({
        roles: prev.roles.map((row) => (row.id === selectedId ? updated : row)),
      }));
    } catch (e) {
      this.setState({
        loadError: getLuxInlineAlertProps(e, "Unable to update role status."),
      });
    }
  };

  handleSavePersonaAccess = async ({ personaModules, pagePersonaMap, dirtyPersonas, dirtyPages }) => {
    const { selectedId } = this.state;
    if (!selectedId) return;
    this.setState({ savingKey: "personaAccess", loadError: null });
    try {
      let updatedRole = null;
      if (dirtyPersonas !== false && personaModules) {
        const result = await rolePermissionService.updatePersonaModules(selectedId, personaModules);
        updatedRole = result.payload;
        if (!updatedRole) {
          throw new Error("Persona update returned empty role");
        }
      }
      if (dirtyPages && pagePersonaMap) {
        const mapResult = await savePersonaPageMap(pagePersonaMap);
        this.setState((prev) => ({
          pageMap: mapResult.payload || pagePersonaMap,
          pageMapRevision: prev.pageMapRevision + 1,
        }));
      } else {
        this.setState((prev) => ({
          pageMapRevision: prev.pageMapRevision + 1,
        }));
      }
      this.setState((prev) => ({
        roles: updatedRole
          ? prev.roles.map((row) => (row.id === selectedId ? updatedRole : row))
          : prev.roles,
        savingKey: null,
      }));
    } catch (e) {
      this.setState({
        savingKey: null,
        loadError: getLuxInlineAlertProps(
          e,
          "Unable to save persona access. Check Application Config access."
        ),
      });
      throw e;
    }
  };

  getFilteredRoles = () => {
    const { roles, statusFilter, personaFilter, query } = this.state;
    return filterRolePermissionProfiles(roles, {
      status: statusFilter,
      persona: personaFilter,
      query,
    });
  };

  getSelectedRole = () => {
    const { roles, selectedId } = this.state;
    return roles.find((row) => row.id === selectedId) || null;
  };

  render() {
    if (!isRbacAdminEnabled()) {
      return (
        <PersonaAccessDenied
          moduleName="Roles & permissions"
          reason="RBAC administration is not enabled for your organization."
        />
      );
    }

    const { loading, loadError, dataSource, statusFilter, personaFilter, query } = this.state;
    const filteredRoles = this.getFilteredRoles();
    const selectedRole = this.getSelectedRole();
    const selectedMeta = selectedRole ? getPersonaMeta(selectedRole.persona) : null;
    const selectedCoverage = selectedRole ? getRoleCoverageStats(selectedRole) : null;

    return (
      <AdminLuxPage
        pageMeta={ADMIN_PAGE_META.roles}
        dataSource={dataSource}
        loading={loading}
        testId="page-admin-roles"
        className="lux-register-page lux-rbac-page"
        heroActions={
          <AdminActionButton icon="fe fe-refresh-cw" onClick={this.loadRoles} disabled={loading}>
            Refresh
          </AdminActionButton>
        }
      >
        {loadError ? (
          <div className="lux-employee-360__error lux-rbac__error" role="alert">
            {typeof loadError === "string" ? (
              <LuxInlineAlert message={loadError} />
            ) : (
              <LuxInlineAlert {...loadError} />
            )}
            <AdminActionButton variant="ghost" onClick={this.loadRoles}>
              Retry
            </AdminActionButton>
          </div>
        ) : null}

        <RolePermissionOverview roles={this.state.roles} selectedRole={selectedRole} loading={loading} />

        <section className="lux-rbac-atelier" data-testid="rbac-role-access">
          <header className="lux-rbac-atelier__masthead">
            <div className="lux-rbac-atelier__masthead-main">
              <span className="lux-rbac-atelier__mark" aria-hidden="true">
                <i className="fe fe-shield" />
              </span>
              <div>
                <p className="lux-rbac-atelier__eyebrow">Permission matrix</p>
                <h2 className="lux-rbac-atelier__title">Role access</h2>
                <p className="lux-rbac-atelier__lede">
                  Select a profile, tune persona access, then open Advanced only when a module flag
                  blocks a page.
                </p>
              </div>
            </div>
            <div className="lux-rbac-atelier__masthead-aside">
              <AdminPanelLink to="/admin/appconfig">Application config</AdminPanelLink>
              <span className="lux-rbac-atelier__count">
                <strong>{filteredRoles.length}</strong>
                <em>shown</em>
              </span>
            </div>
          </header>

          <div className="lux-rbac-atelier__toolbar">
            <div className="lux-rbac-atelier__search">
              <i className="fe fe-search" aria-hidden="true" />
              <input
                type="search"
                className="lux-rbac-atelier__search-input"
                placeholder="Search role, code, or persona"
                value={query}
                onChange={(e) => this.setState({ query: e.target.value })}
              />
            </div>
            {selectedRole && selectedMeta && selectedCoverage ? (
              <span
                className={classNames(
                  "lux-rbac-atelier__focus",
                  selectedMeta.tone && `is-${selectedMeta.tone}`
                )}
              >
                <i className={selectedMeta.icon} aria-hidden="true" />
                <span>
                  <strong>{selectedRole.name}</strong>
                  <em>{selectedCoverage.coverage}% coverage</em>
                </span>
              </span>
            ) : null}
            <div className="lux-rbac-atelier__filters">
              <div className="lux-rbac-atelier__filter">
                <span>Status</span>
                <div className="lux-rbac-atelier__chips" role="group" aria-label="Filter by status">
                  {["ALL", "Active", "Inactive"].map((value) => (
                    <button
                      key={value}
                      type="button"
                      className={classNames("lux-rbac-atelier__chip", {
                        "is-active": statusFilter === value,
                      })}
                      onClick={() => this.setState({ statusFilter: value })}
                    >
                      {value === "ALL" ? "All" : value}
                    </button>
                  ))}
                </div>
              </div>
              <div className="lux-rbac-atelier__filter">
                <span>Persona</span>
                <div className="lux-rbac-atelier__chips" role="group" aria-label="Filter by persona">
                  {PERSONA_FILTERS.map((value) => (
                    <button
                      key={value}
                      type="button"
                      className={classNames("lux-rbac-atelier__chip", {
                        "is-active": personaFilter === value,
                      })}
                      onClick={() => this.setState({ personaFilter: value })}
                    >
                      {value === "ALL" ? "All" : value.replace("_", " ")}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>

          <div className="lux-rbac-atelier__split">
            <div className="lux-rbac-atelier__rail">
              <div className="lux-rbac-atelier__pane-label">
                <span>Profiles</span>
                <em>{filteredRoles.length}</em>
              </div>
              {loading ? (
                <LuxRegisterEmptyState title="Loading roles" description="Fetching permission profiles." />
              ) : filteredRoles.length === 0 ? (
                <LuxRegisterEmptyState title="No roles match" description="Adjust filters or search." />
              ) : (
                <RolePermissionRegister
                  roles={filteredRoles}
                  selectedId={this.state.selectedId}
                  onSelect={(role) => this.setState({ selectedId: role.id })}
                />
              )}
            </div>
            <div className="lux-rbac-atelier__stage">
              <div className="lux-rbac-atelier__pane-label">
                <span>Editor</span>
                <em>{selectedRole ? selectedRole.name : "Awaiting selection"}</em>
              </div>
              <RolePermissionDetailPanel
                role={selectedRole}
                savingKey={this.state.savingKey}
                readOnly={false}
                onToggle={this.handleToggle}
                onSetStatus={this.handleSetStatus}
                pageMap={this.state.pageMap}
                pageMapRevision={this.state.pageMapRevision}
                catalogPages={this.state.catalogPages}
                onSavePersonaAccess={this.handleSavePersonaAccess}
              />
            </div>
          </div>
        </section>
      </AdminLuxPage>
    );
  }
}

export default RolePermissionPage;
