/**
 * EH23 — Admin jobs status FE service. Fail closed when flag on.
 */
import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";
import { shouldUseAdminJobsApi } from "config/admin-jobs.config";

export const adminJobsService = {
  getJobsStatus,
};

const API_ERROR = { payload: null, source: "api-error" };

async function getJobsStatus() {
  if (!shouldUseAdminJobsApi()) {
    return { ...API_ERROR, reason: "flag-off" };
  }
  try {
    const response = await axiosUtils.getWithParam(`${urlConfig.ADMIN_JOBS_API_PATH}/status`, {
      userTeamId: commonUtils.getCurrentUserTeamId(),
    });
    const payload = response && response.payload ? response.payload : response;
    if (payload) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    console.warn("[AdminJobs] API unavailable.", e);
    return { ...API_ERROR, error: e };
  }
}
