import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import CountUp from "react-countup";
import Skeleton from "react-loading-skeleton";
import LuxSummaryEyebrow from "views/common/fragments/LuxSummaryEyebrow";
import {
  readSummaryExpanded,
  writeSummaryExpanded,
  getSummaryToggleLabel,
} from "_helpers/summaryExpandedStorage";

const STORAGE_KEY = "famstack-notes-summary-expanded";

const STATUS_FILTERS = [
  { id: "ALL", label: "All" },
  { id: "OPEN", label: "Open" },
  { id: "DONE", label: "Done" },
];

class NotesPageSummary extends PureComponent {
  constructor(props) {
    super(props);
    this.state = { expanded: readSummaryExpanded(STORAGE_KEY) };
  }

  toggleExpanded = () => {
    this.setState(
      (prev) => ({ expanded: !prev.expanded }),
      () => writeSummaryExpanded(STORAGE_KEY, this.state.expanded)
    );
  };

  buildContextLine = (summary, visibleCount, filterText) => {
    const parts = [];
    parts.push(`${summary.total} notes · ${summary.pending} open · ${summary.completed} done`);
    if (visibleCount !== summary.total) {
      parts.push(`${visibleCount} shown`);
    }
    if (filterText) {
      parts.push(`matching “${filterText}”`);
    }
    return parts.join(" · ");
  };

  renderFilterChips = (statusFilter, compact) => (
    <div
      className={classNames("lux-bid-summary__filters", {
        "lux-bid-summary__filters--compact": compact,
      })}
      role="group"
      aria-label="Filter notes by status"
    >
      {STATUS_FILTERS.map((option) => (
        <button
          key={option.id}
          type="button"
          className={classNames("lux-bid-summary__filter-chip", {
            "is-active": statusFilter === option.id,
          })}
          onClick={() => this.props.onStatusFilter && this.props.onStatusFilter(option.id)}
        >
          {option.label}
        </button>
      ))}
    </div>
  );

  renderKpiStrip = (summary, isLoading) => {
    const kpis = [
      { key: "total", label: "All notes", value: summary.total, tone: "indigo", icon: "fe fe-book-open", hint: "Last 12 months & upcoming" },
      { key: "pending", label: "Open", value: summary.pending, tone: "amber", icon: "fe fe-edit-3", hint: "Still active" },
      { key: "completed", label: "Done", value: summary.completed, tone: "green", icon: "fe fe-check-circle", hint: "Marked complete" },
    ];
    return (
      <div className="lux-bid-summary__kpi-strip" role="list" aria-label="Notes metrics">
        {kpis.map((kpi) => (
          <article
            key={kpi.key}
            className={classNames("lux-bid-summary__kpi", kpi.tone && `is-${kpi.tone}`)}
            role="listitem"
          >
            <div className="lux-bid-summary__kpi-top">
              <span className="lux-bid-summary__kpi-label">{kpi.label}</span>
              <span className="lux-bid-summary__kpi-icon" aria-hidden="true">
                <i className={kpi.icon} />
              </span>
            </div>
            <strong className="lux-bid-summary__kpi-value">
              {isLoading ? <Skeleton width={36} /> : <CountUp end={Number(kpi.value) || 0} duration={0.6} />}
            </strong>
            {kpi.hint && <span className="lux-bid-summary__kpi-hint">{kpi.hint}</span>}
          </article>
        ))}
      </div>
    );
  };

  render() {
    const { summary, isLoading, statusFilter, visibleCount, filterText } = this.props;
    const { expanded } = this.state;

    return (
      <section
        className={classNames("lux-bid-summary lux-po-summary lux-notes-summary", { "is-collapsed": !expanded })}
        aria-label="Notes overview"
      >
        <div className="lux-bid-summary__header-bar">
          <div className="lux-bid-summary__header-main">
            <LuxSummaryEyebrow variant="notes" className="lux-bid-summary__eyebrow">
              Notes intelligence
            </LuxSummaryEyebrow>
            {!expanded ? (
              <h2 className="lux-bid-summary__title lux-bid-summary__title--compact">
                <CountUp end={summary.pending} duration={0.6} />{" "}
                <span>
                  open · {summary.completed} done · {summary.total} total
                </span>
              </h2>
            ) : (
              <h2 className="lux-bid-summary__title lux-bid-summary__title--bar">Personal notes</h2>
            )}
          </div>
          <button
            type="button"
            className="lux-bid-summary__toggle"
            onClick={this.toggleExpanded}
            aria-expanded={expanded}
            aria-controls="lux-notes-summary-body"
            title={expanded ? "Collapse summary" : "Insights"}
          >
            <span>{getSummaryToggleLabel(expanded)}</span>
            <i className={classNames("fe", expanded ? "fe-chevron-up" : "fe-chevron-down")} aria-hidden="true" />
          </button>
        </div>

        {!expanded && (
          <div className="lux-bid-summary__collapsed-strip">
            <p className="lux-bid-summary__collapsed-line">
              {this.buildContextLine(summary, visibleCount, filterText)}
            </p>
            {this.renderFilterChips(statusFilter, true)}
          </div>
        )}

        <div id="lux-notes-summary-body" className="lux-bid-summary__body" aria-hidden={!expanded}>
          <div className="lux-bid-summary__toolbar">
            <p className="lux-bid-summary__subtitle">
              {this.buildContextLine(summary, visibleCount, filterText)}
              {" · "}
              Use the book icon on the left rail for a quick pending-notes overlay anywhere in the app.
            </p>
            {this.renderFilterChips(statusFilter, false)}
          </div>

          <div className="lux-bid-summary__metrics-row lux-po-summary__metrics-row">
            {this.renderKpiStrip(summary, isLoading)}
          </div>
        </div>
      </section>
    );
  }
}

export default NotesPageSummary;
