import React, { Component } from "react";
import PayrollLuxDrawerShell from "views/payroll/components/PayrollLuxDrawerShell";
import {
  PayrollDrawerBanner,
  PayrollDrawerCard,
  PayrollDrawerField,
  PayrollDrawerMeta,
  PayrollDrawerStatStrip,
} from "views/payroll/components/PayrollLuxDrawerShared";
import { PayrollActionButton } from "views/payroll/components/PayrollLuxShared";

const CHANGE_TYPES = [
  { id: "MERIT", label: "Merit increase", hint: "Performance-based adjustment" },
  { id: "PROMOTION", label: "Promotion", hint: "Role or grade change" },
  { id: "ADJUSTMENT", label: "Market adjustment", hint: "Retention or equity correction" },
];

const DRAWER_LINKS = [
  { to: "/payroll/compensation", label: "Compensation", hint: "Merit workflows", icon: "fe fe-trending-up" },
  { to: "/workspace/approvals", label: "Approvals", hint: "Sign-off queue", icon: "fe fe-check-circle" },
];

function formatUsd(value) {
  const amount = Number(value);
  if (!Number.isFinite(amount)) {
    return "—";
  }
  return new Intl.NumberFormat(undefined, { style: "currency", currency: "USD", maximumFractionDigits: 0 }).format(amount);
}

class CompensationChangeDrawer extends Component {
  state = {
    employeeName: "Elena Rossi",
    department: "Sales",
    changeType: "MERIT",
    currentBaseUsd: "92000",
    proposedBaseUsd: "98000",
    effectiveDate: "2026-07-01",
    rationale: "",
    error: null,
    saving: false,
  };

  componentDidUpdate(prevProps) {
    if (this.props.open && !prevProps.open) {
      this.setState({ error: null, saving: false });
    }
  }

  handleSave = async (event) => {
    event.preventDefault();
    const { employeeName, department, changeType, currentBaseUsd, proposedBaseUsd, effectiveDate, rationale } = this.state;
    if (!employeeName.trim() || !proposedBaseUsd) {
      this.setState({ error: "Employee and proposed base salary are required." });
      return;
    }
    this.setState({ saving: true, error: null });
    try {
      await this.props.onSave({
        employeeId: "emp-elena",
        employeeName,
        department,
        changeType,
        currentBaseUsd: Number(currentBaseUsd),
        proposedBaseUsd: Number(proposedBaseUsd),
        currentCtcUsd: Number(currentBaseUsd) * 1.28,
        proposedCtcUsd: Number(proposedBaseUsd) * 1.28,
        effectiveDate,
        rationale,
        requestedBy: "HR Ops",
      });
      this.props.onClose();
    } catch (error) {
      this.setState({ error: (error && error.message) || "Unable to propose compensation change." });
    } finally {
      this.setState({ saving: false });
    }
  };

  render() {
    if (!this.props.open) {
      return null;
    }

    const {
      employeeName,
      department,
      changeType,
      currentBaseUsd,
      proposedBaseUsd,
      effectiveDate,
      rationale,
      error,
      saving,
    } = this.state;

    const delta = Number(proposedBaseUsd) - Number(currentBaseUsd);
    const deltaPct =
      Number(currentBaseUsd) > 0 ? Math.round((delta / Number(currentBaseUsd)) * 1000) / 10 : null;

    const footer = (
      <>
        <PayrollActionButton variant="ghost" onClick={this.props.onClose} disabled={saving}>
          Cancel
        </PayrollActionButton>
        <PayrollActionButton type="submit" form="compensation-change-form" variant="primary" disabled={saving}>
          {saving ? "Submitting…" : "Submit for approval"}
        </PayrollActionButton>
      </>
    );

    return (
      <PayrollLuxDrawerShell
        open={this.props.open}
        onClose={this.props.onClose}
        accent="indigo"
        wide
        icon="fe-trending-up"
        eyebrow="Compensation workflow"
        title="Propose compensation change"
        subtitle="Capture merit, promotion, or market adjustments with approval routing and payroll impact preview."
        quickLinks={DRAWER_LINKS}
        footer={footer}
      >
        <form id="compensation-change-form" onSubmit={this.handleSave}>
          {error ? (
            <div className="lux-employee-360__error" role="alert">
              {error}
            </div>
          ) : null}

          <PayrollDrawerBanner icon="fe-shield" tone="info">
            Changes route through approvals before payroll structures update. Sensitive compensation values remain
            persona-masked outside authorized views.
          </PayrollDrawerBanner>

          <PayrollDrawerStatStrip
            stats={[
              { label: "Current base", value: formatUsd(currentBaseUsd), hint: "Annualized", tone: "blue" },
              { label: "Proposed base", value: formatUsd(proposedBaseUsd), hint: "Target", tone: "green" },
              {
                label: "Delta",
                value: Number.isFinite(delta) ? formatUsd(delta) : "—",
                hint: deltaPct != null ? `${deltaPct}% change` : "Change",
                tone: delta >= 0 ? "green" : "amber",
              },
            ]}
          />

          <PayrollDrawerCard title="Employee context" subtitle="Who the change applies to">
            <PayrollDrawerField label="Employee">
              <input value={employeeName} onChange={(e) => this.setState({ employeeName: e.target.value })} />
            </PayrollDrawerField>
            <PayrollDrawerField label="Department">
              <input value={department} onChange={(e) => this.setState({ department: e.target.value })} />
            </PayrollDrawerField>
          </PayrollDrawerCard>

          <PayrollDrawerCard title="Change type" subtitle="Select the compensation event category">
            <div className="lux-payroll-drawer__group-grid">
              {CHANGE_TYPES.map((type) => (
                <button
                  key={type.id}
                  type="button"
                  className={`lux-payroll-drawer__group-card${changeType === type.id ? " is-selected" : ""}`}
                  onClick={() => this.setState({ changeType: type.id })}
                >
                  <strong className="lux-payroll-drawer__group-name">{type.label}</strong>
                  <span className="lux-payroll-drawer__group-meta">{type.hint}</span>
                </button>
              ))}
            </div>
          </PayrollDrawerCard>

          <PayrollDrawerCard title="Compensation values" subtitle="Base salary and effective date">
            <div className="lux-payroll-drawer__date-grid" style={{ gridTemplateColumns: "repeat(2, minmax(0, 1fr))" }}>
              <PayrollDrawerField label="Current base (USD)">
                <input type="number" value={currentBaseUsd} onChange={(e) => this.setState({ currentBaseUsd: e.target.value })} />
              </PayrollDrawerField>
              <PayrollDrawerField label="Proposed base (USD)">
                <input type="number" value={proposedBaseUsd} onChange={(e) => this.setState({ proposedBaseUsd: e.target.value })} />
              </PayrollDrawerField>
            </div>
            <PayrollDrawerField label="Effective date" hint="Payroll pickup date for structure updates">
              <input type="date" value={effectiveDate} onChange={(e) => this.setState({ effectiveDate: e.target.value })} />
            </PayrollDrawerField>
            <PayrollDrawerField label="Rationale" hint="Visible to approvers and audit reviewers">
              <textarea value={rationale} rows={3} onChange={(e) => this.setState({ rationale: e.target.value })} />
            </PayrollDrawerField>
          </PayrollDrawerCard>

          <PayrollDrawerCard title="Approval preview" subtitle="Summary before submission" className="is-review">
            <PayrollDrawerMeta
              items={[
                { label: "Employee", value: employeeName },
                { label: "Change type", value: (CHANGE_TYPES.find((t) => t.id === changeType) || {}).label || changeType },
                { label: "Proposed base", value: formatUsd(proposedBaseUsd) },
                { label: "Effective", value: effectiveDate },
              ]}
            />
          </PayrollDrawerCard>
        </form>
      </PayrollLuxDrawerShell>
    );
  }
}

export default CompensationChangeDrawer;
