import React, { Component } from "react";
import classNames from "classnames/bind";
import moment from "moment";
import {
  buildHolidayMonthGrid,
  getHolidayLocations,
  indexHolidaysByDate,
} from "./holiday.utils";

const WEEKDAYS = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
const CELL_HOLIDAY_LIMIT = 2;

export default class HolidayMonthCalendar extends Component {
  getNextHolidayCountdown = (nextHoliday) => {
    if (!nextHoliday || !nextHoliday.date) {
      return null;
    }
    const days = Math.max(
      0,
      moment(nextHoliday.date).startOf("day").diff(moment().startOf("day"), "days")
    );
    if (days === 0) {
      return "Today";
    }
    if (days === 1) {
      return "Tomorrow";
    }
    return `In ${days} days`;
  };

  renderSidebar = (monthHolidays, selectedDayKey, onSelectDay) => {
    const { canRemove, canEdit, onRemove, onEdit, anchor } = this.props;
    const monthLabel = moment(anchor).format("MMMM YYYY");
    const count = monthHolidays.length;

    return (
      <aside
        className={classNames("lux-holiday-cal__sidebar", { "is-holiday-day": count > 0 })}
        data-testid="holiday-cal-sidebar"
      >
        <header className="lux-holiday-cal__sidebar-head lux-holiday-cal__sidebar-head--month">
          <div className="lux-holiday-cal__sidebar-copy">
            <span className="lux-holiday-cal__sidebar-badge is-holiday">This month</span>
            <h3>{monthLabel}</h3>
            <p>
              {count === 0
                ? "No holidays in this month"
                : `${count} holiday${count === 1 ? "" : "s"} observed`}
            </p>
          </div>
        </header>

        {count === 0 ? (
          <div className="lux-holiday-cal__sidebar-empty is-compact">
            <p>No holidays scheduled for {monthLabel}.</p>
          </div>
        ) : (
          <ul className="lux-holiday-cal__sidebar-list">
            {monthHolidays.map((item) => {
              const holidayMoment = moment(item.holidayDate);
              const dayKey = holidayMoment.format("YYYY-MM-DD");
              const locations = getHolidayLocations(item);
              const isSelected = selectedDayKey === dayKey;

              return (
                <li
                  key={item.id}
                  className={classNames("lux-holiday-cal__sidebar-item", {
                    "is-selected": isSelected,
                  })}
                >
                  <button
                    type="button"
                    className="lux-holiday-cal__sidebar-item-btn"
                    onClick={() =>
                      onSelectDay &&
                      onSelectDay({
                        key: dayKey,
                        moment: holidayMoment.clone(),
                      })
                    }
                  >
                    <span
                      className={classNames("lux-holiday-cal__sidebar-dateblock", "is-holiday", "is-compact")}
                      aria-hidden="true"
                    >
                      <span className="lux-holiday-cal__sidebar-day">{holidayMoment.format("DD")}</span>
                      <span className="lux-holiday-cal__sidebar-mon">{holidayMoment.format("MMM")}</span>
                    </span>
                    <span className="lux-holiday-cal__sidebar-item-main">
                      <strong>{item.name}</strong>
                      <span className="lux-holiday-cal__sidebar-desc">
                        {holidayMoment.format("dddd")}
                        {item.description && item.description !== item.name
                          ? ` · ${item.description}`
                          : ""}
                      </span>
                      <span className="lux-holiday-cal__sidebar-keys">
                        {locations.length === 0 ? (
                          <span className="lux-activity-holidays__chip is-muted">All locations</span>
                        ) : (
                          locations.map((loc) => (
                            <span key={loc} className="lux-activity-holidays__chip is-key">
                              {loc}
                            </span>
                          ))
                        )}
                      </span>
                    </span>
                  </button>
                  {(canEdit || canRemove) && (
                    <div className="lux-holiday-cal__sidebar-actions">
                      {canEdit && (
                        <button
                          type="button"
                          className="lux-project-row__action"
                          title="Edit holiday"
                          aria-label={`Edit ${item.name}`}
                          onClick={() => onEdit && onEdit(item)}
                        >
                          <i className="fe fe-edit-2" aria-hidden="true" />
                        </button>
                      )}
                      {canRemove && (
                        <button
                          type="button"
                          className="lux-project-row__action is-danger"
                          title="Remove holiday"
                          aria-label={`Remove ${item.name}`}
                          onClick={() => onRemove(item.id)}
                        >
                          <i className="fe fe-trash-2" aria-hidden="true" />
                        </button>
                      )}
                    </div>
                  )}
                </li>
              );
            })}
          </ul>
        )}
      </aside>
    );
  };

  render() {
    const {
      anchor,
      holidays,
      selectedDayKey,
      onSelectDay,
      onPrevMonth,
      onNextMonth,
      onToday,
      nextHoliday,
    } = this.props;

    const grid = buildHolidayMonthGrid(anchor);
    const byDate = indexHolidaysByDate(holidays);
    const monthHolidays = (holidays || [])
      .filter((item) => moment(item.holidayDate).isSame(anchor, "month"))
      .slice()
      .sort((a, b) => moment(a.holidayDate).valueOf() - moment(b.holidayDate).valueOf());
    const monthHolidayCount = monthHolidays.length;
    const monthLabel = moment(anchor).format("MMMM");
    const yearLabel = moment(anchor).format("YYYY");
    const countdown = this.getNextHolidayCountdown(nextHoliday);

    return (
      <div className="lux-holiday-cal" data-testid="holiday-month-calendar">
        <div className="lux-holiday-cal__stage">
          <header className="lux-holiday-cal__head">
            <div className="lux-holiday-cal__head-copy">
              <h2 className="lux-holiday-cal__title">
                {monthLabel} <span>{yearLabel}</span>
              </h2>
              <p className="lux-holiday-cal__sub">
                {monthHolidayCount} holiday{monthHolidayCount === 1 ? "" : "s"} this month
                {nextHoliday ? ` · Next: ${nextHoliday.name}` : ""}
                {countdown ? ` (${countdown})` : ""}
              </p>
            </div>
            <div className="lux-holiday-cal__nav" role="group" aria-label="Month navigation">
              <button
                type="button"
                className="lux-holiday-cal__nav-btn"
                onClick={onPrevMonth}
                aria-label="Previous month"
              >
                <i className="fe fe-chevron-left" aria-hidden="true" />
              </button>
              <button type="button" className="lux-holiday-cal__nav-btn is-today" onClick={onToday}>
                Today
              </button>
              <button
                type="button"
                className="lux-holiday-cal__nav-btn"
                onClick={onNextMonth}
                aria-label="Next month"
              >
                <i className="fe fe-chevron-right" aria-hidden="true" />
              </button>
            </div>
          </header>

          <div className="lux-holiday-cal__weekdays" role="row">
            {WEEKDAYS.map((name) => (
              <span key={name} className="lux-holiday-cal__weekday" role="columnheader">
                {name}
              </span>
            ))}
          </div>

          <div className="lux-holiday-cal__grid" role="grid" aria-label={`${monthLabel} ${yearLabel} holidays`}>
            {grid.map((day) => {
              const items = byDate[day.key] || [];
              const visible = items.slice(0, CELL_HOLIDAY_LIMIT);
              const more = items.length - visible.length;
              const selected = selectedDayKey === day.key;

              return (
                <button
                  key={day.key}
                  type="button"
                  className={classNames("lux-holiday-cal__cell", {
                    "is-off-month": !day.isCurrentMonth,
                    "is-today": day.isToday,
                    "is-weekend": day.isWeekend,
                    "is-past": day.isPast,
                    "is-holiday": items.length > 0,
                    "is-selected": selected,
                  })}
                  onClick={() => onSelectDay(day)}
                  aria-pressed={selected}
                  aria-label={`${day.moment.format("D MMMM")}${
                    items.length ? `, ${items.length} holiday${items.length === 1 ? "" : "s"}` : ""
                  }`}
                >
                  <span className="lux-holiday-cal__cell-head">
                    <span className="lux-holiday-cal__day-num">{day.dayOfMonth}</span>
                    {items.length > 0 && (
                      <span className="lux-holiday-cal__count-pill">{items.length}</span>
                    )}
                  </span>
                  <span className="lux-holiday-cal__cell-events">
                    {visible.map((item) => (
                      <span key={item.id} className="lux-holiday-cal__chip" title={item.name}>
                        {item.name}
                      </span>
                    ))}
                    {more > 0 && <span className="lux-holiday-cal__more">+{more}</span>}
                  </span>
                </button>
              );
            })}
          </div>
        </div>

        {this.renderSidebar(monthHolidays, selectedDayKey, onSelectDay)}
      </div>
    );
  }
}
