import React, { Component } from "react";
import { Link } from "react-router-dom";
import { recruitingService } from "_services/recruiting/recruiting.service";
import RecruitingLuxPage, {
  RecruitingActionButton,
  RecruitingLuxPanel,
} from "views/recruiting/components/RecruitingLuxShared";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

class RecruitingDashboardPage extends Component {
  state = { loading: true, loadError: null, summary: null };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Recruiting dashboard");
    }
    this.load();
  }

  load = async () => {
    this.setState({ loading: true, loadError: null });
    const result = await recruitingService.dashboardSummary();
    if (result.source === "api" && result.payload) {
      this.setState({ loading: false, summary: result.payload });
    } else {
      this.setState({
        loading: false,
        summary: null,
        loadError: result.error || new Error("Unable to load ATS dashboard"),
      });
    }
  };

  render() {
    const { loading, loadError, summary } = this.state;
    const kpiCards = summary
      ? [
          { id: "req", label: "Requisitions", value: summary.requisitionCount, icon: "fe fe-file-text" },
          { id: "cand", label: "Candidates", value: summary.candidateCount, icon: "fe fe-users" },
          { id: "int", label: "Interviews", value: summary.interviewCount, icon: "fe fe-calendar" },
          { id: "off", label: "Offers", value: summary.offerCount, icon: "fe fe-award" },
          { id: "acc", label: "Accepted", value: summary.acceptedOfferCount, icon: "fe fe-check-circle" },
          { id: "post", label: "Open postings", value: summary.openPostingCount, icon: "fe fe-radio" },
        ]
      : [];

    return (
      <RecruitingLuxPage
        testId="recruiting-dashboard-page"
        dataSource={summary ? "api" : loadError ? "api-error" : null}
        loading={loading}
        kpiCards={kpiCards}
        heroActions={
          <>
            <RecruitingActionButton to="/recruiting/requisitions" icon="fe fe-file-text" variant="secondary">
              Requisitions
            </RecruitingActionButton>
            <RecruitingActionButton to="/recruiting/candidates" icon="fe fe-users" variant="secondary">
              Candidates
            </RecruitingActionButton>
            <RecruitingActionButton to="/recruiting/interviews" icon="fe fe-calendar" variant="secondary">
              Interviews
            </RecruitingActionButton>
            <RecruitingActionButton to="/recruiting/offers" icon="fe fe-award">
              Offers
            </RecruitingActionButton>
          </>
        }
      >
        {loadError ? (
          <LuxInlineAlert tone="warning" title="Unable to load dashboard">
            {String(loadError.message || loadError)}{" "}
            <button type="button" className="lux-onb-action lux-onb-action--ghost lux-onb-action--compact" onClick={this.load}>
              Retry
            </button>
          </LuxInlineAlert>
        ) : null}
        {!loading && !summary && !loadError ? (
          <LuxRegisterEmptyState
            title="No ATS summary yet"
            description="Create requisitions and candidates to populate the recruiting dashboard."
            showCreate={false}
          />
        ) : null}
        {summary ? (
          <RecruitingLuxPanel
            title="Pipeline snapshot"
            meta="Live aggregate from requisitions, candidates, interviews and offers."
            icon="fe fe-activity"
          >
            <ul className="list-unstyled mb-0">
              <li>
                Approved requisitions: <strong>{summary.approvedRequisitionCount != null ? summary.approvedRequisitionCount : "—"}</strong>
              </li>
              <li>
                Jump to{" "}
                <Link to="/recruiting/requisitions">requisitions</Link>,{" "}
                <Link to="/recruiting/candidates">candidates</Link>, or{" "}
                <Link to="/recruiting/offers">offers</Link>.
              </li>
            </ul>
          </RecruitingLuxPanel>
        ) : null}
      </RecruitingLuxPage>
    );
  }
}

export default RecruitingDashboardPage;
