import React, { Component } from "react";
import { connect } from "react-redux";
import classNames from "classnames/bind";
import EmployeeImage from "views/common/fragments/EmployeeImage";
import Ckeditor from "views/common/plugins/charts/ckeditor";
import { itemAdditionalActions } from "_actions";
import { commonUtils } from "_helpers";
import { store } from "_helpers";
import {
  COLLAB_VIEWS,
  formatCollabRelativeTime,
  formatCollabTimestamp,
  getCommentHeadline,
  getEmployeeMeta,
  getEmployeeName,
  groupEntriesByDay,
  hasRichHtmlContent,
  stripHtml,
} from "./itemComments.utils";
import LuxActivityPanelEmptyState from "views/common/fragments/LuxActivityPanelEmptyState";
import Skeleton, { SkeletonTheme } from "react-loading-skeleton";
import { LUX_SKELETON_THEME } from "views/common/fragments/luxSkeleton.constants";

class ItemCommentsSection extends Component {
  componentDidMount() {
    this.loadComments();
  }

  componentDidUpdate(prevProps) {
    if (prevProps.itemId !== this.props.itemId) {
      this.loadComments();
    }
  }

  loadComments = () => {
    store.dispatch(
      this.props.getItemAdditionals(
        {
          itemId: this.props.itemId,
          subType: this.props.subType,
          type: COLLAB_VIEWS.COMMENT,
        },
        COLLAB_VIEWS.COMMENT
      )
    );
  };

  handleSubmitComment = (comment) => {
    store.dispatch(
      this.props.createItemAdditional({
        userTeamId: this.props.userTeamId || commonUtils.getCurrentUserTeamId(),
        itemId: this.props.itemId,
        type: COLLAB_VIEWS.COMMENT,
        subType: this.props.subType,
        description: comment,
      })
    );
  };

  handleRemoveComment = (commentId) => {
    store.dispatch(this.props.deleteItemAdditional({ itemId: commentId }));
  };

  renderEmptyState = () => (
    <LuxActivityPanelEmptyState
      className="lux-item-collab__empty"
      variant="collab"
      eyebrow="Conversation"
      title="No comments yet"
      description="Start the conversation — mention teammates, capture decisions, and keep context in one place."
      hints={[
        "Use @mentions to notify teammates",
        "Rich text supports links and formatting",
        "Comments stay attached to this record",
      ]}
    />
  );

  renderComment = (entry) => {
    const employee = entry.employeeInfo;
    const canDelete =
      !this.props.isReadOnly &&
      employee &&
      employee.id === commonUtils.getCurrentUserId();

    return (
      <article key={entry.id} className="lux-item-collab__entry">
        <div className="lux-item-collab__entry-rail" aria-hidden="true">
          <span className="lux-item-collab__entry-icon is-indigo">
            <i className="fe fe-message-square" />
          </span>
          <span className="lux-item-collab__entry-line" />
        </div>

        <div className="lux-item-collab__entry-card is-comment">
          <span className="lux-item-collab__comment-glow" aria-hidden="true" />
          <span className="lux-item-collab__comment-accent" aria-hidden="true" />
          <span className="lux-item-collab__comment-watermark" aria-hidden="true">
            <i className="fe fe-message-square" />
          </span>

          <header className="lux-item-collab__entry-head lux-item-collab__comment-head">
            <div className="lux-item-collab__entry-user">
              {employee && (
                <span className="lux-item-collab__avatar-ring">
                  <EmployeeImage employee={employee} classes="lux-item-collab__avatar" />
                </span>
              )}
              <div className="lux-item-collab__entry-names">
                <strong>{getEmployeeName(entry)}</strong>
                <span>
                  posted a comment
                  {getEmployeeMeta(entry) ? ` · ${getEmployeeMeta(entry)}` : ""}
                </span>
              </div>
            </div>
            <div className="lux-item-collab__entry-time lux-item-collab__comment-time">
              <span className="lux-item-collab__comment-badge">
                <i className="fe fe-message-circle" aria-hidden="true" />
                Comment
              </span>
              <strong title={formatCollabTimestamp(entry.createdDate)}>
                {formatCollabRelativeTime(entry.createdDate)}
              </strong>
              <span>{formatCollabTimestamp(entry.createdDate)}</span>
            </div>
          </header>

          <div className="lux-item-collab__comment-body-wrap">
            {hasRichHtmlContent(entry.description) ? (
              <div
                className="lux-item-collab__entry-body lux-item-collab__comment-body htmlComments"
                dangerouslySetInnerHTML={{ __html: entry.description }}
              />
            ) : (
              <p className="lux-item-collab__entry-body lux-item-collab__comment-body">
                {getCommentHeadline(entry)}
              </p>
            )}
          </div>

          {canDelete && (
            <div className="lux-item-collab__entry-actions">
              <button
                type="button"
                className="lux-item-collab__delete-btn"
                onClick={() => this.handleRemoveComment(entry.id)}
              >
                <i className="fe fe-trash-2" aria-hidden="true" />
                Remove
              </button>
            </div>
          )}
        </div>
      </article>
    );
  };

  renderTimeline = () => {
    const items = this.props.comments || [];
    if (!items.length) return this.renderEmptyState();

    const groups = groupEntriesByDay(items);
    return (
      <div className="lux-item-collab__timeline">
        {groups.map(([dayLabel, entries]) => (
          <section key={dayLabel} className="lux-item-collab__day-group">
            <div className="lux-item-collab__day-label">
              <i className="fe fe-calendar" aria-hidden="true" />
              {dayLabel}
            </div>
            <div className="lux-item-collab__entries">
              {entries.map((entry) => this.renderComment(entry))}
            </div>
          </section>
        ))}
      </div>
    );
  };

  render() {
    const { isLoading, creatingItemAdditional, comments } = this.props;
    const items = comments || [];
    const showLoading = isLoading && !items.length;

    return (
      <div className="lux-item-collab">
        <div className="lux-item-collab__toolbar lux-item-collab__toolbar--comments-only">
          <span className="lux-item-collab__summary">
            {items.length} comment{items.length === 1 ? "" : "s"}
          </span>
        </div>

        <div className="lux-item-collab__body">
          {showLoading && (
            <div className="lux-item-collab__loading" aria-busy="true" aria-label="Loading comments">
              <SkeletonTheme
                baseColor={LUX_SKELETON_THEME.baseColor}
                highlightColor={LUX_SKELETON_THEME.highlightColor}
              >
                {[1, 2, 3].map((key) => (
                  <div key={key} className="lux-item-collab__loading-row">
                    <Skeleton circle width={32} height={32} />
                    <div style={{ flex: 1 }}>
                      <Skeleton width="35%" height={10} borderRadius={4} />
                      <Skeleton height={36} borderRadius={10} style={{ marginTop: 8 }} />
                    </div>
                  </div>
                ))}
              </SkeletonTheme>
            </div>
          )}

          {!showLoading && (
            <>
              <ItemCommentsComposer
                isReadOnly={this.props.isReadOnly}
                onSubmit={this.handleSubmitComment}
                isSubmitting={creatingItemAdditional === true}
                commentCount={items.length}
              />
              {this.renderTimeline()}
            </>
          )}
        </div>
      </div>
    );
  }
}

class ItemCommentsComposer extends Component {
  constructor() {
    super();
    this.state = {
      comment: "",
      submitEnabled: false,
    };
  }

  componentDidUpdate(prevProps) {
    if (prevProps.isSubmitting && !this.props.isSubmitting) {
      this.setState({ comment: "", submitEnabled: false });
    }
  }

  onChange = (comment) => {
    const plain = stripHtml(comment);
    this.setState({
      comment,
      submitEnabled: plain.length > 1,
    });
  };

  onSubmit = () => {
    if (!this.state.submitEnabled || this.props.isSubmitting) return;
    this.props.onSubmit(this.state.comment);
  };

  render() {
    const { isReadOnly, commentCount, isSubmitting } = this.props;

    return (
      <div className="lux-item-collab__composer">
        <div className="lux-item-collab__composer-head">
          <span className="lux-item-collab__composer-title">Add a comment</span>
          <span className="lux-item-collab__composer-hint">Visible to everyone with access</span>
        </div>

        {!isReadOnly && <Ckeditor onChange={this.onChange} content={this.state.comment} />}

        <div className="lux-item-collab__composer-foot">
          <span className="lux-item-collab__composer-meta">
            {commentCount || 0} comment{commentCount === 1 ? "" : "s"} in this thread
          </span>
          {!isReadOnly && (
            <button
              type="button"
              className="lux-item-collab__post-btn"
              onClick={this.onSubmit}
              disabled={!this.state.submitEnabled || isSubmitting}
            >
              {isSubmitting ? (
                <>
                  <i className="fe fe-loader" aria-hidden="true" />
                  Posting…
                </>
              ) : (
                <>
                  <i className="fe fe-send" aria-hidden="true" />
                  Post comment
                </>
              )}
            </button>
          )}
        </div>
      </div>
    );
  }
}

const mapStateToProps = (state) => ({
  comments: state.itemAdditional.comments,
  isLoading: state.itemAdditional.isLoading,
  creatingItemAdditional: state.itemAdditional.creatingItemAdditional,
});

const mapDispatchToProps = () => ({
  getItemAdditionals: itemAdditionalActions.getItemAdditionals,
  createItemAdditional: itemAdditionalActions.createItemAdditional,
  deleteItemAdditional: itemAdditionalActions.removeItemAdditional,
});

export default connect(mapStateToProps, mapDispatchToProps)(ItemCommentsSection);
