import { connect } from "react-redux";
import classNames from "classnames/bind";
import { accessUtils, commonUtils } from "_helpers";
import { shiftPolicyService } from "_services/shift-policy.service";
import { ADMIN_PAGE_META } from "config/admin-page-meta.config";
import {
  isShiftPoliciesEnabled,
  shouldUseShiftPoliciesApi,
} from "config/shift-policy.config";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import {
  AdminActionButton,
  AdminInsightStrip,
  AdminLuxPage,
} from "views/admin/components/AdminLuxShared";
import "views/hrms/leaveLuxForms.css";

const WEEKDAYS = [
  { id: 1, label: "Mon", short: "M" },
  { id: 2, label: "Tue", short: "T" },
  { id: 3, label: "Wed", short: "W" },
  { id: 4, label: "Thu", short: "T" },
  { id: 5, label: "Fri", short: "F" },
  { id: 6, label: "Sat", short: "S" },
  { id: 7, label: "Sun", short: "S" },
];

const EMPTY_FORM = {
  code: "",
  name: "",
  description: "",
  timezone: "Asia/Kolkata",
  workdays: "1,2,3,4,5",
  startTime: "09:00",
  endTime: "18:00",
  breakMinutes: 60,
  active: true,
};

function parseWorkdays(value) {
  if (!value) return [];
  return String(value)
    .split(",")
    .map((part) => Number(String(part).trim()))
    .filter((n) => n >= 1 && n <= 7);
}

function formatWorkdays(ids) {
  return [...new Set(ids)].sort((a, b) => a - b).join(",");
}

function workdayLabels(value) {
  const ids = parseWorkdays(value);
  if (!ids.length) return "—";
  if (ids.length === 5 && ids.every((id, idx) => id === idx + 1)) return "Mon–Fri";
  if (ids.length === 7) return "Every day";
  return ids
    .map((id) => (WEEKDAYS.find((d) => d.id === id) || {}).label || id)
    .join(", ");
}

function timeToMinutes(value) {
  const parts = String(value || "00:00").split(":");
  const h = Number(parts[0]) || 0;
  const m = Number(parts[1]) || 0;
  return Math.max(0, Math.min(24 * 60, h * 60 + m));
}

function formatDurationHours(startTime, endTime, breakMinutes) {
  let span = timeToMinutes(endTime) - timeToMinutes(startTime);
  if (span <= 0) span += 24 * 60;
  const net = Math.max(0, span - (Number(breakMinutes) || 0));
  const hours = Math.round((net / 60) * 10) / 10;
  return `${hours}h net`;
}

function SchedulePreview({ workdays, startTime, endTime, breakMinutes, timezone, compact }) {
  const selected = parseWorkdays(workdays);
  const startPct = (timeToMinutes(startTime) / (24 * 60)) * 100;
  let endPct = (timeToMinutes(endTime) / (24 * 60)) * 100;
  if (endPct <= startPct) endPct = 100;
  const widthPct = Math.max(2, endPct - startPct);

  return (
    <div
      className={classNames("lux-shift-preview", { "is-compact": compact })}
      data-testid="eh04-shift-preview"
    >
      <div className="lux-shift-preview__meta">
        <span className="lux-shift-preview__window">
          {startTime || "—"}–{endTime || "—"}
        </span>
        <span className="lux-shift-preview__sep" aria-hidden="true">
          ·
        </span>
        <span>{formatDurationHours(startTime, endTime, breakMinutes)}</span>
        {timezone ? (
          <>
            <span className="lux-shift-preview__sep" aria-hidden="true">
              ·
            </span>
            <span className="lux-shift-preview__tz">{timezone}</span>
          </>
        ) : null}
      </div>
      <div className="lux-shift-preview__week" role="list" aria-label="Work week">
        {WEEKDAYS.map((day) => {
          const on = selected.includes(day.id);
          return (
            <span
              key={day.id}
              role="listitem"
              className={classNames("lux-shift-preview__day", { "is-on": on })}
              title={day.label}
            >
              {day.short}
            </span>
          );
        })}
      </div>
      <div className="lux-shift-preview__track" aria-hidden="true">
        <span className="lux-shift-preview__track-label">00:00</span>
        <div className="lux-shift-preview__rail">
          <span
            className="lux-shift-preview__block"
            style={{ left: `${startPct}%`, width: `${widthPct}%` }}
          />
        </div>
        <span className="lux-shift-preview__track-label">24:00</span>
      </div>
    </div>
  );
}

function WorkdayPills({ workdays }) {
  const selected = parseWorkdays(workdays);
  return (
    <div className="lux-shift-day-pills" aria-label={workdayLabels(workdays)}>
      {WEEKDAYS.map((day) => (
        <span
          key={day.id}
          className={classNames("lux-shift-day-pill", {
            "is-on": selected.includes(day.id),
          })}
        >
          {day.short}
        </span>
      ))}
    </div>
  );
}

function buildShiftInsights(policies) {
  const insights = [];
  const active = policies.filter((p) => p.active !== false);
  const inactive = policies.length - active.length;
  if (policies.length === 0) {
    insights.push({
      id: "empty",
      tone: "amber",
      icon: "fe fe-clock",
      title: "No shift yet",
      copy: "Create a weekday window so leave coverage can skip non-workdays.",
    });
  } else {
    insights.push({
      id: "shift-coverage",
      tone: "blue",
      icon: "fe fe-calendar",
      title: "Coverage uses active shift",
      copy: "Leave coverage marks non-workdays from the first active shift policy.",
    });
  }
  if (active.length > 1) {
    insights.push({
      id: "multi-active",
      tone: "amber",
      icon: "fe fe-alert-triangle",
      title: `${active.length} active policies`,
      copy: "Coverage uses the first active policy — keep one primary shift when possible.",
    });
  }
  if (inactive > 0) {
    insights.push({
      id: "inactive",
      tone: "rose",
      icon: "fe fe-pause-circle",
      title: `${inactive} inactive`,
      copy: "Inactive shifts stay in history but do not drive coverage.",
    });
  }
  if (insights.length < 2 && policies.length > 0) {
    insights.push({
      id: "aligned",
      tone: "green",
      icon: "fe fe-check-circle",
      title: `${active.length} active shift${active.length === 1 ? "" : "s"}`,
      copy: "Working windows are ready for attendance and leave coverage.",
    });
  }
  return insights.slice(0, 3);
}

class ShiftPolicyPage extends Component {
  constructor(props) {
    super(props);
    const adminModules = accessUtils.getAccessControll("adminModules") || {};
    this.state = {
      enabled: isShiftPoliciesEnabled(adminModules),
      useApi: shouldUseShiftPoliciesApi(),
      policies: [],
      loading: true,
      saving: false,
      editPolicy: null,
      form: { ...EMPTY_FORM },
      error: null,
      drawerOpen: false,
    };
  }

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler(this.props.routeProp.name);
    this.loadAll();
  }

  loadAll = () => {
    const userTeamId = commonUtils.getCurrentUserTeamId();
    if (!this.state.enabled || !userTeamId || !this.state.useApi) {
      this.setState({ loading: false, policies: [] });
      return;
    }
    this.setState({ loading: true, error: null });
    shiftPolicyService.list(userTeamId).then(
      (response) => {
        if (response && response.error) {
          this.setState({
            loading: false,
            error:
              (response.error[0] && response.error[0].message) ||
              "Unable to load shift policies",
            policies: [],
          });
          return;
        }
        this.setState({
          loading: false,
          policies: (response && response.payload) || [],
        });
      },
      () =>
        this.setState({
          loading: false,
          error: "Unable to load shift policies",
          policies: [],
        })
    );
  };

  openNew = () => {
    this.setState({
      drawerOpen: true,
      editPolicy: null,
      form: { ...EMPTY_FORM },
      error: null,
    });
  };

  openEdit = (policy) => {
    this.setState({
      drawerOpen: true,
      editPolicy: policy,
      form: {
        code: policy.code || "",
        name: policy.name || "",
        description: policy.description || "",
        timezone: policy.timezone || "Asia/Kolkata",
        workdays: policy.workdays || "1,2,3,4,5",
        startTime: policy.startTime || "09:00",
        endTime: policy.endTime || "18:00",
        breakMinutes: policy.breakMinutes != null ? policy.breakMinutes : 60,
        active: policy.active !== false,
      },
      error: null,
    });
  };

  closeDrawer = () => this.setState({ drawerOpen: false, editPolicy: null, error: null });

  updateForm = (patch) => {
    this.setState((prev) => ({ form: { ...prev.form, ...patch }, error: null }));
  };

  toggleWorkday = (dayId) => {
    const current = parseWorkdays(this.state.form.workdays);
    const next = current.includes(dayId)
      ? current.filter((id) => id !== dayId)
      : [...current, dayId];
    this.updateForm({ workdays: formatWorkdays(next) });
  };

  save = (e) => {
    if (e && e.preventDefault) e.preventDefault();
    const { form, editPolicy } = this.state;
    if (!form.code || !form.name) {
      this.setState({ error: "Code and name are required" });
      return;
    }
    if (!parseWorkdays(form.workdays).length) {
      this.setState({ error: "Select at least one workday" });
      return;
    }
    const userTeamId = commonUtils.getCurrentUserTeamId();
    const actorId = commonUtils.getCurrentUserId();
    const payload = {
      ...form,
      userTeamId,
      actorId,
      breakMinutes: Number(form.breakMinutes) || 60,
    };
    this.setState({ saving: true, error: null });
    const request = editPolicy
      ? shiftPolicyService.update(editPolicy.id, payload)
      : shiftPolicyService.create(payload);
    request.then(
      (response) => {
        if (response && response.error) {
          this.setState({
            saving: false,
            error: (response.error[0] && response.error[0].message) || "Save failed",
          });
          return;
        }
        this.setState({ saving: false, drawerOpen: false, editPolicy: null });
        this.loadAll();
      },
      () => this.setState({ saving: false, error: "Save failed" })
    );
  };

  renderField = (label, icon, children, spanFull) => (
    <label
      className={classNames("lux-leave-drawer__field", {
        "lux-leave-drawer__field--full": spanFull,
      })}
    >
      <span className="lux-leave-drawer__label">
        {icon ? <i className={`fe ${icon}`} aria-hidden="true" /> : null} {label}
      </span>
      {children}
    </label>
  );

  renderDrawer = () => {
    const { drawerOpen, form, saving, editPolicy, error } = this.state;
    if (!drawerOpen) return null;
    const selectedDays = parseWorkdays(form.workdays);
    const isNew = !editPolicy;

    return createPortal(
      <div
        className="lux-onb-drawer-backdrop lux-leave-drawer-backdrop"
        role="presentation"
        onClick={this.closeDrawer}
      >
        <aside
          className="lux-onb-drawer lux-leave-drawer lux-shift-drawer lux-onb-drawer--warning"
          data-testid="eh04-shift-drawer"
          role="dialog"
          aria-modal="true"
          aria-labelledby="shift-policy-drawer-title"
          onClick={(e) => e.stopPropagation()}
        >
          <header className="lux-onb-drawer__head">
            <div className="lux-onb-drawer__head-main">
              <span className="lux-onb-drawer__category-icon" aria-hidden="true">
                <i className="fe fe-clock" />
              </span>
              <div className="lux-onb-drawer__head-copy">
                <span className="lux-leave-drawer__eyebrow">Admin · Shift policies</span>
                <h2 id="shift-policy-drawer-title">
                  {isNew ? "New shift policy" : "Edit shift policy"}
                </h2>
                <p>Working days and hours for leave coverage and attendance.</p>
              </div>
            </div>
            <button
              type="button"
              className="lux-onb-drawer__close"
              aria-label="Close"
              onClick={this.closeDrawer}
            >
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </header>

          <div className="lux-onb-drawer__body lux-leave-drawer__body">
            <div className="lux-leave-drawer__scroll">
              {error ? (
                <div
                  className="lux-leave-config__banner is-error"
                  role="alert"
                  data-testid="eh04-shift-error"
                >
                  <i className="fe fe-alert-circle" aria-hidden="true" />
                  <span>{error}</span>
                </div>
              ) : null}

              <section className="lux-onb-drawer__section">
                <header className="lux-onb-drawer__section-head">
                  <i className="fe fe-eye" aria-hidden="true" /> Live preview
                </header>
                <SchedulePreview
                  workdays={form.workdays}
                  startTime={form.startTime}
                  endTime={form.endTime}
                  breakMinutes={form.breakMinutes}
                  timezone={form.timezone}
                />
              </section>

              <section className="lux-onb-drawer__section">
                <header className="lux-onb-drawer__section-head">
                  <i className="fe fe-bookmark" aria-hidden="true" /> Identity
                </header>
                <div className="lux-leave-drawer__grid">
                  {this.renderField(
                    "Code",
                    "fe-hash",
                    <input
                      className="lux-leave-drawer__input"
                      data-testid="eh04-shift-code"
                      value={form.code}
                      disabled={!isNew}
                      placeholder="e.g. STD"
                      onChange={(e) => this.updateForm({ code: e.target.value.toUpperCase() })}
                      required
                    />
                  )}
                  {this.renderField(
                    "Name",
                    "fe-tag",
                    <input
                      className="lux-leave-drawer__input"
                      data-testid="eh04-shift-name"
                      value={form.name}
                      placeholder="e.g. Standard weekday"
                      onChange={(e) => this.updateForm({ name: e.target.value })}
                      required
                    />
                  )}
                </div>
                {this.renderField(
                  "Description",
                  "fe-align-left",
                  <textarea
                    className="lux-leave-drawer__textarea lux-shift-drawer__notes"
                    rows={2}
                    value={form.description}
                    placeholder="Optional notes for HR and managers"
                    onChange={(e) => this.updateForm({ description: e.target.value })}
                  />,
                  true
                )}
              </section>

              <section className="lux-onb-drawer__section">
                <header className="lux-onb-drawer__section-head">
                  <i className="fe fe-calendar" aria-hidden="true" /> Work week
                </header>
                <div className="lux-shift-workdays" data-testid="eh04-shift-workdays-panel">
                  <p className="lux-shift-workdays__hint">
                    Tap days that count as working days for coverage.
                  </p>
                  <div className="lux-shift-workdays__chips" role="group" aria-label="Workdays">
                    {WEEKDAYS.map((day) => {
                      const on = selectedDays.includes(day.id);
                      return (
                        <button
                          key={day.id}
                          type="button"
                          className={classNames("lux-shift-workdays__chip", { "is-on": on })}
                          aria-pressed={on}
                          onClick={() => this.toggleWorkday(day.id)}
                        >
                          <span className="lux-shift-workdays__chip-short">{day.short}</span>
                          <span className="lux-shift-workdays__chip-label">{day.label}</span>
                        </button>
                      );
                    })}
                  </div>
                  <input
                    type="hidden"
                    data-testid="eh04-shift-workdays"
                    value={form.workdays}
                    readOnly
                  />
                </div>
              </section>

              <section className="lux-onb-drawer__section">
                <header className="lux-onb-drawer__section-head">
                  <i className="fe fe-clock" aria-hidden="true" /> Daily window
                </header>
                <div className="lux-leave-drawer__grid">
                  {this.renderField(
                    "Start",
                    "fe-sunrise",
                    <input
                      className="lux-leave-drawer__input"
                      type="time"
                      value={form.startTime}
                      onChange={(e) => this.updateForm({ startTime: e.target.value })}
                    />
                  )}
                  {this.renderField(
                    "End",
                    "fe-sunset",
                    <input
                      className="lux-leave-drawer__input"
                      type="time"
                      value={form.endTime}
                      onChange={(e) => this.updateForm({ endTime: e.target.value })}
                    />
                  )}
                  {this.renderField(
                    "Timezone",
                    "fe-globe",
                    <input
                      className="lux-leave-drawer__input"
                      value={form.timezone}
                      onChange={(e) => this.updateForm({ timezone: e.target.value })}
                    />
                  )}
                  {this.renderField(
                    "Break minutes",
                    "fe-coffee",
                    <input
                      type="number"
                      min="0"
                      step="5"
                      className="lux-leave-drawer__input"
                      value={form.breakMinutes}
                      onChange={(e) => this.updateForm({ breakMinutes: e.target.value })}
                    />
                  )}
                </div>
                <label className="lux-leave-drawer__check">
                  <input
                    type="checkbox"
                    checked={form.active}
                    onChange={(e) => this.updateForm({ active: e.target.checked })}
                  />
                  <span>Active — drives leave coverage and attendance windows</span>
                </label>
              </section>
            </div>
          </div>

          <footer className="lux-onb-drawer__foot">
            <div className="lux-onb-drawer__foot-actions">
              <button
                type="button"
                className="lux-leave-drawer__btn is-ghost"
                onClick={this.closeDrawer}
                disabled={saving}
              >
                Cancel
              </button>
              <button
                type="button"
                className="lux-leave-drawer__btn is-primary"
                data-testid="eh04-shift-save"
                disabled={saving}
                onClick={this.save}
              >
                {saving ? "Saving…" : isNew ? "Create policy" : "Save policy"}
              </button>
            </div>
          </footer>
        </aside>
      </div>,
      document.body
    );
  };

  render() {
    const { enabled, policies, loading, error } = this.state;
    const activeCount = policies.filter((p) => p.active !== false).length;
    const canCreate =
      accessUtils.getLeaveAccessControl().policyAdminEnabled || enabled;
    const insights = loading ? [] : buildShiftInsights(policies);

    const kpiCards = [
      {
        id: "policies",
        label: "Policies",
        value: policies.length,
        hint: "Configured shifts",
        tone: "blue",
        icon: "fe fe-layers",
      },
      {
        id: "active",
        label: "Active",
        value: activeCount,
        hint: "Driving coverage",
        tone: "green",
        icon: "fe fe-check-circle",
      },
      {
        id: "window",
        label: "Primary window",
        value:
          activeCount > 0
            ? `${(policies.find((p) => p.active !== false) || {}).startTime || "—"}–${
                (policies.find((p) => p.active !== false) || {}).endTime || "—"
              }`
            : "—",
        hint: "First active shift",
        tone: "violet",
        icon: "fe fe-clock",
      },
      {
        id: "workdays",
        label: "Work pattern",
        value:
          activeCount > 0
            ? workdayLabels((policies.find((p) => p.active !== false) || {}).workdays)
            : "—",
        hint: "Active workdays",
        tone: "amber",
        icon: "fe fe-calendar",
      },
    ];

    const primary =
      policies.find((p) => p.active !== false) || policies[0] || null;

    const heroActions = (
      <>
        <AdminActionButton icon="fe fe-refresh-cw" onClick={this.loadAll} disabled={loading}>
          Refresh
        </AdminActionButton>
        {canCreate ? (
          <AdminActionButton
            icon="fe fe-plus"
            variant="primary"
            onClick={this.openNew}
            testId="eh04-shift-new"
          >
            New shift policy
          </AdminActionButton>
        ) : null}
      </>
    );

    if (!enabled) {
      return (
        <AdminLuxPage
          pageMeta={ADMIN_PAGE_META.shiftPolicies}
          kpiCards={kpiCards}
          loading={loading}
          testId="eh04-shift-page"
          className="lux-admin-page lux-leave-page lux-shift-policy-page"
        >
          <LuxRegisterEmptyState
            className="lux-register-empty--compact lux-leave-empty"
            icon="fe fe-lock"
            title="Shift policies not enabled"
            description="Enable shift policies for this organization to configure working-day calendars."
            data-testid="eh04-shift-disabled"
          />
          <p className="sr-only" data-testid="eh04-shift-disabled">
            Shift policies are not enabled for this organization.
          </p>
        </AdminLuxPage>
      );
    }

    return (
      <AdminLuxPage
        pageMeta={ADMIN_PAGE_META.shiftPolicies}
        kpiCards={kpiCards}
        loading={loading}
        testId="eh04-shift-page"
        className="lux-admin-page lux-leave-page lux-shift-policy-page"
        heroActions={heroActions}
      >
        <AdminInsightStrip insights={insights} />

        {error ? (
          <div className="lux-leave-config__banner is-error" role="alert">
            <i className="fe fe-alert-circle" aria-hidden="true" />
            <span>{error}</span>
          </div>
        ) : null}

        {!loading && primary ? (
          <section className="lux-shift-spotlight" aria-label="Primary shift">
            <div className="lux-shift-spotlight__copy">
              <span className="lux-shift-spotlight__eyebrow">Primary coverage shift</span>
              <h3 className="lux-shift-spotlight__title">
                <span className="lux-shift-spotlight__code">{primary.code}</span>
                {primary.name}
              </h3>
              <p className="lux-shift-spotlight__sub">
                {primary.active === false
                  ? "No active policy — showing the first configured shift."
                  : "Leave coverage treats non-workdays from this active window."}
              </p>
              <button
                type="button"
                className="lux-leave-register__action lux-shift-spotlight__edit"
                onClick={() => this.openEdit(primary)}
              >
                Edit primary
              </button>
            </div>
            <SchedulePreview
              workdays={primary.workdays}
              startTime={primary.startTime}
              endTime={primary.endTime}
              breakMinutes={primary.breakMinutes}
              timezone={primary.timezone}
              compact
            />
          </section>
        ) : null}

        <section className="lux-leave-subpanel lux-leave-policy__section" aria-label="Shift policies">
          <header className="lux-leave-subpanel__head">
            <div>
              <span className="lux-leave-subpanel__eyebrow">Register</span>
              <h3 className="lux-leave-subpanel__title">Shift policies</h3>
              <p className="lux-leave-subpanel__sub">
                Working-day calendars used by leave coverage and attendance.
              </p>
            </div>
            {canCreate ? (
              <button type="button" className="lux-leave-hero__cta is-secondary" onClick={this.openNew}>
                <i className="fe fe-plus" aria-hidden="true" />
                New shift policy
              </button>
            ) : null}
          </header>

          {loading ? (
            <div
              className="lux-leave-register__skeleton"
              aria-busy="true"
              data-testid="eh04-shift-loading"
            >
              Loading shift policies…
            </div>
          ) : policies.length === 0 ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact lux-leave-empty"
              icon="fe fe-clock"
              title="No shift policies yet"
              description="Create a weekday shift so coverage can distinguish working days."
              createLabel="New shift policy"
              onCreate={canCreate ? this.openNew : undefined}
              showCreate={!!canCreate}
            />
          ) : (
            <div className="lux-leave-register-wrap">
              <table className="lux-leave-register" data-testid="eh04-shift-register">
                <thead>
                  <tr>
                    <th>Code</th>
                    <th>Name</th>
                    <th>Workdays</th>
                    <th>Window</th>
                    <th>Timezone</th>
                    <th>Status</th>
                    <th />
                  </tr>
                </thead>
                <tbody>
                  {policies.map((policy) => (
                    <tr
                      key={policy.id}
                      className="lux-leave-register__row"
                      data-testid={`eh04-shift-row-${policy.id}`}
                    >
                      <td>
                        <span className="lux-leave-register__type">
                          <strong>{policy.code}</strong>
                        </span>
                      </td>
                      <td>
                        <div className="lux-shift-policy-name">{policy.name}</div>
                        {policy.description ? (
                          <div className="lux-shift-policy-desc">{policy.description}</div>
                        ) : null}
                      </td>
                      <td>
                        <WorkdayPills workdays={policy.workdays} />
                      </td>
                      <td>
                        <span className="lux-shift-window">
                          {policy.startTime}–{policy.endTime}
                        </span>
                        {policy.breakMinutes != null ? (
                          <div className="lux-shift-break">{policy.breakMinutes}m break</div>
                        ) : null}
                      </td>
                      <td>{policy.timezone || "—"}</td>
                      <td>
                        <span
                          className={classNames("lux-glp-status", {
                            "is-published": policy.active !== false,
                            "is-draft": policy.active === false,
                          })}
                        >
                          {policy.active === false ? "Inactive" : "Active"}
                        </span>
                      </td>
                      <td>
                        <button
                          type="button"
                          className="lux-leave-register__action"
                          onClick={() => this.openEdit(policy)}
                        >
                          Edit
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </section>

        {this.renderDrawer()}
      </AdminLuxPage>
    );
  }
}

function mapStateToProps(state) {
  return {
    user: state.authentication && state.authentication.user,
  };
}

export default connect(mapStateToProps)(ShiftPolicyPage);
