import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isDeveloperPortalEnabled } from "config/developer-portal.config";
import { DEVELOPER_PORTAL_PAGE_META } from "config/developer-portal-nav.config";
import { developerPortalService } from "_services/developerPortal.service";
import DeveloperLuxPage, {
  DeveloperActionButton,
  DeveloperInsightPanel,
} from "views/developer/components/DeveloperLuxShared";
import AppRegistryPanel from "views/developer/components/AppRegistryPanel";
import DeveloperUsageAnalyticsPanel from "views/developer/components/DeveloperUsageAnalyticsPanel";
import { AppRegisterDrawer } from "views/developer/components/DeveloperCreateDrawers";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import { getLuxInlineAlertProps } from "_helpers/apiError.utils";

class DeveloperPortalPage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    apps: [],
    kpiCards: [],
    insights: [],
    analytics: null,
    registerOpen: false,
  };

  componentDidMount() {
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await developerPortalService.getOverview({});
      const payload = result.payload || {};
      this.setState({
        loading: false,
        dataSource: result.source,
        apps: payload.apps || [],
        kpiCards: payload.kpiCards || [],
        insights: payload.insights || [],
        analytics: payload.analytics || null,
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: error,
      });
    }
  };

  render() {
    if (!isDeveloperPortalEnabled()) {
      return <PersonaAccessDenied featureLabel="Developer portal" />;
    }

    const { loading, loadError, dataSource, apps, kpiCards, insights, analytics, registerOpen } = this.state;

    return (
      <DeveloperLuxPage
        pageMeta={DEVELOPER_PORTAL_PAGE_META}
        pageId="developer"
        shellTitle="Developer portal"
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        heroActions={
          <>
            <DeveloperActionButton icon="fe fe-refresh-cw" onClick={this.loadData} disabled={loading}>
              Refresh
            </DeveloperActionButton>
            <DeveloperActionButton icon="fe fe-plus" onClick={() => this.setState({ registerOpen: true })}>
              Register app
            </DeveloperActionButton>
            <DeveloperActionButton to="/admin/api-keys" icon="fe fe-key" variant="primary">
              API keys
            </DeveloperActionButton>
          </>
        }
      >
        {loadError ? <LuxInlineAlert {...getLuxInlineAlertProps(loadError, "Unable to load developer portal.")} /> : null}
        <DeveloperInsightPanel insights={insights} loading={loading} />
        <DeveloperUsageAnalyticsPanel analytics={analytics} loading={loading} loadError={loadError} />
        <AppRegistryPanel apps={apps} loading={loading} />
        <AppRegisterDrawer
          open={registerOpen}
          onClose={() => this.setState({ registerOpen: false })}
          onCreate={(payload) => developerPortalService.createApp(payload)}
          onCreated={this.loadData}
        />
      </DeveloperLuxPage>
    );
  }
}

export default DeveloperPortalPage;
