import moment from "moment";
import {
  normalizeProjectStatus as normalizeDeliverableStatus,
  getProjectStatusMeta as getDeliverableStatusMeta,
  getProjectStatusSelectValue,
  PROJECT_STATUS_OPTIONS,
} from "./projectList.utils";

export {
  normalizeDeliverableStatus,
  getDeliverableStatusMeta,
  getProjectStatusSelectValue as getDeliverableStatusSelectValue,
  PROJECT_STATUS_OPTIONS as DELIVERABLE_STATUS_OPTIONS,
};

export function getDeliverableActivityPct(task) {
  const total = Number(task.taskActivityTotalCount) || 0;
  const done = Number(task.completedTaskActivityCount) || 0;
  if (!total) return 0;
  return Math.round((done / total) * 100);
}

export function isDeliverableOverdue(task) {
  if (!task || !task.estCompletionTime) return false;
  const status = normalizeDeliverableStatus(task.status);
  if (status === "COMPLETED" || status === "CLOSED") return false;
  return moment(task.estCompletionTime).isBefore(moment(), "day");
}

export function formatDeliverableMemberCount(task) {
  const ids = task && task.taskActivityEmployeeIds;
  if (!ids || !ids.length) return null;
  return ids.length;
}
