async function exportExecutiveBriefing(portfolioId) {
  const briefingResult = await getExecutiveBriefing(portfolioId);
  const csv = exportExecutiveBriefingCsv(briefingResult.payload);
  writePortfolioAudit(AUDIT_ACTION_TYPES.EXPORTED, "Executive portfolio briefing exported", portfolioId, {
    eventCode: "EXECUTIVE_EXPORT_GENERATED",
    portfolioId,
  });
  return { payload: csv, filename: `portfolio-briefing-${portfolioId}.csv`, source: briefingResult.source };
}

