import React from "react";
import classNames from "classnames/bind";
import dateUtils from "_helpers/date.utils";
import { getDayHeaderMeta } from "./timesheetBoard.utils";

export const TIMESHEET_DAY_COLUMN_COUNT = 7;

export function getTimesheetDayColumnClass(index) {
  return `lux-ts-board__col-day-${index}`;
}

function TimesheetWeekRail({ weekDates, maxHoursAllowed, sticky, onDayClick }) {
  if (!weekDates || !weekDates.length) return null;

  return (
    <div
      className={classNames("lux-ts-board__week-rail lux-ts-board__grid-row", { "is-sticky": sticky })}
      role="row"
      aria-label="Week days"
    >
      <div className="lux-ts-board__rail-meta lux-ts-board__col-meta">
        <span className="lux-ts-board__rail-meta-label">This week</span>
      </div>

      {weekDates.map((dateString, index) => {
        const dayMeta = getDayHeaderMeta(dateString);
        const dayName = dateUtils.WEEK_NAMES[index] || dayMeta.dayShort;

        return (
          <button
            type="button"
            key={dateString}
            className={classNames(
              "lux-ts-board__week-day",
              getTimesheetDayColumnClass(index),
              {
                "is-today": dayMeta.isToday,
                "is-weekend": dayMeta.isSaturday || dayMeta.isSunday,
                "is-clickable": !!onDayClick,
              }
            )}
            title={onDayClick ? `View ${dateString} summary` : dateString}
            onClick={onDayClick ? () => onDayClick(dateString) : undefined}
          >
            <span className="lux-ts-board__week-day-name">{dayName}</span>
            <span className="lux-ts-board__week-day-num">{dayMeta.dayNum}</span>
            {dayMeta.isToday && <span className="lux-ts-board__week-day-dot" aria-label="Today" />}
          </button>
        );
      })}

      <div className="lux-ts-board__rail-tools lux-ts-board__col-tools" aria-hidden="true" />
    </div>
  );
}

export default TimesheetWeekRail;
