import React, { Component } from "react";
import { recruitingService } from "_services/recruiting/recruiting.service";
import RecruitingLuxPage, {
  RecruitingActionButton,
  RecruitingLuxPanel,
} from "views/recruiting/components/RecruitingLuxShared";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

class InterviewsPage extends Component {
  state = {
    loading: true,
    loadError: null,
    rows: [],
    saving: false,
    form: { candidateRef: "", roundNumber: "1", interviewerEmployeeId: "", recommendation: "HOLD", comments: "", roundRef: "" },
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Interviews");
    }
    this.load();
  }

  load = async () => {
    this.setState({ loading: true, loadError: null });
    const result = await recruitingService.listInterviews();
    if (result.source === "api" && Array.isArray(result.payload)) {
      this.setState({ loading: false, rows: result.payload });
    } else {
      this.setState({
        loading: false,
        rows: [],
        loadError: result.error || new Error("Unable to load interviews"),
      });
    }
  };

  handleCreate = async (e) => {
    e.preventDefault();
    const { form } = this.state;
    if (!form.candidateRef) return;
    this.setState({ saving: true });
    const result = await recruitingService.createInterview({
      candidateRef: form.candidateRef,
      roundNumber: Number(form.roundNumber) || 1,
      interviewerEmployeeId: form.interviewerEmployeeId ? Number(form.interviewerEmployeeId) : null,
    });
    this.setState({ saving: false });
    if (result.source === "api") {
      this.setState({
        form: { ...form, candidateRef: "", interviewerEmployeeId: "" },
      });
      this.load();
    } else {
      this.setState({ loadError: result.error || new Error("Create failed") });
    }
  };

  handleFeedback = async (roundRef) => {
    const { form } = this.state;
    await recruitingService.submitFeedback({
      roundRef,
      recommendation: form.recommendation || "HOLD",
      comments: form.comments || null,
      rating: 3,
    });
    this.load();
  };

  render() {
    const { loading, loadError, rows, saving, form } = this.state;
    return (
      <RecruitingLuxPage
        testId="recruiting-interviews-page"
        dataSource={rows.length ? "api" : loadError ? "api-error" : loading ? null : "api"}
        pageMeta={{
          tone: "indigo",
          icon: "fe fe-calendar",
          eyebrow: "People · ATS",
          titleLead: "Interview",
          titleAccent: "rounds",
          lede: "Schedule rounds and capture interviewer feedback recommendations.",
        }}
      >
        {loadError ? (
          <LuxInlineAlert tone="warning" title="Unable to load interviews">
            {String(loadError.message || loadError)}
          </LuxInlineAlert>
        ) : null}
        <RecruitingLuxPanel title="Schedule interview" icon="fe fe-plus">
          <form className="lux-module-inline-form" onSubmit={this.handleCreate}>
            <div className="form-row">
              <div className="col-md-3">
                <input
                  className="form-control"
                  placeholder="Candidate ref"
                  value={form.candidateRef}
                  onChange={(e) => this.setState({ form: { ...form, candidateRef: e.target.value } })}
                />
              </div>
              <div className="col-md-2">
                <input
                  className="form-control"
                  placeholder="Round #"
                  value={form.roundNumber}
                  onChange={(e) => this.setState({ form: { ...form, roundNumber: e.target.value } })}
                />
              </div>
              <div className="col-md-3">
                <input
                  className="form-control"
                  placeholder="Interviewer employee id"
                  value={form.interviewerEmployeeId}
                  onChange={(e) => this.setState({ form: { ...form, interviewerEmployeeId: e.target.value } })}
                />
              </div>
              <div className="col-md-2">
                <RecruitingActionButton type="submit" disabled={saving}>
                  Schedule
                </RecruitingActionButton>
              </div>
            </div>
          </form>
        </RecruitingLuxPanel>
        <RecruitingLuxPanel title="Feedback defaults" meta="Applied when submitting feedback on a round" icon="fe fe-message-square">
          <div className="form-row">
            <div className="col-md-2">
              <select
                className="form-control"
                value={form.recommendation}
                onChange={(e) => this.setState({ form: { ...form, recommendation: e.target.value } })}
              >
                <option value="HIRE">HIRE</option>
                <option value="NO_HIRE">NO_HIRE</option>
                <option value="HOLD">HOLD</option>
              </select>
            </div>
            <div className="col-md-4">
              <input
                className="form-control"
                placeholder="Feedback comments"
                value={form.comments}
                onChange={(e) => this.setState({ form: { ...form, comments: e.target.value } })}
              />
            </div>
          </div>
        </RecruitingLuxPanel>
        <RecruitingLuxPanel title="Interview rounds" meta={`${rows.length} record${rows.length === 1 ? "" : "s"}`} icon="fe fe-list">
          {loading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="Loading"
              description="Fetching records."
            />
          ) : null}
          {!loading && rows.length === 0 ? (
            <LuxRegisterEmptyState
              title="No interview rounds yet"
              description="Schedule a round for a candidate to collect feedback."
              showCreate={false}
            />
          ) : !loading ? (
            <div className="lux-module-table-wrap">
              <table className="table table-sm mb-0">
                <thead>
                  <tr>
                    <th>Ref</th>
                    <th>Candidate id</th>
                    <th>Round</th>
                    <th>Status</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {rows.map((r) => (
                    <tr key={r.roundRef || r.id}>
                      <td>{r.roundRef}</td>
                      <td>{r.candidateId}</td>
                      <td>{r.roundNumber}</td>
                      <td>
                        <span className={`lux-expansion-status is-${String(r.status || "planned").toLowerCase()}`}>
                          {r.status || "Planned"}
                        </span>
                      </td>
                      <td>
                        {r.status !== "COMPLETED" && (
                          <RecruitingActionButton
                            type="button"
                            variant="ghost"
                            className="lux-onb-action--compact"
                            onClick={() => this.handleFeedback(r.roundRef)}
                          >
                            Submit feedback
                          </RecruitingActionButton>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : null}
        </RecruitingLuxPanel>
      </RecruitingLuxPage>
    );
  }
}

export default InterviewsPage;
