import {
  DOCUMENT_STATUSES,
  DOCUMENT_VISIBILITY,
  POLICY_ACK_STATUSES,
} from "config/document-vault.config";

function normalizeStatus(value) {
  return String(value || "").toLowerCase();
}

export function filterDocuments(documents, filters = {}) {
  const rows = documents || [];
  const { status, type, visibility, query, employeeId } = filters;

  return rows.filter((row) => {
    if (employeeId && String(row.employeeId) !== String(employeeId)) {
      return false;
    }
    if (status && status !== "ALL" && normalizeStatus(row.status) !== normalizeStatus(status)) {
      return false;
    }
    if (type && type !== "ALL" && row.type !== type) {
      return false;
    }
    if (visibility && visibility !== "ALL" && row.visibility !== visibility) {
      return false;
    }
    if (query) {
      const q = String(query).toLowerCase();
      const haystack = [row.title, row.employeeName, row.typeLabel, row.fileName]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();
      if (!haystack.includes(q)) {
        return false;
      }
    }
    return true;
  });
}

export function canViewDocument(document, viewerRole) {
  if (!document) {
    return false;
  }
  const role = String(viewerRole || "EMPLOYEE").toUpperCase();
  if (role === "ADMIN" || role === "HR_ADMIN") {
    return true;
  }
  const visibility = document.visibility || DOCUMENT_VISIBILITY.HR_ONLY;
  if (visibility === DOCUMENT_VISIBILITY.EMPLOYEE) {
    return true;
  }
  if (visibility === DOCUMENT_VISIBILITY.MANAGER && (role === "MANAGER" || role === "PROJECT_MANAGER")) {
    return true;
  }
  if (visibility === DOCUMENT_VISIBILITY.FINANCE_ONLY && (role === "FINANCE_MANAGER" || role === "PAYROLL_MANAGER")) {
    return true;
  }
  return false;
}

export function maskDocumentForViewer(document, viewerRole) {
  if (!document) {
    return document;
  }
  if (!canViewDocument(document, viewerRole)) {
    return {
      ...document,
      title: "Restricted document",
      fileName: "—",
      piiMasked: true,
      notes: "",
    };
  }
  if (document.piiMasked && viewerRole !== "HR_ADMIN" && viewerRole !== "ADMIN") {
    return {
      ...document,
      fileName: "—",
      notes: "",
    };
  }
  return document;
}

export function buildDocumentVaultMetrics(documents) {
  const rows = documents || [];
  const pending = rows.filter((row) => normalizeStatus(row.status).includes("pending")).length;
  const verified = rows.filter((row) => normalizeStatus(row.status).includes("verified")).length;
  const expiring = getExpiringDocuments(rows, 30).length;

  return {
    total: rows.length,
    pending,
    verified,
    expiring,
    employees: new Set(rows.map((row) => row.employeeId).filter(Boolean)).size,
  };
}

export function getDocumentsNeedingVerification(documents) {
  return (documents || []).filter((row) => normalizeStatus(row.status).includes("pending"));
}

export function getExpiringDocuments(documents, withinDays = 30) {
  const now = Date.now();
  const windowMs = withinDays * 24 * 60 * 60 * 1000;
  return (documents || []).filter((row) => {
    if (!row.expiresAt) {
      return false;
    }
    const expires = Date.parse(row.expiresAt);
    if (Number.isNaN(expires)) {
      return false;
    }
    return expires >= now && expires <= now + windowMs;
  });
}

export function buildDocumentComplianceMetrics(documents, policies) {
  const docRows = documents || [];
  const policyRows = policies || [];
  const verifiedPct =
    docRows.length === 0
      ? 0
      : Math.round(
          (docRows.filter((row) => normalizeStatus(row.status).includes("verified")).length / docRows.length) * 100
        );
  const pendingPolicies = policyRows.filter(
    (row) => row.status === POLICY_ACK_STATUSES.PENDING || row.status === POLICY_ACK_STATUSES.OVERDUE
  ).length;
  const overduePolicies = policyRows.filter((row) => row.status === POLICY_ACK_STATUSES.OVERDUE).length;

  return {
    verifiedPct,
    expiringCount: getExpiringDocuments(docRows, 30).length,
    pendingVerification: getDocumentsNeedingVerification(docRows).length,
    pendingPolicies,
    overduePolicies,
    policyCompliancePct:
      policyRows.length === 0
        ? 100
        : Math.round(
            (policyRows.filter((row) => row.status === POLICY_ACK_STATUSES.ACKNOWLEDGED).length / policyRows.length) *
              100
          ),
  };
}

export function buildDocumentComplianceChartRows(documents) {
  const rows = documents || [];
  const buckets = {};
  rows.forEach((row) => {
    const key = row.typeLabel || row.type || "Other";
    if (!buckets[key]) {
      buckets[key] = { label: key, verified: 0, pending: 0, total: 0 };
    }
    buckets[key].total += 1;
    if (normalizeStatus(row.status).includes("verified")) {
      buckets[key].verified += 1;
    } else if (normalizeStatus(row.status).includes("pending")) {
      buckets[key].pending += 1;
    }
  });
  return Object.values(buckets).sort((a, b) => b.total - a.total);
}

export function toEmployee360DocumentRow(document) {
  if (!document) {
    return null;
  }
  return {
    id: document.id,
    title: document.title,
    type: document.typeLabel || document.type,
    status: document.status,
    uploadedAt: document.uploadedAt,
  };
}
