import React from "react";
import classNames from "classnames/bind";

export function ProfileSettingsBanner({ readOnly, variant }) {
  if (readOnly) {
    return (
      <p className="profile-settings-banner is-muted" role="note">
        <i className="fe fe-eye" aria-hidden="true" />
        Viewing another employee&apos;s settings — changes are not available here.
      </p>
    );
  }

  return (
    <p className={classNames("profile-settings-banner", `is-${variant || "preview"}`)} role="note">
      <i className="fe fe-info" aria-hidden="true" />
      Preview on this device only — account sync from the server will be enabled in a future release.
    </p>
  );
}

export function ProfileSettingToggle({ icon, label, description, checked, disabled, onChange }) {
  return (
    <label
      className={classNames("profile-setting-row profile-setting-row--toggle", {
        "is-disabled": disabled,
      })}
    >
      <span className="profile-setting-row__icon">
        <i className={icon} aria-hidden="true" />
      </span>
      <span className="profile-setting-row__copy">
        <span className="profile-setting-row__label">{label}</span>
        {description && <span className="profile-setting-row__desc">{description}</span>}
      </span>
      <span className="profile-setting-row__control">
        <input
          type="checkbox"
          className="profile-setting-toggle__input"
          checked={!!checked}
          disabled={disabled}
          onChange={(e) => onChange && onChange(e.target.checked)}
        />
        <span className="profile-setting-toggle__track" aria-hidden="true" />
      </span>
    </label>
  );
}

export function ProfileSettingSelect({ icon, label, description, value, options, disabled, onChange }) {
  return (
    <label
      className={classNames("profile-setting-row profile-setting-row--select", {
        "is-disabled": disabled,
      })}
    >
      <span className="profile-setting-row__icon">
        <i className={icon} aria-hidden="true" />
      </span>
      <span className="profile-setting-row__copy">
        <span className="profile-setting-row__label">{label}</span>
        {description && <span className="profile-setting-row__desc">{description}</span>}
      </span>
      <span className="profile-setting-row__control">
        <select
          className="profile-setting-select"
          value={value}
          disabled={disabled}
          onChange={(e) => onChange && onChange(e.target.value)}
        >
          {options.map((opt) => (
            <option key={opt.value} value={opt.value}>
              {opt.label}
            </option>
          ))}
        </select>
      </span>
    </label>
  );
}

export function ProfileChannelCard({ icon, label, description, enabled, disabled, comingSoon, onChange }) {
  return (
    <div
      className={classNames("profile-channel-card", {
        "is-on": enabled,
        "is-off": !enabled,
        "is-disabled": disabled,
        "is-soon": comingSoon,
      })}
    >
      <span className="profile-channel-card__icon">
        <i className={icon} aria-hidden="true" />
      </span>
      <div className="profile-channel-card__copy">
        <strong>{label}</strong>
        <span>{description}</span>
      </div>
      {comingSoon ? (
        <span className="profile-channel-card__badge">Soon</span>
      ) : (
        <label className="profile-channel-card__switch">
          <input
            type="checkbox"
            checked={!!enabled}
            disabled={disabled}
            onChange={(e) => onChange && onChange(e.target.checked)}
          />
          <span className="profile-setting-toggle__track" aria-hidden="true" />
        </label>
      )}
    </div>
  );
}
