export function hasActiveAuditFilters(filters = {}) {
  return (
    (filters.entityType && filters.entityType !== "ALL") ||
    (filters.actionType && filters.actionType !== "ALL") ||
    Boolean(String(filters.query || "").trim())
  );
}
export function normalizeAdminAuditEvents(rows) {
  return (rows || []).map((row) => normalizeAuditEvent(row)).filter(Boolean);
}

export function buildMockAdminAuditEvents() {
  return normalizeAdminAuditEvents(
    MOCK_AUDIT_EVENTS.map((row) => ({
      id: row.id,
      createdAt: row.createdAt || new Date().toISOString(),
      actionType: row.actionType || "UPDATED",
      entityType: row.entityType || "EMPLOYEE",
      entity: {
        type: row.entityType || "EMPLOYEE",
        ref: row.entityLabel || row.entity,
      },
      actor: {
        name: row.actorUserName || row.actor || "System",
      },
    }))
  );
}

export function filterAdminAuditEvents(events, filters = {}) {
  const { entityType = "ALL", query = "", actionType = "ALL" } = filters;
  const normalizedQuery = String(query || "").trim().toLowerCase();

  return (events || []).filter((event) => {
    const eventEntityType = event.entityType || (event.entity && event.entity.type);
    if (entityType !== "ALL" && eventEntityType !== entityType) {
      return false;
    }
    if (actionType !== "ALL") {
      const actionKey = getActionMeta(event.actionType).key;
      if (actionKey !== actionType) {
        return false;
      }
    }
    if (!normalizedQuery) {
      return true;
    }
    const haystack = [
      getActorName(event),
      event.actionType,
      eventEntityType,
      event.headline,
      event.entity && event.entity.ref,
    ]
      .filter(Boolean)
      .join(" ")
      .toLowerCase();
    return haystack.includes(normalizedQuery);
  });
}

export function buildAuditAdminMetrics(events) {
  const rows = events || [];
  const now = Date.now();
  const dayMs = 24 * 60 * 60 * 1000;
  const recent24h = rows.filter((event) => {
    const date = new Date(event.createdDate);
    return !Number.isNaN(date.getTime()) && now - date.getTime() <= dayMs;
  }).length;
  const actors = new Set(
    rows.map((event) => getActorName(event)).filter((name) => name && name !== "Unknown user")
  );
  const approvals = rows.filter((event) => getActionMeta(event.actionType).key === "APPROVED").length;
  const delegateActions = rows.filter(
    (event) => getActionMeta(event.actionType).key === "DELEGATE_ACTED"
  ).length;

  const entityCounts = {};
  rows.forEach((event) => {
    const type = (event.entity && event.entity.type) || event.entityType || "UNKNOWN";
    entityCounts[type] = (entityCounts[type] || 0) + 1;
  });
  const topEntity = Object.entries(entityCounts).sort((a, b) => b[1] - a[1])[0];

  return {
    total: rows.length,
    recent24h,
    uniqueActors: actors.size,
    approvals,
    delegateActions,
    topEntityType: topEntity ? topEntity[0] : null,
    topEntityCount: topEntity ? topEntity[1] : 0,
  };
}

export function buildAuditAdminInsights(events, filters = {}) {
  const metrics = buildAuditAdminMetrics(events);
  const filtered = filterAdminAuditEvents(events, filters);
  const insights = [];

  if (metrics.recent24h >= 2) {
    insights.push({
      id: "volume",
      tone: "blue",
      icon: "fe fe-activity",
      title: `${metrics.recent24h} event(s) in the last 24 hours`,
      copy: "Review high-activity areas for compliance anomalies.",
    });
  }
  if (metrics.delegateActions > 0) {
    insights.push({
      id: "delegate",
      tone: "violet",
      icon: "fe fe-users",
      title: `${metrics.delegateActions} delegate action(s) recorded`,
      copy: "Verify acting approvals match delegation rules.",
    });
  }
  if (filtered.length > 0 && (filters.query || filters.entityType !== "ALL" || filters.actionType !== "ALL")) {
    insights.push({
      id: "export-ready",
      tone: "green",
      icon: "fe fe-download",
      title: `${filtered.length} event(s) match current filters`,
      copy: "Export CSV for compliance pack or regulator requests.",
    });
  }
  if (metrics.total === 0) {
    insights.push({
      id: "empty",
      tone: "slate",
      icon: "fe fe-shield",
      title: "No audit events yet",
      copy: "Organization-wide mutations will appear here once audit writes are enabled.",
    });
  }
  if (insights.length === 0) {
    const topLabel = metrics.topEntityType
      ? getEntityMeta(metrics.topEntityType).label
      : "records";
    insights.push({
      id: "baseline",
      tone: "primary",
      icon: "fe fe-shield",
      title: `${metrics.total} audit event(s) on file`,
      copy: `Most activity in ${topLabel.toLowerCase()} (${metrics.topEntityCount} event(s)).`,
    });
  }
  return insights.slice(0, 3);
}

const AUDIT_ACTION_TONES = {
  APPROVED: "green",
  SUBMITTED: "blue",
  UPDATED: "amber",
  STATUS_CHANGED: "violet",
  DELEGATE_ACTED: "indigo",
  AUDIT_VIEWED: "slate",
  EXPORTED: "rose",
};

export function buildAuditActionSeries(events) {
  const rows = normalizeAdminAuditEvents(events);
  const counts = {};
  rows.forEach((event) => {
    const key = event.actionType || "OTHER";
    counts[key] = (counts[key] || 0) + 1;
  });
  return Object.entries(counts)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 6)
    .map(([actionType, value]) => {
      const meta = getActionMeta(actionType);
      return {
        id: actionType,
        label: meta.label || actionType,
        value,
        tone: AUDIT_ACTION_TONES[actionType] || "slate",
      };
    });
}

function escapeCsvCell(value) {
  const str = String(value == null ? "" : value);
  if (/[",\n]/.test(str)) {
    return `"${str.replace(/"/g, '""')}"`;
  }
  return str;
}

export function buildAuditExportCsv(events) {
  const headers = ["Event ID", "Timestamp", "Actor", "Action", "Entity Type", "Entity Ref", "Headline"];
  const lines = [headers.join(",")];
  (events || []).forEach((event) => {
    const entityType = (event.entity && event.entity.type) || event.entityType || "";
    const row = [
      event.id || "",
      event.createdDate || "",
      getActorName(event),
      getActionMeta(event.actionType).label,
      entityType,
      (event.entity && event.entity.ref) || "",
      event.headline || "",
    ].map(escapeCsvCell);
    lines.push(row.join(","));
  });
  return lines.join("\n");
}

export function downloadAuditExportCsv(events, filename) {
  const csv = buildAuditExportCsv(events);
  const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
  const url = window.URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename || `tracopus-audit-export-${new Date().toISOString().slice(0, 10)}.csv`;
  link.click();
  window.URL.revokeObjectURL(url);
}
