import React from "react";
import classNames from "classnames/bind";
import OnboardingStatusBadge from "./OnboardingStatusBadge";
import { isTaskOverdue } from "config/onboarding.utils";

const CATEGORY_TONES = {
  HR: "violet",
  IT: "blue",
  Documents: "primary",
  Payroll: "green",
  Training: "teal",
  Manager: "amber",
  Access: "rose",
  Assets: "slate",
  Other: "neutral",
};

function taskIcon(status) {
  if (status === "completed") return "fe-check-circle";
  if (status === "blocked") return "fe-alert-circle";
  if (status === "in_progress") return "fe-loader";
  if (status === "skipped") return "fe-minus-circle";
  return "fe-circle";
}

function getOwnerInitials(owner = "") {
  return owner
    .split(" ")
    .filter(Boolean)
    .map((part) => part[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();
}

function OnboardingChecklistPanel({ groups, onTaskSelect, lifecycle = "onboarding" }) {
  if (!groups.length) {
    return (
      <div className="lux-onb-checklist-empty">
        <i className="fe fe-clipboard" aria-hidden />
        <p>No checklist tasks are configured for this case.</p>
      </div>
    );
  }

  return (
    <div className="lux-onb-checklist">
      {groups.map((group) => {
        const completed = group.tasks.filter(
          (task) => task.status === "completed" || task.status === "skipped"
        ).length;
        const pct = group.tasks.length
          ? Math.round((completed / group.tasks.length) * 100)
          : 0;
        const tone = CATEGORY_TONES[group.id] || CATEGORY_TONES.Other;

        return (
          <section
            key={group.id}
            className={classNames("lux-onb-checklist__group", `lux-onb-checklist__group--${tone}`)}
          >
            <header className="lux-onb-checklist__group-head">
              <div className="lux-onb-checklist__group-brand">
                <span className="lux-onb-checklist__group-icon" aria-hidden>
                  <i className={group.icon || "fe fe-check-square"} />
                </span>
                <div>
                  <h3 className="lux-onb-checklist__group-title">{group.label}</h3>
                  <p className="lux-onb-checklist__group-sub">
                    {completed} of {group.tasks.length} complete · {pct}% ready
                  </p>
                </div>
              </div>
              <span className="lux-onb-checklist__group-pill">{group.tasks.length} tasks</span>
            </header>

            <div className="lux-onb-checklist__group-progress" aria-hidden>
              <div className="lux-onb-checklist__group-progress-fill" style={{ width: `${pct}%` }} />
            </div>

            <ul className="lux-onb-checklist__tasks">
              {group.tasks.map((task, index) => {
                const overdue = isTaskOverdue(task);
                const isDone = task.status === "completed" || task.status === "skipped";

                return (
                  <li key={task.id}>
                    <button
                      type="button"
                      className={classNames("lux-onb-task", `lux-onb-task--${tone}`, {
                        "is-completed": isDone,
                        "is-blocked": task.status === "blocked",
                        "is-overdue": overdue,
                        "is-required": task.required,
                      })}
                      onClick={() => onTaskSelect(task)}
                    >
                      <span className="lux-onb-task__index">{index + 1}</span>
                      <span className={`lux-onb-task__state fe ${taskIcon(task.status)}`} aria-hidden />
                      <span className="lux-onb-task__body">
                        <strong className="lux-onb-task__title">{task.title}</strong>
                        <span className="lux-onb-task__meta">
                          <span className="lux-onb-task__owner-chip">
                            <span className="lux-onb-task__owner-avatar" aria-hidden>
                              {getOwnerInitials(task.owner)}
                            </span>
                            {task.owner}
                          </span>
                          {task.dueDate && (
                            <span className={classNames("lux-onb-task__due-chip", { "is-overdue": overdue })}>
                              <i className="fe fe-calendar" aria-hidden />
                              {task.dueDate}
                            </span>
                          )}
                          {!task.required && (
                            <span className="lux-onb-task__optional-chip">Optional</span>
                          )}
                        </span>
                      </span>
                      <OnboardingStatusBadge status={task.status} variant="task" lifecycle={lifecycle} />
                      <i className="fe fe-chevron-right lux-onb-task__chevron" aria-hidden />
                    </button>
                  </li>
                );
              })}
            </ul>
          </section>
        );
      })}
    </div>
  );
}

export default OnboardingChecklistPanel;
