import React from "react";
import classNames from "classnames/bind";
import { getOrgUnitTypeMeta } from "config/org-structure.utils";

export default function OrgUnitRegister({ orgUnits, onSelect, selectedId }) {
  return (
    <div className="lux-org-unit-register-wrap">
      <table className="lux-org-unit-register">
        <thead>
          <tr>
            <th>Org unit</th>
            <th>Type</th>
            <th>Head</th>
            <th>Headcount</th>
            <th>Cost center</th>
            <th>Status</th>
          </tr>
        </thead>
        <tbody>
          {orgUnits.map((row) => {
            const typeMeta = getOrgUnitTypeMeta(row.type);
            const isVacant = !row.headEmployeeId;
            return (
              <tr
                key={row.id}
                className={classNames("lux-org-unit-register__row", {
                  "is-selected": selectedId === row.id,
                  "is-attention": isVacant,
                })}
                onClick={() => onSelect && onSelect(row)}
              >
                <td>
                  <div className="lux-org-unit-register__primary">
                    <span className={classNames("lux-org-unit-register__icon", typeMeta.tone && `is-${typeMeta.tone}`)} aria-hidden="true">
                      <i className={typeMeta.icon} />
                    </span>
                    <span className="lux-org-unit-register__primary-copy">
                      <strong>{row.name}</strong>
                      {row.location && <span className="lux-org-unit-register__meta">{row.location}</span>}
                    </span>
                  </div>
                </td>
                <td>
                  <span className={classNames("lux-org-unit-register__chip", typeMeta.tone && `is-${typeMeta.tone}`)}>
                    {typeMeta.label}
                  </span>
                </td>
                <td>{row.headEmployeeName || <span className="lux-org-unit-register__vacant">Vacant</span>}</td>
                <td>{row.headcount != null ? row.headcount : "—"}</td>
                <td>{row.costCenter || "—"}</td>
                <td>
                  <span className={classNames("lux-doc-badge", row.status === "Active" ? "is-primary" : "is-slate")}>
                    {row.status}
                  </span>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
