import React from "react";
import classNames from "classnames/bind";
import CountUp from "react-countup";

function KpiCard({ label, value, suffix, hint, tone, icon, loading, linkTo, linkLabel }) {
  return (
    <article className={classNames("lux-hrms-dash__kpi", tone && `is-${tone}`)}>
      <div className="lux-hrms-dash__kpi-top">
        <span className="lux-hrms-dash__kpi-label">{label}</span>
        {icon && (
          <span className="lux-hrms-dash__kpi-icon" aria-hidden="true">
            <i className={`fe ${icon}`} />
          </span>
        )}
      </div>
      <strong className="lux-hrms-dash__kpi-value">
        {loading ? (
          "—"
        ) : (
          <>
            <CountUp end={Number(value) || 0} duration={0.8} separator="," />
            {suffix && <small>{suffix}</small>}
          </>
        )}
      </strong>
      {hint && <span className="lux-hrms-dash__kpi-hint">{hint}</span>}
      {linkTo && (
        <a href={linkTo} className="lux-hrms-dash__kpi-link">
          {linkLabel || "View"} <i className="fe fe-arrow-right" aria-hidden="true" />
        </a>
      )}
    </article>
  );
}

function EmployeeDashboardKpiStrip({ stats, loading, weeklyHours, variant = "manager" }) {
  const cards = [
    {
      key: "total",
      label: "Total workforce",
      value: stats.total,
      hint: `${stats.selectedTeams || "All"} teams in scope`,
      tone: "primary",
      icon: "fe-users",
    },
    {
      key: "active",
      label: "Active employees",
      value: stats.active,
      hint: `${stats.activeRate}% active rate`,
      tone: "green",
      icon: "fe-user-check",
      linkTo: "/people/employees",
      linkLabel: "Open roster",
    },
    {
      key: "inactive",
      label: "Inactive",
      value: stats.inactive,
      hint: "Profiles deactivated or exited",
      tone: "amber",
      icon: "fe-user-x",
    },
    {
      key: "new",
      label: "New joiners",
      value: stats.newJoiners30,
      hint: "Joined in last 30 days",
      tone: "violet",
      icon: "fe-user-plus",
    },
    {
      key: "teams",
      label: "Teams represented",
      value: stats.uniqueTeams,
      hint: "Across active employees",
      tone: "blue",
      icon: "fe-layers",
    },
    {
      key: "skills",
      label: "Skills tracked",
      value: stats.uniqueSkills,
      hint: "Primary skills in roster",
      tone: "teal",
      icon: "fe-award",
    },
    {
      key: "permanent",
      label: "Permanent staff",
      value: stats.fulltime,
      hint: `${stats.contract} contract · ${stats.intern} intern`,
      tone: "slate",
      icon: "fe-briefcase",
    },
  ];

  if (variant !== "manager") {
    cards.push({
      key: "hours",
      label: "Your week logged",
      value: weeklyHours != null ? weeklyHours : 0,
      suffix: weeklyHours != null ? "h" : "",
      hint: weeklyHours != null ? "Billable + non-billable + leave" : "Utilization unavailable",
      tone: "rose",
      icon: "fe-clock",
      linkTo: "/people/timesheet",
      linkLabel: "Timesheets",
    });
  }

  return (
    <section className="lux-hrms-dash__kpi-strip" aria-label="Workforce KPIs">
      {cards.map((card) => (
        <KpiCard key={card.key} {...card} loading={loading} />
      ))}
    </section>
  );
}

export default EmployeeDashboardKpiStrip;
