import React from 'react';
import { connect } from 'react-redux';
import { withRouter } from 'react-router-dom';
import { leavePhase2Service as api } from '_services/leavePhase2.service';
import { getApiErrorMessage } from '_helpers/apiError.utils';
import { AdminActionButton } from 'views/admin/components/AdminLuxShared';
import {
  LeavePhase2AdminBase,
  LeavePhase2Panel,
  LeavePhase2Register,
  mapLeavePhase2State,
  renderLeavePhase2Nav,
  LEAVE_PHASE2_EMPTY_DESCRIPTION,
  cell,
} from './leavePhase2.shared';
import '../leaveLuxForms.css';

const NAV = [
  { path: '/admin/leave/agreements', label: 'Agreements', icon: 'fe fe-users', exact: true },
  { path: '/admin/leave/contract-overrides', label: 'Contract overrides', icon: 'fe fe-file' },
];

const EMPTY_AGREEMENT = { name: '', agreementType: 'CBA' };

function sectionFromPath(pathname) {
  if (pathname.includes('contract-overrides')) return 'overrides';
  return 'agreements';
}

class LeaveAgreementsPage extends LeavePhase2AdminBase {
  state = {
    ...this.state,
    agreements: [],
    overrides: [],
    versions: [],
    saving: false,
    agreementForm: { ...EMPTY_AGREEMENT },
  };

  fetchSectionData = async (teamId) => {
    const section = sectionFromPath(this.props.location.pathname);
    if (section === 'agreements') {
      const agreements = (await api.listAgreements(teamId)) || [];
      const list = Array.isArray(agreements) ? agreements : [];
      this.setState({ agreements: list, versions: [] });
      if (list.length && list[0].id) {
        const versions = (await api.listAgreementVersions(list[0].id).catch(() => [])) || [];
        this.setState({ versions: Array.isArray(versions) ? versions : [] });
      }
      return;
    }
    const overrides = (await api.listContractOverrides(teamId)) || [];
    this.setState({ overrides: Array.isArray(overrides) ? overrides : [] });
  };

  createAgreement = (event) => {
    event.preventDefault();
    const { agreementForm } = this.state;
    const name = (agreementForm.name || '').trim();
    if (!name) return;
    const teamId = this.teamId();
    if (!teamId) {
      this.setState({ error: 'Select a team first.' });
      return;
    }
    this.setState({ saving: true, error: null, notice: null });
    api
      .createAgreement({
        userTeamId: teamId,
        actorId: this.actorId(),
        name,
        agreementType: agreementForm.agreementType || 'CBA',
        active: true,
      })
      .then(() => {
        this.setState({
          saving: false,
          notice: 'Agreement created. Publish a version for resolve/accrual merge.',
          agreementForm: { ...EMPTY_AGREEMENT },
        });
        return this.loadAll();
      })
      .catch((e) => {
        this.setState({
          saving: false,
          error: getApiErrorMessage(e, 'Could not create agreement.'),
        });
      });
  };

  render() {
    const { loading, agreements, overrides, versions, agreementForm, saving } = this.state;
    const section = sectionFromPath(this.props.location.pathname);
    const kpiCards = [
      { id: 'agr', label: 'Agreements', value: agreements.length, tone: 'primary', icon: 'fe fe-users' },
      { id: 'ovr', label: 'Overrides', value: overrides.length, tone: 'blue', icon: 'fe fe-file' },
    ];

    return this.renderChrome({
      testId: 'page-leave-agreements',
      kpiCards,
      pageMeta: {
        tone: 'emerald',
        icon: 'fe fe-users',
        eyebrow: 'Admin · Leave',
        titleLead: 'Agreements',
        titleAccent: '& contracts',
        lede: 'CBA/union layers and contract overrides — minimal create form; versions/overrides via API when forms are absent.',
      },
      heroNav: renderLeavePhase2Nav(NAV, this.props.location.pathname),
      children: (
        <>
          {section === 'agreements' && (
            <>
              <LeavePhase2Panel
                title="Create agreement"
                subtitle="Minimal shell — add versions via API or follow-on forms."
                testId="glp19-create-agreement"
              >
                <form
                  className="lux-glp-form"
                  onSubmit={this.createAgreement}
                  data-testid="glp19-create-agreement-form"
                >
                  <label>
                    Name
                    <input
                      required
                      value={agreementForm.name}
                      onChange={(e) =>
                        this.setState({
                          agreementForm: { ...agreementForm, name: e.target.value },
                        })
                      }
                      placeholder="Plant CBA 2026"
                    />
                  </label>
                  <label>
                    Type
                    <select
                      value={agreementForm.agreementType}
                      onChange={(e) =>
                        this.setState({
                          agreementForm: { ...agreementForm, agreementType: e.target.value },
                        })
                      }
                    >
                      <option value="CBA">CBA / Union</option>
                      <option value="CONTRACT">Employment contract</option>
                      <option value="LOCAL">Local agreement</option>
                    </select>
                  </label>
                  <div className="lux-glp-form__actions">
                    <AdminActionButton type="submit" icon="fe fe-plus" disabled={saving || loading}>
                      Create agreement
                    </AdminActionButton>
                  </div>
                </form>
              </LeavePhase2Panel>
              <LeavePhase2Panel
                title="Collective agreements"
                subtitle="Effective-dated agreement rule layers above location policy."
              >
                <LeavePhase2Register
                  loading={loading}
                  rows={agreements}
                  testId="glp19-agreements-register"
                  emptyTitle="No agreements"
                  emptyDescription={LEAVE_PHASE2_EMPTY_DESCRIPTION}
                  columns={[
                    { key: 'id', label: 'ID' },
                    { key: 'name', label: 'Name' },
                    { key: 'agreementType', label: 'Type', render: (r) => cell(r.agreementType || r.type) },
                    { key: 'status', label: 'Status' },
                    { key: 'effectiveFrom', label: 'Effective' },
                  ]}
                />
              </LeavePhase2Panel>
              {agreements.length ? (
                <LeavePhase2Panel title="Agreement versions" subtitle="Version history for the first agreement in scope.">
                  <LeavePhase2Register
                    loading={loading}
                    rows={versions}
                    testId="glp19-versions-register"
                    emptyTitle="No versions"
                    emptyDescription={LEAVE_PHASE2_EMPTY_DESCRIPTION}
                    columns={[
                      { key: 'id', label: 'Version' },
                      { key: 'versionNumber', label: 'Number' },
                      { key: 'status', label: 'Status' },
                      { key: 'effectiveFrom', label: 'From' },
                    ]}
                  />
                </LeavePhase2Panel>
              ) : null}
            </>
          )}
          {section === 'overrides' && (
            <LeavePhase2Panel title="Employment contract overrides" subtitle="Employee-specific contract rules in precedence stack.">
              <LeavePhase2Register
                loading={loading}
                rows={overrides}
                testId="glp19-overrides-register"
                emptyTitle="No contract overrides"
                emptyDescription={LEAVE_PHASE2_EMPTY_DESCRIPTION}
                columns={[
                  { key: 'id', label: 'ID' },
                  { key: 'employeeId', label: 'Employee' },
                  { key: 'contractRef', label: 'Contract', render: (r) => cell(r.contractRef || r.contractCode) },
                  { key: 'effectiveFrom', label: 'From' },
                  { key: 'status', label: 'Status' },
                ]}
              />
            </LeavePhase2Panel>
          )}
        </>
      ),
    });
  }
}

export default connect(mapLeavePhase2State)(withRouter(LeaveAgreementsPage));
