import React, { Component } from "react";
import classNames from "classnames/bind";
import LuxListRowMenuPortal from "views/common/fragments/LuxListRowMenuPortal";
import { getFileMimeMeta, getOwnerInitials } from "./fileManager.utils";

class FileManagerListRow extends Component {
  constructor(props) {
    super(props);
    this.state = { menuOpen: false };
    this.rowRef = React.createRef();
    this.menuTriggerRef = React.createRef();
  }

  componentDidMount() {
    document.addEventListener("mousedown", this.handleOutsideClick);
  }

  componentWillUnmount() {
    document.removeEventListener("mousedown", this.handleOutsideClick);
  }

  handleOutsideClick = (event) => {
    if (!this.state.menuOpen) return;
    if (event.target.closest(".lux-list-row-menu-portal")) return;
    if (this.rowRef.current && !this.rowRef.current.contains(event.target)) {
      this.setState({ menuOpen: false });
    }
  };

  toggleMenu = (event) => {
    event.preventDefault();
    event.stopPropagation();
    this.setState((prev) => ({ menuOpen: !prev.menuOpen }));
  };

  closeMenu = () => this.setState({ menuOpen: false });

  runAction = (handler) => (event) => {
    event.preventDefault();
    event.stopPropagation();
    this.closeMenu();
    if (handler) handler(this.props.item);
  };

  handleRowClick = () => {
    const { item, onOpenItem } = this.props;
    if (onOpenItem) onOpenItem(item);
  };

  renderSharedAvatars = () => {
    const { item } = this.props;
    if (!item.isShared || !item.sharedWith || item.sharedWith.length === 0) {
      return <span className="lux-file-row__shared-empty">Private</span>;
    }
    const visible = item.sharedWith.slice(0, 3);
    const extra = item.sharedWith.length - visible.length;
    return (
      <div className="lux-file-row__shared">
        <div className="lux-file-row__avatars" aria-label={`Shared with ${item.sharedWith.length} people`}>
          {visible.map((person) => (
            <span
              key={person.name}
              className="lux-file-row__avatar"
              title={person.name}
            >
              {getOwnerInitials(person.name)}
            </span>
          ))}
        </div>
        {extra > 0 && <span className="lux-file-row__shared-more">+{extra}</span>}
      </div>
    );
  };

  renderMenuItem = (entry) => (
    <button
      key={entry.key}
      type="button"
      className={classNames("lux-list-row-menu__item", entry.danger && "is-danger")}
      onClick={this.runAction(entry.action)}
    >
      <i className={entry.icon} aria-hidden="true" />
      {entry.label}
    </button>
  );

  render() {
    const { item, rowIndex, onDownload, onShare, onRename, onDelete } = this.props;
    const meta = getFileMimeMeta(item.mimeKind);
    const isFolder = item.type === "folder";

    const menuItems = [
      isFolder
        ? { key: "open", label: "Open folder", icon: "fe fe-folder", action: this.props.onOpenItem }
        : { key: "download", label: "Download", icon: "fe fe-download", action: onDownload },
      { key: "share", label: "Share", icon: "fe fe-share-2", action: onShare },
      { key: "rename", label: "Rename", icon: "fe fe-edit-2", action: onRename },
      { key: "delete", label: "Remove", icon: "fe fe-trash-2", action: onDelete, danger: true },
    ];

    return (
      <div
        ref={this.rowRef}
        className={classNames("lux-bid-list__item lux-file-row", {
          "is-menu-open": this.state.menuOpen,
          "is-folder": isFolder,
        })}
        role="listitem"
        onClick={this.handleRowClick}
      >
        <div className="lux-bid-list__cell lux-bid-list__cell--index lux-file-row__index">
          {rowIndex}
        </div>
        <div className="lux-bid-list__cell lux-bid-list__cell--type lux-file-row__type">
          <span className={classNames("lux-file-row__type-icon", `is-${meta.tone}`)} aria-hidden="true">
            <i className={meta.icon} />
          </span>
        </div>
        <div className="lux-bid-list__cell lux-bid-list__cell--name lux-file-row__name-col">
          <div className="lux-file-row__name">
            <span className="lux-file-row__name-text" title={item.name}>
              {item.name}
            </span>
            {item.starred && (
              <span className="lux-file-row__star" title="Starred">
                <i className="fe fe-star" aria-hidden="true" />
              </span>
            )}
            <span className={classNames("lux-file-row__kind", `is-${meta.tone}`)}>{meta.label}</span>
          </div>
        </div>
        <div className="lux-bid-list__cell lux-bid-list__cell--shared lux-file-row__shared-col">
          {this.renderSharedAvatars()}
        </div>
        <div className="lux-bid-list__cell lux-bid-list__cell--owner lux-file-row__owner-col">
          <span className="lux-file-row__owner">
            <span className="lux-file-row__owner-avatar">{getOwnerInitials(item.owner)}</span>
            <span className="lux-file-row__owner-name">{item.owner}</span>
          </span>
        </div>
        <div className="lux-bid-list__cell lux-bid-list__cell--date lux-file-row__date-col">
          <span className="lux-file-row__date">{item.lastUpdatedLabel}</span>
        </div>
        <div className="lux-bid-list__cell lux-bid-list__cell--size lux-file-row__size-col">
          <span className="lux-file-row__size">{item.sizeLabel}</span>
        </div>
        <div className="lux-bid-list__cell lux-bid-list__cell--actions lux-file-row__actions-col is-center">
          <button
            ref={this.menuTriggerRef}
            type="button"
            className="lux-bid-list__menu-btn"
            aria-label={`Actions for ${item.name}`}
            aria-expanded={this.state.menuOpen}
            onClick={this.toggleMenu}
          >
            <i className="fe fe-more-vertical" aria-hidden="true" />
          </button>
          <LuxListRowMenuPortal
            open={this.state.menuOpen}
            anchorRef={this.menuTriggerRef}
            className="lux-bid-list__menu-panel"
          >
            {menuItems.map((entry) => this.renderMenuItem(entry))}
          </LuxListRowMenuPortal>
        </div>
      </div>
    );
  }
}

export default FileManagerListRow;
