import React from "react";
import classNames from "classnames/bind";
import {
  formatSubmittedDate,
  formatTimesheetWeekRange,
  groupPendingTimesheetWeeksByEmployee,
} from "./timesheetApproval.utils";
import TimesheetApprovalCommentField from "./TimesheetApprovalCommentField";
import ApprovalActingForBadge from "../delegation/ApprovalActingForBadge";

const TimesheetApprovalTable = ({
  weeks,
  comments,
  rejectErrors,
  conflictCounts,
  isLoading,
  actingDelegations,
  employees,
  onCommentChange,
  onApprove,
  onReject,
  onOpenConflicts,
  onViewWeek,
}) => {
  if (!weeks || !weeks.length) return null;

  const groups = groupPendingTimesheetWeeksByEmployee(weeks);

  return (
    <div className="lux-ts-pending__list" role="list" aria-label="Pending timesheet weeks">
      {groups.map((group) => (
        <div key={group.employeeId} className="lux-ts-pending__group">
          <h4 className="lux-ts-pending__employee">
            <span className="lux-ts-pending__employee-avatar" aria-hidden="true">
              {(group.employeeName || "?").charAt(0).toUpperCase()}
            </span>
            <span className="lux-ts-pending__employee-copy">
              <strong>{group.employeeName}</strong>
              <em>
                {group.items.length} week{group.items.length === 1 ? "" : "s"} awaiting review
              </em>
            </span>
          </h4>

          {group.items.map((week) => {
            const weekId = week.id;
            const conflictCount = conflictCounts && conflictCounts[weekId];
            const hasConflicts = conflictCount > 0;

            return (
              <article key={weekId} className="lux-ts-pending__card" role="listitem">
                <div className="lux-ts-pending__card-head">
                  <div className="lux-ts-pending__card-main">
                    <div className="lux-ts-pending__card-title-row">
                      <strong>{formatTimesheetWeekRange(week)}</strong>
                      <ApprovalActingForBadge
                        record={week}
                        actingDelegations={actingDelegations}
                        employees={employees}
                      />
                    </div>
                    <span>Submitted {formatSubmittedDate(week)}</span>
                    {hasConflicts ? (
                      <em className="lux-ts-pending__card-warn">
                        Resolve {conflictCount} conflict{conflictCount === 1 ? "" : "s"} before approval
                      </em>
                    ) : (
                      <em>Ready for manager decision</em>
                    )}
                  </div>
                  {hasConflicts && (
                    <span
                      className="lux-ts-pending__conflict-badge"
                      title="Open conflicts must be resolved before approval"
                    >
                      <i className="fe fe-alert-triangle" aria-hidden="true" />
                      {conflictCount}
                    </span>
                  )}
                </div>

                <div className="lux-ts-pending__row-actions">
                  <button
                    type="button"
                    className="lux-ts-pending__btn is-ghost"
                    disabled={isLoading}
                    onClick={() => onViewWeek && onViewWeek(week)}
                  >
                    <i className="fe fe-eye" aria-hidden="true" />
                    View week
                  </button>
                  {onOpenConflicts && (
                    <button
                      type="button"
                      className={classNames("lux-ts-pending__btn is-ghost", {
                        "is-warning": hasConflicts,
                      })}
                      disabled={isLoading}
                      onClick={() => onOpenConflicts(week)}
                    >
                      <i className="fe fe-git-merge" aria-hidden="true" />
                      {hasConflicts ? "Resolve conflicts" : "Check conflicts"}
                    </button>
                  )}
                </div>

                <TimesheetApprovalCommentField
                  value={(comments && comments[weekId]) || ""}
                  onChange={(value) => onCommentChange(weekId, value)}
                  disabled={isLoading}
                  required
                  error={rejectErrors && rejectErrors[weekId]}
                  id={`lux-ts-pending-comment-${weekId}`}
                />

                <div className="lux-ts-pending__actions">
                  <button
                    type="button"
                    className={classNames("lux-ts-pending__btn is-primary", {
                      "is-loading": isLoading,
                    })}
                    disabled={isLoading || hasConflicts}
                    title={
                      hasConflicts
                        ? "Resolve conflicts before approving"
                        : "Approve timesheet"
                    }
                    onClick={() =>
                      onApprove && onApprove(week, (comments && comments[weekId]) || "")
                    }
                  >
                    Approve
                  </button>
                  <button
                    type="button"
                    className={classNames("lux-ts-pending__btn is-danger", {
                      "is-loading": isLoading,
                    })}
                    disabled={isLoading}
                    onClick={() =>
                      onReject && onReject(week, (comments && comments[weekId]) || "")
                    }
                  >
                    Reject
                  </button>
                </div>
              </article>
            );
          })}
        </div>
      ))}
    </div>
  );
};

export default TimesheetApprovalTable;
