import React, { PureComponent } from "react";
import Skeleton from "react-loading-skeleton";
import { LUX_SKELETON_THEME } from "views/common/fragments/luxSkeleton.constants";
import AttendanceMatrixRow from "./AttendanceMatrixRow";
import AttendanceEmployeeFilter from "./AttendanceEmployeeFilter";
import { getDayMeta } from "./attendance.utils";

class AttendanceMatrix extends PureComponent {
  renderHeaderDays = () =>
    this.props.monthDays.map((dayMonth) => {
      const meta = getDayMeta(dayMonth, this.props.workdays, this.props.holidayDates);
      return (
        <th
          key={dayMonth.format("YYYY-MM-DD")}
          className={classNamesHeader(meta)}
          scope="col"
          title={
            meta.isHoliday
              ? `${dayMonth.format("dddd, MMMM D")} · holiday`
              : meta.isWeekend
              ? `${dayMonth.format("dddd, MMMM D")} · optional attendance day`
              : dayMonth.format("dddd, MMMM D")
          }
        >
          <span className="lux-att-matrix__day-num">{meta.dayNum}</span>
          <span className="lux-att-matrix__day-label">{meta.dayShort}</span>
          {meta.isHoliday ? (
            <span className="lux-att-matrix__day-optional">Hol</span>
          ) : meta.isWeekend ? (
            <span className="lux-att-matrix__day-optional">Opt</span>
          ) : null}
        </th>
      );
    });

  renderSkeleton = () =>
    [1, 2, 3, 4, 5, 6, 7, 8].map((key) => (
      <tr key={key}>
        <td colSpan={this.props.monthDays.length + 1}>
          <Skeleton
            height={48}
            borderRadius={10}
            baseColor={LUX_SKELETON_THEME.baseColor}
            highlightColor={LUX_SKELETON_THEME.highlightColor}
          />
        </td>
      </tr>
    ));

  render() {
    const {
      employees,
      monthDays,
      items,
      permission,
      isLoading,
      currentUserId,
      createAttendance,
      deleteAttendance,
      onRequestMark,
      onRequestViewDetails,
      employeeFilterEmployees,
      selectedEmployeeId,
      onEmployeeFilterChange,
    } = this.props;

    return (
      <div className="lux-att-matrix">
        <div className="lux-att-matrix__legend" aria-label="Attendance legend">
          <span className="lux-att-matrix__legend-item is-present">
            <i className="fe fe-check" aria-hidden="true" /> Present
          </span>
          <span className="lux-att-matrix__legend-item is-pending">
            <i className="fe fe-clock" aria-hidden="true" /> Pending
          </span>
          <span className="lux-att-matrix__legend-item is-rejected">
            <i className="fe fe-x" aria-hidden="true" /> Rejected
          </span>
          <span className="lux-att-matrix__legend-item is-absent">
            <i className="fe fe-minus" aria-hidden="true" /> Absent
          </span>
          <span className="lux-att-matrix__legend-item is-today">
            <span className="lux-att-matrix__legend-dot" /> Today
          </span>
          <span className="lux-att-matrix__legend-item is-optional-sat">
            <span className="lux-att-matrix__legend-swatch is-sat" aria-hidden="true" />
            Sat · optional
          </span>
          <span className="lux-att-matrix__legend-item is-optional-sun">
            <span className="lux-att-matrix__legend-swatch is-sun" aria-hidden="true" />
            Sun · optional
          </span>
          <span className="lux-att-matrix__legend-item is-future">Future</span>
        </div>

        <div className="lux-att-matrix__scroll">
          <table className="lux-att-matrix__table">
            <thead>
              <tr>
                <th className="lux-att-matrix__th-employee" scope="col">
                  <div className="lux-att-matrix__th-employee-inner">
                    <span className="lux-att-matrix__th-employee-label">Employee</span>
                    {employeeFilterEmployees && employeeFilterEmployees.length > 0 && (
                      <AttendanceEmployeeFilter
                        variant="matrix"
                        employees={employeeFilterEmployees}
                        selectedEmployeeId={selectedEmployeeId}
                        onChange={onEmployeeFilterChange}
                        isLoading={isLoading}
                      />
                    )}
                  </div>
                </th>
                {this.renderHeaderDays()}
              </tr>
            </thead>
            <tbody>
              {isLoading && this.renderSkeleton()}
              {!isLoading &&
                employees &&
                employees.map((employee) => (
                  <AttendanceMatrixRow
                    key={employee.id}
                    employee={employee}
                    monthDays={monthDays}
                    items={items}
                    permission={permission}
                    isLoading={isLoading}
                    isCurrentUser={currentUserId === employee.id}
                    currentUserId={currentUserId}
                    createAttendance={createAttendance}
                    deleteAttendance={deleteAttendance}
                    onRequestMark={onRequestMark}
                    onRequestViewDetails={onRequestViewDetails}
                    workdays={this.props.workdays}
                    holidayDates={this.props.holidayDates}
                  />
                ))}
            </tbody>
          </table>
        </div>
      </div>
    );
  }
}

function classNamesHeader(meta) {
  const classes = ["lux-att-matrix__th-day"];
  if (meta.isSaturday) classes.push("is-weekend-sat");
  if (meta.isSunday) classes.push("is-weekend-sun");
  if (meta.isHoliday) classes.push("is-holiday");
  if (meta.isToday) classes.push("is-today");
  if (meta.isFuture) classes.push("is-future");
  return classes.join(" ");
}

export default AttendanceMatrix;
