import React, { Component } from "react";
import { connect } from "react-redux";
import classNames from "classnames/bind";
import { store } from "_helpers";
import { auditActions } from "_actions";
import {
  AUDIT_DEFAULT_PAGE_SIZE,
  AUDIT_ENTITY_FILTER_OPTIONS,
  AUDIT_SCOPES,
} from "_constants/audit.constants";
import {
  buildAuditScopeKey,
  enrichAuditEventsWithEmployees,
  filterEventsByEntityType,
  filterEventsByViewMode,
} from "_helpers/audit.utils";
import {
  readAuditPanelEntityFilter,
  writeAuditPanelPrefs,
} from "_helpers/audit.panel.utils";
import { isAuditUiEnabled } from "_helpers/audit.config";
import AuditTimeline from "./AuditTimeline";

class AuditTrailSection extends Component {
  componentDidMount() {
    this.applyInitialFilter();
    if (!this.props.disabled) {
      this.loadIfNeeded();
    }
  }

  componentDidUpdate(prevProps) {
    if (this.props.disabled) {
      return;
    }
    if (
      prevProps.disabled !== this.props.disabled ||
      prevProps.scope !== this.props.scope ||
      prevProps.actorUserId !== this.props.actorUserId ||
      prevProps.entityType !== this.props.entityType ||
      prevProps.entityId !== this.props.entityId
    ) {
      this.applyInitialFilter();
      this.loadIfNeeded();
    }
  }

  resolveInitialEntityFilter = () => {
    const { initialEntityFilter, persistKey, lockedEntityFilter } = this.props;
    if (lockedEntityFilter) {
      return lockedEntityFilter;
    }
    if (persistKey) {
      const saved = readAuditPanelEntityFilter(persistKey, initialEntityFilter || "ALL");
      if (saved) return saved;
    }
    return initialEntityFilter;
  };

  applyInitialFilter = () => {
    const filter = this.resolveInitialEntityFilter();
    if (!filter || filter === "ALL") return;
    const scopeKey = this.getScopeKey();
    store.dispatch(
      auditActions.setTimelineFilters(scopeKey, { entityType: filter })
    );
  };

  getScopeKey = () => {
    const { scope, actorUserId, entityType, entityId } = this.props;
    if (scope === AUDIT_SCOPES.ACTOR) {
      return buildAuditScopeKey("actor", { actorUserId });
    }
    return buildAuditScopeKey("entity", { entityType, entityId });
  };

  loadTimeline = (page = 1) => {
    const { scope, actorUserId, entityType, entityId, disabled } = this.props;
    if (disabled || !isAuditUiEnabled()) return;

    const params = { page, pageSize: AUDIT_DEFAULT_PAGE_SIZE };

    if (scope === AUDIT_SCOPES.ACTOR && actorUserId) {
      store.dispatch(auditActions.loadActorTimeline(actorUserId, params));
      return;
    }

    if (scope === AUDIT_SCOPES.ENTITY && entityType && entityId) {
      const loaders = {
        PROJECT: auditActions.loadProjectAudit,
        PURCHASE_ORDER: auditActions.loadPurchaseOrderAudit,
        EMPLOYEE: auditActions.loadEmployeeAudit,
        DELIVERABLE: auditActions.loadDeliverableAudit,
        LEAVE: auditActions.loadLeaveAudit,
        ATTENDANCE: auditActions.loadAttendanceAudit,
        TIMESHEET_WEEK: auditActions.loadTimesheetWeekAudit,
      };
      const loader = loaders[entityType] || auditActions.loadEntityTimeline;
      if (loader === auditActions.loadEntityTimeline) {
        store.dispatch(loader(entityType, entityId, params));
      } else {
        store.dispatch(loader(entityId, params));
      }
    }
  };

  loadIfNeeded = () => {
    const { timeline } = this.props;
    const page = (timeline && timeline.page) || 1;
    this.loadTimeline(page);
  };

  handlePageChange = (page) => {
    if (!page || page < 1) return;
    this.loadTimeline(page);
  };

  handleEntityFilter = (entityType) => {
    const { persistKey, lockedEntityFilter } = this.props;
    const nextFilter = lockedEntityFilter || entityType;
    const scopeKey = this.getScopeKey();
    store.dispatch(auditActions.setTimelineFilters(scopeKey, { entityType: nextFilter }));
    if (persistKey && !lockedEntityFilter) {
      writeAuditPanelPrefs(persistKey, { entityFilter: nextFilter });
    }
  };

  getFilterOptions = () => {
    const { entityFilterOptions } = this.props;
    if (entityFilterOptions && entityFilterOptions.length) {
      return entityFilterOptions;
    }
    return AUDIT_ENTITY_FILTER_OPTIONS;
  };

  renderFilterChips = () => {
    const { showEntityFilters, timeline } = this.props;
    const options = this.getFilterOptions();
    if (!showEntityFilters || options.length <= 1) return null;

    const selected = (timeline && timeline.filters && timeline.filters.entityType) || "ALL";

    return (
      <div className="lux-audit-panel__filters" role="group" aria-label="Filter audit by area">
        {options.map((option) => (
          <button
            key={option.value}
            type="button"
            className={classNames("lux-audit-panel__filter-chip", {
              "is-active": selected === option.value,
            })}
            onClick={() => this.handleEntityFilter(option.value)}
          >
            {option.label}
          </button>
        ))}
      </div>
    );
  };

  render() {
    const {
      className,
      eyebrow,
      title,
      subtitle,
      timeline,
      emptyState,
      showToolbar,
      onEventDeepLink,
      children,
      hideHeader,
      viewMode,
    } = this.props;

    if (!isAuditUiEnabled()) {
      return children || null;
    }

    const { lockedEntityFilter, employees } = this.props;
    const entityFilter =
      lockedEntityFilter || (timeline && timeline.filters && timeline.filters.entityType);
    let items = filterEventsByEntityType((timeline && timeline.items) || [], entityFilter);
    items = filterEventsByViewMode(items, viewMode);
    items = enrichAuditEventsWithEmployees(items, employees);

    return (
      <section className={classNames("lux-audit-panel", className)} aria-label={title || "Audit trail"}>
        {!hideHeader && (eyebrow || title) && (
          <header className="lux-audit-panel__head">
            <div>
              {eyebrow && <span className="lux-audit-panel__eyebrow">{eyebrow}</span>}
              {title && <h2 className="lux-audit-panel__title">{title}</h2>}
              {subtitle && <p className="lux-audit-panel__subtitle">{subtitle}</p>}
            </div>
            {timeline && !timeline.isLoading && (
              <span className="lux-audit-panel__count">
                {items.length} event{items.length === 1 ? "" : "s"}
              </span>
            )}
          </header>
        )}

        {showToolbar !== false && this.renderFilterChips()}

        {children}

        <AuditTimeline
          events={items}
          isLoading={timeline && timeline.isLoading}
          error={timeline && timeline.error}
          emptyState={emptyState}
          pagination={
            timeline && timeline.pageInfo
              ? {
                  page: timeline.pageInfo.page || timeline.page || 1,
                  pageSize: timeline.pageInfo.pageSize || timeline.pageSize || AUDIT_DEFAULT_PAGE_SIZE,
                  hasMore: timeline.pageInfo.hasMore === true,
                }
              : null
          }
          onPageChange={this.handlePageChange}
          onEventDeepLink={onEventDeepLink}
        />
      </section>
    );
  }
}

const mapStateToProps = (state, ownProps) => {
  const scopeKey =
    ownProps.scope === AUDIT_SCOPES.ACTOR
      ? buildAuditScopeKey("actor", { actorUserId: ownProps.actorUserId })
      : buildAuditScopeKey("entity", {
          entityType: ownProps.entityType,
          entityId: ownProps.entityId,
        });

  return {
    timeline: state.audit && state.audit.timelines && state.audit.timelines[scopeKey],
  };
};

export default connect(mapStateToProps)(AuditTrailSection);
