import dateUtils from "_helpers/date.utils";
import moment from "moment";
import { normalizeTimesheetStatus, readAttributeValue } from "./timesheetSummary.utils";

export function isManagerTimesheetApprover(permission) {
  // Role RBAC is the gate for manager lifecycle actions (approve / reopen / lock).
  // Org timesheetApprovalEnabled gates submit/workflow chrome separately — do not
  // hide reopen when a week is already APPROVED (in-flight) and org flag is off/unloaded.
  return !!(permission && permission.enableTimeSheetApproval === true);
}

/**
 * Reopen CTA for APPROVED weeks:
 * - Normal approve: only {@code approvedBy} may reopen.
 * - Auto-approve-own ({@code approvedBy === employeeId} or authority AUTO):
 *   manager / timesheet approval actor can reopen; employee can only when they
 *   have no reporting manager (solo owner — options.employeeManagerId null).
 */
export function canReopenTimesheetWeek(permission, actingDelegations, options = {}) {
  if (!permission) {
    return false;
  }
  if (permission.timesheetReopenEnabled === false || permission.enableTimeSheetReopen === false) {
    return false;
  }
  const { timeSheetData, currentUserId, viewingOwnWeek, employeeManagerId } = options;
  if (!timeSheetData || currentUserId == null) {
    return false;
  }
  const weekStatus = normalizeTimesheetStatus(readAttributeValue(timeSheetData.status));
  if (weekStatus !== "APPROVED") {
    return false;
  }
  const approvedBy = readAttributeValue(timeSheetData.approvedBy);
  if (!approvedBy) {
    return false;
  }
  const employeeId = readAttributeValue(timeSheetData.employeeId);
  const authorityType = String(readAttributeValue(timeSheetData.approvalAuthorityType) || "").toUpperCase();
  const selfApproved =
    (employeeId != null && String(approvedBy) === String(employeeId)) || authorityType === "AUTO";

  if (selfApproved) {
    const isOwner =
      viewingOwnWeek === true || String(currentUserId) === String(employeeId);
    if (isOwner) {
      return !hasReportingManager(employeeManagerId);
    }
    return isTimesheetApprovalActor(permission, actingDelegations);
  }
  return String(approvedBy) === String(currentUserId);
}

function hasReportingManager(managerId) {
  if (managerId == null || managerId === "") {
    return false;
  }
  return String(managerId) !== "0";
}

export function hasTimesheetDelegationScope(approvalTypes) {
  if (!approvalTypes || !approvalTypes.length) return false;
  return approvalTypes.some((type) => {
    const normalized = String(type).toUpperCase();
    return normalized === "TIMESHEET" || normalized === "BOTH";
  });
}

export function isTimesheetApprovalActor(permission, actingDelegations) {
  if (isManagerTimesheetApprover(permission)) return true;
  if (!permission || permission.approvalDelegationEnabled !== true) return false;
  if (!actingDelegations || !actingDelegations.length) return false;
  return actingDelegations.some(
    (delegation) =>
      delegation &&
      delegation.active !== false &&
      hasTimesheetDelegationScope(delegation.approvalTypes)
  );
}

export function formatTimesheetWeekRange(week) {
  if (!week) return "—";
  const start = parseWeekDate(week.weekStartDate);
  const end = parseWeekDate(week.weekEndDate);
  if (start && end && start.isValid() && end.isValid()) {
    return `${start.format("D MMM")} – ${end.format("D MMM YYYY")}`;
  }
  if (start && start.isValid()) {
    return `Week of ${start.format("D MMM YYYY")}`;
  }
  return "This week";
}

export function formatSubmittedDate(week) {
  const submitted = parseWeekDate(week && week.submittedDate);
  if (!submitted || !submitted.isValid()) {
    return "—";
  }
  return submitted.format("D MMM YYYY, h:mm a");
}

export function summarizePendingTimesheetWeeks(weeks) {
  const list = weeks || [];
  const employeeIds = new Set(list.map((week) => week.employeeId).filter((id) => id != null));
  return {
    total: list.length,
    employeeCount: employeeIds.size,
  };
}

/** Group pending weeks by employee for the luxury inbox layout (matches leave pending). */
export function groupPendingTimesheetWeeksByEmployee(weeks) {
  const groups = [];
  const byEmployee = new Map();
  (weeks || []).forEach((week) => {
    const employeeId = week && week.employeeId != null ? week.employeeId : "unknown";
    if (!byEmployee.has(employeeId)) {
      const group = {
        employeeId,
        employeeName: (week && week.employeeName) || `Employee #${employeeId}`,
        items: [],
      };
      byEmployee.set(employeeId, group);
      groups.push(group);
    }
    byEmployee.get(employeeId).items.push(week);
  });
  return groups;
}

export function getConflictTypeLabel(conflictType) {
  if (conflictType === "TASK_BOARD_OVERLAP") {
    return "Task board overlap";
  }
  if (conflictType === "DUPLICATE_ENTRY") {
    return "Duplicate entry";
  }
  return conflictType || "Conflict";
}

export const CONFLICT_RESOLUTION_OPTIONS = [
  { id: "MERGE", label: "Merge hours", hint: "Sum staged and approved durations" },
  { id: "REPLACE", label: "Replace", hint: "Keep staged hours only" },
  { id: "KEEP_BOTH", label: "Keep both", hint: "Promote staged as a separate entry" },
];

function parseWeekDate(value) {
  if (!value) return null;
  if (moment.isMoment(value)) return value;
  if (typeof value === "string") {
    const iso = moment(value);
    if (iso.isValid()) return iso;
    return dateUtils.convertDateToMoment(value);
  }
  return dateUtils.convertDateToMoment(value);
}
