import React, { Component } from "react";
import { Link } from "react-router-dom";
import { dossierService } from "_services/dossier/dossier.service";
import DossierLuxPage, {
  DossierActionButton,
  DossierLuxPanel,
} from "views/dossiers/components/DossierLuxShared";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

class DossiersPage extends Component {
  state = {
    loading: true,
    loadError: null,
    rows: [],
    saving: false,
    form: { title: "", description: "", projectId: "", accountId: "" },
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Dossiers");
    }
    this.load();
  }

  load = async () => {
    this.setState({ loading: true, loadError: null });
    const result = await dossierService.listDossiers();
    if (result.source === "api" && Array.isArray(result.payload)) {
      this.setState({ loading: false, rows: result.payload });
    } else {
      this.setState({
        loading: false,
        rows: [],
        loadError: result.error || new Error("Unable to load dossiers"),
      });
    }
  };

  handleCreate = async (e) => {
    e.preventDefault();
    const { form } = this.state;
    if (!form.title) return;
    this.setState({ saving: true });
    const result = await dossierService.createDossier({
      title: form.title,
      description: form.description,
      projectId: form.projectId || undefined,
      accountId: form.accountId || undefined,
    });
    this.setState({ saving: false });
    if (result.source === "api") {
      this.setState({
        form: { title: "", description: "", projectId: "", accountId: "" },
      });
      this.load();
    } else {
      this.setState({ loadError: result.error || new Error("Create failed") });
    }
  };

  render() {
    const { loading, loadError, rows, saving, form } = this.state;
    return (
      <DossierLuxPage
        testId="dossiers-page"
        dataSource={rows.length ? "api" : loadError ? "api-error" : loading ? null : "api"}
        pageMeta={{
          tone: "slate",
          icon: "fe fe-folder",
          eyebrow: "Projects · Dossier",
          titleLead: "Dossier",
          titleAccent: "register",
          lede: "Metadata + Document Vault links only — blobs stay in the vault.",
        }}
      >
        {loadError ? (
          <LuxInlineAlert tone="warning" title="Unable to load dossiers">
            {String(loadError.message || loadError)}
          </LuxInlineAlert>
        ) : null}
        <DossierLuxPanel title="Create dossier" icon="fe fe-plus">
          <form className="lux-module-inline-form" onSubmit={this.handleCreate}>
            <div className="form-row">
              <div className="col-md-3">
                <input
                  className="form-control"
                  placeholder="Title"
                  value={form.title}
                  onChange={(e) => this.setState({ form: { ...form, title: e.target.value } })}
                />
              </div>
              <div className="col-md-3">
                <input
                  className="form-control"
                  placeholder="Description"
                  value={form.description}
                  onChange={(e) => this.setState({ form: { ...form, description: e.target.value } })}
                />
              </div>
              <div className="col-md-2">
                <input
                  className="form-control"
                  placeholder="Project ID"
                  value={form.projectId}
                  onChange={(e) => this.setState({ form: { ...form, projectId: e.target.value } })}
                />
              </div>
              <div className="col-md-2">
                <input
                  className="form-control"
                  placeholder="Account ID"
                  value={form.accountId}
                  onChange={(e) => this.setState({ form: { ...form, accountId: e.target.value } })}
                />
              </div>
              <div className="col-md-2">
                <DossierActionButton type="submit" disabled={saving}>
                  {saving ? "Saving…" : "Create"}
                </DossierActionButton>
              </div>
            </div>
          </form>
        </DossierLuxPanel>
        <DossierLuxPanel title="Dossiers" meta={`${rows.length} record${rows.length === 1 ? "" : "s"}`} icon="fe fe-list">
          {loading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="Loading"
              description="Fetching records."
            />
          ) : null}
          {!loading && rows.length === 0 ? (
            <LuxRegisterEmptyState
              title="No dossiers yet"
              description="Create a dossier to manage sections, required docs, and exports."
              showCreate={false}
            />
          ) : !loading ? (
            <div className="lux-module-table-wrap">
              <table className="table table-sm mb-0">
                <thead>
                  <tr>
                    <th>Ref</th>
                    <th>Title</th>
                    <th>Status</th>
                    <th>Completeness</th>
                    <th />
                  </tr>
                </thead>
                <tbody>
                  {rows.map((row) => (
                    <tr key={row.dossierRef || row.id}>
                      <td>
                        <Link to={`/dossiers/${encodeURIComponent(row.dossierRef)}`}>
                          {row.dossierRef}
                        </Link>
                      </td>
                      <td>{row.title}</td>
                      <td>
                        <span className={`lux-expansion-status is-${String(row.status || "draft").toLowerCase()}`}>
                          {row.status || "Draft"}
                        </span>
                      </td>
                      <td>{row.completenessPct != null ? `${row.completenessPct}%` : "—"}</td>
                      <td>
                        <DossierActionButton
                          to={`/dossiers/${encodeURIComponent(row.dossierRef)}/sections`}
                          variant="ghost"
                          className="lux-onb-action--compact mr-1"
                        >
                          Sections
                        </DossierActionButton>
                        <DossierActionButton
                          to={`/dossiers/${encodeURIComponent(row.dossierRef)}/export`}
                          variant="ghost"
                          className="lux-onb-action--compact"
                        >
                          Export
                        </DossierActionButton>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : null}
        </DossierLuxPanel>
      </DossierLuxPage>
    );
  }
}

export default DossiersPage;
