/** Mock adapters are permanently disabled — live API only. */
export function shouldFallbackToMock() {
  return false;
}

/** Never use mock adapters; live API only. */
export function useMockAdapterInsteadOfApi(apiEnabled) {
  return false;
}

export function apiErrorResult(emptyPayload = null) {
  return { payload: emptyPayload, source: "api-error" };
}

export async function withMockOnlyFallback(apiCall, mockCall, emptyPayload = null) {
  try {
    return await apiCall();
  } catch (e) {
    if (shouldFallbackToMock()) {
      try {
        return await mockCall();
      } catch (_) {
        return apiErrorResult(emptyPayload);
      }
    }
    return apiErrorResult(emptyPayload);
  }
}

export async function invokeMockOrEmpty(mockFn, emptyResult = { payload: [], source: "client" }) {
  if (!shouldFallbackToMock()) {
    return emptyResult;
  }
  try {
    return await mockFn();
  } catch (e) {
    return emptyResult;
  }
}

export function resolveDataSourceLabel(dataSource, demoLabel) {
  if (!dataSource) {
    return null;
  }
  if (dataSource === "api") {
    return "Live API";
  }
  if (dataSource === "mock") {
    return demoLabel;
  }
  if (dataSource === "api-error") {
    return "Unavailable";
  }
  return null;
}
