import React, { useMemo } from "react";
import moment from "moment";
import classNames from "classnames/bind";
import {
  buildDelegationMonthCalendar,
  getDelegationHeatLevel,
} from "config/delegation-calendar.utils";

export default function DelegationCalendarPanel({ delegations, monthDate, onMonthChange, loading }) {
  const month = moment(monthDate || new Date()).startOf("month");

  const heatmap = useMemo(
    () => buildDelegationMonthCalendar(delegations, month),
    [delegations, month]
  );

  const activeDays = useMemo(
    () => heatmap.filter((cell) => cell.count > 0).length,
    [heatmap]
  );

  const peakCount = useMemo(
    () => heatmap.reduce((max, cell) => Math.max(max, cell.count), 0),
    [heatmap]
  );

  const handlePrev = () => {
    if (onMonthChange) onMonthChange(month.clone().subtract(1, "month").toDate());
  };

  const handleNext = () => {
    if (onMonthChange) onMonthChange(month.clone().add(1, "month").toDate());
  };

  const handleToday = () => {
    if (onMonthChange) onMonthChange(moment().startOf("month").toDate());
  };

  return (
    <section className="lux-hrms-dash__panel lux-delegation-panel lux-delegation-panel--accent lux-delegation-calendar" aria-label="Delegation calendar">
      <header className="lux-hrms-dash__panel-head lux-hrms-dash__panel-head--stack">
        <div>
          <span className="lux-hrms-dash__section-eyebrow">Coverage heatmap</span>
          <h2 className="lux-hrms-dash__panel-title">Delegation calendar</h2>
          <p className="lux-hrms-dash__panel-sub">
            {loading
              ? "Loading delegation spans…"
              : `${activeDays} day${activeDays === 1 ? "" : "s"} with coverage · peak ${peakCount} overlap${peakCount === 1 ? "" : "s"}`}
          </p>
        </div>
        <div className="lux-delegation-calendar__nav">
          <button type="button" className="lux-delegation-calendar__nav-btn" onClick={handlePrev} aria-label="Previous month">
            <i className="fe fe-chevron-left" aria-hidden="true" />
          </button>
          <span className="lux-delegation-calendar__month">{month.format("MMMM YYYY")}</span>
          <button type="button" className="lux-delegation-calendar__nav-btn" onClick={handleNext} aria-label="Next month">
            <i className="fe fe-chevron-right" aria-hidden="true" />
          </button>
          <button type="button" className="lux-delegation-calendar__today-btn" onClick={handleToday}>
            Today
          </button>
        </div>
      </header>

      <div className="lux-hrms-dash__panel-body">
        <div className="lux-delegation-calendar__legend" aria-hidden="true">
          <span className="is-outgoing">Outgoing coverage</span>
          <span className="is-incoming">Acting for managers</span>
        </div>

        {loading ? (
          <div className="lux-delegation-calendar__skeleton" aria-busy="true" />
        ) : (
          <div className="lux-delegation-calendar__heatmap-wrap">
            <div className="lux-delegation-calendar__heatmap-label">Active delegation days</div>
            <div className="lux-delegation-calendar__heatmap" role="list" aria-label="Delegation density by day">
              {heatmap.map((cell) => (
                <div
                  key={cell.day}
                  role="listitem"
                  className={classNames("lux-delegation-calendar__day", `is-${getDelegationHeatLevel(cell.count)}`, {
                    "is-weekend": cell.isWeekend,
                    "is-today": cell.isToday,
                  })}
                  title={`${month.format("MMM")} ${cell.day}: ${cell.count} delegation span${cell.count === 1 ? "" : "s"}`}
                >
                  <span className="lux-delegation-calendar__day-num">{cell.day}</span>
                  {cell.count > 0 && <span className="lux-delegation-calendar__day-count">{cell.count}</span>}
                </div>
              ))}
            </div>
            <div className="lux-delegation-calendar__density-legend" aria-hidden="true">
              <span className="is-low">1 span</span>
              <span className="is-medium">2 spans</span>
              <span className="is-high">3+ spans</span>
            </div>
          </div>
        )}
      </div>
    </section>
  );
}
