import React, { Component } from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import { industryTemplateService } from "_services/industryTemplates/industryTemplates.service";
import {
  AdminActionButton,
  AdminInsightStrip,
  AdminLuxPage,
  AdminPanelHead,
  AdminPanelLink,
  AdminQuickNav,
} from "views/admin/components/AdminLuxShared";
import AdminLoadAlert from "views/admin/components/AdminLoadAlert";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";

const QUICK_LINKS = [
  {
    path: "/admin/appconfig",
    label: "Application config",
    desc: "Allowlisted keys touched by template apply",
    icon: "fe fe-settings",
    tone: "indigo",
  },
  {
    path: "/admin/roles",
    label: "Roles & personas",
    desc: "Review persona access after packing roles",
    icon: "fe fe-shield",
    tone: "blue",
  },
  {
    path: "/admin/industry-templates/apply",
    label: "Apply wizard",
    desc: "Preview → draft → commit with overwrite guard",
    icon: "fe fe-play",
    tone: "green",
  },
];

const PACK_ICON = {
  SERVICES: "fe fe-briefcase",
  PRODUCT: "fe fe-box",
  HEALTHCARE: "fe fe-heart",
  MANUFACTURING: "fe fe-tool",
  default: "fe fe-package",
};

function normalizeStatus(status) {
  return String(status || "UNKNOWN").toUpperCase();
}

function statusTone(status) {
  const s = normalizeStatus(status);
  if (s === "PUBLISHED" || s === "ACTIVE") return "green";
  if (s === "DRAFT") return "amber";
  if (s === "ARCHIVED" || s === "RETIRED") return "slate";
  return "indigo";
}

function buildMetrics(rows) {
  const list = Array.isArray(rows) ? rows : [];
  const published = list.filter((r) => normalizeStatus(r.status) === "PUBLISHED").length;
  const draft = list.filter((r) => normalizeStatus(r.status) === "DRAFT").length;
  const packs = new Set(list.map((r) => r.industryPack).filter(Boolean)).size;
  return {
    total: list.length,
    published,
    draft,
    packs,
  };
}

function packIcon(industryPack) {
  const key = String(industryPack || "")
    .toUpperCase()
    .split(/[\s_-]/)[0];
  return PACK_ICON[key] || PACK_ICON.default;
}

class IndustryTemplatesPage extends Component {
  state = {
    loading: true,
    loadError: null,
    rows: [],
    query: "",
    statusFilter: "ALL",
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Industry templates");
    }
    this.load();
  }

  load = async () => {
    this.setState({ loading: true, loadError: null });
    const result = await industryTemplateService.listCatalog();
    if (result.source === "api" && Array.isArray(result.payload)) {
      this.setState({ loading: false, rows: result.payload });
    } else {
      this.setState({
        loading: false,
        rows: [],
        loadError: result.error || new Error("Unable to load industry templates"),
      });
    }
  };

  getFilteredRows = () => {
    const { rows, query, statusFilter } = this.state;
    const q = String(query || "")
      .trim()
      .toLowerCase();
    return (rows || []).filter((row) => {
      if (statusFilter !== "ALL" && normalizeStatus(row.status) !== statusFilter) {
        return false;
      }
      if (!q) return true;
      const hay = [row.industryPack, row.name, row.templateRef, row.version, row.status]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();
      return hay.includes(q);
    });
  };

  renderInsights = (metrics) => {
    if (this.state.loading) return null;
    const insights = [
      {
        id: "catalog",
        tone: "indigo",
        icon: "fe fe-package",
        title: `${metrics.total} pack${metrics.total === 1 ? "" : "s"} in catalog`,
        copy: `${metrics.packs} industry vertical${metrics.packs === 1 ? "" : "s"} represented`,
      },
      {
        id: "published",
        tone: "green",
        icon: "fe fe-check-circle",
        title: `${metrics.published} published`,
        copy: "Ready for preview and controlled apply",
      },
      {
        id: "guard",
        tone: "amber",
        icon: "fe fe-shield",
        title: "No silent overwrite",
        copy: "Conflicts require explicit approve before App Config write",
        path: "/admin/industry-templates/apply",
      },
    ];
    return <AdminInsightStrip insights={insights} className="lux-itpl-insights" />;
  };

  render() {
    const { loading, loadError, query, statusFilter } = this.state;
    const metrics = buildMetrics(this.state.rows);
    const filtered = this.getFilteredRows();
    const statuses = [
      "ALL",
      ...Array.from(
        new Set((this.state.rows || []).map((r) => normalizeStatus(r.status)).filter(Boolean))
      ).sort(),
    ];

    const kpiCards = [
      {
        id: "packs",
        label: "Templates",
        value: metrics.total,
        hint: `${metrics.packs} verticals`,
        tone: "primary",
        icon: "fe fe-package",
      },
      {
        id: "published",
        label: "Published",
        value: metrics.published,
        hint: "Apply-ready",
        tone: "green",
        icon: "fe fe-check-circle",
      },
      {
        id: "draft",
        label: "Draft",
        value: metrics.draft,
        hint: "Not published",
        tone: "amber",
        icon: "fe fe-edit-3",
      },
      {
        id: "guard",
        label: "Overwrite",
        value: "Guarded",
        hint: "ITPL-009",
        tone: "blue",
        icon: "fe fe-lock",
      },
    ];

    return (
      <AdminLuxPage
        testId="industry-templates-page"
        className="lux-register-page lux-itpl-page"
        pageMeta={{
          tone: "indigo",
          icon: "fe fe-package",
          eyebrow: "Admin · Configuration",
          titleLead: "Industry",
          titleAccent: "templates",
          lede: "Catalog packs seed App Config defaults by vertical — preview, draft, then commit with an overwrite guard.",
        }}
        dataSource="api"
        loading={loading}
        kpiCards={kpiCards}
        heroActions={
          <>
            <AdminActionButton
              type="button"
              variant="ghost"
              icon="fe fe-refresh-cw"
              onClick={this.load}
              disabled={loading}
            >
              Refresh
            </AdminActionButton>
            <AdminActionButton to="/admin/industry-templates/apply" variant="primary" icon="fe fe-play">
              Apply wizard
            </AdminActionButton>
          </>
        }
      >
        <AdminLoadAlert
          error={loadError}
          fallback="Unable to load industry templates."
          onDismiss={() => this.setState({ loadError: null })}
        />

        {this.renderInsights(metrics)}

        <AdminQuickNav
          className="lux-itpl-quick-nav"
          eyebrow="Continue in Admin"
          title="Related configuration"
          links={QUICK_LINKS}
        />

        <section className="lux-hrms-dash__panel lux-itpl-panel">
          <AdminPanelHead
            title="Template catalog"
            subtitle="Open a pack for payload detail, or start the apply wizard to seed the selected team."
            actions={<AdminPanelLink to="/admin/appconfig">Application config</AdminPanelLink>}
          />

          <div className="lux-itpl-toolbar">
            <label className="lux-itpl-search">
              <i className="fe fe-search" aria-hidden="true" />
              <input
                type="search"
                value={query}
                placeholder="Search pack, name, or ref"
                onChange={(e) => this.setState({ query: e.target.value })}
                aria-label="Search industry templates"
              />
            </label>
            <div className="lux-itpl-chips" role="tablist" aria-label="Filter by status">
              {statuses.map((status) => (
                <button
                  key={status}
                  type="button"
                  role="tab"
                  aria-selected={statusFilter === status}
                  className={classNames("lux-hrms-dash__filter-chip", {
                    "is-active": statusFilter === status,
                  })}
                  onClick={() => this.setState({ statusFilter: status })}
                >
                  {status === "ALL" ? "All" : status}
                </button>
              ))}
            </div>
          </div>

          {loading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="Loading templates"
              description="Fetching the industry template catalog."
            />
          ) : !loadError && filtered.length === 0 ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title={this.state.rows.length ? "No matching packs" : "No templates found"}
              description={
                this.state.rows.length
                  ? "Try another status filter or clear the search."
                  : "No industry packs are available in the catalog."
              }
            />
          ) : !loadError ? (
            <div className="lux-itpl-grid">
              {filtered.map((row) => {
                const tone = statusTone(row.status);
                const href = `/admin/industry-templates/${encodeURIComponent(row.templateRef)}`;
                return (
                  <article
                    key={row.templateRef || row.code}
                    className={classNames("lux-itpl-card", `is-${tone}`)}
                    data-testid={`industry-template-card-${row.templateRef}`}
                  >
                    <header className="lux-itpl-card__head">
                      <span className="lux-itpl-card__icon" aria-hidden="true">
                        <i className={packIcon(row.industryPack)} />
                      </span>
                      <div className="lux-itpl-card__titles">
                        <p className="lux-itpl-card__pack">{row.industryPack || "Industry pack"}</p>
                        <h3 className="lux-itpl-card__title">{row.name || row.templateRef}</h3>
                      </div>
                      <span className={classNames("lux-itpl-pill", `is-${tone}`)}>
                        {normalizeStatus(row.status)}
                      </span>
                    </header>
                    <p className="lux-itpl-card__meta">
                      <code>{row.templateRef}</code>
                      <span>v{row.version || "—"}</span>
                    </p>
                    {row.description ? (
                      <p className="lux-itpl-card__desc">{row.description}</p>
                    ) : (
                      <p className="lux-itpl-card__desc lux-itpl-card__desc--muted">
                        Roles, workflows, checklists, and App Config defaults for this vertical.
                      </p>
                    )}
                    <footer className="lux-itpl-card__foot">
                      <Link className="lux-admin-panel-link" to={href}>
                        Open detail
                        <i className="fe fe-arrow-right" aria-hidden="true" />
                      </Link>
                      <AdminActionButton
                        to={`/admin/industry-templates/apply?templateRef=${encodeURIComponent(
                          row.templateRef || ""
                        )}`}
                        variant="secondary"
                        icon="fe fe-play"
                      >
                        Apply
                      </AdminActionButton>
                    </footer>
                  </article>
                );
              })}
            </div>
          ) : null}
        </section>
      </AdminLuxPage>
    );
  }
}

export default IndustryTemplatesPage;
