/**
 * F04 — Leave enhancement APIs with client fallback.
 * PR-05: fail closed on API error when mock is off — never invent metrics.
 */
import { axiosUtils } from "../_helpers";
import urlConfig from "url.config";
import { shouldUseLeaveImpactApi } from "config/leave-enhancement.config";
import {
  buildLeaveImpactAnalysis,
  buildTeamCoverageSummary,
  buildImpactRecommendationDraft,
} from "config/leave-impact.utils";
import { buildLeaveAnalytics } from "config/leave-analytics.utils";
import { buildPayrollLeaveExtract } from "config/leave-payroll.utils";

export const leaveEnhancementService = {
  getImpactAnalysis,
  getTeamCoverage,
  getLeaveAnalytics,
  getPayrollExtract,
  getImpactRecommendationDraft,
};

const API_ERROR = { payload: null, source: "api-error" };

async function getImpactFromApi(leaveId) {
  const response = await axiosUtils.get(`${urlConfig.LEAVES_IMPACT}/${leaveId}`);
  return response && response.payload ? response.payload : response;
}

async function getImpactAnalysis(leave, context) {
  if (shouldUseLeaveImpactApi()) {
    if (!leave || !leave.id) {
      return { ...API_ERROR, reason: "leaveId-required" };
    }
    try {
      const apiPayload = await getImpactFromApi(leave.id);
      if (apiPayload) {
        return { ...apiPayload, source: "api" };
      }
      return { ...API_ERROR, reason: "empty-payload" };
    } catch (e) {
      console.warn("[LeaveEnhancement] Impact API unavailable.", e);
      return { ...API_ERROR, error: e };

    }
  }
  return {
    ...buildLeaveImpactAnalysis(leave, context),
    source: "client",
  };
}

function normalizeTeamIds(userTeamIds, userTeamId) {
  if (Array.isArray(userTeamIds) && userTeamIds.length) return userTeamIds;
  if (userTeamId != null && userTeamId !== "") return [userTeamId];
  return [];
}

async function getTeamCoverageFromApi(userTeamIds, startDate, endDate) {
  const params = {
    startDate,
    endDate,
    ...(Array.isArray(userTeamIds) && userTeamIds.length
      ? { userTeamIds }
      : { userTeamId: userTeamIds }),
  };
  const response = await axiosUtils.getWithParam(urlConfig.LEAVES_COVERAGE, params);
  return response && response.payload ? response.payload : response;
}

async function getTeamCoverage(context) {
  const { calendarLeaves, employees, monthDate, userTeamId, userTeamIds, startDate, endDate } = context || {};
  const teamIds = normalizeTeamIds(userTeamIds, userTeamId);
  if (shouldUseLeaveImpactApi()) {
    if (!teamIds.length || !startDate || !endDate) {
      return { ...API_ERROR, reason: "coverage-params-required" };
    }
    try {
      const apiPayload = await getTeamCoverageFromApi(teamIds, startDate, endDate);
      if (apiPayload) {
        return { ...apiPayload, source: "api" };
      }
      return { ...API_ERROR, reason: "empty-payload" };
    } catch (e) {
      console.warn("[LeaveEnhancement] Coverage API unavailable.", e);
      return { ...API_ERROR, error: e };

    }
  }
  return {
    ...buildTeamCoverageSummary(calendarLeaves, employees, monthDate),
    source: "client",
  };
}

async function getLeaveAnalyticsFromApi(userTeamIds) {
  const params = Array.isArray(userTeamIds) && userTeamIds.length
    ? { userTeamIds }
    : { userTeamId: userTeamIds };
  const response = await axiosUtils.getWithParam(urlConfig.LEAVES_ANALYTICS, params);
  return response && response.payload ? response.payload : response;
}

async function getLeaveAnalytics(context) {
  const { userTeamId, userTeamIds, leaves, calendarLeaves, pendingLeaves, balances } = context || {};
  const teamIds = normalizeTeamIds(userTeamIds, userTeamId);
  if (shouldUseLeaveImpactApi()) {
    if (!teamIds.length) {
      return { ...API_ERROR, reason: "userTeamId-required" };
    }
    try {
      const apiPayload = await getLeaveAnalyticsFromApi(teamIds);
      if (apiPayload) {
        return { ...apiPayload, source: "api" };
      }
      return { ...API_ERROR, reason: "empty-payload" };
    } catch (e) {
      console.warn("[LeaveEnhancement] Analytics API unavailable.", e);
      return { ...API_ERROR, error: e };

    }
  }
  return {
    ...buildLeaveAnalytics({ leaves, calendarLeaves, pendingLeaves, balances }),
    source: "client",
  };
}

async function getPayrollExtractFromApi(userTeamIds, periodStart, periodEnd) {
  const params = {
    periodStart,
    periodEnd,
    ...(Array.isArray(userTeamIds) && userTeamIds.length
      ? { userTeamIds }
      : { userTeamId: userTeamIds }),
  };
  const response = await axiosUtils.getWithParam(urlConfig.LEAVES_PAYROLL_EXTRACT, params);
  return response && response.payload ? response.payload : response;
}

async function getPayrollExtract(context) {
  const { userTeamId, userTeamIds, leaves, employeesById, periodStart, periodEnd } = context || {};
  const teamIds = normalizeTeamIds(userTeamIds, userTeamId);
  if (shouldUseLeaveImpactApi()) {
    if (!teamIds.length || !periodStart || !periodEnd) {
      return { ...API_ERROR, reason: "payroll-extract-params-required" };
    }
    try {
      const apiPayload = await getPayrollExtractFromApi(teamIds, periodStart, periodEnd);
      if (apiPayload) {
        return { ...apiPayload, source: "api" };
      }
      return { ...API_ERROR, reason: "empty-payload" };
    } catch (e) {
      console.warn("[LeaveEnhancement] Payroll extract API unavailable.", e);
      return { ...API_ERROR, error: e };

    }
  }
  return {
    ...buildPayrollLeaveExtract(leaves, employeesById, periodStart, periodEnd),
    source: "client",
  };
}

async function getImpactRecommendationDraft(impact) {
  if (!impact || impact.source === "api-error") {
    return { ...API_ERROR };
  }
  return buildImpactRecommendationDraft(impact);
}
