import React from "react";
import classNames from "classnames/bind";
import {
  getNotificationTemplateSourceLabel,
  getNotificationTemplateSourceTip,
  isSystemNotificationTemplate,
} from "config/notification-template.config";

function rowKey(row) {
  return row.templateRef || `${row.eventType || "evt"}-${row.channel || "EMAIL"}`;
}

export default function NotificationTemplateRegister({
  templates,
  onView,
  onEdit,
  onClone,
}) {
  return (
    <div className="lux-ntpl-register-wrap">
      <table className="lux-ntpl-register lux-appr-policy-register">
        <thead>
          <tr>
            <th>Event</th>
            <th>Channel</th>
            <th>Subject</th>
            <th>Source</th>
            <th>Status</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {(templates || []).map((row) => {
            const system = isSystemNotificationTemplate(row);
            const enabled = row.enabled !== false;
            const channel = String(row.channel || "EMAIL").toUpperCase();
            const sourceLabel = getNotificationTemplateSourceLabel(row);
            const sourceTip = getNotificationTemplateSourceTip(row);
            const key = rowKey(row);
            const open = () => (system ? onView && onView(row) : onEdit && onEdit(row));

            return (
              <tr
                key={key}
                className={classNames("lux-ntpl-register__row lux-appr-policy-register__row", {
                  "is-system": system,
                  "is-override": !system,
                  "is-disabled": !enabled,
                  "is-attention": !enabled,
                })}
                onDoubleClick={open}
              >
                <td>
                  <button
                    type="button"
                    className="lux-ntpl-register__primary-btn"
                    onClick={open}
                    data-testid={`ntpl-open-primary-${key}`}
                  >
                    <span className="lux-appr-policy-register__primary lux-ntpl-register__primary">
                      <span
                        className={classNames(
                          "lux-appr-policy-register__avatar lux-ntpl-register__avatar",
                          system ? "is-blue" : "is-primary"
                        )}
                        aria-hidden="true"
                      >
                        <i className={system ? "fe fe-package" : "fe fe-edit-3"} />
                      </span>
                      <span className="lux-appr-policy-register__primary-copy">
                        <strong className="lux-appr-policy-register__primary-title">
                          {row.eventType || "—"}
                        </strong>
                        {row.classpathTemplateName ? (
                          <span className="lux-appr-policy-register__primary-meta" title={row.classpathTemplateName}>
                            {row.classpathTemplateName}
                          </span>
                        ) : row.templateRef ? (
                          <span className="lux-appr-policy-register__primary-meta" title={row.templateRef}>
                            {row.templateRef}
                          </span>
                        ) : (
                          <span className="lux-appr-policy-register__primary-meta">
                            {system ? "Classpath default" : "Workspace override"}
                          </span>
                        )}
                      </span>
                    </span>
                  </button>
                </td>
                <td>
                  <span className={classNames("lux-appr-policy-register__chip", "is-sky")} title={`${channel} channel`}>
                    <i className="fe fe-at-sign" aria-hidden="true" />
                    <span>
                      <strong>{channel}</strong>
                      <em>Channel</em>
                    </span>
                  </span>
                </td>
                <td>
                  <span className="lux-ntpl-register__subject" title={row.subject || ""}>
                    {row.subject || "—"}
                  </span>
                </td>
                <td>
                  <span
                    className={classNames("lux-doc-badge", system ? "is-info" : "is-primary")}
                    title={sourceTip}
                  >
                    {sourceLabel}
                  </span>
                </td>
                <td>
                  <span className={classNames("lux-doc-badge", enabled ? "is-success" : "is-warning")}>
                    {enabled ? "Enabled" : "Disabled"}
                  </span>
                </td>
                <td className="lux-ntpl-register__actions lux-appr-policy-register__actions">
                  <button
                    type="button"
                    className="lux-appr-policy-register__edit lux-ntpl-register__action"
                    onClick={open}
                    data-testid={`ntpl-open-${key}`}
                    title={system ? "View system template" : "Edit org override"}
                  >
                    <i className={system ? "fe fe-eye" : "fe fe-edit-2"} aria-hidden="true" />
                    {system ? "View" : "Edit"}
                  </button>
                  {system && typeof onClone === "function" ? (
                    <button
                      type="button"
                      className="lux-appr-policy-register__edit lux-ntpl-register__action is-secondary"
                      onClick={() => onClone(row)}
                      data-testid={`ntpl-clone-${key}`}
                      title="Create org override from this system default"
                    >
                      <i className="fe fe-copy" aria-hidden="true" />
                      Clone
                    </button>
                  ) : null}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
