import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isUniversalApprovalInboxEnabled } from "config/universal-approval.config";
import {
  buildApprovalInboxMetrics,
  filterApprovalInboxItems,
  sortApprovalInboxItems,
} from "config/universal-approval.utils";
import { universalApprovalService } from "_services/universalApproval.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxSegmentNav from "views/common/fragments/LuxSegmentNav";
import PageCreateButton from "views/common/fragments/PageCreateButton";
import { PageDataSourceReporter } from "views/common/PageChromeContext";
import UniversalApprovalSummary from "views/workspace/components/approvals/UniversalApprovalSummary";
import UniversalApprovalFilterBar from "views/workspace/components/approvals/UniversalApprovalFilterBar";
import UniversalApprovalRegister from "views/workspace/components/approvals/UniversalApprovalRegister";
import UniversalApprovalDetailDrawer from "views/workspace/components/approvals/UniversalApprovalDetailDrawer";
import UniversalApprovalAnalyticsPanel from "views/workspace/components/approvals/UniversalApprovalAnalyticsPanel";
import UniversalApprovalSlaBanner from "views/workspace/components/approvals/UniversalApprovalSlaBanner";
import WorkspaceSavedViewBar from "views/workspace/components/WorkspaceSavedViewBar";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import { DENSE_PAGE_META } from "config/dense-page-meta.config";

const DEFAULT_FILTERS = {
  status: "PENDING",
  domain: "ALL",
  priority: "ALL",
  query: "",
};

class ApprovalsPage extends Component {
  state = {
    items: [],
    loading: true,
    loadError: null,
    dataSource: null,
    filters: { ...DEFAULT_FILTERS },
    selectedItem: null,
    drawerOpen: false,
    acting: false,
    activeView: "inbox",
  };

  componentDidMount() {
    const { pageHeaderNameChangeHandler } = this.props;
    if (pageHeaderNameChangeHandler) {
      pageHeaderNameChangeHandler("My approvals");
    }
    this.loadInbox();
  }

  loadInbox = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await universalApprovalService.listInbox({ status: "ALL" });
      this.setState({
        items: sortApprovalInboxItems(result.payload || []),
        loading: false,
        dataSource: result.source || null,
      });
    } catch (_error) {
      this.setState({
        loading: false,
        loadError: "Unable to load your approval inbox.",
        items: [],
      });
    }
  };

  handleFiltersChange = (filters) => {
    this.setState({ filters });
  };

  handleSummaryFilter = (patch) => {
    this.setState((prev) => ({
      filters: { ...prev.filters, ...patch },
      activeView: "inbox",
    }));
  };

  handleSlaFocus = () => {
    this.setState((prev) => {
      const alreadyFocused =
        prev.filters.status === "PENDING" && prev.filters.priority === "HIGH";
      return {
        activeView: "inbox",
        filters: alreadyFocused
          ? { ...DEFAULT_FILTERS }
          : {
              ...DEFAULT_FILTERS,
              status: "PENDING",
              priority: "HIGH",
            },
      };
    });
  };

  handleSelectItem = (item) => {
    this.setState({ selectedItem: item, drawerOpen: true });
  };

  handleCloseDrawer = () => {
    this.setState({ drawerOpen: false, selectedItem: null, acting: false });
  };

  handleApprove = async (item, comment) => {
    this.setState({ acting: true });
    try {
      await universalApprovalService.approveItem(item, comment);
      await this.loadInbox();
      this.setState({ acting: false });
    } catch (error) {
      this.setState({ acting: false });
      throw error;
    }
  };

  handleReject = async (item, comment) => {
    this.setState({ acting: true });
    try {
      await universalApprovalService.rejectItem(item, comment);
      await this.loadInbox();
      this.setState({ acting: false });
    } catch (error) {
      this.setState({ acting: false });
      throw error;
    }
  };

  getFilteredItems = () => {
    const { items, filters } = this.state;
    return filterApprovalInboxItems(items, filters);
  };

  getStatusCounts = () => {
    const { items } = this.state;
    const counts = { ALL: items.length, PENDING: 0, APPROVED: 0, REJECTED: 0 };
    items.forEach((item) => {
      if (counts[item.status] != null) {
        counts[item.status] += 1;
      }
    });
    return counts;
  };

  render() {
    if (!isUniversalApprovalInboxEnabled()) {
      return (
        <PersonaAccessDenied
          moduleName="Approval inbox"
          reason="Universal approval inbox is not enabled for your organization."
        />
      );
    }

    const { loading, loadError, filters, selectedItem, drawerOpen, acting, dataSource, activeView } =
      this.state;
    const filteredItems = this.getFilteredItems();
    const metrics = buildApprovalInboxMetrics(this.state.items);
    const statusCounts = this.getStatusCounts();
    const isInbox = activeView === "inbox";

    return (
      <div className="lux-appr-page lux-register-page" data-testid="page-approvals">
        <PageDataSourceReporter dataSource={dataSource} />
        <LuxModuleIntro
          meta={DENSE_PAGE_META.approvals}
          actions={
            <PageCreateButton
              onClick={this.loadInbox}
              icon="fe-refresh-cw"
              disabled={loading}
              testId="approvals-refresh"
            >
              Refresh
            </PageCreateButton>
          }
          nav={
            <LuxSegmentNav
              className="lux-appr-view-tabs"
              items={[
                {
                  id: "inbox",
                  label: "Inbox",
                  icon: "fe fe-inbox",
                  badge: metrics.pending,
                  showZeroBadge: false,
                },
                { id: "analytics", label: "Analytics", icon: "fe fe-bar-chart-2" },
              ]}
              activeId={activeView}
              onChange={(next) => this.setState({ activeView: next })}
              ariaLabel="Approval views"
              tabList
              testId="approval-view-nav"
            />
          }
        />

        {isInbox && (
          <UniversalApprovalFilterBar
            filters={filters}
            onChange={this.handleFiltersChange}
            resultCount={filteredItems.length}
            statusCounts={statusCounts}
          />
        )}

        {isInbox && (
          <UniversalApprovalSummary
            metrics={metrics}
            loading={loading}
            filters={filters}
            onFilter={this.handleSummaryFilter}
          />
        )}

        {isInbox && (
          <UniversalApprovalSlaBanner
            items={this.state.items}
            onReview={this.handleSlaFocus}
            active={filters.status === "PENDING" && filters.priority === "HIGH"}
          />
        )}

        {activeView === "analytics" && (
          <div className="lux-register-list-section lux-appr-list-section lux-appr-analytics-section">
            <UniversalApprovalAnalyticsPanel items={this.state.items} loading={loading} />
          </div>
        )}

        {loadError && (
          <LuxRegisterEmptyState
            className="lux-register-empty--compact lux-appr-empty"
            icon="fe fe-alert-circle"
            title="Inbox unavailable"
            description={loadError}
          />
        )}

        {isInbox && !loadError && (
          <div className="lux-register-list-section lux-appr-list-section">
            <WorkspaceSavedViewBar
              surface="APPROVALS"
              currentFilters={filters}
              onApply={this.handleFiltersChange}
            />
            <UniversalApprovalRegister
              items={filteredItems}
              loading={loading}
              onSelect={this.handleSelectItem}
              onClearFilters={
                filteredItems.length === 0 &&
                (filters.status !== DEFAULT_FILTERS.status ||
                  filters.domain !== DEFAULT_FILTERS.domain ||
                  filters.priority !== DEFAULT_FILTERS.priority ||
                  Boolean((filters.query || "").trim()))
                  ? () => this.handleFiltersChange({ ...DEFAULT_FILTERS })
                  : undefined
              }
            />
          </div>
        )}

        <UniversalApprovalDetailDrawer
          item={selectedItem}
          open={drawerOpen}
          onClose={this.handleCloseDrawer}
          onApprove={this.handleApprove}
          onReject={this.handleReject}
          acting={acting}
        />
      </div>
    );
  }
}

export default ApprovalsPage;
