import { axiosUtils } from "../_helpers";
import urlConfig from "url.config";
import {
  AnalyticsEvents,
  trackTimesheetAction,
} from "config/analytics-events.config";

export const timesheetApprovalService = {
  submitWeek,
  resubmitWeek,
  listPending,
  approveWeek,
  rejectWeek,
  rejectLine,
  listConflicts,
  resolveConflict,
  lockWeeks,
  unlockWeeks,
  reopenWeek,
  listDefaulters,
};

async function submitWeek(weekId, actorId) {
  const result = await axiosUtils.patch(
    `${urlConfig.TIMESHEETS_API_PATH}/${weekId}/submit?actorId=${actorId}`
  );
  trackTimesheetAction(AnalyticsEvents.TIMESHEET_SUBMIT, weekId);
  return result;
}

async function resubmitWeek(weekId, actorId) {
  const result = await axiosUtils.patch(
    `${urlConfig.TIMESHEETS_API_PATH}/${weekId}/resubmit?actorId=${actorId}`
  );
  trackTimesheetAction(AnalyticsEvents.TIMESHEET_RESUBMIT, weekId);
  return result;
}

async function listPending(userTeamIds, managerId) {
  const params = { managerId };
  if (userTeamIds && userTeamIds.length) {
    params.userTeamIds = userTeamIds;
  }
  return axiosUtils.getWithParam(`${urlConfig.TIMESHEETS_API_PATH}/pending`, params);
}

async function approveWeek(weekId, approverId, approvalComment) {
  const result = await axiosUtils.patch(
    `${urlConfig.TIMESHEETS_API_PATH}/${weekId}/approve?approverId=${approverId}`,
    { approvalComment: approvalComment || null }
  );
  trackTimesheetAction(AnalyticsEvents.TIMESHEET_APPROVE, weekId);
  return result;
}

async function rejectWeek(weekId, approverId, rejectionComment) {
  const result = await axiosUtils.patch(
    `${urlConfig.TIMESHEETS_API_PATH}/${weekId}/reject?approverId=${approverId}`,
    { rejectionComment }
  );
  trackTimesheetAction(AnalyticsEvents.TIMESHEET_REJECT, weekId);
  return result;
}

async function rejectLine(weekId, lineId, approverId, rejectionComment) {
  const result = await axiosUtils.patch(
    `${urlConfig.TIMESHEETS_API_PATH}/${weekId}/lines/${lineId}/reject?approverId=${approverId}`,
    { rejectionComment }
  );
  trackTimesheetAction(AnalyticsEvents.TIMESHEET_REJECT_LINE, weekId);
  return result;
}

async function listConflicts(weekId) {
  return axiosUtils.get(`${urlConfig.TIMESHEETS_API_PATH}/${weekId}/conflicts`);
}

async function resolveConflict(conflictId, payload) {
  return axiosUtils.post(
    `${urlConfig.TIMESHEETS_API_PATH}/conflicts/${conflictId}/resolve`,
    payload
  );
}

async function lockWeeks(payload) {
  const result = await axiosUtils.post(`${urlConfig.TIMESHEETS_API_PATH}/lock`, payload);
  trackTimesheetAction(AnalyticsEvents.TIMESHEET_LOCK, payload && payload.weekId);
  return result;
}

async function unlockWeeks(payload) {
  return axiosUtils.post(`${urlConfig.TIMESHEETS_API_PATH}/unlock`, payload);
}

async function reopenWeek(weekId, actorId) {
  const result = await axiosUtils.patch(
    `${urlConfig.TIMESHEETS_API_PATH}/${weekId}/reopen?actorId=${actorId}`
  );
  trackTimesheetAction(AnalyticsEvents.TIMESHEET_REOPEN, weekId);
  return result;
}

async function listDefaulters(userTeamIds, weekStartDate) {
  const params = { weekStartDate };
  if (userTeamIds && userTeamIds.length) {
    params.userTeamIds = userTeamIds;
  }
  return axiosUtils.getWithParam(`${urlConfig.TIMESHEETS_API_PATH}/defaulters`, params);
}
