import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import { isWorkspaceBriefingEnabled } from "config/workspace-briefing.config";
import { buildWorkspaceDailyBriefing } from "config/workspace-briefing.utils";
import { isMockDataEnabled } from "mock/mock.config";
import { shouldUseWorkspaceHomeApi } from "config/workspace.config";
import { workspaceService } from "_services/workspace.service";
import { WorkspacePanelHead } from "views/workspace/components/WorkspaceLuxShared";

function formatBriefingTime(value) {
  if (!value) {
    return "Just now";
  }
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    return "Just now";
  }
  return date.toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" });
}

/**
 * Wave 4 — Daily briefing from GET /api/v2/workspace/daily-briefing when live;
 * client buildWorkspaceDailyBriefing only when mock is on.
 */
export default function WorkspaceDailyBriefingPanel({ dashboard, activePersona, loading }) {
  const [briefing, setBriefing] = useState(null);
  const [briefingLoading, setBriefingLoading] = useState(false);
  const [unavailable, setUnavailable] = useState(false);

  useEffect(() => {
    if (!isWorkspaceBriefingEnabled()) {
      return undefined;
    }

    let cancelled = false;

    async function load() {
      if (isMockDataEnabled()) {
        if (loading) {
          setBriefing(null);
          setUnavailable(false);
          return;
        }
        setBriefing(buildWorkspaceDailyBriefing(dashboard, activePersona));
        setUnavailable(false);
        return;
      }

      if (!shouldUseWorkspaceHomeApi()) {
        setBriefing(null);
        setUnavailable(true);
        return;
      }

      setBriefingLoading(true);
      setUnavailable(false);
      try {
        const result = await workspaceService.getDailyBriefing(activePersona);
        if (cancelled) {
          return;
        }
        const payload = result && result.payload;
        if (payload) {
          setBriefing(payload);
          setUnavailable(false);
        } else {
          setBriefing(null);
          setUnavailable(true);
        }
      } catch (e) {
        if (!cancelled) {
          setBriefing(null);
          setUnavailable(true);
        }
      } finally {
        if (!cancelled) {
          setBriefingLoading(false);
        }
      }
    }

    load();
    return () => {
      cancelled = true;
    };
  }, [dashboard, activePersona, loading]);

  if (!isWorkspaceBriefingEnabled()) {
    return null;
  }

  const showLoading = loading || briefingLoading;

  return (
    <section className="lux-hrms-dash__panel lux-workspace-home-panel lux-workspace-home-panel--briefing lux-workspace-briefing" aria-label="Daily AI briefing">
      <WorkspacePanelHead
        title="Daily briefing"
        subtitle={
          briefing
            ? briefing.greeting
            : unavailable
              ? "Unavailable"
              : "Generating your operating summary"
        }
        actions={
          briefing && (
            <span className="lux-workspace-briefing__meta">
              <span className="lux-workspace-briefing__time">{formatBriefingTime(briefing.generatedAt)}</span>
            </span>
          )
        }
      />
      <div className="lux-hrms-dash__panel-body">
        {showLoading ? (
          <div className="lux-workspace-briefing__skeleton" aria-busy="true">
            <div className="lux-workspace-briefing__skeleton-line" />
            <div className="lux-workspace-briefing__skeleton-line is-short" />
            <div className="lux-workspace-briefing__skeleton-cards" />
          </div>
        ) : unavailable || !briefing ? (
          <p className="lux-workspace-briefing__empty lux-hrms-dash__empty" role="status">
            Unavailable — daily briefing could not be loaded from workspace signals.
          </p>
        ) : (
          <>
            <header className="lux-workspace-briefing__headline-wrap">
              <h3 className="lux-workspace-briefing__headline">{briefing.headline}</h3>
              <p className="lux-workspace-briefing__confidence">
                Confidence {Math.round((briefing.confidence || 0) * 100)}% · evidence-backed from workspace signals
              </p>
            </header>

            {(briefing.focusAreas || []).length > 0 && (
              <div className="lux-workspace-briefing__focus" aria-label="Focus areas">
                {briefing.focusAreas.map((area) => (
                  <span key={area} className="lux-workspace-briefing__focus-chip">
                    {area}
                  </span>
                ))}
              </div>
            )}

            <ol className="lux-workspace-briefing__priorities" role="list">
              {(briefing.priorities || []).map((item, index) => (
                <li key={item.id} className="lux-workspace-briefing__priority" role="listitem">
                  <span className="lux-workspace-briefing__rank">{index + 1}</span>
                  <Link
                    to={item.path}
                    className={classNames("lux-workspace-briefing__priority-link", item.tone && `is-${item.tone}`)}
                  >
                    <span className="lux-workspace-briefing__priority-icon" aria-hidden="true">
                      <i className={item.icon} />
                    </span>
                    <span className="lux-workspace-briefing__priority-copy">
                      <strong>{item.title}</strong>
                      <small>{item.copy}</small>
                      <em>{item.evidence}</em>
                    </span>
                    <i className="fe fe-chevron-right lux-workspace-briefing__chevron" aria-hidden="true" />
                  </Link>
                </li>
              ))}
            </ol>

            {briefing.disclaimer && <p className="lux-workspace-briefing__disclaimer">{briefing.disclaimer}</p>}
          </>
        )}
      </div>
    </section>
  );
}
