/**
 * Org-wide (root) access kill switches — Application Config
 * `personaNavigationAdditional`:
 *   pagePersonaMap, disabledPaths, disabledPersonas, disabledModules,
 *   disabledSidebarGroups
 *
 * Applied after role flags: org disable always wins.
 */

import { commonUtils } from "_helpers";
import { appConfigService } from "_services/appconfig.service";
import { PERMISSION_MODULE_META, PERMISSION_MODULE_ORDER } from "config/role-permission.config";

const PERSONA_TYPES = [
  "EMPLOYEE",
  "MANAGER",
  "PROJECT_MANAGER",
  "RESOURCE_MANAGER",
  "HR_ADMIN",
  "PAYROLL_MANAGER",
  "FINANCE_MANAGER",
  "EXECUTIVE",
  "ADMIN",
  "CLIENT",
];

export const PERSONA_NAVIGATION_CONFIG_KEY = "personaNavigationAdditional";
export const ORG_ACCESS_POLICY_CHANGED = "famstack-org-access-policy-changed";
const STORAGE_KEY = "tracopus_org_access_policy";

const EMPTY_POLICY = {
  pagePersonaMap: {},
  disabledPaths: [],
  disabledPersonas: [],
  disabledModules: [],
  disabledSidebarGroups: [],
};

/** Paths that must stay reachable so admins can undo kill switches. */
export const ORG_ACCESS_PROTECTED_PATHS = [
  "/admin/persona-navigation",
  "/admin/roles",
  "/admin/appconfig",
  "/admin/setup-checklist",
];

/** Module groups that must not be org-killed (would lock out admin recovery). */
export const ORG_ACCESS_PROTECTED_MODULES = ["adminModules"];

/** Sidebar catalog groups that must stay available for admin recovery. */
export const ORG_ACCESS_PROTECTED_SIDEBAR_GROUPS = ["admin"];

let cachedPolicy = null;

function normalizePath(pathname) {
  return (pathname || "").split("?")[0].replace(/\/+$/, "") || "/";
}

function normalizePersonaList(list) {
  if (!Array.isArray(list)) {
    return [];
  }
  const set = new Set();
  list.forEach((item) => {
    const code = String(item || "").trim().toUpperCase();
    if (code === "HR_MANAGER") {
      set.add("HR_ADMIN");
      return;
    }
    if (PERSONA_TYPES.includes(code)) {
      set.add(code);
    }
  });
  return PERSONA_TYPES.filter((p) => set.has(p));
}

function normalizePagePersonaMap(raw) {
  const map = {};
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
    return map;
  }
  Object.keys(raw).forEach((path) => {
    const personas = normalizePersonaList(raw[path]);
    if (personas.length > 0) {
      map[normalizePath(path)] = personas;
    }
  });
  return map;
}

function normalizePathList(list) {
  if (!Array.isArray(list)) {
    return [];
  }
  const set = new Set();
  list.forEach((item) => {
    const path = normalizePath(item);
    if (path && path !== "/" && !ORG_ACCESS_PROTECTED_PATHS.includes(path)) {
      set.add(path);
    }
  });
  return Array.from(set).sort();
}

function normalizeModuleList(list) {
  if (!Array.isArray(list)) {
    return [];
  }
  const set = new Set();
  list.forEach((item) => {
    const key = String(item || "").trim();
    if (PERMISSION_MODULE_ORDER.includes(key) && !ORG_ACCESS_PROTECTED_MODULES.includes(key)) {
      set.add(key);
    }
  });
  return PERMISSION_MODULE_ORDER.filter((k) => set.has(k));
}

function normalizeSidebarGroupList(list) {
  if (!Array.isArray(list)) {
    return [];
  }
  const set = new Set();
  list.forEach((item) => {
    const id = String(item || "").trim();
    if (id && !ORG_ACCESS_PROTECTED_SIDEBAR_GROUPS.includes(id)) {
      set.add(id);
    }
  });
  return Array.from(set).sort();
}

export function normalizeOrgAccessPolicy(raw) {
  const src = raw && typeof raw === "object" && !Array.isArray(raw) ? raw : {};
  const pagePersonaMap =
    src.pagePersonaMap != null
      ? normalizePagePersonaMap(src.pagePersonaMap)
      : normalizePagePersonaMap(src);
  return {
    pagePersonaMap,
    disabledPaths: normalizePathList(src.disabledPaths),
    disabledPersonas: normalizePersonaList(src.disabledPersonas),
    disabledModules: normalizeModuleList(src.disabledModules),
    disabledSidebarGroups: normalizeSidebarGroupList(src.disabledSidebarGroups),
  };
}

function readStoredPolicy() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) {
      return { ...EMPTY_POLICY };
    }
    return normalizeOrgAccessPolicy(JSON.parse(raw));
  } catch (e) {
    return { ...EMPTY_POLICY };
  }
}

function writeStoredPolicy(policy) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(policy || EMPTY_POLICY));
  } catch (e) {
    /* ignore */
  }
}

export function getOrgAccessPolicy() {
  if (cachedPolicy) {
    return cachedPolicy;
  }
  cachedPolicy = readStoredPolicy();
  return cachedPolicy;
}

export function setOrgAccessPolicyLocal(policy) {
  cachedPolicy = normalizeOrgAccessPolicy(policy);
  writeStoredPolicy(cachedPolicy);
  if (typeof window !== "undefined") {
    window.dispatchEvent(new CustomEvent(ORG_ACCESS_POLICY_CHANGED, { detail: cachedPolicy }));
  }
  return cachedPolicy;
}

export function getPagePersonaMap() {
  return getOrgAccessPolicy().pagePersonaMap || {};
}

export function getPagePersonaOverride(path) {
  const map = getPagePersonaMap();
  return map[normalizePath(path)] || null;
}

export function setPagePersonaMapLocal(map) {
  const current = getOrgAccessPolicy();
  return setOrgAccessPolicyLocal({
    ...current,
    pagePersonaMap: map,
  }).pagePersonaMap;
}

export function isOrgPathDisabled(pathname) {
  const path = normalizePath(pathname);
  const disabled = getOrgAccessPolicy().disabledPaths || [];
  return disabled.some((blocked) => path === blocked || path.startsWith(`${blocked}/`));
}

export function isOrgPersonaDisabled(persona) {
  const code = String(persona || "")
    .trim()
    .toUpperCase();
  return (getOrgAccessPolicy().disabledPersonas || []).includes(code);
}

export function isOrgModuleDisabled(moduleKey) {
  return (getOrgAccessPolicy().disabledModules || []).includes(moduleKey);
}

export function isOrgSidebarGroupDisabled(groupId) {
  const id = String(groupId || "").trim();
  if (!id || ORG_ACCESS_PROTECTED_SIDEBAR_GROUPS.includes(id)) {
    return false;
  }
  return (getOrgAccessPolicy().disabledSidebarGroups || []).includes(id);
}

export function filterPersonasByOrgPolicy(personas) {
  const list = Array.isArray(personas) ? personas : [];
  const filtered = list.filter((p) => !isOrgPersonaDisabled(p));
  if (filtered.length > 0) {
    return filtered;
  }
  if (!isOrgPersonaDisabled("EMPLOYEE")) {
    return ["EMPLOYEE"];
  }
  return list.length ? [list[0]] : ["EMPLOYEE"];
}

/** Force disabled module groups off inside menu access control. */
export function applyOrgModuleKillSwitches(menuAccessControl) {
  const access = menuAccessControl && typeof menuAccessControl === "object" ? { ...menuAccessControl } : {};
  const disabled = getOrgAccessPolicy().disabledModules || [];
  disabled.forEach((moduleKey) => {
    const mod = access[moduleKey];
    if (!mod || typeof mod !== "object") {
      access[moduleKey] = { active: false };
      return;
    }
    const next = { ...mod, active: false };
    Object.keys(next).forEach((flag) => {
      if (flag === "active" || /Enabled$/i.test(flag)) {
        next[flag] = false;
      }
    });
    access[moduleKey] = next;
  });
  return access;
}

function extractPolicyFromModulePayload(payload) {
  const list = Array.isArray(payload) ? payload : payload && payload.payload;
  if (!Array.isArray(list)) {
    return null;
  }
  const entry = list.find(
    (row) =>
      row &&
      (row.name === PERSONA_NAVIGATION_CONFIG_KEY ||
        row.configName === PERSONA_NAVIGATION_CONFIG_KEY ||
        row.key === PERSONA_NAVIGATION_CONFIG_KEY)
  );
  if (entry && entry.value && typeof entry.value === "object") {
    return normalizeOrgAccessPolicy(entry.value);
  }
  try {
    const value = commonUtils.getAppConfigValue(list, PERSONA_NAVIGATION_CONFIG_KEY);
    if (value && typeof value === "object") {
      return normalizeOrgAccessPolicy(value);
    }
  } catch (e) {
    /* ignore */
  }
  return null;
}

export async function loadOrgAccessPolicyFromAppConfig() {
  const teamId = commonUtils.getCurrentUserTeamId && commonUtils.getCurrentUserTeamId();
  if (!teamId) {
    cachedPolicy = readStoredPolicy();
    return cachedPolicy;
  }
  try {
    const response = await appConfigService.getModuleConfig(teamId, "HRMS");
    const fromApi = extractPolicyFromModulePayload(
      response && response.payload != null ? response : response
    );
    if (fromApi) {
      cachedPolicy = fromApi;
      writeStoredPolicy(fromApi);
      return cachedPolicy;
    }
  } catch (e) {
    /* fall through */
  }
  cachedPolicy = readStoredPolicy();
  return cachedPolicy;
}

/** @deprecated use loadOrgAccessPolicyFromAppConfig */
export async function loadPersonaPageMapFromAppConfig() {
  const policy = await loadOrgAccessPolicyFromAppConfig();
  return policy.pagePersonaMap || {};
}

export async function saveOrgAccessPolicy(policy) {
  const normalized = setOrgAccessPolicyLocal(policy);
  const teamId = commonUtils.getCurrentUserTeamId && commonUtils.getCurrentUserTeamId();
  if (!teamId) {
    return { payload: normalized, source: "local" };
  }
  try {
    const response = await appConfigService.getAppConfig(teamId, false);
    const model = (response && response.payload) || response;
    if (!model || !model.config) {
      return { payload: normalized, source: "local" };
    }
    const config = model.config;
    if (!config.modules) {
      config.modules = {};
    }
    if (!config.modules.HRMS) {
      config.modules.HRMS = {
        label: "HRMS",
        enabled: true,
        configurations: {},
      };
    }
    const hrms = config.modules.HRMS;
    if (!hrms.configurations) {
      hrms.configurations = {};
    }
    hrms.configurations[PERSONA_NAVIGATION_CONFIG_KEY] = {
      label: "Persona Navigation Access",
      value: {
        pagePersonaMap: normalized.pagePersonaMap,
        disabledPaths: normalized.disabledPaths,
        disabledPersonas: normalized.disabledPersonas,
        disabledModules: normalized.disabledModules,
        disabledSidebarGroups: normalized.disabledSidebarGroups,
      },
      hidden: false,
      locked: false,
      longList: true,
      inputType: "list",
      overridden: true,
    };
    await appConfigService.updateConfig(config, teamId);
    return { payload: normalized, source: "api" };
  } catch (e) {
    return { payload: normalized, source: "local", error: e };
  }
}

export async function savePersonaPageMap(map) {
  const current = getOrgAccessPolicy();
  const result = await saveOrgAccessPolicy({
    ...current,
    pagePersonaMap: map,
  });
  return {
    payload: (result.payload && result.payload.pagePersonaMap) || {},
    source: result.source,
    error: result.error,
  };
}

export function isPersonaNavigationAdminEnabled(menuAccessControl) {
  const admin = (menuAccessControl && menuAccessControl.adminModules) || {};
  return admin.personaNavigationEnabled === true || admin.rolesEnabled === true;
}

export function listOrgKillSwitchModules() {
  return PERMISSION_MODULE_ORDER.filter((key) => !ORG_ACCESS_PROTECTED_MODULES.includes(key)).map(
    (key) => ({
      key,
      label: (PERMISSION_MODULE_META[key] && PERMISSION_MODULE_META[key].label) || key,
      icon: (PERMISSION_MODULE_META[key] && PERMISSION_MODULE_META[key].icon) || "fe fe-box",
      tone: (PERMISSION_MODULE_META[key] && PERMISSION_MODULE_META[key].tone) || "slate",
    })
  );
}

export function listOrgKillSwitchPages() {
  // Lazy import avoided — callers use listCatalogPagesForPersonaAdmin and filter protected.
  return ORG_ACCESS_PROTECTED_PATHS;
}

export { normalizePath as normalizeOrgAccessPath };
