import React, { useState } from "react";
import classNames from "classnames/bind";

function averagePct(values) {
  if (!values || !values.length) return null;
  return Math.round(values.reduce((acc, n) => acc + n, 0) / values.length);
}

function formatGap(expectedAvg, actualAvg) {
  if (expectedAvg == null || actualAvg == null) return null;
  const gap = actualAvg - expectedAvg;
  return { gap, label: `${gap > 0 ? "+" : ""}${gap}` };
}

/**
 * Leave-calendar coverage = expected. Optional actualByDate = attendance present %.
 */
export default function LeaveCoveragePanel({
  coverage,
  actualByDate,
  loading,
  unavailableMessage,
}) {
  const hasActual = actualByDate && Object.keys(actualByDate).length > 0;
  const [view, setView] = useState("actual");

  if (loading) {
    return <div className="lux-leave-subpanel lux-leave-coverage is-loading" aria-busy="true" />;
  }
  if (!coverage || !Array.isArray(coverage.daily)) {
    if (!unavailableMessage) return null;
    return (
      <section className="lux-leave-subpanel lux-leave-coverage is-unavailable" aria-label="Team coverage unavailable">
        <header className="lux-leave-subpanel__head">
          <div>
            <span className="lux-leave-subpanel__eyebrow">Coverage</span>
            <h3 className="lux-leave-subpanel__title">Team coverage</h3>
            <p className="lux-leave-subpanel__sub">{unavailableMessage}</p>
          </div>
        </header>
      </section>
    );
  }

  const expectedValues = coverage.daily
    .filter((day) => !day.outsideShift && !day.holiday)
    .map((day) => Number(day.coveragePct) || 0);
  const expectedAvg = averagePct(
    expectedValues.length
      ? expectedValues
      : coverage.daily.map((d) => Number(d.coveragePct) || 0)
  );

  const actualValues = hasActual
    ? coverage.daily
        .map((day) => actualByDate[day.date])
        .filter((row) => row && row.pct != null && row.possible > 0)
        .map((row) => row.pct)
    : [];
  const actualAvg = averagePct(actualValues);
  const gapInfo = formatGap(expectedAvg, actualAvg);
  const showingActual = hasActual && view === "actual";

  return (
    <section
      className={classNames("lux-leave-subpanel lux-leave-coverage", {
        "has-actual": hasActual,
      })}
      aria-label="Team coverage heatmap"
    >
      <header className="lux-leave-coverage__head">
        <div className="lux-leave-coverage__intro">
          <span className="lux-leave-subpanel__eyebrow">Coverage</span>
          <h3 className="lux-leave-subpanel__title">Team coverage</h3>
          <p className="lux-leave-subpanel__sub">
            {hasActual
              ? "Expected is the leave plan. Actual is marked attendance."
              : "Expected coverage from approved leave — not live attendance."}
            {" · "}
            {coverage.monthLabel}
            {" · "}
            {coverage.teamSize} people
            {coverage.riskyDays > 0
              ? ` · ${coverage.riskyDays} expected at-risk day${coverage.riskyDays === 1 ? "" : "s"}`
              : ""}
          </p>
        </div>

        <div className="lux-leave-coverage__summary" role="group" aria-label="Coverage summary">
          <div className="lux-leave-coverage__stat is-expected">
            <span>Expected</span>
            <strong>{expectedAvg != null ? `${expectedAvg}%` : "—"}</strong>
          </div>
          {hasActual ? (
            <>
              <div className="lux-leave-coverage__stat is-actual">
                <span>Actual</span>
                <strong>{actualAvg != null ? `${actualAvg}%` : "—"}</strong>
              </div>
              <div
                className={classNames("lux-leave-coverage__stat is-gap", {
                  "is-behind": gapInfo && gapInfo.gap < 0,
                  "is-ahead": gapInfo && gapInfo.gap > 0,
                })}
              >
                <span>Gap</span>
                <strong>{gapInfo ? gapInfo.label : "—"}</strong>
              </div>
            </>
          ) : null}
        </div>
      </header>

      {hasActual ? (
        <div className="lux-leave-coverage__toggle" role="tablist" aria-label="Coverage view">
          <button
            type="button"
            role="tab"
            aria-selected={!showingActual}
            className={classNames("lux-leave-coverage__toggle-btn", { "is-active": !showingActual })}
            onClick={() => setView("expected")}
          >
            Expected
          </button>
          <button
            type="button"
            role="tab"
            aria-selected={showingActual}
            className={classNames("lux-leave-coverage__toggle-btn", { "is-active": showingActual })}
            onClick={() => setView("actual")}
          >
            Actual
          </button>
        </div>
      ) : null}

      <div className="lux-leave-coverage__grid" role="list">
        {coverage.daily.map((day) => {
          const actual = hasActual ? actualByDate[day.date] : null;
          const actualPct = actual && actual.possible > 0 ? actual.pct : null;
          const displayPct = showingActual
            ? actualPct != null
              ? actualPct
              : null
            : day.coveragePct;
          // Expected = orange; Actual = green (≥65%) / red (<65%).
          const toneClass = showingActual
            ? actualPct == null
              ? "is-empty"
              : actualPct < 65
                ? "is-bad"
                : "is-good"
            : day.outsideShift || day.holiday
              ? "is-empty"
              : "is-expected";

          const title = showingActual
            ? actualPct != null
              ? `Actual ${actualPct}% present (${actual.present}/${actual.possible})`
              : "Actual not available yet"
            : `Expected ${day.coveragePct}% · ${day.onLeaveCount} on leave${
                day.shiftNote ? ` · ${day.shiftNote}` : ""
              }`;

          return (
            <div
              key={day.date}
              role="listitem"
              className={classNames(
                "lux-leave-coverage__cell",
                toneClass,
                {
                  "is-outside-shift": !!day.outsideShift,
                  "is-holiday": !!day.holiday,
                  "is-pending": showingActual && actualPct == null,
                }
              )}
              title={title}
            >
              <span className="lux-leave-coverage__day">{day.label}</span>
              <span className="lux-leave-coverage__pct">
                {displayPct != null ? `${displayPct}%` : "—"}
              </span>
              {!showingActual ? <em>{day.onLeaveCount} away</em> : null}
              {showingActual && actualPct != null ? (
                <em>
                  {actual.present}/{actual.possible}
                </em>
              ) : null}
            </div>
          );
        })}
      </div>
    </section>
  );
}
