/**
 * EH17 — Vendor master FE service. Fail closed when flag on.
 */
import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";
import { shouldUseVendorMasterApi } from "config/vendor-master.config";

export const vendorMasterService = {
  listVendors,
  createVendor,
};

const API_ERROR = { payload: null, source: "api-error" };

function resolveUserTeamId() {
  return commonUtils.getCurrentUserTeamId();
}

async function listVendors() {
  if (!shouldUseVendorMasterApi()) {
    return { ...API_ERROR, reason: "flag-off" };
  }
  try {
    const response = await axiosUtils.getWithParam(urlConfig.VENDORS_MASTER_API_PATH, {
      userTeamId: resolveUserTeamId(),
    });
    const payload = response && response.payload != null ? response.payload : response;
    if (Array.isArray(payload)) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    console.warn("[VendorMaster] API unavailable.", e);
    return { ...API_ERROR, error: e };
  }
}

async function createVendor(body = {}) {
  if (!shouldUseVendorMasterApi()) {
    return { ...API_ERROR, reason: "flag-off" };
  }
  try {
    const response = await axiosUtils.post(urlConfig.VENDORS_MASTER_API_PATH, {
      ...body,
      userTeamId: body.userTeamId || resolveUserTeamId(),
      actorId: body.actorId || commonUtils.getCurrentUserId(),
    });
    const payload = response && response.payload != null ? response.payload : response;
    if (payload) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    console.warn("[VendorMaster] create unavailable.", e);
    return { ...API_ERROR, error: e };
  }
}
