import { shouldUsePerformanceManagement } from "config/tracopus-pilot.config";
import envconfig from "env.config";
import { isMockDataEnabled } from "mock/mock.config";

/** F14 — Performance management and growth. */

export function isPerformanceManagementEnabled() {
  if (shouldUsePerformanceManagement()) {
    return true;
  }
  if (isMockDataEnabled()) {
    return true;
  }
  return envconfig.ENV_NAME === "development";
}

export function shouldUsePerformanceManagementApi() {
  return envconfig.USE_PERFORMANCE_MANAGEMENT_API === true;
}

