import classNames from "classnames/bind";
import React, { Component } from "react";
import Skeleton, { SkeletonTheme } from "react-loading-skeleton";
import { LUX_SKELETON_THEME } from "views/common/fragments/luxSkeleton.constants";
import { getRegisterSkeletonRowKeys } from "views/common/fragments/luxRegisterListSkeleton.utils";
import dateUtils from "_helpers/date.utils";
import LuxActivityPanelEmptyState from "views/common/fragments/LuxActivityPanelEmptyState";
import {
  getChecklistStatusMeta,
  getPendingDueMeta,
  getWorkItemPriorityMeta,
  getWorkItemStatusMeta,
  summarizePendingItems,
} from "./workItemActivity.utils";

class WorkItemPendingItems extends Component {
  render() {
    const items = this.props.items || [];
    const summary = summarizePendingItems(items);

    return (
      <section className="lux-activity-pending" aria-label="Pending tasks">
        <header className="lux-activity-pending__head">
          <div className="lux-activity-pending__head-main">
            <h3 className="lux-activity-pending__title">
              My pending tasks
              <span className="lux-activity-pending__count">{summary.total}</span>
            </h3>
            {summary.total > 0 && (
              <div className="lux-activity-pending__stats">
                {summary.overdue > 0 && (
                  <span className="lux-activity-pending__stat is-rose">
                    <i className="fe fe-alert-circle" aria-hidden="true" />
                    {summary.overdue} overdue
                  </span>
                )}
                {summary.dueSoon > 0 && (
                  <span className="lux-activity-pending__stat is-amber">
                    <i className="fe fe-clock" aria-hidden="true" />
                    {summary.dueSoon} due soon
                  </span>
                )}
                {summary.checklistOpen > 0 && (
                  <span className="lux-activity-pending__stat is-indigo">
                    <i className="fe fe-check-square" aria-hidden="true" />
                    {summary.checklistOpen} checklist
                  </span>
                )}
              </div>
            )}
          </div>
          <button
            type="button"
            className="lux-project-row__action"
            onClick={() => this.props.reloadPendingTasks()}
            title="Reload pending tasks"
            aria-label="Reload pending tasks"
            data-ga-action="workitem_reload_pending"
            data-ga-category="engagement"
            data-ga-label="Reload"
          >
            <i className="fe fe-refresh-cw" aria-hidden="true" />
          </button>
        </header>

        <div className="lux-activity-pending__body">
          {this.props.isLoading && (
            <div className="lux-activity-pending__skeleton is-loading" aria-busy="true">
              <SkeletonTheme
                baseColor={LUX_SKELETON_THEME.baseColor}
                highlightColor={LUX_SKELETON_THEME.highlightColor}
              >
                {getRegisterSkeletonRowKeys(8).map((key) => (
                  <Skeleton
                    key={key}
                    height={96}
                    borderRadius={12}
                    containerClassName="lux-activity-pending__skeleton-line"
                  />
                ))}
              </SkeletonTheme>
            </div>
          )}

          {!this.props.isLoading && items.length > 0 && (
            <ul className="lux-activity-pending__list">
              {items.map((activityItem) => (
                <WorkItemPendingItem
                  key={activityItem.id}
                  item={activityItem}
                  permission={this.props.permission}
                  onCheklistItemClick={this.props.onCheklistItemClick}
                />
              ))}
            </ul>
          )}

          {!this.props.isLoading && items.length === 0 && (
            <LuxActivityPanelEmptyState
              variant="pending-tasks"
              eyebrow="Inbox clear"
              title="No pending activities"
              description="Deliverables waiting for your attention will appear here."
              hints={[
                "Create work items from project deliverables",
                "Check filters on the activity register",
                "Open checklists before starting work",
              ]}
            />
          )}
        </div>
      </section>
    );
  }
}

class WorkItemPendingItem extends Component {
  render() {
    const { item, permission } = this.props;
    const statusMeta = getWorkItemStatusMeta(item.status);
    const priorityMeta = getWorkItemPriorityMeta(item.taskPriority);
    const dueMeta = getPendingDueMeta(item.taskEstCompletionTime || item.estStartTime);
    const checklistMeta = getChecklistStatusMeta(item);
    const estDuration = dateUtils.minuteToHourString(item.estDurationInMins) || "—";
    const ownerName = (item.ownerDetails && item.ownerDetails.name) || "Unassigned";
    const ownerInitial = ownerName.substring(0, 1).toUpperCase();
    const projectLabel = item.projectName || item.taskName || "Non-project";
    const projectCode = item.projectcode || (item.taskType === "NON_PROJECT" ? "NON BILLABLE" : null);
    const checklistClass =
      checklistMeta.key === "COMPLETED"
        ? "is-done"
        : checklistMeta.key === "INPROGRESS"
          ? "is-progress"
          : checklistMeta.key === "NOT_STARTED"
            ? "is-open"
            : "";

    return (
      <li className={classNames("lux-activity-pending__item", { "is-overdue": dueMeta.overdue })}>
        <div className="lux-activity-pending__item-head">
          <div className="lux-activity-pending__item-lead">
            <span className={classNames("lux-activity-pending__status", `is-${statusMeta.tone}`)} title={statusMeta.label}>
              <i className={classNames(statusMeta.icon, { spin: statusMeta.spin })} aria-hidden="true" />
            </span>
            <span className={classNames("lux-activity-pending__prio", `is-${priorityMeta.tone}`)} title={priorityMeta.label}>
              P{priorityMeta.level}
            </span>
            {item.itemIdUserTeamPrefix && (
              <span className="lux-activity-pending__ref">{item.itemIdUserTeamPrefix}</span>
            )}
          </div>
          {permission && permission.checklistEnabled === true &&
            (item.taskType === "PROJECT" || item.taskType === "NON_PROJECT") && (
              <button
                type="button"
                className={classNames("lux-project-row__action is-checklist", checklistClass)}
                title={checklistMeta.label}
                aria-label={checklistMeta.label}
                onClick={() => this.props.onCheklistItemClick && this.props.onCheklistItemClick(item)}
              >
                <i className="fa fa-wpforms" aria-hidden="true" />
              </button>
            )}
        </div>

        <div className="lux-activity-pending__copy">
          <span className="lux-activity-pending__name" title={item.name}>
            {item.name}
          </span>
          <span className="lux-activity-pending__task" title={projectLabel}>
            {projectLabel}
          </span>
        </div>

        <div className="lux-activity-pending__meta">
          {projectCode && <span className="lux-activity-pending__chip is-code">[{projectCode}]</span>}
          {item.taskActCategory && (
            <span className="lux-activity-pending__chip">{item.taskActCategory}</span>
          )}
          <span className="lux-activity-pending__chip is-muted">
            <i className="fe fe-watch" aria-hidden="true" />
            Est {estDuration}
          </span>
        </div>

        <div className="lux-activity-pending__footer">
          <div className="lux-activity-pending__dates">
            <span title={`Start ${dateUtils.convertDateTimeFormat(item.estStartTime)}`}>
              <i className="fe fe-play-circle" aria-hidden="true" />
              {dateUtils.convertDateFormat(item.estStartTime)}
            </span>
            <span className={classNames("lux-activity-pending__due", `is-${dueMeta.tone}`)} title={dueMeta.dueLabel}>
              <i className="fe fe-flag" aria-hidden="true" />
              {dueMeta.label}
            </span>
          </div>
          <div className="lux-activity-pending__owner" title={ownerName}>
            <span className="lux-activity-pending__avatar">{ownerInitial}</span>
            <span className="lux-activity-pending__owner-name">{ownerName}</span>
          </div>
        </div>
      </li>
    );
  }
}

export default WorkItemPendingItems;
