import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isDeveloperPortalEnabled } from "config/developer-portal.config";
import { API_KEYS_PAGE_META } from "config/developer-portal-nav.config";
import { developerPortalService } from "_services/developerPortal.service";
import DeveloperLuxPage, {
  DeveloperActionButton,
  DeveloperInsightPanel,
  DeveloperLuxPanel,
} from "views/developer/components/DeveloperLuxShared";
import ApiKeyRegister from "views/developer/components/ApiKeyRegister";
import { ApiKeyCreateDrawer } from "views/developer/components/DeveloperCreateDrawers";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

class ApiKeysPage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    keys: [],
    kpiCards: [],
    insights: [],
    statusFilter: "ALL",
    busy: false,
    createOpen: false,
  };

  componentDidMount() {
    this.loadData();
  }

  loadData = async () => {
    const { statusFilter } = this.state;
    this.setState({ loading: true, loadError: null });
    try {
      const filters = statusFilter !== "ALL" ? { status: statusFilter } : {};
      const result = await developerPortalService.getOverview(filters);
      const payload = result.payload || {};
      this.setState({
        loading: false,
        dataSource: result.source,
        keys: payload.keys || [],
        kpiCards: payload.kpiCards || [],
        insights: payload.insights || [],
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load API keys.",
      });
    }
  };

  handleRevoke = async (key) => {
    this.setState({ busy: true });
    try {
      await developerPortalService.revokeApiKey(key.id);
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to revoke key." });
    } finally {
      this.setState({ busy: false });
    }
  };

  handleExport = async () => {
    try {
      const result = await developerPortalService.exportApiKeysCsv({});
      const blob = new Blob([result.payload || ""], { type: "text/csv;charset=utf-8;" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = "api-keys.csv";
      link.click();
      URL.revokeObjectURL(url);
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Export failed." });
    }
  };

  render() {
    if (!isDeveloperPortalEnabled()) {
      return <PersonaAccessDenied featureLabel="API keys" />;
    }

    const { loading, loadError, dataSource, keys, kpiCards, insights, statusFilter, busy, createOpen } = this.state;

    return (
      <DeveloperLuxPage
        pageMeta={API_KEYS_PAGE_META}
        pageId="api-keys"
        shellTitle="API keys"
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        heroActions={
          <>
            <DeveloperActionButton icon="fe fe-refresh-cw" onClick={this.loadData} disabled={loading}>
              Refresh
            </DeveloperActionButton>
            <DeveloperActionButton icon="fe fe-download" onClick={this.handleExport}>
              Export CSV
            </DeveloperActionButton>
            <DeveloperActionButton variant="primary" icon="fe fe-plus" onClick={() => this.setState({ createOpen: true })}>
              Create key
            </DeveloperActionButton>
            <DeveloperActionButton to="/admin/developer" icon="fe fe-code">
              Portal
            </DeveloperActionButton>
          </>
        }
      >
        {loadError ? <LuxInlineAlert message={loadError} /> : null}
        <DeveloperInsightPanel insights={insights} loading={loading} />
        <DeveloperLuxPanel
          title="API credentials"
          meta="Scoped keys with rotation and audit"
          icon="fe fe-key"
          accent="indigo"
          featured
          actions={
            <select
              className="lux-dev-filter"
              value={statusFilter}
              onChange={(e) => this.setState({ statusFilter: e.target.value }, this.loadData)}
            >
              <option value="ALL">All statuses</option>
              <option value="active">Active</option>
              <option value="revoked">Revoked</option>
              <option value="expired">Expired</option>
            </select>
          }
        >
          <ApiKeyRegister keys={keys} loading={loading} onRevoke={this.handleRevoke} busy={busy} />
        </DeveloperLuxPanel>
        <ApiKeyCreateDrawer
          open={createOpen}
          onClose={() => this.setState({ createOpen: false })}
          onCreate={(payload) => developerPortalService.createApiKey(payload)}
          onCreated={this.loadData}
        />
      </DeveloperLuxPage>
    );
  }
}

export default ApiKeysPage;
