import React, { Component } from "react";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import ClientLuxPage, {
  ClientActionButton,
  ClientLuxPanel,
} from "views/client/components/ClientLuxShared";
import { isClientPortalEnabled } from "config/client-portal.config";
import { clientPortalService } from "_services/clientPortal.service";
import ClientPortalNav from "./ClientPortalNav";

class ClientFeedbackPage extends Component {
  state = {
    loading: false,
    submitting: false,
    error: null,
    message: null,
    feedback: [],
    projectId: "",
    rating: "",
    comment: "",
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Client feedback");
    }
    this.load();
  }

  load = async () => {
    this.setState({ loading: true, error: null });
    try {
      const result = await clientPortalService.listFeedback();
      if (!result || result.source === "api-error") {
        this.setState({
          loading: false,
          error: "Unable to load feedback. Sign in at /client/login.",
          feedback: [],
        });
        return;
      }
      this.setState({
        loading: false,
        feedback: (result.payload && result.payload.feedback) || [],
      });
    } catch (e) {
      this.setState({ loading: false, error: (e && e.message) || "Unable to load feedback." });
    }
  };

  handleSubmit = async () => {
    const { projectId, rating, comment } = this.state;
    this.setState({ submitting: true, message: null });
    try {
      const result = await clientPortalService.submitFeedback({
        projectId: Number(projectId),
        rating: rating === "" ? null : Number(rating),
        comment: String(comment || "").trim(),
      });
      if (!result || result.source === "api-error") {
        this.setState({ submitting: false, message: "Submit failed." });
        return;
      }
      this.setState({
        submitting: false,
        message: `Submitted ${result.payload && result.payload.feedbackRef}`,
        comment: "",
        rating: "",
      });
      this.load();
    } catch (e) {
      this.setState({ submitting: false, message: (e && e.message) || "Submit failed." });
    }
  };

  render() {
    if (!isClientPortalEnabled()) {
      return (
        <ClientLuxPage>
          <LuxRegisterEmptyState title="Client portal unavailable" description="Enable REACT_APP_USE_CLIENT_PORTAL_API." />
        </ClientLuxPage>
      );
    }
    const { loading, submitting, error, message, feedback, projectId, rating, comment } = this.state;
    return (
      <ClientLuxPage
        testId="client-feedback-page"
        className="lux-client-portal-page"
        pageMeta={{
          tone: "indigo",
          icon: "fe fe-message-circle",
          eyebrow: "Client portal",
          titleLead: "Feedback",
          titleAccent: "channel",
          lede: "Submit client feedback linked to permitted projects.",
        }}
        heroActions={
          <ClientActionButton variant="primary" onClick={this.load} disabled={loading}>
            Refresh
          </ClientActionButton>
        }
      >
        <ClientPortalNav />
        {error ? (
          <LuxInlineAlert tone="warning" title="Unable to load feedback">
            {error}
          </LuxInlineAlert>
        ) : null}
        {message ? (
          <LuxInlineAlert tone="info" title="Feedback update">
            {message}
          </LuxInlineAlert>
        ) : null}
        <ClientLuxPanel title="Submit feedback" icon="fe fe-edit-3">
          <label className="form-label" htmlFor="cf-project">
            Project id
          </label>
          <input
            id="cf-project"
            className="form-control mb-2"
            value={projectId}
            onChange={(e) => this.setState({ projectId: e.target.value })}
          />
          <label className="form-label" htmlFor="cf-rating">
            Rating (optional)
          </label>
          <input
            id="cf-rating"
            className="form-control mb-2"
            type="number"
            min="1"
            max="5"
            value={rating}
            onChange={(e) => this.setState({ rating: e.target.value })}
          />
          <label className="form-label" htmlFor="cf-comment">
            Comment
          </label>
          <textarea
            id="cf-comment"
            className="form-control mb-2"
            rows={3}
            value={comment}
            onChange={(e) => this.setState({ comment: e.target.value })}
          />
          <ClientActionButton variant="primary" onClick={this.handleSubmit} disabled={submitting}>
            {submitting ? "Submitting…" : "Submit feedback"}
          </ClientActionButton>
        </ClientLuxPanel>
        <ClientLuxPanel title="Feedback" icon="fe fe-list" meta={`${feedback.length} entr${feedback.length === 1 ? "y" : "ies"}`}>
          {feedback.length === 0 && !loading && !error ? (
            <LuxRegisterEmptyState title="No feedback yet" description="Submit feedback for a permitted project." showCreate={false} />
          ) : (
            <ul className="lux-client-portal-list lux-client-portal-list--plain">
              {feedback.map((row) => (
                <li key={row.feedbackRef || row.id}>
                  {row.feedbackRef}: project {row.projectId}
                  {row.rating != null ? ` · ${row.rating}/5` : ""} — {row.comment || ""}
                </li>
              ))}
            </ul>
          )}
        </ClientLuxPanel>
      </ClientLuxPage>
    );
  }
}

export default ClientFeedbackPage;
