import React, { Component } from "react";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import ClientLuxPage, {
  ClientActionButton,
  ClientLuxPanel,
} from "views/client/components/ClientLuxShared";
import { isClientPortalEnabled } from "config/client-portal.config";
import { clientPortalService } from "_services/clientPortal.service";
import ClientPortalNav from "./ClientPortalNav";

class ClientInvoicesPage extends Component {
  state = { loading: false, error: null, invoices: [], summary: null };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Client invoices");
    }
    this.load();
  }

  load = async () => {
    this.setState({ loading: true, error: null });
    try {
      const result = await clientPortalService.listInvoices();
      if (!result || result.source === "api-error") {
        this.setState({
          loading: false,
          error: "Unable to load invoices. Sign in at /client/login.",
          invoices: [],
        });
        return;
      }
      this.setState({
        loading: false,
        invoices: (result.payload && result.payload.invoices) || [],
        summary: result.payload && result.payload.invoiceSummary,
      });
    } catch (e) {
      this.setState({ loading: false, error: (e && e.message) || "Unable to load invoices." });
    }
  };

  render() {
    if (!isClientPortalEnabled()) {
      return (
        <ClientLuxPage>
          <LuxRegisterEmptyState title="Client portal unavailable" description="Enable REACT_APP_USE_CLIENT_PORTAL_API." />
        </ClientLuxPage>
      );
    }
    const { loading, error, invoices, summary } = this.state;
    return (
      <ClientLuxPage
        testId="client-invoices-page"
        className="lux-client-portal-page"
        pageMeta={{
          tone: "indigo",
          icon: "fe fe-file-text",
          eyebrow: "Client portal",
          titleLead: "Invoices",
          titleAccent: "visibility",
          lede: "Account-scoped invoice visibility (read-only).",
        }}
        heroActions={
          <ClientActionButton variant="primary" onClick={this.load} disabled={loading}>
            Refresh
          </ClientActionButton>
        }
      >
        <ClientPortalNav />
        {error ? (
          <LuxInlineAlert tone="warning" title="Unable to load invoices">
            {error}
          </LuxInlineAlert>
        ) : null}
        {summary ? (
          <p className="small text-muted">
            Paid {summary.paidCount} · Outstanding {summary.outstandingCount}
          </p>
        ) : null}
        <ClientLuxPanel title="Invoices" icon="fe fe-list" meta={`${invoices.length} record${invoices.length === 1 ? "" : "s"}`}>
          {invoices.length === 0 && !loading && !error ? (
            <LuxRegisterEmptyState title="No invoices" description="No invoices in the account lookback window." showCreate={false} />
          ) : (
            <ul className="lux-client-portal-list lux-client-portal-list--plain">
              {invoices.map((row) => (
                <li key={row.id}>
                  {row.invoiceNumber || row.name || row.id} — {row.status} ({row.totalAmount})
                </li>
              ))}
            </ul>
          )}
        </ClientLuxPanel>
      </ClientLuxPage>
    );
  }
}

export default ClientInvoicesPage;
