import React, { useEffect } from 'react';
import { Router, Route, Switch, Redirect } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';

import { accessUtils, authGetItem, ensureAuthSession, history, returnUrlUtils, init as initAnalytics, trackPageView, setupGlobalTracking, applyPageSeo } from './_helpers';
import { notificationActions } from './_actions';
import MainLayout from 'layouts/MainLayout';
import PersonaContextProvider from 'context/PersonaContextProvider';
import UserLayout from 'layouts/UserLayout';
import ErrorLayout from 'layouts/ErrorLayout';
import DocsLayout from 'layouts/DocsLayout';

// Share auth across tabs; clear non-remembered sessions on cold browser start.
ensureAuthSession();

function App() {
  const dispatch = useDispatch();

  useEffect(() => {
    initAnalytics();
    const trackLocation = (location) => {
      const path = (location.pathname || "") + (location.search || "");
      const seo = applyPageSeo(location.pathname);
      trackPageView(path, seo.title);
    };
    const unlisten = history.listen((location) => {
      notificationActions && dispatch(notificationActions.clear());
      trackLocation(location);
    });
    trackLocation(history.location);
    return () => unlisten();
  }, [dispatch]);

  useEffect(() => setupGlobalTracking(), []);

  function getRedirectPageUrl() {
    const menuAccessControl = accessUtils.getMenuAccessControl();
   if(menuAccessControl && menuAccessControl.projectModules && menuAccessControl.projectModules.active === true){
    return "/project/" +  (menuAccessControl.projectModules.defaultRedirectPage ? menuAccessControl.projectModules.defaultRedirectPage : "dashboard");
   } else if(menuAccessControl && menuAccessControl.peopleModules && menuAccessControl.peopleModules.active === true){
    return "/people/" +  (menuAccessControl.peopleModules.defaultRedirectPage ? menuAccessControl.peopleModules.defaultRedirectPage : "dashboard");
   } else if(menuAccessControl && menuAccessControl.salesModules  && menuAccessControl.salesModules.active === true){
    return "/sales/" +  (menuAccessControl.salesModules.defaultRedirectPage ? menuAccessControl.salesModules.defaultRedirectPage : "bidrequests");
   }
    return "/project/dashboard";
  }

  return (
    <Router history={history}>
      <Switch>
        <Route path="/hrms" render={props => securePage(props)} />
        <Route path="/sales" render={props => securePage(props)} />
        <Route path="/project" render={props => securePage(props)} />
        <Route path="/report" render={props => securePage(props)} />
        <Route path="/workspace" render={props => securePage(props)} />
        <Route path="/client" render={props => securePage(props)} />
        <Route path="/people" render={props => securePage(props)} />
        <Route path="/integrations" render={props => securePage(props)} />
        <Route path="/ai" render={props => securePage(props)} />
        <Route path="/finance" render={props => securePage(props)} />
        <Route path="/resources" render={props => securePage(props)} />
        <Route path="/payroll" render={props => securePage(props)} />
        <Route path="/performance" render={props => securePage(props)} />
        <Route path="/analytics" render={props => securePage(props)} />
        <Route path="/admin" render={props => securePage(props)} />
        {/* W17–W26 expansion layouts — must mount MainLayout or URLs fall through to "/" redirect */}
        <Route path="/recruiting" render={props => securePage(props)} />
        <Route path="/learning" render={props => securePage(props)} />
        <Route path="/benefits" render={props => securePage(props)} />
        <Route path="/npd" render={props => securePage(props)} />
        <Route path="/dossiers" render={props => securePage(props)} />
        <Route path="/vendors" render={props => securePage(props)} />
        {/* EH16 — convenience alias; MainLayout aliases also map /delivery → /project/delivery */}
        <Route path="/delivery" render={props => securePage(props)} />
        <Route path="/user" render={props => inSecurePage(props)} />
        <Route path="/error" render={props =>  <ErrorLayout {...props} />} />
        <Route path="/document" render={props =>  <DocsLayout {...props} />} />
        <Redirect from="/" to={getRedirectPageUrl()} />
      </Switch>
    </Router>
  );

  function inSecurePage(props) {
    return (
      authGetItem('cu')
        ? <Redirect to={{ pathname: '/', state: { from: props.location } }} />
        : <UserLayout {...props} />
    );
  }

  function securePage(props) {
    if (!authGetItem('cu')) {
      returnUrlUtils.saveReturnUrl(props.location);
      return (
        <Redirect to={{ pathname: '/user/login', state: { from: props.location } }} />
      );
    }
    return (
      <PersonaContextProvider>
        <MainLayout {...props} />
      </PersonaContextProvider>
    );
  }
}

export default App;