import React, { Component } from "react";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import SelectInput from "views/common/fragments/formfields/SelectInput";
import dateUtils from "_helpers/date.utils";
import {
  buildInvoiceShareUrl,
  formatCurrency,
  getInvoiceNumber,
  getInvoiceShareAccessToken,
  getUserCount,
  INVOICE_STATUS_META,
} from "./invoice.utils";

const STATUS_OPTIONS = [
  { value: "DRAFT", label: "Draft", level: 0 },
  { value: "PENDING", label: "Pending", level: 1 },
  { value: "APPROVED", label: "Approved", level: 2 },
  { value: "PAID", label: "Paid", level: 3 },
  { value: "CLOSED", label: "Closed", level: 4 },
];

class InvoiceLineItem extends Component {
  constructor(props) {
    super(props);
    this.state = {
      confirmDelete: false,
      menuOpen: false,
    };
    this.rowRef = React.createRef();
  }

  componentDidMount() {
    document.addEventListener("mousedown", this.handleOutsideClick);
  }

  componentWillUnmount() {
    document.removeEventListener("mousedown", this.handleOutsideClick);
  }

  handleOutsideClick = (event) => {
    if (!this.state.menuOpen) return;
    if (this.rowRef.current && !this.rowRef.current.contains(event.target)) {
      this.setState({ menuOpen: false, confirmDelete: false });
    }
  };

  handleRemoveInvoice = (event) => {
    event.preventDefault();
    event.stopPropagation();
    if (this.state.confirmDelete) {
      this.props.removeInvoice(this.props.item.id);
      this.setState({ confirmDelete: false, menuOpen: false });
    } else {
      this.setState({ confirmDelete: true });
    }
  };

  toggleMenu = (event) => {
    event.preventDefault();
    event.stopPropagation();
    this.setState((prev) => ({
      menuOpen: !prev.menuOpen,
      confirmDelete: false,
    }));
  };

  closeMenu = () => {
    this.setState({ menuOpen: false, confirmDelete: false });
  };

  getShareUrl = () => {
    return buildInvoiceShareUrl(
      this.props.item,
      getInvoiceShareAccessToken(this.props.header)
    );
  };

  getStatusMeta = () => {
    const status = this.props.item.status || "DRAFT";
    return INVOICE_STATUS_META[status] || INVOICE_STATUS_META.DRAFT;
  };

  render() {
    const { item, permission, handleUpdateStatus } = this.props;
    const statusMeta = this.getStatusMeta();
    const invoiceNumber = getInvoiceNumber(item);
    const userCount = getUserCount(item);
    const invoiceDate = dateUtils.convertDateFormat(item.invoiceDateTime);
    const monthLabel = item.invoiceMonthYear
      ? dateUtils
          .convertDateStringToMoment(item.invoiceMonthYear)
          .format(dateUtils.DATE_MONTH_FORMAT)
      : null;

    return (
      <article
        ref={this.rowRef}
        className={classNames("lux-inv-list__item", {
          "is-menu-open": this.state.menuOpen,
          [`is-status-${statusMeta.tone}`]: true,
        })}
        role="listitem"
      >
        <div className="lux-inv-list__col lux-inv-list__col--invoice">
          <div className="lux-inv-list__invoice-icon">
            <i className="fe fe-file-text" aria-hidden="true" />
          </div>
          <div className="lux-inv-list__invoice-copy">
            <div className="lux-inv-list__invoice-top">
              <span className="lux-inv-list__number">#{invoiceNumber}</span>
              <span
                className={classNames(
                  "lux-inv-list__status-pill",
                  `is-${statusMeta.tone}`
                )}
              >
                {statusMeta.label}
              </span>
            </div>
            <Link
              to={`/finance/invoice/details/${item.id}`}
              className="lux-inv-list__title"
            >
              {item.name || "Untitled invoice"}
              <i className="fe fe-arrow-up-right" aria-hidden="true" />
            </Link>
            {item.description && (
              <p className="lux-inv-list__description">{item.description}</p>
            )}
          </div>
        </div>

        <div className="lux-inv-list__col lux-inv-list__col--period">
          <span className="lux-inv-list__cell-label">Invoice date</span>
          <strong>{invoiceDate}</strong>
          {monthLabel && <span className="lux-inv-list__cell-hint">{monthLabel}</span>}
        </div>

        <div className="lux-inv-list__col lux-inv-list__col--users is-center">
          <span className="lux-inv-list__cell-label">Users</span>
          <strong className="lux-inv-list__users-count">{userCount}</strong>
        </div>

        <div className="lux-inv-list__col lux-inv-list__col--status">
          <span className="lux-inv-list__cell-label">Status</span>
          <SelectInput
            options={STATUS_OPTIONS}
            value={item.status}
            allowLevelDown={true}
            changeableStatus={["DRAFT", "PENDING", "APPROVED", "PAID", "CLOSED"]}
            isReadOnly={false}
            itemId={item.id}
            onChange={handleUpdateStatus}
            className={classNames(
              "lux-inv-list__status-select",
              "badge",
              { "badge-info": item.status === "DRAFT" },
              { "badge-primary": item.status === "PENDING" },
              { "badge-warning": item.status === "APPROVED" },
              { "badge-success": item.status === "PAID" },
              { "badge-dark": item.status === "CLOSED" }
            )}
          />
        </div>

        <div className="lux-inv-list__col lux-inv-list__col--amount">
          <span className="lux-inv-list__cell-label">Amount</span>
          <strong className="lux-inv-list__amount">
            {permission.viewEnabled
              ? formatCurrency(item.subTotal)
              : "—"}
          </strong>
        </div>

        <div className="lux-inv-list__col lux-inv-list__col--actions is-center">
          <button
            type="button"
            className="lux-inv-list__menu-btn"
            onClick={this.toggleMenu}
            aria-label="Invoice actions"
            aria-expanded={this.state.menuOpen}
          >
            <i className="fe fe-more-vertical" aria-hidden="true" />
          </button>

          {this.state.menuOpen && (
            <div className="lux-inv-list__menu" role="menu">
              <Link
                to={`/finance/invoice/details/${item.id}`}
                className="lux-inv-list__menu-item"
                role="menuitem"
                onClick={this.closeMenu}
              >
                <i className="fe fe-eye" aria-hidden="true" />
                View invoice
              </Link>
              {permission.viewEnabled && this.getShareUrl() && (
                <a
                  href={this.getShareUrl()}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="lux-inv-list__menu-item"
                  role="menuitem"
                  onClick={this.closeMenu}
                >
                  <i className="fe fe-share-2" aria-hidden="true" />
                  Share link
                </a>
              )}
              <button
                type="button"
                className="lux-inv-list__menu-item"
                role="menuitem"
                onClick={(e) => {
                  e.preventDefault();
                  window.open(`/finance/invoice/details/${item.id}`, "_blank");
                  this.closeMenu();
                }}
              >
                <i className="fe fe-printer" aria-hidden="true" />
                Open for print
              </button>
              {permission.removeEnabled && (
                <button
                  type="button"
                  className={classNames("lux-inv-list__menu-item", "is-danger", {
                    "is-confirm": this.state.confirmDelete,
                  })}
                  role="menuitem"
                  onClick={this.handleRemoveInvoice}
                >
                  <i
                    className={`fe ${this.state.confirmDelete ? "fe-check" : "fe-trash-2"}`}
                    aria-hidden="true"
                  />
                  {this.state.confirmDelete ? "Confirm delete" : "Delete invoice"}
                </button>
              )}
            </div>
          )}
        </div>
      </article>
    );
  }
}

export default InvoiceLineItem;
