import React, { Component } from "react";
import { NavLink } from "react-router-dom";
import { userActions } from '_actions';
import { connect } from 'react-redux';
import PropTypes from "prop-types";
import { store } from '_helpers';
import { validationUtils } from "_helpers";
import LoginPageFooter from "./LoginPageFooter";
import AuthPageShell from "./components/AuthPageShell";
import AuthLoginCard from "./components/AuthLoginCard";

class ForgotPassword extends Component {
  constructor() {
    super();
    this.state = {
      submitted: false,
      email: "",
      invalidEmail: false,
      errors: {
        email: ""
      }
    };
  }

  onSubmit = (e) => {
    e.preventDefault();
    this.setState({ invalidEmail: false, submitted: true });
    if (this.state.email && validationUtils.validateEmail(this.state.email)) {
      store.dispatch(this.props.initiateAccountActivation(this.state.email));
    } else {
      this.setState({ invalidEmail: true });
    }
  }

  onChange = (e) => {
    this.setState({ submitted: false, invalidEmail: false });
    const { name, value } = e.target;
    this.setState({ [name]: value });
  }

  render() {
    const success = this.props.authentication.initiateActivationRequestSuccess;
    const submitting = this.props.authentication.initiatinalizingAccountActivation;

    return (
      <AuthPageShell>
        <AuthLoginCard
          eyebrow="Account recovery"
          title="Forgot password"
          subtitle={
            success
              ? null
              : "Enter your work email and we will send a password reset link."
          }
          footer={
            <p className="auth-login__foot-text">
              Remember your password?{" "}
              <NavLink
                to="/user/login"
                className="auth-login__link"
                data-ga-action="forgot_password_back"
                data-ga-category="auth"
                data-ga-label="Send me Back"
              >
                Back to sign in
              </NavLink>
            </p>
          }
        >
          {success ? (
            <div className="auth-login__success" role="status">
              <i className="fe fe-check-circle" aria-hidden="true" />
              <p>
                If an account exists for that email, a password reset link has been sent. Please check your inbox.
              </p>
            </div>
          ) : (
            <form onSubmit={this.onSubmit} noValidate>
              <div className="form-group">
                <label className="form-label" htmlFor="forgotEmail">Email</label>
                <div className="passwordinputcontainer auth-login__field">
                  <span className="input-icon-addon"><i className="fe fe-mail" aria-hidden="true" /></span>
                  <input
                    type="email"
                    className={`form-control passwordinput${this.state.submitted && this.state.invalidEmail ? ' is-invalid' : ''}`}
                    id="forgotEmail"
                    placeholder="you@company.com"
                    name="email"
                    value={this.state.email}
                    onChange={this.onChange}
                    autoComplete="email"
                    autoFocus
                    disabled={submitting}
                    aria-invalid={this.state.submitted && this.state.invalidEmail}
                  />
                </div>
                {((this.state.submitted && this.state.invalidEmail) || this.props.authentication.error) && (
                  <div className="invalid-feedback" style={{ display: 'block' }}>A valid email is required</div>
                )}
              </div>
              <div className="form-footer auth-login__actions">
                <button
                  type="submit"
                  className="btn btn-primary btn-block auth-login__submit"
                  disabled={submitting}
                  aria-busy={!!submitting}
                  data-ga-action="forgot_password_submit"
                  data-ga-category="auth"
                  data-ga-label="Request password reset"
                >
                  {submitting && (
                    <span className="spinner-border spinner-border-sm mr-1" aria-hidden="true" />
                  )}
                  Send reset link
                </button>
              </div>
            </form>
          )}
        </AuthLoginCard>
        <LoginPageFooter />
      </AuthPageShell>
    );
  }
}

ForgotPassword.propTypes = {
  initiateAccountActivation: PropTypes.func.isRequired,
  authentication: PropTypes.object.isRequired
};

const mapStateToProps = state => ({
  authentication: state.authentication,
});

const mapDispatchToProps = () => ({
  initiateAccountActivation: userActions.initiateAccountActivation
});

export default connect(
  mapStateToProps,
  mapDispatchToProps
)(ForgotPassword);
