/**
 * F05-T1/T5: Regularization payload, conflicts, payroll lock helpers.
 */
import moment from "moment";
import {
  DEFAULT_REGULARIZATION_POLICY,
  getExceptionTypeLabel,
} from "config/attendance-regularization.config";
import {
  findAttendanceItem,
  isAttendanceMarked,
  normalizeAttendanceStatus,
} from "views/hrms/components/attendance/attendance.utils";

export const REGULARIZATION_STATUS = {
  DRAFT: "DRAFT",
  SUBMITTED: "SUBMITTED",
  APPROVED: "APPROVED",
  REJECTED: "REJECTED",
  WITHDRAWN: "WITHDRAWN",
};

export function normalizeRegularizationPayload(apiPayload) {
  if (!apiPayload) return null;
  return {
    id: apiPayload.id,
    userTeamId: apiPayload.userTeamId || apiPayload.user_team_id || null,
    employeeId: apiPayload.employeeId || apiPayload.employee_id,
    markDate: apiPayload.markDate || apiPayload.mark_date,
    exceptionType: apiPayload.exceptionType || apiPayload.exception_type,
    exceptionLabel: getExceptionTypeLabel(apiPayload.exceptionType || apiPayload.exception_type),
    requestedInTime: apiPayload.requestedInTime || apiPayload.requested_in_time,
    requestedOutTime: apiPayload.requestedOutTime || apiPayload.requested_out_time,
    reason: apiPayload.reason,
    status: apiPayload.status || REGULARIZATION_STATUS.SUBMITTED,
    payrollLocked: apiPayload.payrollLocked === true,
    timesheetConflict: apiPayload.timesheetConflict === true,
    employeeName: apiPayload.employeeName,
    empCode: apiPayload.empCode || apiPayload.employeeCode || apiPayload.emp_code || null,
  };
}

export function buildRegularizationSubmitPayload(form, employee, actorId) {
  const markDate = moment.isMoment(form.markDate)
    ? form.markDate
    : moment(form.markDate);
  return {
    employeeId: employee.id,
    userTeamId: employee.userTeamId,
    actorId: actorId || employee.id,
    // BE parseMarkDate accepts ISO local date or dd-MM-yyyy (not full SERVER_DATE_FORMAT datetime).
    markDate: markDate.isValid() ? markDate.format("YYYY-MM-DD") : form.markDate,
    exceptionType: form.exceptionType,
    requestedInTime: form.requestedInTime || null,
    requestedOutTime: form.requestedOutTime || null,
    reason: form.reason ? form.reason.trim() : "",
    remarks: form.remarks ? form.remarks.trim() : null,
  };
}

export function isPayrollPeriodLocked(markDate, policy) {
  const p = policy || DEFAULT_REGULARIZATION_POLICY;
  const lockDay = p.payrollLockDayOfMonth || 25;
  const date = moment.isMoment(markDate) ? markDate : moment(markDate);
  const now = moment();
  if (now.date() >= lockDay && date.isBefore(now.clone().startOf("month"))) {
    return true;
  }
  return false;
}

export function detectTimesheetConflict(markDate, timesheetWeeks) {
  const date = moment.isMoment(markDate) ? markDate : moment(markDate);
  return (timesheetWeeks || []).some((week) => {
    const start = moment(week.weekStart || week.startDate);
    const end = moment(week.weekEnd || week.endDate);
    if (!start.isValid() || !end.isValid()) return false;
    if (!date.isBetween(start, end, "day", "[]")) return false;
    const status = String(week.status || week.approvalStatus || "").toUpperCase();
    return status === "APPROVED" || status === "LOCKED" || week.locked === true;
  });
}

export function buildRegularizationEligibility(dayMonth, item, policy) {
  const meta = { eligible: true, reasons: [] };
  if (!dayMonth || dayMonth.isAfter(moment(), "day")) {
    meta.eligible = false;
    meta.reasons.push("Future dates cannot be regularized.");
  }
  const backdatedLimit = (policy && policy.allowBackdatedDays) || 7;
  if (dayMonth && dayMonth.isBefore(moment().subtract(backdatedLimit, "days"), "day")) {
    meta.eligible = false;
    meta.reasons.push(`Backdating limited to ${backdatedLimit} days.`);
  }
  if (isPayrollPeriodLocked(dayMonth, policy)) {
    meta.eligible = false;
    meta.reasons.push("Payroll lock is active for this period.");
  }
  if (item && normalizeAttendanceStatus(item.status) === "APPROVED" && item.checkoutTime) {
    meta.eligible = false;
    meta.reasons.push("Complete attendance already recorded.");
  }
  return meta;
}

export function resolveRegularizationEmployee(request, employees) {
  const eid = request && request.employeeId;
  const match =
    (employees || []).find((emp) => String(emp.id) === String(eid)) || null;
  const nameFromRequest =
    request && request.employeeName && String(request.employeeName).trim()
      ? String(request.employeeName).trim()
      : null;
  const name =
    (match && match.name) ||
    nameFromRequest ||
    (eid != null ? `Employee ${eid}` : "Unknown employee");
  const empCode =
    (match && (match.empCode || match.employeeCode || match.code)) ||
    (request && (request.empCode || request.employeeCode)) ||
    null;
  return {
    employeeId: eid,
    employeeName: name,
    empCode: empCode ? String(empCode) : null,
    employee: match,
  };
}

export function summarizeRegularizationPending(requests, employees) {
  const list = requests || [];
  const byEmployee = {};
  list.forEach((req) => {
    const resolved = resolveRegularizationEmployee(req, employees);
    const eid = resolved.employeeId;
    if (!byEmployee[eid]) {
      byEmployee[eid] = {
        employeeId: eid,
        employeeName: resolved.employeeName,
        empCode: resolved.empCode,
        items: [],
      };
    }
    byEmployee[eid].items.push({
      ...req,
      employeeName: resolved.employeeName,
      empCode: resolved.empCode,
    });
  });
  const groups = Object.values(byEmployee);
  return {
    total: list.length,
    employeeCount: groups.length,
    groups,
  };
}

export function findRegularizableDays(employeeId, monthDays, items, policy) {
  return (monthDays || [])
    .map((day) => {
      const item = findAttendanceItem(items, employeeId, day);
      const eligibility = buildRegularizationEligibility(day, item, policy);
      if (!eligibility.eligible) return null;
      const marked = isAttendanceMarked(item);
      if (marked && item && normalizeAttendanceStatus(item.status) === "APPROVED" && item.checkoutTime) {
        return null;
      }
      return { day, item, eligibility };
    })
    .filter(Boolean);
}

export function permissionAllowsApprove(permission) {
  return !!(permission && (permission.approveTeamEnabled || permission.approveEnabled));
}

export function mergeRegularizations(existing, employeeRegs, pendingRegs) {
  const map = new Map();
  [...(existing || []), ...(employeeRegs || []), ...(pendingRegs || [])].forEach((row) => {
    if (row && row.id != null) {
      map.set(String(row.id), row);
    }
  });
  return Array.from(map.values());
}
