import React, { Component } from 'react';
import { createPortal } from 'react-dom';
import { connect } from 'react-redux';
import classNames from 'classnames/bind';
import { accessUtils, commonUtils, store } from '_helpers';
import { employeeConstants } from '_constants';
import {
  loadLeaveConfig,
  LEAVE_CONFIG_CHANGED,
  shouldUseLeaveManagement,
  resolveLeaveUserTeamIds,
  resolveLeaveWriteUserTeamId,
  buildLeaveUserTeamsAllSelected,
} from '_helpers/leave.config';
import { leaveService } from '_services/leave.service';
import PageInnerHeader from 'views/common/PageInnerHeader';
import { PageDataSourceReporter } from 'views/common/PageChromeContext';
import LuxModuleIntro from 'views/common/fragments/LuxModuleIntro';
import PageCreateButton from 'views/common/fragments/PageCreateButton';
import LuxRegisterEmptyState from 'views/common/fragments/LuxRegisterEmptyState';
import {
  AdminInsightStrip,
  AdminKpiStrip,
} from 'views/admin/components/AdminLuxShared';
import { LEAVE_TYPE_OPTIONS } from './components/leave/leave.utils';
import LeavePolicyModeSwitcher from './globalLeave/LeavePolicyModeSwitcher';
import AccrualSourceBanner from './globalLeave/AccrualSourceBanner';
import { globalLeavePolicyService as globalLeaveApi } from '_services/globalLeavePolicy.service';
import './globalLeave/globalLeavePolicyCenter.css';
import './leaveLuxForms.css';

function buildLeavePolicyPageInsights(leaveTypes, policies) {
  const insights = [];
  const inactiveTypes = leaveTypes.filter((type) => type.active === false);
  const draftPolicies = policies.filter((policy) => policy.active === false);

  if (inactiveTypes.length > 0) {
    insights.push({
      id: 'inactive-types',
      tone: 'amber',
      icon: 'fe fe-alert-triangle',
      title: `${inactiveTypes.length} inactive leave type(s)`,
      copy: 'Disabled codes are hidden from employee request dropdowns.',
    });
  }
  if (policies.length === 0 && leaveTypes.length > 0) {
    insights.push({
      id: 'no-policies',
      tone: 'rose',
      icon: 'fe fe-book-open',
      title: 'No entitlement policies',
      copy: 'Add a policy to define monthly accrual rules.',
    });
  }
  if (draftPolicies.length > 0) {
    insights.push({
      id: 'draft-policies',
      tone: 'blue',
      icon: 'fe fe-edit-3',
      title: `${draftPolicies.length} inactive polic${draftPolicies.length === 1 ? 'y' : 'ies'}`,
      copy: 'Activate policies to apply entitlements to employees.',
    });
  }
  if (insights.length === 0) {
    insights.push({
      id: 'aligned',
      tone: 'green',
      icon: 'fe fe-check-circle',
      title: `${leaveTypes.length} types · ${policies.length} policies`,
      copy: 'Leave configuration is aligned for your team.',
    });
  }
  return insights.slice(0, 3);
}

class LeavePolicyPage extends Component {
  constructor() {
    super();
    this.state = {
      permission: accessUtils.getLeaveAccessControl(),
      moduleEnabled: shouldUseLeaveManagement(),
      leaveTypes: [],
      policies: [],
      loading: true,
      saving: false,
      editType: null,
      editPolicy: null,
      typeForm: { code: '', name: '', description: '', active: true },
      policyForm: { name: '', description: '', active: true, policyConfig: '{}' },
      error: null,
      accrualSource: null,
      accrualSourceLoading: false,
      leaveUserTeams: null,
    };
  }

  getLeaveUserTeams = () => {
    if (this.state.leaveUserTeams && this.state.leaveUserTeams.length) {
      return this.state.leaveUserTeams;
    }
    return commonUtils.getUserTeams(this.props.userTeams);
  };

  leaveTeamMenuPermission = () => {
    const leave = this.state.permission || accessUtils.getLeaveAccessControl() || {};
    const teams = this.getLeaveUserTeams() || [];
    return {
      ...leave,
      switchUserTeamsEnabled: leave.switchUserTeamsEnabled === true || teams.length > 1,
    };
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler(this.props.routeProp.name);
    const leaveUserTeams = buildLeaveUserTeamsAllSelected(this.props.userTeams);
    store.dispatch({
      type: employeeConstants.INITIALIZE_EMPLOYEE_ATTENDANCE_USER_TEAMS,
      userTeams: leaveUserTeams,
    });
    this.handleLeaveConfigChanged = () => {
      this.setState(
        {
          permission: accessUtils.getLeaveAccessControl(),
          moduleEnabled: shouldUseLeaveManagement(),
        },
        () => this.loadAll()
      );
    };
    window.addEventListener(LEAVE_CONFIG_CHANGED, this.handleLeaveConfigChanged);
    this.setState({ leaveUserTeams }, () => {
      loadLeaveConfig().then(() => {
        this.setState(
          {
            permission: accessUtils.getLeaveAccessControl(),
            moduleEnabled: shouldUseLeaveManagement(),
          },
          () => this.loadAll()
        );
      });
    });
  }

  componentWillUnmount() {
    window.removeEventListener(LEAVE_CONFIG_CHANGED, this.handleLeaveConfigChanged);
  }

  resolveTeamIds = () => resolveLeaveUserTeamIds(this.getLeaveUserTeams());
  userTeamId = () => resolveLeaveWriteUserTeamId(this.getLeaveUserTeams());

  loadAll = () => {
    const teamIds = this.resolveTeamIds();
    const writeTeamId = this.userTeamId();
    if (!this.state.moduleEnabled || !teamIds.length) {
      this.setState({ loading: false, leaveTypes: [], policies: [], accrualSource: null });
      return;
    }
    this.setState({ loading: true, error: null, accrualSourceLoading: true });
    Promise.all([
      leaveService.listLeaveTypes(teamIds),
      leaveService.listLeavePolicies(teamIds),
      Promise.all(teamIds.map((id) => globalLeaveApi.accrualSource(id).catch(() => null))).then((sources) => {
        const published = sources.find((s) => s && String(s.source || '').toUpperCase() === 'GLOBAL');
        return published || sources.find(Boolean) || null;
      }),
    ]).then(
      ([typesRes, policiesRes, accrualSource]) => {
        this.setState({
          leaveTypes: (typesRes && typesRes.payload) || [],
          policies: (policiesRes && policiesRes.payload) || [],
          accrualSource: accrualSource || null,
          accrualSourceLoading: false,
          loading: false,
        });
      },
      (err) => {
        this.setState({
          loading: false,
          accrualSourceLoading: false,
          error: (err && err.message) || 'Failed to load leave configuration',
        });
      }
    );
  };

  entitlementsLocked = () => {
    const { accrualSource } = this.state;
    return !!(accrualSource
      && (accrualSource.classicEntitlementsLocked === true
        || String(accrualSource.source || '').toUpperCase() === 'GLOBAL'));
  };

  openNewType = () => {
    this.setState({
      editType: 'new',
      typeForm: { code: 'AL', name: 'Annual Leave', description: '', active: true },
    });
  };

  openEditType = (type) => {
    this.setState({
      editType: type.id,
      typeForm: {
        code: type.code || '',
        name: type.name || '',
        description: type.description || '',
        active: type.active !== false,
      },
    });
  };

  saveType = () => {
    const userTeamId = this.userTeamId();
    const actorId = commonUtils.getCurrentUserId();
    const { editType, typeForm } = this.state;
    if (!userTeamId || !typeForm.code) return;

    this.setState({ saving: true });
    const payload = {
      userTeamId,
      actorId,
      code: typeForm.code.trim().toUpperCase(),
      name: typeForm.name.trim(),
      description: typeForm.description.trim() || null,
      active: typeForm.active === true,
    };

    const request =
      editType === 'new'
        ? leaveService.createLeaveType(payload)
        : leaveService.updateLeaveType(editType, payload);

    request.then(
      () => {
        this.setState({ saving: false, editType: null });
        this.loadAll();
      },
      () => this.setState({ saving: false })
    );
  };

  openNewPolicy = () => {
    if (this.entitlementsLocked()) {
      this.setState({
        error: 'Classic entitlement policies are locked while a published global policy drives accrual. Edit rules in Global policies.',
      });
      return;
    }
    this.setState({
      editPolicy: 'new',
      policyForm: {
        name: '',
        description: '',
        active: true,
        policyConfig: JSON.stringify(
          {
            accruals: [
              { leaveTypeCode: 'AL', monthlyDays: 1.75 },
              { leaveTypeCode: 'SL', monthlyDays: 0.5 },
            ],
          },
          null,
          2
        ),
      },
    });
  };

  openEditPolicy = (policy) => {
    if (this.entitlementsLocked()) {
      this.setState({
        error: 'Classic entitlement policies are locked while a published global policy drives accrual. Edit rules in Global policies.',
      });
      return;
    }
    this.setState({
      editPolicy: policy.id,
      policyForm: {
        name: policy.name || '',
        description: policy.description || '',
        active: policy.active !== false,
        policyConfig: policy.policyConfig || policy.policy_config || '{}',
      },
    });
  };

  savePolicy = () => {
    const userTeamId = this.userTeamId();
    const actorId = commonUtils.getCurrentUserId();
    const { editPolicy, policyForm } = this.state;
    if (!userTeamId || !policyForm.name) return;

    try {
      if (policyForm.policyConfig) {
        JSON.parse(policyForm.policyConfig);
      }
    } catch (e) {
      this.setState({ error: 'Policy config must be valid JSON.' });
      return;
    }

    this.setState({ saving: true, error: null });
    const payload = {
      userTeamId,
      actorId,
      name: policyForm.name.trim(),
      description: policyForm.description.trim() || null,
      active: policyForm.active === true,
      policyConfig: policyForm.policyConfig || '{}',
    };

    const request =
      editPolicy === 'new'
        ? leaveService.createLeavePolicy(payload)
        : leaveService.updateLeavePolicy(editPolicy, payload);

    request.then(
      () => {
        this.setState({ saving: false, editPolicy: null });
        this.loadAll();
      },
      () => this.setState({ saving: false })
    );
  };

  renderField = (label, icon, children) => (
    <label className="lux-leave-drawer__field">
      <span className="lux-leave-drawer__label">
        {icon && <i className={`fe ${icon}`} aria-hidden="true" />}
        {label}
      </span>
      {children}
    </label>
  );

  renderStatusBadge = (active) => (
    <span className={classNames('lux-leave-status-badge', active ? 'is-approved' : 'is-draft')}>
      {active ? 'Active' : 'Inactive'}
    </span>
  );

  renderTypeDrawer = () => {
    const { editType, typeForm, saving } = this.state;
    if (!editType) return null;

    return createPortal(
      <div
        className="lux-onb-drawer-backdrop lux-leave-drawer-backdrop"
        role="presentation"
        onClick={() => this.setState({ editType: null })}
      >
        <aside
          className="lux-onb-drawer lux-leave-drawer lux-onb-drawer--warning"
          role="dialog"
          aria-modal="true"
          aria-labelledby="leave-type-drawer-title"
          onClick={(event) => event.stopPropagation()}
        >
          <header className="lux-onb-drawer__head">
            <div className="lux-onb-drawer__head-main">
              <span className="lux-onb-drawer__category-icon" aria-hidden="true">
                <i className="fe fe-layers" />
              </span>
              <div className="lux-onb-drawer__head-copy">
                <span className="lux-leave-drawer__eyebrow">Admin · Leave types</span>
                <h2 id="leave-type-drawer-title">{editType === 'new' ? 'New leave type' : 'Edit leave type'}</h2>
                <p>Codes map to ZingHR and employee leave requests.</p>
              </div>
            </div>
            <button
              type="button"
              className="lux-onb-drawer__close"
              aria-label="Close"
              onClick={() => this.setState({ editType: null })}
            >
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </header>

          <div className="lux-onb-drawer__body lux-leave-drawer__body">
            <div className="lux-leave-drawer__scroll">
              <div className="lux-leave-drawer__grid">
                {this.renderField(
                  'Code',
                  'fe-hash',
                  <select
                    className="lux-leave-drawer__input"
                    value={typeForm.code}
                    onChange={(e) => {
                      const code = e.target.value;
                      const opt = LEAVE_TYPE_OPTIONS.find((o) => o.value === code);
                      this.setState({
                        typeForm: {
                          ...typeForm,
                          code,
                          name: opt ? opt.label : typeForm.name,
                        },
                      });
                    }}
                    disabled={editType !== 'new'}
                  >
                    {LEAVE_TYPE_OPTIONS.map((o) => (
                      <option key={o.value} value={o.value}>
                        {o.value} — {o.label}
                      </option>
                    ))}
                  </select>
                )}

                {this.renderField(
                  'Name',
                  'fe-tag',
                  <input
                    className="lux-leave-drawer__input"
                    value={typeForm.name}
                    onChange={(e) => this.setState({ typeForm: { ...typeForm, name: e.target.value } })}
                  />
                )}
              </div>

              {this.renderField(
                'Description',
                'fe-align-left',
                <textarea
                  className="lux-leave-drawer__textarea"
                  rows={2}
                  value={typeForm.description}
                  onChange={(e) =>
                    this.setState({ typeForm: { ...typeForm, description: e.target.value } })
                  }
                />
              )}

              <label className="lux-leave-drawer__check">
                <input
                  type="checkbox"
                  checked={typeForm.active}
                  onChange={(e) =>
                    this.setState({ typeForm: { ...typeForm, active: e.target.checked } })
                  }
                />
                <span>Active — available for new requests</span>
              </label>
            </div>
          </div>

          <footer className="lux-onb-drawer__foot">
            <div className="lux-onb-drawer__foot-actions">
              <button
                type="button"
                className="lux-leave-drawer__btn is-ghost"
                onClick={() => this.setState({ editType: null })}
              >
                Cancel
              </button>
              <button
                type="button"
                className="lux-leave-drawer__btn is-primary"
                disabled={saving}
                onClick={this.saveType}
              >
                {saving ? 'Saving…' : 'Save type'}
              </button>
            </div>
          </footer>
        </aside>
      </div>,
      document.body
    );
  };

  renderPolicyDrawer = () => {
    const { editPolicy, policyForm, saving } = this.state;
    if (!editPolicy) return null;

    return createPortal(
      <div
        className="lux-onb-drawer-backdrop lux-leave-drawer-backdrop"
        role="presentation"
        onClick={() => this.setState({ editPolicy: null })}
      >
        <aside
          className="lux-onb-drawer lux-leave-drawer lux-onb-drawer--warning lux-leave-policy__drawer"
          role="dialog"
          aria-modal="true"
          aria-labelledby="leave-policy-drawer-title"
          onClick={(event) => event.stopPropagation()}
        >
          <header className="lux-onb-drawer__head">
            <div className="lux-onb-drawer__head-main">
              <span className="lux-onb-drawer__category-icon" aria-hidden="true">
                <i className="fe fe-sliders" />
              </span>
              <div className="lux-onb-drawer__head-copy">
                <span className="lux-leave-drawer__eyebrow">Admin · Leave policies</span>
                <h2 id="leave-policy-drawer-title">{editPolicy === 'new' ? 'New policy' : 'Edit policy'}</h2>
                <p>Entitlement rules and monthly accrual configuration.</p>
              </div>
            </div>
            <button
              type="button"
              className="lux-onb-drawer__close"
              aria-label="Close"
              onClick={() => this.setState({ editPolicy: null })}
            >
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </header>

          <div className="lux-onb-drawer__body lux-leave-drawer__body">
            <div className="lux-leave-drawer__scroll">
              <div className="lux-leave-drawer__grid">
                {this.renderField(
                  'Name',
                  'fe-book',
                  <input
                    className="lux-leave-drawer__input"
                    value={policyForm.name}
                    onChange={(e) =>
                      this.setState({ policyForm: { ...policyForm, name: e.target.value } })
                    }
                  />
                )}

                {this.renderField(
                  'Description',
                  'fe-align-left',
                  <input
                    className="lux-leave-drawer__input"
                    value={policyForm.description}
                    onChange={(e) =>
                      this.setState({ policyForm: { ...policyForm, description: e.target.value } })
                    }
                  />
                )}
              </div>

              {this.renderField(
                'Policy config (JSON)',
                'fe-code',
                <textarea
                  className="lux-leave-drawer__textarea lux-leave-policy__json"
                  rows={10}
                  value={policyForm.policyConfig}
                  onChange={(e) =>
                    this.setState({ policyForm: { ...policyForm, policyConfig: e.target.value } })
                  }
                  spellCheck={false}
                />
              )}

              <p className="lux-leave-policy__json-hint">
                Use <code>accruals[].leaveTypeCode</code> and <code>monthlyDays</code> for monthly entitlement.
              </p>

              <label className="lux-leave-drawer__check">
                <input
                  type="checkbox"
                  checked={policyForm.active}
                  onChange={(e) =>
                    this.setState({ policyForm: { ...policyForm, active: e.target.checked } })
                  }
                />
                <span>Active — policy applies to team members</span>
              </label>
            </div>
          </div>

          <footer className="lux-onb-drawer__foot">
            <div className="lux-onb-drawer__foot-actions">
              <button
                type="button"
                className="lux-leave-drawer__btn is-ghost"
                onClick={() => this.setState({ editPolicy: null })}
              >
                Cancel
              </button>
              <button
                type="button"
                className="lux-leave-drawer__btn is-primary"
                disabled={saving}
                onClick={this.savePolicy}
              >
                {saving ? 'Saving…' : 'Save policy'}
              </button>
            </div>
          </footer>
        </aside>
      </div>,
      document.body
    );
  };

  render() {
    const {
      permission,
      moduleEnabled,
      leaveTypes,
      policies,
      loading,
      editType,
      editPolicy,
      error,
    } = this.state;

    if (!permission.policyAdminEnabled) {
      return (
        <div className="lux-leave-page lux-leave-policy-page">
          <LuxRegisterEmptyState
            className="lux-register-empty--compact lux-leave-empty"
            icon="fe fe-lock"
            title="Leave policy admin not available"
            description="Your role does not include leave policy administration."
          />
        </div>
      );
    }

    const activeTypes = leaveTypes.filter((type) => type.active !== false).length;
    const activePolicies = policies.filter((policy) => policy.active !== false).length;
    const insights = loading ? [] : buildLeavePolicyPageInsights(leaveTypes, policies);
    const entitlementsLocked = this.entitlementsLocked();
    const kpiCards = [
      { id: 'types', label: 'Leave types', value: leaveTypes.length, hint: 'Codes for requests & HR sync', tone: 'amber', icon: 'fe fe-layers' },
      { id: 'active-types', label: 'Active types', value: activeTypes, hint: 'Available in dropdowns', tone: 'green', icon: 'fe fe-check-circle' },
      { id: 'policies', label: 'Policies', value: policies.length, hint: entitlementsLocked ? 'Fallback only (global published)' : 'Entitlement rule sets', tone: 'violet', icon: 'fe fe-sliders' },
      { id: 'active-policies', label: 'Active policies', value: activePolicies, hint: entitlementsLocked ? 'Not driving accrual' : 'Applied to employees', tone: 'primary', icon: 'fe fe-book-open' },
    ];

    return (
      <div className="lux-leave-page lux-leave-policy-page">
        <PageDataSourceReporter dataSource="api" />
        <LuxModuleIntro
          meta={{
            tone: 'teal',
            icon: 'fe fe-book-open',
            eyebrow: 'Admin · Leave',
            titleLead: 'Leave',
            titleAccent: 'policies',
            lede: 'Leave types and entitlement policies.',
          }}
          actions={
            <>
              {!entitlementsLocked ? (
                <PageCreateButton onClick={this.openNewPolicy}>Add policy</PageCreateButton>
              ) : null}
              <button
                type="button"
                className="lux-page-header__action-btn"
                onClick={this.openNewType}
              >
                <i className="fe fe-layers" aria-hidden="true" />
                Add type
              </button>
            </>
          }
        />
        <LeavePolicyModeSwitcher active="classic" />
        <AccrualSourceBanner
          source={this.state.accrualSource}
          loading={this.state.accrualSourceLoading}
        />
        <PageInnerHeader
          showUserTeamMenu={true}
          userTeams={this.getLeaveUserTeams()}
          handleUserTeamsSelection={(userTeams) => {
            store.dispatch({
              type: employeeConstants.INITIALIZE_EMPLOYEE_ATTENDANCE_USER_TEAMS,
              userTeams,
            });
            this.setState({ leaveUserTeams: userTeams }, () => this.loadAll());
          }}
          showFilter={false}
          isLoading={loading}
          permission={this.leaveTeamMenuPermission()}
        />

        <AdminKpiStrip cards={kpiCards} loading={loading} className="lux-leave-policy-kpi-strip" />
        <AdminInsightStrip insights={insights} />

        {!moduleEnabled ? (
          <LuxRegisterEmptyState
            className="lux-register-empty--compact lux-leave-empty"
            icon="fe fe-sliders"
            title="Native leave module is off"
            description="Enable leaveManagementEnabled under leaveAdditional in Application Configuration."
          />
        ) : (
          <>
            {error && (
              <div className="lux-leave-policy__error" role="alert">
                <i className="fe fe-alert-circle" aria-hidden="true" />
                <span>{error}</span>
                <button type="button" onClick={() => this.setState({ error: null })} aria-label="Dismiss">
                  <i className="fe fe-x" aria-hidden="true" />
                </button>
              </div>
            )}

            <section className="lux-leave-subpanel lux-leave-policy__section" aria-label="Leave types">
              <header className="lux-leave-subpanel__head">
                <div>
                  <span className="lux-leave-subpanel__eyebrow">Configuration</span>
                  <h3 className="lux-leave-subpanel__title">Leave types</h3>
                  <p className="lux-leave-subpanel__sub">
                    Codes used in requests and ZingHR mapping (AL, SL, CL, …)
                  </p>
                </div>
                <button type="button" className="lux-leave-hero__cta is-secondary" onClick={this.openNewType}>
                  <i className="fe fe-plus" aria-hidden="true" />
                  Add type
                </button>
              </header>

              {loading ? (
                <div className="lux-leave-register__skeleton" aria-busy="true" />
              ) : leaveTypes.length === 0 ? (
                <LuxRegisterEmptyState
                  className="lux-register-empty--compact lux-leave-empty"
                  icon="fe fe-layers"
                  title="No leave types yet"
                  description="Add a leave type to enable employee requests and HR sync mapping."
                />
              ) : (
                <div className="lux-leave-register-wrap">
                  <table className="lux-leave-register">
                    <thead>
                      <tr>
                        <th>Code</th>
                        <th>Name</th>
                        <th>Description</th>
                        <th>Status</th>
                        <th aria-hidden="true" />
                      </tr>
                    </thead>
                    <tbody>
                      {leaveTypes.map((type) => (
                        <tr key={type.id} className="lux-leave-register__row">
                          <td>
                            <span className="lux-leave-register__type">
                              <strong>{type.code}</strong>
                            </span>
                          </td>
                          <td>{type.name || '—'}</td>
                          <td>
                            <span className="lux-leave-policy__desc">{type.description || '—'}</span>
                          </td>
                          <td>{this.renderStatusBadge(type.active !== false)}</td>
                          <td>
                            <button
                              type="button"
                              className="lux-leave-register__action"
                              onClick={() => this.openEditType(type)}
                            >
                              Edit
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </section>

            <section className="lux-leave-subpanel lux-leave-policy__section" aria-label="Leave policies">
              <header className="lux-leave-subpanel__head">
                <div>
                  <span className="lux-leave-subpanel__eyebrow">
                    {entitlementsLocked ? 'Fallback entitlements' : 'Entitlements'}
                  </span>
                  <h3 className="lux-leave-subpanel__title">Leave policies</h3>
                  <p className="lux-leave-subpanel__sub">
                    {entitlementsLocked
                      ? 'Read-only while a published global policy drives monthly accrual.'
                      : (
                        <>
                          Monthly accrual via <code>accruals[].leaveTypeCode</code> + <code>monthlyDays</code>
                        </>
                      )}
                  </p>
                </div>
                {!entitlementsLocked && (
                  <button type="button" className="lux-leave-hero__cta is-secondary" onClick={this.openNewPolicy}>
                    <i className="fe fe-plus" aria-hidden="true" />
                    Add policy
                  </button>
                )}
              </header>

              {loading ? (
                <div className="lux-leave-register__skeleton" aria-busy="true" />
              ) : policies.length === 0 ? (
                <LuxRegisterEmptyState
                  className="lux-register-empty--compact lux-leave-empty"
                  icon="fe fe-book-open"
                  title="No policies yet"
                  description="Default types are seeded on first load. Add a policy to define entitlements."
                />
              ) : (
                <div className="lux-leave-register-wrap">
                  <table className="lux-leave-register">
                    <thead>
                      <tr>
                        <th>Name</th>
                        <th>Description</th>
                        <th>Status</th>
                        <th aria-hidden="true" />
                      </tr>
                    </thead>
                    <tbody>
                      {policies.map((policy) => (
                        <tr key={policy.id} className="lux-leave-register__row">
                          <td>
                            <span className="lux-leave-register__type">
                              <strong>{policy.name}</strong>
                            </span>
                          </td>
                          <td>
                            <span className="lux-leave-policy__desc">{policy.description || '—'}</span>
                          </td>
                          <td>{this.renderStatusBadge(policy.active !== false)}</td>
                          <td>
                            {entitlementsLocked ? (
                              <span className="lux-leave-policy__desc">Locked</span>
                            ) : (
                              <button
                                type="button"
                                className="lux-leave-register__action"
                                onClick={() => this.openEditPolicy(policy)}
                              >
                                Edit
                              </button>
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </section>
          </>
        )}

        {editType && this.renderTypeDrawer()}
        {editPolicy && this.renderPolicyDrawer()}
      </div>
    );
  }
}

function mapStateToProps(state) {
  return {
    userTeams: state.employees && (state.employees.userTeamsA || state.employees.userTeams),
  };
}

export default connect(mapStateToProps)(LeavePolicyPage);
