import dateUtils from '_helpers/date.utils';
import moment from 'moment';

export const LEAVE_TYPE_OPTIONS = [
  { value: 'AL', label: 'Annual Leave', tone: 'annual' },
  { value: 'SL', label: 'Sick Leave', tone: 'sick' },
  { value: 'CL', label: 'Casual Leave', tone: 'casual' },
  { value: 'EL', label: 'Earned Leave', tone: 'annual' },
  { value: 'UL', label: 'Unpaid Leave', tone: 'unpaid' },
  { value: 'CO', label: 'Compensatory Off', tone: 'comp' },
  { value: 'PL', label: 'Paternity Leave', tone: 'family' },
  { value: 'MATERNITY', label: 'Maternity Leave', tone: 'family' },
  { value: 'PATERNITY', label: 'Paternity Leave', tone: 'family' },
  { value: 'FMLA', label: 'FMLA', tone: 'family' },
];

export function getLeaveTypeLabel(code, description) {
  if (description) return description;
  const match = LEAVE_TYPE_OPTIONS.find((o) => o.value === code);
  return match ? match.label : code || 'Leave';
}

export function hasLeaveDelegationScope(approvalTypes) {
  if (!approvalTypes || !approvalTypes.length) return false;
  return approvalTypes.some((type) => {
    const normalized = String(type).toUpperCase();
    return normalized === 'LEAVE' || normalized === 'BOTH';
  });
}

/** Manager leave approver OR active LEAVE-scoped delegate. */
export function isLeaveApprovalActor(permission, actingDelegations) {
  if (permission && permission.approveTeamEnabled === true) return true;
  if (!permission || permission.approvalDelegationEnabled !== true) return false;
  if (!actingDelegations || !actingDelegations.length) return false;
  return actingDelegations.some(
    (delegation) =>
      delegation &&
      delegation.active !== false &&
      hasLeaveDelegationScope(delegation.approvalTypes)
  );
}

export function getWorkflowStatusMeta(leave) {
  const status = String(
    (leave && (leave.workflowStatus || leave.workflow_status)) || ''
  ).toUpperCase();
  const zinghrStatus = leave && leave.status;

  if (status === 'SUBMITTED') {
    return { label: 'Pending approval', tone: 'pending', code: 'SUBMITTED' };
  }
  if (status === 'APPROVED' || zinghrStatus === 'Final Acceptance') {
    return { label: 'Approved', tone: 'approved', code: 'APPROVED' };
  }
  if (status === 'REJECTED') {
    return { label: 'Rejected', tone: 'rejected', code: 'REJECTED' };
  }
  if (status === 'CREATED') {
    return { label: 'Draft', tone: 'draft', code: 'CREATED' };
  }
  if (status === 'WITHDRAWN') {
    return { label: 'Withdrawn', tone: 'muted', code: 'WITHDRAWN' };
  }
  if (status === 'CANCELLED') {
    return { label: 'Cancelled', tone: 'muted', code: 'CANCELLED' };
  }
  if (status === 'SYNCED') {
    return { label: 'Synced (HR)', tone: 'synced', code: 'SYNCED' };
  }
  if (zinghrStatus === 'Cancelled' || zinghrStatus === 'Final Cancel Request Acceptance') {
    return { label: 'Cancelled (HR)', tone: 'muted', code: 'CANCELLED' };
  }
  return { label: status || 'Unknown', tone: 'muted', code: status };
}

export function getSourceMeta(leave) {
  const source = String((leave && leave.source) || '').toUpperCase();
  if (source === 'ZINGHR') {
    return { label: 'ZingHR', tone: 'zinghr' };
  }
  if (source === 'NATIVE') {
    return { label: 'Tracopus', tone: 'native' };
  }
  return { label: source || '—', tone: 'muted' };
}

export function getPromotionStatusMeta(leave) {
  const promo = String(
    (leave && (leave.promotionStatus || leave.promotion_status)) || ''
  ).toUpperCase();
  const synced = leave && (leave.sync === true || leave.is_sync === true);

  if (promo === 'FAILED') {
    return {
      label: 'Sync failed',
      tone: 'failed',
      canRetry: true,
      hint: leave.promotionLastError || leave.promotion_last_error,
    };
  }
  if (promo === 'PENDING' || (promo === '' && !synced && isApprovedLeave(leave))) {
    return { label: 'Syncing…', tone: 'pending', canRetry: false };
  }
  if (promo === 'SUCCESS' || synced) {
    return { label: 'Work items synced', tone: 'success', canRetry: false };
  }
  return { label: '—', tone: 'muted', canRetry: false };
}

export function isApprovedLeave(leave) {
  const meta = getWorkflowStatusMeta(leave);
  return meta.code === 'APPROVED' || meta.code === 'SYNCED';
}

export function isPendingLeave(leave) {
  return getWorkflowStatusMeta(leave).code === 'SUBMITTED';
}

export function isDraftLeave(leave) {
  return getWorkflowStatusMeta(leave).code === 'CREATED';
}

export function parseLeaveDate(value) {
  if (!value) return null;
  if (moment.isMoment(value)) return value;
  const formats = ['DD-MM-YYYY', 'YYYY-MM-DD', dateUtils.SERVER_DATE_FORMAT];
  for (let i = 0; i < formats.length; i += 1) {
    const m = moment(value, formats[i], true);
    if (m.isValid()) return m;
  }
  return dateUtils.convertDateToMoment(value);
}

export function formatLeaveDateRange(leave) {
  const from = parseLeaveDate(leave.applicationFromDate || leave.application_from_date);
  const to = parseLeaveDate(leave.applicationToDate || leave.application_to_date);
  if (from && to && from.isValid() && to.isValid()) {
    if (from.isSame(to, 'day')) {
      return from.format('D MMM YYYY');
    }
    return `${from.format('D MMM')} – ${to.format('D MMM YYYY')}`;
  }
  return '—';
}

export function formatLeaveDays(leave) {
  const days = leave.numberOfDays || leave.number_of_days;
  if (days == null || days === '') return '—';
  const n = parseFloat(days);
  if (Number.isNaN(n)) return String(days);
  return n === 1 ? '1 day' : `${n} days`;
}

export function buildLeaveSummary(leaves) {
  const list = leaves || [];
  let pending = 0;
  let approved = 0;
  let rejected = 0;
  let synced = 0;
  let failedPromotion = 0;
  let totalDaysApproved = 0;

  list.forEach((leave) => {
    const meta = getWorkflowStatusMeta(leave);
    if (meta.code === 'SUBMITTED') pending += 1;
    if (meta.code === 'APPROVED' || meta.code === 'SYNCED') {
      approved += 1;
      const d = parseFloat(leave.numberOfDays || leave.number_of_days);
      if (!Number.isNaN(d)) totalDaysApproved += d;
    }
    if (meta.code === 'REJECTED') rejected += 1;
    if (meta.code === 'SYNCED') synced += 1;
    if (getPromotionStatusMeta(leave).tone === 'failed') failedPromotion += 1;
  });

  return {
    total: list.length,
    pending,
    approved,
    rejected,
    synced,
    failedPromotion,
    totalDaysApproved: Math.round(totalDaysApproved * 10) / 10,
  };
}

function toNumber(value) {
  if (value == null || value === '') return 0;
  const n = parseFloat(value);
  return Number.isNaN(n) ? 0 : n;
}

export function buildBalanceCardsFromApi(balances, leaveTypes) {
  const typeById = {};
  (leaveTypes || []).forEach((type) => {
    typeById[type.id] = type;
  });

  const cards = (balances || []).map((row) => {
    const type = typeById[row.leaveTypeId || row.leave_type_id];
    const code = (type && type.code) || 'OTHER';
    const label = getLeaveTypeLabel(code, type && type.name);
    const entitlement = toNumber(row.entitlement);
    const used = toNumber(row.used);
    const pending = toNumber(row.pending);
    const balance = toNumber(row.balance);
    const available = Math.round((balance - pending) * 10) / 10;
    const hasEntitlement = entitlement > 0 || balance !== 0 || used > 0 || pending > 0;
    return {
      code,
      label,
      leaveTypeId: row.leaveTypeId || row.leave_type_id,
      entitlement,
      usedDays: Math.round(used * 10) / 10,
      pending,
      balance: Math.round(balance * 10) / 10,
      available,
      requests: null,
      hasEntitlement,
      remainingLabel: hasEntitlement
        ? pending > 0
          ? `${available} available · ${pending} pending approval`
          : `${Math.round(balance * 10) / 10} days remaining`
        : 'No entitlement configured',
    };
  });

  return cards.sort((a, b) => b.usedDays - a.usedDays);
}

export function mergeBalanceCards(apiCards, historyCards) {
  if (apiCards && apiCards.length > 0) {
    return apiCards;
  }
  return historyCards || [];
}

export function buildBalanceCardsFromLeaves(leaves) {
  const byType = {};
  (leaves || []).forEach((leave) => {
    if (!isApprovedLeave(leave)) return;
    const code = leave.leaveTypeCode || leave.leave_type_code || 'OTHER';
    const label = getLeaveTypeLabel(code, leave.leaveTypeDescription);
    if (!byType[code]) {
      byType[code] = { code, label, usedDays: 0, requests: 0 };
    }
    const d = parseFloat(leave.numberOfDays || leave.number_of_days);
    byType[code].usedDays += Number.isNaN(d) ? 0 : d;
    byType[code].requests += 1;
  });

  return Object.values(byType)
    .sort((a, b) => b.usedDays - a.usedDays)
    .map((row) => ({
      ...row,
      usedDays: Math.round(row.usedDays * 10) / 10,
      remainingLabel: 'Policy balance — configure in HR',
    }));
}

export function summarizePendingLeaves(pending) {
  const list = pending || [];
  const byEmployee = {};
  list.forEach((leave) => {
    const eid = leave.employeeId || leave.employee_id;
    if (!byEmployee[eid]) {
      byEmployee[eid] = {
        employeeId: eid,
        employeeName: leave.employeeName || `Employee ${eid}`,
        items: [],
      };
    }
    byEmployee[eid].items.push(leave);
  });
  const groups = Object.values(byEmployee);
  return {
    total: list.length,
    employeeCount: groups.length,
    groups,
  };
}

export function buildLeaveCreatePayload(form, employee) {
  return {
    employeeId: employee.id,
    userTeamId: employee.userTeamId,
    actorId: employee.id,
    leaveTypeCode: form.leaveTypeCode,
    leaveTypeDescription: getLeaveTypeLabel(form.leaveTypeCode),
    applicationFromDate: form.fromDate,
    applicationToDate: form.toDate,
    numberOfDays: String(form.numberOfDays || 1),
    reason: form.reason ? form.reason.trim() : '',
    remarks: form.remarks ? form.remarks.trim() : null,
    halfDay: form.halfDay === true,
    halfDaySession: form.halfDay ? form.halfDaySession : null,
  };
}

export function findCurrentUserEmployee(employees, currentUserId) {
  const list = employees || [];
  if (currentUserId == null || currentUserId === "") return null;
  const id = String(currentUserId);
  return (
    list.find((emp) => String(emp.id) === id)
    || list.find((emp) => emp.userId != null && String(emp.userId) === id)
    || list.find((emp) => emp.userAccessId != null && String(emp.userAccessId) === id)
    || null
  );
}

/**
 * Explains why Apply leave is hidden/disabled on Leave management.
 * Apply requires: module on + leaves.createEnabled + resolved employee.
 */
export function getLeaveApplyGate({ moduleEnabled, createEnabled, employee, employees }) {
  if (!moduleEnabled) {
    return {
      canApply: false,
      code: "MODULE_OFF",
      title: "Apply leave is unavailable",
      message:
        "Native leave management is off for this team. Enable leaveManagementEnabled under leaveAdditional in Application Configuration, then refresh.",
    };
  }
  if (!createEnabled) {
    return {
      canApply: false,
      code: "NO_CREATE_PERMISSION",
      title: "Apply leave is unavailable",
      message:
        "Your role cannot create leave requests. Ask an admin to enable leaves.createEnabled for your role, then sign out and back in.",
    };
  }
  if (!employee) {
    const hasEmployees = Array.isArray(employees) && employees.length > 0;
    return {
      canApply: false,
      code: hasEmployees ? "NO_EMPLOYEE_SELECTED" : "NO_EMPLOYEES",
      title: "Apply leave is unavailable",
      message: hasEmployees
        ? "Select an employee in the header filter to apply leave for that person."
        : "No employees loaded for the selected team. Check the team filter above, or confirm your user is linked to an employee record.",
    };
  }
  return {
    canApply: true,
    code: "OK",
    title: null,
    message: null,
  };
}

export function groupLeavesForCalendar(leaves, employeesById) {
  const rows = (leaves || []).map((leave) => {
    const employeeId = leave.employeeId || leave.employee_id;
    const employee = employeesById && employeesById[employeeId];
    return {
      id: leave.id,
      employeeId,
      employeeName:
        (employee && employee.name) || leave.employeeName || `Employee ${employeeId}`,
      leaveTypeCode: leave.leaveTypeCode || leave.leave_type_code,
      leaveTypeDescription: leave.leaveTypeDescription || leave.leave_type_description,
      fromDate: leave.applicationFromDate || leave.application_from_date,
      toDate: leave.applicationToDate || leave.application_to_date,
      days: leave.numberOfDays || leave.number_of_days,
      halfDay: leave.halfDay === true || leave.half_day === true,
      statusMeta: getWorkflowStatusMeta(leave),
      dateLabel: formatLeaveDateRange(leave),
    };
  });
  return rows.sort((a, b) => {
    const da = parseLeaveDate(a.fromDate);
    const db = parseLeaveDate(b.fromDate);
    if (!da || !db) return 0;
    return da.valueOf() - db.valueOf();
  });
}

export function computeWorkingDaysBetween(fromMoment, toMoment, halfDay, holidayDates, workdays) {
  if (!fromMoment || !toMoment || !fromMoment.isValid() || !toMoment.isValid()) {
    return 1;
  }
  const { fullDays, halfDays } = partitionHolidayDaySets(holidayDates);
  const workdaySet = normalizeWorkdayIsoSet(workdays);
  let days = 0;
  const cursor = fromMoment.clone().startOf('day');
  const end = toMoment.clone().startOf('day');
  while (cursor.isSameOrBefore(end, 'day')) {
    const isoDow = cursor.isoWeekday(); // 1=Mon … 7=Sun
    const key = cursor.format('YYYY-MM-DD');
    if (workdaySet.has(isoDow) && !fullDays.has(key)) {
      days += halfDays.has(key) ? 0.5 : 1;
    }
    cursor.add(1, 'day');
  }
  if (halfDay && fromMoment.isSame(toMoment, 'day')) {
    return days > 0 ? 0.5 : 0;
  }
  // Legacy fallback when holiday set was not supplied (pre-holiday-aware callers).
  if (days === 0 && holidayDates == null) {
    return 1;
  }
  return days;
}

/** Split holiday rows into full-day vs half-day (description contains half-day). */
export function partitionHolidayDaySets(holidayDates) {
  const fullDays = new Set();
  const halfDays = new Set();
  if (holidayDates == null) {
    return { fullDays, halfDays };
  }
  const list = holidayDates instanceof Set ? Array.from(holidayDates) : holidayDates;
  if (!Array.isArray(list) && !(holidayDates instanceof Set)) {
    return { fullDays, halfDays };
  }
  list.forEach((item) => {
    if (item == null) return;
    let key = null;
    let half = false;
    if (typeof item === 'string') {
      const trimmed = item.trim();
      if (/^\d{4}-\d{2}-\d{2}/.test(trimmed)) key = trimmed.slice(0, 10);
      else if (/^\d{2}-\d{2}-\d{4}/.test(trimmed)) {
        const [dd, mm, yyyy] = trimmed.slice(0, 10).split('-');
        key = `${yyyy}-${mm}-${dd}`;
      }
    } else if (typeof item === 'object') {
      const raw = item.holidayDate || item.date || item.observedDate;
      if (typeof raw === 'string' && /^\d{4}-\d{2}-\d{2}/.test(raw)) {
        key = raw.slice(0, 10);
      } else {
        const m = parseLeaveDate(raw);
        if (m && m.isValid()) key = m.format('YYYY-MM-DD');
      }
      const desc = String(item.description || item.desc || '').toLowerCase();
      half = item.halfDay === true || item.half_day === true || desc.includes('half-day');
    }
    if (!key) return;
    if (half) halfDays.add(key);
    else fullDays.add(key);
  });
  halfDays.forEach((d) => {
    if (fullDays.has(d)) halfDays.delete(d);
  });
  return { fullDays, halfDays };
}

/** ISO workdays 1=Mon … 7=Sun. Default Mon–Fri when unset. */
export function normalizeWorkdayIsoSet(workdays) {
  const defaults = new Set([1, 2, 3, 4, 5]);
  if (workdays == null) return defaults;
  const list = Array.isArray(workdays)
    ? workdays
    : typeof workdays === 'string'
      ? workdays.split(',')
      : workdays instanceof Set
        ? Array.from(workdays)
        : [];
  const out = new Set();
  list.forEach((raw) => {
    const n = Number(raw);
    if (Number.isInteger(n) && n >= 1 && n <= 7) out.add(n);
  });
  return out.size ? out : defaults;
}

export function isConfiguredWeekend(momentOrDay, workdays) {
  const workdaySet = normalizeWorkdayIsoSet(workdays);
  const iso =
    momentOrDay && typeof momentOrDay.isoWeekday === 'function'
      ? momentOrDay.isoWeekday()
      : Number(momentOrDay);
  return !workdaySet.has(iso);
}

/** Accepts Set/Array of YYYY-MM-DD strings, Date/moment-like values, or holiday API rows. */
export function normalizeHolidayDateSet(holidayDates) {
  const out = new Set();
  if (holidayDates == null) return out;
  const list = holidayDates instanceof Set ? Array.from(holidayDates) : holidayDates;
  if (!Array.isArray(list) && !(holidayDates instanceof Set)) {
    return out;
  }
  list.forEach((item) => {
    if (item == null) return;
    if (typeof item === 'string') {
      const trimmed = item.trim();
      if (/^\d{4}-\d{2}-\d{2}/.test(trimmed)) {
        out.add(trimmed.slice(0, 10));
        return;
      }
      if (/^\d{2}-\d{2}-\d{4}/.test(trimmed)) {
        const [dd, mm, yyyy] = trimmed.slice(0, 10).split('-');
        out.add(`${yyyy}-${mm}-${dd}`);
        return;
      }
      return;
    }
    if (typeof item === 'object') {
      const raw = item.holidayDate || item.date || item.observedDate;
      if (raw == null) return;
      if (typeof raw === 'string' && /^\d{4}-\d{2}-\d{2}/.test(raw)) {
        out.add(raw.slice(0, 10));
        return;
      }
      const m = parseLeaveDate(raw);
      if (m && m.isValid()) out.add(m.format('YYYY-MM-DD'));
    }
  });
  return out;
}
