import React from "react";
import classNames from "classnames/bind";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import ApprovalActingForBadge from "views/hrms/components/delegation/ApprovalActingForBadge";
import UniversalApprovalStatusBadge from "./UniversalApprovalStatusBadge";
import UniversalApprovalSlaBadge from "./UniversalApprovalSlaBadge";

function getInitials(name = "") {
  return String(name || "")
    .split(/[\s·]+/)
    .filter(Boolean)
    .map((part) => part[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();
}

function getRequesterParts(item) {
  const meta = (item && item.metadata) || {};
  const name =
    (meta.employeeName && String(meta.employeeName).trim()) ||
    String((item && item.requester) || "")
      .split(" · ")[0]
      .trim() ||
    "Unknown";
  const metaLine = [
    meta.empCode ? `Code ${meta.empCode}` : null,
    meta.employeeId != null ? `ID ${meta.employeeId}` : null,
  ]
    .filter(Boolean)
    .join(" · ");
  return { name, metaLine };
}

function UniversalApprovalRegister({ items, loading, onSelect, onClearFilters }) {
  if (loading) {
    return <div className="lux-appr-register__skeleton" aria-busy="true" role="status" />;
  }

  if (!items.length) {
    return (
      <LuxRegisterEmptyState
        className="lux-register-empty--compact lux-appr-empty"
        icon="fe fe-inbox"
        title="Inbox clear"
        description="No approvals match your filters. Try broadening status or domain, or check back when new requests arrive."
        showSecondary={typeof onClearFilters === "function"}
        secondaryLabel="Reset to pending"
        secondaryIcon="fe fe-rotate-ccw"
        onSecondary={onClearFilters}
      />
    );
  }

  return (
    <div className="lux-appr-register-wrap">
      <table className="lux-appr-register">
        <thead>
          <tr>
            <th>Request</th>
            <th>Domain</th>
            <th>Priority</th>
            <th>Due</th>
            <th>Status</th>
            <th aria-hidden="true" />
          </tr>
        </thead>
        <tbody>
          {items.map((item) => {
            const requesterParts = getRequesterParts(item);
            return (
            <tr
              key={item.id}
              className={classNames("lux-appr-register__row", {
                "is-high": item.priority === "HIGH",
                "is-delegate": item.actingAsDelegate,
              })}
              onClick={() => onSelect(item)}
              onKeyDown={(event) => {
                if (event.key === "Enter" || event.key === " ") {
                  event.preventDefault();
                  onSelect(item);
                }
              }}
              tabIndex={0}
              role="button"
              aria-label={`Review ${item.subject}`}
            >
              <td>
                <div className="lux-appr-register__request">
                  <span
                    className={classNames(
                      "lux-appr-register__avatar",
                      item.moduleTone && `is-${item.moduleTone}`
                    )}
                    aria-hidden="true"
                  >
                    {getInitials(requesterParts.name)}
                  </span>
                  <span className="lux-appr-register__request-copy">
                    <strong>{requesterParts.name}</strong>
                    {requesterParts.metaLine ? (
                      <em className="lux-appr-register__requester-meta">{requesterParts.metaLine}</em>
                    ) : null}
                    <span>{item.subject}</span>
                    {item.actingAsDelegate && (
                      <ApprovalActingForBadge
                        record={item}
                        className="lux-appr-register__delegate"
                      />
                    )}
                  </span>
                </div>
              </td>
              <td>
                <span className="lux-appr-register__domain">
                  <i className={item.domainIcon} aria-hidden="true" />
                  <span>
                    <strong>{item.domainLabel}</strong>
                    <em>{item.module}</em>
                  </span>
                </span>
              </td>
              <td>
                <UniversalApprovalStatusBadge variant="priority" priority={item.priority} />
              </td>
              <td>
                <div className="lux-appr-register__due-cell">
                  <span className="lux-appr-register__due">{item.dueLabel || "—"}</span>
                  <UniversalApprovalSlaBadge item={item} />
                </div>
              </td>
              <td>
                <UniversalApprovalStatusBadge status={item.status} />
              </td>
              <td>
                <span className="lux-appr-register__open" aria-hidden="true">
                  <i className="fe fe-chevron-right" />
                </span>
              </td>
            </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

export default UniversalApprovalRegister;
