import React, { PureComponent } from "react";
import classNames from "classnames/bind";

class UserTeamDirectoryRow extends PureComponent {
  render() {
    const { item, parentItem, onSelect, onOpenDetail, hierarchyEnabled } = this.props;

    if (!item || !parentItem) return null;

    const canDrill = hierarchyEnabled !== false;
    const nodeCount = item.nodes && item.nodes.length ? item.nodes.length : null;

    return (
      <article
        className={classNames("lux-acct-dir-row", "lux-acct-dir-row--user-team", {
          "is-drillable": canDrill,
        })}
      >
        <div className="lux-acct-dir-row__avatar is-violet">
          <i className="fe fe-users" aria-hidden="true" />
        </div>

        <div className="lux-acct-dir-row__main">
          <div className="lux-acct-dir-row__title-row">
            {canDrill ? (
              <button type="button" className="lux-acct-dir-row__title" onClick={onSelect}>
                {item.name}
                <i className="fe fe-chevrons-right lux-acct-dir-row__drill-icon" aria-hidden="true" />
              </button>
            ) : (
              <h3 className="lux-acct-dir-row__title is-static">{item.name}</h3>
            )}
            <span className="lux-acct-dir-row__type-badge is-violet">User team</span>
            <span className="lux-acct-dir-row__id">#{item.id}</span>
          </div>

          <p className="lux-acct-dir-row__parent">
            <i className="fe fe-layers" aria-hidden="true" />
            Group <strong>{parentItem.name}</strong>
          </p>

          <p className="lux-acct-dir-row__desc lux-acct-dir-row__desc--hint">
            Open to browse accounts, then add teams and clients in the hierarchy.
          </p>

          <div className="lux-acct-dir-row__chips">
            <span className="lux-acct-dir-row__chip is-violet">
              <i className="fe fe-git-branch" aria-hidden="true" />
              Account hierarchy
            </span>
            {nodeCount != null && (
              <span className="lux-acct-dir-row__chip is-slate">
                <i className="fe fe-grid" aria-hidden="true" />
                {nodeCount} nodes
              </span>
            )}
          </div>
        </div>

        <div className="lux-acct-dir-row__metrics" aria-label="Hierarchy entry">
          <div className="lux-acct-dir-row__metric lux-acct-dir-row__metric--solo">
            <i className="fe fe-layers" aria-hidden="true" />
            <span>Accounts</span>
          </div>
        </div>

        <div className="lux-acct-dir-row__actions lux-project-row__actions">
          <button
            type="button"
            className="lux-project-row__action"
            onClick={onOpenDetail}
            title="Quick details"
            aria-label={`View details for ${item.name}`}
          >
            <i className="fe fe-eye" aria-hidden="true" />
          </button>
          {canDrill && (
            <button
              type="button"
              className="lux-project-row__action lux-project-row__action--primary"
              onClick={onSelect}
              title="Browse accounts"
              aria-label={`Browse accounts for ${item.name}`}
            >
              <i className="fe fe-chevrons-right" aria-hidden="true" />
            </button>
          )}
        </div>
      </article>
    );
  }
}

export default UserTeamDirectoryRow;
