import React from "react";
import { getPathAccessDenialReason } from "config/persona-route.utils";
import { getModuleEmptyReason } from "config/module-route.utils";
import { usePersonaContext } from "hooks/usePersonaContext";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import ModuleEmptyState from "components/navigation/ModuleEmptyState";

function normalizePersona(persona) {
  const code = String(persona || "").trim().toUpperCase();
  return code === "HR_MANAGER" ? "HR_ADMIN" : code;
}

function getRoutePropDenial(routeProp, activePersona) {
  const personas = routeProp && routeProp.personas;
  if (!Array.isArray(personas) || personas.length === 0 || !activePersona) {
    return null;
  }
  const active = normalizePersona(activePersona);
  const allowed = personas.map(normalizePersona);
  if (allowed.includes(active)) {
    return null;
  }
  return {
    path: routeProp.layout ? `${routeProp.layout}${routeProp.path}` : routeProp.path,
    pageName: routeProp.name || "this page",
    moduleName: routeProp.layout ? routeProp.layout.replace("/", "") : "module",
    requiredPersonas: personas,
  };
}

/**
 * P00-T8: Wraps a route component with persona path guard.
 */
function PersonaGuardedRoute({
  component: Component,
  routeProp,
  pageHeaderNameChangeHandler,
  ...routeProps
}) {
  const { activePersona, menuAccessControl, isLoading } = usePersonaContext();
  const pathname = routeProps.location && routeProps.location.pathname;

  if (isLoading) {
    return (
      <div className="lux-persona-loading" aria-busy="true" aria-label="Loading workspace view">
        <div className="lux-persona-loading__pulse" />
      </div>
    );
  }

  const routePropDenial = getRoutePropDenial(routeProp, activePersona);
  if (routePropDenial) {
    return <PersonaAccessDenied denial={routePropDenial} />;
  }

  const denial = getPathAccessDenialReason(pathname, activePersona, menuAccessControl);
  if (denial) {
    return <PersonaAccessDenied denial={denial} />;
  }

  const moduleEmpty = getModuleEmptyReason(pathname, menuAccessControl, activePersona);
  if (moduleEmpty) {
    return (
      <ModuleEmptyState
        moduleId={moduleEmpty.moduleId}
        moduleName={moduleEmpty.moduleName}
        pathname={moduleEmpty.pathname}
      />
    );
  }

  return (
    <Component
      {...routeProps}
      routeProp={routeProp}
      pageHeaderNameChangeHandler={pageHeaderNameChangeHandler}
    />
  );
}

export default PersonaGuardedRoute;
