/**
 * F20-T7 — Compliance pack export service.
 */
import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";
import envconfig from "env.config";
import { recordAuditEvent } from "config/audit-write.service";
import { AUDIT_ACTION_TYPES, AUDIT_ENTITY_TYPES } from "_constants/audit.constants";
import { apiErrorResult } from "config/mock-fallback.utils";
import {
  assembleCompliancePackManifest,
  downloadCompliancePackJson,
} from "config/compliance-pack.utils";

export const compliancePackService = {
  listSections,
  exportPack,
};

const API_BASE = `${urlConfig.APPCONFIG_API_PATH}/compliance-packs`;

function teamQuery(extra) {
  const query = { userTeamId: commonUtils.getCurrentUserTeamId() };
  if (extra) {
    Object.keys(extra).forEach((key) => {
      if (extra[key] != null && extra[key] !== "") {
        query[key] = extra[key];
      }
    });
  }
  return query;
}

async function listSections() {
  if (envconfig.USE_COMPLIANCE_EXPORT_ADMIN_API === true) {
    try {
      const response = await axiosUtils.getWithParam(`${API_BASE}/sections`, teamQuery());
      const rows = (response && response.payload) || response || [];
      return { payload: Array.isArray(rows) ? rows : [], source: "api" };
    } catch (e) {
      // fall through
    }
  }

  return apiErrorResult(null);
}

async function exportPack(selectedIds) {
  if (envconfig.USE_COMPLIANCE_EXPORT_ADMIN_API !== true) {
    return apiErrorResult(null);
  }
  try {
    const response = await axiosUtils.post(
      `${API_BASE}/export?userTeamId=${commonUtils.getCurrentUserTeamId()}`,
      { sectionIds: selectedIds }
    );
    const result = { payload: (response && response.payload) || response, source: "api" };
    const manifest = result.payload || assembleCompliancePackManifest([], selectedIds, {});
    downloadCompliancePackJson(manifest);

    recordAuditEvent({
      actionType: AUDIT_ACTION_TYPES.EXPORTED,
      entityType: AUDIT_ENTITY_TYPES.ADMIN_CONFIG,
      entityRef: "Compliance pack export",
      metadata: {
        sectionIds: selectedIds,
        sectionCount: (manifest.sections && manifest.sections.length) || selectedIds.length,
        exportedAt: manifest.exportedAt,
      },
    });

    return result;
  } catch (e) {
    return apiErrorResult(null);
  }
}
