import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";
import { onboardingService } from "_services/onboarding.service";
import {
  getTemplateCategories,
  getTemplateAssigneeTypes,
  createEmptyTemplateTask,
  buildLifecycleTemplatePayload,
} from "config/onboarding-template.utils";
import LifecycleActionLink from "./LifecycleActionLink";

const DRAWER_CLOSE_MS = 280;

const COPY = {
  onboarding: {
    drawerTone: "primary",
    icon: "fe-layers",
    title: "Create onboarding template",
    subtitle: "Build a reusable playbook HR can spawn for each new hire.",
    intro:
      "Templates define the default checklist copied into onboarding cases. Add at least one task with a title; required steps block case completion until done.",
    namePlaceholder: "Engineering · US full-time",
    descriptionPlaceholder: "Standard onboarding for US engineering hires",
    taskPlaceholder: "Collect signed offer letter",
    tasksHint: "Each row becomes a task on new onboarding cases.",
    selfServiceLabel: "Self-service",
    footHint: "Saved templates appear in the catalog and can be used to start onboarding cases.",
    saveTemplate: (payload) => onboardingService.createOnboardingTemplate(payload),
  },
  offboarding: {
    drawerTone: "warning",
    icon: "fe-user-x",
    title: "Create exit template",
    subtitle: "Build a reusable exit checklist for separations and last-day coordination.",
    intro:
      "Templates define access revocation, asset return, settlement, and handover tasks copied into exit cases. Required steps can block final settlement.",
    namePlaceholder: "Engineering · US exit",
    descriptionPlaceholder: "Standard exit checklist for US engineering separations",
    taskPlaceholder: "Revoke VPN and SSO access",
    tasksHint: "Each row becomes a task on new offboarding cases.",
    selfServiceLabel: "Employee task",
    footHint: "Saved templates appear in the catalog and can be used to start exit cases.",
    saveTemplate: (payload) => onboardingService.createOffboardingTemplate(payload),
  },
};

function getCategoryMeta(categoryId, lifecycle) {
  const categories = getTemplateCategories(lifecycle);
  return (
    categories.find((item) => item.id === categoryId) || {
      id: categoryId,
      label: categoryId,
      icon: "fe fe-check-square",
    }
  );
}

function TemplateField({ label, icon, highlight, children, className }) {
  return (
    <label
      className={classNames("lux-onb-template-author__field", className, {
        "is-highlight": highlight,
        "is-wide": className === "is-wide",
      })}
    >
      <span>
        {icon && <i className={classNames("fe", icon)} aria-hidden="true" />}
        {label}
      </span>
      {children}
    </label>
  );
}

function FlagPill({ active, onClick, icon, label, disabled }) {
  return (
    <button
      type="button"
      className={classNames("lux-onb-template-author__pill", { "is-active": active })}
      onClick={onClick}
      disabled={disabled}
      aria-pressed={active}
    >
      <i className={classNames("fe", icon)} aria-hidden="true" />
      {label}
    </button>
  );
}

export default function CreateLifecycleTemplatePanel({
  open,
  onClose,
  onCreated,
  lifecycle = "onboarding",
}) {
  const copy = COPY[lifecycle] || COPY.onboarding;
  const categories = getTemplateCategories(lifecycle);
  const assigneeTypes = getTemplateAssigneeTypes(lifecycle);
  const isOffboarding = lifecycle === "offboarding";

  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [department, setDepartment] = useState("");
  const [roleFilter, setRoleFilter] = useState("");
  const [locationFilter, setLocationFilter] = useState("");
  const taskIdRef = useRef(0);
  const tasksEndRef = useRef(null);
  const scrollToNewTaskRef = useRef(false);

  const makeTask = useCallback(
    (sortOrder) => {
      taskIdRef.current += 1;
      return {
        ...createEmptyTemplateTask(sortOrder, lifecycle),
        _clientId: `task-${taskIdRef.current}`,
      };
    },
    [lifecycle]
  );

  const [tasks, setTasks] = useState(() => [makeTask(1)]);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState(null);
  const [closing, setClosing] = useState(false);

  const requestClose = useCallback(() => {
    setClosing(true);
    window.setTimeout(() => {
      setClosing(false);
      setError(null);
      onClose();
    }, DRAWER_CLOSE_MS);
  }, [onClose]);

  useEffect(() => {
    if (!open) {
      return;
    }
    setName("");
    setDescription("");
    setDepartment("");
    setRoleFilter("");
    setLocationFilter("");
    taskIdRef.current = 0;
    setTasks([makeTask(1)]);
    setSubmitting(false);
    setError(null);
  }, [open, lifecycle, makeTask]);

  useEffect(() => {
    if (!scrollToNewTaskRef.current) {
      return;
    }
    scrollToNewTaskRef.current = false;
    window.requestAnimationFrame(() => {
      const tasksEnd = tasksEndRef.current;
      if (tasksEnd) {
        tasksEnd.scrollIntoView({ behavior: "smooth", block: "nearest" });
      }
    });
  }, [tasks.length]);

  const titledTaskCount = useMemo(
    () => tasks.filter((task) => String(task.title || "").trim()).length,
    [tasks]
  );
  const requiredCount = useMemo(() => tasks.filter((task) => task.required).length, [tasks]);
  const selfServiceCount = useMemo(() => tasks.filter((task) => task.selfService).length, [tasks]);

  const updateTask = (index, patch) => {
    setTasks((prev) =>
      prev.map((task, taskIndex) => (taskIndex === index ? { ...task, ...patch } : task))
    );
  };

  const addTask = () => {
    scrollToNewTaskRef.current = true;
    setTasks((prev) => [...prev, makeTask(prev.length + 1)]);
  };

  const duplicateTask = (index) => {
    scrollToNewTaskRef.current = true;
    setTasks((prev) => {
      const source = prev[index];
      if (!source) {
        return prev;
      }
      const clone = {
        ...source,
        _clientId: `task-${taskIdRef.current + 1}`,
      };
      taskIdRef.current += 1;
      const next = [...prev];
      next.splice(index + 1, 0, clone);
      return next.map((task, taskIndex) => ({ ...task, sortOrder: taskIndex + 1 }));
    });
  };

  const removeTask = (index) => {
    setTasks((prev) => {
      if (prev.length <= 1) {
        return prev;
      }
      return prev
        .filter((_, taskIndex) => taskIndex !== index)
        .map((task, taskIndex) => ({ ...task, sortOrder: taskIndex + 1 }));
    });
  };

  const handleSubmit = async (event) => {
    if (event && event.preventDefault) {
      event.preventDefault();
    }
    if (!name.trim()) {
      setError("Template name is required.");
      return;
    }
    if (titledTaskCount === 0) {
      setError("Add at least one checklist task with a title.");
      return;
    }
    setSubmitting(true);
    setError(null);
    try {
      const payload = buildLifecycleTemplatePayload(
        { name, description, department, roleFilter, locationFilter, tasks },
        lifecycle
      );
      const res = await copy.saveTemplate(payload);
      if (!res.payload || !res.payload.code) {
        throw new Error("Template was not saved.");
      }
      if (onCreated) {
        await onCreated(res.payload);
      }
      requestClose();
    } catch (submitError) {
      setError(submitError.message || "Unable to save template.");
      setSubmitting(false);
    }
  };

  if (!open) {
    return null;
  }

  return createPortal(
    <div
      className={classNames("lux-onb-drawer-backdrop", { "is-closing": closing })}
      role="presentation"
      onClick={requestClose}
    >
      <aside
        className={classNames(
          "lux-onb-drawer",
          `lux-onb-drawer--${copy.drawerTone}`,
          "lux-onb-template-author",
          { "is-exit": isOffboarding, "is-closing": closing }
        )}
        role="dialog"
        aria-labelledby="lux-onb-template-author-title"
        onClick={(event) => event.stopPropagation()}
      >
        <div className="lux-onb-drawer__accent" aria-hidden="true" />

        <header className="lux-onb-drawer__head">
          <div className="lux-onb-drawer__head-main">
            <div className="lux-onb-drawer__category-icon" aria-hidden="true">
              <i className={classNames("fe", copy.icon)} />
            </div>
            <div className="lux-onb-drawer__head-copy">
              <h2 id="lux-onb-template-author-title">{copy.title}</h2>
              <p className="lux-onb-drawer__task-id">{copy.subtitle}</p>
            </div>
          </div>
          <button type="button" className="lux-onb-drawer__close" onClick={requestClose} aria-label="Close">
            <i className="fe fe-x" aria-hidden />
          </button>
        </header>

        <form className="lux-onb-drawer__body lux-onb-template-author__body" onSubmit={handleSubmit} noValidate>
          <div className="lux-onb-template-author__highlights">
            <article className="lux-onb-template-author__highlight">
              <span>Tasks with titles</span>
              <strong>
                {titledTaskCount}
                {tasks.length > titledTaskCount ? ` / ${tasks.length}` : ""}
              </strong>
            </article>
            <article className="lux-onb-template-author__highlight is-required">
              <span>Required steps</span>
              <strong>{requiredCount}</strong>
            </article>
            <article className="lux-onb-template-author__highlight is-self">
              <span>{copy.selfServiceLabel}</span>
              <strong>{selfServiceCount}</strong>
            </article>
          </div>

          {error && (
            <p className="lux-onb-template-author__error" role="alert">
              <i className="fe fe-alert-circle" aria-hidden="true" />
              {error}
            </p>
          )}

          <section className="lux-onb-template-author__card">
            <header className="lux-onb-template-author__card-head">
              <div>
                <h3>
                  <i className="fe fe-bookmark" aria-hidden="true" />
                  Template profile
                </h3>
                <p>Name and targeting rules shown when HR picks a template.</p>
              </div>
            </header>

            <TemplateField label="Template name" icon="fe-type" highlight>
              <input
                className="lux-onb-template-author__input"
                value={name}
                onChange={(event) => setName(event.target.value)}
                disabled={submitting}
                placeholder={copy.namePlaceholder}
                required
              />
            </TemplateField>

            <TemplateField label="Description" icon="fe-align-left" className="is-wide">
              <textarea
                className="lux-onb-template-author__textarea"
                value={description}
                onChange={(event) => setDescription(event.target.value)}
                disabled={submitting}
                rows={2}
                placeholder={copy.descriptionPlaceholder}
              />
            </TemplateField>

            <div className="lux-onb-template-author__grid">
              <TemplateField label="Department" icon="fe-briefcase">
                <input
                  className="lux-onb-template-author__input"
                  value={department}
                  onChange={(event) => setDepartment(event.target.value)}
                  disabled={submitting}
                  placeholder="Engineering"
                />
              </TemplateField>
              <TemplateField label="Role filter" icon="fe-user">
                <input
                  className="lux-onb-template-author__input"
                  value={roleFilter}
                  onChange={(event) => setRoleFilter(event.target.value)}
                  disabled={submitting}
                  placeholder="Software Engineer"
                />
              </TemplateField>
            </div>

            <TemplateField label="Location filter" icon="fe-map-pin" className="is-wide">
              <input
                className="lux-onb-template-author__input"
                value={locationFilter}
                onChange={(event) => setLocationFilter(event.target.value)}
                disabled={submitting}
                placeholder="US"
              />
            </TemplateField>
          </section>

          <section className="lux-onb-template-author__card is-tasks">
            <header className="lux-onb-template-author__card-head">
              <div>
                <h3>
                  <i className="fe fe-check-square" aria-hidden="true" />
                  Checklist tasks
                </h3>
                <p>{copy.tasksHint}</p>
              </div>
              <button
                type="button"
                className="lux-onb-template-author__add-btn"
                onClick={addTask}
                disabled={submitting}
              >
                <i className="fe fe-plus" aria-hidden="true" />
                Add task
              </button>
            </header>

            <ul className="lux-onb-template-author__task-list">
              {tasks.map((task, index) => {
                const categoryMeta = getCategoryMeta(task.category, lifecycle);
                const isLast = index === tasks.length - 1;
                return (
                  <li
                    key={task._clientId}
                    ref={isLast ? tasksEndRef : null}
                    className="lux-onb-template-author__task-card"
                  >
                    <div className="lux-onb-template-author__task-head">
                      <div className="lux-onb-template-author__task-id">
                        <span className="lux-onb-template-author__task-icon">
                          <i className={categoryMeta.icon} aria-hidden="true" />
                        </span>
                        <div>
                          <strong>Task {index + 1}</strong>
                          <span>{categoryMeta.label}</span>
                        </div>
                      </div>
                      <div className="lux-onb-template-author__task-actions">
                        <button
                          type="button"
                          className="lux-onb-template-author__duplicate"
                          onClick={() => duplicateTask(index)}
                          disabled={submitting}
                          aria-label={`Duplicate task ${index + 1}`}
                          title="Duplicate task"
                        >
                          <i className="fe fe-copy" aria-hidden />
                        </button>
                        {tasks.length > 1 && (
                          <button
                            type="button"
                            className="lux-onb-template-author__remove"
                            onClick={() => removeTask(index)}
                            disabled={submitting}
                            aria-label={`Remove task ${index + 1}`}
                            title="Remove task"
                          >
                            <i className="fe fe-trash-2" aria-hidden />
                          </button>
                        )}
                      </div>
                    </div>

                    <TemplateField label="Task title" icon="fe-edit-3" highlight className="is-wide">
                      <input
                        className="lux-onb-template-author__input"
                        value={task.title}
                        onChange={(event) => updateTask(index, { title: event.target.value })}
                        disabled={submitting}
                        placeholder={copy.taskPlaceholder}
                        aria-required={titledTaskCount === 0 && index === 0}
                      />
                    </TemplateField>

                    <div className="lux-onb-template-author__grid">
                      <TemplateField label="Category" icon="fe-grid">
                        <select
                          className="lux-onb-template-author__input"
                          value={task.category}
                          onChange={(event) => updateTask(index, { category: event.target.value })}
                          disabled={submitting}
                        >
                          {categories.map((category) => (
                            <option key={category.id} value={category.id}>
                              {category.label}
                            </option>
                          ))}
                        </select>
                      </TemplateField>
                      <TemplateField label="Due offset (days)" icon="fe-calendar">
                        <input
                          className="lux-onb-template-author__input"
                          type="number"
                          min="0"
                          value={task.dueOffsetDays}
                          onChange={(event) =>
                            updateTask(index, {
                              dueOffsetDays: Number(event.target.value) >= 0 ? Number(event.target.value) : 0,
                            })
                          }
                          disabled={submitting}
                        />
                      </TemplateField>
                    </div>

                    <div className="lux-onb-template-author__grid">
                      <TemplateField label="Owner role" icon="fe-shield">
                        <input
                          className="lux-onb-template-author__input"
                          value={task.ownerRole}
                          onChange={(event) => updateTask(index, { ownerRole: event.target.value })}
                          disabled={submitting}
                          placeholder="HR Admin"
                        />
                      </TemplateField>
                      <TemplateField label="Assignee" icon="fe-users">
                        <select
                          className="lux-onb-template-author__input"
                          value={task.assigneeType}
                          onChange={(event) =>
                            updateTask(index, { assigneeType: event.target.value })
                          }
                          disabled={submitting}
                        >
                          {assigneeTypes.map((assignee) => (
                            <option key={assignee.id} value={assignee.id}>
                              {assignee.label}
                            </option>
                          ))}
                        </select>
                      </TemplateField>
                    </div>

                    <div className="lux-onb-template-author__pills">
                      <FlagPill
                        active={task.required}
                        icon="fe-alert-circle"
                        label="Required"
                        disabled={submitting}
                        onClick={() => updateTask(index, { required: !task.required })}
                      />
                      <FlagPill
                        active={task.selfService}
                        icon="fe-user-check"
                        label={copy.selfServiceLabel}
                        disabled={submitting}
                        onClick={() => updateTask(index, { selfService: !task.selfService })}
                      />
                    </div>
                  </li>
                );
              })}
            </ul>
          </section>
        </form>

        <footer className="lux-onb-drawer__foot">
          <div className="lux-onb-drawer__foot-actions">
            <LifecycleActionLink variant="ghost" onClick={requestClose}>
              Cancel
            </LifecycleActionLink>
            <LifecycleActionLink
              variant="primary"
              icon="fe-save"
              type="submit"
              disabled={submitting || !name.trim() || titledTaskCount === 0}
            >
              {submitting ? "Saving…" : "Save template"}
            </LifecycleActionLink>
          </div>
          <p className="lux-onb-drawer__foot-hint">{copy.footHint}</p>
        </footer>
      </aside>
    </div>,
    document.body
  );
}
