import React, { Component } from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import { commonUtils } from "_helpers";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isPaychecksEnabled, isPayslipPdfEnabled } from "config/payroll.config";
import {
  buildMyPaycheckMetrics,
  buildMyPaycheckInsights,
  canDownloadPayslipPdf,
  filterPaychecks,
  resolveIndianFinancialYear,
} from "config/paycheck.utils";
import { shouldUsePayrollApi } from "config/payroll.config";
import { formatPayrollCurrency, formatPayrollDate } from "config/payroll.utils";
import { payrollService } from "_services/payroll.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import {
  WorkspaceActionButton,
  WorkspaceKpiStrip,
  WorkspacePanelHead,
} from "views/workspace/components/WorkspaceLuxShared";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import { PageDataSourceReporter } from "views/common/PageChromeContext";
import { DENSE_PAGE_META } from "config/dense-page-meta.config";

class MyPaychecksPage extends Component {
  state = {
    paychecks: [],
    loading: true,
    loadError: null,
    dataSource: null,
    query: "",
    downloadingId: null,
    downloadingForm16: false,
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("My paychecks");
    this.loadPaychecks();
  }

  loadPaychecks = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const employeeId = commonUtils.getCurrentUserId();
      const result = await payrollService.listMyPaychecks(employeeId);
      this.setState({
        paychecks: result.payload || [],
        loading: false,
        dataSource: result.source || null,
      });
    } catch (e) {
      this.setState({ loading: false, loadError: "Unable to load your paychecks.", paychecks: [] });
    }
  };

  getFilteredPaychecks = () => {
    return filterPaychecks(this.state.paychecks, { query: this.state.query });
  };

  handleDownloadPdf = async (paycheckId, event) => {
    if (event && event.preventDefault) {
      event.preventDefault();
    }
    if (!isPayslipPdfEnabled()) {
      return;
    }
    this.setState({ downloadingId: paycheckId });
    try {
      await payrollService.downloadPaycheckPdf(paycheckId);
    } catch (e) {
      this.setState({ loadError: "Unable to download payslip PDF." });
    } finally {
      this.setState({ downloadingId: null });
    }
  };

  handleDownloadForm16 = async () => {
    if (!shouldUsePayrollApi()) {
      this.setState({ loadError: "Form 16 estimate requires payroll API." });
      return;
    }
    const employeeId = commonUtils.getCurrentUserId();
    const fy = resolveIndianFinancialYear();
    this.setState({ downloadingForm16: true, loadError: null });
    try {
      const result = await payrollService.downloadForm16(employeeId, fy);
      if (!result || !result.payload) {
        this.setState({ loadError: "Unable to download Form 16 estimate." });
      }
    } catch (e) {
      this.setState({ loadError: "Unable to download Form 16 estimate." });
    } finally {
      this.setState({ downloadingForm16: false });
    }
  };

  renderInsights = () => {
    const { paychecks, loading } = this.state;
    if (loading) return null;
    const insights = buildMyPaycheckInsights(paychecks);
    return (
      <div className="lux-paycheck-insights" role="list">
        {insights.map((insight) => {
          const content = (
            <>
              <span className="lux-hrms-dash__alert-icon" aria-hidden="true"><i className={insight.icon} /></span>
              <span className="lux-paycheck-insight__copy">
                <strong>{insight.title}</strong>
                <small>{insight.copy}</small>
              </span>
              {insight.path && <i className="fe fe-chevron-right lux-paycheck-insight__chevron" aria-hidden="true" />}
            </>
          );
          return insight.path ? (
            <Link key={insight.id} to={insight.path} className={classNames("lux-hrms-dash__alert lux-paycheck-insight", `is-${insight.tone}`)} role="listitem">
              {content}
            </Link>
          ) : (
            <article key={insight.id} className={classNames("lux-hrms-dash__alert lux-paycheck-insight", `is-${insight.tone}`)} role="listitem">
              {content}
            </article>
          );
        })}
      </div>
    );
  };

  render() {
    if (!isPaychecksEnabled()) {
      return <PersonaAccessDenied moduleName="My paychecks" reason="Employee paycheck access is not enabled." />;
    }

    const { loading, loadError, dataSource, query, downloadingId, downloadingForm16 } = this.state;
    const rows = this.getFilteredPaychecks();
    const metrics = buildMyPaycheckMetrics(this.state.paychecks);
    const kpiCards = [
      { id: "total", label: "Payslips", value: metrics.total, hint: "Published on file", tone: "primary", icon: "fe fe-file-text" },
      { id: "latest", label: "Latest net", value: metrics.latestNet != null ? formatPayrollCurrency(metrics.latestNet, metrics.currency) : "—", hint: metrics.latestPeriod || "Most recent", tone: "green", icon: "fe fe-dollar-sign" },
      { id: "ytd", label: "YTD net", value: metrics.ytdNet != null ? formatPayrollCurrency(metrics.ytdNet, metrics.currency) : "—", hint: "Year to date", tone: "blue", icon: "fe fe-trending-up" },
    ];

    return (
      <div className="lux-my-paychecks-page lux-register-page" data-testid="page-my-paychecks">
        <PageDataSourceReporter dataSource={dataSource} />
        <LuxModuleIntro
          meta={DENSE_PAGE_META.myPaychecks}
          actions={
            <>
              {shouldUsePayrollApi() && (
                <WorkspaceActionButton
                  icon="fe fe-file"
                  variant="ghost"
                  onClick={this.handleDownloadForm16}
                  disabled={downloadingForm16 || loading}
                >
                  {downloadingForm16 ? "Form 16…" : "Form 16 estimate"}
                </WorkspaceActionButton>
              )}
              <WorkspaceActionButton to="/payroll/dashboard" icon="fe fe-pie-chart" variant="ghost">
                Payroll
              </WorkspaceActionButton>
            </>
          }
        />

        <div className="lux-register-page__body">
        <WorkspaceKpiStrip cards={kpiCards} loading={loading} className="lux-paycheck-kpi-strip" />
        {loadError && (
          <div className="lux-employee-360__error" role="alert">{loadError}</div>
        )}
        {this.renderInsights()}

        <section className="lux-hrms-dash__panel lux-paycheck-panel">
          <WorkspacePanelHead title="Payslip history" subtitle="Open a period to review earnings, deductions, and YTD" />

          <div className="lux-paycheck-panel__toolbar">
            <div className="lux-appr-toolbar__row">
              <div className="lux-appr-toolbar__search">
                <i className="fe fe-search" aria-hidden="true" />
                <input
                  type="search"
                  className="lux-appr-toolbar__search-input"
                  placeholder="Search pay periods"
                  value={query}
                  onChange={(e) => this.setState({ query: e.target.value })}
                />
              </div>
              <span className="lux-appr-toolbar__count">
                <strong>{rows.length}</strong> payslip{rows.length === 1 ? "" : "s"}
              </span>
            </div>
          </div>

          <div className="lux-hrms-dash__panel-body">
            {loading ? (
              <LuxRegisterEmptyState className="lux-register-empty--compact" title="Loading paychecks" description="Fetching your published payslips." />
            ) : rows.length === 0 ? (
              <LuxRegisterEmptyState className="lux-register-empty--compact" icon="fe fe-dollar-sign" title="No paychecks yet" description="Published payslips will appear here after payroll processing." />
            ) : (
              <div className="lux-paycheck-register-wrap">
                <table className="lux-paycheck-register">
                  <thead>
                    <tr>
                      <th>Pay period</th>
                      <th>Pay date</th>
                      <th>Net pay</th>
                      <th>YTD net</th>
                      <th aria-hidden="true" />
                    </tr>
                  </thead>
                  <tbody>
                    {rows.map((row) => (
                      <tr key={row.id} className="lux-paycheck-register__row">
                        <td>
                          <Link to={`/payroll/paychecks/${row.id}`} className="lux-paycheck-register__primary">
                            <span className="lux-paycheck-register__avatar is-green" aria-hidden="true">
                              <i className="fe fe-file-text" />
                            </span>
                            <span className="lux-paycheck-register__primary-copy">
                              <strong className="lux-paycheck-register__primary-title">{row.periodLabel}</strong>
                              <span className="lux-paycheck-register__primary-meta">{row.runName}</span>
                            </span>
                          </Link>
                        </td>
                        <td><span className="lux-paycheck-register__date">{formatPayrollDate(row.payDate)}</span></td>
                        <td><strong className="lux-paycheck-register__net">{formatPayrollCurrency(row.net, row.currency)}</strong></td>
                        <td><span className="lux-paycheck-register__period">{formatPayrollCurrency(row.ytdNet, row.currency)}</span></td>
                        <td>
                          <div className="lux-paycheck-register__actions">
                            {isPayslipPdfEnabled() && canDownloadPayslipPdf(row) && (
                              <button
                                type="button"
                                className="lux-paycheck-register__download"
                                aria-label={`Download ${row.periodLabel} PDF`}
                                disabled={downloadingId === row.id}
                                onClick={(event) => this.handleDownloadPdf(row.id, event)}
                              >
                                <i className="fe fe-download" aria-hidden="true" />
                              </button>
                            )}
                            <Link to={`/payroll/paychecks/${row.id}`} className="lux-paycheck-register__open" aria-label={`Open ${row.periodLabel} payslip`}>
                              <i className="fe fe-chevron-right" aria-hidden="true" />
                            </Link>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </section>
        </div>
      </div>
    );
  }
}

export default MyPaychecksPage;
