/**
 * F06 — Timesheet intelligence APIs with client fallback.
 * PR-05: fail closed on API error when mock is off — never invent metrics.
 */
import { axiosUtils } from "../_helpers";
import urlConfig from "url.config";
import { shouldUseTimesheetIntelligenceApi } from "config/timesheet-enhancement.config";
import { buildTimesheetIntelligence } from "config/timesheet-intelligence.utils";
import { buildBillabilityLeakageAnalytics } from "config/timesheet-leakage.utils";
import { buildTimesheetRecommendationDraft } from "config/timesheet-recommendation.utils";

export const timesheetIntelligenceService = {
  getIntelligence,
  getBillabilityAnalytics,
  getRecommendation,
};

async function getIntelligenceFromApi(userTeamId, weekStartDate) {
  const query = [
    userTeamId ? `userTeamId=${encodeURIComponent(userTeamId)}` : null,
    weekStartDate ? `weekStartDate=${encodeURIComponent(weekStartDate)}` : null,
  ]
    .filter(Boolean)
    .join("&");
  const response = await axiosUtils.get(`${urlConfig.TIMESHEET_INTELLIGENCE}?${query}`);
  return response && response.payload ? response.payload : response;
}

function clientIntelligence(context) {
  return {
    ...buildTimesheetIntelligence(context),
    source: "client",
  };
}

async function getIntelligence(context) {
  if (shouldUseTimesheetIntelligenceApi()) {
    try {
      const payload = await getIntelligenceFromApi(context.userTeamId, context.weekStartDate);
      if (payload) {
        return { ...payload, source: "api" };
      }
    } catch (e) {
      console.warn("[TimesheetIntelligence] API unavailable.", e);
      return { payload: null, source: "api-error", error: e };

    }
  }
  return clientIntelligence(context);
}

async function getBillabilityAnalytics(context) {
  const intelligence = await getIntelligence(context);
  if (intelligence && intelligence.source === "api-error") {
    return { payload: null, source: "api-error" };
  }
  return buildBillabilityLeakageAnalytics(intelligence);
}

async function getRecommendation(context) {
  const intelligence = await getIntelligence(context);
  if (intelligence && intelligence.source === "api-error") {
    return { payload: null, source: "api-error" };
  }
  const billability = buildBillabilityLeakageAnalytics(intelligence);
  return buildTimesheetRecommendationDraft(intelligence, billability);
}
