import React, { Component } from "react";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { ADMIN_PAGE_META } from "config/admin-page-meta.config";
import {
  buildNotificationTemplateInsights,
  buildNotificationTemplateMetrics,
  filterNotificationTemplates,
  isNotificationTemplatesAdminEnabled,
  isSystemNotificationTemplate,
} from "config/notification-template.config";
import { notificationTemplateService } from "_services/notificationTemplate.service";
import {
  AdminActionButton,
  AdminInsightStrip,
  AdminPanelHead,
  AdminQuickNav,
  AdminLuxPage,
} from "views/admin/components/AdminLuxShared";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import AdminLoadAlert from "views/admin/components/AdminLoadAlert";
import NotificationTemplateRegister from "views/admin/components/NotificationTemplateRegister";
import NotificationTemplateDrawer from "views/admin/components/NotificationTemplateDrawer";
import "views/hrms/leaveLuxForms.css";
import "views/admin/components/NotificationTemplateDrawer.css";

class NotificationTemplatesPage extends Component {
  state = {
    templates: [],
    loading: true,
    loadError: null,
    dataSource: null,
    query: "",
    sourceFilter: "ALL",
    channelFilter: "ALL",
    selected: null,
    drawerOpen: false,
    previewHtml: "",
    previewLoading: false,
    showPreview: false,
    showDeleteConfirm: false,
    saving: false,
    sendTestEmail: "",
    sendTestLoading: false,
    sendTestMessage: null,
    formError: null,
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Notification templates");
    this.loadTemplates();
  }

  loadTemplates = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await notificationTemplateService.listTemplates();
      this.setState({
        templates: result.payload || [],
        loading: false,
        dataSource: result.source || null,
      });
    } catch (e) {
      this.setState({
        loading: false,
        loadError: "Unable to load notification templates.",
        templates: [],
      });
    }
  };

  getFilteredTemplates = () => {
    const { templates, query, sourceFilter, channelFilter } = this.state;
    return filterNotificationTemplates(templates, {
      query,
      source: sourceFilter,
      channel: channelFilter,
    });
  };

  closeDrawer = () => {
    if (this.state.saving || this.state.sendTestLoading) return;
    this.setState({
      drawerOpen: false,
      selected: null,
      previewHtml: "",
      showPreview: false,
      showDeleteConfirm: false,
      formError: null,
      sendTestMessage: null,
    });
  };

  openTemplate = (row) => {
    this.setState({
      drawerOpen: true,
      selected: {
        ...row,
        htmlTemplate: row.htmlTemplate || "",
        subject: row.subject || "",
        enabled: row.enabled !== false,
      },
      previewHtml: "",
      showPreview: false,
      showDeleteConfirm: false,
      formError: null,
      sendTestMessage: null,
    });
  };

  cloneToOverride = (row) => {
    const source = row || this.state.selected;
    if (!source || !isSystemNotificationTemplate(source)) {
      return;
    }
    this.setState({
      drawerOpen: true,
      selected: {
        eventType: source.eventType,
        channel: source.channel || "EMAIL",
        subject: source.subject || "",
        htmlTemplate: "",
        textTemplate: "",
        classpathTemplateName: source.classpathTemplateName,
        enabled: true,
        systemDefault: false,
        source: "org-override",
      },
      previewHtml: "",
      showPreview: false,
      showDeleteConfirm: false,
      formError: null,
      sendTestMessage: null,
    });
  };

  handleFieldChange = (field, value) => {
    const { selected } = this.state;
    if (!selected || isSystemNotificationTemplate(selected)) return;
    this.setState({ selected: { ...selected, [field]: value } });
  };

  toggleEnabled = (enabled) => {
    const { selected } = this.state;
    if (!selected || isSystemNotificationTemplate(selected)) return;
    this.setState({ selected: { ...selected, enabled } });
  };

  saveTemplate = async () => {
    const { selected } = this.state;
    if (!selected || isSystemNotificationTemplate(selected)) return;
    this.setState({ saving: true, formError: null, loadError: null });
    try {
      await notificationTemplateService.saveTemplate(selected);
      await this.loadTemplates();
      this.setState({
        saving: false,
        drawerOpen: false,
        selected: null,
        previewHtml: "",
        showPreview: false,
        showDeleteConfirm: false,
      });
    } catch (e) {
      this.setState({ saving: false, formError: "Unable to save template." });
    }
  };

  requestDelete = () => {
    const { selected } = this.state;
    if (!selected || isSystemNotificationTemplate(selected) || !selected.templateRef) return;
    this.setState({ showDeleteConfirm: true });
  };

  confirmDelete = async () => {
    const { selected } = this.state;
    if (!selected || isSystemNotificationTemplate(selected) || !selected.templateRef) return;
    this.setState({ saving: true, formError: null, loadError: null });
    try {
      await notificationTemplateService.deleteTemplate(selected.templateRef);
      await this.loadTemplates();
      this.setState({
        saving: false,
        drawerOpen: false,
        selected: null,
        previewHtml: "",
        showPreview: false,
        showDeleteConfirm: false,
      });
    } catch (e) {
      this.setState({ saving: false, formError: "Unable to delete template." });
    }
  };

  previewTemplate = async () => {
    const { selected } = this.state;
    if (!selected) return;
    this.setState({ previewLoading: true, formError: null });
    try {
      const result = await notificationTemplateService.previewTemplate(selected);
      const html = (result.payload && (result.payload.html || result.payload.text)) || "";
      this.setState({
        previewHtml: html,
        previewLoading: false,
        showPreview: true,
      });
    } catch (e) {
      this.setState({ previewLoading: false, formError: "Unable to preview template." });
    }
  };

  sendTest = async () => {
    const { selected, sendTestEmail } = this.state;
    if (!selected) return;
    this.setState({ sendTestLoading: true, sendTestMessage: null, formError: null, loadError: null });
    try {
      const result = await notificationTemplateService.sendTestTemplate({
        ...selected,
        toEmail: (sendTestEmail || "").trim() || undefined,
      });
      const payload = (result && result.payload) || {};
      this.setState({
        sendTestLoading: false,
        sendTestMessage: payload.message
          ? `${payload.message} → ${payload.toEmail || ""}`
          : "Send-test completed.",
      });
    } catch (e) {
      this.setState({
        sendTestLoading: false,
        sendTestMessage: null,
        formError: (e && e.message) || "Send-test failed (mail may be disabled).",
      });
    }
  };

  render() {
    if (!isNotificationTemplatesAdminEnabled()) {
      return (
        <PersonaAccessDenied
          moduleName="Notification templates"
          reason="Notification template administration is not enabled for your organization."
        />
      );
    }

    const filtered = this.getFilteredTemplates();
    const metrics = buildNotificationTemplateMetrics(this.state.templates);
    const insights = this.state.loading ? [] : buildNotificationTemplateInsights(this.state.templates);
    const {
      selected,
      drawerOpen,
      previewHtml,
      previewLoading,
      showPreview,
      showDeleteConfirm,
      saving,
      loading,
      dataSource,
      sendTestEmail,
      sendTestLoading,
      sendTestMessage,
      query,
      sourceFilter,
      channelFilter,
      loadError,
      formError,
    } = this.state;

    const busy = saving || sendTestLoading;
    const kpiCards = [
      { id: "total", label: "Templates", value: metrics.total, hint: "Merged catalog", tone: "blue", icon: "fe fe-mail" },
      { id: "overrides", label: "Org overrides", value: metrics.overrides, hint: "Custom templates", tone: "primary", icon: "fe fe-edit" },
      { id: "email", label: "Email", value: metrics.email, hint: "EMAIL channel", tone: "indigo", icon: "fe fe-at-sign" },
      { id: "disabled", label: "Disabled", value: metrics.disabled, hint: "Not dispatching", tone: metrics.disabled ? "amber" : "green", icon: "fe fe-slash" },
    ];

    return (
      <AdminLuxPage
        pageMeta={ADMIN_PAGE_META.notificationTemplates}
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        testId="page-admin-notification-templates"
        className="lux-register-page lux-ntpl-page lux-leave-page lux-admin-page"
        heroActions={
          <AdminActionButton icon="fe fe-refresh-cw" onClick={this.loadTemplates} disabled={loading}>
            Refresh
          </AdminActionButton>
        }
      >
        <LuxInlineAlert tone="info" className="lux-ntpl-editor-banner" testId="ntpl-editor-banner">
          Manage classpath defaults and org overrides for outbound messaging. Open any row to view or edit in
          the luxury drawer. Preview masks sensitive placeholders; runtime dispatch still uses workspace
          notification services.
        </LuxInlineAlert>

        <AdminLoadAlert
          error={loadError}
          fallback="Unable to load notification templates."
          onDismiss={() => this.setState({ loadError: null })}
        />

        <AdminInsightStrip insights={insights} />

        <AdminQuickNav
          eyebrow="Shortcuts"
          title="Related governance"
          ariaLabel="Notification template related links"
          links={[
            {
              path: "/admin/feature-flags",
              label: "Feature flags",
              desc: "Stage notification pilots and workspace messaging toggles",
              icon: "fe fe-toggle-right",
              tone: "violet",
            },
            {
              path: "/admin/audit",
              label: "Audit trail",
              desc: "Review send-test and template override activity",
              icon: "fe fe-activity",
              tone: "blue",
            },
            {
              path: "/admin/roles",
              label: "Roles & permissions",
              desc: "Who can administer notification templates",
              icon: "fe fe-lock",
              tone: "indigo",
            },
          ]}
        />

        <section className="lux-hrms-dash__panel lux-ntpl-panel">
          <AdminPanelHead
            title="Template catalog"
            subtitle={
              dataSource === "api"
                ? "Live merged catalog — click View / Edit to open the drawer"
                : "Merged classpath defaults + org overrides — click View / Edit to open the drawer"
            }
            actions={
              <AdminActionButton
                icon="fe fe-refresh-cw"
                variant="ghost"
                onClick={this.loadTemplates}
                disabled={loading}
              >
                Refresh
              </AdminActionButton>
            }
          />

          <div className="lux-ntpl-panel__toolbar">
            <div className="lux-ntpl-toolbar__row">
              <div className="lux-ntpl-toolbar__search">
                <i className="fe fe-search" aria-hidden="true" />
                <input
                  type="search"
                  className="lux-ntpl-toolbar__search-input"
                  placeholder="Search event type, subject, or template ref"
                  value={query}
                  onChange={(e) => this.setState({ query: e.target.value })}
                  data-testid="ntpl-search"
                />
              </div>
              <span className="lux-ntpl-toolbar__count">
                <strong>{filtered.length}</strong> template{filtered.length === 1 ? "" : "s"}
              </span>
            </div>
            <div className="lux-ntpl-panel__filters">
              <div className="lux-ntpl-toolbar__group">
                <span className="lux-ntpl-toolbar__label">Source</span>
                <div className="lux-hrms-dash__filter-group">
                  {[
                    { id: "ALL", label: "All" },
                    { id: "SYSTEM", label: "System" },
                    { id: "OVERRIDE", label: "Overrides" },
                  ].map((item) => (
                    <button
                      key={item.id}
                      type="button"
                      className={classNames("lux-hrms-dash__filter-chip", {
                        "is-active": sourceFilter === item.id,
                      })}
                      onClick={() => this.setState({ sourceFilter: item.id })}
                    >
                      {item.label}
                    </button>
                  ))}
                </div>
              </div>
              <div className="lux-ntpl-toolbar__group">
                <span className="lux-ntpl-toolbar__label">Channel</span>
                <div className="lux-hrms-dash__filter-group">
                  {[
                    { id: "ALL", label: "All" },
                    { id: "EMAIL", label: "Email" },
                  ].map((item) => (
                    <button
                      key={item.id}
                      type="button"
                      className={classNames("lux-hrms-dash__filter-chip", {
                        "is-active": channelFilter === item.id,
                      })}
                      onClick={() => this.setState({ channelFilter: item.id })}
                    >
                      {item.label}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>

          <div className="lux-hrms-dash__panel-body">
            {loading ? (
              <LuxRegisterEmptyState
                className="lux-register-empty--compact"
                title="Loading templates"
                description="Fetching the merged notification catalog."
              />
            ) : filtered.length === 0 ? (
              <LuxRegisterEmptyState
                className="lux-register-empty--compact"
                icon="fe fe-mail"
                title="No templates"
                description="Adjust filters or refresh the catalog."
              />
            ) : (
              <NotificationTemplateRegister
                templates={filtered}
                onView={this.openTemplate}
                onEdit={this.openTemplate}
                onClone={this.cloneToOverride}
              />
            )}
          </div>
        </section>

        <NotificationTemplateDrawer
          open={drawerOpen}
          selected={selected}
          busy={busy}
          saving={saving}
          previewHtml={previewHtml}
          previewLoading={previewLoading}
          showPreview={showPreview}
          showDeleteConfirm={showDeleteConfirm}
          sendTestEmail={sendTestEmail}
          sendTestLoading={sendTestLoading}
          sendTestMessage={sendTestMessage}
          formError={formError}
          onClose={this.closeDrawer}
          onChange={this.handleFieldChange}
          onToggleEnabled={this.toggleEnabled}
          onClone={() => this.cloneToOverride()}
          onSave={this.saveTemplate}
          onRequestDelete={this.requestDelete}
          onCancelDelete={() => this.setState({ showDeleteConfirm: false })}
          onConfirmDelete={this.confirmDelete}
          onPreview={this.previewTemplate}
          onClosePreview={() => this.setState({ showPreview: false })}
          onSendTestEmailChange={(value) =>
            this.setState({ sendTestEmail: value, sendTestMessage: null })
          }
          onSendTest={this.sendTest}
        />
      </AdminLuxPage>
    );
  }
}

export default NotificationTemplatesPage;
