import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isIntegrationCenterEnabled } from "config/integration-center.config";
import { INTEGRATION_MAPPING_PAGE_META } from "config/integration-center-nav.config";
import { buildMappingInsights, buildMappingKpis } from "config/integration-center.utils";
import { integrationCenterService } from "_services/integrationCenter.service";
import IntegrationsLuxPage, {
  IntegrationActionButton,
  IntegrationInsightPanel,
  IntegrationLuxPanel,
} from "views/integrations/components/IntegrationsLuxShared";
import {
  IntegrationSnapshotStrip,
  MappingRegister,
  buildMappingSnapshotMetrics,
} from "views/integrations/components/IntegrationRegisters";

class IntegrationMappingPage extends Component {
  state = { loading: true, loadError: null, dataSource: null, mappings: [], kpiCards: [], insights: [] };

  componentDidMount() {
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await integrationCenterService.listFieldMappings();
      const mappings = result.payload || [];
      this.setState({
        loading: false,
        dataSource: result.source,
        mappings,
        kpiCards: buildMappingKpis(mappings),
        insights: buildMappingInsights(mappings),
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load field mappings.",
      });
    }
  };

  render() {
    if (!isIntegrationCenterEnabled()) {
      return <PersonaAccessDenied title="Data mapping" message="Integration center is not enabled for this organization." />;
    }

    const { loading, loadError, dataSource, mappings, kpiCards, insights } = this.state;

    return (
      <IntegrationsLuxPage
        pageMeta={INTEGRATION_MAPPING_PAGE_META}
        pageId="mapping"
        shellTitle="Data mapping"
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        heroActions={
          <IntegrationActionButton icon="fe fe-refresh-cw" onClick={this.loadData} disabled={loading}>
            Refresh
          </IntegrationActionButton>
        }
      >
        {loadError ? <p className="lux-integ-error">{loadError}</p> : null}
        <IntegrationInsightPanel insights={insights} />
        <IntegrationSnapshotStrip
          loading={loading}
          badgeIcon="fe fe-shuffle"
          badgeLabel="Mapping coverage"
          metrics={buildMappingSnapshotMetrics(mappings)}
        />
        <IntegrationLuxPanel
          title="Canonical field maps"
          meta="Source-to-target object coverage across connectors"
          icon="fe fe-shuffle"
          accent="indigo"
          featured
        >
          <MappingRegister mappings={mappings} loading={loading} />
        </IntegrationLuxPanel>
      </IntegrationsLuxPage>
    );
  }
}

export default IntegrationMappingPage;
