import React, { Component } from "react";
import classNames from "classnames/bind";

export default class TimesheetAgentDraftPanel extends Component {
  handleAction = (action) => {
    const { onAction, recommendation } = this.props;
    if (onAction) {
      onAction(action, recommendation);
    }
  };

  render() {
    const { recommendation, actionLog, source } = this.props;
    if (!recommendation) {
      return null;
    }

    const statusLabel =
      source === "api" ? "Live" : source === "mock" ? "Demo" : "Unavailable";

    return (
      <section className="lux-ts-intel__agent" aria-label="Agent draft workflow">
        <header className="lux-ts-intel__agent-head">
          <div>
            <span className="lux-ts-intel__agent-kicker">
              <i className="fe fe-cpu" aria-hidden="true" />
              AI agent workflow
            </span>
            <h4>Accept, reject, or defer</h4>
          </div>
          <span className="lux-ts-intel__agent-badge">{statusLabel}</span>
        </header>

        {recommendation.summary && (
          <p className="lux-ts-intel__agent-context">{recommendation.summary}</p>
        )}
        <p className="lux-ts-intel__agent-summary">{recommendation.recommendation}</p>

        <div className="lux-ts-intel__agent-actions">
          <button
            type="button"
            className="lux-ts-intel__agent-btn is-accept"
            onClick={() => this.handleAction("accept")}
          >
            <i className="fe fe-check" aria-hidden="true" />
            Accept
          </button>
          <button
            type="button"
            className="lux-ts-intel__agent-btn is-reject"
            onClick={() => this.handleAction("reject")}
          >
            <i className="fe fe-x" aria-hidden="true" />
            Reject
          </button>
          <button
            type="button"
            className="lux-ts-intel__agent-btn is-defer"
            onClick={() => this.handleAction("defer")}
          >
            <i className="fe fe-clock" aria-hidden="true" />
            Defer
          </button>
        </div>

        {actionLog && actionLog.length > 0 && (
          <ul className="lux-ts-intel__agent-log">
            {actionLog.slice(0, 3).map((entry) => (
              <li key={entry.at} className={classNames("lux-ts-intel__agent-log-item", `is-${entry.action}`)}>
                <strong>{entry.action}</strong>
                <span>{entry.message}</span>
              </li>
            ))}
          </ul>
        )}
      </section>
    );
  }
}
