import React from "react";
import LuxHeroLineSkeleton from "views/common/fragments/LuxHeroLineSkeleton";
import OnboardingStatusBadge from "./OnboardingStatusBadge";

function getInitials(name = "") {
  return name
    .split(" ")
    .filter(Boolean)
    .map((part) => part[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();
}

function LifecycleCaseHero({ caseData, loading, lifecycle }) {
  const isOffboarding = lifecycle === "offboarding";
  const safeCase = caseData || {};
  const name = isOffboarding ? safeCase.employeeName : safeCase.candidateName;
  const pct = safeCase.readinessPct || 0;

  return (
    <header
      className={`lux-hrms-dash__hero lux-onb-hero lux-onb-hero--detail ${
        isOffboarding ? "lux-onb-hero--exit" : "lux-onb-hero--join"
      }`}
    >
      <div className="lux-onb-hero__detail-main">
        <span className="lux-onb-case-card__avatar lux-onb-case-card__avatar--lg" aria-hidden>
          {loading ? "…" : getInitials(name)}
        </span>
        <div className="lux-hrms-dash__hero-main">
          <span className="lux-hrms-dash__hero-eyebrow">
            {isOffboarding ? "Exit checklist" : "Onboarding checklist"}
          </span>
          <h1 className="lux-hrms-dash__hero-title">
            {loading ? <LuxHeroLineSkeleton width={220} /> : <span>{name}</span>}
          </h1>
          <p className="lux-hrms-dash__hero-sub">
            {loading ? (
              <LuxHeroLineSkeleton width={300} />
            ) : (
              <>
                {safeCase.role}
                {isOffboarding
                  ? ` · Last day ${safeCase.lastDay || "—"}`
                  : ` · Starts ${safeCase.startDate || "—"}`}
              </>
            )}
          </p>
          {!loading && (
            <p className="lux-hrms-dash__hero-context">
              {safeCase.department} · {safeCase.location} · Manager {safeCase.manager}
              {isOffboarding && safeCase.exitReason ? ` · ${safeCase.exitReason}` : ""}
            </p>
          )}
        </div>
      </div>

      <div className="lux-onb-hero__detail-aside">
        {!loading && (
          <>
            <div
              className="lux-onb-progress-ring"
              style={{ "--lux-onb-pct": pct }}
              aria-label={`${pct}% ready`}
            >
              <span className="lux-onb-progress-ring__value">{pct}%</span>
            </div>
            <OnboardingStatusBadge status={safeCase.status} lifecycle={lifecycle} />
            {safeCase.templateName && (
              <span className="lux-onb-hero__template">
                <i className="fe fe-layers" aria-hidden /> {safeCase.templateName}
              </span>
            )}
          </>
        )}
      </div>
    </header>
  );
}

export default LifecycleCaseHero;
