import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isFinanceIntelligenceEnabled } from "config/finance-intelligence.config";
import { REVENUE_LEAKAGE_PAGE_META } from "config/finance-intelligence-nav.config";
import { financeIntelligenceService } from "_services/financeIntelligence.service";
import FinanceLuxPage, {
  FinanceActionButton,
  FinanceInsightPanel,
  FinanceLuxPanel,
} from "views/finance/components/FinanceLuxShared";
import FinanceLoadAlert from "views/finance/components/FinanceLoadAlert";
import RevenueLeakageRegister from "views/finance/components/RevenueLeakageRegister";
import { shouldHideRegisterOnLoadError } from "_helpers/registerListError.utils";

class RevenueLeakagePage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    flags: [],
    kpiCards: [],
    insights: [],
    filters: { severity: "ALL", status: "OPEN" },
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Revenue leakage");
    }
    this.loadData();
  }

  loadData = async (filters = this.state.filters) => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await financeIntelligenceService.listRevenueLeakageFlags(filters);
      this.setState({
        loading: false,
        flags: result.payload || [],
        kpiCards: (result.overview && result.overview.kpiCards) || [],
        insights: (result.overview && result.overview.insights) || [],
        dataSource: result.source,
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: error,
      });
    }
  };

  handleFilterChange = (patch) => {
    const filters = { ...this.state.filters, ...patch };
    this.setState({ filters }, () => this.loadData(filters));
  };

  render() {
    if (!isFinanceIntelligenceEnabled()) {
      return <PersonaAccessDenied featureLabel="Revenue leakage" />;
    }

    const { loading, loadError, dataSource, flags, kpiCards, insights, filters } = this.state;
    const meta = REVENUE_LEAKAGE_PAGE_META;
    const hideRegister = shouldHideRegisterOnLoadError(loadError, flags);

    return (
      <FinanceLuxPage
        testId="page-finance-revenue-leakage"
        pageMeta={meta}
        dataSource={dataSource}
        demoLabel="Demo revenue leakage"
        loading={loading}
        kpiCards={kpiCards}
        heroActions={
          <>
            <FinanceActionButton to="/analytics/finance" icon="fe fe-trending-up" variant="ghost">
              Financial analytics
            </FinanceActionButton>
            <FinanceActionButton to="/finance/project-financials" icon="fe fe-pie-chart" variant="primary">
              Project financials
            </FinanceActionButton>
          </>
        }
      >
        <FinanceInsightPanel insights={insights} />
        <FinanceLoadAlert
          error={loadError}
          fallback="Unable to load revenue leakage flags."
          onDismiss={() => this.setState({ loadError: null })}
        />
        {hideRegister ? null : (
        <FinanceLuxPanel title={meta.panelTitle} meta={meta.panelMeta} icon="fe fe-shield" accent="rose">
          <div className="lux-finance-snapshots">
            <div className="lux-finance-snapshots__toolbar">
              <div className="lux-finance-snapshots__filters">
                <label className="lux-finance-snapshots__field">
                  <span>Severity</span>
                  <select
                    value={filters.severity || "ALL"}
                    onChange={(event) => this.handleFilterChange({ severity: event.target.value })}
                  >
                    <option value="ALL">All severities</option>
                    <option value="HIGH">High</option>
                    <option value="MEDIUM">Medium</option>
                    <option value="LOW">Low</option>
                  </select>
                </label>
                <label className="lux-finance-snapshots__field">
                  <span>Status</span>
                  <select
                    value={filters.status || "OPEN"}
                    onChange={(event) => this.handleFilterChange({ status: event.target.value })}
                  >
                    <option value="OPEN">Open</option>
                    <option value="RESOLVED">Resolved</option>
                    <option value="ALL">All statuses</option>
                  </select>
                </label>
              </div>
            </div>
            <RevenueLeakageRegister rows={flags} loading={loading} />
          </div>
        </FinanceLuxPanel>
        )}
      </FinanceLuxPage>
    );
  }
}

export default RevenueLeakagePage;
