import React, { Component } from "react";
import classNames from "classnames/bind";
import DateRangeSelector from "./DateRangeSelector";

class PageInnerHeaderSearchDateMenu extends Component {
  constructor(props) {
    super(props);
    this.state = {
      searchOption: props.defaultSearchViewOpiton || "All",
      searchTerm: "",
      showSearchPanel: false,
    };
    this.searchWrapRef = React.createRef();
  }

  componentDidMount() {
    document.addEventListener("mousedown", this.handleOutsideClick);
  }

  componentDidUpdate(prevProps) {
    if (
      prevProps.defaultSearchViewOpiton !== this.props.defaultSearchViewOpiton &&
      this.props.defaultSearchViewOpiton
    ) {
      this.setState({ searchOption: this.props.defaultSearchViewOpiton });
    }
  }

  componentWillUnmount() {
    document.removeEventListener("mousedown", this.handleOutsideClick);
  }

  hasDateRange = () => !!this.props.defaultDateRangeValue;

  hasSearchFields = () => {
    const options = this.props.searchViewOpitons;
    return this.props.searchViewEnabled && options && Object.keys(options).length > 0;
  };

  handleOutsideClick = (event) => {
    if (!this.state.showSearchPanel) return;
    const wrap = this.searchWrapRef.current;
    if (wrap && !wrap.contains(event.target)) {
      this.setState({ showSearchPanel: false });
    }
  };

  toggleSearchPanel = () => {
    if (this.props.isLoading) return;
    this.setState((prev) => ({ showSearchPanel: !prev.showSearchPanel }));
  };

  closeSearchPanel = () => {
    this.setState({ showSearchPanel: false });
  };

  getSearchFieldOptions = () => {
    const options = this.props.searchViewOpitons || {};
    return Object.keys(options).map((key) => ({
      key,
      label: options[key],
    }));
  };

  getActiveFieldLabel = () => {
    const options = this.props.searchViewOpitons || {};
    return options[this.state.searchOption] || this.state.searchOption;
  };

  getSearchTriggerLabel = () => {
    if (this.state.searchTerm.trim()) {
      return `${this.getActiveFieldLabel()} · ${this.state.searchTerm.trim()}`;
    }
    return "Field search";
  };

  handleSearchSubmit = () => {
    const term = this.state.searchTerm.trim();
    if (!term) return;
    this.props.handleSearchSubmit(this.state.searchOption, term);
    this.closeSearchPanel();
  };

  onSearchKeyDown = (event) => {
    if (event.key === "Enter") {
      event.preventDefault();
      this.handleSearchSubmit();
    }
  };

  renderSearchPanel = () => {
    const fieldOptions = this.getSearchFieldOptions();

    return (
      <div className="lux-page-header__query-popover lux-page-header__query-popover--search" role="dialog" aria-label="Field search">
        <header className="lux-page-header__query-popover-head">
          <span className="lux-page-header__query-popover-icon" aria-hidden="true">
            <i className="fe fe-search" />
          </span>
          <div>
            <span className="lux-page-header__query-popover-eyebrow">List query</span>
            <strong>Field search</strong>
          </div>
          <button
            type="button"
            className="lux-page-header__query-popover-close"
            onClick={this.closeSearchPanel}
            aria-label="Close"
          >
            <i className="fe fe-x" aria-hidden="true" />
          </button>
        </header>

        <div className="lux-page-header__query-popover-body">
          <div className="lux-page-header__query-search">
            <p className="lux-page-header__query-hint">Pick a field and enter a value to search.</p>

            <div className="lux-page-header__query-search-fields" role="listbox" aria-label="Search field">
              {fieldOptions.map((option) => (
                <button
                  key={option.key}
                  type="button"
                  role="option"
                  aria-selected={this.state.searchOption === option.key}
                  className={classNames("lux-page-header__query-search-field", {
                    "is-active": this.state.searchOption === option.key,
                  })}
                  onClick={() => this.setState({ searchOption: option.key })}
                >
                  <span className="lux-page-header__query-search-field-mark" aria-hidden="true">
                    {this.state.searchOption === option.key && <i className="fe fe-check" />}
                  </span>
                  <span>{option.label}</span>
                </button>
              ))}
            </div>

            <label className="lux-page-header__query-search-input">
              <i className="fe fe-search" aria-hidden="true" />
              <input
                type="search"
                value={this.state.searchTerm}
                onChange={(e) => this.setState({ searchTerm: e.target.value })}
                onKeyDown={this.onSearchKeyDown}
                placeholder="Enter search value..."
                disabled={this.props.isLoading}
                aria-label="Search value"
                autoFocus
              />
              {this.state.searchTerm && (
                <button
                  type="button"
                  className="lux-page-header__query-search-clear"
                  onClick={() => this.setState({ searchTerm: "" })}
                  aria-label="Clear"
                >
                  <i className="fe fe-x" aria-hidden="true" />
                </button>
              )}
            </label>

            <footer className="lux-page-header__query-footer">
              <button type="button" className="lux-page-header__query-cancel" onClick={this.closeSearchPanel}>
                Cancel
              </button>
              <button
                type="button"
                className="lux-page-header__query-submit"
                onClick={this.handleSearchSubmit}
                disabled={this.props.isLoading || !this.state.searchTerm.trim()}
              >
                <i className="fe fe-arrow-right" aria-hidden="true" />
                Search
              </button>
            </footer>
          </div>
        </div>
      </div>
    );
  };

  renderFieldSearch = () => (
    <div
      className={classNames("lux-page-header__field-query", {
        "is-open": this.state.showSearchPanel,
      })}
      ref={this.searchWrapRef}
    >
      <button
        type="button"
        className="lux-page-header__field-query-btn"
        onClick={this.toggleSearchPanel}
        disabled={this.props.isLoading}
        aria-expanded={this.state.showSearchPanel}
        aria-haspopup="dialog"
        title={this.getSearchTriggerLabel()}
      >
        <i className="fe fe-search" aria-hidden="true" />
        <span className="lux-page-header__field-query-label">{this.getSearchTriggerLabel()}</span>
        <i className="fe fe-chevron-down" aria-hidden="true" />
      </button>
      {this.state.showSearchPanel && this.renderSearchPanel()}
    </div>
  );

  render() {
    if (!this.hasDateRange() && !this.hasSearchFields()) return null;

    return (
      <div className="lux-page-header__query-tools">
        {this.hasDateRange() && (
          <DateRangeSelector
            defaultDateRangeValue={this.props.defaultDateRangeValue}
            onDateRangeChange={this.props.handleDateRangeChange}
            isLoading={this.props.isLoading}
          />
        )}
        {this.hasSearchFields() && this.renderFieldSearch()}
      </div>
    );
  }
}

export default PageInnerHeaderSearchDateMenu;
