import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isResourcePlanningEnabled } from "config/resource-planning.config";
import { resourcePlanningService } from "_services/resourcePlanning.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import PolicyAnalyticsBarChart from "views/people/components/policy/PolicyAnalyticsBarChart";
import {
  AdminInsightStrip,
} from "views/admin/components/AdminLuxShared";
import {
  ResourcesActionButton,
  ResourcesHeroActions,
  ResourcesKpiStrip,
  ResourcesSectionHead,
} from "views/resources/components/ResourcesLuxShared";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import { PageDataSourceReporter } from "views/common/PageChromeContext";
import ResourceAllocationHeatmap from "views/resources/components/ResourceAllocationHeatmap";
import { DENSE_PAGE_META } from "config/dense-page-meta.config";

class ResourceUtilizationPage extends Component {
  state = {
    snapshot: null,
    loading: true,
    loadError: null,
    dataSource: null,
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Resource analytics");
    this.loadAnalytics();
  }

  loadAnalytics = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await resourcePlanningService.getResourceAnalytics();
      this.setState({
        snapshot: result.payload || null,
        loading: false,
        dataSource: result.source || null,
      });
    } catch (e) {
      this.setState({
        loading: false,
        loadError: "Unable to load resource analytics.",
        snapshot: null,
      });
    }
  };

  render() {
    if (!isResourcePlanningEnabled()) {
      return (
        <PersonaAccessDenied
          moduleName="Resources"
          reason="Resource planning is not enabled for your organization."
        />
      );
    }

    const { loading, loadError, dataSource, snapshot } = this.state;
    const metrics = (snapshot && snapshot.metrics) || {};
    const charts = (snapshot && snapshot.charts) || {};
    const insights = loading ? [] : (snapshot && snapshot.insights) || [];

    const kpiCards = [
      {
        id: "utilization",
        label: "Avg utilization",
        value: metrics.avgUtilizationPct != null ? `${metrics.avgUtilizationPct}%` : "—",
        hint: `${metrics.freeHours || 0} free hours`,
        tone: "primary",
        icon: "fe fe-activity",
      },
      {
        id: "demand",
        label: "Open demand",
        value: metrics.openDemandHeadcount != null ? metrics.openDemandHeadcount : "—",
        hint: `${metrics.openStaffingRequests || 0} staffing requests`,
        tone: metrics.supplyGap > 0 ? "rose" : "green",
        icon: "fe fe-users",
      },
      {
        id: "bench",
        label: "Bench pool",
        value: metrics.benchCount != null ? metrics.benchCount : "—",
        hint: `${metrics.rollingOffCount || 0} rolling off`,
        tone: "sky",
        icon: "fe fe-user-minus",
      },
      {
        id: "overbook",
        label: "Overallocated",
        value: metrics.overbookedCount != null ? metrics.overbookedCount : "—",
        hint: `${metrics.skillGapCount || 0} skill gaps`,
        tone: metrics.overbookedCount > 0 ? "amber" : "green",
        icon: "fe fe-alert-triangle",
      },
    ];

    const hasCharts =
      (charts.capacityVsDemand && charts.capacityVsDemand.length > 0) ||
      (charts.allocationByProject && charts.allocationByProject.length > 0) ||
      (charts.benchTrend && charts.benchTrend.length > 0) ||
      (charts.overallocatedUsers && charts.overallocatedUsers.length > 0) ||
      (charts.upcomingRolloffs && charts.upcomingRolloffs.length > 0) ||
      (charts.skillGaps && charts.skillGaps.length > 0);

    return (
      <div
        className="lux-resource-analytics-page lux-register-page lux-resource-analytics-lux"
        data-testid="page-resources-utilization"
      >
        <PageDataSourceReporter dataSource={dataSource} />
        <div className="lux-resource-analytics-lux__ambient" aria-hidden="true">
          <span className="lux-resource-analytics-lux__orb lux-resource-analytics-lux__orb--a" />
          <span className="lux-resource-analytics-lux__orb lux-resource-analytics-lux__orb--b" />
        </div>

        <LuxModuleIntro
          meta={DENSE_PAGE_META.resourceUtilization}
          className="lux-resource-analytics-hero"
          actions={
            <ResourcesHeroActions dataSource={dataSource}>
              <ResourcesActionButton
                icon="fe fe-refresh-cw"
                variant="ghost"
                onClick={this.loadAnalytics}
                disabled={loading}
              >
                Refresh
              </ResourcesActionButton>
              <ResourcesActionButton to="/project/capacity" icon="fe fe-pie-chart" variant="ghost">
                Team capacity
              </ResourcesActionButton>
              <ResourcesActionButton to="/resources/planner" icon="fe fe-sliders" variant="primary">
                Run simulation
              </ResourcesActionButton>
            </ResourcesHeroActions>
          }
        />

        <div className="lux-resource-analytics-page__body">
          <ResourcesKpiStrip
            cards={kpiCards}
            loading={loading}
            className="lux-resource-analytics-kpi-strip"
          />

          {loadError && (
            <div className="lux-employee-360__error lux-resource-analytics__error" role="alert">
              <span>{loadError}</span>
              <ResourcesActionButton variant="ghost" onClick={this.loadAnalytics}>
                Retry
              </ResourcesActionButton>
            </div>
          )}

          <AdminInsightStrip insights={insights} className="lux-resource-analytics-insights" />

          {loading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="Loading resource analytics"
              description="Aggregating capacity, demand, bench, and skill signals."
            />
          ) : (
            <>
              {hasCharts && (
                <section className="lux-hrms-dash__panel lux-resource-analytics-panel">
                  <ResourcesSectionHead
                    tone="indigo"
                    icon="fe fe-bar-chart-2"
                    eyebrow="Supply & demand"
                    title="Analytics charts"
                    subtitle={
                      snapshot && snapshot.snapshotDate
                        ? `Snapshot ${snapshot.snapshotDate} · utilization and planning signals`
                        : "Utilization and planning signals across the roster"
                    }
                  />
                  <div className="lux-resource-analytics__grid">
                    {charts.capacityVsDemand && charts.capacityVsDemand.length > 0 && (
                      <PolicyAnalyticsBarChart
                        title="Capacity vs demand"
                        subtitle="Allocated roster vs bench supply vs open roles"
                        series={charts.capacityVsDemand}
                      />
                    )}
                    {charts.allocationByProject && charts.allocationByProject.length > 0 && (
                      <PolicyAnalyticsBarChart
                        title="Allocation by project"
                        subtitle="Total allocation % across active engagements"
                        series={charts.allocationByProject}
                        suffix="%"
                      />
                    )}
                    {charts.benchTrend && charts.benchTrend.length > 0 && (
                      <PolicyAnalyticsBarChart
                        title="Bench trend"
                        subtitle="Consultants on bench over recent weeks"
                        series={charts.benchTrend}
                      />
                    )}
                    {charts.overallocatedUsers && charts.overallocatedUsers.length > 0 && (
                      <PolicyAnalyticsBarChart
                        title="Overallocated consultants"
                        subtitle="Total allocation % above 100"
                        series={charts.overallocatedUsers}
                        suffix="%"
                      />
                    )}
                    {charts.upcomingRolloffs && charts.upcomingRolloffs.length > 0 && (
                      <PolicyAnalyticsBarChart
                        title="Upcoming roll-offs"
                        subtitle="Availability % at project end"
                        series={charts.upcomingRolloffs}
                        suffix="%"
                      />
                    )}
                    {charts.skillGaps && charts.skillGaps.length > 0 && (
                      <PolicyAnalyticsBarChart
                        title="Skill gaps"
                        subtitle="Beginner / intermediate profiles"
                        series={charts.skillGaps}
                      />
                    )}
                  </div>
                </section>
              )}

              {charts.heatmap && charts.heatmap.length > 0 && (
                <section className="lux-hrms-dash__panel lux-resource-analytics-panel lux-resource-analytics-panel--heatmap">
                  <ResourcesSectionHead
                    tone="sky"
                    icon="fe fe-grid"
                    eyebrow="Load map"
                    title="Allocation heatmap"
                    subtitle="Per-consultant project load and utilization intensity"
                  />
                  <div className="lux-resource-analytics__heatmap-wrap">
                    <ResourceAllocationHeatmap rows={charts.heatmap} />
                  </div>
                </section>
              )}
            </>
          )}
        </div>
      </div>
    );
  }
}

export default ResourceUtilizationPage;
