import React, { Component } from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";
import CustomInput from "views/common/fragments/formfields/CustomInput";
import { entryHasAdditionalDetails } from "./timesheetDetail.utils";

class TimesheetCommentsPopover extends Component {
  constructor(props) {
    super(props);
    this.triggerRef = React.createRef();
    this.state = {
      open: false,
      panelStyle: null,
    };
  }

  componentDidUpdate(prevProps, prevState) {
    if (this.state.open && !prevState.open) {
      this.updatePanelPosition();
      window.addEventListener("resize", this.updatePanelPosition);
      window.addEventListener("scroll", this.updatePanelPosition, true);
    }
    if (!this.state.open && prevState.open) {
      window.removeEventListener("resize", this.updatePanelPosition);
      window.removeEventListener("scroll", this.updatePanelPosition, true);
    }
  }

  componentWillUnmount() {
    window.removeEventListener("resize", this.updatePanelPosition);
    window.removeEventListener("scroll", this.updatePanelPosition, true);
  }

  updatePanelPosition = () => {
    const trigger = this.triggerRef.current;
    if (!trigger || typeof window === "undefined") return;

    const rect = trigger.getBoundingClientRect();
    const panelWidth = Math.min(320, window.innerWidth - 24);
    let left = rect.right - panelWidth;
    if (left < 12) left = 12;
    if (left + panelWidth > window.innerWidth - 12) {
      left = window.innerWidth - panelWidth - 12;
    }

    let top = rect.bottom + 8;
    const maxTop = window.innerHeight - 340;
    if (top > maxTop) top = Math.max(12, rect.top - 340);

    this.setState({
      panelStyle: { top, left, width: panelWidth },
    });
  };

  stopCellHandlers = (event) => {
    if (event) {
      event.preventDefault();
      event.stopPropagation();
    }
  };

  toggleOpen = (event) => {
    this.stopCellHandlers(event);
    // Read-only with no notes: show disabled control, do not open.
    if (this.props.readOnly === true && !entryHasAdditionalDetails(this.props.timeEntryValues)) {
      return;
    }
    this.setState((prev) => ({ open: !prev.open, panelStyle: null }));
  };

  close = (event) => {
    this.stopCellHandlers(event);
    this.setState({ open: false });
  };

  onChange = (fieldName, value) => {
    if (this.props.readOnly) return;
    this.props.onFieldValueChange(fieldName, value, this.props.dateString);
  };

  renderPanel() {
    if (!this.state.open || typeof document === "undefined") return null;

    const { panelStyle } = this.state;
    const { timesheetType, timeEntryValues, projectFieldConfig, selectedEmployeeOption, readOnly } =
      this.props;

    return createPortal(
      <>
        <button type="button" className="lux-ts-comments-pop__backdrop" onClick={this.close} aria-label="Close" />
        <div
          className="lux-ts-comments-pop__panel"
          style={panelStyle}
          role="dialog"
          aria-label={readOnly ? "View entry comments" : "Entry comments"}
          onClick={(e) => e.stopPropagation()}
          onMouseDown={(e) => e.stopPropagation()}
        >
          <div className="lux-ts-comments-pop__head">
            <div>
              <strong>{readOnly ? "Comments" : "Comments & details"}</strong>
              <span>
                {readOnly
                  ? "Submitted notes for this day (read only)"
                  : "Add notes for this day's hours"}
              </span>
            </div>
            <button type="button" className="lux-ts-comments-pop__close" onClick={this.close} aria-label="Close">
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </div>
          <div className="lux-ts-comments-pop__body">
            <CustomInput
              type="textarea"
              label="Comments"
              name="comments"
              height="72px"
              fieldConfig={projectFieldConfig}
              mappingObject={timeEntryValues}
              onChange={this.onChange}
              placeholder={readOnly ? "No comments" : "What did you work on? Add context for reviewers…"}
              onFormError={this.props.onFormError}
              datatype="alpnumspl"
              readOnly={readOnly === true}
              disabled={readOnly === true}
            />
            {timesheetType === "project" && (
              <>
                <CustomInput
                  formClass="w-100p"
                  type="select"
                  label="Skill"
                  name="skill"
                  fieldConfig={projectFieldConfig}
                  mappingObject={timeEntryValues}
                  onChange={this.onChange}
                  placeholder="Skill…"
                  options={selectedEmployeeOption && this.props.getRestrictedSkillOptions()}
                  onFormError={this.props.onFormError}
                  readOnly={readOnly === true}
                  disabled={readOnly === true}
                />
                <CustomInput
                  formClass="w-100p"
                  type="text"
                  datatype="num"
                  label="Quantity"
                  name="quantity"
                  fieldConfig={projectFieldConfig}
                  mappingObject={timeEntryValues}
                  onChange={this.onChange}
                  placeholder="Quantity…"
                  onFormError={this.props.onFormError}
                  readOnly={readOnly === true}
                  disabled={readOnly === true}
                />
              </>
            )}
          </div>
          <div className="lux-ts-comments-pop__foot">
            <button type="button" className="lux-ts-comments-pop__done" onClick={this.close}>
              {readOnly ? "Close" : "Done"}
            </button>
          </div>
        </div>
      </>,
      document.body
    );
  }

  render() {
    const hasDetails = entryHasAdditionalDetails(this.props.timeEntryValues);
    const readOnly = this.props.readOnly === true;
    const triggerDisabled = readOnly && !hasDetails;
    const icon = hasDetails ? "fe-message-circle" : "fe-message-square";
    const title = readOnly
      ? hasDetails
        ? "View comments (read only)"
        : "No comments"
      : hasDetails
        ? "Edit comments"
        : "Add comments";

    return (
      <div
        className="lux-ts-comments-pop"
        onClick={this.stopCellHandlers}
        onMouseDown={this.stopCellHandlers}
      >
        <button
          ref={this.triggerRef}
          type="button"
          className={classNames("lux-ts-comments-pop__trigger", {
            "has-details": hasDetails,
            "is-open": this.state.open,
            "is-readonly": readOnly,
            "is-disabled": readOnly,
          })}
          onClick={this.toggleOpen}
          onMouseDown={this.stopCellHandlers}
          title={title}
          aria-expanded={this.state.open}
          aria-label={title}
          aria-disabled={readOnly}
          disabled={triggerDisabled}
        >
          <i className={classNames("fe", icon)} aria-hidden="true" />
        </button>
        {this.renderPanel()}
      </div>
    );
  }
}

export default TimesheetCommentsPopover;
