import React from "react";
import LuxListCountSkeleton from "views/common/fragments/LuxListCountSkeleton";
import classNames from "classnames/bind";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { formatEventTimeRange, getCalendarEventStatusMeta } from "./userCalendar.utils";

export default function LuxUserCalendarSidebar({
  upcoming,
  selectedEvent,
  onSelectEvent,
  viewModeLabel,
  isLoading,
}) {
  return (
    <aside className="lux-user-calendar-sidebar" aria-label="Upcoming events">
      <header className="lux-user-calendar-sidebar__head">
        <span className="lux-user-calendar-sidebar__eyebrow">Up next</span>
        <h3 className="lux-user-calendar-sidebar__title">Agenda preview</h3>
        <p className="lux-user-calendar-sidebar__hint">
          {isLoading ? <LuxListCountSkeleton width={120} /> : `${upcoming.length} upcoming · ${viewModeLabel}`}
        </p>
      </header>

      {upcoming.length > 0 ? (
        <ul className="lux-user-calendar-sidebar__list">
          {upcoming.map((event) => {
            const meta = getCalendarEventStatusMeta(event.status);
            const isSelected = selectedEvent && selectedEvent.id === event.id;
            return (
              <li key={event.id}>
                <button
                  type="button"
                  className={classNames("lux-user-calendar-sidebar__item", `is-${meta.tone}`, {
                    "is-selected": isSelected,
                  })}
                  onClick={() => onSelectEvent(event)}
                >
                  <div className="lux-user-calendar-sidebar__item-body">
                    <span className="lux-user-calendar-sidebar__item-time">
                      {formatEventTimeRange(event)}
                    </span>
                    <strong className="lux-user-calendar-sidebar__item-title">{event.title}</strong>
                    {event.desc && (
                      <span className="lux-user-calendar-sidebar__item-desc">{event.desc}</span>
                    )}
                  </div>
                  <span className={classNames("lux-user-calendar-sidebar__badge", `is-${meta.tone}`)}>
                    {meta.label}
                  </span>
                </button>
              </li>
            );
          })}
        </ul>
      ) : (
        !isLoading && (
          <LuxRegisterEmptyState
            variant="holidays"
            eyebrow="Clear horizon"
            title="Nothing upcoming"
            description="No events in this range match your filters. Try another week or switch the data mode."
            className="lux-user-calendar-sidebar__empty"
          />
        )
      )}
    </aside>
  );
}
