import React, { Component } from "react";
import { commonUtils } from "_helpers";
import {
  loadApprovalDelegationConfig,
  shouldUseApprovalDelegation,
} from "_helpers/approvalDelegation.config";
import { approvalDelegationService } from "_services/approvalDelegation.service";
import { ADMIN_PAGE_META } from "config/admin-page-meta.config";
import {
  mergeDelegationsForCalendar,
  summarizeDelegationCalendar,
} from "config/delegation-calendar.utils";
import {
  buildDelegationSummary,
} from "config/delegation-admin.utils";
import { isUniversalApprovalInboxEnabled } from "config/universal-approval.config";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxSegmentNav from "views/common/fragments/LuxSegmentNav";
import ApprovalDelegationPanel from "views/hrms/components/delegation/ApprovalDelegationPanel";
import DelegationCalendarPanel from "./components/delegation/DelegationCalendarPanel";
import DelegationActingRegister from "./components/delegation/DelegationActingRegister";
import AdminInsightsSummary from "views/admin/components/AdminInsightsSummary";
import {
  AdminActionButton,
  AdminPanelLink,
  AdminLuxPage,
} from "views/admin/components/AdminLuxShared";

class DelegationRulesPage extends Component {
  state = {
    moduleEnabled: shouldUseApprovalDelegation(),
    mine: [],
    acting: [],
    loading: true,
    loadError: null,
    calendarMonth: new Date(),
    activeTab: "manage",
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler(this.props.routeProp.name);
    loadApprovalDelegationConfig().then(() => {
      this.setState({ moduleEnabled: shouldUseApprovalDelegation() }, () => this.loadAll());
    });
  }

  loadAll = async () => {
    const enabled = shouldUseApprovalDelegation();
    this.setState({ moduleEnabled: enabled });
    const userId = commonUtils.getCurrentUserId();
    if (!userId || !enabled) {
      this.setState({ loading: false, mine: [], acting: [] });
      return;
    }

    this.setState({ loading: true, loadError: null });
    try {
      const [mineRes, actingRes] = await Promise.all([
        approvalDelegationService.listMine(userId),
        approvalDelegationService.listActing(userId),
      ]);
      this.setState({
        mine: (mineRes && mineRes.payload) || [],
        acting: (actingRes && actingRes.payload) || [],
        loading: false,
      });
    } catch (_error) {
      this.setState({
        loading: false,
        loadError: "Unable to load delegation coverage.",
        mine: [],
        acting: [],
      });
    }
  };

  renderHeroActions = () => (
    <>
      <AdminActionButton icon="fe fe-refresh-cw" onClick={this.loadAll} disabled={this.state.loading}>
        Refresh
      </AdminActionButton>
      {isUniversalApprovalInboxEnabled() && (
        <AdminActionButton to="/workspace/approvals" icon="fe fe-inbox" variant="ghost">
          Approval inbox
        </AdminActionButton>
      )}
      <AdminActionButton to="/admin/approval-policies" icon="fe fe-sliders" variant="ghost">
        Policies
      </AdminActionButton>
    </>
  );

  render() {
    const { moduleEnabled, mine, acting, loading, loadError, calendarMonth, activeTab } = this.state;
    const calendarDelegations = mergeDelegationsForCalendar(mine, acting);
    const calendarSummary = summarizeDelegationCalendar(calendarDelegations);
    const summary = loading ? null : buildDelegationSummary(mine, acting);
    const totalSpans = (mine || []).length + (acting || []).length;

    if (!moduleEnabled) {
      return (
        <AdminLuxPage
          pageMeta={ADMIN_PAGE_META.delegation}
          loading={loading}
          heroActions={this.renderHeroActions()}
          className="lux-register-page lux-delegation-admin-page"
        >
          <LuxRegisterEmptyState
            className="lux-register-empty--compact lux-leave-empty"
            title="Approval delegation is off"
            description="Enable approvalDelegationEnabled under approvalDelegation in Application Configuration, and grant adminModules.delegationEnabled in role.json."
          />
        </AdminLuxPage>
      );
    }

    return (
      <AdminLuxPage
        pageMeta={ADMIN_PAGE_META.delegation}
        loading={loading}
        heroActions={this.renderHeroActions()}
        className="lux-register-page lux-delegation-admin-page"
      >
        {loadError && (
          <div className="lux-employee-360__error lux-delegation-admin__error" role="alert">
            <span>{loadError}</span>
            <AdminActionButton variant="ghost" onClick={this.loadAll}>
              Retry
            </AdminActionButton>
          </div>
        )}

        <AdminInsightsSummary
          storageKey="famstack-delegation-summary-expanded"
          domainClass="lux-admin-summary--delegation"
          loading={loading}
          eyebrow="Coverage intelligence"
          eyebrowIcon="fe-user-check"
          title="Delegation insights"
          compactTitle={
            summary
              ? `${summary.metrics.totalSpans} spans · ${summary.metrics.activeOutgoing} active out · ${summary.metrics.actingActive || 0} acting`
              : "Delegation insights"
          }
          collapsedLine={
            summary
              ? `${summary.metrics.outgoing} outgoing · ${summary.metrics.incoming} incoming · ${summary.metrics.upcomingOutgoing} upcoming`
              : null
          }
          subtitle="Outgoing coverage, acting-for posture, and calendar span health."
          kpis={summary ? summary.kpis : []}
          highlights={summary ? summary.highlights : []}
          attention={summary ? summary.attention : []}
          mixInsights={summary ? summary.mixInsights : []}
          series={summary ? summary.series : []}
          testId="delegation-insights"
        />

        <section
          className="lux-admin-atelier lux-admin-atelier--delegation"
          data-testid="delegation-coverage"
        >
          <header className="lux-admin-atelier__masthead">
            <div className="lux-admin-atelier__masthead-main">
              <span className="lux-admin-atelier__mark" aria-hidden="true">
                <i className="fe fe-user-check" />
              </span>
              <div>
                <p className="lux-admin-atelier__eyebrow">Coverage control</p>
                <h2 className="lux-admin-atelier__title">Delegation coverage</h2>
                <p className="lux-admin-atelier__lede">
                  Manage outgoing delegates and review managers you are acting for.
                </p>
              </div>
            </div>
            <div className="lux-admin-atelier__masthead-aside">
              <AdminPanelLink to="/admin/approval-policies">Approval policies</AdminPanelLink>
              <span className="lux-admin-atelier__count">
                <strong>{totalSpans}</strong>
                <em>spans</em>
              </span>
            </div>
          </header>

          <div className="lux-admin-atelier__body">
            <DelegationCalendarPanel
              delegations={calendarDelegations}
              monthDate={calendarMonth}
              onMonthChange={(date) => this.setState({ calendarMonth: date })}
              loading={loading}
            />

            <div className="lux-admin-atelier__stage-card">
              <header className="lux-hrms-dash__panel-head lux-delegation-panel__tabs-head">
                <LuxSegmentNav
                  items={[
                    { id: "manage", label: "My delegations", icon: "fe fe-user-plus" },
                    { id: "acting", label: "Acting for me", icon: "fe fe-shield", count: acting.length },
                  ]}
                  activeId={activeTab}
                  onChange={(next) => this.setState({ activeTab: next })}
                  ariaLabel="Delegation views"
                  tabList
                  testId="delegation-view-nav"
                />
              </header>

              <div className="lux-hrms-dash__panel-body">
                {activeTab === "manage" && (
                  <div className="lux-delegation-admin__manage-wrap">
                    <ApprovalDelegationPanel
                      employee={{ id: commonUtils.getCurrentUserId() }}
                      onDelegationsLoaded={() => this.loadAll()}
                    />
                  </div>
                )}

                {activeTab === "acting" && (
                  <div className="lux-delegation-admin__acting-wrap">
                    <p className="lux-delegation-admin__acting-sub">
                      {calendarSummary.incoming} manager{calendarSummary.incoming === 1 ? "" : "s"} have delegated approvals to you.
                      Open the approval inbox to act with an acting-for badge.
                    </p>
                    <DelegationActingRegister delegations={acting} loading={loading} />
                  </div>
                )}
              </div>
            </div>
          </div>
        </section>
      </AdminLuxPage>
    );
  }
}

export default DelegationRulesPage;
