import React, { Component } from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { ADMIN_PAGE_META } from "config/admin-page-meta.config";
import { isMaskingPolicyAdminEnabled } from "config/masking-policy.config";
import {
  buildMaskingLevelSeries,
  buildMaskingPolicyInsights,
  buildMaskingPolicyMetrics,
  filterMaskingPolicyRules,
} from "config/masking-policy.utils";
import { maskingPolicyService } from "_services/maskingPolicy.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import MaskingPolicyRegister from "views/admin/components/MaskingPolicyRegister";
import MaskingPolicyDetailPanel from "views/admin/components/MaskingPolicyDetailPanel";
import PolicyAnalyticsBarChart from "views/people/components/policy/PolicyAnalyticsBarChart";
import {
  AdminActionButton,
  AdminPanelHead,
  AdminPanelLink,
  AdminLuxPage,
} from "views/admin/components/AdminLuxShared";

const DOMAIN_FILTERS = ["ALL", "Payroll", "People", "Finance", "HR", "Documents", "Performance"];

class SecurityPolicyPage extends Component {
  state = {
    rules: [],
    loading: true,
    loadError: null,
    dataSource: null,
    domainFilter: "ALL",
    levelFilter: "ALL",
    query: "",
    selectedId: null,
    savingKey: null,
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Security settings");
    this.loadRules();
  }

  loadRules = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await maskingPolicyService.listRules();
      const rules = result.payload || [];
      this.setState({
        rules,
        loading: false,
        dataSource: result.source || null,
        selectedId: this.state.selectedId || (rules[0] && rules[0].id) || null,
      });
    } catch (e) {
      this.setState({
        loading: false,
        loadError: "Unable to load masking policy rules.",
        rules: [],
      });
    }
  };

  getFilteredRules = () => {
    const { rules, domainFilter, levelFilter, query } = this.state;
    return filterMaskingPolicyRules(rules, {
      domain: domainFilter,
      level: levelFilter,
      query,
    });
  };

  getSelectedRule = () => {
    const { rules, selectedId } = this.state;
    return rules.find((row) => row.id === selectedId) || null;
  };

  handleSetLevel = async (persona, level) => {
    const { selectedId } = this.state;
    if (!selectedId) return;
    const savingKey = `${selectedId}:${persona}`;
    this.setState({ savingKey });
    try {
      const result = await maskingPolicyService.updatePersonaLevel(selectedId, persona, level);
      const updated = result.payload;
      this.setState((prev) => ({
        rules: prev.rules.map((row) => (row.id === selectedId ? updated : row)),
        savingKey: null,
      }));
    } catch (e) {
      this.setState({ savingKey: null });
    }
  };

  renderInsights = () => {
    const { rules, loading } = this.state;
    if (loading) return null;
    const insights = buildMaskingPolicyInsights(rules);
    return (
      <div className="lux-mask-insights" role="list">
        {insights.map((insight) => (
          <article key={insight.id} className={classNames("lux-mask-insight-card", `is-${insight.tone}`)} role="listitem">
            <span className="lux-mask-insight-card__icon" aria-hidden="true">
              <i className={insight.icon} />
            </span>
            <div className="lux-mask-insight-card__copy">
              <strong>{insight.title}</strong>
              <p>{insight.copy}</p>
            </div>
          </article>
        ))}
      </div>
    );
  };

  render() {
    if (!isMaskingPolicyAdminEnabled()) {
      return (
        <PersonaAccessDenied
          moduleName="Security settings"
          reason="Sensitive field masking administration is not enabled for your organization."
        />
      );
    }

    const { loading, loadError, dataSource, domainFilter, levelFilter, query } = this.state;
    const filteredRules = this.getFilteredRules();
    const metrics = buildMaskingPolicyMetrics(this.state.rules);
    const levelSeries = buildMaskingLevelSeries(this.state.rules);

    const kpiCards = [
      { id: "rules", label: "Field rules", value: metrics.totalRules, hint: `${metrics.highRiskRules} high risk`, tone: "primary", icon: "fe fe-eye-off" },
      { id: "restricted", label: "Restricted", value: `${metrics.restrictedPct}%`, hint: "Persona grants masked/hidden", tone: "amber", icon: "fe fe-shield" },
      { id: "export", label: "Export gated", value: metrics.exportRestricted, hint: "Rules with export controls", tone: "blue", icon: "fe fe-download" },
      { id: "hidden", label: "Hidden grants", value: metrics.hiddenGrants, hint: "Across all personas", tone: "green", icon: "fe fe-lock" },
    ];

    return (
      <AdminLuxPage
        pageMeta={ADMIN_PAGE_META.security}
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        className="lux-register-page lux-mask-page"
        heroActions={
          <AdminActionButton icon="fe fe-refresh-cw" onClick={this.loadRules} disabled={loading}>
            Refresh
          </AdminActionButton>
        }
      >
        {loadError && (
          <div className="lux-employee-360__error lux-mask__error" role="alert">
            <span>{loadError}</span>
            <AdminActionButton variant="ghost" onClick={this.loadRules}>
              Retry
            </AdminActionButton>
          </div>
        )}

        {this.renderInsights()}

        <section className="lux-mask-analytics lux-hrms-dash__panel">
          <AdminPanelHead title="Masking distribution" subtitle="Visible vs masked vs hidden grants across persona rules." />
          <PolicyAnalyticsBarChart title="Level mix" subtitle="Persona grant counts" series={levelSeries} />
        </section>

        <section className="lux-hrms-dash__panel lux-mask-panel">
          <AdminPanelHead
            title="Field masking registry"
            subtitle="Select a sensitive field to set VISIBLE, MASKED, or HIDDEN per persona. Changes are audited when audit writes are enabled."
            actions={<AdminPanelLink to="/admin/data-retention">Data retention</AdminPanelLink>}
          />

          <div className="lux-mask-panel__toolbar">
            <div className="lux-appr-toolbar__row">
              <div className="lux-appr-toolbar__search">
                <i className="fe fe-search" aria-hidden="true" />
                <input
                  type="search"
                  className="lux-appr-toolbar__search-input"
                  placeholder="Search field name or key"
                  value={query}
                  onChange={(e) => this.setState({ query: e.target.value })}
                />
              </div>
              <span className="lux-appr-toolbar__count">
                <strong>{filteredRules.length}</strong> rule{filteredRules.length === 1 ? "" : "s"}
              </span>
            </div>
            <div className="lux-mask-panel__filters">
              <div className="lux-appr-toolbar__group">
                <span className="lux-appr-toolbar__label">Domain</span>
                <div className="lux-hrms-dash__filter-group">
                  {DOMAIN_FILTERS.map((value) => (
                    <button
                      key={value}
                      type="button"
                      className={classNames("lux-hrms-dash__filter-chip", { "is-active": domainFilter === value })}
                      onClick={() => this.setState({ domainFilter: value })}
                    >
                      {value === "ALL" ? "All" : value}
                    </button>
                  ))}
                </div>
              </div>
              <div className="lux-appr-toolbar__group">
                <span className="lux-appr-toolbar__label">Level</span>
                <div className="lux-hrms-dash__filter-group">
                  {["ALL", "VISIBLE", "MASKED", "HIDDEN"].map((value) => (
                    <button
                      key={value}
                      type="button"
                      className={classNames("lux-hrms-dash__filter-chip", { "is-active": levelFilter === value })}
                      onClick={() => this.setState({ levelFilter: value })}
                    >
                      {value === "ALL" ? "All" : value.charAt(0) + value.slice(1).toLowerCase()}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>

          <div className="lux-mask-panel__body">
            <div className="lux-mask-panel__grid">
              <div className="lux-mask-panel__register">
                {loading ? (
                  <LuxRegisterEmptyState title="Loading rules" description="Fetching masking policy registry." />
                ) : filteredRules.length === 0 ? (
                  <LuxRegisterEmptyState title="No rules match" description="Adjust filters or search." />
                ) : (
                  <MaskingPolicyRegister
                    rules={filteredRules}
                    selectedId={this.state.selectedId}
                    onSelect={(rule) => this.setState({ selectedId: rule.id })}
                  />
                )}
              </div>
              <MaskingPolicyDetailPanel
                rule={this.getSelectedRule()}
                savingKey={this.state.savingKey}
                onSetLevel={this.handleSetLevel}
              />
            </div>
          </div>
        </section>
      </AdminLuxPage>
    );
  }
}

export default SecurityPolicyPage;
