/**
 * Named GA4 domain events for product actions.
 * Prefer these over raw trackEvent strings so reports stay stable.
 */
import { trackEvent } from "_helpers/analytics.utils";

export const AnalyticsEvents = {
  LEAVE_CREATE: "leave_create",
  LEAVE_SUBMIT: "leave_submit",
  LEAVE_APPROVE: "leave_approve",
  LEAVE_REJECT: "leave_reject",
  LEAVE_WITHDRAW: "leave_withdraw",
  LEAVE_CANCEL: "leave_cancel",

  ATTENDANCE_MARK: "attendance_mark",
  ATTENDANCE_APPROVE: "attendance_approve",
  ATTENDANCE_REJECT: "attendance_reject",
  ATTENDANCE_REG_SUBMIT: "attendance_reg_submit",
  ATTENDANCE_REG_APPROVE: "attendance_reg_approve",
  ATTENDANCE_REG_REJECT: "attendance_reg_reject",

  TIMESHEET_SUBMIT: "timesheet_submit",
  TIMESHEET_RESUBMIT: "timesheet_resubmit",
  TIMESHEET_APPROVE: "timesheet_approve",
  TIMESHEET_REJECT: "timesheet_reject",
  TIMESHEET_REJECT_LINE: "timesheet_reject_line",
  TIMESHEET_LOCK: "timesheet_lock",
  TIMESHEET_REOPEN: "timesheet_reopen",

  APPROVAL_INBOX_APPROVE: "approval_inbox_approve",
  APPROVAL_INBOX_REJECT: "approval_inbox_reject",

  DELEGATION_CREATE: "delegation_create",
  DELEGATION_UPDATE: "delegation_update",
  DELEGATION_REVOKE: "delegation_revoke",

  HOLIDAY_CREATE: "holiday_create",
  HOLIDAY_UPDATE: "holiday_update",
  HOLIDAY_DELETE: "holiday_delete",
};

/**
 * @param {string} eventName
 * @param {string} category
 * @param {string} [label]
 * @param {object} [extra]
 */
export function trackDomainEvent(eventName, category, label = "", extra = {}) {
  trackEvent(eventName, category, label, undefined, {
    domain_event: eventName,
    ...extra,
  });
}

export function trackLeaveAction(action, leaveId) {
  trackDomainEvent(action, "leave", leaveId != null ? String(leaveId) : "", {
    entity: "leave",
  });
}

export function trackAttendanceAction(action, attendanceId) {
  trackDomainEvent(action, "attendance", attendanceId != null ? String(attendanceId) : "", {
    entity: "attendance",
  });
}

export function trackTimesheetAction(action, weekId) {
  trackDomainEvent(action, "timesheet", weekId != null ? String(weekId) : "", {
    entity: "timesheet_week",
  });
}

export function trackApprovalInboxAction(action, domain, sourceId) {
  trackDomainEvent(action, "approval", `${domain || "unknown"}:${sourceId || ""}`, {
    entity: "approval_inbox",
    approval_domain: domain || undefined,
  });
}

export function trackDelegationAction(action, delegationId) {
  trackDomainEvent(action, "delegation", delegationId != null ? String(delegationId) : "", {
    entity: "approval_delegation",
  });
}

export function trackHolidayAction(action, holidayId) {
  trackDomainEvent(action, "holiday", holidayId != null ? String(holidayId) : "", {
    entity: "holiday",
  });
}
