import React, { Component } from "react";
import { connect } from "react-redux";
import { Link } from "react-router-dom";
import { employeeActions, notificationActions, timesheetApprovalActions, workItemActions } from "_actions";
import { workItemConstants } from "_constants";
import { accessUtils, commonUtils, store } from "_helpers";
import dateUtils from "_helpers/date.utils";
import workItemUtils from "_helpers/workitem.utils";
import ProjectDetailsTabShell from "views/project/components/ProjectDetailsTabShell";
import LuxCalendarNav from "views/common/fragments/LuxCalendarNav";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import TimesheetSummaryPanel from "views/hrms/components/timesheet/TimesheetSummaryPanel";
import TimesheetPageInputItem from "views/hrms/TimesheetPageInputItem";
import TimesheetLockBanner from "views/hrms/components/timesheet/TimesheetLockBanner";
import CollapsibleAuditPanel from "views/common/fragments/CollapsibleAuditPanel";
import { AUDIT_ENTITY_TYPES, AUDIT_SCOPES } from "_constants/audit.constants";
import { isManagerTimesheetApprover, canReopenTimesheetWeek } from "views/hrms/components/timesheet/timesheetApproval.utils";
import {
  canAddTimesheetEntry,
  isResubmitAction,
  isTimesheetApprovalWorkflowActive,
} from "_helpers/timesheetWorkflow.utils";
import { loadTimesheetApprovalConfig } from "_helpers/timesheetApproval.config";
import { timesheetApprovalService } from "_services/timesheetApproval.service";
import {
  buildTimesheetTabStats,
  isEmployee360ViewingSelf,
} from "config/employee360Tab.utils";
import { getEmployeeDisplayName } from "config/employee360.utils";

class Employee360TimesheetsTab extends Component {
  timesheetLoadSeq = 0;

  state = {
    selectedDate: dateUtils.getCurrentTime(),
    applicableDates: {},
    timeSheetRequest: null,
    permission: accessUtils.getTimeSheetAccessControl(),
    addEntryOpen: false,
    addEntrySession: 0,
    submitInProgress: false,
    unlockInProgress: false,
    reopenInProgress: false,
  };

  componentDidMount() {
    const userTeams = commonUtils.getUserTeams(this.props.userTeams);
    store.dispatch({ type: workItemConstants.INITIALIZE_TIME_SHEET_USER_TEAMS, userTeams });
    this.loadEmployeeList(userTeams);
    loadTimesheetApprovalConfig().then(() => {
      this.setState({ permission: accessUtils.getTimeSheetAccessControl() });
    });
    this.handleDateChange(this.state.selectedDate, this.props.employee);
  }

  componentDidUpdate(prevProps) {
    const prevId = prevProps.employee && prevProps.employee.id;
    const nextId = this.props.employee && this.props.employee.id;
    if (prevId !== nextId && this.props.employee) {
      this.handleDateChange(this.state.selectedDate, this.props.employee);
    }
  }

  loadEmployeeList = (userTeams) => {
    store.dispatch(
      this.props.getTeamsEmployees(commonUtils.getSelectedUserTeamIds(userTeams))
    );
  };

  updateTimeSheetRequest = (timeSheetRequest) => {
    this.setState({ timeSheetRequest });
  };

  handleDateChange = (date, employeeOverride) => {
    const employee = employeeOverride || this.props.employee;
    if (!employee || !employee.id) {
      return;
    }

    const startDate = date.clone().startOf("isoWeek");
    const endDate = date.clone().endOf("isoWeek");
    const loadSeq = ++this.timesheetLoadSeq;
    const userTeamIds = this.resolveTimesheetUserTeamIds();

    store.dispatch(
      this.props.loadTimeSheetData(
        startDate.format(dateUtils.SERVER_DATE_FORMAT),
        endDate.format(dateUtils.SERVER_DATE_FORMAT),
        [employee.id],
        userTeamIds,
        (timesheetResponse) => {
          if (loadSeq !== this.timesheetLoadSeq) {
            return;
          }
          this.updateTimeSheetRequest(timesheetResponse);
        }
      )
    );

    this.setState({
      selectedDate: date,
      timeSheetRequest: null,
      applicableDates: {
        currentWeekDates: dateUtils
          .getCurrentWeekDateArray(date)
          .map((dateObject) => dateObject.value),
        workItemMinDates: workItemUtils.getWorkItemCreateStartMinDate(
          startDate,
          this.state.permission
        ),
        workItemMaxDates: workItemUtils.getWorkItemCreateEndMaxDate(
          endDate,
          this.state.permission
        ),
      },
    });
  };

  goToNext = () => {
    this.handleDateChange(dateUtils.addXDays(this.state.selectedDate, 7));
  };

  goToBack = () => {
    this.handleDateChange(dateUtils.substractXDays(this.state.selectedDate, 7));
  };

  goToCurrent = () => {
    this.handleDateChange(dateUtils.getCurrentTime());
  };

  createItemClickHandler = () => {
    if (this.state.addEntryOpen) {
      return;
    }
    if (!canAddTimesheetEntry(this.state.timeSheetRequest, this.state.permission)) {
      return;
    }
    this.setState((prevState) => ({
      addEntryOpen: true,
      addEntrySession: prevState.addEntrySession + 1,
    }));
  };

  cancelShowSelectionWindow = () => {
    this.setState({ addEntryOpen: false });
  };

  resolveTimesheetUserTeamIds = () => {
    const selected = commonUtils.getSelectedUserTeamIds(
      commonUtils.getUserTeams(this.props.userTeams)
    );
    if (selected && selected.length) {
      return selected;
    }
    const all = commonUtils.getCurrentUserTeamIds();
    if (all && all.length) {
      return all;
    }
    const current = commonUtils.getCurrentUserTeamId();
    return current != null ? [current] : [];
  };

  handleUpdateTimeSheet = (submitCallBackFunction) => {
    const { selectedDate, timeSheetRequest } = this.state;
    const employee = this.props.employee;
    if (!employee || !employee.id) {
      return;
    }
    const startDate = selectedDate.clone().startOf("isoWeek").format(dateUtils.SERVER_DATE_FORMAT);
    const endDate = selectedDate.clone().endOf("isoWeek").format(dateUtils.SERVER_DATE_FORMAT);
    const userTeamIds = this.resolveTimesheetUserTeamIds();
    if (!userTeamIds.length) {
      store.dispatch(
        notificationActions.error(
          "Cannot save timesheet: no team is selected. Set your default team and try again."
        )
      );
      return;
    }
    store.dispatch(
      this.props.addTimesheetData(
        startDate,
        endDate,
        [employee.id],
        commonUtils.getCurrentUserId(),
        userTeamIds,
        timeSheetRequest,
        (payload) => {
          this.updateTimeSheetRequest(payload);
          if (typeof submitCallBackFunction === "function") {
            submitCallBackFunction(payload);
          }
          if (
            payload &&
            !payload.weekId &&
            isTimesheetApprovalWorkflowActive(payload, this.state.permission)
          ) {
            store.dispatch(
              notificationActions.warning(
                "Draft saved, but approval staging did not return a week id. Confirm timesheet approval is enabled for this team in Application Configuration."
              )
            );
          }
        }
      )
    );
  };

  handleSubmitTimesheet = (timeSheetOverride) => {
    const { selectedDate, permission } = this.state;
    const timeSheetRequest = timeSheetOverride || this.state.timeSheetRequest;
    if (!isTimesheetApprovalWorkflowActive(timeSheetRequest, permission)) {
      store.dispatch(
        notificationActions.warning(
          "Timesheet approval is disabled for this team. Save timesheet directly — submit is not required."
        )
      );
      return;
    }
    if (!timeSheetRequest || !timeSheetRequest.weekId) {
      store.dispatch(
        notificationActions.warning("Save your draft before submitting for approval.")
      );
      return;
    }
    const actorId = commonUtils.getCurrentUserId();
    const submitFn = isResubmitAction(timeSheetRequest)
      ? timesheetApprovalService.resubmitWeek
      : timesheetApprovalService.submitWeek;

    this.setState({ submitInProgress: true });
    submitFn(timeSheetRequest.weekId, actorId)
      .then(() => {
        store.dispatch(notificationActions.success("Timesheet submitted for approval."));
        this.handleDateChange(selectedDate);
      })
      .catch((error) => {
        const message =
          (error && error.message) || error || "Unable to submit timesheet.";
        store.dispatch(notificationActions.error(message));
      })
      .finally(() => {
        this.setState({ submitInProgress: false });
      });
  };

  resetTimeSheet = () => {
    this.handleDateChange(this.state.selectedDate);
  };

  handleUnlockCurrentWeek = () => {
    const { timeSheetRequest, selectedDate } = this.state;
    if (!timeSheetRequest || !timeSheetRequest.weekId) {
      return;
    }
    const actorId = commonUtils.getCurrentUserId();
    this.setState({ unlockInProgress: true });
    store
      .dispatch(
        timesheetApprovalActions.unlockWeeks({
          actorId,
          weekIds: [timeSheetRequest.weekId],
        })
      )
      .then(() => {
        this.handleDateChange(selectedDate);
      })
      .finally(() => {
        this.setState({ unlockInProgress: false });
      });
  };

  handleReopenCurrentWeek = () => {
    const { timeSheetRequest, selectedDate } = this.state;
    if (!timeSheetRequest || !timeSheetRequest.weekId) {
      return;
    }
    const actorId = commonUtils.getCurrentUserId();
    this.setState({ reopenInProgress: true });
    store
      .dispatch(timesheetApprovalActions.reopenWeek(timeSheetRequest.weekId, actorId))
      .then(() => {
        this.handleDateChange(selectedDate);
      })
      .finally(() => {
        this.setState({ reopenInProgress: false });
      });
  };

  render() {
    const { employee, timesheetLoading, employees } = this.props;
    const {
      selectedDate,
      applicableDates,
      timeSheetRequest,
      permission,
      addEntryOpen,
      addEntrySession,
      submitInProgress,
      unlockInProgress,
      reopenInProgress,
    } = this.state;

    if (!employee) {
      return null;
    }

    const isViewingSelf = isEmployee360ViewingSelf(employee, commonUtils.getCurrentUserId());
    const displayName = getEmployeeDisplayName(employee);
    const stats = buildTimesheetTabStats(timeSheetRequest, selectedDate);
    const isBoardLoading = !timeSheetRequest;
    const isManager = isManagerTimesheetApprover(permission);
    const canReopen = canReopenTimesheetWeek(permission, null, {
      viewingOwnWeek: isViewingSelf,
      timeSheetData: timeSheetRequest,
      currentUserId: commonUtils.getCurrentUserId(),
      employeeManagerId: employee && employee.managerId,
    });
    const canAddEntry = canAddTimesheetEntry(timeSheetRequest, permission);
    const weekStart = selectedDate.clone().startOf("isoWeek");
    const weekEnd = selectedDate.clone().endOf("isoWeek");
    const weekLabel = `${weekStart.format("MMM D")} – ${weekEnd.format("MMM D, YYYY")}`;

    return (
      <ProjectDetailsTabShell
        icon="fe fe-calendar"
        eyebrow="Project time"
        title="Timesheets"
        subtitle={
          isViewingSelf
            ? "Weekly time entries, submission status, and approval trail."
            : `Weekly timesheet for ${displayName}.`
        }
        stats={stats}
        className="lux-employee-360__embed lux-employee-360__embed--timesheet"
      >
        <div className="lux-employee-360__embed-toolbar">
          <strong className="lux-employee-360__embed-period">{weekLabel}</strong>
          <LuxCalendarNav
            onBack={this.goToBack}
            onToday={this.goToCurrent}
            onNext={this.goToNext}
            disabled={timesheetLoading}
          />
          <Link to="/people/timesheet" className="lux-employee-360__embed-link">
            Open full timesheet
            <i className="fe fe-external-link" aria-hidden="true" />
          </Link>
        </div>

        <TimesheetSummaryPanel
          timeSheetData={timeSheetRequest}
          applicableDates={applicableDates}
          loading={timesheetLoading}
          addEntryOpen={addEntryOpen}
          employees={employees}
        />

        <TimesheetLockBanner
          timeSheetData={timeSheetRequest}
          canUnlock={isManager || canReopen}
          unlockInProgress={unlockInProgress}
          onUnlock={this.handleUnlockCurrentWeek}
          canReopen={canReopen}
          reopenInProgress={reopenInProgress}
          onReopen={this.handleReopenCurrentWeek}
        />

        <div className="lux-ts-page__grid-shell lux-employee-360__timesheet-board">
          {isBoardLoading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact lux-employee-360__embed-empty"
              title="Loading timesheet"
              description="Fetching weekly entries for this employee."
            />
          ) : (
            <TimesheetPageInputItem
              permission={permission}
              timeSheetRequest={timeSheetRequest || {}}
              onChange={this.updateTimeSheetRequest}
              showSelectionWindow={addEntryOpen}
              addEntrySession={addEntrySession}
              addEntryOpen={addEntryOpen}
              onOpenAddEntry={canAddEntry ? this.createItemClickHandler : undefined}
              cancelShowSelectionWindow={this.cancelShowSelectionWindow}
              selectedEmployee={employee}
              resetTimeSheet={this.resetTimeSheet}
              handleUpdateTimeSheet={this.handleUpdateTimeSheet}
              handleSubmitTimesheet={this.handleSubmitTimesheet}
              submitInProgress={submitInProgress}
              applicableDates={applicableDates}
              startOfTheWeek={selectedDate && dateUtils.getStartOftheWeek(selectedDate)}
            />
          )}
        </div>

        <div className="lux-page-audit-footer lux-employee-360__embed-audit">
          <CollapsibleAuditPanel
            panelKey={`employee-360-timesheet-${employee.id}`}
            title={isViewingSelf ? "Your timesheet audit" : `${displayName}'s timesheet audit`}
            subtitle="Submissions, resubmissions, and approval decisions"
            icon="fe-activity"
            auditProps={{
              scope: AUDIT_SCOPES.ACTOR,
              actorUserId: employee.id,
              lockedEntityFilter: AUDIT_ENTITY_TYPES.TIMESHEET_WEEK,
              showEntityFilters: false,
              emptyState: {
                eyebrow: "Timesheet actions",
                title: "No timesheet audit events yet",
                description:
                  "Submissions and approval decisions will appear here when audit logging is enabled.",
              },
            }}
          />
        </div>
      </ProjectDetailsTabShell>
    );
  }
}

const mapStateToProps = (state) => ({
  timesheetLoading: state.workItem.timesheetLoading,
  userTeams: state.workItem.userTeamsTimesheet,
  employees:
    state.employees.teamEmployees &&
    commonUtils.getActiveEmployees(state.employees.teamEmployees),
});

const mapDispatchToProps = () => ({
  loadTimeSheetData: workItemActions.loadTimeSheetData,
  addTimesheetData: workItemActions.addTimesheetData,
  getTeamsEmployees: employeeActions.getTeamsEmployees,
});

export default connect(mapStateToProps, mapDispatchToProps)(Employee360TimesheetsTab);
