import React, { Component } from 'react';
import { Link } from 'react-router-dom';
import classNames from 'classnames/bind';
import { accessUtils, commonUtils, store } from '_helpers';
import { getApiErrorMessage } from '_helpers/apiError.utils';
import { employeeConstants } from '_constants';
import {
  resolveLeaveWriteUserTeamId,
  resolveLeaveUserTeamIds,
  buildLeaveUserTeamsAllSelected,
} from '_helpers/leave.config';
import PageInnerHeader from 'views/common/PageInnerHeader';
import LuxRegisterEmptyState from 'views/common/fragments/LuxRegisterEmptyState';
import { AdminActionButton, AdminLuxPage } from 'views/admin/components/AdminLuxShared';

export function mapLeavePhase2State(state) {
  return {
    userTeams: state.employees && (state.employees.userTeamsA || state.employees.userTeams),
  };
}

export function cell(value) {
  if (value == null || value === '') return '—';
  if (typeof value === 'boolean') return value ? 'Yes' : 'No';
  if (typeof value === 'object') return JSON.stringify(value);
  return String(value);
}

export function renderLeavePhase2Nav(tabs, pathname) {
  return (
    <nav className="lux-glp-tabs" aria-label="Section navigation">
      {tabs.map((item) => {
        const isActive = item.exact
          ? pathname === item.path || pathname === `${item.path}/`
          : pathname === item.path || pathname.startsWith(`${item.path}/`);
        return (
          <Link
            key={item.path}
            to={item.path}
            className={classNames('lux-glp-tab', { 'is-active': isActive })}
          >
            {item.icon ? <i className={item.icon} aria-hidden="true" /> : null} {item.label}
          </Link>
        );
      })}
    </nav>
  );
}

export function LeavePhase2Panel({ eyebrow, title, subtitle, actions, children, testId }) {
  return (
    <section
      className="lux-hrms-dash__panel lux-leave-subpanel lux-leave-policy__section"
      aria-label={title}
      {...(testId ? { 'data-testid': testId } : {})}
    >
      <header className="lux-leave-subpanel__head">
        <div>
          {eyebrow ? <span className="lux-leave-subpanel__eyebrow">{eyebrow}</span> : null}
          <h3 className="lux-leave-subpanel__title">{title}</h3>
          {subtitle ? <p className="lux-leave-subpanel__sub">{subtitle}</p> : null}
        </div>
        {actions ? <div className="lux-glp-actions">{actions}</div> : null}
      </header>
      {children}
    </section>
  );
}

/** Honest empty copy for Phase-2 registers (no fake self-serve CTAs). */
export const LEAVE_PHASE2_EMPTY_DESCRIPTION =
  'No rows yet. Use Add when available, or ask an admin to seed via API.';

export function LeavePhase2Register({ loading, rows, columns, emptyTitle, emptyDescription, testId }) {
  if (loading) {
    return (
      <div className="lux-leave-register__skeleton" aria-busy="true">
        Loading…
      </div>
    );
  }
  if (!rows || !rows.length) {
    return (
      <LuxRegisterEmptyState
        className="lux-register-empty--compact lux-leave-empty"
        icon="fe fe-inbox"
        title={emptyTitle || 'Nothing here yet'}
        description={emptyDescription || LEAVE_PHASE2_EMPTY_DESCRIPTION}
        data-testid={testId ? `${testId}-empty` : undefined}
      />
    );
  }
  return (
    <div className="lux-leave-register-wrap">
      <table className="lux-leave-register" data-testid={testId}>
        <thead>
          <tr>
            {columns.map((col) => (
              <th key={col.key}>{col.label}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((row, idx) => (
            <tr key={row.id != null ? row.id : `row-${idx}`} className="lux-leave-register__row">
              {columns.map((col) => (
                <td key={col.key}>
                  {col.render ? col.render(row) : cell(row[col.key])}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export class LeavePhase2AdminBase extends Component {
  state = {
    loading: true,
    error: null,
    notice: null,
    leaveUserTeams: null,
  };

  teamId = () => resolveLeaveWriteUserTeamId(this.getLeaveUserTeams());

  actorId = () => commonUtils.getCurrentUserId();

  resolveTeamIds = () => resolveLeaveUserTeamIds(this.getLeaveUserTeams());

  getLeaveUserTeams = () => {
    if (this.state.leaveUserTeams && this.state.leaveUserTeams.length) {
      return this.state.leaveUserTeams;
    }
    return commonUtils.getUserTeams(this.props.userTeams);
  };

  leaveTeamMenuPermission = () => {
    const leave = accessUtils.getLeaveAccessControl() || {};
    const teams = this.getLeaveUserTeams();
    return {
      ...leave,
      switchUserTeamsEnabled: leave.switchUserTeamsEnabled === true || teams.length > 1,
    };
  };

  handleTeamsChange = (userTeams) => {
    store.dispatch({
      type: employeeConstants.INITIALIZE_EMPLOYEE_ATTENDANCE_USER_TEAMS,
      userTeams,
    });
    this.setState({ leaveUserTeams: userTeams }, () => this.loadAll());
  };

  initTeams = () => {
    const seeded = buildLeaveUserTeamsAllSelected(this.props.userTeams);
    if (seeded.length && !this.state.leaveUserTeams) {
      this.setState({ leaveUserTeams: seeded });
    }
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler && this.props.routeProp) {
      this.props.pageHeaderNameChangeHandler(this.props.routeProp.name || '');
    }
    this.initTeams();
    this.loadAll();
  }

  componentDidUpdate(prevProps) {
    if (prevProps.location.pathname !== this.props.location.pathname) {
      this.loadAll();
    }
  }

  loadAll = async () => {
    const teamId = this.teamId();
    if (!teamId) {
      this.setState({ loading: false, error: null });
      return;
    }
    this.setState({ loading: true, error: null });
    try {
      await this.fetchSectionData(teamId);
      this.setState({ loading: false });
    } catch (e) {
      this.setState({
        loading: false,
        error: getApiErrorMessage(e, 'Failed to load leave data.'),
      });
    }
  };

  fetchSectionData = async () => {
    throw new Error('fetchSectionData must be implemented by subclass');
  };

  renderErrorBanner() {
    const { error } = this.state;
    if (!error) return null;
    return (
      <div className="lux-glp-banner is-error" role="alert">
        <i className="fe fe-alert-circle" aria-hidden="true" />
        <span>{error}</span>
        <button type="button" onClick={this.loadAll}>
          Retry
        </button>
        <button type="button" onClick={() => this.setState({ error: null })} aria-label="Dismiss">
          <i className="fe fe-x" aria-hidden="true" />
        </button>
      </div>
    );
  }

  renderNoticeBanner() {
    const { notice } = this.state;
    if (!notice) return null;
    return (
      <div className="lux-glp-banner is-ok" role="status">
        <i className="fe fe-check-circle" aria-hidden="true" />
        <span>{notice}</span>
        <button type="button" onClick={() => this.setState({ notice: null })} aria-label="Dismiss">
          <i className="fe fe-x" aria-hidden="true" />
        </button>
      </div>
    );
  }

  renderChrome({ pageMeta, testId, heroNav, heroActions, kpiCards, children, className }) {
    const { loading } = this.state;
    return (
      <AdminLuxPage
        testId={testId}
        className={classNames('lux-register-page lux-leave-page lux-leave-phase2-page', className)}
        dataSource="api"
        loading={loading}
        kpiCards={kpiCards}
        pageMeta={pageMeta}
        heroNav={heroNav}
        heroActions={
          heroActions || (
            <AdminActionButton icon="fe fe-refresh-cw" onClick={this.loadAll} disabled={loading}>
              Refresh
            </AdminActionButton>
          )
        }
      >
        <PageInnerHeader
          userTeams={this.getLeaveUserTeams()}
          handleUserTeamsSelection={this.handleTeamsChange}
          showUserTeamMenu={true}
          showFilter={false}
          isLoading={loading}
          permission={this.leaveTeamMenuPermission()}
        />
        {this.renderErrorBanner()}
        {this.renderNoticeBanner()}
        {children}
      </AdminLuxPage>
    );
  }
}
