import React, { useMemo } from "react";
import classNames from "classnames/bind";
import DashboardApexChart from "../dashboard/DashboardApexChart";
import TimesheetLuxuryDialog from "./TimesheetLuxuryDialog";
import {
  buildDayDetailModel,
  buildDayMixDonutChart,
  buildDayTargetGaugeChart,
} from "./timesheetDetail.utils";
import { convertMinsToDisplay } from "./timesheetSummary.utils";

function TimesheetDayDetailModal({ show, dateString, timeSheetRequest, weekDates, onClose }) {
  const model = useMemo(
    () => (show && dateString ? buildDayDetailModel(timeSheetRequest, dateString, weekDates) : null),
    [show, dateString, timeSheetRequest, weekDates]
  );

  const mixChart = useMemo(() => (model ? buildDayMixDonutChart(model) : null), [model]);
  const gaugeChart = useMemo(() => (model ? buildDayTargetGaugeChart(model) : null), [model]);

  if (!model) return null;

  const badgeTone =
    model.targetLevel === "target"
      ? "green"
      : model.targetLevel === "over"
        ? "rose"
        : model.targetLevel === "under"
          ? "amber"
          : "slate";

  return (
    <TimesheetLuxuryDialog
      show={show}
      onClose={onClose}
      wide
      ariaLabel="Daily timesheet summary"
      kicker={model.isToday ? "Today" : "Day summary"}
      kickerIcon={model.isToday ? "fe-sun" : "fe-calendar"}
      title={model.title}
      subtitle={`${model.entryCount} ${model.entryCount === 1 ? "entry" : "entries"} · ${model.gapDisplay}`}
      badge={{ label: model.totalDisplay, tone: badgeTone }}
      footer={
        <p className="lux-ts-detail__foot-note">
          {model.isWeekend
            ? "Weekend day — targets may differ by policy."
            : "Aim for 8 hours of logged time on standard workdays."}
        </p>
      }
    >
      <div className="lux-ts-detail__kpi-grid">
        <article className={classNames("lux-ts-detail__kpi", `is-${badgeTone}`)}>
          <span>Total logged</span>
          <strong>{model.totalDisplay}</strong>
        </article>
        <article className="lux-ts-detail__kpi is-green">
          <span>Billable</span>
          <strong>{convertMinsToDisplay(model.billableMins)}</strong>
        </article>
        <article className="lux-ts-detail__kpi is-blue">
          <span>Non-billable</span>
          <strong>{convertMinsToDisplay(model.nonProjectMins)}</strong>
        </article>
        <article className="lux-ts-detail__kpi is-amber">
          <span>Leave / holiday</span>
          <strong>{convertMinsToDisplay(model.leaveMins)}</strong>
        </article>
      </div>

      <div className="lux-ts-detail__split lux-ts-detail__split--charts">
        <section className="lux-ts-detail__card lux-ts-detail__card--chart">
          <h4 className="lux-ts-detail__card-title">8-hour target</h4>
          <p className="lux-ts-detail__card-sub">Progress toward the daily goal</p>
          {gaugeChart && (
            <DashboardApexChart
              type="radialBar"
              series={gaugeChart.series}
              options={gaugeChart.options}
              height={240}
            />
          )}
        </section>

        <section className="lux-ts-detail__card lux-ts-detail__card--chart">
          <h4 className="lux-ts-detail__card-title">Time mix</h4>
          <p className="lux-ts-detail__card-sub">How hours split across categories</p>
          {mixChart ? (
            <DashboardApexChart type="donut" series={mixChart.series} options={mixChart.options} height={240} />
          ) : (
            <p className="lux-ts-detail__empty">No hours logged for this day.</p>
          )}
        </section>
      </div>

      <section className="lux-ts-detail__card">
        <h4 className="lux-ts-detail__card-title">Entries on this day</h4>
        <p className="lux-ts-detail__card-sub">All tasks and projects with time logged</p>
        {model.entries.length === 0 ? (
          <p className="lux-ts-detail__empty">No entries — this day is empty.</p>
        ) : (
          <ul className="lux-ts-detail__entry-list">
            {model.entries.map((entry, index) => (
              <li
                key={`${entry.timesheetType}-${entry.taskGroupId}-${index}`}
                className={classNames("lux-ts-detail__entry-item", {
                  "is-billable": entry.timesheetType === "project",
                  "is-leave": entry.leaveKind === "leave",
                  "is-holiday": entry.leaveKind === "holiday",
                })}
              >
                <div className="lux-ts-detail__entry-item-top">
                  <div>
                    <strong>{entry.label}</strong>
                    <span>{entry.groupLabel}</span>
                  </div>
                  <div className="lux-ts-detail__entry-item-right">
                    <strong>{entry.hoursDisplay}</strong>
                    <span className={classNames("lux-ts-detail__status-pill is-compact", `is-${entry.statusMeta.tone}`)}>
                      {entry.statusMeta.label}
                    </span>
                  </div>
                </div>
                {entry.comments && (
                  <p className="lux-ts-detail__comment">
                    <i className="fe fe-message-square" aria-hidden="true" />
                    {entry.comments}
                  </p>
                )}
              </li>
            ))}
          </ul>
        )}
      </section>
    </TimesheetLuxuryDialog>
  );
}

export default TimesheetDayDetailModal;
