import React from "react";
import classNames from "classnames/bind";

/**
 * Luxury checklist register for customer setup / implementation steps.
 */
export default function SetupChecklistRegister({ items, saving, onToggle }) {
  const rows = Array.isArray(items) ? items : [];

  if (!rows.length) {
    return null;
  }

  return (
    <ul className="lux-setup-checklist" data-testid="setup-checklist-register">
      {rows.map((row) => {
        const done = Boolean(row.done);
        return (
          <li
            key={row.id}
            className={classNames(
              "lux-setup-checklist__row",
              done && "is-done"
            )}
          >
            <label className="lux-setup-checklist__label">
              <input
                type="checkbox"
                className="lux-setup-checklist__check"
                checked={done}
                disabled={saving}
                onChange={() => onToggle && onToggle(row.id)}
                data-testid={`setup-checklist-${row.id}`}
              />
              <span className="lux-setup-checklist__copy">
                <span className="lux-setup-checklist__id">{row.id}</span>
                <span className="lux-setup-checklist__title">{row.label}</span>
              </span>
              <span
                className={classNames(
                  "lux-setup-checklist__badge",
                  done ? "is-done" : "is-open"
                )}
              >
                {done ? "Done" : "Open"}
              </span>
            </label>
          </li>
        );
      })}
    </ul>
  );
}
