import React, { Component } from "react";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import {
  isResourcePlanningEnabled,
  normalizeBenchRecord,
} from "config/resource-planning.config";
import {
  BENCH_STATUS_FILTER_OPTIONS,
  buildBenchDepartmentOptions,
  buildBenchInsights,
  buildBenchMetrics,
  buildUpcomingRolloffs,
  filterBenchRecords,
  getBenchStatusLabel,
  getBenchStatusTone,
  getEmployeeInitials,
} from "config/resource-planning.utils";
import { resourcePlanningService } from "_services/resourcePlanning.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import {
  AdminInsightStrip,
  AdminPanelLink,
} from "views/admin/components/AdminLuxShared";
import {
  ResourcesActionButton,
  ResourcesHeroActions,
  ResourcesKpiStrip,
  ResourcesSectionHead,
} from "views/resources/components/ResourcesLuxShared";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import { PageDataSourceReporter } from "views/common/PageChromeContext";
import BenchRecordDrawer from "views/resources/components/BenchRecordDrawer";
import BenchRegister from "views/resources/components/BenchRegister";
import { DENSE_PAGE_META } from "config/dense-page-meta.config";

class BenchPage extends Component {
  state = {
    records: [],
    loading: true,
    loadError: null,
    dataSource: null,
    query: "",
    statusFilter: "ALL",
    departmentFilter: "ALL",
    drawerOpen: false,
    selectedRecord: null,
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Bench & roll-off");
    this.loadRecords();
  }

  loadRecords = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await resourcePlanningService.listBenchRecords();
      const payload = (result && result.payload) || [];
      this.setState({
        records: Array.isArray(payload) ? payload : [],
        loading: false,
        dataSource: (result && result.source) || null,
        loadError:
          result && result.source === "api-error"
            ? "Unable to load bench records from the API."
            : null,
      });
    } catch (e) {
      this.setState({
        loading: false,
        loadError: "Unable to load bench records.",
        records: [],
      });
    }
  };

  getFilteredRecords = () => {
    const { records, query, statusFilter, departmentFilter } = this.state;
    return filterBenchRecords(records, {
      query,
      status: statusFilter,
      department: departmentFilter,
    });
  };

  openDrawer = (record) => {
    this.setState({ drawerOpen: true, selectedRecord: record });
  };

  closeDrawer = () => {
    this.setState({ drawerOpen: false, selectedRecord: null });
  };

  upsertLocalRecord = (row) => {
    if (!row) {
      return;
    }
    this.setState((prev) => {
      const records = prev.records.map((item) =>
        item.id === row.id ? { ...item, ...row } : item
      );
      return {
        records,
        selectedRecord: prev.selectedRecord && prev.selectedRecord.id === row.id ? row : prev.selectedRecord,
        dataSource: prev.dataSource === "api" ? "api" : "local",
      };
    });
  };

  handleUpdate = async (record, payload) => {
    const next = {
      employeeId: record.employeeId,
      employeeName: record.employeeName,
      role: record.role,
      department: record.department,
      lastProjectId: record.lastProjectId,
      lastProjectName: record.lastProjectName,
      lastProjectEndDate: record.lastProjectEndDate,
      daysOnBench: record.daysOnBench,
      primarySkills: record.primarySkills,
      location: record.location,
      ...payload,
    };
    const result = await resourcePlanningService.updateBenchRecord(record.id, next);
    if (result && result.payload) {
      this.upsertLocalRecord(result.payload);
      return;
    }
    const local = normalizeBenchRecord({
      ...record,
      ...next,
      id: record.id,
    });
    if (!local) {
      throw new Error("Unable to update bench record.");
    }
    this.upsertLocalRecord(local);
  };

  renderRolloffTimeline = (upcoming) => {
    if (!upcoming.length) {
      return null;
    }

    return (
      <section className="lux-hrms-dash__panel lux-bench-panel lux-bench-panel--timeline">
        <ResourcesSectionHead
          tone="teal"
          icon="fe fe-calendar"
          eyebrow="Roll-off pipeline"
          title="Upcoming roll-offs"
          subtitle="Consultants freeing up soon — tap to place or update"
          badge={`${upcoming.length} coming up`}
        />
        <div className="lux-bench-timeline">
          {upcoming.map((row) => {
            const tone = getBenchStatusTone(row.status);
            return (
              <button
                key={row.id}
                type="button"
                className={classNames("lux-bench-timeline__item", `is-${tone}`)}
                onClick={() => this.openDrawer(row)}
              >
                <span className="lux-bench-timeline__avatar" aria-hidden="true">
                  {getEmployeeInitials(row.employeeName)}
                </span>
                <span className="lux-bench-timeline__copy">
                  <strong>{row.employeeName}</strong>
                  <span>{row.lastProjectName || row.role}</span>
                </span>
                <span className="lux-bench-timeline__meta">
                  <span className={classNames("lux-bench-timeline__chip", `is-${tone}`)}>
                    {getBenchStatusLabel(row.status)}
                  </span>
                  <time>{row.lastProjectEndDate || row.availableFrom}</time>
                </span>
              </button>
            );
          })}
        </div>
      </section>
    );
  };

  render() {
    if (!isResourcePlanningEnabled()) {
      return (
        <PersonaAccessDenied
          moduleName="Resources"
          reason="Resource planning is not enabled for your organization."
        />
      );
    }

    const {
      loading,
      loadError,
      dataSource,
      query,
      statusFilter,
      departmentFilter,
      records,
      drawerOpen,
      selectedRecord,
    } = this.state;
    const filtered = this.getFilteredRecords();
    const metrics = buildBenchMetrics(records);
    const insights = loading ? [] : buildBenchInsights(records, metrics);
    const departmentOptions = buildBenchDepartmentOptions(records);
    const upcomingRolloffs = loading ? [] : buildUpcomingRolloffs(records);

    const kpiCards = [
      {
        id: "active",
        label: "Active bench pool",
        value: metrics.activeCount,
        hint: `${metrics.onBenchCount} fully available`,
        tone: "primary",
        icon: "fe fe-user-minus",
      },
      {
        id: "rolloff",
        label: "Rolling off",
        value: metrics.rollingOffCount,
        hint: `${metrics.soonRolloffCount} within 14 days`,
        tone: metrics.soonRolloffCount > 0 ? "amber" : "green",
        icon: "fe fe-log-out",
      },
      {
        id: "availability",
        label: "Avg availability",
        value: `${metrics.avgAvailabilityPct}%`,
        hint: "Across active bench pool",
        tone: "sky",
        icon: "fe fe-percent",
      },
      {
        id: "placed",
        label: "Recently placed",
        value: metrics.placedCount,
        hint: `${metrics.total} total tracked`,
        tone: "green",
        icon: "fe fe-check-circle",
      },
    ];

    return (
      <div className="lux-bench-page lux-register-page lux-bench-lux" data-testid="page-resources-bench">
        <PageDataSourceReporter dataSource={dataSource} />
        <div className="lux-bench-lux__ambient" aria-hidden="true">
          <span className="lux-bench-lux__orb lux-bench-lux__orb--a" />
          <span className="lux-bench-lux__orb lux-bench-lux__orb--b" />
        </div>

        <LuxModuleIntro
          meta={DENSE_PAGE_META.bench}
          className="lux-bench-hero"
          actions={
            <ResourcesHeroActions dataSource={dataSource}>
              <ResourcesActionButton
                icon="fe fe-refresh-cw"
                variant="ghost"
                onClick={this.loadRecords}
                disabled={loading}
              >
                Refresh
              </ResourcesActionButton>
              <ResourcesActionButton to="/project/capacity" icon="fe fe-pie-chart" variant="ghost">
                Team capacity
              </ResourcesActionButton>
              <ResourcesActionButton
                to="/resources/staffing-requests"
                icon="fe fe-user-plus"
                variant="primary"
              >
                Staffing requests
              </ResourcesActionButton>
            </ResourcesHeroActions>
          }
        />

        <div className="lux-bench-page__body">
          <ResourcesKpiStrip cards={kpiCards} loading={loading} className="lux-bench-kpi-strip" />

          {loadError && (
            <div className="lux-employee-360__error lux-bench__error" role="alert">
              <span>{loadError}</span>
              <ResourcesActionButton variant="ghost" onClick={this.loadRecords}>
                Retry
              </ResourcesActionButton>
            </div>
          )}

          <AdminInsightStrip insights={insights} className="lux-bench-insights" />

          {this.renderRolloffTimeline(upcomingRolloffs)}

          <section className="lux-hrms-dash__panel lux-bench-panel lux-bench-panel--register">
            <ResourcesSectionHead
              tone="sky"
              icon="fe fe-users"
              eyebrow="Availability pool"
              title="Bench register"
              subtitle="Search, filter, and manage placement readiness"
              badge={`${filtered.length} shown`}
              actions={
                <AdminPanelLink to="/resources/staffing-requests">Open staffing queue</AdminPanelLink>
              }
            />

            <div className="lux-bench-panel__toolbar">
              <div className="lux-appr-toolbar__row">
                <div className="lux-appr-toolbar__search">
                  <i className="fe fe-search" aria-hidden="true" />
                  <input
                    type="search"
                    className="lux-appr-toolbar__search-input"
                    placeholder="Search consultants, skills, or projects"
                    value={query}
                    onChange={(event) => this.setState({ query: event.target.value })}
                  />
                </div>
                <span className="lux-appr-toolbar__count">
                  <strong>{filtered.length}</strong> consultant{filtered.length === 1 ? "" : "s"}
                </span>
              </div>

              <div className="lux-appr-toolbar__group">
                <span className="lux-appr-toolbar__label">Status</span>
                <div className="lux-hrms-dash__filter-group">
                  {BENCH_STATUS_FILTER_OPTIONS.map((opt) => (
                    <button
                      key={opt.value}
                      type="button"
                      className={classNames("lux-hrms-dash__filter-chip", {
                        "is-active": statusFilter === opt.value,
                      })}
                      onClick={() => this.setState({ statusFilter: opt.value })}
                    >
                      {opt.label}
                    </button>
                  ))}
                </div>
              </div>

              {departmentOptions.length > 2 && (
                <div className="lux-appr-toolbar__group">
                  <span className="lux-appr-toolbar__label">Department</span>
                  <div className="lux-hrms-dash__filter-group">
                    {departmentOptions.map((dept) => (
                      <button
                        key={dept}
                        type="button"
                        className={classNames("lux-hrms-dash__filter-chip", {
                          "is-active": departmentFilter === dept,
                        })}
                        onClick={() => this.setState({ departmentFilter: dept })}
                      >
                        {dept === "ALL" ? "All departments" : dept}
                      </button>
                    ))}
                  </div>
                </div>
              )}
            </div>

            <div className="lux-hrms-dash__panel-body">
              {loading ? (
                <LuxRegisterEmptyState
                  className="lux-register-empty--compact"
                  title="Loading bench records"
                  description="Aggregating availability and roll-off pipeline."
                />
              ) : filtered.length === 0 ? (
                <LuxRegisterEmptyState
                  className="lux-register-empty--compact"
                  icon="fe fe-user-minus"
                  title="No bench records match"
                  description="Adjust filters or check team capacity for utilization gaps."
                />
              ) : (
                <BenchRegister rows={filtered} loading={loading} onSelect={this.openDrawer} />
              )}
            </div>
          </section>
        </div>

        <BenchRecordDrawer
          open={drawerOpen}
          record={selectedRecord}
          onClose={this.closeDrawer}
          onUpdate={this.handleUpdate}
        />
      </div>
    );
  }
}

export default BenchPage;
