import React from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import { sanitizeUiCopy } from "_helpers/ui-copy.utils";
import {
  enrichGovernanceInsights,
  enrichGovernanceKpiCards,
  GOVERNANCE_MODULE_NAV,
  GOVERNANCE_PAGE_META,
} from "config/project-governance-nav.config";
import { useReportPageDataSource } from "views/common/PageChromeContext";
import { AdminInsightStrip } from "views/admin/components/AdminLuxShared";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import LuxSegmentNav from "views/common/fragments/LuxSegmentNav";
import LuxKpiStrip from "views/common/fragments/LuxKpiStrip";

export function GovernanceKpiStrip({ cards, loading, className }) {
  return <LuxKpiStrip cards={cards} loading={loading} className={className} />;
}

export function GovernanceModuleNav({ activeId }) {
  return (
    <LuxSegmentNav
      items={GOVERNANCE_MODULE_NAV}
      activeId={activeId}
      ariaLabel="Delivery governance modules"
      testId="governance-module-nav"
    />
  );
}

export function GovernancePageMasthead({ meta, actions, activeId }) {
  return (
    <LuxModuleIntro
      meta={meta}
      actions={actions}
      nav={<GovernanceModuleNav activeId={activeId} />}
    />
  );
}

export function GovernanceLuxPanel({ title, meta, icon, accent, className, children }) {
  return (
    <section className={classNames("lux-gov-lux-panel", accent && `is-${accent}`, className)}>
      {title ? (
        <header className="lux-hrms-dash__panel-head lux-hrms-dash__panel-head--stack lux-gov-lux-panel__head">
          <div className="lux-gov-lux-panel__title-wrap">
            {icon ? (
              <span className="lux-gov-lux-panel__icon" aria-hidden="true">
                <i className={icon} />
              </span>
            ) : null}
            <div>
              <h2 className="lux-hrms-dash__panel-title">{title}</h2>
              {meta ? <p className="lux-hrms-dash__panel-sub">{sanitizeUiCopy(meta)}</p> : null}
            </div>
          </div>
        </header>
      ) : null}
      <div className="lux-gov-lux-panel__body">{children}</div>
    </section>
  );
}

export function GovernanceLuxFilters({ className, children }) {
  return <div className={classNames("lux-gov-lux-filters", className)}>{children}</div>;
}

export { default as GovernanceLuxDrawerShell } from "views/project/components/GovernanceLuxDrawerShell";
export {
  GovernanceDrawerLinks,
  GovernanceDrawerStatStrip,
  GovernanceDrawerCard,
  GovernanceDrawerMeta,
  GovernanceDrawerField,
  GovernanceDrawerBanner,
  GovernanceDrawerModuleLink,
  buildGovernanceQuickLinks,
} from "views/project/components/GovernanceLuxDrawerShared";

export default function GovernanceLuxPage({
  pageId,
  dataSource,
  demoLabel = "Demo governance data",
  heroActions,
  kpiCards,
  insights,
  quickLinks,
  quickNavEyebrow = "Related workspaces",
  loading,
  children,
}) {
  useReportPageDataSource(dataSource);
  const meta = GOVERNANCE_PAGE_META[pageId] || GOVERNANCE_PAGE_META.governance;
  const insightRows = enrichGovernanceInsights(insights);
  const kpiRows = enrichGovernanceKpiCards(kpiCards);

  return (
    <div
      className={classNames("lux-register-page", "lux-gov-module", "lux-gov-lux", meta.tone && `is-${meta.tone}`)}
      data-testid={pageId ? `page-project-${pageId}` : undefined}
    >
      <div className="lux-gov-lux__ambient" aria-hidden="true">
        <span className="lux-gov-lux__orb lux-gov-lux__orb--a" />
        <span className="lux-gov-lux__orb lux-gov-lux__orb--b" />
      </div>

      <div className="lux-register-page__body">
        <GovernancePageMasthead
          meta={meta}
          actions={heroActions || undefined}
          activeId={pageId}
        />

        {kpiRows && kpiRows.length ? <GovernanceKpiStrip cards={kpiRows} loading={loading} /> : null}

        {insightRows.length ? <AdminInsightStrip insights={insightRows} className="lux-gov-lux__insights" /> : null}

        <div className="lux-gov-lux__content">{children}</div>
      </div>
    </div>
  );
}
