import React, { Component } from "react";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isWorkflowAutomationEnabled } from "config/workflow-automation.config";
import { WORKFLOW_STUDIO_PAGE_META } from "config/workflow-automation-nav.config";
import { workflowAutomationService } from "_services/workflowAutomation.service";
import WorkflowLuxPage, { WorkflowActionButton } from "views/automation/components/WorkflowLuxShared";
import WorkflowRuleRegister from "views/automation/components/WorkflowRuleRegister";
import WorkflowAiSuggestionPanel from "views/automation/components/WorkflowAiSuggestionPanel";
import AdminInsightsSummary from "views/admin/components/AdminInsightsSummary";
import { AdminPanelLink } from "views/admin/components/AdminLuxShared";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

class WorkflowStudioPage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    rules: [],
    kpiCards: [],
    insights: [],
    analytics: null,
    aiSuggestion: null,
    aiLoading: false,
    statusFilter: "ALL",
    busy: false,
  };

  componentDidMount() {
    this.loadData();
    this.loadAi();
  }

  loadData = async () => {
    const { statusFilter } = this.state;
    this.setState({ loading: true, loadError: null });
    try {
      const filters = statusFilter !== "ALL" ? { status: statusFilter } : {};
      const result = await workflowAutomationService.getOverview(filters);
      const payload = result.payload || {};
      this.setState({
        loading: false,
        dataSource: result.source,
        rules: payload.rules || [],
        kpiCards: payload.kpiCards || [],
        insights: payload.insights || [],
        analytics: payload.analytics || null,
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load workflow studio.",
      });
    }
  };

  loadAi = async () => {
    this.setState({ aiLoading: true });
    try {
      const result = await workflowAutomationService.getAiSuggestions();
      this.setState({ aiSuggestion: result.payload, aiLoading: false });
    } catch (_error) {
      this.setState({ aiLoading: false });
    }
  };

  handlePublish = async (rule) => {
    this.setState({ busy: true });
    try {
      await workflowAutomationService.publishRule(rule.id);
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to publish rule." });
    } finally {
      this.setState({ busy: false });
    }
  };

  handlePause = async (rule) => {
    this.setState({ busy: true });
    try {
      await workflowAutomationService.pauseRule(rule.id);
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to pause rule." });
    } finally {
      this.setState({ busy: false });
    }
  };

  handleExport = async () => {
    try {
      const result = await workflowAutomationService.exportRulesCsv({});
      const blob = new Blob([result.payload || ""], { type: "text/csv;charset=utf-8;" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = "workflow-rules.csv";
      link.click();
      URL.revokeObjectURL(url);
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Export failed." });
    }
  };

  render() {
    if (!isWorkflowAutomationEnabled()) {
      return <PersonaAccessDenied featureLabel="Workflow automation studio" />;
    }

    const { loading, loadError, dataSource, rules, kpiCards, insights, analytics, aiSuggestion, aiLoading, statusFilter, busy } = this.state;

    const published = (rules || []).filter((r) => String(r.status).toLowerCase() === "published").length;
    const draft = (rules || []).filter((r) => String(r.status).toLowerCase() === "draft").length;
    const paused = (rules || []).filter((r) => String(r.status).toLowerCase() === "paused").length;
    const ruleTotal = Math.max((rules || []).length, 1);
    const attention = (insights || []).map((item, index) => ({
      id: item.id || `wf-insight-${index}`,
      tone: item.tone || "slate",
      icon: item.icon || "fe fe-zap",
      eyebrow: item.eyebrow || "Automation",
      stat: item.stat,
      title: item.title,
      copy: item.copy || item.body || item.detail,
      hint: item.hint,
    }));
    const triggers = (analytics && analytics.triggerDistribution) || [];
    const summaryKpis = (kpiCards || []).slice(0, 4).map((card, index) => ({
      key: card.id || card.key || `kpi-${index}`,
      label: card.label,
      value: typeof card.value === "number" ? card.value : Number(card.value) || 0,
      hint: card.hint,
      tone: card.tone || "primary",
      icon: card.icon || "fe fe-activity",
    }));

    return (
      <WorkflowLuxPage
        pageMeta={WORKFLOW_STUDIO_PAGE_META}
        shellTitle="Workflow automation"
        dataSource={dataSource}
        loading={loading}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        heroActions={
          <>
            <WorkflowActionButton icon="fe fe-refresh-cw" onClick={this.loadData} disabled={loading}>
              Refresh
            </WorkflowActionButton>
            <WorkflowActionButton icon="fe fe-download" onClick={this.handleExport}>
              Export CSV
            </WorkflowActionButton>
            <WorkflowActionButton to="/admin/automation-rules" icon="fe fe-sliders" variant="primary">
              Rule builder
            </WorkflowActionButton>
          </>
        }
      >
        {loadError ? <LuxInlineAlert message={loadError} /> : null}

        <AdminInsightsSummary
          storageKey="famstack-workflows-summary-expanded"
          domainClass="lux-admin-summary--workflows"
          loading={loading}
          eyebrow="Automation intelligence"
          eyebrowIcon="fe-zap"
          title="Workflow insights"
          compactTitle={`${(rules || []).length} rules · ${published} published · ${
            analytics ? `${analytics.successRate}% success` : "studio"
          }`}
          collapsedLine={
            analytics
              ? `${analytics.successRate}% success · ${analytics.failureRate}% failure · ${triggers.length} trigger types`
              : `${draft} draft · ${paused} paused`
          }
          subtitle="Rule posture, execution health, and trigger mix for automation studio."
          kpis={
            summaryKpis.length
              ? summaryKpis
              : [
                  {
                    key: "rules",
                    label: "Rules",
                    value: (rules || []).length,
                    hint: `${published} published`,
                    tone: "primary",
                    icon: "fe fe-list",
                  },
                  {
                    key: "success",
                    label: "Success rate",
                    value: (analytics && analytics.successRate) || 0,
                    suffix: "%",
                    hint: "Last 7 days",
                    tone: "green",
                    icon: "fe fe-check-circle",
                  },
                  {
                    key: "failure",
                    label: "Failure rate",
                    value: (analytics && analytics.failureRate) || 0,
                    suffix: "%",
                    hint: "Last 7 days",
                    tone: "rose",
                    icon: "fe fe-alert-triangle",
                  },
                  {
                    key: "triggers",
                    label: "Trigger types",
                    value: triggers.length,
                    hint: "Event distribution",
                    tone: "indigo",
                    icon: "fe fe-pie-chart",
                  },
                ]
          }
          highlights={[
            {
              key: "published",
              label: "Published",
              value: published,
              hint: "Live automations",
              tone: "green",
              icon: "fe fe-play",
            },
            {
              key: "draft",
              label: "Draft",
              value: draft,
              hint: "Not yet live",
              tone: "amber",
              icon: "fe fe-edit-3",
            },
            {
              key: "paused",
              label: "Paused",
              value: paused,
              hint: "Temporarily stopped",
              tone: "slate",
              icon: "fe fe-pause",
            },
          ]}
          attention={attention}
          mixInsights={[
            {
              key: "status",
              icon: "fe fe-toggle-right",
              title: "Rule status mix",
              subtitle: "Published, draft, and paused automations",
              mix: [
                {
                  key: "published",
                  label: "Published",
                  count: published,
                  pct: Math.round((published / ruleTotal) * 100),
                  tone: "green",
                },
                {
                  key: "draft",
                  label: "Draft",
                  count: draft,
                  pct: Math.round((draft / ruleTotal) * 100),
                  tone: "amber",
                },
                {
                  key: "paused",
                  label: "Paused",
                  count: paused,
                  pct: Math.round((paused / ruleTotal) * 100),
                  tone: "slate",
                },
              ],
              emptyLabel: "No workflow rules yet",
            },
            {
              key: "health",
              icon: "fe fe-activity",
              title: "Execution health",
              subtitle: analytics ? "Last 7 days success vs failure" : "Load analytics to see health",
              mix: analytics
                ? [
                    {
                      key: "ok",
                      label: "Success",
                      count: analytics.successRate,
                      pct: analytics.successRate,
                      tone: "green",
                    },
                    {
                      key: "fail",
                      label: "Failure",
                      count: analytics.failureRate,
                      pct: analytics.failureRate,
                      tone: "rose",
                    },
                  ]
                : [],
              emptyLabel: "No execution analytics yet",
            },
          ]}
          series={[
            {
              id: "triggers",
              title: "Trigger distribution",
              subtitle: "By event type",
              rows: triggers.map((bar) => ({
                key: bar.label,
                label: bar.label,
                icon: "fe fe-zap",
                tone: "indigo",
                value: bar.count,
                pct: Math.min((bar.count || 0) * 25, 100),
                meta: String(bar.count),
              })),
              emptyLabel: "No trigger events in window",
            },
          ]}
          testId="workflows-insights"
        />

        <section
          className="lux-admin-atelier lux-admin-atelier--workflows"
          data-testid="workflow-rules-atelier"
        >
          <header className="lux-admin-atelier__masthead">
            <div className="lux-admin-atelier__masthead-main">
              <span className="lux-admin-atelier__mark" aria-hidden="true">
                <i className="fe fe-zap" />
              </span>
              <div>
                <p className="lux-admin-atelier__eyebrow">Automation studio</p>
                <h2 className="lux-admin-atelier__title">Workflow rules</h2>
                <p className="lux-admin-atelier__lede">
                  Published, draft, and paused automations — publish or pause from the register.
                </p>
              </div>
            </div>
            <div className="lux-admin-atelier__masthead-aside">
              <AdminPanelLink to="/admin/automation-rules">Rule builder</AdminPanelLink>
              <span className="lux-admin-atelier__count">
                <strong>{(rules || []).length}</strong>
                <em>rules</em>
              </span>
            </div>
          </header>

          <div className="lux-admin-atelier__toolbar">
            <div className="lux-admin-atelier__filter">
              <span>Status</span>
              <select
                className={classNames("lux-admin-atelier__search-input", "lux-wf-filter")}
                value={statusFilter}
                onChange={(e) => this.setState({ statusFilter: e.target.value }, this.loadData)}
                aria-label="Filter rules by status"
              >
                <option value="ALL">All statuses</option>
                <option value="published">Published</option>
                <option value="draft">Draft</option>
                <option value="paused">Paused</option>
              </select>
            </div>
          </div>

          <div className="lux-admin-atelier__body">
            <WorkflowAiSuggestionPanel suggestion={aiSuggestion} loading={aiLoading} />

            <div className="lux-admin-atelier__stage-card">
              <WorkflowRuleRegister
                rules={rules}
                loading={loading}
                onPublish={this.handlePublish}
                onPause={this.handlePause}
                busy={busy}
              />
            </div>
          </div>
        </section>
      </WorkflowLuxPage>
    );
  }
}

export default WorkflowStudioPage;
