import React from "react";
import { withRouter } from "react-router-dom";
import classNames from "classnames/bind";
import { sanitizeUiCopy } from "_helpers/ui-copy.utils";
import { resolveHowToDocPath } from "config/page-howto.config";
import HowToUseLink from "views/common/fragments/HowToUseLink";

/**
 * Module page hero — same card header language as Application Config.
 * Top: brand lockup (icon + kicker + title + subtitle) with optional actions/toolbar.
 * Optional compact section menu (icons + short labels) — not a full-height second band.
 * Auto-appends icon-only How to use when a registry match exists (unless hideHowTo).
 */
function LuxModuleIntro({
  meta,
  eyebrow,
  titleLead,
  titleAccent,
  lede,
  icon,
  tone,
  nav,
  actions,
  toolbar,
  className,
  kickerIcon,
  location,
  howToHref,
  howToTestId = "howto-use-link",
  hideHowTo = false,
}) {
  const resolved = meta || {};
  const toneClass = tone || resolved.tone;
  const lead = titleLead != null ? titleLead : resolved.titleLead;
  const accent = titleAccent != null ? titleAccent : resolved.titleAccent;
  const eyebrowText = eyebrow != null ? eyebrow : resolved.eyebrow;
  const iconClass = icon || resolved.icon || "fe fe-layers";
  const kickerIconClass = kickerIcon || iconClass;
  const ledeText = lede != null ? lede : resolved.lede;
  const description = ledeText ? sanitizeUiCopy(ledeText) : "";
  const hasTitle = Boolean(lead || accent);
  const hasToolbar = Boolean(toolbar);

  const pathname = (location && location.pathname) || "";
  const resolvedHowTo = howToHref || resolveHowToDocPath(pathname);
  const howTo =
    !hideHowTo && !hasToolbar && resolvedHowTo ? (
      <HowToUseLink href={resolvedHowTo} testId={howToTestId} />
    ) : null;

  const asideContent = hasToolbar
    ? toolbar
    : actions || howTo
      ? (
          <>
            {actions}
            {howTo}
          </>
        )
      : null;

  if (!eyebrowText && !hasTitle && !description && !nav && !asideContent) {
    return null;
  }

  return (
    <header
      className={classNames(
        "lux-appconfig-hero",
        "lux-module-hero",
        toneClass && `is-${toneClass}`,
        nav && "has-nav",
        hasToolbar && "has-toolbar",
        className
      )}
    >
      <div className="lux-appconfig-hero__glow" aria-hidden="true" />

      <div className="lux-appconfig-hero__top">
        <div className="lux-appconfig-hero__brand">
          <div className="lux-appconfig-hero__icon" aria-hidden="true">
            <i className={iconClass} />
          </div>
          <div className="lux-appconfig-hero__intro">
            {eyebrowText ? (
              <p className="lux-appconfig-hero__kicker">
                <i className={kickerIconClass} aria-hidden="true" />
                {eyebrowText}
              </p>
            ) : null}
            {hasTitle ? (
              <h2 className="lux-appconfig-hero__title">
                {lead}
                {accent ? (
                  <>
                    {lead ? " " : null}
                    <span className="lux-module-hero__title-accent">{accent}</span>
                  </>
                ) : null}
              </h2>
            ) : null}
            {description ? (
              <p className="lux-appconfig-hero__subtitle">{description}</p>
            ) : null}
          </div>
        </div>

        {asideContent ? (
          <div
            className={classNames("lux-module-hero__aside", {
              "lux-module-hero__aside--toolbar": hasToolbar,
            })}
            role="group"
            aria-label={hasToolbar ? "Page toolbar" : "Page actions"}
          >
            {hasToolbar ? (
              <div className="lux-module-hero__toolbar">{toolbar}</div>
            ) : (
              <div className="lux-module-hero__actions">{asideContent}</div>
            )}
          </div>
        ) : null}
      </div>

      {nav ? (
        <div className="lux-module-hero__nav-row" role="navigation" aria-label="Module sections">
          <div className="lux-module-hero__nav lux-module-hero__nav--compact">{nav}</div>
        </div>
      ) : null}
    </header>
  );
}

export default withRouter(LuxModuleIntro);
