export function downloadLedgerCsv(entries, options = {}) {
  const list = entries || [];
  const employeeName = options.employeeName || 'employee';
  const leaveTypeLabel = options.leaveTypeLabel || 'all-types';
  const safeName = `${employeeName}-${leaveTypeLabel}`
    .replace(/[^a-z0-9-_]+/gi, '-')
    .toLowerCase();

  const headers = [
    'changeType',
    'amount',
    'balanceBefore',
    'balanceAfter',
    'comment',
    'leaveMasterId',
  ];

  const rows = list.map((entry) =>
    [
      entry.changeType || entry.change_type || '',
      entry.amount != null ? entry.amount : '',
      entry.balanceBefore != null ? entry.balanceBefore : entry.balance_before || '',
      entry.balanceAfter != null ? entry.balanceAfter : entry.balance_after || '',
      csvEscape(entry.comment || ''),
      entry.leaveMasterId || entry.leave_master_id || '',
    ].join(',')
  );

  const csv = [headers.join(','), ...rows].join('\n');
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = `leave-ledger-${safeName}.csv`;
  link.click();
  URL.revokeObjectURL(url);
}

function csvEscape(value) {
  const text = String(value).replace(/"/g, '""');
  return `"${text}"`;
}
