import envconfig from "env.config";
import { shouldUseMyWorkQueue, shouldUseWorkspaceNotifications } from "config/tracopus-pilot.config";

export function shouldUseWorkspaceHomeApi() {
  return envconfig.USE_WORKSPACE_HOME_API === true;
}

export const MY_WORK_CATEGORIES = {
  APPROVAL: { id: "APPROVAL", label: "Approval", icon: "fe fe-check-circle", tone: "mint" },
  TIMESHEET: { id: "TIMESHEET", label: "Timesheet", icon: "fe fe-clock", tone: "amber" },
  ATTENDANCE: { id: "ATTENDANCE", label: "Attendance", icon: "fe fe-calendar", tone: "violet" },
  ONBOARDING: { id: "ONBOARDING", label: "Onboarding", icon: "fe fe-user-plus", tone: "blue" },
};

export function isMyWorkQueueEnabled() {
  return shouldUseMyWorkQueue();
}

export function getMyWorkCategoryMeta(category) {
  return MY_WORK_CATEGORIES[category] || {
    id: category || "TASK",
    label: category || "Task",
    icon: "fe fe-layers",
    tone: "slate",
  };
}

export function filterMyWorkItems(items, filters = {}) {
  const { status, category, query } = filters;
  return (items || []).filter((row) => {
    if (status && status !== "ALL" && row.status !== status) {
      return false;
    }
    if (category && category !== "ALL" && row.category !== category) {
      return false;
    }
    if (query) {
      const q = String(query).toLowerCase();
      const haystack = [row.title, row.subtitle, row.category, row.dueLabel]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();
      if (!haystack.includes(q)) {
        return false;
      }
    }
    return true;
  });
}

export function buildMyWorkQueueMetrics(items) {
  const rows = items || [];
  const open = rows.filter((row) => row.status === "OPEN");
  const high = open.filter((row) => String(row.priority).toUpperCase() === "HIGH");
  const categories = new Set(open.map((row) => row.category));
  const dueSoon = open.filter((row) => row.dueLabel).length;

  return {
    open: open.length,
    highPriority: high.length,
    categories: categories.size,
    total: rows.length,
    dueSoon,
  };
}

export function buildMyWorkInsights(items) {
  const open = (items || []).filter((row) => row.status === "OPEN");
  const high = open.filter((row) => String(row.priority).toUpperCase() === "HIGH");
  const approvals = open.filter((row) => row.category === "APPROVAL");
  const insights = [];

  if (high.length > 0) {
    insights.push({
      id: "high",
      tone: "amber",
      icon: "fe fe-alert-triangle",
      title: `${high.length} high-priority item(s)`,
      copy: "Review due-soon tasks before they slip.",
      path: "/workspace/my-work",
    });
  }
  if (approvals.length > 0) {
    insights.push({
      id: "approvals",
      tone: "green",
      icon: "fe fe-inbox",
      title: `${approvals.length} approval(s) waiting`,
      copy: "Sign off leave, timesheet, and attendance requests.",
      path: "/workspace/approvals",
    });
  }
  if (open.length > 0 && high.length === 0) {
    insights.push({
      id: "ontrack",
      tone: "green",
      icon: "fe fe-check-circle",
      title: "Queue is manageable",
      copy: `${open.length} open item(s) — no urgent blockers flagged.`,
      path: "/workspace/my-work",
    });
  }
  return insights.slice(0, 3);
}

export function getMyWorkPriorityTone(priority) {
  return String(priority).toUpperCase() === "HIGH" ? "danger" : "slate";
}

export const NOTIFICATION_TYPES = {
  APPROVAL: { id: "APPROVAL", label: "Approval", icon: "fe fe-check-circle", tone: "mint" },
  TIMESHEET: { id: "TIMESHEET", label: "Timesheet", icon: "fe fe-clock", tone: "amber" },
  PAYROLL: { id: "PAYROLL", label: "Payroll", icon: "fe fe-dollar-sign", tone: "green" },
  PROJECT: { id: "PROJECT", label: "Project", icon: "fe fe-briefcase", tone: "rose" },
  LEAVE: { id: "LEAVE", label: "Leave", icon: "fe fe-sun", tone: "mint" },
  ONBOARDING: { id: "ONBOARDING", label: "Onboarding", icon: "fe fe-user-plus", tone: "blue" },
  SYSTEM: { id: "SYSTEM", label: "System", icon: "fe fe-shield", tone: "slate" },
};

export const NOTIFICATION_CHANNELS = {
  IN_APP: { id: "IN_APP", label: "In-app" },
  EMAIL: { id: "EMAIL", label: "Email" },
  PUSH: { id: "PUSH", label: "Push" },
};

export function isWorkspaceNotificationsEnabled() {
  return shouldUseWorkspaceNotifications();
}

export function getNotificationTypeMeta(type) {
  return NOTIFICATION_TYPES[type] || {
    id: type || "ALERT",
    label: type || "Alert",
    icon: "fe fe-bell",
    tone: "slate",
  };
}

export function getNotificationChannelLabel(channel) {
  const meta = NOTIFICATION_CHANNELS[channel];
  return (meta && meta.label) || channel || "In-app";
}

export function filterNotifications(items, filters = {}) {
  const { status, type, query } = filters;
  return (items || []).filter((row) => {
    if (status && status !== "ALL" && row.status !== status) {
      return false;
    }
    if (type && type !== "ALL" && row.type !== type) {
      return false;
    }
    if (query) {
      const q = String(query).toLowerCase();
      const haystack = [row.title, row.body, row.actorName, row.module, row.type]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();
      if (!haystack.includes(q)) {
        return false;
      }
    }
    return true;
  });
}

export function buildNotificationMetrics(items) {
  const rows = items || [];
  const unread = rows.filter((row) => row.status === "UNREAD");
  const high = unread.filter((row) => String(row.priority).toUpperCase() === "HIGH");
  const types = new Set(unread.map((row) => row.type));
  const today = rows.filter((row) => isNotificationToday(row.createdAt)).length;

  return {
    unread: unread.length,
    highPriority: high.length,
    types: types.size,
    total: rows.length,
    today,
    read: rows.filter((row) => row.status === "READ").length,
  };
}

export function buildNotificationInsights(items) {
  const unread = (items || []).filter((row) => row.status === "UNREAD");
  const high = unread.filter((row) => String(row.priority).toUpperCase() === "HIGH");
  const approvals = unread.filter((row) => row.type === "APPROVAL");
  const insights = [];

  if (high.length > 0) {
    insights.push({
      id: "high",
      tone: "rose",
      icon: "fe fe-alert-triangle",
      title: `${high.length} urgent notification(s)`,
      copy: "Review high-priority alerts before they expire.",
    });
  }
  if (approvals.length > 0) {
    insights.push({
      id: "approvals",
      tone: "green",
      icon: "fe fe-inbox",
      title: `${approvals.length} approval alert(s)`,
      copy: "Open your approvals inbox to sign off requests.",
      path: "/workspace/approvals",
    });
  }
  if (unread.length === 0) {
    insights.push({
      id: "clear",
      tone: "green",
      icon: "fe fe-check-circle",
      title: "Inbox zero",
      copy: "You're caught up — new alerts will appear here in real time.",
    });
  } else if (high.length === 0) {
    insights.push({
      id: "manageable",
      tone: "blue",
      icon: "fe fe-bell",
      title: `${unread.length} unread notification(s)`,
      copy: "No urgent items flagged — review at your pace.",
    });
  }
  return insights.slice(0, 3);
}

export function getNotificationStatusTone(status) {
  if (status === "UNREAD") return "warning";
  if (status === "READ") return "slate";
  if (status === "ARCHIVED") return "success";
  return "slate";
}

export function formatNotificationTimestamp(value) {
  if (!value) return "—";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  const now = new Date();
  const sameDay =
    date.getFullYear() === now.getFullYear() &&
    date.getMonth() === now.getMonth() &&
    date.getDate() === now.getDate();
  if (sameDay) {
    return date.toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" });
  }
  return date.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
}

function isNotificationToday(value) {
  if (!value) return false;
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return false;
  const now = new Date();
  return (
    date.getFullYear() === now.getFullYear() &&
    date.getMonth() === now.getMonth() &&
    date.getDate() === now.getDate()
  );
}
