/**
 * Org-level persona → page map overrides + re-exports of org kill switches.
 * Catalog listing stays here to avoid circular imports with sidebar-menu.
 */

import { SIDEBAR_GROUPS } from "config/sidebar-menu.config";
import { groupSidebarItemsByNavGroup, resolveSidebarNavGroup } from "config/sidebar-nav-groups";
import {
  PERSONA_NAVIGATION_CONFIG_KEY,
  ORG_ACCESS_POLICY_CHANGED,
  ORG_ACCESS_PROTECTED_PATHS,
  ORG_ACCESS_PROTECTED_MODULES,
  ORG_ACCESS_PROTECTED_SIDEBAR_GROUPS,
  getPagePersonaMap,
  getPagePersonaOverride,
  setPagePersonaMapLocal,
  loadPersonaPageMapFromAppConfig,
  savePersonaPageMap,
  isPersonaNavigationAdminEnabled,
  loadOrgAccessPolicyFromAppConfig,
  saveOrgAccessPolicy,
  getOrgAccessPolicy,
  setOrgAccessPolicyLocal,
  isOrgPathDisabled,
  isOrgPersonaDisabled,
  isOrgModuleDisabled,
  isOrgSidebarGroupDisabled,
  filterPersonasByOrgPolicy,
  applyOrgModuleKillSwitches,
  listOrgKillSwitchModules,
  normalizeOrgAccessPath,
} from "config/org-access-policy.config";

export {
  PERSONA_NAVIGATION_CONFIG_KEY,
  ORG_ACCESS_POLICY_CHANGED as PERSONA_PAGE_MAP_CHANGED,
  ORG_ACCESS_PROTECTED_PATHS,
  ORG_ACCESS_PROTECTED_MODULES,
  ORG_ACCESS_PROTECTED_SIDEBAR_GROUPS,
  getPagePersonaMap,
  getPagePersonaOverride,
  setPagePersonaMapLocal,
  loadPersonaPageMapFromAppConfig,
  savePersonaPageMap,
  isPersonaNavigationAdminEnabled,
  loadOrgAccessPolicyFromAppConfig,
  saveOrgAccessPolicy,
  getOrgAccessPolicy,
  setOrgAccessPolicyLocal,
  isOrgPathDisabled,
  isOrgPersonaDisabled,
  isOrgModuleDisabled,
  isOrgSidebarGroupDisabled,
  filterPersonasByOrgPolicy,
  applyOrgModuleKillSwitches,
  listOrgKillSwitchModules,
};

function toCatalogPageRow(group, item) {
  const navGroup = resolveSidebarNavGroup(group.id, item);
  const path = normalizeOrgAccessPath(item.path);
  return {
    path,
    name: item.name || item.path,
    groupId: group.id,
    groupName: group.menuName || group.name || group.id,
    groupIcon: group.icon || "fe fe-grid",
    sectionId: navGroup.id,
    sectionLabel: navGroup.label,
    protected: (ORG_ACCESS_PROTECTED_PATHS || []).includes(path),
    defaultPersonas: Array.isArray(item.personas) ? [...item.personas] : [],
    feature: item.feature || null,
    flagModule: item.flagModule || null,
    flag: item.flag || null,
  };
}

/** Catalog pages in sidebar order (not alphabetical). */
export function listCatalogPagesForPersonaAdmin() {
  const rows = [];
  (SIDEBAR_GROUPS || []).forEach((group) => {
    (group.items || []).forEach((item) => {
      if (!item || !item.path || item.hidden === true) {
        return;
      }
      rows.push(toCatalogPageRow(group, item));
    });
  });
  return rows;
}

/** Sidebar group id → primary permission module key (Modules kill switch). */
export const SIDEBAR_GROUP_PRIMARY_MODULE = {
  workspace: "workspaceModules",
  projects: "projectModules",
  people: "peopleModules",
  finance: "financeModules",
  payroll: "payrollModules",
  performance: "performanceModules",
  analytics: "analyticsModules",
  ai: "aiModules",
  integrations: "integrationsModules",
};

/** Permission module key → sidebar group id. */
export const MODULE_PRIMARY_SIDEBAR_GROUP = Object.keys(SIDEBAR_GROUP_PRIMARY_MODULE).reduce(
  (acc, groupId) => {
    const moduleKey = SIDEBAR_GROUP_PRIMARY_MODULE[groupId];
    if (moduleKey) acc[moduleKey] = groupId;
    return acc;
  },
  {}
);

/** Sidebar groups available as org kill switches (Admin stays protected). */
export function listSidebarGroupsForPersonaAdmin() {
  return (SIDEBAR_GROUPS || [])
    .filter((group) => group && group.id)
    .map((group) => ({
      id: group.id,
      name: group.menuName || group.name || group.id,
      icon: group.icon || "fe fe-grid",
      protected: (ORG_ACCESS_PROTECTED_SIDEBAR_GROUPS || []).includes(group.id),
      pageCount: (group.items || []).filter((item) => item && item.path && item.hidden !== true)
        .length,
      primaryModule: SIDEBAR_GROUP_PRIMARY_MODULE[group.id] || null,
    }));
}

/**
 * Fold filtered catalog pages into sidebar groups → soft nav sections.
 * Preserves SIDEBAR_GROUPS order and MODULE_NAV_GROUP_RULES section order.
 */
export function groupCatalogPagesLikeSidebar(pages) {
  const list = Array.isArray(pages) ? pages : [];
  const byGroup = new Map();
  list.forEach((page) => {
    const groupId = page.groupId || "other";
    if (!byGroup.has(groupId)) {
      byGroup.set(groupId, []);
    }
    byGroup.get(groupId).push(page);
  });

  const ordered = [];
  (SIDEBAR_GROUPS || []).forEach((group) => {
    const groupPages = byGroup.get(group.id);
    if (!groupPages || !groupPages.length) {
      return;
    }
    const sections = groupSidebarItemsByNavGroup(group.id, groupPages).map((section) => ({
      id: section.id,
      label: section.label,
      pages: section.items,
    }));
    ordered.push({
      id: group.id,
      name: group.menuName || group.name || group.id,
      icon: group.icon || "fe fe-grid",
      protected: (ORG_ACCESS_PROTECTED_SIDEBAR_GROUPS || []).includes(group.id),
      sections,
      pages: groupPages,
    });
    byGroup.delete(group.id);
  });

  byGroup.forEach((groupPages, groupId) => {
    ordered.push({
      id: groupId,
      name: (groupPages[0] && groupPages[0].groupName) || groupId,
      icon: (groupPages[0] && groupPages[0].groupIcon) || "fe fe-grid",
      protected: (ORG_ACCESS_PROTECTED_SIDEBAR_GROUPS || []).includes(groupId),
      sections: [{ id: "general", label: null, pages: groupPages }],
      pages: groupPages,
    });
  });

  return ordered;
}
