import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isFinanceIntelligenceEnabled } from "config/finance-intelligence.config";
import { BILLING_PLANS_PAGE_META } from "config/finance-intelligence-nav.config";
import { financeIntelligenceService } from "_services/financeIntelligence.service";
import { projectService } from "_services/project.service";
import { commonUtils } from "_helpers";
import FinanceLuxPage, {
  FinanceActionButton,
  FinanceInsightPanel,
  FinanceLuxPanel,
} from "views/finance/components/FinanceLuxShared";
import FinanceLoadAlert from "views/finance/components/FinanceLoadAlert";
import BillingPlansPanel from "views/finance/components/BillingPlansPanel";
import { shouldHideRegisterOnLoadError } from "_helpers/registerListError.utils";

class BillingPlansPage extends Component {
  state = {
    loading: true,
    loadError: null,
    saving: false,
    dataSource: null,
    plans: [],
    projects: [],
    kpiCards: [],
    insights: [],
    filters: { search: "", status: "ALL" },
    createForm: {
      projectId: "",
      name: "",
      recognitionMethod: "MILESTONE",
      totalValueUsd: "",
      milestoneName: "Kickoff",
      milestoneAmountUsd: "",
    },
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Billing plans");
    }
    this.loadData();
    this.loadProjects();
  }

  loadProjects = async () => {
    try {
      const userTeamId = commonUtils.getCurrentUserTeamId();
      const employeeId = commonUtils.getCurrentUserId && commonUtils.getCurrentUserId();
      const response = await projectService.getProjectList({
        userTeamIds: userTeamId,
        currentUserId: employeeId || "",
        startDate: "",
        endDate: "",
        isOnlyUserTeams: false,
      });
      const rows = (response && response.payload) || response || [];
      const projects = (Array.isArray(rows) ? rows : []).map((row) => ({
        id: String(row.id),
        code: row.code || "",
        name: row.name || `Project ${row.id}`,
        estCost: row.estCost,
      }));
      this.setState({ projects });
    } catch (error) {
      // Keep page usable; create will fail closed without a live project.
      this.setState({ projects: [] });
    }
  };

  loadData = async (filters = this.state.filters) => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await financeIntelligenceService.listBillingPlans(filters);
      this.setState({
        loading: false,
        plans: result.payload || [],
        kpiCards: (result.overview && result.overview.kpiCards) || [],
        insights: (result.overview && result.overview.insights) || [],
        dataSource: result.source,
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: error,
      });
    }
  };

  handleFilterChange = (patch) => {
    const filters = { ...this.state.filters, ...patch };
    this.setState({ filters }, () => this.loadData(filters));
  };

  handleCreateFormChange = (patch) => {
    this.setState({ createForm: { ...this.state.createForm, ...patch } });
  };

  handleCreatePlan = async () => {
    const { createForm, projects } = this.state;
    const project = projects.find((row) => row.id === String(createForm.projectId));
    if (!project) {
      this.setState({ loadError: { message: "Select a live project before creating a billing plan." } });
      return;
    }
    const totalValueUsd = Number(createForm.totalValueUsd || project.estCost || 0);
    const milestoneAmount = Number(createForm.milestoneAmountUsd || totalValueUsd || 0);
    this.setState({ saving: true, loadError: null });
    try {
      await financeIntelligenceService.saveBillingPlan({
        projectId: project.id,
        projectCode: project.code,
        projectName: project.name,
        name: (createForm.name || `${project.name} billing plan`).trim(),
        status: "DRAFT",
        recognitionMethod: createForm.recognitionMethod || "MILESTONE",
        totalValueUsd,
        recognizedUsd: 0,
        readinessPct: 0,
        milestones: [
          {
            id: `ms-${Date.now()}`,
            name: (createForm.milestoneName || "Kickoff").trim(),
            amountUsd: milestoneAmount,
            status: "PLANNED",
            dueDate: null,
          },
        ],
      });
      this.setState({
        createForm: {
          projectId: "",
          name: "",
          recognitionMethod: "MILESTONE",
          totalValueUsd: "",
          milestoneName: "Kickoff",
          milestoneAmountUsd: "",
        },
      });
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: error });
    } finally {
      this.setState({ saving: false });
    }
  };

  handleUpdateMilestone = async (plan, milestoneId, status) => {
    if (!plan || !milestoneId || !status) {
      return;
    }
    this.setState({ saving: true, loadError: null });
    try {
      const milestones = (plan.milestones || []).map((ms) =>
        ms.id === milestoneId ? { ...ms, status } : ms
      );
      const recognizedUsd = milestones
        .filter((ms) => ms.status === "BILLED")
        .reduce((sum, ms) => sum + (Number(ms.amountUsd) || 0), 0);
      await financeIntelligenceService.saveBillingPlan({
        ...plan,
        milestones,
        recognizedUsd,
        status: plan.status === "DRAFT" && status !== "PLANNED" ? "ACTIVE" : plan.status,
      });
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: error });
    } finally {
      this.setState({ saving: false });
    }
  };

  render() {
    if (!isFinanceIntelligenceEnabled()) {
      return <PersonaAccessDenied featureLabel="Billing plans" />;
    }

    const {
      loading,
      loadError,
      saving,
      dataSource,
      plans,
      projects,
      kpiCards,
      insights,
      filters,
      createForm,
    } = this.state;
    const meta = BILLING_PLANS_PAGE_META;
    const hideRegister = shouldHideRegisterOnLoadError(loadError, plans);

    return (
      <FinanceLuxPage
        testId="page-finance-billing-plans"
        pageMeta={meta}
        dataSource={dataSource}
        demoLabel={null}
        loading={loading}
        kpiCards={kpiCards}
        heroActions={
          <>
            <FinanceActionButton to="/finance/dashboard" icon="fe fe-grid" variant="ghost">
              Finance hub
            </FinanceActionButton>
            <FinanceActionButton to="/finance/invoice" icon="fe fe-credit-card" variant="primary">
              Platform invoices
            </FinanceActionButton>
          </>
        }
      >
        <FinanceInsightPanel insights={insights} />
        <FinanceLoadAlert
          error={loadError}
          fallback="Unable to load billing plans."
          onDismiss={() => this.setState({ loadError: null })}
        />
        {hideRegister ? null : (
        <FinanceLuxPanel title={meta.panelTitle} meta={meta.panelMeta} icon="fe fe-layers" accent="indigo">
          <BillingPlansPanel
            plans={plans}
            projects={projects}
            loading={loading}
            filters={filters}
            createForm={createForm}
            onFilterChange={this.handleFilterChange}
            onCreateFormChange={this.handleCreateFormChange}
            onCreatePlan={this.handleCreatePlan}
            onUpdateMilestone={this.handleUpdateMilestone}
            saving={saving}
          />
        </FinanceLuxPanel>
        )}
      </FinanceLuxPage>
    );
  }
}

export default BillingPlansPage;
