import React, { Component } from "react";
import { ADMIN_PAGE_META } from "config/admin-page-meta.config";
import { commonUtils } from "_helpers";
import { appConfigService } from "_services/appconfig.service";
import {
  AdminActionButton,
  AdminInsightStrip,
  AdminLuxPage,
  AdminPanelHead,
} from "views/admin/components/AdminLuxShared";
import AdminLoadAlert from "views/admin/components/AdminLoadAlert";
import SetupChecklistRegister from "views/admin/components/SetupChecklistRegister";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";

/**
 * W0A / CUST-008 / MIG-001 — customer implementation checklist backed by Application Config.
 */
class CustomerSetupChecklistPage extends Component {
  state = {
    loading: true,
    saving: false,
    loadError: null,
    items: [],
    summary: {},
    dataSource: null,
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Setup checklist");
    }
    this.loadChecklist();
  }

  loadChecklist = async () => {
    const teamId = commonUtils.getCurrentUserTeamId();
    this.setState({ loading: true, loadError: null });
    try {
      const response = await appConfigService.getImplementationChecklist(teamId);
      const payload = (response && response.payload) || response || {};
      this.setState({
        loading: false,
        items: Array.isArray(payload.items) ? payload.items : [],
        summary: {
          total: payload.total,
          done: payload.done,
          remaining: payload.remaining,
          complete: payload.complete,
        },
        dataSource: payload.source || "application-config",
      });
    } catch (e) {
      this.setState({
        loading: false,
        loadError: "Unable to load implementation checklist.",
        items: [],
      });
    }
  };

  toggleItem = async (itemId) => {
    const { items, saving } = this.state;
    if (saving) return;
    const nextItems = items.map((row) =>
      row.id === itemId ? { ...row, done: !row.done } : row
    );
    this.setState({ saving: true, items: nextItems, loadError: null });
    try {
      const teamId = commonUtils.getCurrentUserTeamId();
      const response = await appConfigService.updateImplementationChecklist(teamId, {
        items: nextItems,
      });
      const payload = (response && response.payload) || response || {};
      this.setState({
        saving: false,
        items: Array.isArray(payload.items) ? payload.items : nextItems,
        summary: {
          total: payload.total,
          done: payload.done,
          remaining: payload.remaining,
          complete: payload.complete,
        },
        dataSource: payload.source || "application-config",
      });
    } catch (e) {
      this.setState({ saving: false, loadError: "Unable to save checklist progress." });
      this.loadChecklist();
    }
  };

  buildKpiCards = () => {
    const { summary } = this.state;
    const done = Number(summary.done) || 0;
    const total = Number(summary.total) || 0;
    const remaining = Number(summary.remaining) || Math.max(total - done, 0);
    const complete = Boolean(summary.complete) || (total > 0 && remaining === 0);
    return [
      {
        id: "done",
        label: "Completed",
        value: String(done),
        hint: `of ${total || "—"} steps`,
        tone: done ? "green" : "slate",
        icon: "fe fe-check-circle",
      },
      {
        id: "remaining",
        label: "Remaining",
        value: String(remaining),
        hint: complete ? "All steps closed" : "Still open",
        tone: remaining ? "amber" : "green",
        icon: "fe fe-clock",
      },
      {
        id: "status",
        label: "Status",
        value: complete ? "Complete" : "In progress",
        hint: "Day-one activation",
        tone: complete ? "green" : "blue",
        icon: "fe fe-flag",
      },
    ];
  };

  buildInsights = () => {
    const { items, summary } = this.state;
    if (summary.complete) {
      return [
        {
          id: "complete",
          title: "Activation ready",
          body: "All implementation checklist steps are marked done.",
          tone: "green",
        },
      ];
    }
    const nextOpen = (items || []).find((row) => !row.done);
    if (!nextOpen) {
      return [];
    }
    return [
      {
        id: "next",
        title: "Next open step",
        body: `${nextOpen.id} — ${nextOpen.label}`,
        tone: "amber",
      },
    ];
  };

  render() {
    const { loading, saving, loadError, items, summary, dataSource } = this.state;
    const insights = loading ? [] : this.buildInsights();

    return (
      <AdminLuxPage
        pageMeta={ADMIN_PAGE_META.setupChecklist}
        dataSource={dataSource}
        loading={loading}
        kpiCards={this.buildKpiCards()}
        testId="page-admin-setup-checklist"
        heroActions={
          <>
            <AdminActionButton
              icon="fe fe-refresh-cw"
              onClick={this.loadChecklist}
              disabled={loading || saving}
            >
              Refresh
            </AdminActionButton>
            <AdminActionButton
              to="/admin/appconfig"
              icon="fe fe-settings"
              variant="secondary"
            >
              Application config
            </AdminActionButton>
          </>
        }
      >
        {insights.length ? <AdminInsightStrip insights={insights} /> : null}

        <div className="lux-admin-panel">
          <AdminPanelHead
            title="Customer implementation checklist"
            subtitle="Day-one activation steps persisted in Application Config (no isolated checklist table)."
          />
          <div className="lux-admin-panel__body">
            <AdminLoadAlert
              error={loadError}
              fallback="Unable to load implementation checklist."
              onDismiss={() => this.setState({ loadError: null })}
              testId="setup-checklist-load-alert"
            />

            {loading ? (
              <LuxRegisterEmptyState
                className="lux-register-empty--compact"
                variant="default"
                eyebrow="Setup"
                title="Loading checklist"
                description="Fetching implementation steps from Application Config."
              />
            ) : !items.length ? (
              <LuxRegisterEmptyState
                className="lux-register-empty--compact"
                variant="default"
                eyebrow="Setup"
                title="No checklist items"
                description="No implementation steps were returned for this team."
                hints={[
                  "Confirm Application Config is available for your team",
                  "Refresh to retry the checklist load",
                ]}
              />
            ) : (
              <SetupChecklistRegister
                items={items}
                saving={saving}
                onToggle={this.toggleItem}
              />
            )}

            {!loading && summary.complete ? (
              <p className="lux-setup-checklist__complete-note" role="status">
                Checklist complete — continue in Application Config for ongoing admin setup.
              </p>
            ) : null}
          </div>
        </div>
      </AdminLuxPage>
    );
  }
}

export default CustomerSetupChecklistPage;
