import React, { useCallback, useEffect, useState } from "react";
import { getAppBrandName } from "_helpers/brand.utils";
import ProfileSection from "./ProfileSection";
import {
  ProfileSettingSelect,
  ProfileSettingToggle,
  ProfileSettingsBanner,
} from "./ProfileSettingsShared";
import {
  DEFAULT_PREFERENCES,
  readProfilePreferences,
  writeProfilePreferences,
} from "./profileSettings.storage";

const LANDING_OPTIONS = [
  { value: "dashboard", label: "HR dashboard" },
  { value: "timesheet", label: "Timesheet" },
  { value: "projects", label: "Projects" },
  { value: "employees", label: "Employees" },
];

const TIMESHEET_VIEW_OPTIONS = [
  { value: "week", label: "Week board" },
  { value: "summary", label: "Summary first" },
];

function ProfilePreferencesView({ employee, readOnly }) {
  const [prefs, setPrefs] = useState(DEFAULT_PREFERENCES);
  const disabled = !!readOnly;

  useEffect(() => {
    if (employee && employee.id) {
      setPrefs(readProfilePreferences(employee.id));
    }
  }, [employee]);

  const updatePref = useCallback(
    (key, value) => {
      if (disabled || !employee || !employee.id) return;
      setPrefs((prev) => {
        const next = { ...prev, [key]: value };
        writeProfilePreferences(employee.id, next);
        return next;
      });
    },
    [disabled, employee]
  );

  if (!employee) return null;

  const appName = getAppBrandName();

  return (
    <div className="profile-settings profile-preferences lux-settings-tab__stack">
      <ProfileSettingsBanner readOnly={disabled} />

      <ProfileSection
        title="Workspace"
        subtitle={`How ${appName} opens and presents information`}
        icon="fe fe-home"
      >
        <div className="profile-setting-list">
          <ProfileSettingSelect
            icon="fe fe-navigation"
            label="Default landing page"
            description="First screen after sign-in"
            value={prefs.landingPage}
            options={LANDING_OPTIONS}
            disabled={disabled}
            onChange={(v) => updatePref("landingPage", v)}
          />
          <ProfileSettingToggle
            icon="fe fe-minimize-2"
            label="Compact layout"
            description="Tighter spacing on lists and tables"
            checked={prefs.compactLayout}
            disabled={disabled}
            onChange={(v) => updatePref("compactLayout", v)}
          />
        </div>
      </ProfileSection>

      <ProfileSection
        title="Timesheet & calendar"
        subtitle="Scheduling defaults for time entry"
        icon="fe fe-calendar"
      >
        <div className="profile-setting-list">
          <ProfileSettingSelect
            icon="fe fe-grid"
            label="Timesheet default view"
            description="Preferred layout when opening timesheet"
            value={prefs.timesheetView}
            options={TIMESHEET_VIEW_OPTIONS}
            disabled={disabled}
            onChange={(v) => updatePref("timesheetView", v)}
          />
          <ProfileSettingToggle
            icon="fe fe-hash"
            label="Show week numbers"
            description="Display ISO week numbers on the week rail"
            checked={prefs.showWeekNumbers}
            disabled={disabled}
            onChange={(v) => updatePref("showWeekNumbers", v)}
          />
          <ProfileSettingToggle
            icon="fe fe-calendar"
            label="Week starts on Monday"
            description="Align weeks with the business calendar"
            checked={prefs.weekStartsMonday}
            disabled={disabled}
            onChange={(v) => updatePref("weekStartsMonday", v)}
          />
        </div>
      </ProfileSection>

      <ProfileSection
        title="Regional"
        subtitle="Display formats — server-managed when sync is live"
        icon="fe fe-globe"
      >
        <div className="profile-setting-list">
          <ProfileSettingSelect
            icon="fe fe-type"
            label="Date format"
            description="Matches your organization client settings"
            value={prefs.dateFormat}
            options={[
              { value: "client", label: "Organization default (DD-MM-YYYY)" },
              { value: "iso", label: "ISO (YYYY-MM-DD)" },
            ]}
            disabled={disabled}
            onChange={(v) => updatePref("dateFormat", v)}
          />
        </div>
      </ProfileSection>
    </div>
  );
}

export default ProfilePreferencesView;
