import {
  BENCH_STATUSES,
  SIMULATION_ADJUSTMENT_TYPES,
  SKILL_PROFICIENCY_LEVELS,
  STAFFING_REQUEST_STATUSES,
  normalizeProficiencyLevel,
} from "config/resource-planning.config";

export function filterSkillProfiles(rows, filters = {}) {
  let list = Array.isArray(rows) ? [...rows] : [];
  const query = (filters.query || "").trim().toLowerCase();
  if (query) {
    list = list.filter(
      (row) =>
        (row.employeeName || "").toLowerCase().includes(query) ||
        (row.skillName || "").toLowerCase().includes(query) ||
        (row.skillCategory || "").toLowerCase().includes(query)
    );
  }
  if (filters.category && filters.category !== "ALL") {
    const category = String(filters.category).trim().toLowerCase();
    list = list.filter(
      (row) => String(row.skillCategory || "General").trim().toLowerCase() === category
    );
  }
  if (filters.proficiency && filters.proficiency !== "ALL") {
    list = list.filter(
      (row) => normalizeProficiencyLevel(row.proficiencyLevel) === filters.proficiency
    );
  }
  return list;
}

export function buildSkillMatrixMetrics(rows) {
  const list = Array.isArray(rows) ? rows : [];
  const uniqueEmployees = new Set(list.map((row) => row.employeeId).filter(Boolean));
  const uniqueSkills = new Set(list.map((row) => row.skillName).filter(Boolean));
  const experts = list.filter((row) => row.proficiencyLevel === "EXPERT").length;
  const certified = list.filter((row) => row.certified).length;
  const gaps = list.filter((row) => (row.proficiencyScore || 0) <= 1).length;
  return {
    profileCount: list.length,
    employeeCount: uniqueEmployees.size,
    skillCount: uniqueSkills.size,
    expertCount: experts,
    certifiedCount: certified,
    gapCount: gaps,
  };
}

export function buildSkillCategoryOptions(rows) {
  const categories = new Set((rows || []).map((row) => row.skillCategory).filter(Boolean));
  return ["ALL", ...Array.from(categories).sort()];
}

export function buildSkillGapInsights(rows) {
  const list = Array.isArray(rows) ? rows : [];
  return list
    .filter((row) => (row.proficiencyScore || 0) <= 2)
    .slice(0, 5)
    .map((row) => ({
      id: row.id,
      employeeName: row.employeeName,
      skillName: row.skillName,
      proficiencyLabel: row.proficiencyLabel,
      tone: row.proficiencyScore <= 1 ? "rose" : "amber",
    }));
}

export function buildSkillMatrixInsights(rows, metrics) {
  const list = Array.isArray(rows) ? rows : [];
  const insights = [];

  if (metrics.gapCount > 0) {
    insights.push({
      id: "gaps",
      title: `${metrics.gapCount} upskill gap${metrics.gapCount === 1 ? "" : "s"}`,
      copy: "Beginner-level profiles that may block staffing on critical roles.",
      icon: "fe fe-trending-up",
      tone: "amber",
    });
  }

  if (metrics.certifiedCount > 0) {
    insights.push({
      id: "certified",
      title: `${metrics.certifiedCount} certified skill${metrics.certifiedCount === 1 ? "" : "s"}`,
      copy: "Verified credentials ready for client-facing or compliance-heavy work.",
      icon: "fe fe-award",
      tone: "green",
    });
  }

  const topCategory = buildSkillCategoryBreakdown(list)[0];
  if (topCategory) {
    insights.push({
      id: "category",
      title: `${topCategory.category} leads coverage`,
      copy: `${topCategory.count} profile${topCategory.count === 1 ? "" : "s"} · ${topCategory.expertCount} expert-rated`,
      icon: topCategory.icon,
      tone: topCategory.tone,
    });
  }

  return insights.slice(0, 3);
}

export function buildSkillCategoryBreakdown(rows) {
  const list = Array.isArray(rows) ? rows : [];
  const byCategory = {};

  list.forEach((row) => {
    const key = row.skillCategory || "General";
    if (!byCategory[key]) {
      byCategory[key] = { category: key, count: 0, expertCount: 0, avgScore: 0, totalScore: 0 };
    }
    byCategory[key].count += 1;
    byCategory[key].totalScore += row.proficiencyScore || 0;
    if (row.proficiencyLevel === "EXPERT") {
      byCategory[key].expertCount += 1;
    }
  });

  return Object.values(byCategory)
    .map((entry) => {
      const meta = getSkillCategoryMeta(entry.category);
      return {
        ...entry,
        avgScore: entry.count ? Math.round((entry.totalScore / entry.count) * 10) / 10 : 0,
        pct: list.length ? Math.round((entry.count / list.length) * 100) : 0,
        icon: meta.icon,
        tone: meta.tone,
      };
    })
    .sort((a, b) => b.count - a.count);
}

export function buildProficiencyDistribution(rows) {
  const list = Array.isArray(rows) ? rows : [];
  const total = list.length || 1;
  return Object.values(SKILL_PROFICIENCY_LEVELS).map((level) => {
    const count = list.filter((row) => row.proficiencyLevel === level.id).length;
    return {
      id: level.id,
      label: level.label,
      count,
      pct: Math.round((count / total) * 100),
      tone: getProficiencyTone(level.id),
    };
  });
}

export function getEmployeeInitials(name) {
  const parts = (name || "").trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return "?";
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return `${parts[0][0]}${parts[parts.length - 1][0]}`.toUpperCase();
}

export function getSkillCategoryMeta(category) {
  const key = (category || "").toLowerCase();
  if (key.includes("engineer") || key.includes("engineering")) {
    return { icon: "fe fe-code", tone: "violet" };
  }
  if (key.includes("delivery") || key.includes("program")) {
    return { icon: "fe fe-briefcase", tone: "primary" };
  }
  if (key.includes("data")) {
    return { icon: "fe fe-database", tone: "sky" };
  }
  if (key.includes("quality") || key.includes("qa")) {
    return { icon: "fe fe-check-circle", tone: "amber" };
  }
  return { icon: "fe fe-grid", tone: "slate" };
}

export function getProficiencyTone(level) {
  if (level === "EXPERT") return "green";
  if (level === "ADVANCED") return "blue";
  if (level === "INTERMEDIATE") return "amber";
  return "slate";
}

