export function filterStaffingRequests(rows, filters = {}) {
  let list = Array.isArray(rows) ? [...rows] : [];
  const query = (filters.query || "").trim().toLowerCase();
  if (query) {
    list = list.filter(
      (row) =>
        (row.title || "").toLowerCase().includes(query) ||
        (row.projectName || "").toLowerCase().includes(query) ||
        (row.roleNeeded || "").toLowerCase().includes(query) ||
        (row.requesterName || "").toLowerCase().includes(query)
    );
  }
  if (filters.status && filters.status !== "ALL") {
    list = list.filter((row) => row.status === filters.status);
  }
  if (filters.priority && filters.priority !== "ALL") {
    list = list.filter((row) => String(row.priority || "").toUpperCase() === filters.priority);
  }
  return list;
}

export function buildStaffingRequestMetrics(rows) {
  const list = Array.isArray(rows) ? rows : [];
  const open = list.filter(
    (row) =>
      row.status === STAFFING_REQUEST_STATUSES.PENDING ||
      row.status === STAFFING_REQUEST_STATUSES.APPROVED
  );
  const pending = list.filter((row) => row.status === STAFFING_REQUEST_STATUSES.PENDING);
  const highPriority = open.filter((row) => String(row.priority).toUpperCase() === "HIGH");
  const headcountNeeded = open.reduce((sum, row) => sum + (row.headcount || 0), 0);
  const fulfilled = list.filter((row) => row.status === STAFFING_REQUEST_STATUSES.FULFILLED).length;
  return {
    total: list.length,
    openCount: open.length,
    pendingCount: pending.length,
    highPriorityCount: highPriority.length,
    headcountNeeded,
    fulfilledCount: fulfilled,
  };
}

