export function buildBenchMetrics(rows) {
  const list = Array.isArray(rows) ? rows : [];
  const active = list.filter(
    (row) => row.status === BENCH_STATUSES.ON_BENCH || row.status === BENCH_STATUSES.PARTIAL
  );
  const rollingOff = list.filter((row) => row.status === BENCH_STATUSES.ROLLING_OFF);
  const onBench = list.filter((row) => row.status === BENCH_STATUSES.ON_BENCH);
  const partial = list.filter((row) => row.status === BENCH_STATUSES.PARTIAL);
  const placed = list.filter((row) => row.status === BENCH_STATUSES.PLACED);
  const avgAvailability =
    active.length > 0
      ? Math.round(active.reduce((sum, row) => sum + (row.availabilityPct || 0), 0) / active.length)
      : 0;
  const soonRolloff = rollingOff.filter((row) => isRolloffWithinDays(row, 14)).length;
  return {
    total: list.length,
    activeCount: active.length,
    onBenchCount: onBench.length,
    partialCount: partial.length,
    rollingOffCount: rollingOff.length,
    placedCount: placed.length,
    avgAvailabilityPct: avgAvailability,
    soonRolloffCount: soonRolloff,
  };
}

export function isRolloffWithinDays(row, days = 14) {
  const dateStr = row.lastProjectEndDate || row.availableFrom;
  if (!dateStr) {
    return false;
  }
  const end = new Date(dateStr);
  if (Number.isNaN(end.getTime())) {
    return false;
  }
  const now = new Date();
  const diffMs = end.getTime() - now.getTime();
  const diffDays = diffMs / (1000 * 60 * 60 * 24);
  return diffDays >= 0 && diffDays <= days;
}

