export function buildUpcomingRolloffs(rows, limit = 5) {
  return (Array.isArray(rows) ? rows : [])
    .filter((row) => row.status === BENCH_STATUSES.ROLLING_OFF || row.status === BENCH_STATUSES.ON_BENCH)
    .filter((row) => row.lastProjectEndDate || row.availableFrom)
    .sort((a, b) => {
      const dateA = new Date(a.lastProjectEndDate || a.availableFrom).getTime();
      const dateB = new Date(b.lastProjectEndDate || b.availableFrom).getTime();
      return dateA - dateB;
    })
    .slice(0, limit);
}

export function buildOpenStaffingDemand(staffingRequests) {
  const open = (staffingRequests || []).filter(
    (row) =>
      row.status === STAFFING_REQUEST_STATUSES.PENDING ||
      row.status === STAFFING_REQUEST_STATUSES.APPROVED
  );
  return {
    requestCount: open.length,
    headcount: open.reduce((sum, row) => sum + (row.headcount || 0), 0),
    highPriority: open.filter((row) => String(row.priority).toUpperCase() === "HIGH").length,
  };
}

export function buildSimulationBaseline(capacitySummary, staffingRequests, benchRecords) {
  const summary = capacitySummary || {};
  const demand = buildOpenStaffingDemand(staffingRequests);
  const benchPool = (benchRecords || []).filter(
    (row) =>
      row.status === BENCH_STATUSES.ON_BENCH ||
      row.status === BENCH_STATUSES.PARTIAL ||
      row.status === BENCH_STATUSES.ROLLING_OFF
  );
  const benchAvailability = benchPool.reduce((sum, row) => sum + (row.availabilityPct || 0), 0);
  return {
    avgUtilizationPct: summary.avgUtilizationPct != null ? summary.avgUtilizationPct : 0,
    freeHours: summary.freeHours != null ? summary.freeHours : 0,
    overbookedResources: summary.overbookedResources != null ? summary.overbookedResources : 0,
    benchCount: summary.benchCount != null ? summary.benchCount : benchPool.length,
    openDemandHeadcount: demand.headcount,
    openStaffingRequests: demand.requestCount,
    supplyGap: Math.max(0, demand.headcount - Math.round(benchAvailability / 100)),
  };
}

function cloneBaseline(baseline) {
  return { ...baseline };
}

function applyFulfillRequest(projected, adjustment, staffingRequests) {
  const request = (staffingRequests || []).find((row) => row.id === adjustment.requestId);
  if (!request) {
    return projected;
  }
  const headcount = adjustment.headcount != null ? adjustment.headcount : request.headcount || 1;
  const utilBump = Math.min(12, headcount * 4);
  return {
    ...projected,
    openDemandHeadcount: Math.max(0, projected.openDemandHeadcount - headcount),
    openStaffingRequests: Math.max(0, projected.openStaffingRequests - 1),
    avgUtilizationPct: Math.min(100, projected.avgUtilizationPct + utilBump),
    freeHours: Math.max(0, projected.freeHours - headcount * 40),
    benchCount: Math.max(0, projected.benchCount - Math.min(projected.benchCount, headcount)),
    supplyGap: Math.max(0, projected.supplyGap - headcount),
    overbookedResources: Math.max(0, projected.overbookedResources - (adjustment.reduceOverbook ? 1 : 0)),
  };
}

function applyPlaceBench(projected, adjustment) {
  const allocationPct = adjustment.allocationPct != null ? adjustment.allocationPct : 80;
  const utilBump = Math.min(15, Math.round(allocationPct / 8));
  return {
    ...projected,
    benchCount: Math.max(0, projected.benchCount - 1),
    avgUtilizationPct: Math.min(100, projected.avgUtilizationPct + utilBump),
    freeHours: Math.max(0, projected.freeHours - Math.round(allocationPct * 0.4)),
    supplyGap: Math.max(0, projected.supplyGap - 1),
  };
}

function applyShiftAllocation(projected, adjustment) {
  const delta = adjustment.deltaPct != null ? adjustment.deltaPct : -10;
  const utilDelta = Math.round(delta / -4);
  const hoursDelta = Math.round(delta * -0.4);
  return {
    ...projected,
    avgUtilizationPct: Math.max(0, Math.min(100, projected.avgUtilizationPct + utilDelta)),
    freeHours: Math.max(0, projected.freeHours + hoursDelta),
    overbookedResources:
      delta < 0
        ? Math.max(0, projected.overbookedResources - 1)
        : projected.overbookedResources + (delta > 15 ? 1 : 0),
  };
}

export function applySimulationAdjustments(baseline, adjustments, context = {}) {
  let projected = cloneBaseline(baseline);
  (adjustments || []).forEach((adjustment) => {
    if (adjustment.type === SIMULATION_ADJUSTMENT_TYPES.FULFILL_REQUEST) {
      projected = applyFulfillRequest(projected, adjustment, context.staffingRequests);
    } else if (adjustment.type === SIMULATION_ADJUSTMENT_TYPES.PLACE_BENCH) {
      projected = applyPlaceBench(projected, adjustment);
    } else if (adjustment.type === SIMULATION_ADJUSTMENT_TYPES.SHIFT_ALLOCATION) {
      projected = applyShiftAllocation(projected, adjustment);
    }
  });
  return projected;
}

export function buildSimulationComparison(baseline, projected) {
  const metrics = [
    {
      id: "utilization",
      label: "Avg utilization",
      baseline: `${baseline.avgUtilizationPct}%`,
      projected: `${projected.avgUtilizationPct}%`,
      delta: projected.avgUtilizationPct - baseline.avgUtilizationPct,
      tone: projected.avgUtilizationPct > baseline.avgUtilizationPct ? "amber" : "green",
    },
    {
      id: "free-hours",
      label: "Free hours",
      baseline: String(baseline.freeHours),
      projected: String(projected.freeHours),
      delta: projected.freeHours - baseline.freeHours,
      tone: projected.freeHours >= baseline.freeHours ? "green" : "amber",
    },
    {
      id: "demand",
      label: "Open demand",
      baseline: String(baseline.openDemandHeadcount),
      projected: String(projected.openDemandHeadcount),
      delta: projected.openDemandHeadcount - baseline.openDemandHeadcount,
      tone: projected.openDemandHeadcount < baseline.openDemandHeadcount ? "green" : "rose",
    },
    {
      id: "bench",
      label: "Bench pool",
      baseline: String(baseline.benchCount),
      projected: String(projected.benchCount),
      delta: projected.benchCount - baseline.benchCount,
      tone: projected.benchCount <= baseline.benchCount ? "primary" : "sky",
    },
    {
      id: "overbooked",
      label: "Overbooked",
      baseline: String(baseline.overbookedResources),
      projected: String(projected.overbookedResources),
      delta: projected.overbookedResources - baseline.overbookedResources,
      tone: projected.overbookedResources < baseline.overbookedResources ? "green" : "rose",
    },
    {
      id: "gap",
      label: "Supply gap",
      baseline: String(baseline.supplyGap),
      projected: String(projected.supplyGap),
      delta: projected.supplyGap - baseline.supplyGap,
      tone: projected.supplyGap < baseline.supplyGap ? "green" : "rose",
    },
  ];
  return metrics.map((metric) => ({
    ...metric,
    deltaLabel:
      metric.delta === 0
        ? "No change"
        : `${metric.delta > 0 ? "+" : ""}${metric.delta}${metric.id === "utilization" ? "%" : ""}`,
  }));
}

export function buildSimulationInsights(baseline, projected, adjustments) {
  const insights = [];
  const demandDelta = projected.openDemandHeadcount - baseline.openDemandHeadcount;
  const gapDelta = projected.supplyGap - baseline.supplyGap;

  if (demandDelta < 0) {
    insights.push({
      id: "demand",
      title: `${Math.abs(demandDelta)} fewer role${Math.abs(demandDelta) === 1 ? "" : "s"} open`,
      copy: "Scenario closes staffing demand versus baseline.",
      icon: "fe fe-check-circle",
      tone: "green",
    });
  }

  if (gapDelta < 0) {
    insights.push({
      id: "gap",
      title: "Supply gap narrows",
      copy: `Gap drops from ${baseline.supplyGap} to ${projected.supplyGap} roles.`,
      icon: "fe fe-trending-up",
      tone: "primary",
    });
  }

  if (projected.overbookedResources < baseline.overbookedResources) {
    insights.push({
      id: "overbook",
      title: "Overbooking reduced",
      copy: "Rebalancing frees overloaded consultants.",
      icon: "fe fe-shield",
      tone: "green",
    });
  }

  if (insights.length === 0 && (adjustments || []).length > 0) {
    insights.push({
      id: "neutral",
      title: "Scenario modeled",
      copy: "Adjustments applied — review comparison strip for net impact.",
      icon: "fe fe-sliders",
      tone: "sky",
    });
  }

  return insights.slice(0, 3);
}

export function formatSimulationAdjustmentLabel(adjustment, context = {}) {
  if (adjustment.type === SIMULATION_ADJUSTMENT_TYPES.FULFILL_REQUEST) {
    const request = (context.staffingRequests || []).find((row) => row.id === adjustment.requestId);
    return request ? `Fulfill: ${request.title}` : "Fulfill staffing request";
  }
  if (adjustment.type === SIMULATION_ADJUSTMENT_TYPES.PLACE_BENCH) {
    const bench = (context.benchRecords || []).find((row) => row.id === adjustment.benchId);
    return bench
      ? `Place ${bench.employeeName} on ${adjustment.projectName || "project"} (${adjustment.allocationPct || 80}%)`
      : "Place bench consultant";
  }
  if (adjustment.type === SIMULATION_ADJUSTMENT_TYPES.SHIFT_ALLOCATION) {
    const allocation = (context.allocations || []).find((row) => row.id === adjustment.allocationId);
    const delta = adjustment.deltaPct != null ? adjustment.deltaPct : -10;
    return allocation
      ? `Shift ${allocation.employeeName}: ${delta > 0 ? "+" : ""}${delta}% on ${allocation.projectName}`
      : `Shift allocation ${delta > 0 ? "+" : ""}${delta}%`;
  }
  return "Adjustment";
}

export function buildOverallocatedEmployees(allocations) {
  const byEmployee = {};
  (allocations || []).forEach((row) => {
    if (!row.employeeId) {
      return;
    }
    if (!byEmployee[row.employeeId]) {
      byEmployee[row.employeeId] = {
        employeeId: row.employeeId,
        employeeName: row.employeeName,
        totalPct: 0,
        projects: [],
      };
    }
    byEmployee[row.employeeId].totalPct += row.allocationPct || 0;
    byEmployee[row.employeeId].projects.push(row.projectName);
  });
  return Object.values(byEmployee)
    .filter((row) => row.totalPct > 100)
    .sort((a, b) => b.totalPct - a.totalPct);
}

export function buildResourceAnalyticsMetrics(
  capacitySummary,
  allocations,
  staffingRequests,
  benchRecords,
  skillProfiles
) {
  const demand = buildOpenStaffingDemand(staffingRequests);
  const benchMetrics = buildBenchMetrics(benchRecords);
  const overallocated = buildOverallocatedEmployees(allocations);
  const skillGaps = (skillProfiles || []).filter((row) => (row.proficiencyScore || 0) <= 2).length;
  const summary = capacitySummary || {};
  return {
    avgUtilizationPct: summary.avgUtilizationPct != null ? summary.avgUtilizationPct : 0,
    freeHours: summary.freeHours != null ? summary.freeHours : 0,
    openDemandHeadcount: demand.headcount,
    openStaffingRequests: demand.requestCount,
    benchCount: benchMetrics.activeCount,
    rollingOffCount: benchMetrics.rollingOffCount,
    overbookedCount: overallocated.length || summary.overbookedResources || 0,
    skillGapCount: skillGaps,
    supplyGap: Math.max(0, demand.headcount - benchMetrics.onBenchCount),
  };
}

export function buildCapacityVsDemandSeries(capacitySummary, staffingRequests, benchRecords) {
  const demand = buildOpenStaffingDemand(staffingRequests);
  const benchMetrics = buildBenchMetrics(benchRecords);
  const summary = capacitySummary || {};
  const roster = summary.rosterSize != null ? summary.rosterSize : 6;
  const allocated = Math.max(0, roster - benchMetrics.activeCount);
  return [
    { label: "Allocated", value: allocated, tone: "sky" },
    { label: "Bench / partial", value: benchMetrics.activeCount, tone: "primary" },
    { label: "Open demand", value: demand.headcount, tone: "rose" },
  ];
}

export function buildAllocationByProjectSeries(allocations) {
  const byProject = {};
  (allocations || []).forEach((row) => {
    const key = row.projectName || "Unassigned";
    if (!byProject[key]) {
      byProject[key] = { label: key, value: 0, tone: "violet" };
    }
    byProject[key].value += row.allocationPct || 0;
  });
  return Object.values(byProject)
    .sort((a, b) => b.value - a.value)
    .slice(0, 6)
    .map((row, index) => ({
      ...row,
      tone: index === 0 ? "primary" : index === 1 ? "violet" : "sky",
      meta: `${row.value}% total`,
    }));
}

export function buildBenchTrendSeries(trendRows) {
  return (trendRows || []).map((row, index) => ({
    label: row.label,
    value: row.value,
    tone: index === (trendRows || []).length - 1 ? "amber" : "primary",
  }));
}

export function buildOverallocatedSeries(allocations) {
  return buildOverallocatedEmployees(allocations)
    .slice(0, 5)
    .map((row) => ({
      label: row.employeeName,
      value: row.totalPct,
      tone: row.totalPct > 120 ? "rose" : "amber",
      meta: `${row.totalPct}%`,
    }));
}

export function buildRolloffSeries(benchRecords) {
  return buildUpcomingRolloffs(benchRecords, 5).map((row) => ({
    label: row.employeeName,
    value: row.availabilityPct != null ? row.availabilityPct : 100,
    tone: row.status === BENCH_STATUSES.ROLLING_OFF ? "amber" : "primary",
    meta: row.lastProjectEndDate || row.availableFrom || "",
  }));
}

export function buildSkillGapSeries(skillProfiles) {
  return (skillProfiles || [])
    .filter((row) => (row.proficiencyScore || 0) <= 2)
    .slice(0, 5)
    .map((row) => ({
      label: `${row.employeeName} · ${row.skillName}`,
      value: row.proficiencyScore || 1,
      tone: row.proficiencyScore <= 1 ? "rose" : "amber",
      meta: row.proficiencyLabel,
    }));
}

export function buildAllocationHeatmap(allocations) {
  const byEmployee = {};
  (allocations || []).forEach((row) => {
    if (!row.employeeId) {
      return;
    }
    if (!byEmployee[row.employeeId]) {
      byEmployee[row.employeeId] = {
        employeeId: row.employeeId,
        employeeName: row.employeeName,
        totalPct: 0,
        cells: [],
      };
    }
    const pct = row.allocationPct || 0;
    byEmployee[row.employeeId].totalPct += pct;
    byEmployee[row.employeeId].cells.push({
      id: row.id,
      projectName: row.projectName,
      allocationPct: pct,
      tone: pct >= 70 ? "rose" : pct >= 50 ? "amber" : "green",
    });
  });
  return Object.values(byEmployee).sort((a, b) => b.totalPct - a.totalPct);
}

export function buildResourceAnalyticsChartBundle(context = {}) {
  const {
    capacitySummary,
    allocations,
    staffingRequests,
    benchRecords,
    skillProfiles,
    benchTrend,
  } = context;
  return {
    capacityVsDemand: buildCapacityVsDemandSeries(capacitySummary, staffingRequests, benchRecords),
    allocationByProject: buildAllocationByProjectSeries(allocations),
    benchTrend: buildBenchTrendSeries(benchTrend),
    overallocatedUsers: buildOverallocatedSeries(allocations),
    upcomingRolloffs: buildRolloffSeries(benchRecords),
    skillGaps: buildSkillGapSeries(skillProfiles),
    heatmap: buildAllocationHeatmap(allocations),
  };
}

export function buildResourceAnalyticsInsights(metrics, charts) {
  const insights = [];
  if (metrics.supplyGap > 0) {
    insights.push({
      id: "gap",
      title: `${metrics.supplyGap} role supply gap`,
      copy: `${metrics.openDemandHeadcount} open demand vs ${metrics.benchCount} bench/partial consultants.`,
      icon: "fe fe-alert-triangle",
      tone: "rose",
    });
  }
  if (metrics.overbookedCount > 0) {
    insights.push({
      id: "overbook",
      title: `${metrics.overbookedCount} overallocated`,
      copy: "Review allocation heatmap and rebalance before new staffing.",
      icon: "fe fe-activity",
      tone: "amber",
    });
  }
  if (metrics.skillGapCount > 0) {
    insights.push({
      id: "skills",
      title: `${metrics.skillGapCount} skill gap${metrics.skillGapCount === 1 ? "" : "s"}`,
      copy: "Beginner-level profiles may block critical staffing matches.",
      icon: "fe fe-trending-up",
      tone: "sky",
    });
  }
  if (charts.benchTrend && charts.benchTrend.length > 1) {
    const latest = charts.benchTrend[charts.benchTrend.length - 1];
    const prior = charts.benchTrend[charts.benchTrend.length - 2];
    if (latest.value > prior.value) {
      insights.push({
        id: "bench",
        title: "Bench trend rising",
        copy: `Bench pool grew to ${latest.value} consultants this period.`,
        icon: "fe fe-user-minus",
        tone: "primary",
      });
    }
  }
  return insights.slice(0, 3);
}
