import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isAiWorkIntelligenceEnabled } from "config/ai-work-intelligence.config";
import { AI_RECOMMENDATIONS_PAGE_META } from "config/ai-work-intelligence-nav.config";
import { buildAgentConsoleKpis } from "config/ai-work-intelligence.utils";
import { canViewAiWorkIntelligence } from "config/ai-work-intelligence-security.utils";
import { aiWorkIntelligenceService } from "_services/aiWorkIntelligence.service";
import AiLuxPage, { AiActionButton, AiLuxPanel } from "views/ai/components/AiLuxShared";
import AgentRecommendationPanel from "views/ai/components/AgentRecommendationPanel";

class AIRecommendationsPage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    kpiCards: [],
    recommendations: [],
    selectedRecommendationId: null,
    statusFilter: "ALL",
    busyId: null,
  };

  componentDidMount() {
    this.loadData();
  }

  getActivePersona = () => {
    const personaCtx = this.props.personaContext || {};
    return personaCtx.activePersona || "EXECUTIVE";
  };

  loadData = async () => {
    const persona = this.getActivePersona();
    const { statusFilter } = this.state;
    this.setState({ loading: true, loadError: null });
    try {
      const filters = { persona };
      if (statusFilter !== "ALL") {
        filters.status = statusFilter;
      }
      const [overviewResult, recsResult] = await Promise.all([
        aiWorkIntelligenceService.getAgentConsoleOverview({ persona }),
        aiWorkIntelligenceService.listRecommendations(filters),
      ]);
      const recommendations = recsResult.payload || [];
      this.setState({
        loading: false,
        dataSource: recsResult.source,
        kpiCards: buildAgentConsoleKpis((overviewResult.payload || {}).overview),
        recommendations,
        selectedRecommendationId: recommendations[0] ? recommendations[0].id : null,
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load recommendations.",
      });
    }
  };

  handleDecide = async (recommendationId, decision, rationale) => {
    const persona = this.getActivePersona();
    this.setState({ busyId: recommendationId, loadError: null });
    try {
      await aiWorkIntelligenceService.decideRecommendation(recommendationId, decision, rationale, { persona });
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to record decision." });
    } finally {
      this.setState({ busyId: null });
    }
  };

  render() {
    if (!isAiWorkIntelligenceEnabled()) {
      return <PersonaAccessDenied title="AI recommendations" message="AI work intelligence is not enabled for this organization." />;
    }
    const persona = this.getActivePersona();
    if (!canViewAiWorkIntelligence(persona)) {
      return <PersonaAccessDenied title="AI recommendations" message="Your persona cannot access AI recommendations." />;
    }

    const { loading, loadError, dataSource, kpiCards, recommendations, selectedRecommendationId, statusFilter, busyId } = this.state;

    return (
      <AiLuxPage
        pageMeta={AI_RECOMMENDATIONS_PAGE_META}
        pageId="decision-audit"
        shellTitle="AI recommendations"
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        heroActions={
          <AiActionButton icon="fe fe-refresh-cw" onClick={this.loadData} disabled={loading}>
            Refresh
          </AiActionButton>
        }
      >
        {loadError ? <p className="lux-ai-intel-error">{loadError}</p> : null}

        <AiLuxPanel
          title="Recommendation inbox"
          meta="Filter by status and record accept/reject/defer decisions"
          icon="fe fe-inbox"
          accent="indigo"
          featured
          actions={
            <select
              className="lux-ai-intel-filter"
              value={statusFilter}
              onChange={(event) => this.setState({ statusFilter: event.target.value }, this.loadData)}
            >
              <option value="ALL">All statuses</option>
              <option value="draft">Draft</option>
              <option value="accepted">Accepted</option>
              <option value="rejected">Rejected</option>
              <option value="deferred">Deferred</option>
            </select>
          }
        >
          <AgentRecommendationPanel
            recommendations={recommendations}
            activePersona={persona}
            selectedRecommendationId={selectedRecommendationId}
            onSelectRecommendation={(id) => this.setState({ selectedRecommendationId: id })}
            onDecide={this.handleDecide}
            busyId={busyId}
            loading={loading}
          />
        </AiLuxPanel>
      </AiLuxPage>
    );
  }
}

export default AIRecommendationsPage;
