import React, { useEffect } from "react";
import { useReportPageDataSource } from "views/common/PageChromeContext";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import { AdminInsightStrip } from "views/admin/components/AdminLuxShared";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import LuxKpiStrip from "views/common/fragments/LuxKpiStrip";

export default function AiLuxPage({
  pageMeta,
  dataSource,
  demoLabel = "Demo AI work intelligence data",
  heroActions,
  kpiCards,
  loading,
  pageHeaderNameChangeHandler,
  shellTitle,
  testId,
  pageId,
  children,
}) {
  useReportPageDataSource(dataSource);
  const meta = pageMeta || {
    tone: "violet",
    icon: "fe fe-cpu",
    eyebrow: "AI",
    titleLead: "Work",
    titleAccent: "intelligence",
    lede: "Agent registry, recommendations, and human-in-the-loop decisions.",
  };

  useEffect(() => {
    if (pageHeaderNameChangeHandler && shellTitle) {
      pageHeaderNameChangeHandler(shellTitle);
    }
  }, [pageHeaderNameChangeHandler, shellTitle]);

  return (
    <div
      className={classNames("lux-register-page", "lux-ai-module", "lux-ai-intel-lux", meta.tone && `is-${meta.tone}`)}
      data-testid={testId || (pageId ? `page-ai-${pageId}` : undefined)}
    >
      <div className="lux-ai-intel-lux__ambient" aria-hidden="true">
        <span className="lux-ai-intel-lux__orb lux-ai-intel-lux__orb--a" />
        <span className="lux-ai-intel-lux__orb lux-ai-intel-lux__orb--b" />
        <span className="lux-ai-intel-lux__orb lux-ai-intel-lux__orb--c" />
      </div>
      <LuxModuleIntro meta={meta} actions={heroActions || undefined} />

      <div className="lux-register-page__body">
        {kpiCards && kpiCards.length ? (
          <LuxKpiStrip cards={kpiCards} loading={loading} className="lux-ai-intel-lux__kpi-strip" />
        ) : null}

        <div className="lux-ai-intel-lux__content">{children}</div>
      </div>
    </div>
  );
}

export function AiActionButton({ to, onClick, icon, variant = "ghost", children, disabled, className }) {
  const classes = classNames("lux-onb-action", "lux-ai-intel-action", `lux-onb-action--${variant}`, className);
  const content = icon ? (
    <>
      <i className={icon} aria-hidden="true" />
      <span>{children}</span>
    </>
  ) : (
    children
  );
  if (to && !onClick) {
    return (
      <Link to={to} className={classes}>
        {content}
      </Link>
    );
  }
  return (
    <button type="button" className={classes} onClick={onClick} disabled={disabled}>
      {content}
    </button>
  );
}

export function AiLuxPanel({ title, meta, icon, accent, actions, children, featured }) {
  return (
    <section
      className={classNames(
        "lux-hrms-dash__panel",
        "lux-ai-intel-lux__panel",
        accent && `is-${accent}`,
        featured && "lux-ai-intel-lux__panel--featured"
      )}
    >
      <header className="lux-hrms-dash__panel-head lux-ai-intel-lux__panel-head">
        <div className="lux-ai-intel-lux__panel-head-main">
          {icon ? <i className={icon} aria-hidden="true" /> : null}
          <div>
            <h2 className="lux-hrms-dash__panel-title">{title}</h2>
            {meta ? <p className="lux-hrms-dash__panel-sub">{meta}</p> : null}
          </div>
        </div>
        {actions ? <div className="lux-hrms-dash__panel-actions lux-ai-intel-lux__panel-actions">{actions}</div> : null}
      </header>
      <div className="lux-hrms-dash__panel-body lux-ai-intel-lux__panel-body">{children}</div>
    </section>
  );
}

export function AiInsightPanel({ insights }) {
  if (!insights || !insights.length) {
    return null;
  }
  return <AdminInsightStrip insights={insights} className="lux-ai-intel-lux__insights" />;
}

export function AiConfidenceBadge({ band, confidence }) {
  const tone = (band && band.tone) || "warning";
  return (
    <span className={classNames("lux-ai-intel-chip", `is-${tone}`)}>
      {(band && band.label) || "Confidence"} · {Math.round((Number(confidence) || 0) * 100)}%
    </span>
  );
}

export function AiConfidenceRing({ confidence, band }) {
  const pct = Math.round((Number(confidence) || 0) * 100);
  const tone = (band && band.tone) || "warning";
  const circumference = 226;
  const offset = circumference - (pct / 100) * circumference;

  return (
    <div className={classNames("lux-ai-intel-confidence-ring", `is-${tone}`)} aria-label={`${pct}% confidence`}>
      <svg viewBox="0 0 80 80" aria-hidden="true">
        <circle className="lux-ai-intel-confidence-ring__track" cx="40" cy="40" r="36" />
        <circle
          className="lux-ai-intel-confidence-ring__value"
          cx="40"
          cy="40"
          r="36"
          style={{ strokeDashoffset: offset }}
        />
      </svg>
      <strong>{pct}%</strong>
      <span>{(band && band.label) || "Confidence"}</span>
    </div>
  );
}
