import React, { Component } from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { ADMIN_PAGE_META } from "config/admin-page-meta.config";
import { isAccessRequestsAdminEnabled, ACCESS_REQUEST_STATUSES } from "config/asset-register.config";
import { filterAccessRequests } from "config/asset-register.utils";
import {
  buildAccessRequestAdminMetrics,
  buildAccessRequestInsights,
  getAccessRequestTypeMeta,
} from "config/access-request-admin.utils";
import { assetRegisterService } from "_services/assetRegister.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import AccessRequestRegister from "views/admin/components/AccessRequestRegister";
import {
  AdminActionButton,
  AdminInsightStrip,
  AdminPanelHead,
  AdminPanelLink,
  AdminLuxPage,
} from "views/admin/components/AdminLuxShared";

const EMPTY_DRAFT = {
  type: "ACCESS",
  title: "",
  requesterId: "",
  requesterName: "",
  priority: "NORMAL",
  assetTag: "",
  notes: "",
};

const REQUEST_TYPE_OPTIONS = [
  { value: "ACCESS", hint: "Apps, VPN, or system roles" },
  { value: "SOFTWARE", hint: "Licenses and SaaS seats" },
  { value: "HARDWARE", hint: "Monitors and peripherals" },
  { value: "LAPTOP", hint: "Notebook provisioning" },
  { value: "MOBILE", hint: "Phone or tablet access" },
  { value: "SYSTEM", hint: "Environment or infra access" },
];

const PRIORITY_OPTIONS = [
  { value: "LOW", label: "Low", hint: "Can wait" },
  { value: "NORMAL", label: "Normal", hint: "Standard SLA" },
  { value: "HIGH", label: "High", hint: "Blocks delivery" },
];

class AccessRequestsPage extends Component {
  state = {
    requests: [],
    loading: true,
    loadError: null,
    dataSource: null,
    statusFilter: "Pending",
    query: "",
    acting: false,
    createOpen: false,
    creating: false,
    createError: null,
    createSuccess: null,
    draft: { ...EMPTY_DRAFT },
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Access requests");
    this.loadRequests();
  }

  componentDidUpdate(_prevProps, prevState) {
    if (prevState.createOpen !== this.state.createOpen) {
      document.body.style.overflow = this.state.createOpen ? "hidden" : "";
    }
  }

  componentWillUnmount() {
    document.body.style.overflow = "";
  }

  loadRequests = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await assetRegisterService.listAccessRequests();
      this.setState({
        requests: result.payload || [],
        loading: false,
        dataSource: result.source || null,
      });
    } catch (e) {
      this.setState({
        loading: false,
        loadError: "Unable to load access requests.",
        requests: [],
      });
    }
  };

  handleStatusUpdate = async (request, status) => {
    this.setState({ acting: true });
    try {
      await assetRegisterService.updateAccessRequestStatus(request.id, status);
      await this.loadRequests();
    } finally {
      this.setState({ acting: false });
    }
  };

  openCreateDrawer = () => {
    this.setState({
      createOpen: true,
      createError: null,
      createSuccess: null,
      draft: { ...EMPTY_DRAFT },
    });
  };

  closeCreateDrawer = () => {
    if (this.state.creating) {
      return;
    }
    this.setState({
      createOpen: false,
      createError: null,
    });
  };

  handleDraftChange = (field, value) => {
    this.setState((state) => ({
      draft: {
        ...state.draft,
        [field]: value,
      },
      createError: null,
    }));
  };

  handleCreateRequest = async (event) => {
    event.preventDefault();
    const { draft } = this.state;
    const title = String(draft.title || "").trim();
    if (!title) {
      this.setState({ createError: "Enter a request title before submitting." });
      return;
    }

    this.setState({ creating: true, createError: null, createSuccess: null });
    const payload = {
      type: draft.type,
      title,
      requesterId: String(draft.requesterId || "").trim() || undefined,
      requesterName: String(draft.requesterName || "").trim(),
      priority: draft.priority,
      assetTag: String(draft.assetTag || "").trim(),
      notes: String(draft.notes || "").trim(),
    };

    try {
      const result = await assetRegisterService.createAccessRequest(payload);
      if (!result || !result.payload) {
        throw new Error("Create request failed");
      }
      this.setState({
        creating: false,
        createOpen: false,
        statusFilter: ACCESS_REQUEST_STATUSES.PENDING,
        draft: { ...EMPTY_DRAFT },
        createSuccess: "Access request submitted to the approval queue.",
      });
      await this.loadRequests();
    } catch (e) {
      this.setState({
        creating: false,
        createError: "Unable to create the access request. Check API configuration and try again.",
      });
    }
  };

  renderCreateField(label, icon, children, options = {}) {
    const { wide = false, hint = null } = options;
    return (
      <label
        className={classNames("lux-access-request-drawer__field", {
          "lux-access-request-drawer__field--wide": wide,
        })}
      >
        <span className="lux-access-request-drawer__label">
          {icon ? <i className={icon} aria-hidden="true" /> : null}
          {label}
        </span>
        {children}
        {hint ? <small className="lux-access-request-drawer__hint">{hint}</small> : null}
      </label>
    );
  }

  renderCreateDrawer() {
    const { createOpen, creating, createError, draft } = this.state;
    if (!createOpen || typeof document === "undefined") {
      return null;
    }

    const selectedType = getAccessRequestTypeMeta(draft.type);

    return createPortal(
      <div
        className="lux-onb-drawer-backdrop lux-access-request-drawer-backdrop"
        role="presentation"
        onClick={this.closeCreateDrawer}
        data-testid="access-request-create-backdrop"
      >
        <aside
          className="lux-onb-drawer lux-gov-drawer lux-onb-drawer--primary lux-access-request-drawer"
          data-testid="access-request-create-panel"
          role="dialog"
          aria-modal="true"
          aria-labelledby="access-request-drawer-title"
          onClick={(event) => event.stopPropagation()}
        >
          <span className="lux-onb-drawer__accent" aria-hidden="true" />

          <header className="lux-onb-drawer__head">
            <div className="lux-onb-drawer__head-main">
              <span className={classNames("lux-onb-drawer__category-icon", selectedType.tone && `is-${selectedType.tone}`)} aria-hidden="true">
                <i className={selectedType.icon} />
              </span>
              <div className="lux-onb-drawer__head-copy">
                <span className="lux-onb-drawer__eyebrow">Admin · Access requests</span>
                <h2 id="access-request-drawer-title">New access request</h2>
                <p className="lux-gov-drawer__subtitle">
                  Capture IT access, software, or hardware needs and route them into the approval queue.
                </p>
                <div className="lux-onb-drawer__badges">
                  <span className="lux-onb-drawer__pill lux-onb-drawer__pill--required">Submit → Approve → Fulfill</span>
                  <span className="lux-onb-drawer__pill lux-onb-drawer__pill--optional">{selectedType.label}</span>
                </div>
              </div>
            </div>
            <button
              type="button"
              className="lux-onb-drawer__close"
              onClick={this.closeCreateDrawer}
              disabled={creating}
              aria-label="Close"
              data-testid="access-request-create-close"
            >
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </header>

          <form className="lux-onb-drawer__body lux-access-request-drawer__body" onSubmit={this.handleCreateRequest}>
            <div className="lux-access-request-drawer__scroll">
              {createError && (
                <div className="lux-access-request-drawer__alert is-danger" role="alert">
                  <i className="fe fe-alert-triangle" aria-hidden="true" />
                  <span>{createError}</span>
                </div>
              )}

              <div className="lux-access-request-drawer__banner">
                <i className="fe fe-shield" aria-hidden="true" />
                <div>
                  <strong>Provisioned through the managed queue</strong>
                  <p>Requests land as pending for IT/HR, then move to approved and fulfilled once access is granted.</p>
                </div>
              </div>

              <section className="lux-access-request-drawer__section">
                <div className="lux-access-request-drawer__section-head">
                  <h3>Request type</h3>
                  <p>Choose what the employee needs provisioned.</p>
                </div>
                <div className="lux-access-request-drawer__type-grid" role="radiogroup" aria-label="Request type">
                  {REQUEST_TYPE_OPTIONS.map((option) => {
                    const meta = getAccessRequestTypeMeta(option.value);
                    const selected = draft.type === option.value;
                    return (
                      <button
                        key={option.value}
                        type="button"
                        role="radio"
                        aria-checked={selected}
                        className={classNames(
                          "lux-access-request-drawer__type-card",
                          meta.tone && `is-${meta.tone}`,
                          { "is-selected": selected }
                        )}
                        disabled={creating}
                        onClick={() => this.handleDraftChange("type", option.value)}
                      >
                        <span className="lux-access-request-drawer__type-icon" aria-hidden="true">
                          <i className={meta.icon} />
                        </span>
                        <span className="lux-access-request-drawer__type-copy">
                          <strong>{meta.label}</strong>
                          <small>{option.hint}</small>
                        </span>
                      </button>
                    );
                  })}
                </div>
              </section>

              <section className="lux-access-request-drawer__section">
                <div className="lux-access-request-drawer__section-head">
                  <h3>Priority</h3>
                  <p>Set urgency so the queue can triage correctly.</p>
                </div>
                <div className="lux-access-request-drawer__priority-row" role="radiogroup" aria-label="Priority">
                  {PRIORITY_OPTIONS.map((option) => {
                    const selected = draft.priority === option.value;
                    return (
                      <button
                        key={option.value}
                        type="button"
                        role="radio"
                        aria-checked={selected}
                        className={classNames("lux-access-request-drawer__priority-chip", {
                          "is-selected": selected,
                          "is-high": option.value === "HIGH",
                        })}
                        disabled={creating}
                        onClick={() => this.handleDraftChange("priority", option.value)}
                      >
                        <strong>{option.label}</strong>
                        <span>{option.hint}</span>
                      </button>
                    );
                  })}
                </div>
              </section>

              <section className="lux-access-request-drawer__section">
                <div className="lux-access-request-drawer__section-head">
                  <h3>Request details</h3>
                  <p>Title and requester context used in the approval queue.</p>
                </div>
                <div className="lux-access-request-drawer__grid">
                  {this.renderCreateField(
                    "Title",
                    "fe fe-edit-3",
                    <input
                      type="text"
                      className="lux-access-request-drawer__input"
                      value={draft.title}
                      placeholder="Example: Jira admin access for release support"
                      onChange={(event) => this.handleDraftChange("title", event.target.value)}
                      disabled={creating}
                      required
                      autoFocus
                    />,
                    { wide: true }
                  )}
                  {this.renderCreateField(
                    "Requester employee ID",
                    "fe fe-hash",
                    <input
                      type="text"
                      className="lux-access-request-drawer__input"
                      value={draft.requesterId}
                      placeholder="Defaults to current user"
                      onChange={(event) => this.handleDraftChange("requesterId", event.target.value)}
                      disabled={creating}
                    />,
                    { hint: "Leave blank to use the signed-in employee." }
                  )}
                  {this.renderCreateField(
                    "Requester name",
                    "fe fe-user",
                    <input
                      type="text"
                      className="lux-access-request-drawer__input"
                      value={draft.requesterName}
                      placeholder="Employee display name"
                      onChange={(event) => this.handleDraftChange("requesterName", event.target.value)}
                      disabled={creating}
                    />
                  )}
                  {this.renderCreateField(
                    "Asset tag or system",
                    "fe fe-tag",
                    <input
                      type="text"
                      className="lux-access-request-drawer__input"
                      value={draft.assetTag}
                      placeholder="Optional: JIRA, VPN, AST-1042"
                      onChange={(event) => this.handleDraftChange("assetTag", event.target.value)}
                      disabled={creating}
                    />,
                    { wide: true, hint: "Link to an asset tag, app code, or environment name." }
                  )}
                  {this.renderCreateField(
                    "Business reason",
                    "fe fe-message-square",
                    <textarea
                      className="lux-access-request-drawer__textarea"
                      rows="4"
                      value={draft.notes}
                      placeholder="Describe why this access or asset is needed and any deadline."
                      onChange={(event) => this.handleDraftChange("notes", event.target.value)}
                      disabled={creating}
                    />,
                    { wide: true }
                  )}
                </div>
              </section>
            </div>

            <footer className="lux-onb-drawer__foot lux-access-request-drawer__foot">
              <div className="lux-onb-drawer__foot-actions">
                <button
                  type="button"
                  className="lux-access-request-drawer__btn is-ghost"
                  onClick={() => this.setState({ draft: { ...EMPTY_DRAFT }, createError: null })}
                  disabled={creating}
                >
                  Reset
                </button>
                <button
                  type="button"
                  className="lux-access-request-drawer__btn is-ghost"
                  onClick={this.closeCreateDrawer}
                  disabled={creating}
                >
                  Cancel
                </button>
                <button type="submit" className="lux-access-request-drawer__btn is-primary" disabled={creating}>
                  <i className="fe fe-send" aria-hidden="true" />
                  {creating ? "Submitting…" : "Submit request"}
                </button>
              </div>
              <p className="lux-onb-drawer__foot-hint">
                Submitted requests appear immediately in the pending queue for IT/HR action.
              </p>
            </footer>
          </form>
        </aside>
      </div>,
      document.body
    );
  }

  getFilteredRequests = () => {
    const { requests, statusFilter, query } = this.state;
    return filterAccessRequests(requests, {
      status: statusFilter === "ALL" ? null : statusFilter,
      query,
    });
  };

  render() {
    if (!isAccessRequestsAdminEnabled()) {
      return (
        <PersonaAccessDenied
          moduleName="Access requests"
          reason="Access request queue is not enabled for your organization."
        />
      );
    }

    const { loading, loadError, dataSource, statusFilter, query, acting, createSuccess } = this.state;
    const rows = this.getFilteredRequests();
    const metrics = buildAccessRequestAdminMetrics(this.state.requests);
    const insights = loading ? [] : buildAccessRequestInsights(this.state.requests);
    const kpiCards = [
      { id: "pending", label: "Pending", value: metrics.pending, hint: "Needs IT/HR action", tone: "amber", icon: "fe fe-inbox" },
      { id: "approved", label: "Approved", value: metrics.approved, hint: "Awaiting fulfillment", tone: "primary", icon: "fe fe-check" },
      { id: "fulfilled", label: "Fulfilled", value: metrics.fulfilled, hint: "Complete", tone: "green", icon: "fe fe-check-circle" },
      { id: "total", label: "Total", value: metrics.total, hint: metrics.highPriority ? `${metrics.highPriority} high priority` : "All requests", tone: "slate", icon: "fe fe-layers" },
    ];

    return (
      <AdminLuxPage
        pageMeta={ADMIN_PAGE_META.accessRequests}
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        className="lux-register-page lux-access-request-page"
        testId="page-admin-access-requests"
        heroActions={
          <>
            <AdminActionButton
              icon="fe fe-plus"
              onClick={this.openCreateDrawer}
              testId="access-request-open-create"
            >
              New request
            </AdminActionButton>
            <AdminActionButton icon="fe fe-refresh-cw" onClick={this.loadRequests} disabled={loading} variant="ghost">
              Refresh
            </AdminActionButton>
          </>
        }
      >
        {loadError && (
          <div className="lux-employee-360__error lux-access-request__error" role="alert">
            <span>{loadError}</span>
            <AdminActionButton variant="ghost" onClick={this.loadRequests}>
              Retry
            </AdminActionButton>
          </div>
        )}

        {createSuccess && (
          <div className="lux-employee-360__success lux-access-request__success" role="status">
            <i className="fe fe-check-circle" aria-hidden="true" />
            <span>{createSuccess}</span>
          </div>
        )}

        <AdminInsightStrip insights={insights} />

        {this.renderCreateDrawer()}

        <section className="lux-hrms-dash__panel lux-access-request-panel">
          <AdminPanelHead
            title="Request queue"
            subtitle="Approve, reject, or mark fulfilled once IT provisioning is complete"
            actions={<AdminPanelLink to="/people/assets">Asset register</AdminPanelLink>}
          />

          <div className="lux-access-request-panel__toolbar">
            <div className="lux-appr-toolbar__row">
              <div className="lux-appr-toolbar__search">
                <i className="fe fe-search" aria-hidden="true" />
                <input
                  type="search"
                  className="lux-appr-toolbar__search-input"
                  placeholder="Search requests, requesters, or notes"
                  value={query}
                  onChange={(event) => this.setState({ query: event.target.value })}
                />
              </div>
              <span className="lux-appr-toolbar__count">
                <strong>{rows.length}</strong> request{rows.length === 1 ? "" : "s"}
              </span>
            </div>
            <div className="lux-appr-toolbar__group">
              <span className="lux-appr-toolbar__label">Status</span>
              <div className="lux-hrms-dash__filter-group">
                {["ALL", ACCESS_REQUEST_STATUSES.PENDING, ACCESS_REQUEST_STATUSES.APPROVED, ACCESS_REQUEST_STATUSES.FULFILLED, ACCESS_REQUEST_STATUSES.REJECTED].map(
                  (value) => (
                    <button
                      key={value}
                      type="button"
                      className={classNames("lux-hrms-dash__filter-chip", {
                        "is-active": statusFilter === value,
                      })}
                      onClick={() => this.setState({ statusFilter: value })}
                    >
                      {value === "ALL" ? "All" : value}
                    </button>
                  )
                )}
              </div>
            </div>
          </div>

          <div className="lux-hrms-dash__panel-body">
            {loading ? (
              <LuxRegisterEmptyState
                className="lux-register-empty--compact"
                title="Loading access requests"
                description="Fetching IT and hardware request queue."
              />
            ) : rows.length === 0 ? (
              <LuxRegisterEmptyState
                className="lux-register-empty--compact"
                icon="fe fe-key"
                title="No access requests"
                description="Employee hardware and access requests will appear here when submitted."
              />
            ) : (
              <AccessRequestRegister
                requests={rows}
                acting={acting}
                onStatusUpdate={this.handleStatusUpdate}
              />
            )}
          </div>
        </section>
      </AdminLuxPage>
    );
  }
}

export default AccessRequestsPage;
