import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import LuxSummaryEyebrow from "views/common/fragments/LuxSummaryEyebrow";
import LuxCalendarNav from "views/common/fragments/LuxCalendarNav";
import CountUp from "react-countup";
import Skeleton, { SkeletonTheme } from "react-loading-skeleton";

import {
  readSummaryExpanded,
  writeSummaryExpanded,
  getSummaryToggleLabel,
} from "_helpers/summaryExpandedStorage";

const SUMMARY_STORAGE_KEY = "famstack-attendance-summary-expanded";

class AttendancePageSummary extends PureComponent {
  constructor(props) {
    super(props);
    this.state = {
      expanded: readSummaryExpanded(SUMMARY_STORAGE_KEY),
    };
  }

  toggleExpanded = () => {
    this.setState(
      (prev) => ({ expanded: !prev.expanded }),
      () => {
        writeSummaryExpanded(SUMMARY_STORAGE_KEY, this.state.expanded);
      }
    );
  };

  renderMixBar = (segments) => {
    if (!segments || !segments.length) {
      return <div className="lux-att-summary__bar lux-att-summary__bar--empty">No data yet</div>;
    }

    return (
      <div className="lux-att-summary__bar" role="img" aria-label="Distribution breakdown">
        {segments.map((segment) => (
          <span
            key={segment.label}
            className={classNames("lux-att-summary__bar-segment", `is-${segment.tone}`)}
            style={{ width: `${Math.max(segment.pct, segment.count > 0 ? 4 : 0)}%` }}
            title={`${segment.label}: ${segment.count} (${segment.pct}%)`}
          />
        ))}
      </div>
    );
  };

  renderMixLegend = (segments) => (
    <ul className="lux-att-summary__legend">
      {segments.map((segment) => (
        <li key={segment.label}>
          <span className={classNames("lux-att-summary__legend-dot", `is-${segment.tone}`)} />
          <span className="lux-att-summary__legend-label">{segment.label}</span>
          <strong>{segment.count}</strong>
          <span className="lux-att-summary__legend-pct">{segment.pct}%</span>
        </li>
      ))}
    </ul>
  );

  buildDailyChartTitle = (day) => {
    if (day.isFuture) {
      return `${day.fullLabel} · future (not available yet)`;
    }
    if (day.isWeekend) {
      return `${day.fullLabel} (optional): ${day.present}/${day.possible} present (${day.rate}%)`;
    }
    return `${day.fullLabel}: ${day.present}/${day.possible} present (${day.rate}%)`;
  };

  renderDailyChart = (dailyTrend) => {
    if (!dailyTrend || !dailyTrend.length) {
      return <p className="lux-att-summary__empty-note">No days in this month.</p>;
    }

    return (
      <div className="lux-att-summary__daily-chart" role="img" aria-label="Daily team attendance rate">
        <div className="lux-att-summary__daily-bars">
          {dailyTrend.map((day) => (
            <div
              key={day.key}
              className={classNames("lux-att-summary__daily-col", {
                "is-today": day.isToday,
                "is-saturday": day.isSaturday,
                "is-sunday": day.isSunday,
                "is-future": day.isFuture,
              })}
              title={this.buildDailyChartTitle(day)}
              aria-disabled={day.isFuture || undefined}
            >
              <div className="lux-att-summary__daily-bar-wrap">
                {!day.isFuture && (
                  <div
                    className="lux-att-summary__daily-bar"
                    style={{ height: `${Math.max(day.rate, day.present > 0 ? 6 : 0)}%` }}
                  />
                )}
              </div>
              <span className="lux-att-summary__daily-label">{day.label}</span>
            </div>
          ))}
        </div>
      </div>
    );
  };

  renderWeeklyChart = (weeklyTrend) => {
    if (!weeklyTrend || !weeklyTrend.length) return null;

    return (
      <div className="lux-att-summary__weekly-list">
        {weeklyTrend.map((week) => (
          <div
            key={week.label}
            className={classNames("lux-att-summary__weekly-row", {
              "is-future": week.isFuture,
              "is-partial": week.isPartial,
            })}
            title={
              week.isFuture
                ? `${week.range} · future week`
                : week.isPartial
                  ? `${week.range} · includes future days`
                  : week.range
            }
          >
            <div className="lux-att-summary__weekly-copy">
              <strong>{week.label}</strong>
              <span>{week.range}</span>
            </div>
            <div className="lux-att-summary__weekly-track">
              <div
                className="lux-att-summary__weekly-fill"
                style={{ width: week.isFuture ? 0 : `${week.rate}%` }}
              />
            </div>
            <span className="lux-att-summary__weekly-rate">{week.rate}%</span>
          </div>
        ))}
      </div>
    );
  };

  renderLeaderboard = (title, rows, tone) => {
    if (!rows || !rows.length) {
      return (
        <p className="lux-att-summary__empty-note">
          {tone === "green" ? "No top performers yet this month." : "Everyone is above 70% — great work!"}
        </p>
      );
    }

    return (
      <ol className="lux-att-summary__leaderboard">
        {rows.map((row, index) => (
          <li
            key={row.id}
            className={classNames("lux-att-summary__leader", `is-${tone}`, {
              "is-you": row.isCurrentUser,
            })}
          >
            <span className="lux-att-summary__leader-rank">{index + 1}</span>
            <div className="lux-att-summary__leader-copy">
              <strong>
                {row.name}
                {row.isCurrentUser && <em>You</em>}
              </strong>
              {row.designation && <span>{row.designation}</span>}
            </div>
            <div className="lux-att-summary__leader-stats">
              <strong>{row.rate}%</strong>
              <span>{row.present}/{row.elapsed} days</span>
            </div>
          </li>
        ))}
      </ol>
    );
  };

  renderSkeleton = () => (
    <SkeletonTheme baseColor="#f1f5f9" highlightColor="#e2e8f0">
      <div className="lux-att-summary is-loading">
        <Skeleton height={120} borderRadius={16} />
        <div className="lux-att-summary__insights lux-att-summary__insights--skeleton">
          {[1, 2, 3].map((key) => (
            <Skeleton key={key} height={160} borderRadius={14} />
          ))}
        </div>
      </div>
    </SkeletonTheme>
  );

  render() {
    const { stat, dashboard, isLoading, calendarControls, calendarDisabled } = this.props;
    const { expanded } = this.state;

    if (isLoading && !stat) return this.renderSkeleton();
    if (!stat) return null;

    const insightLine = dashboard && dashboard.bestDay && dashboard.lowestDay
      ? `Best day ${dashboard.bestDay.fullLabel} (${dashboard.bestDay.rate}%) · Lowest ${dashboard.lowestDay.fullLabel} (${dashboard.lowestDay.rate}%) · Avg ${dashboard.avgDailyRate}% daily`
      : null;

    return (
      <section
        className={classNames("lux-att-summary", { "is-collapsed": !expanded })}
        aria-label="Attendance Overview"
      >
        <div className="lux-att-summary__header-bar">
          <div className="lux-att-summary__header-main">
            <LuxSummaryEyebrow variant="attendance" className="lux-att-summary__eyebrow">
              Team attendance intelligence
            </LuxSummaryEyebrow>
            {!expanded ? (
              <h2 className="lux-att-summary__title lux-att-summary__title--compact">
                <CountUp end={stat.teamRate} duration={0.7} />% team rate
              </h2>
            ) : (
              <h2 className="lux-att-summary__title lux-att-summary__title--bar">Attendance Overview</h2>
            )}
            {calendarControls && (
              <div className="lux-att-summary__period-row">
                <LuxCalendarNav
                  onBack={calendarControls.goToBack}
                  onToday={calendarControls.goToCurrent}
                  onNext={calendarControls.goToNext}
                  disabled={calendarDisabled}
                />
                <span className="lux-att-summary__month-pill" aria-live="polite">
                  <i className="fe fe-calendar" aria-hidden="true" />
                  {stat.monthLabel}
                </span>
              </div>
            )}
          </div>
          <button
            type="button"
            className="lux-att-summary__toggle"
            onClick={this.toggleExpanded}
            aria-expanded={expanded}
            aria-controls="lux-att-summary-body"
          >
            <span>{getSummaryToggleLabel(expanded)}</span>
            <i className={classNames("fe", expanded ? "fe-chevron-up" : "fe-chevron-down")} aria-hidden="true" />
          </button>
        </div>

        {!expanded && (
          <div className="lux-att-summary__collapsed-strip">
            <p className="lux-att-summary__collapsed-line">
              {stat.employeeCount} people · {stat.totalMarks} marks · {stat.elapsedDays}/{stat.daysInMonth} days elapsed
              {dashboard && dashboard.todaySnapshot
                ? ` · Today ${dashboard.todaySnapshot.present}/${dashboard.todaySnapshot.total} present`
                : ""}
            </p>
          </div>
        )}

        <div id="lux-att-summary-body" className="lux-att-summary__body" aria-hidden={!expanded}>
          <header className="lux-att-summary__hero">
            <div className="lux-att-summary__hero-copy">
              <h3 className="lux-att-summary__month">{stat.monthLabel}</h3>
              <p className="lux-att-summary__subtitle">
                {stat.employeeCount} people tracked across {stat.elapsedDays} elapsed days
                {insightLine ? ` · ${insightLine}` : ""}
              </p>
            </div>

            <div className="lux-att-summary__hero-rate" title="Team mark rate for elapsed days">
              <div
                className="lux-att-summary__rate-ring"
                style={{ "--lux-active-pct": `${stat.teamRate}%` }}
                aria-hidden="true"
              >
                <span>{stat.teamRate}%</span>
              </div>
              <div className="lux-att-summary__rate-copy">
                <strong>Team mark rate</strong>
                <span>
                  {stat.totalMarks} present · {stat.totalAbsent} absent
                </span>
              </div>
            </div>

            {dashboard && dashboard.todaySnapshot && (
              <div className="lux-att-summary__today-card">
                <span className="lux-att-summary__today-label">Today</span>
                <strong>
                  {dashboard.todaySnapshot.present}/{dashboard.todaySnapshot.total}
                </strong>
                <span>{dashboard.todaySnapshot.rate}% marked</span>
              </div>
            )}
          </header>

          <div className="lux-att-summary__metrics">
            <article className="lux-att-summary__metric">
              <i className="fe fe-users" aria-hidden="true" />
              <div>
                <strong><CountUp end={stat.employeeCount} duration={0.7} /></strong>
                <span>People tracked</span>
              </div>
            </article>
            <article className="lux-att-summary__metric">
              <i className="fe fe-check-circle" aria-hidden="true" />
              <div>
                <strong><CountUp end={stat.totalMarks} duration={0.7} /></strong>
                <span>Total marks</span>
              </div>
            </article>
            <article className="lux-att-summary__metric">
              <i className="fe fe-x-circle" aria-hidden="true" />
              <div>
                <strong><CountUp end={stat.totalAbsent} duration={0.7} /></strong>
                <span>Total absent</span>
              </div>
            </article>
            <article className="lux-att-summary__metric">
              <i className="fe fe-calendar" aria-hidden="true" />
              <div>
                <strong>{stat.elapsedDays}/{stat.daysInMonth}</strong>
                <span>Days elapsed</span>
              </div>
            </article>
            <article className="lux-att-summary__metric">
              <i className="fe fe-bar-chart-2" aria-hidden="true" />
              <div>
                <strong>{dashboard ? dashboard.avgDailyRate : 0}%</strong>
                <span>Avg daily rate</span>
              </div>
            </article>
          </div>

          {dashboard && (
            <div className="lux-att-summary__insights">
              <article className="lux-att-summary__insight lux-att-summary__insight--wide">
                <header>
                  <i className="fe fe-activity" aria-hidden="true" />
                  <div>
                    <strong>Daily attendance trend</strong>
                    <span>Full month shown · grey = future days · amber/violet = optional Sat/Sun</span>
                  </div>
                </header>
                {this.renderDailyChart(dashboard.dailyTrend)}
              </article>

              <article className="lux-att-summary__insight">
                <header>
                  <i className="fe fe-pie-chart" aria-hidden="true" />
                  <div>
                    <strong>Month coverage</strong>
                    <span>Present vs absent marks</span>
                  </div>
                </header>
                {this.renderMixBar(dashboard.coverageMix)}
                {this.renderMixLegend(dashboard.coverageMix)}
              </article>

              <article className="lux-att-summary__insight">
                <header>
                  <i className="fe fe-layers" aria-hidden="true" />
                  <div>
                    <strong>Performance bands</strong>
                    <span>How people are tracking this month</span>
                  </div>
                </header>
                {this.renderMixBar(dashboard.distributionMix)}
                {this.renderMixLegend(dashboard.distributionMix)}
              </article>

              <article className="lux-att-summary__insight">
                <header>
                  <i className="fe fe-trending-up" aria-hidden="true" />
                  <div>
                    <strong>Weekly momentum</strong>
                    <span>Mark rate by week</span>
                  </div>
                </header>
                {this.renderWeeklyChart(dashboard.weeklyTrend)}
              </article>

              <article className="lux-att-summary__insight">
                <header>
                  <i className="fe fe-award" aria-hidden="true" />
                  <div>
                    <strong>Top performers</strong>
                    <span>70%+ attendance this month</span>
                  </div>
                </header>
                {this.renderLeaderboard("Top performers", dashboard.topPerformers, "green")}
              </article>

              <article className="lux-att-summary__insight">
                <header>
                  <i className="fe fe-alert-circle" aria-hidden="true" />
                  <div>
                    <strong>Needs attention</strong>
                    <span>Below 70% this month</span>
                  </div>
                </header>
                {this.renderLeaderboard("Needs attention", dashboard.needsAttention, "amber")}
              </article>
            </div>
          )}
        </div>
      </section>
    );
  }
}

export default AttendancePageSummary;
