/**
 * Google Analytics (GA4) - Central configuration and tracking utilities.
 * All tracking is no-op when REACT_APP_GA_MEASUREMENT_ID is not set.
 * User and team context from user.utils.js is attached to all events for per-user/team analysis.
 *
 * Setup: Set REACT_APP_GA_MEASUREMENT_ID in .env (e.g. G-XXXXXXXXXX).
 *
 * Automatic tracking (see setupGlobalTracking in App.jsx):
 * - Page views on every route change
 * - Clicks on buttons, links, nav items, and interactive controls
 * - Form submissions and select/checkbox/radio changes
 * - Redux mutation actions (analytics.middleware.js)
 * - Successful API calls (axios.utils.js)
 *
 * Manual overrides on any element:
 *   data-ga-action="action_name"    (required for custom action name)
 *   data-ga-category="auth"         (optional)
 *   data-ga-label="Sign in"         (optional)
 *   data-ga-value="1"               (optional)
 *   data-ga-skip                    (exclude from auto-tracking)
 */

import { userUtils } from './user.utils';

const GA_MEASUREMENT_ID = process.env.REACT_APP_GA_MEASUREMENT_ID;
const CONTENT_GROUP = 'app';
const isEnabled = () => typeof window !== 'undefined' && GA_MEASUREMENT_ID;

const INTERACTIVE_CLICK_SELECTOR = [
  'button',
  'a[href]',
  '[role="button"]',
  'input[type="submit"]',
  'input[type="button"]',
  'input[type="checkbox"]',
  'input[type="radio"]',
  '.btn',
  '.nav-link',
  '[data-toggle]',
  '[data-ga-action]',
].join(',');

function sanitizeName(value) {
  return String(value || 'unknown')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '')
    .slice(0, 100) || 'unknown';
}

function getElementDescriptor(el) {
  if (!el) return 'unknown';
  const explicit = el.getAttribute('data-ga-label') || el.getAttribute('aria-label') || el.getAttribute('title');
  if (explicit) return explicit.trim().slice(0, 120);
  if (el.id) return el.id;
  if (el.name) return el.name;
  if (el.tagName === 'A') {
    const href = el.getAttribute('href') || '';
    return href.startsWith('/') ? href : href.slice(0, 120);
  }
  const text = (el.textContent || '').replace(/\s+/g, ' ').trim();
  if (text) return text.slice(0, 120);
  return el.tagName.toLowerCase();
}

function shouldSkipElement(el) {
  if (!el || el.closest('[data-ga-skip]')) return true;
  if (el.closest('input[type="password"], textarea[data-ga-skip-input]')) return true;
  const tag = el.tagName;
  if (tag === 'INPUT') {
    const type = (el.getAttribute('type') || 'text').toLowerCase();
    if (type === 'password' || type === 'hidden' || type === 'file') return true;
  }
  return false;
}

function findInteractiveTarget(target) {
  const explicit = target.closest('[data-ga-action]');
  if (explicit) return explicit;
  return target.closest(INTERACTIVE_CLICK_SELECTOR);
}

/**
 * Get current user/team context from user.utils for analytics. Safe to call when not logged in.
 * Returns {} if unavailable; use for user_id, team_id, and GA4 user properties.
 */
function getUserContext() {
  if (typeof window === 'undefined') return {};
  try {
    const userId = userUtils.getCurrentUserId && userUtils.getCurrentUserId();
    const teamId = userUtils.getCurrentTeamId && userUtils.getCurrentTeamId();
    const teamName = userUtils.getCurrentTeamName && userUtils.getCurrentTeamName();
    const loginType = userUtils.getLoginType && userUtils.getLoginType();
    const userName = userUtils.getCurrentUserName && userUtils.getCurrentUserName();
    if (userId == null && teamId == null) return {};
    return {
      user_id: userId != null ? String(userId) : undefined,
      team_id: teamId != null ? String(teamId) : undefined,
      team_name: teamName || undefined,
      login_type: loginType || undefined,
      user_name: userName || undefined,
    };
  } catch (e) {
    return {};
  }
}

/**
 * Set GA4 user ID and user properties from current user/team. Call before events when context exists.
 */
function setUserContext() {
  if (!isEnabled()) return;
  const ctx = getUserContext();
  if (ctx.user_id) {
    window.gtag('config', GA_MEASUREMENT_ID, { user_id: ctx.user_id });
  }
  const userProps = {};
  if (ctx.team_id) userProps.team_id = ctx.team_id;
  if (ctx.team_name) userProps.team_name = ctx.team_name;
  if (ctx.login_type) userProps.login_type = ctx.login_type;
  if (ctx.user_name) userProps.user_name = ctx.user_name;
  if (Object.keys(userProps).length) {
    window.gtag('set', 'user_properties', userProps);
  }
}

/**
 * Event params that include user/team for segmentation. Omit undefined values.
 */
function getEventUserParams() {
  const ctx = getUserContext();
  const params = {};
  if (ctx.user_id) params.user_id = ctx.user_id;
  if (ctx.team_id) params.team_id = ctx.team_id;
  if (ctx.team_name) params.team_name = ctx.team_name;
  if (ctx.login_type) params.login_type = ctx.login_type;
  return params;
}

/**
 * Initialize Google Analytics. Loads gtag script and configures the property.
 * Call once when the app mounts (e.g. in App.jsx).
 */
export function init() {
  if (!GA_MEASUREMENT_ID) return;

  window.dataLayer = window.dataLayer || [];
  function gtag() {
    window.dataLayer.push(arguments);
  }
  window.gtag = gtag;
  gtag('js', new Date());

  const script = document.createElement('script');
  script.async = true;
  script.src = `https://www.googletagmanager.com/gtag/js?id=${GA_MEASUREMENT_ID}`;
  document.head.appendChild(script);

  gtag('config', GA_MEASUREMENT_ID, {
    send_page_view: false,
    content_group: CONTENT_GROUP,
  });
}

/**
 * Sanitize API URLs for analytics (strip IDs and query params).
 */
export function sanitizeApiUrl(url) {
  if (!url) return 'unknown';
  return String(url)
    .split('?')[0]
    .replace(/\/\d+/g, '/:id')
    .replace(/\/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi, '/:id')
    .slice(0, 200);
}

/**
 * Track a page view (call on every route change).
 * Includes user_id, team_id, team_name, login_type for per-user/team analysis.
 * @param {string} path - Full path (e.g. /project/dashboard)
 * @param {string} [title] - Optional page title
 */
export function trackPageView(path, title) {
  if (!isEnabled()) return;
  setUserContext();
  window.gtag('event', 'page_view', {
    page_path: path || window.location.pathname,
    page_title: title || document.title,
    content_group: CONTENT_GROUP,
    ...getEventUserParams(),
  });
}

/**
 * Track a custom event (button clicks, feature usage, etc.).
 * @param {string} action - Action name (e.g. 'click_login', 'submit_form')
 * @param {string} [category] - Category (e.g. 'engagement', 'auth')
 * @param {string} [label] - Optional label for the event
 * @param {number} [value] - Optional numeric value
 * @param {object} [extraParams] - Additional GA4 event parameters
 */
export function trackEvent(action, category = 'engagement', label = '', value, extraParams = {}) {
  if (!isEnabled()) return;
  setUserContext();
  const params = {
    event_category: category,
    content_group: CONTENT_GROUP,
    ...getEventUserParams(),
    ...extraParams,
  };
  if (label) params.event_label = label;
  if (value != null) params.value = value;
  window.gtag('event', sanitizeName(action), params);
}

function trackDomEvent(action, category, el, extraParams = {}) {
  if (!el || shouldSkipElement(el)) return;
  const explicitAction = el.getAttribute('data-ga-action');
  const explicitCategory = el.getAttribute('data-ga-category');
  const explicitLabel = el.getAttribute('data-ga-label');
  const explicitValue = el.getAttribute('data-ga-value');
  trackEvent(
    explicitAction || action,
    explicitCategory || category,
    explicitLabel || getElementDescriptor(el),
    explicitValue ? Number(explicitValue) : undefined,
    {
      element_tag: el.tagName.toLowerCase(),
      element_id: el.id || undefined,
      page_path: window.location.pathname,
      ...extraParams,
    }
  );
}

/**
 * Attach global listeners for automatic user-interaction tracking.
 * Returns a cleanup function.
 */
export function setupGlobalTracking() {
  if (!isEnabled()) return () => {};

  const onClick = (e) => {
    const el = findInteractiveTarget(e.target);
    if (!el) return;
    const category = el.tagName === 'A' ? 'navigation' : 'engagement';
    trackDomEvent('user_click', category, el);
  };

  const onSubmit = (e) => {
    const form = e.target;
    if (!form || form.tagName !== 'FORM' || shouldSkipElement(form)) return;
    trackEvent('form_submit', 'form', form.getAttribute('name') || form.id || getElementDescriptor(form), undefined, {
      page_path: window.location.pathname,
      form_action: form.getAttribute('action') || undefined,
    });
  };

  const onChange = (e) => {
    const el = e.target;
    if (!el || shouldSkipElement(el)) return;
    const tag = el.tagName;
    const type = (el.getAttribute('type') || '').toLowerCase();
    if (tag === 'SELECT' || type === 'checkbox' || type === 'radio') {
      trackDomEvent('user_change', 'form', el, {
        field_name: el.name || undefined,
        field_value: type === 'checkbox' || type === 'radio' ? String(el.checked) : undefined,
      });
    }
  };

  document.addEventListener('click', onClick, true);
  document.addEventListener('submit', onSubmit, true);
  document.addEventListener('change', onChange, true);

  return () => {
    document.removeEventListener('click', onClick, true);
    document.removeEventListener('submit', onSubmit, true);
    document.removeEventListener('change', onChange, true);
  };
}

export default {
  init,
  trackPageView,
  trackEvent,
  setupGlobalTracking,
  sanitizeApiUrl,
  setUserContext,
  getUserContext,
  isEnabled: () => !!GA_MEASUREMENT_ID,
};
