import { commonUtils } from "_helpers";
import { accessUtils } from "_helpers";
import dateUtils from "_helpers/date.utils";
import { projectActions } from "_actions";
import { workItemService } from "_services/workitem.service";
import { dashbaordService } from "_services/dashboard.service";
import DashboardApexChart from "views/hrms/components/dashboard/DashboardApexChart";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import LuxKpiStrip from "views/common/fragments/LuxKpiStrip";
import { DENSE_PAGE_META } from "config/dense-page-meta.config";

