    function () {
      var now = moment().startOf("day");
      var windows = [7, 14, 30];
      return windows.map(function (days) {
        var until = now.clone().add(days, "days").endOf("day");
        var due = 0;
        var risk = 0;
        var overdue = 0;
        managerProjects.forEach(function (p) {
          var s = statusKey(p.status);
          if (s === "COMPLETED" || s === "CLOSED") return;
          var end = p.estCompletionTime
            ? dateUtils.convertDateStringToMoment(p.estCompletionTime)
            : null;
          if (!end || !end.isValid()) return;
          if (end.isBefore(now, "day")) {
            overdue += 1;
          }
          if (end.isBetween(now, until, "day", "[]")) {
            due += 1;
            var r = getProjectRisk(p, now);
            if (r === "OVERDUE" || r === "ATRISK") risk += 1;
          }
        });
        return { days: days, due: due, risk: risk, overdue: overdue };
      });
    },
