import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import EmployeeImage from "views/common/fragments/EmployeeImage";
import LuxActivityPanelEmptyState from "views/common/fragments/LuxActivityPanelEmptyState";
import Skeleton, { SkeletonTheme } from "react-loading-skeleton";
import { LUX_SKELETON_THEME } from "views/common/fragments/luxSkeleton.constants";
import {
  extractFieldChanges,
  formatAuditRelativeTime,
  formatAuditTimestamp,
  getActionMeta,
  getActorMeta,
  getActorName,
  getAuditEventIcon,
  getAuditEventTone,
  canDeepLinkAuditEvent,
  getAuditEventDeepLinkLabel,
  getDelegateActingLabel,
  getEntityMeta,
  groupEventsByDay,
} from "_helpers/audit.utils";

class AuditTimeline extends PureComponent {
  renderFieldChanges = (metadata) => {
    const changes = extractFieldChanges(metadata);
    if (!changes.length) return null;

    return (
      <dl className="lux-audit__changes">
        {changes.map((change, index) => (
          <div key={`${change.field || index}-${index}`} className="lux-audit__change-row">
            <dt>{change.label || change.field || "Field"}</dt>
            <dd>
              <span className="lux-audit__change-from">{change.from != null ? change.from : "—"}</span>
              <i className="fe fe-arrow-right" aria-hidden="true" />
              <span className="lux-audit__change-to">{change.to != null ? change.to : "—"}</span>
            </dd>
          </div>
        ))}
      </dl>
    );
  };

  renderMetadataNote = (metadata) => {
    if (!metadata || typeof metadata !== "object") return null;
    const note = metadata.comment || metadata.rejectionComment || metadata.approvalComment || metadata.note;
    if (!note) return null;
    return (
      <blockquote className="lux-audit__note">
        <i className="fe fe-message-circle" aria-hidden="true" />
        {note}
      </blockquote>
    );
  };

  renderEntry = (event) => {
    const { onEventDeepLink } = this.props;
    const tone = getAuditEventTone(event);
    const icon = getAuditEventIcon(event);
    const actionMeta = getActionMeta(event.actionType);
    const entityMeta = getEntityMeta(event.entity && event.entity.type);
    const delegateLabel = getDelegateActingLabel(event.metadata);
    const actor = event.actor;
    const deepLinkLabel = onEventDeepLink ? getAuditEventDeepLinkLabel(event) : null;
    const showDeepLink = onEventDeepLink && canDeepLinkAuditEvent(event) && deepLinkLabel;

    return (
      <article key={event.id || `${event.createdDate}-${event.actionType}`} className="lux-audit__entry">
        <div className="lux-audit__entry-rail" aria-hidden="true">
          <span className={classNames("lux-audit__entry-icon", `is-${tone}`)}>
            <i className={`fe ${icon}`} />
          </span>
          <span className="lux-audit__entry-line" />
        </div>

        <div className="lux-audit__entry-card">
          <header className="lux-audit__entry-head">
            <div className="lux-audit__entry-user">
              {actor && (
                <span className="lux-audit__avatar-ring">
                  <EmployeeImage employee={actor} classes="lux-audit__avatar" />
                </span>
              )}
              <div className="lux-audit__entry-names">
                <strong>{getActorName(event)}</strong>
                <span>
                  {actionMeta.label}
                  {getActorMeta(event) ? ` · ${getActorMeta(event)}` : ""}
                </span>
              </div>
            </div>
            <div className="lux-audit__entry-time">
              <strong title={formatAuditTimestamp(event.createdDate)}>
                {formatAuditRelativeTime(event.createdDate)}
              </strong>
              <span>{formatAuditTimestamp(event.createdDate)}</span>
            </div>
          </header>

          <h3 className="lux-audit__entry-title">{event.headline}</h3>

          <div className="lux-audit__entry-meta">
            {event.entity && event.entity.type && (
              <span className={classNames("lux-audit__entity-chip", `is-${entityMeta.tone}`)}>
                <i className={`fe ${entityMeta.icon}`} aria-hidden="true" />
                {entityMeta.label}
                {event.entity.ref ? ` · ${event.entity.ref}` : ""}
              </span>
            )}
            <span className={classNames("lux-audit__action-chip", `is-${tone}`)}>
              {actionMeta.label}
            </span>
            {delegateLabel && (
              <span className="lux-audit__delegate-chip">
                <i className="fe fe-user-check" aria-hidden="true" />
                {delegateLabel}
              </span>
            )}
          </div>

          {this.renderMetadataNote(event.metadata)}
          {this.renderFieldChanges(event.metadata)}

          {showDeepLink && (
            <footer className="lux-audit__entry-actions">
              <button
                type="button"
                className="lux-audit__deep-link"
                onClick={() => onEventDeepLink(event)}
              >
                <i className="fe fe-external-link" aria-hidden="true" />
                {deepLinkLabel}
              </button>
            </footer>
          )}
        </div>
      </article>
    );
  };

  renderSkeleton = () => (
    <SkeletonTheme baseColor={LUX_SKELETON_THEME.baseColor} highlightColor={LUX_SKELETON_THEME.highlightColor}>
      <div className="lux-audit__loading" aria-busy="true">
        {[1, 2, 3].map((key) => (
          <div key={key} className="lux-audit__loading-row">
            <Skeleton circle width={36} height={36} />
            <div style={{ flex: 1 }}>
              <Skeleton width="40%" height={10} borderRadius={4} />
              <Skeleton height={48} borderRadius={12} style={{ marginTop: 8 }} />
            </div>
          </div>
        ))}
      </div>
    </SkeletonTheme>
  );

  renderEmpty = () => {
    const { emptyState } = this.props;
    const copy = emptyState || {
      eyebrow: "Audit trail",
      title: "No audit events yet",
      description:
        "Changes, approvals, and security events will appear here once activity logging is active for this record.",
      hints: [
        "Events are recorded automatically when you save or approve",
        "Delegate actions show who acted on whose behalf",
        "Older events may appear after a compliance backfill",
      ],
    };

    return (
      <LuxActivityPanelEmptyState
        className="lux-audit__empty"
        variant="collab"
        eyebrow={copy.eyebrow}
        title={copy.title}
        description={copy.description}
        hints={copy.hints}
      />
    );
  };

  renderPagination = () => {
    const { pagination, onPageChange, isLoading } = this.props;
    if (!pagination || !onPageChange) return null;

    const page = pagination.page || 1;
    const hasMore = pagination.hasMore === true;
    if (page <= 1 && !hasMore) return null;

    return (
      <footer className="lux-audit__pagination lux-search-pagination" aria-label="Audit timeline pagination">
        <div className="lux-search-pagination__summary">
          Page <strong>{page}</strong>
          {pagination.pageSize ? ` · ${pagination.pageSize} per page` : ""}
        </div>
        <div className="lux-search-pagination__controls">
          <button
            type="button"
            className="lux-search-pagination__btn"
            disabled={page <= 1 || isLoading}
            onClick={() => onPageChange(page - 1)}
            aria-label="Previous page"
          >
            <i className="fe fe-chevron-left" aria-hidden="true" />
          </button>
          <button
            type="button"
            className="lux-search-pagination__btn"
            disabled={!hasMore || isLoading}
            onClick={() => onPageChange(page + 1)}
            aria-label="Next page"
          >
            <i className="fe fe-chevron-right" aria-hidden="true" />
          </button>
        </div>
      </footer>
    );
  };

  render() {
    const { events, isLoading, error, className } = this.props;
    const items = events || [];
    const showLoading = isLoading && !items.length;

    if (showLoading) {
      return <div className={classNames("lux-audit", className)}>{this.renderSkeleton()}</div>;
    }

    if (error && !items.length) {
      return (
        <div className={classNames("lux-audit lux-audit--error", className)} role="alert">
          <LuxActivityPanelEmptyState
            variant="collab"
            eyebrow="Audit unavailable"
            title="Could not load audit trail"
            description={
              typeof error === "string"
                ? error
                : "The audit service is not available yet or you may not have permission to view these events."
            }
            hints={["Try refreshing the page", "Contact your admin if this persists"]}
          />
        </div>
      );
    }

    if (!items.length) {
      return <div className={classNames("lux-audit", className)}>{this.renderEmpty()}</div>;
    }

    const groups = groupEventsByDay(items);

    return (
      <div className={classNames("lux-audit", className)}>
        <div className="lux-audit__timeline">
          {groups.map(([dayLabel, dayEvents]) => (
            <section key={dayLabel} className="lux-audit__day-group">
              <div className="lux-audit__day-label">
                <i className="fe fe-calendar" aria-hidden="true" />
                {dayLabel}
              </div>
              <div className="lux-audit__entries">{dayEvents.map(this.renderEntry)}</div>
            </section>
          ))}
        </div>

        {this.renderPagination()}
      </div>
    );
  }
}

export default AuditTimeline;
