import React from "react";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import {
  getEmployeeInitials,
  getProficiencyTone,
  getSkillCategoryMeta,
} from "config/resource-planning.utils";

function ProficiencyMeter({ score, level }) {
  const tone = getProficiencyTone(level);
  const pct = Math.max(0, Math.min(100, (score || 0) * 25));
  return (
    <div className="lux-skills-proficiency">
      <div className={`lux-skills-proficiency__bar is-${tone}`}>
        <span style={{ width: `${pct}%` }} />
      </div>
      <span className={`lux-doc-badge is-${tone === "green" ? "success" : tone === "amber" ? "warning" : tone === "blue" ? "info" : "slate"}`}>
        {level}
      </span>
    </div>
  );
}

export default function SkillsMatrixRegister({ rows, loading }) {
  if (loading) {
    return null;
  }

  return (
    <div className="lux-skills-register-wrap">
      <table className="lux-skills-register">
        <thead>
          <tr>
            <th>Person</th>
            <th>Skill</th>
            <th>Category</th>
            <th>Proficiency</th>
            <th>Experience</th>
            <th>Last used</th>
            <th>Certified</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => {
            const categoryMeta = getSkillCategoryMeta(row.skillCategory);
            const isGap = (row.proficiencyScore || 0) <= 1;
            return (
              <tr
                key={row.id}
                className={classNames("lux-skills-register__row", {
                  "is-attention": isGap,
                  "is-certified": row.certified,
                })}
              >
                <td>
                  <div className="lux-skills-register__person">
                    <span className="lux-skills-register__avatar" aria-hidden="true">
                      {getEmployeeInitials(row.employeeName)}
                    </span>
                    <span className="lux-skills-register__person-copy">
                      <strong>{row.employeeName || "—"}</strong>
                      {row.employeeId && (
                        <Link className="lux-skills-register__link" to={`/people/employees/${row.employeeId}/360`}>
                          Employee 360
                        </Link>
                      )}
                    </span>
                  </div>
                </td>
                <td>
                  <div className="lux-skills-register__skill">
                    <span className={classNames("lux-skills-register__skill-icon", categoryMeta.tone && `is-${categoryMeta.tone}`)} aria-hidden="true">
                      <i className={categoryMeta.icon} />
                    </span>
                    <span className="lux-skills-register__skill-copy">
                      <strong>{row.skillName}</strong>
                      {row.notes && <span className="lux-skills-register__meta">{row.notes}</span>}
                    </span>
                  </div>
                </td>
                <td>
                  <span className={classNames("lux-skills-register__chip", categoryMeta.tone && `is-${categoryMeta.tone}`)}>
                    <i className={categoryMeta.icon} aria-hidden="true" />
                    {row.skillCategory}
                  </span>
                </td>
                <td>
                  <ProficiencyMeter score={row.proficiencyScore} level={row.proficiencyLabel} />
                </td>
                <td>
                  <span className="lux-skills-register__metric">
                    {row.yearsExperience != null ? `${row.yearsExperience} yrs` : "—"}
                  </span>
                </td>
                <td>
                  <span className="lux-skills-register__date">{row.lastUsedDate || "—"}</span>
                </td>
                <td>
                  {row.certified ? (
                    <span className="lux-doc-badge is-success">
                      <i className="fe fe-award mr-1" aria-hidden="true" />
                      Certified
                    </span>
                  ) : (
                    <span className="lux-skills-register__muted">—</span>
                  )}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
