import React from "react";
import classNames from "classnames/bind";

function healthTone(score) {
  if (score == null) return "slate";
  if (score >= 80) return "green";
  if (score >= 60) return "amber";
  return "rose";
}

function steeringLabel(rollup) {
  if (!rollup) return "Awaiting roll-up";
  if (rollup.criticalProjects > 0) return "Intervention required";
  if (rollup.avgSlippageDays >= 5) return "Schedule watch";
  if (rollup.openRisks > 6) return "Risk escalation";
  return "Stable steering";
}

function steeringTone(rollup) {
  if (!rollup) return "slate";
  if (rollup.criticalProjects > 0) return "rose";
  if (rollup.avgSlippageDays >= 5 || rollup.openRisks > 6) return "amber";
  return "green";
}

export default function PortfolioExecutiveSnapshotStrip({ rollup, loading }) {
  if (loading) {
    return (
      <div className="lux-portfolio-exec-snapshot lux-portfolio-exec-snapshot--loading" aria-busy="true">
        <span className="lux-portfolio-exec-snapshot__skeleton" />
      </div>
    );
  }

  if (!rollup) {
    return null;
  }

  const tone = healthTone(rollup.healthScore);
  const steerTone = steeringTone(rollup);

  return (
    <section className="lux-portfolio-exec-snapshot" aria-label="Executive portfolio snapshot">
      <div className="lux-portfolio-exec-snapshot__main">
        <span className="lux-portfolio-exec-snapshot__kicker">
          <i className="fe fe-briefcase" aria-hidden="true" />
          {rollup.name || "Enterprise portfolio"}
        </span>
        <div className="lux-portfolio-exec-snapshot__headline">
          <strong className={classNames("lux-portfolio-exec-snapshot__health", `is-${tone}`)}>
            {rollup.healthScore}%
          </strong>
          <div>
            <span className="lux-portfolio-exec-snapshot__title">Composite portfolio health</span>
            <span className={classNames("lux-portfolio-exec-snapshot__steer", `is-${steerTone}`)}>
              {steeringLabel(rollup)}
            </span>
          </div>
        </div>
      </div>

      <div className="lux-portfolio-exec-snapshot__chips" role="list">
        <article className="lux-portfolio-exec-snapshot__chip is-indigo" role="listitem">
          <i className="fe fe-layers" aria-hidden="true" />
          <div>
            <strong>{rollup.programCount || 0}</strong>
            <span>Programs</span>
          </div>
        </article>
        <article className="lux-portfolio-exec-snapshot__chip is-blue" role="listitem">
          <i className="fe fe-folder" aria-hidden="true" />
          <div>
            <strong>{rollup.projectCount || 0}</strong>
            <span>Governed projects</span>
          </div>
        </article>
        <article className="lux-portfolio-exec-snapshot__chip is-rose" role="listitem">
          <i className="fe fe-alert-circle" aria-hidden="true" />
          <div>
            <strong>{rollup.criticalProjects || 0}</strong>
            <span>Critical health</span>
          </div>
        </article>
        <article className="lux-portfolio-exec-snapshot__chip is-amber" role="listitem">
          <i className="fe fe-clock" aria-hidden="true" />
          <div>
            <strong>{rollup.avgSlippageDays || 0}d</strong>
            <span>Avg slippage</span>
          </div>
        </article>
        <article className="lux-portfolio-exec-snapshot__chip is-violet" role="listitem">
          <i className="fe fe-alert-triangle" aria-hidden="true" />
          <div>
            <strong>{rollup.openRisks || 0}</strong>
            <span>Open risks</span>
          </div>
        </article>
        <article className="lux-portfolio-exec-snapshot__chip is-slate" role="listitem">
          <i className="fe fe-flag" aria-hidden="true" />
          <div>
            <strong>{rollup.openIssues || 0}</strong>
            <span>Open issues</span>
          </div>
        </article>
      </div>
    </section>
  );
}
