import React from 'react';
import { connect } from 'react-redux';
import { withRouter } from 'react-router-dom';
import { leavePhase2Service as api } from '_services/leavePhase2.service';
import { globalLeavePolicyService as glpApi } from '_services/globalLeavePolicy.service';
import {
  LeavePhase2AdminBase,
  LeavePhase2Panel,
  LeavePhase2Register,
  mapLeavePhase2State,
  renderLeavePhase2Nav,
  cell,
} from './leavePhase2.shared';
import { AdminActionButton } from 'views/admin/components/AdminLuxShared';
import '../leaveLuxForms.css';

const BASE = '/admin/leave/legal-calendars';

const NAV = [
  { path: BASE, label: 'Calendars', icon: 'fe fe-calendar', exact: true },
  { path: '/admin/leave/holiday-imports', label: 'Imports', icon: 'fe fe-upload' },
  { path: '/admin/leave/working-day-rules', label: 'Working days', icon: 'fe fe-sun' },
  { path: '/admin/leave/calendar-impact-preview', label: 'Impact', icon: 'fe fe-eye' },
];

const EMPTY_CAL_FORM = {
  holidayCalendarKey: 'IN',
  jurisdictionId: '',
  effectiveFrom: '',
};

const EMPTY_HOLIDAY_FORM = {
  holidayDate: '',
  name: '',
  entryType: 'PUBLIC',
  optional: false,
  halfDay: false,
  observedDate: '',
};

const EMPTY_WORKING_FORM = {
  name: '',
  pattern: 'MON_FRI',
  jurisdictionId: '',
  halfDayAllowed: true,
};

const WORKING_DAY_PRESETS = {
  MON_FRI: {
    label: 'Mon–Fri (5-day)',
    workdays: [1, 2, 3, 4, 5],
    weekendDays: [6, 7],
  },
  MON_SAT: {
    label: 'Mon–Sat (6-day)',
    workdays: [1, 2, 3, 4, 5, 6],
    weekendDays: [7],
  },
  SUN_THU: {
    label: 'Sun–Thu (Middle East)',
    workdays: [7, 1, 2, 3, 4],
    weekendDays: [5, 6],
  },
};

const ISO_DAY_LABELS = {
  1: 'Mon',
  2: 'Tue',
  3: 'Wed',
  4: 'Thu',
  5: 'Fri',
  6: 'Sat',
  7: 'Sun',
};

function formatWorkdays(workdays) {
  if (!Array.isArray(workdays) || !workdays.length) return '—';
  return workdays.map((d) => ISO_DAY_LABELS[d] || d).join(', ');
}

const EMPTY_EMP_JUR_FORM = {
  employeeId: '',
  jurisdictionId: '',
};

const EMPTY_EMP_WD_FORM = {
  employeeId: '',
  workingDayRuleId: '',
};

function sectionFromPath(pathname) {
  if (pathname.includes('holiday-imports')) return 'imports';
  if (pathname.includes('working-day-rules')) return 'working';
  if (pathname.includes('calendar-impact-preview')) return 'impact';
  return 'calendars';
}

class LegalCalendarsPage extends LeavePhase2AdminBase {
  state = {
    ...this.state,
    versions: [],
    imports: [],
    workingRules: [],
    changeTasks: [],
    impact: null,
    holidays: [],
    jurisdictions: [],
    selectedVersionId: null,
    calForm: { ...EMPTY_CAL_FORM },
    holidayForm: { ...EMPTY_HOLIDAY_FORM },
    workingForm: { ...EMPTY_WORKING_FORM },
    empJurForm: { ...EMPTY_EMP_JUR_FORM },
    empWdForm: { ...EMPTY_EMP_WD_FORM },
    employeeJurisdictions: [],
    employeeWorkingDays: [],
    previewEmployeeId: '',
    resolvedPattern: null,
    saving: false,
  };

  fetchSectionData = async (teamId) => {
    const section = sectionFromPath(this.props.location.pathname);
    if (section === 'calendars') {
      const [versionsRaw, jurisdictionsRaw] = await Promise.all([
        api.listCalendarVersions(teamId),
        glpApi.listJurisdictions(teamId).catch(() => []),
      ]);
      const list = Array.isArray(versionsRaw) ? versionsRaw : [];
      const jurisdictions = Array.isArray(jurisdictionsRaw) ? jurisdictionsRaw : [];
      const preferred =
        list.find((v) => String(v.status || '').toUpperCase() === 'DRAFT') || list[0] || null;
      const selectedVersionId =
        this.state.selectedVersionId && list.some((v) => v.id === this.state.selectedVersionId)
          ? this.state.selectedVersionId
          : preferred
            ? preferred.id
            : null;
      let holidays = [];
      if (selectedVersionId) {
        const rows = (await api.listHolidayEntries(selectedVersionId)) || [];
        holidays = Array.isArray(rows) ? rows : [];
      }
      this.setState({
        versions: list,
        jurisdictions,
        selectedVersionId,
        holidays,
      });
      return;
    }
    if (section === 'imports') {
      const imports = (await api.listHolidayImports(teamId)) || [];
      this.setState({ imports: Array.isArray(imports) ? imports : [] });
      return;
    }
    if (section === 'working') {
      const previewEmployeeId = this.state.previewEmployeeId;
      const [workingRulesRaw, patternRaw, jurisdictionsRaw, empJurRaw, empWdRaw] = await Promise.all([
        api.listWorkingDayRules(teamId),
        api
          .resolveWorkingDayPattern(teamId, previewEmployeeId ? Number(previewEmployeeId) : null)
          .catch(() => null),
        glpApi.listJurisdictions(teamId).catch(() => []),
        api.listEmployeeJurisdictions(teamId).catch(() => []),
        api.listEmployeeWorkingDays(teamId).catch(() => []),
      ]);
      this.setState({
        workingRules: Array.isArray(workingRulesRaw) ? workingRulesRaw : [],
        resolvedPattern: patternRaw || null,
        jurisdictions: Array.isArray(jurisdictionsRaw) ? jurisdictionsRaw : [],
        employeeJurisdictions: Array.isArray(empJurRaw) ? empJurRaw : [],
        employeeWorkingDays: Array.isArray(empWdRaw) ? empWdRaw : [],
      });
      return;
    }
    const versions = (await api.listCalendarVersions(teamId)) || [];
    const list = Array.isArray(versions) ? versions : [];
    let impact = null;
    if (list.length && list[0].id) {
      impact = await api.previewCalendarImpact(list[0].id, teamId).catch(() => null);
    }
    const changeTasks = (await api.listCalendarChangeTasks(teamId).catch(() => [])) || [];
    this.setState({
      versions: list,
      impact,
      changeTasks: Array.isArray(changeTasks) ? changeTasks : [],
    });
  };

  selectedVersion = () => {
    const { versions, selectedVersionId } = this.state;
    return (versions || []).find((v) => v.id === selectedVersionId) || null;
  };

  runAction = async (fn, successNotice) => {
    const teamId = this.teamId();
    if (!teamId) {
      this.setState({ error: 'Select a team first.' });
      return;
    }
    this.setState({ saving: true, error: null, notice: null });
    try {
      await fn(teamId);
      this.setState({
        saving: false,
        notice: successNotice,
        calForm: { ...EMPTY_CAL_FORM },
        holidayForm: { ...EMPTY_HOLIDAY_FORM },
      });
      await this.loadAll();
    } catch (e) {
      this.setState({
        saving: false,
        error: (e && e.message) || 'Action failed.',
      });
    }
  };

  createCalendar = (event) => {
    event.preventDefault();
    const { calForm } = this.state;
    this.runAction(
      (teamId) =>
        api.createCalendarVersion({
          userTeamId: teamId,
          actorId: this.actorId(),
          holidayCalendarKey: (calForm.holidayCalendarKey || 'IN').trim(),
          jurisdictionId: calForm.jurisdictionId ? Number(calForm.jurisdictionId) : null,
          effectiveFrom: calForm.effectiveFrom || null,
          status: 'DRAFT',
        }),
      'Draft calendar created. Add holidays, then publish to sync People → Holidays.'
    );
  };

  addHoliday = (event) => {
    event.preventDefault();
    const version = this.selectedVersion();
    const { holidayForm } = this.state;
    if (!version || !version.id) {
      this.setState({ error: 'Select a draft calendar first.' });
      return;
    }
    if (String(version.status || '').toUpperCase() === 'PUBLISHED') {
      this.setState({ error: 'Published calendars are immutable. Create a new draft version.' });
      return;
    }
    this.runAction(
      () =>
        api.addHolidayEntry({
          calendarVersionId: version.id,
          actorId: this.actorId(),
          userTeamId: this.teamId(),
          holidayDate: holidayForm.holidayDate,
          name: (holidayForm.name || '').trim(),
          entryType: holidayForm.entryType || 'PUBLIC',
          optional: !!holidayForm.optional,
          halfDay: !!holidayForm.halfDay,
          observedDate: holidayForm.observedDate || null,
        }),
      'Holiday entry added to the draft calendar.'
    );
  };

  publishSelected = () => {
    const version = this.selectedVersion();
    if (!version || !version.id) {
      this.setState({ error: 'Select a calendar version to publish.' });
      return;
    }
    if (String(version.status || '').toUpperCase() === 'PUBLISHED') {
      this.setState({ error: 'This calendar is already published.' });
      return;
    }
    this.runAction(
      () => api.publishCalendarVersion(version.id, { actorId: this.actorId() }),
      'Calendar published. Blocking holidays synced to People → Holidays for leave day counting.'
    );
  };

  selectVersion = async (versionId) => {
    const id = versionId ? Number(versionId) : null;
    this.setState({ selectedVersionId: id, holidays: [], loading: true });
    try {
      const holidays = id ? (await api.listHolidayEntries(id)) || [] : [];
      this.setState({
        holidays: Array.isArray(holidays) ? holidays : [],
        loading: false,
      });
    } catch (e) {
      this.setState({
        loading: false,
        error: (e && e.message) || 'Failed to load holiday entries.',
      });
    }
  };

  renderCalendars() {
    const {
      loading,
      versions,
      holidays,
      jurisdictions,
      selectedVersionId,
      calForm,
      holidayForm,
      saving,
    } = this.state;
    const selected = this.selectedVersion();
    const isDraft = selected && String(selected.status || '').toUpperCase() !== 'PUBLISHED';

    return (
      <>
        <LeavePhase2Panel
          title="Create draft calendar"
          subtitle="Key must match People → Holidays locations (e.g. IN, IN-KA)."
          testId="glp18-create-calendar"
        >
          <form className="lux-glp-form" onSubmit={this.createCalendar} data-testid="glp18-create-calendar-form">
            <label>
              Calendar key
              <input
                required
                value={calForm.holidayCalendarKey}
                onChange={(e) =>
                  this.setState({ calForm: { ...calForm, holidayCalendarKey: e.target.value } })
                }
                placeholder="IN-KA"
              />
            </label>
            <label>
              Jurisdiction
              <select
                value={calForm.jurisdictionId}
                onChange={(e) =>
                  this.setState({ calForm: { ...calForm, jurisdictionId: e.target.value } })
                }
              >
                <option value="">Optional…</option>
                {(jurisdictions || []).map((j) => (
                  <option key={j.id} value={j.id}>
                    {j.name || j.code || j.id}
                  </option>
                ))}
              </select>
            </label>
            <label>
              Effective from
              <input
                type="date"
                value={calForm.effectiveFrom}
                onChange={(e) =>
                  this.setState({ calForm: { ...calForm, effectiveFrom: e.target.value } })
                }
              />
            </label>
            <div className="lux-glp-form__actions">
              <AdminActionButton type="submit" icon="fe fe-plus" disabled={saving || loading}>
                Create draft
              </AdminActionButton>
            </div>
          </form>
        </LeavePhase2Panel>

        <LeavePhase2Panel
          title="Legal calendar versions"
          subtitle="Select a draft, add holidays, then publish to sync leave runtime."
          testId="glp18-calendars"
          actions={
            <AdminActionButton
              icon="fe fe-upload"
              disabled={saving || loading || !isDraft}
              onClick={this.publishSelected}
              testId="glp18-publish-calendar"
            >
              Publish selected
            </AdminActionButton>
          }
        >
          <label className="lux-glp-form" style={{ marginBottom: '0.75rem' }}>
            Active version
            <select
              data-testid="glp18-version-select"
              value={selectedVersionId || ''}
              onChange={(e) => this.selectVersion(e.target.value)}
            >
              <option value="">Select…</option>
              {(versions || []).map((v) => (
                <option key={v.id} value={v.id}>
                  {v.calendarRef || v.id} · {v.holidayCalendarKey || '—'} · {v.status || 'DRAFT'}
                </option>
              ))}
            </select>
          </label>
          <LeavePhase2Register
            loading={loading}
            rows={versions}
            testId="glp18-versions-register"
            emptyTitle="No legal calendars"
            emptyDescription="Use Create draft calendar above, or ask an admin to seed via API."
            columns={[
              { key: 'id', label: 'ID' },
              { key: 'calendarRef', label: 'Ref' },
              { key: 'holidayCalendarKey', label: 'Calendar key' },
              { key: 'jurisdictionId', label: 'Jurisdiction' },
              { key: 'status', label: 'Status' },
              {
                key: 'effectiveFrom',
                label: 'Effective',
                render: (r) => cell(r.effectiveFrom || r.versionNo),
              },
            ]}
          />
        </LeavePhase2Panel>

        {selected ? (
          <LeavePhase2Panel
            title="Holiday entries"
            subtitle="Blocking (non-optional) holidays sync to People → Holidays on publish."
            testId="glp18-holiday-entries"
          >
            {isDraft ? (
              <form
                className="lux-glp-form"
                onSubmit={this.addHoliday}
                data-testid="glp18-add-holiday-form"
                style={{ marginBottom: '1rem' }}
              >
                <label>
                  Date
                  <input
                    required
                    type="date"
                    value={holidayForm.holidayDate}
                    onChange={(e) =>
                      this.setState({ holidayForm: { ...holidayForm, holidayDate: e.target.value } })
                    }
                  />
                </label>
                <label>
                  Name
                  <input
                    required
                    value={holidayForm.name}
                    onChange={(e) =>
                      this.setState({ holidayForm: { ...holidayForm, name: e.target.value } })
                    }
                    placeholder="Republic Day"
                  />
                </label>
                <label>
                  Type
                  <select
                    value={holidayForm.entryType}
                    onChange={(e) =>
                      this.setState({ holidayForm: { ...holidayForm, entryType: e.target.value } })
                    }
                  >
                    <option value="PUBLIC">Public</option>
                    <option value="REGIONAL">Regional</option>
                    <option value="SUBSTITUTE">Substitute</option>
                  </select>
                </label>
                <label>
                  Observed date
                  <input
                    type="date"
                    value={holidayForm.observedDate}
                    onChange={(e) =>
                      this.setState({
                        holidayForm: { ...holidayForm, observedDate: e.target.value },
                      })
                    }
                  />
                </label>
                <label>
                  <input
                    type="checkbox"
                    checked={!!holidayForm.optional}
                    onChange={(e) =>
                      this.setState({
                        holidayForm: { ...holidayForm, optional: e.target.checked },
                      })
                    }
                  />{' '}
                  Optional (not synced / not blocking)
                </label>
                <label>
                  <input
                    type="checkbox"
                    checked={!!holidayForm.halfDay}
                    onChange={(e) =>
                      this.setState({
                        holidayForm: { ...holidayForm, halfDay: e.target.checked },
                      })
                    }
                  />{' '}
                  Half-day holiday (counts as 0.5 working day)
                </label>
                <div className="lux-glp-form__actions">
                  <AdminActionButton type="submit" icon="fe fe-plus" disabled={saving || loading}>
                    Add holiday
                  </AdminActionButton>
                </div>
              </form>
            ) : (
              <p className="lux-leave-policy__desc">
                Published calendar is read-only. Create a new draft to change holidays.
              </p>
            )}
            <LeavePhase2Register
              loading={loading}
              rows={holidays}
              testId="glp18-holidays-register"
              emptyTitle="No holidays in selected version"
              columns={[
                { key: 'holidayDate', label: 'Date' },
                { key: 'name', label: 'Name' },
                { key: 'entryType', label: 'Type' },
                { key: 'observedDate', label: 'Observed' },
                {
                  key: 'optional',
                  label: 'Optional',
                  render: (r) => cell(r.optional ? 'Yes' : 'No'),
                },
              ]}
            />
          </LeavePhase2Panel>
        ) : null}
      </>
    );
  }

  renderImports() {
    const { loading, imports } = this.state;
    return (
      <LeavePhase2Panel title="Holiday imports" subtitle="Official import batches and reconciliation.">
        <LeavePhase2Register
          loading={loading}
          rows={imports}
          testId="glp18-imports-register"
          emptyTitle="No import batches"
          columns={[
            { key: 'importRef', label: 'Batch' },
            { key: 'sourceType', label: 'Source' },
            { key: 'status', label: 'Status' },
            { key: 'rowCount', label: 'Records' },
            { key: 'createdDateTime', label: 'Imported' },
          ]}
        />
      </LeavePhase2Panel>
    );
  }

  renderWorking() {
    const {
      loading,
      workingRules,
      workingForm,
      resolvedPattern,
      jurisdictions,
      saving,
      empJurForm,
      empWdForm,
      employeeJurisdictions,
      employeeWorkingDays,
      previewEmployeeId,
    } = this.state;
    const preset = WORKING_DAY_PRESETS[workingForm.pattern] || WORKING_DAY_PRESETS.MON_FRI;
    return (
      <>
        <LeavePhase2Panel
          title="Resolved working week"
          subtitle="Priority: employee override → country/jurisdiction rule → team default → work schedule → shift → Mon–Fri."
        >
          <div className="lux-leave-form" style={{ marginBottom: 12 }}>
            <label className="lux-leave-form-field">
              <span>Preview for employee id (optional)</span>
              <input
                data-testid="glp18-preview-employee"
                value={previewEmployeeId}
                onChange={(e) => this.setState({ previewEmployeeId: e.target.value })}
                placeholder="e.g. 42"
              />
            </label>
            <AdminActionButton
              type="button"
              testId="glp18-preview-refresh"
              onClick={() => this.loadAll()}
            >
              Refresh resolved pattern
            </AdminActionButton>
          </div>
          <div className="lux-leave-form-grid" data-testid="glp18-resolved-pattern">
            <div>
              <span className="lux-leave-form-label">Workdays</span>
              <strong>{formatWorkdays(resolvedPattern && resolvedPattern.workdays)}</strong>
            </div>
            <div>
              <span className="lux-leave-form-label">Weekly offs</span>
              <strong>{formatWorkdays(resolvedPattern && resolvedPattern.weekendDays)}</strong>
            </div>
            <div>
              <span className="lux-leave-form-label">Source</span>
              <strong>{(resolvedPattern && resolvedPattern.source) || '—'}</strong>
            </div>
          </div>
        </LeavePhase2Panel>

        <LeavePhase2Panel
          title="Add working-day rule"
          subtitle="Team default (no jurisdiction) or country/region-scoped. Does not assume Sat/Sun are offs."
        >
          <form
            className="lux-leave-form"
            data-testid="glp18-working-form"
            onSubmit={(e) => {
              e.preventDefault();
              this.saveWorkingRule(e);
            }}
          >
            <label className="lux-leave-form-field">
              <span>Name</span>
              <input
                value={workingForm.name}
                onChange={(e) =>
                  this.setState({ workingForm: { ...workingForm, name: e.target.value } })
                }
                placeholder="e.g. India Mon–Sat"
                required
              />
            </label>
            <label className="lux-leave-form-field">
              <span>Pattern</span>
              <select
                value={workingForm.pattern}
                onChange={(e) =>
                  this.setState({ workingForm: { ...workingForm, pattern: e.target.value } })
                }
              >
                {Object.entries(WORKING_DAY_PRESETS).map(([key, value]) => (
                  <option key={key} value={key}>
                    {value.label}
                  </option>
                ))}
              </select>
            </label>
            <label className="lux-leave-form-field">
              <span>Scope</span>
              <select
                value={workingForm.jurisdictionId}
                onChange={(e) =>
                  this.setState({
                    workingForm: { ...workingForm, jurisdictionId: e.target.value },
                  })
                }
              >
                <option value="">Team default</option>
                {(jurisdictions || []).map((j) => (
                  <option key={j.id} value={j.id}>
                    {j.name || j.jurisdictionRef || j.id}
                    {j.countryCode ? ` (${j.countryCode}${j.regionCode ? `-${j.regionCode}` : ''})` : ''}
                  </option>
                ))}
              </select>
            </label>
            <p className="lux-leave-form-hint">
              Workdays: {formatWorkdays(preset.workdays)} · Weekly offs: {formatWorkdays(preset.weekendDays)}
            </p>
            <AdminActionButton type="submit" disabled={saving} testId="glp18-working-save">
              {saving ? 'Saving…' : 'Save working-day rule'}
            </AdminActionButton>
          </form>
        </LeavePhase2Panel>

        <LeavePhase2Panel
          title="Assign employee jurisdiction"
          subtitle="Maps an employee to a country/region so jurisdiction working-day rules apply."
        >
          <form
            className="lux-leave-form"
            data-testid="glp18-emp-jur-form"
            onSubmit={(e) => {
              e.preventDefault();
              this.saveEmployeeJurisdiction(e);
            }}
          >
            <label className="lux-leave-form-field">
              <span>Employee id</span>
              <input
                value={empJurForm.employeeId}
                onChange={(e) =>
                  this.setState({ empJurForm: { ...empJurForm, employeeId: e.target.value } })
                }
                required
              />
            </label>
            <label className="lux-leave-form-field">
              <span>Jurisdiction</span>
              <select
                value={empJurForm.jurisdictionId}
                onChange={(e) =>
                  this.setState({ empJurForm: { ...empJurForm, jurisdictionId: e.target.value } })
                }
                required
              >
                <option value="">Select…</option>
                {(jurisdictions || []).map((j) => (
                  <option key={j.id} value={j.id}>
                    {j.name || j.jurisdictionRef || j.id}
                  </option>
                ))}
              </select>
            </label>
            <AdminActionButton type="submit" disabled={saving} testId="glp18-emp-jur-save">
              Save jurisdiction assignment
            </AdminActionButton>
          </form>
          <LeavePhase2Register
            loading={loading}
            rows={employeeJurisdictions}
            testId="glp18-emp-jur-register"
            emptyTitle="No employee jurisdiction assignments"
            columns={[
              { key: 'id', label: 'ID' },
              { key: 'employeeId', label: 'Employee' },
              { key: 'jurisdictionId', label: 'Jurisdiction' },
              { key: 'active', label: 'Active' },
            ]}
          />
        </LeavePhase2Panel>

        <LeavePhase2Panel
          title="Employee working-day override"
          subtitle="Highest priority. Assign an existing working-day rule to a specific employee."
        >
          <form
            className="lux-leave-form"
            data-testid="glp18-emp-wd-form"
            onSubmit={(e) => {
              e.preventDefault();
              this.saveEmployeeWorkingDay(e);
            }}
          >
            <label className="lux-leave-form-field">
              <span>Employee id</span>
              <input
                value={empWdForm.employeeId}
                onChange={(e) =>
                  this.setState({ empWdForm: { ...empWdForm, employeeId: e.target.value } })
                }
                required
              />
            </label>
            <label className="lux-leave-form-field">
              <span>Working-day rule</span>
              <select
                value={empWdForm.workingDayRuleId}
                onChange={(e) =>
                  this.setState({ empWdForm: { ...empWdForm, workingDayRuleId: e.target.value } })
                }
                required
              >
                <option value="">Select…</option>
                {(workingRules || []).map((r) => (
                  <option key={r.id} value={r.id}>
                    {r.name || r.ruleRef || r.id}
                  </option>
                ))}
              </select>
            </label>
            <AdminActionButton type="submit" disabled={saving} testId="glp18-emp-wd-save">
              Save employee override
            </AdminActionButton>
          </form>
          <LeavePhase2Register
            loading={loading}
            rows={employeeWorkingDays}
            testId="glp18-emp-wd-register"
            emptyTitle="No employee working-day overrides"
            columns={[
              { key: 'id', label: 'ID' },
              { key: 'employeeId', label: 'Employee' },
              { key: 'workingDayRuleId', label: 'Rule' },
              { key: 'active', label: 'Active' },
            ]}
          />
        </LeavePhase2Panel>

        <LeavePhase2Panel title="Working-day rules" subtitle="Reusable patterns for team or jurisdiction scope.">
          <LeavePhase2Register
            loading={loading}
            rows={workingRules}
            testId="glp18-working-register"
            emptyTitle="No working-day rules"
            columns={[
              { key: 'id', label: 'ID' },
              { key: 'ruleRef', label: 'Ref' },
              { key: 'name', label: 'Name' },
              {
                key: 'jurisdictionId',
                label: 'Scope',
                render: (r) => cell(r.jurisdictionId ? `Jurisdiction ${r.jurisdictionId}` : 'Team default'),
              },
              {
                key: 'configJson',
                label: 'Workdays',
                render: (r) => {
                  try {
                    const cfg = typeof r.configJson === 'string' ? JSON.parse(r.configJson) : r.configJson;
                    return cell(formatWorkdays(cfg && cfg.workdays));
                  } catch (e) {
                    return cell(r.configJson || '—');
                  }
                },
              },
              { key: 'active', label: 'Active' },
            ]}
          />
        </LeavePhase2Panel>
      </>
    );
  }

  saveWorkingRule = (event) => {
    if (event && event.preventDefault) event.preventDefault();
    const { workingForm } = this.state;
    if (!workingForm.name || !String(workingForm.name).trim()) {
      this.setState({ error: 'Name is required for a working-day rule.' });
      return;
    }
    const preset = WORKING_DAY_PRESETS[workingForm.pattern] || WORKING_DAY_PRESETS.MON_FRI;
    this.runAction(
      (teamId) =>
        api.saveWorkingDayRule({
          userTeamId: teamId,
          actorId: this.actorId(),
          name: workingForm.name.trim(),
          jurisdictionId: workingForm.jurisdictionId ? Number(workingForm.jurisdictionId) : null,
          active: true,
          effectiveFrom: '2024-01-01',
          configJson: JSON.stringify({
            workdays: preset.workdays,
            weekendDays: preset.weekendDays,
            halfDayAllowed: workingForm.halfDayAllowed !== false,
            pattern: workingForm.pattern,
          }),
        }).then(() => {
          this.setState({ workingForm: { ...EMPTY_WORKING_FORM } });
        }),
      'Working-day rule saved.'
    );
  };

  saveEmployeeJurisdiction = (event) => {
    if (event && event.preventDefault) event.preventDefault();
    const { empJurForm } = this.state;
    if (!empJurForm.employeeId || !empJurForm.jurisdictionId) {
      this.setState({ error: 'Employee id and jurisdiction are required.' });
      return;
    }
    this.runAction(
      (teamId) =>
        api.saveEmployeeJurisdiction({
          userTeamId: teamId,
          actorId: this.actorId(),
          employeeId: Number(empJurForm.employeeId),
          jurisdictionId: Number(empJurForm.jurisdictionId),
          active: true,
          effectiveFrom: '2024-01-01',
        }).then(() => {
          this.setState({ empJurForm: { ...EMPTY_EMP_JUR_FORM } });
        }),
      'Employee jurisdiction assignment saved.'
    );
  };

  saveEmployeeWorkingDay = (event) => {
    if (event && event.preventDefault) event.preventDefault();
    const { empWdForm } = this.state;
    if (!empWdForm.employeeId || !empWdForm.workingDayRuleId) {
      this.setState({ error: 'Employee id and working-day rule are required.' });
      return;
    }
    this.runAction(
      (teamId) =>
        api.saveEmployeeWorkingDay({
          userTeamId: teamId,
          actorId: this.actorId(),
          employeeId: Number(empWdForm.employeeId),
          workingDayRuleId: Number(empWdForm.workingDayRuleId),
          active: true,
          effectiveFrom: '2024-01-01',
        }).then(() => {
          this.setState({ empWdForm: { ...EMPTY_EMP_WD_FORM } });
        }),
      'Employee working-day override saved.'
    );
  };

  renderImpact() {
    const { loading, changeTasks, impact } = this.state;
    const impactRows = impact && typeof impact === 'object' ? [impact] : [];
    return (
      <>
        <LeavePhase2Panel title="Calendar impact preview" subtitle="Leave accrual and eligibility impact before publish.">
          <LeavePhase2Register
            loading={loading}
            rows={impactRows}
            testId="glp18-impact-register"
            emptyTitle="No impact preview"
            emptyDescription="Publish a calendar version or select one to preview downstream impact."
            columns={[
              { key: 'holidayCount', label: 'Holidays' },
              { key: 'blockingHolidayCount', label: 'Blocking' },
              { key: 'affectedLeaveDays', label: 'Leave days' },
              { key: 'summary', label: 'Summary' },
            ]}
          />
        </LeavePhase2Panel>
        <LeavePhase2Panel title="Change tasks" subtitle="Pending calendar change workflow items.">
          <LeavePhase2Register
            loading={loading}
            rows={changeTasks}
            testId="glp18-tasks-register"
            emptyTitle="No pending change tasks"
            columns={[
              { key: 'taskRef', label: 'Task' },
              { key: 'taskType', label: 'Type' },
              { key: 'status', label: 'Status' },
            ]}
          />
        </LeavePhase2Panel>
      </>
    );
  }

  render() {
    const { loading, versions, imports, workingRules } = this.state;
    const section = sectionFromPath(this.props.location.pathname);
    const kpiCards = [
      { id: 'cal', label: 'Calendars', value: versions.length, tone: 'primary', icon: 'fe fe-calendar' },
      { id: 'imp', label: 'Imports', value: imports.length, tone: 'blue', icon: 'fe fe-upload' },
      { id: 'wd', label: 'Working rules', value: workingRules.length, tone: 'green', icon: 'fe fe-sun' },
    ];

    return this.renderChrome({
      testId: 'page-leave-legal-calendars',
      kpiCards,
      pageMeta: {
        tone: 'emerald',
        icon: 'fe fe-calendar',
        eyebrow: 'Admin · Leave',
        titleLead: 'Legal',
        titleAccent: 'Calendars',
        lede: 'Create → add holidays → publish syncs People holidays used by leave day counting.',
      },
      heroNav: renderLeavePhase2Nav(NAV, this.props.location.pathname),
      children: (
        <>
          {section === 'calendars' && this.renderCalendars()}
          {section === 'imports' && this.renderImports()}
          {section === 'working' && this.renderWorking()}
          {section === 'impact' && this.renderImpact()}
        </>
      ),
    });
  }
}

export default connect(mapLeavePhase2State)(withRouter(LegalCalendarsPage));
