/**
 * F06-T2/T5 — Timesheet recommendation and agent draft stubs.
 */
export function buildTimesheetRecommendationDraft(intelligence, billability) {
  if (!intelligence) {
    return null;
  }

  const parts = [];
  if (intelligence.daysNeedingAttention > 0) {
    parts.push(`${intelligence.daysNeedingAttention} day(s) below daily target or missing entries`);
  }
  if (intelligence.dataQualityIssues > 0) {
    parts.push(`${intelligence.dataQualityIssues} data quality issue(s) detected`);
  }
  if (intelligence.pendingApprovals > 0) {
    parts.push(`${intelligence.pendingApprovals} timesheet(s) awaiting manager approval`);
  }
  if (intelligence.openConflicts > 0) {
    parts.push(`${intelligence.openConflicts} open approval conflict(s)`);
  }
  if (billability && billability.leakagePct > 35) {
    parts.push(`non-billable leakage at ${billability.leakagePct}% of work hours`);
  }

  const summary = parts.length
    ? parts.join("; ")
    : "This week looks compliant — no major anomalies detected.";

  let recommendation = "Continue monitoring daily totals and submit before the approval deadline.";
  if (intelligence.defaulterCount > 0) {
    recommendation = "Follow up with defaulters and lock approved weeks before payroll processing.";
  } else if (intelligence.pendingApprovals > 0) {
    recommendation = "Clear the pending approval queue and resolve conflicts before week lock.";
  } else if (intelligence.daysNeedingAttention > 0) {
    recommendation = "Backfill missing days or add notes on under-target days before submit.";
  }

  return {
    draftOnly: true,
    summary,
    recommendation,
    confidence: intelligence.dataQualityIssues > 2 ? 0.72 : 0.86,
    disclaimer: "Draft insight — human review required. Full timesheet intelligence will be available in a future release.",
    actions: ["accept", "reject", "defer"],
  };
}

export function applyAgentDraftAction(recommendation, action) {
  if (!recommendation || !action) {
    return null;
  }
  const verb = String(action).toLowerCase();
  const labels = {
    accept: "Accepted draft recommendation (logged locally)",
    reject: "Rejected draft recommendation (logged locally)",
    defer: "Deferred draft recommendation for later review",
  };
  return {
    action: verb,
    message: labels[verb] || "Draft action recorded",
    at: new Date().toISOString(),
    recommendation: recommendation.summary,
  };
}
