import React from "react";
import classNames from "classnames/bind";
import { ResourcesSectionHead } from "views/resources/components/ResourcesLuxShared";

export default function SkillsCategoryPanel({ breakdown, loading, activeCategory, onCategorySelect }) {
  if (loading || !breakdown || breakdown.length === 0) {
    return null;
  }

  const maxCount = breakdown[0].count || 1;
  const totalProfiles = breakdown.reduce((sum, entry) => sum + (entry.count || 0), 0);

  return (
    <section className="lux-hrms-dash__panel lux-skills-panel lux-skills-panel--accent">
      <ResourcesSectionHead
        tone="violet"
        icon="fe fe-pie-chart"
        eyebrow="Coverage map"
        title="Skills by category"
        subtitle="Tap a category to filter the proficiency register"
        badge={`${breakdown.length} areas`}
      />
      <div className="lux-hrms-dash__panel-body lux-skills-panel__body">
        <div className="lux-skills-panel__summary" aria-hidden="true">
          <span>
            <strong>{totalProfiles}</strong> profile rows
          </span>
          <span>Highest share leads the list</span>
        </div>
        <div className="lux-skills-category-list" role="list">
          {breakdown.map((entry) => {
            const isActive = activeCategory === entry.category;
            const rowClass = classNames("lux-skills-category-row", {
              "is-active": isActive,
              "is-clickable": Boolean(onCategorySelect),
            });
            const content = (
              <>
                <div className="lux-skills-category-row__head">
                  <span
                    className={classNames(
                      "lux-skills-category-row__icon",
                      entry.tone && `is-${entry.tone}`
                    )}
                    aria-hidden="true"
                  >
                    <i className={entry.icon} />
                  </span>
                  <div className="lux-skills-category-row__copy">
                    <strong>{entry.category}</strong>
                    <span className="lux-skills-category-row__stats">
                      <em>{entry.count} profiles</em>
                      <em>avg {entry.avgScore}/4</em>
                      <em>{entry.expertCount} expert</em>
                    </span>
                  </div>
                  <span className="lux-skills-category-row__pct">
                    <strong>{entry.pct}%</strong>
                    <small>of matrix</small>
                  </span>
                </div>
                <div className="lux-skills-category-row__bar" aria-hidden="true">
                  <span
                    className={classNames(
                      "lux-skills-category-row__fill",
                      entry.tone && `is-${entry.tone}`
                    )}
                    style={{ width: `${Math.round((entry.count / maxCount) * 100)}%` }}
                  />
                </div>
                {isActive ? (
                  <span className="lux-skills-category-row__active-hint">Filtering register · tap again to clear</span>
                ) : null}
              </>
            );

            if (!onCategorySelect) {
              return (
                <article key={entry.category} className={rowClass} role="listitem">
                  {content}
                </article>
              );
            }

            return (
              <button
                key={entry.category}
                type="button"
                className={rowClass}
                role="listitem"
                aria-pressed={isActive}
                onClick={() => onCategorySelect(isActive ? "ALL" : entry.category)}
              >
                {content}
              </button>
            );
          })}
        </div>
      </div>
    </section>
  );
}
