import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isEmployeeFinanceEnabled } from "config/employee-finance.config";
import { EMPLOYEE_FINANCE_PAGE_META } from "config/employee-finance-nav.config";
import { employeeFinanceService } from "_services/employeeFinance.service";
import EmployeeFinanceLuxPage, {
  EmployeeFinanceActionButton,
  EmployeeFinanceInsightPanel,
  EmployeeFinanceLuxPanel,
} from "views/payroll/components/EmployeeFinanceLuxShared";
import CompensationRegister from "views/payroll/components/CompensationRegister";
import CompensationChangeDrawer from "views/payroll/components/CompensationChangeDrawer";

class CompensationPage extends Component {
  state = {
    loading: true,
    loadError: null,
    exporting: false,
    drawerOpen: false,
    busyId: null,
    dataSource: null,
    changes: [],
    kpiCards: [],
    insights: [],
    filters: { query: "", status: "ALL", changeType: "ALL" },
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Compensation");
    }
    this.loadData();
  }

  loadData = async (filters = this.state.filters) => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await employeeFinanceService.getCompensationOverview(filters);
      const overview = result.payload || {};
      this.setState({
        loading: false,
        changes: overview.changes || [],
        kpiCards: overview.kpiCards || [],
        insights: overview.insights || [],
        dataSource: result.source,
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load compensation changes.",
      });
    }
  };

  handleFilterChange = (patch) => {
    const filters = { ...this.state.filters, ...patch };
    this.setState({ filters }, () => this.loadData(filters));
  };

  handleApprove = async (changeId, userTeamId) => {
    this.setState({ busyId: changeId });
    try {
      await employeeFinanceService.approveCompensationChange(changeId, { userTeamId });
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to approve compensation change." });
    } finally {
      this.setState({ busyId: null });
    }
  };

  handleReject = async (changeId, userTeamId) => {
    this.setState({ busyId: changeId });
    try {
      await employeeFinanceService.rejectCompensationChange(
        changeId,
        "Rejected during compensation review",
        { userTeamId }
      );
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to reject compensation change." });
    } finally {
      this.setState({ busyId: null });
    }
  };

  handlePropose = async (payload) => {
    await employeeFinanceService.proposeCompensationChange(payload);
    await this.loadData();
  };

  handleExport = async () => {
    this.setState({ exporting: true });
    try {
      const result = await employeeFinanceService.exportCompensation(this.state.filters);
      const blob = new Blob([result.payload || ""], { type: "text/csv;charset=utf-8;" });
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement("a");
      anchor.href = url;
      anchor.download = result.filename || "compensation.csv";
      anchor.click();
      URL.revokeObjectURL(url);
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to export compensation changes." });
    } finally {
      this.setState({ exporting: false });
    }
  };

  render() {
    if (!isEmployeeFinanceEnabled()) {
      return <PersonaAccessDenied featureLabel="Compensation" />;
    }

    const { loading, loadError, exporting, drawerOpen, busyId, dataSource, changes, kpiCards, insights, filters } = this.state;
    const meta = EMPLOYEE_FINANCE_PAGE_META.compensation;

    return (
      <EmployeeFinanceLuxPage
        pageMeta={meta}
        dataSource={dataSource}
        demoLabel="Demo compensation queue"
        loading={loading}
        kpiCards={kpiCards}
        heroActions={
          <>
            <EmployeeFinanceActionButton icon="fe fe-download" variant="ghost" onClick={this.handleExport} disabled={exporting}>
              {exporting ? "Exporting…" : "Export CSV"}
            </EmployeeFinanceActionButton>
            <EmployeeFinanceActionButton icon="fe fe-plus" variant="primary" onClick={() => this.setState({ drawerOpen: true })}>
              Propose change
            </EmployeeFinanceActionButton>
          </>
        }
      >
        <EmployeeFinanceInsightPanel insights={insights} />
        {loadError ? (
          <EmployeeFinanceLuxPanel title="Compensation load issue" meta={loadError} accent="rose">
            <EmployeeFinanceActionButton icon="fe fe-refresh-cw" variant="primary" onClick={() => this.loadData()}>
              Retry
            </EmployeeFinanceActionButton>
          </EmployeeFinanceLuxPanel>
        ) : null}
        <EmployeeFinanceLuxPanel
          title={meta.panelTitle}
          meta={meta.panelMeta}
          icon="fe fe-trending-up"
          accent="indigo"
          actions={
            <div className="lux-empfin-snapshots__filters lux-empfin-snapshots__filters--inline">
              <select value={filters.changeType || "ALL"} onChange={(e) => this.handleFilterChange({ changeType: e.target.value })}>
                <option value="ALL">All types</option>
                <option value="MERIT">Merit</option>
                <option value="PROMOTION">Promotion</option>
                <option value="ADJUSTMENT">Adjustment</option>
              </select>
            </div>
          }
        >
          <CompensationRegister
            rows={changes}
            loading={loading}
            busyId={busyId}
            onApprove={this.handleApprove}
            onReject={this.handleReject}
            onPropose={() => this.setState({ drawerOpen: true })}
          />
        </EmployeeFinanceLuxPanel>
        <CompensationChangeDrawer
          open={drawerOpen}
          onClose={() => this.setState({ drawerOpen: false })}
          onSave={this.handlePropose}
        />
      </EmployeeFinanceLuxPage>
    );
  }
}

export default CompensationPage;
