import React, { useMemo } from "react";
import moment from "moment";
import classNames from "classnames/bind";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { groupLeavesForCalendar, parseLeaveDate, isConfiguredWeekend } from "./leave.utils";

function buildMonthHeatmap(leaves, month, workdays) {
  const daysInMonth = month.daysInMonth();
  const counts = new Array(daysInMonth).fill(0);

  (leaves || []).forEach((leave) => {
    const from = parseLeaveDate(leave.applicationFromDate || leave.application_from_date);
    const to = parseLeaveDate(leave.applicationToDate || leave.application_to_date || leave.applicationFromDate);
    if (!from || !to) return;

    const cursor = from.clone().startOf("day");
    const end = to.clone().startOf("day");
    while (cursor.isSameOrBefore(end, "day")) {
      if (cursor.isSame(month, "month")) {
        counts[cursor.date() - 1] += 1;
      }
      cursor.add(1, "day");
    }
  });

  return counts.map((count, index) => {
    const date = month.clone().date(index + 1);
    return {
      day: index + 1,
      count,
      isWeekend: isConfiguredWeekend(date, workdays),
      isToday: date.isSame(moment(), "day"),
    };
  });
}

function getHeatLevel(count) {
  if (count >= 4) return "high";
  if (count >= 2) return "medium";
  if (count >= 1) return "low";
  return "none";
}

function LeaveTeamCalendar({ leaves, employees, loading, monthDate, onMonthChange, workdays }) {
  const month = moment(monthDate || new Date()).startOf("month");

  const employeesById = useMemo(() => {
    const map = {};
    (employees || []).forEach((emp) => {
      map[emp.id] = emp;
    });
    return map;
  }, [employees]);

  const rows = useMemo(
    () => groupLeavesForCalendar(leaves, employeesById),
    [leaves, employeesById]
  );

  const heatmap = useMemo(
    () => buildMonthHeatmap(leaves, month, workdays),
    [leaves, month, workdays]
  );

  const uniqueEmployees = useMemo(() => new Set(rows.map((row) => row.employeeId)).size, [rows]);
  const totalDays = useMemo(
    () => rows.reduce((sum, row) => sum + (Number(row.days) || 0), 0),
    [rows]
  );

  const handlePrev = () => {
    if (onMonthChange) onMonthChange(month.clone().subtract(1, "month").toDate());
  };

  const handleNext = () => {
    if (onMonthChange) onMonthChange(month.clone().add(1, "month").toDate());
  };

  const handleToday = () => {
    if (onMonthChange) onMonthChange(moment().startOf("month").toDate());
  };

  return (
    <section className="lux-leave-subpanel lux-leave-calendar" aria-label="Team leave calendar">
      <header className="lux-leave-subpanel__head">
        <div>
          <span className="lux-leave-subpanel__eyebrow">Team view</span>
          <h3 className="lux-leave-subpanel__title">Leave calendar</h3>
          <p className="lux-leave-subpanel__sub">
            Approved and synced leave for {month.format("MMMM YYYY")}
          </p>
        </div>
        <div className="lux-leave-calendar__nav">
          <button type="button" className="lux-leave-calendar__nav-btn" onClick={handlePrev} aria-label="Previous month">
            <i className="fe fe-chevron-left" aria-hidden="true" />
          </button>
          <span className="lux-leave-calendar__month">{month.format("MMMM YYYY")}</span>
          <button type="button" className="lux-leave-calendar__nav-btn" onClick={handleNext} aria-label="Next month">
            <i className="fe fe-chevron-right" aria-hidden="true" />
          </button>
          <button type="button" className="lux-leave-calendar__today-btn" onClick={handleToday}>
            Today
          </button>
        </div>
      </header>

      <div className="lux-leave-calendar__summary">
        <article className="lux-leave-calendar__stat">
          <span>People on leave</span>
          <strong>{loading ? "—" : uniqueEmployees}</strong>
        </article>
        <article className="lux-leave-calendar__stat">
          <span>Approved blocks</span>
          <strong>{loading ? "—" : rows.length}</strong>
        </article>
        <article className="lux-leave-calendar__stat">
          <span>Total days</span>
          <strong>{loading ? "—" : totalDays}</strong>
        </article>
      </div>

      <div className="lux-leave-calendar__heatmap-wrap">
        <div className="lux-leave-calendar__heatmap-label">Month density</div>
        {loading ? (
          <div className="lux-leave-calendar__heatmap lux-leave-calendar__heatmap--skeleton" aria-busy="true" />
        ) : (
          <div className="lux-leave-calendar__heatmap" role="list" aria-label="Leave density by day">
            {heatmap.map((cell) => (
              <div
                key={cell.day}
                role="listitem"
                className={classNames("lux-leave-calendar__day", `is-${getHeatLevel(cell.count)}`, {
                  "is-weekend": cell.isWeekend,
                  "is-today": cell.isToday,
                })}
                title={`${month.format("MMM")} ${cell.day}: ${cell.count} leave block${cell.count === 1 ? "" : "s"}`}
              >
                <span className="lux-leave-calendar__day-num">{cell.day}</span>
                {cell.count > 0 && <span className="lux-leave-calendar__day-count">{cell.count}</span>}
              </div>
            ))}
          </div>
        )}
        <div className="lux-leave-calendar__legend" aria-hidden="true">
          <span className="is-low">1</span>
          <span className="is-medium">2–3</span>
          <span className="is-high">4+</span>
        </div>
      </div>

      {loading ? (
        <div className="lux-leave-register__skeleton" aria-busy="true" />
      ) : rows.length === 0 ? (
        <LuxRegisterEmptyState
          className="lux-register-empty--compact lux-leave-empty"
          icon="fe fe-calendar"
          title="No approved leave this month"
          description={`No approved or synced leave between ${month.startOf("month").format("MMM D")} and ${month.endOf("month").format("MMM D")}.`}
        />
      ) : (
        <div className="lux-leave-register-wrap lux-leave-calendar__register">
          <table className="lux-leave-register">
            <thead>
              <tr>
                <th>Employee</th>
                <th>Dates</th>
                <th>Type</th>
                <th>Days</th>
                <th>Status</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((row) => (
                <tr key={row.id} className="lux-leave-register__row">
                  <td>
                    <span className="lux-leave-calendar__employee">
                      <span className="lux-leave-calendar__avatar" aria-hidden="true">
                        {String(row.employeeName || "?")
                          .split(" ")
                          .filter(Boolean)
                          .map((part) => part[0])
                          .join("")
                          .slice(0, 2)
                          .toUpperCase()}
                      </span>
                      <strong>{row.employeeName}</strong>
                    </span>
                  </td>
                  <td>
                    <span className="lux-leave-register__dates">{row.dateLabel}</span>
                  </td>
                  <td>
                    <span className="lux-leave-register__type">
                      <strong>{row.leaveTypeDescription || row.leaveTypeCode || "—"}</strong>
                      {row.halfDay && <em>Half day</em>}
                    </span>
                  </td>
                  <td>
                    <span className="lux-leave-register__duration">{row.days != null ? row.days : "—"}</span>
                  </td>
                  <td>
                    <span className={classNames("lux-leave-status-badge", `is-${row.statusMeta.tone}`)}>
                      {row.statusMeta.label}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </section>
  );
}

export default LeaveTeamCalendar;
