import {
  UNIVERSAL_APPROVAL_PRIORITIES,
  UNIVERSAL_APPROVAL_STATUSES,
  getApprovalDomainMeta,
} from "config/universal-approval.config";

function parseDueDate(dueLabel) {
  if (!dueLabel) {
    return null;
  }
  const parsed = Date.parse(String(dueLabel));
  return Number.isNaN(parsed) ? null : new Date(parsed);
}

export function classifyApprovalAging(item, now = new Date()) {
  if (!item || item.status !== UNIVERSAL_APPROVAL_STATUSES.PENDING) {
    return null;
  }
  const due = parseDueDate(item.dueLabel);
  if (due) {
    const diffMs = due.getTime() - now.getTime();
    const diffDays = diffMs / (1000 * 60 * 60 * 24);
    if (diffDays < 0) {
      return "overdue";
    }
    if (diffDays <= 2) {
      return "dueSoon";
    }
    return "onTrack";
  }
  if (item.priority === UNIVERSAL_APPROVAL_PRIORITIES.HIGH) {
    return "dueSoon";
  }
  return "onTrack";
}

export function buildApprovalDomainBreakdown(items) {
  const pending = (items || []).filter((item) => item.status === UNIVERSAL_APPROVAL_STATUSES.PENDING);
  const counts = {};
  pending.forEach((item) => {
    counts[item.domain] = (counts[item.domain] || 0) + 1;
  });

  return Object.entries(counts)
    .map(([domain, count]) => {
      const meta = getApprovalDomainMeta(domain);
      return {
        domain,
        label: meta.label,
        count,
        tone: meta.tone || "slate",
      };
    })
    .sort((a, b) => b.count - a.count);
}

export function buildApprovalAgingBuckets(items, now = new Date()) {
  const pending = (items || []).filter((item) => item.status === UNIVERSAL_APPROVAL_STATUSES.PENDING);
  const buckets = { overdue: 0, dueSoon: 0, onTrack: 0 };
  pending.forEach((item) => {
    const bucket = classifyApprovalAging(item, now) || "onTrack";
    buckets[bucket] += 1;
  });
  return buckets;
}

export function buildApprovalAnalyticsMetrics(items, now = new Date()) {
  const list = items || [];
  const pending = list.filter((item) => item.status === UNIVERSAL_APPROVAL_STATUSES.PENDING);
  const aging = buildApprovalAgingBuckets(list, now);
  const domainBreakdown = buildApprovalDomainBreakdown(list);
  const approved = list.filter((item) => item.status === UNIVERSAL_APPROVAL_STATUSES.APPROVED).length;
  const rejected = list.filter((item) => item.status === UNIVERSAL_APPROVAL_STATUSES.REJECTED).length;
  const delegatePending = pending.filter((item) => item.actingAsDelegate).length;
  const bottleneck = domainBreakdown[0] || null;

  return {
    pending: pending.length,
    approved,
    rejected,
    overdue: aging.overdue,
    dueSoon: aging.dueSoon,
    onTrack: aging.onTrack,
    delegatePending,
    domainBreakdown,
    bottleneckDomain: bottleneck ? bottleneck.label : "—",
    bottleneckCount: bottleneck ? bottleneck.count : 0,
  };
}
