/**
 * Redux middleware — records audit events for successful mutations (F20-T1).
 */
import { shouldUseAuditWrite } from "config/audit-write.config";
import { mapReduxActionToAudit } from "config/audit-write.utils";
import { recordAuditEvent } from "config/audit-write.service";

const SKIP_TYPES = new Set([
  "AUDIT_LOAD_TIMELINE_REQUEST",
  "AUDIT_LOAD_TIMELINE_SUCCESS",
  "AUDIT_LOAD_TIMELINE_FAILURE",
]);

export function auditWriteMiddleware() {
  return (next) => (action) => {
    const result = next(action);
    if (!shouldUseAuditWrite() || !action || SKIP_TYPES.has(action.type)) {
      return result;
    }
    const mapped = mapReduxActionToAudit(action);
    if (mapped) {
      recordAuditEvent(mapped);
    }
    return result;
  };
}
