import { axiosUtils } from "../_helpers";
import urlConfig from "url.config";
import envconfig from "env.config";
import { employeeService } from "_services/employee.service";
import {
  mergeSummaryWithEmployee,
  normalizeEmployee360Payload,
} from "config/employee360-context.utils";
import { isDocumentVaultEnabled } from "config/document-vault.config";
import { isAssetRegisterEnabled } from "config/asset-register.config";
import { isPayrollManagementEnabled } from "config/payroll.config";
import { documentVaultService } from "_services/documentVault.service";
import { assetRegisterService } from "_services/assetRegister.service";
import { payrollService } from "_services/payroll.service";
import { resolveMaskingPolicyForPersona } from "config/persona-context.utils";

/**
 * F02-T1: Employee 360 aggregate — API when enabled, client fallback otherwise.
 * PR-05: fail closed on API error; client fallback never drops maskingPolicy.
 */
export const employee360Service = {
  getEmployee360,
};

function buildFallbackProjectAllocations(allocatedProjects) {
  if (!Array.isArray(allocatedProjects) || allocatedProjects.length === 0) {
    return [];
  }
  return allocatedProjects.map((name, index) => ({
    id: `alloc-${index + 1}`,
    name,
    code: "—",
    role: "—",
    allocationPct: null,
    health: "—",
    schedule: "—",
  }));
}

function buildClientSummary(employee) {
  if (!employee) {
    return null;
  }

  const skills = Array.isArray(employee.skills) ? employee.skills.length : 0;
  const profileCompletionPct = Math.min(100, 55 + skills * 5 + (employee.email ? 10 : 0));

  return {
    teamName: employee.defaultUserTeamDetails && employee.defaultUserTeamDetails.name,
    roleName: employee.userAccessDetails && employee.userAccessDetails.name,
    manager: employee.manager || employee.managerName,
    location: employee.location,
    employmentType: employee.employmentType,
    attendanceToday: "—",
    leaveBalanceDays: employee.leaveBalanceDays != null ? employee.leaveBalanceDays : null,
    timesheetStatus: "—",
    pendingApprovals: 0,
    profileCompletionPct,
    payrollGroup: "—",
    payroll: null,
    projectAllocations: [],
    documents: [],
    assets: [],
    attentionItems: [
      {
        id: "profile",
        label: "Review profile details for completeness",
        icon: "fe fe-user",
      },
    ],
    allocatedProjects: Array.isArray(employee.allocatedProjects) ? employee.allocatedProjects : [],
    projectAllocations: Array.isArray(employee.projectAllocations)
      ? employee.projectAllocations
      : buildFallbackProjectAllocations(employee.allocatedProjects),
    documents: Array.isArray(employee.documents) ? employee.documents : [],
    assets: Array.isArray(employee.assets) ? employee.assets : [],
    payroll: employee.payroll && typeof employee.payroll === "object" ? employee.payroll : null,
    recentNotes: [],
    activityCount: null,
  };
}

/**
 * Resolve a non-null maskingPolicy for client/mock fallback.
 * Prefer viewer context; otherwise derive from activePersona; never return null.
 */
function resolveFallbackMaskingPolicy(viewerContext) {
  const fromContext = viewerContext && viewerContext.maskingPolicy;
  if (fromContext && typeof fromContext === "object") {
    return fromContext;
  }
  const persona =
    (viewerContext && viewerContext.activePersona) ||
    (viewerContext && viewerContext.persona) ||
    "EMPLOYEE";
  return resolveMaskingPolicyForPersona(persona) || {};
}

async function getEmployee360FromApi(employeeId) {
  const response = await axiosUtils.get(`${urlConfig.EMPLOYEE_360}/${employeeId}/360`);
  const payload = response && response.payload ? response.payload : response;
  const normalized = normalizeEmployee360Payload(payload);
  if (!normalized) {
    throw new Error("Invalid Employee 360 response");
  }
  return {
    ...normalized,
    summary: mergeSummaryWithEmployee(normalized.employee, normalized.summary),
    source: "api",
  };
}

async function getEmployee360FromClient(employeeId, viewerContext) {
  const maskingPolicy = resolveFallbackMaskingPolicy(viewerContext);
  const response = await employeeService.getEmployeeById(employeeId);
  const employee = response && response.payload ? response.payload : response;
  return {
    employee,
    summary: buildClientSummary(employee),
    visibleTabIds: null,
    maskingPolicy,
    accessAllowed: null,
    source: "client",
  };
}

async function getEmployee360(employeeId, viewerContext) {

  if (envconfig.USE_EMPLOYEE_360_API === true) {
    try {
      return finalizeEmployee360Result(await getEmployee360FromApi(employeeId), employeeId);
    } catch (e) {
      console.warn("[Employee360] API unavailable.", e);
      // EH21: fail-closed still carries a non-null maskingPolicy for callers/UI.
      return {
        payload: null,
        source: "api-error",
        error: e,
        maskingPolicy: resolveFallbackMaskingPolicy(viewerContext),
      };
    }
  }

  return finalizeEmployee360Result(await getEmployee360FromClient(employeeId, viewerContext), employeeId);
}

async function enrichSummaryFromVault(employeeId, summary) {
  if (!summary || !employeeId) {
    return summary;
  }
  const next = { ...summary };
  if (isDocumentVaultEnabled()) {
    try {
      const docResult = await documentVaultService.getEmployeeDocuments(employeeId);
      if (Array.isArray(docResult.payload) && docResult.payload.length > 0) {
        next.documents = docResult.payload;
      }
    } catch (e) {
      // keep existing summary documents
    }
  }
  if (isAssetRegisterEnabled()) {
    try {
      const assetResult = await assetRegisterService.getEmployeeAssets(employeeId);
      if (Array.isArray(assetResult.payload) && assetResult.payload.length > 0) {
        next.assets = assetResult.payload;
      }
    } catch (e) {
      // keep existing summary assets
    }
  }
  if (isPayrollManagementEnabled()) {
    try {
      const payrollResult = await payrollService.getEmployeePayroll(employeeId);
      if (payrollResult.payload && typeof payrollResult.payload === "object") {
        next.payroll = payrollResult.payload;
        if (payrollResult.payload.payrollGroup) {
          next.payrollGroup = payrollResult.payload.payrollGroup;
        }
      }
    } catch (e) {
      // keep existing summary payroll
    }
  }
  return next;
}

async function finalizeEmployee360Result(result, employeeId) {
  if (!result || !result.summary) {
    return result;
  }
  // Live aggregate already includes documents/assets/payroll from fservices adapters.
  if (result.source === "api") {
    return result;
  }
  const summary = await enrichSummaryFromVault(employeeId, result.summary);
  return { ...result, summary };
}
