import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import {
  ANALYTICS_DOMAINS,
  isAnalyticsAiInsightsEnabled,
  isAnalyticsPlatformEnabled,
} from "config/analytics-platform.config";
import { analyticsPlatformService } from "_services/analyticsPlatform.service";
import AnalyticsLuxPage, { AnalyticsActionButton, AnalyticsLuxPanel } from "views/analytics/components/AnalyticsLuxShared";
import AnalyticsAiInsightPanel from "views/analytics/components/AnalyticsAiInsightPanel";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { recordAuditEvent } from "config/audit-write.service";
import { AUDIT_ACTION_TYPES, AUDIT_ENTITY_TYPES } from "_constants/audit.constants";

const DOMAIN_LABELS = {
  [ANALYTICS_DOMAINS.EXECUTIVE]: "Executive",
  [ANALYTICS_DOMAINS.WORKFORCE]: "Workforce",
  [ANALYTICS_DOMAINS.DELIVERY]: "Delivery",
  [ANALYTICS_DOMAINS.RESOURCE]: "Resource",
  [ANALYTICS_DOMAINS.PAYROLL]: "Payroll",
  [ANALYTICS_DOMAINS.FINANCE]: "Finance",
  [ANALYTICS_DOMAINS.APPROVALS]: "Approvals",
  [ANALYTICS_DOMAINS.RISK]: "Risk",
};

class AnalyticsAiInsightsPage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    domain: ANALYTICS_DOMAINS.EXECUTIVE,
    insight: null,
    allInsights: [],
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("AI insights");
    this.loadInsights(this.state.domain);
  }

  loadInsights = async (domain) => {
    this.setState({ loading: true, loadError: null, domain });
    try {
      const result = await analyticsPlatformService.getAnalyticsAiInsight(domain);
      const insight = result.payload || null;
      this.setState({ insight, loading: false, dataSource: result.source, loadError: null });
      recordAuditEvent({
        actionType: AUDIT_ACTION_TYPES.AUDIT_VIEWED,
        entityType: AUDIT_ENTITY_TYPES.ADMIN_CONFIG,
        entityRef: `analytics-ai-insight-${domain}`,
        metadata: { domain, sourceReferences: insight && insight.sourceReferences },
      });
    } catch (e) {
      this.setState({ loading: false, loadError: "Unable to load AI insight.", insight: null });
    }
  };

  loadAllDomains = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const domains = Object.values(ANALYTICS_DOMAINS);
      const results = await Promise.all(domains.map((d) => analyticsPlatformService.getAnalyticsAiInsight(d)));
      const allInsights = domains
        .map((d, i) => ({ domain: d, insight: results[i].payload }))
        .filter((row) => row.insight);
      this.setState({ allInsights, loading: false, dataSource: results[0] && results[0].source });
    } catch (e) {
      this.setState({ loading: false, loadError: "Unable to load insights." });
    }
  };

  render() {
    if (!isAnalyticsPlatformEnabled() || !isAnalyticsAiInsightsEnabled()) {
      return (
        <PersonaAccessDenied
          moduleName="Analytics AI insights"
          reason="Analytics platform or AI insights are not enabled for your organization."
        />
      );
    }

    const { loading, loadError, domain, insight, dataSource, allInsights } = this.state;

    return (
      <div data-testid="page-analytics-ai-insights">
        <AnalyticsLuxPage
          shellTitle="AI insights"
          pageId="analytics-ai-insights"
          dataSource={dataSource}
          loading={loading}
          pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
          heroActions={
            <>
              <AnalyticsActionButton icon="fe fe-layers" onClick={this.loadAllDomains} disabled={loading}>
                Load all domains
              </AnalyticsActionButton>
              <AnalyticsActionButton icon="fe fe-refresh-cw" onClick={() => this.loadInsights(domain)} disabled={loading}>
                Refresh
              </AnalyticsActionButton>
            </>
          }
        >
          <div className="lux-admin-toolbar mb-3">
            <select className="form-control" value={domain} onChange={(e) => this.loadInsights(e.target.value)}>
              {Object.entries(DOMAIN_LABELS).map(([key, label]) => (
                <option key={key} value={key}>{label}</option>
              ))}
            </select>
          </div>

          {loadError && <p className="lux-ai-intel-error">{loadError}</p>}

          {!loading && !insight && !allInsights.length ? (
            <LuxRegisterEmptyState title="No insight" message="Select a domain or enable analytics AI insights." />
          ) : null}

          {insight && !allInsights.length ? <AnalyticsAiInsightPanel insight={insight} /> : null}

          {allInsights.length > 0 && (
            <AnalyticsLuxPanel title="Cross-domain insight cards" subtitle="Derived read-model with source references">
              {allInsights.map(({ domain: d, insight: row }) => (
                <div key={d} className="mb-4">
                  <h4>{DOMAIN_LABELS[d] || d}</h4>
                  <AnalyticsAiInsightPanel insight={row} />
                </div>
              ))}
            </AnalyticsLuxPanel>
          )}
        </AnalyticsLuxPage>
      </div>
    );
  }
}

export default AnalyticsAiInsightsPage;
